from AS_INGREDIENTS ai, MAGASIN2 m;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AS_INGREDIENT_MACHINE" ("ID", "IDINGREDIENT", "IDENTITE", "REFERENCEOBJET", "MARQUEOBJET", "MODELEOBJET", "NUMEROSERIEOBJET", "DESCRIPTIONOBJET", "QUALITEOBJET", "ETATOBJET", "LOCALISATIONOBJET", "PUISSANCEOBJET", "OBSERVATIONOBJET", "TYPERATTACHEMENT", "ESTENGIN", "LIBELLE", "DATEAQUISITION", "INGREDIENTLIB", "IDENTITELIB", "QUALITEOBJETLIB", "ETATOBJETLIB", "LOCALISATIONOBJETLIB", "ESTENGINLIB", "IDLIGNE", "IDLIGNELIB", "PU", "IDINSPECTION") AS
(
  SELECT
	  asm.ID,
	  asm.IDINGREDIENT,
	  asm.IDENTITE,
	  asm.REFERENCEOBJET,
	  asm.MARQUEOBJET,
	  asm.MODELEOBJET,
	  asm.NUMEROSERIEOBJET,
	  asm.DESCRIPTIONOBJET,
	  asm.QUALITEOBJET,
	  asm.ETATOBJET,
	  asm.LOCALISATIONOBJET,
	  asm.PUISSANCEOBJET,
	  asm.OBSERVATIONOBJET,
	  asm.TYPERATTACHEMENT,
	  asm.ESTENGIN,
	  asm.LIBELLE,
	  asm.DATEAQUISITION,
	  asm.INGREDIENTLIB,
	  asm.IDENTITELIB,
	  asm.QUALITEOBJETLIB,
	  asm.ETATOBJETLIB,
	  asm.LOCALISATIONOBJETLIB,
	  asm.ESTENGINLIB,
	  asm.IDLIGNE,
	  asm.IDLIGNELIB,
	  asm.PU,
	  im.id AS idinspection
  FROM
  	As_ingredient_maintenance_lib asm
  	LEFT JOIN inspectionmere im ON im.idElement=asm.id
  WHERE
  	IDENTITE = 'ENT000001');

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AS_INGREDIENT_MAINTENANCE_LIB" ("ID", "IDINGREDIENT", "IDENTITE", "REFERENCEOBJET", "MARQUEOBJET", "MODELEOBJET", "NUMEROSERIEOBJET", "DESCRIPTIONOBJET", "QUALITEOBJET", "ETATOBJET", "LOCALISATIONOBJET", "PUISSANCEOBJET", "OBSERVATIONOBJET", "TYPERATTACHEMENT", "ESTENGIN", "LIBELLE", "DATEAQUISITION", "INGREDIENTLIB", "IDENTITELIB", "QUALITEOBJETLIB", "ETATOBJETLIB", "LOCALISATIONOBJETLIB", "ESTENGINLIB", "IDLIGNE", "IDLIGNELIB", "PU", "MOTSCLESSS", "IDDEPARTEMENT", "IDDEPARTEMENTLIB") AS
SELECT
    am.ID,
    am.IDINGREDIENT,
    am.IDENTITE,
    am.REFERENCEOBJET,
    am.MARQUEOBJET,
    am.MODELEOBJET,
    am.NUMEROSERIEOBJET,
    am.DESCRIPTIONOBJET,
    am.QUALITEOBJET,
    am.ETATOBJET,
    am.LOCALISATIONOBJET,
    am.PUISSANCEOBJET,
    am.OBSERVATIONOBJET,
    am.TYPERATTACHEMENT,
    am.ESTENGIN,
    am.LIBELLE,
    am.DATEAQUISITION,

    ai.libelle AS INGREDIENTLIB,
    am.IDENTITE AS IDENTITELIB,
    qo.VAL AS QUALITEOBJETLIB,
    eo.VAL AS ETATOBJETLIB,
    ld.val AS localisationObjetLib,

    CASE
        WHEN am.ESTENGIN = 1 THEN 'Oui'
        ELSE 'Non'
        END AS ESTENGINLIB,

    l.id AS idligne,
    l.val AS idlignelib,
    am.pu AS PU,

    (
        NVL(am.ID, '') || ' | ' ||
        NVL(ai.libelle, '') || ' | ' ||
        NVL(am.IDENTITE, '') || ' | ' ||
        NVL(qo.val, '') || ' | ' ||
        NVL(eo.val, '') || ' | ' ||
        NVL(ld.val, '') || ' | ' ||
        NVL(l.val, '') || ' | ' ||
        NVL(am.LIBELLE, '')
        ) AS MOTSCLESSS,
    ai.parfums AS iddepartement,
    de.val AS iddepartementlib

FROM AS_INGREDIENTS ai
         JOIN AS_INGREDIENT_MAINTENANCE am ON ai.ID = am.IDINGREDIENT
         LEFT JOIN QUALITESOBJETMAINTENANCE qo ON am.QUALITEOBJET = qo.ID
         LEFT JOIN ETATOBJETMAINTENANCE eo ON am.ETATOBJET = eo.ID
         LEFT JOIN LOG_DEPARTEMENT ld ON am.LOCALISATIONOBJET = ld.ID
         LEFT JOIN LIGNE l ON l.ID = am.IDLIGNE
         LEFT JOIN departement de ON de.id=ai.parfums;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AS_INGREDIENT_PIECE" ("ID", "IDINGREDIENT", "IDENTITE", "REFERENCEOBJET", "MARQUEOBJET", "MODELEOBJET", "NUMEROSERIEOBJET", "DESCRIPTIONOBJET", "QUALITEOBJET", "ETATOBJET", "LOCALISATIONOBJET", "PUISSANCEOBJET", "OBSERVATIONOBJET", "TYPERATTACHEMENT", "ESTENGIN", "LIBELLE", "DATEAQUISITION", "INGREDIENTLIB", "IDENTITELIB", "QUALITEOBJETLIB", "ETATOBJETLIB", "LOCALISATIONOBJETLIB", "ESTENGINLIB", "IDLIGNE", "IDLIGNELIB", "PU") AS
SELECT "ID","IDINGREDIENT","IDENTITE","REFERENCEOBJET","MARQUEOBJET","MODELEOBJET","NUMEROSERIEOBJET","DESCRIPTIONOBJET","QUALITEOBJET","ETATOBJET","LOCALISATIONOBJET","PUISSANCEOBJET","OBSERVATIONOBJET","TYPERATTACHEMENT","ESTENGIN","LIBELLE","DATEAQUISITION","INGREDIENTLIB","IDENTITELIB","QUALITEOBJETLIB","ETATOBJETLIB","LOCALISATIONOBJETLIB","ESTENGINLIB","IDLIGNE","IDLIGNELIB","PU" FROM As_ingredient_maintenance_lib WHERE IDENTITE = 'ENT000004';

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AS_INGREDIENT_VENTE_LIB" ("ID", "LIBELLE", "SEUIL", "UNITE", "QUANTITEPARPACK", "PU", "ACTIF", "PHOTO", "CALORIE", "DURRE", "COMPOSE", "CATEGORIEINGREDIENT", "IDFOURNISSEUR", "DATY", "QTELIMITE", "PV", "LIBELLEVENTE", "SEUILMIN", "SEUILMAX", "PUACHATUSD", "PUACHATEURO", "PUACHATAUTREDEVISE", "PUVENTEUSD", "PUVENTEEURO", "PUVENTEAUTREDEVISE", "ISVENTE", "ISACHAT", "COMPTE_VENTE", "COMPTE_ACHAT", "LIBELLEEXTACTE", "TVA", "FILEPATH", "RESTE", "TYPESTOCK", "REFPOST", "REFQUALIFICATION", "IDCHAMBRE", "ISPERISHABLE", "PV2", "IDMAGASIN", "PRIXUNITAIRE", "IDTYPECLIENT", "IDTYPECLIENTLIB", "IDUNITE", "IDUNITELIB", "POIDS", "QUANTITE", "TARIFMAGASIN", "UNITE2") AS
select ing.ID,
	       --concat(concat(ing.LIBELLE, ' '), ing.PARFUMS) as LIBELLE,
  	   nvl(ing.LIBELLEVENTE, ing.libelle) as LIBELLE,
       CAST(ing.SEUIL AS NUMBER(10,5)) AS  SEUIL,
       ing.UNITE,
       CAST(ing.QUANTITEPARPACK AS NUMBER(10,5)) AS QUANTITEPARPACK ,
       CAST(ing.PU AS NUMBER(30,5)) AS PU,
       ing.ACTIF,
       ing.PHOTO,
       ing.CALORIE,
       ing.DURRE,
       ing.COMPOSE,
       ing.CATEGORIEINGREDIENT,
       ing.IDFOURNISSEUR,
       ing.DATY,
       CAST(ing.QTELIMITE AS NUMBER(30,5)) AS QTELIMITE,
       CAST(ing.PV AS NUMBER(30,5)) AS PV,
       ing.LIBELLEVENTE,
       CAST(COALESCE(ing.SEUILMIN,0) AS NUMBER(30,5)) AS SEUILMIN,
       CAST(COALESCE(ing.SEUILMAX,0) AS NUMBER(30,5)) AS SEUILMAX,
       CAST(COALESCE(ing.PUACHATUSD,0) AS NUMBER(30,5)) AS PUACHATUSD,
       CAST(COALESCE(ing.PUACHATEURO,0) AS NUMBER(30,5)) AS PUACHATEURO,
       CAST(COALESCE(ing.PUACHATAUTREDEVISE,0) AS NUMBER(30,5)) AS PUACHATAUTREDEVISE,
       CAST(COALESCE(ing.PUVENTEUSD,0) AS NUMBER(30,5)) AS PUVENTEUSD,
       CAST(COALESCE(ing.PUVENTEEURO,0) AS NUMBER(30,5)) AS PUVENTEEURO,
       CAST(COALESCE(ing.PUVENTEAUTREDEVISE,0) AS NUMBER(30,5)) AS PUVENTEAUTREDEVISE,
       ing.ISVENTE,
       ing.ISACHAT,
       ing.COMPTE_VENTE,
       ing.COMPTE_ACHAT,
       ing.LIBELLEEXTACTE,
       CAST(ing.TVA AS NUMBER(10,5)) AS TVA,
       ing.FILEPATH,
       CAST(ing.RESTE AS NUMBER(20,5)) AS RESTE,
       ing.TYPESTOCK,
       ing.REFPOST,
       ing.REFQUALIFICATION,
       ing.IDCHAMBRE,
       ing.ISPERISHABLE,
       ing.PV2,
       ing.IDMAGASIN,
       CAST(nvl(ting.PRIXUNITAIRE,ing.PV)  AS NUMBER(30,5)) AS PRIXUNITAIRE,
       tc.ID as IDTYPECLIENT,
       tc.VAL as idtypeclientlib,
       nvl(un.id,un2.id) as idunite,
       nvl(un.VAL,un2.val) as idunitelib,
       CAST(eq.POIDS  AS NUMBER(30,5)) AS POIDS,
       CAST(eq.QUANTITE AS NUMBER(20,5)) AS QUANTITE,
       ting.IDMAGASIN as TARIFMAGASIN,
       nvl(un.VAL,un2.val) as UNITE2
from AS_INGREDIENTS ing
         cross join TYPECLIENT tc
         left join TARIF_INGREDIENTS_MAX ting on ing.ID = TING.IDINGREDIENT AND ting.IDTYPECLIENT=tc.id
         left join AS_UNITE un on un.ID = TING.UNITE
         left join AS_UNITE un2 on un2.ID = ing.UNITE
         left join EQUIVALENCEVENTE eq on eq.IDPRODUIT2 = ting.IDINGREDIENT
WHERE ing.ISVENTE = 1 AND ing.ACTIF=1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AS_MACHINE" ("ID", "LIBELLE", "PARFUMS", "SEUIL", "UNITE", "QUANTITEPARPACK", "PU", "ACTIF", "PHOTO", "CALORIE", "DURRE", "COMPOSE", "COMPOSELIB", "IDCATEGORIEINGREDIENT", "CATEGORIEINGREDIENT", "IDCATEGORIE", "IDFOURNISSEUR", "DATY", "BIENOUSERV", "ETATLIB", "COMPTE_VENTE", "COMPTE_ACHAT", "PV", "TVA", "TYPESTOCK", "IDUNITE", "REFPOST", "REFQUALIFICATION", "REFPOSTLIB", "REFQUALIFICATIONLIB", "IDFAMILLELIB") AS
SELECT "ID","LIBELLE","PARFUMS","SEUIL","UNITE","QUANTITEPARPACK","PU","ACTIF","PHOTO","CALORIE","DURRE","COMPOSE","COMPOSELIB","IDCATEGORIEINGREDIENT","CATEGORIEINGREDIENT","IDCATEGORIE","IDFOURNISSEUR","DATY","BIENOUSERV","ETATLIB","COMPTE_VENTE","COMPTE_ACHAT","PV","TVA","TYPESTOCK","IDUNITE","REFPOST","REFQUALIFICATION","REFPOSTLIB","REFQUALIFICATIONLIB","IDFAMILLELIB" FROM AS_INGREDIENTS_LIB ai WHERE ai.IDCATEGORIEINGREDIENT = 'CAT005';

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AS_PRODUITS" ("ID", "LIBELLE", "SEUIL", "UNITE", "QUANTITEPARPACK", "PU", "ACTIF", "PHOTO", "CALORIE", "DURRE", "COMPOSE", "CATEGORIEINGREDIENT", "IDFOURNISSEUR", "DATY", "QTELIMITE", "PV", "LIBELLEVENTE", "SEUILMIN", "SEUILMAX", "PUACHATUSD", "PUACHATEURO", "PUACHATAUTREDEVISE", "PUVENTEUSD", "PUVENTEEURO", "PUVENTEAUTREDEVISE", "ISVENTE", "ISACHAT", "COMPTE_VENTE", "COMPTE_ACHAT") AS
select "ID","LIBELLE","SEUIL","UNITE","QUANTITEPARPACK","PU","ACTIF","PHOTO","CALORIE","DURRE","COMPOSE","CATEGORIEINGREDIENT","IDFOURNISSEUR","DATY","QTELIMITE","PV","LIBELLEVENTE","SEUILMIN","SEUILMAX","PUACHATUSD","PUACHATEURO","PUACHATAUTREDEVISE","PUVENTEUSD","PUVENTEEURO","PUVENTEAUTREDEVISE","ISVENTE","ISACHAT","COMPTE_VENTE","COMPTE_ACHAT" from AS_INGREDIENTS where pv>0;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AS_RECETTEBC" ("ID", "IDPRODUITS", "IDINGREDIENTS", "QUANTITE", "UNITE", "COMPOSE") AS
select offi.id,offi.idbc as IDPRODUITS,offi.PRODUIT as idingredients,
cast(cast(offi.quantite as number(20,2))*cast(nvl(e.qte,1) as number(20,2)) as number(20,2)) as quantite,ing.unite,ing.compose from BONDECOMMANDE_CLIENT_FILLE offi left join equivalence e
on e.idproduit=offi.PRODUIT and e.idunite=offi.unite
left join as_ingredients ing on ing.id=offi.PRODUIT
union all
select "ID","IDPRODUITS","IDINGREDIENTS",cast (QUANTITE as number(20,2))as quantite,"UNITE","COMPOSE" from AS_RECETTECOMPOSE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AS_RECETTECOMPOSE" ("ID", "IDPRODUITS", "IDINGREDIENTS", "QUANTITE", "UNITE", "COMPOSE", "TYPESTOCK", "CATEGORIEINGREDIENT") AS
select r.ID,
       r.IDPRODUITS,
       r.IDINGREDIENTS,
       CAST(r.QUANTITE AS NUMBER(30,
                                 10)) AS quantite,
       nvl(r.UNITE, u.VAL) as unite,
       ing.compose,
       ing.TYPESTOCK,
       ing.CATEGORIEINGREDIENT
FROM
    as_recette r,
    as_ingredients ing,
    as_unite u
WHERE
    r.IDINGREDIENTS = ing.id(+)
  and ing.UNITE=u.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AS_RECETTEFAB" ("ID", "IDPRODUITS", "IDINGREDIENTS", "QUANTITE", "VAL", "COMPOSE") AS
select offi.id,offi.idMere as IDPRODUITS,offi.idingredients,
cast(offi.qte*nvl(e.qte,1) as number(30,10))as quantite,u.val,ing.compose from FabricationFille offi left join equivalence e
on e.idproduit=offi.idingredients and e.idunite=offi.idunite
left join as_ingredients ing on ing.id=offi.idingredients
left join as_unite u on ing.UNITE=u.id
union all
select "ID","IDPRODUITS","IDINGREDIENTS",cast (QUANTITE as number(30,10))as quantite,"UNITE","COMPOSE" from AS_RECETTECOMPOSE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AS_RECETTEFABLIB" ("ID", "IDINGREDIENTS", "UNITE", "QTEAV", "QUANTITE", "IDPRODUITS", "LIBINGREDIENTS", "TYPESTOCK", "CATEGORIEINGREDIENT", "PU", "CATEGORIEINGREDIENTLIB") AS
select 
	arf.ID,
	arf.IDINGREDIENTS,
	arf.UNITE,
	arf.QTEAV,
	arf.QUANTITE,
	arf.IDPRODUITS,
	i.LIBELLE ||' ('||u.VAL||')' as libIngredients,
	i.TYPESTOCK,
	i.CATEGORIEINGREDIENT,
	i.pu,
	cat.val AS CATEGORIEINGREDIENTLIB
from as_recettefabrication arf
left join AS_INGREDIENTS i 
on arf.idingredients=i.id
LEFT JOIN CATEGORIEINGREDIENT cat 
ON cat.id=i.CATEGORIEINGREDIENT  
left join AS_UNITE u on i.UNITE=u.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AS_RECETTEFABLIBSERVICE" ("ID", "IDINGREDIENTS", "UNITE", "QTEAV", "QUANTITE", "IDPRODUITS", "LIBINGREDIENTS", "TYPESTOCK", "CATEGORIEINGREDIENT") AS
SELECT ID,IDINGREDIENTS,UNITE,QTEAV,QUANTITE,IDPRODUITS,LIBINGREDIENTS,TYPESTOCK,categorieingredient FROM As_recetteFabLib WHERE TYPESTOCK IS NULL AND UNITE = 'UNT003' AND CATEGORIEINGREDIENT!='CAT002';

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AS_RECETTEFABLIBST" ("ID", "IDINGREDIENTS", "UNITE", "QTEAV", "QUANTITE", "IDPRODUITS", "LIBINGREDIENTS", "TYPESTOCK", "SORTIE", "RESTE") AS
select th."ID",th."IDINGREDIENTS",th."UNITE",th."QTEAV",th."QUANTITE",th."IDPRODUITS",th."LIBINGREDIENTS",th."TYPESTOCK",cast(nvl(st.sortie,0) as number(30,2)) as sortie,cast(th.QUANTITE-nvl(st.sortie,0) as number(30,2)) as reste from as_recetteFabLib th
    left join stockEtDepenseFab st on st.IDOBJET=th.IDPRODUITS and st.IDPRODUIT=th.IDINGREDIENTS;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AS_RECETTEOF" ("ID", "IDPRODUITS", "IDINGREDIENTS", "QUANTITE", "UNITE", "COMPOSE") AS
SELECT
    id,
    IDPRODUITS,
    IDINGREDIENTS,
    CAST(quantite AS NUMBER(30,10)) AS quantite,
    unite,
    compose
FROM (
    SELECT
        offi.id,
        offi.idMere AS IDPRODUITS,
        offi.idingredients AS IDINGREDIENTS,
        CAST(offi.qte AS NUMBER(30,10)) * CAST(NVL(e.qte, 1) AS NUMBER(30,10)) AS quantite,
        ing.unite,
        ing.compose
    FROM
        OFFille offi
    LEFT JOIN equivalence e ON
        e.idproduit = offi.idingredients
        AND e.idunite = offi.idunite
    LEFT JOIN as_ingredients ing ON
        ing.id = offi.idingredients
    
    UNION ALL
    
    SELECT
        ID,
        IDPRODUITS,
        IDINGREDIENTS,
        QUANTITE,
        UNITE,
        COMPOSE
    FROM
        AS_RECETTECOMPOSE
);

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AS_RECETTEOFABRICATION" ("ID", "IDPRODUITS", "IDINGREDIENTS", "QUANTITE", "UNITE", "COMPOSE") AS
select offi.id,fab.ID as IDPRODUITS,offi.IDINGREDIENTS as idingredients,
cast(cast(offi.QTE as number(20,2))*cast(nvl(e.qte,1) as number(20,2)) as number(20,2)) as quantite,ing.unite,ing.compose from OFFILLE offi left join equivalence e
on e.idproduit=offi.IDINGREDIENTS and e.idunite=offi.IDUNITE
left join as_ingredients ing on ing.id=offi.IDINGREDIENTS
left join OFAB fab on offi.IDMERE=fab.ID
union all
select ID,IDPRODUITS,IDINGREDIENTS,cast (QUANTITE as number(20,2))as quantite,UNITE,COMPOSE from AS_RECETTECOMPOSE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AS_RECETTEOFF" ("ID", "IDPRODUITS", "IDINGREDIENTS", "QUANTITE", "UNITE", "COMPOSE") AS
select offi.id,offi.ID as IDPRODUITS,offi.IDINGREDIENTS as idingredients,
cast(cast(offi.QTE as number(30,10))*cast(nvl(e.qte,1) as number(30,10)) as number(30,10)) as quantite,ing.unite,ing.compose from OFFILLE offi left join equivalence e
on e.idproduit=offi.IDINGREDIENTS and e.idunite=offi.IDUNITE
left join as_ingredients ing on ing.id=offi.IDINGREDIENTS
union all
select ID,IDPRODUITS,IDINGREDIENTS,cast (QUANTITE as number(30,10))as quantite,UNITE,COMPOSE from AS_RECETTECOMPOSE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AS_RECETTEREC" ("ID", "IDPRODUITS", "IDINGREDIENTS", "QUANTITE", "VAL", "COMPOSE") AS
select offi.id,offi.id as IDPRODUITS,offi.idingredients,
cast(offi.quantite*nvl(e.qte,1) as number(30,10))as quantite,u.val,ing.compose from as_recette offi left join equivalence e
on e.idproduit=offi.idingredients and e.idunite=offi.unite
left join as_ingredients ing on ing.id=offi.idingredients
left join as_unite u on ing.UNITE=u.id
union all
select "ID","IDPRODUITS","IDINGREDIENTS",cast (QUANTITE as number(30,10))as quantite,"UNITE","COMPOSE" from AS_RECETTECOMPOSE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AS_RECETTE_LIBCOMPLET" ("ID", "IDPRODUITS", "IDINGREDIENTS", "QUANTITE", "UNITE", "LIBELLEINGREDIENT", "LIBELLEPRODUIT", "IDUNITE", "VALUNITE", "PU") AS
select rec."ID",rec."IDPRODUITS",rec."IDINGREDIENTS",rec."QUANTITE",ing."UNITE",
ing.LIBELLE as libelleingredient,
       ing2.libelle as libelleproduit,
un.id as idunite,
un.val as valunite,
ing.pu
from as_recette rec
left join as_ingredients ing on
ing.id=rec.idingredients
left join as_ingredients ing2 on
ing2.id=rec.IDPRODUITS
left join as_unite un on
un.id=ing.unite
order by rec.id asc;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AS_RECETTE_LIB_CAT" ("ID", "IDPRODUITS", "IDINGREDIENTS", "QUANTITE", "UNITE", "LIBELLEINGREDIENT", "LIBELLEPRODUIT", "IDUNITE", "VALUNITE", "PU", "CATEGORIEINGREDIENT", "CATEGORIELIB", "COMPTE_VENTE", "COMPTE_ACHAT") AS
SELECT arl."ID",arl."IDPRODUITS",arl."IDINGREDIENTS",arl."QUANTITE",arl."UNITE",arl."LIBELLEINGREDIENT",arl."LIBELLEPRODUIT",arl."IDUNITE",arl."VALUNITE",arl."PU",c.ID AS CATEGORIEINGREDIENT , c.VAL AS categorielib, ai.COMPTE_VENTE ,ai.COMPTE_ACHAT  FROM 
	AS_RECETTE_LIBCOMPLET arl 
	JOIN AS_INGREDIENTS ai ON ai.id = arl.IDINGREDIENTS 
	JOIN CATEGORIEINGREDIENT c ON c.ID = ai.CATEGORIEINGREDIENT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AS_RECETTE_MAINTENANCE_LIB" ("ID", "IDPRODUITS", "IDINGREDIENTS", "UNITE", "QUANTITE", "IDPRODUITSLIB", "IDINGREDIENTSLIB", "IDINGREDIENTSMAINTENANCE", "UNITELIB") AS
select
             ar."ID",ar."IDPRODUITS",ar."IDINGREDIENTS",ar."UNITE",ar."QUANTITE" ,
             ai2.LIBELLE AS idProduitslib,
             ai.LIBELLE  AS idIngredientsLib,
             aim.id AS idIngredientsMaintenance,
             au.val AS uniteLib
         FROM AS_recette ar
                  LEFT JOIN As_ingredients ai ON ai.id = ar.IDINGREDIENTS
                  LEFT JOIN As_ingredients ai2 ON ai2.id = ar.IDPRODUITS
                  LEFT JOIN AS_UNITE au ON ai.unite = au.id
                  JOIN AS_INGREDIENT_MAINTENANCE aim ON aim.IDINGREDIENT  = ai2.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AS_RECFABLIBGROUPE" ("IDPRODUITS", "IDINGREDIENTS", "UNITE", "QUANTITE", "QTEAV", "PU", "LIBINGREDIENTS", "CATEGORIEINGREDIENT") AS
select a.IDPRODUITS,a.idingredients,max(a.unite) as unite,sum(quantite) as quantite, avg(a.qteav) as qteav,avg(a.pu) AS pu, a.libIngredients,a.categorieingredient
from as_recetteFabLib a group by a.IDPRODUITS, a.idingredients, a.libIngredients,a.categorieingredient;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AS_RECFOFABLIBGROUPE" ("IDPRODUITS", "IDINGREDIENTS", "UNITE", "QUANTITE", "QTEAV", "PU", "LIBINGREDIENTS", "CATEGORIEINGREDIENT", "CATEGORIEINGREDIENTLIB") AS
select 
	fille.IDMERE as IDPRODUITS,
	a.idingredients,
	max(a.unite) as unite,
	sum(quantite) as quantite,
	avg(a.qteav) as qteav,
	CAST(avg(a.pu) AS NUMBER(30,2)) AS pu,
	a.libIngredients,
	a.CATEGORIEINGREDIENT,
	a.CATEGORIEINGREDIENTLIB
from as_recetteFabLib a 
left join fabrication fab on a.IDPRODUITS=fab.ID
left join OFFILLE fille on fab.IDOFFILLE=fille.id
group by fille.idMere, a.idingredients, a.libIngredients, a.CATEGORIEINGREDIENT, a.CATEGORIEINGREDIENTLIB;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AS_RECOFFVUE" ("ID", "IDINGREDIENTS", "UNITE", "QTEAV", "QUANTITE", "IDPRODUITS", "IDUNITE", "COMPOSE", "NIVEAU", "LIBINGREDIENTS", "RESTESTOCK", "TYPESTOCK") AS
SELECT
    ar.ID,ar.IDINGREDIENTS,ar.UNITE,ar.QTEAV,ar.QUANTITE,ar.IDPRODUITS,ar.IDUNITE,ar.COMPOSE,ar.NIVEAU,
    ai.LIBELLE AS libIngredients,cast(0 as number(30,10)) as resteStock,ai.TYPESTOCK
FROM AS_RECETTEOFFFABTABLE ar
         LEFT JOIN AS_INGREDIENTS ai ON ai.id = ar.IDINGREDIENTS;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AS_RECOFFVUERESTEST" ("ID", "IDINGREDIENTS", "UNITE", "QTEAV", "QUANTITE", "IDPRODUITS", "IDUNITE", "COMPOSE", "NIVEAU", "LIBINGREDIENTS", "RESTESTOCK", "RAF", "TYPESTOCK") AS
SELECT 
a.ID,a.IDINGREDIENTS,a.UNITE,a.QTEAV,a.QUANTITE,a.IDPRODUITS,a.IDUNITE,a.COMPOSE,a.NIVEAU,a.LIBINGREDIENTS,
a.resteStock,
CAST( nvl(a.QUANTITE,0) - nvl(a.RESTESTOCK,0) AS NUMBER(30,10))  AS raf,a.TYPESTOCK
FROM as_recOffVue a;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AS_RECOFFVUESTFAB" ("ID", "IDINGREDIENTS", "UNITE", "QTEAV", "QUANTITE", "IDPRODUITS", "IDUNITE", "COMPOSE", "NIVEAU", "LIBINGREDIENTS", "RESTESTOCK", "RAF", "FABENCOURS", "TYPESTOCK") AS
SELECT
    a."ID",
    a."IDINGREDIENTS",
    a."UNITE",
    a."QTEAV",
    a."QUANTITE",
    a."IDPRODUITS",
    a."IDUNITE",
    a."COMPOSE",
    a."NIVEAU",
    a."LIBINGREDIENTS",
    a."RESTESTOCK",
    CAST(a.RAF AS NUMBER(30,10)) AS RAF,
    NVL(f.FabEncours,0) AS FabEncours,
    a.TYPESTOCK
  FROM as_recOffVueResteSt a
  LEFT JOIN FabricationEncours f
    ON f.IDINGREDIENTS = a.IDINGREDIENTS;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AS_UNITE_ACTIF" ("ID", "VAL", "DESCE", "ACTIF") AS
select "ID","VAL","DESCE","ACTIF" from AS_UNITE where ACTIF=1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."ATTRIBUTIONELEMENTLIB" ("ID", "IDINGREDIENTMAINTENANCE", "IDPERSONNEL", "DATY", "ETATELEMENT", "TYPEATTRIBUTION", "IDINGREDIENTMAINTENANCELIB", "IDPERSONNELLIB", "QUALITEOBJETMAINTENANCELIB", "TYPEATTRIBUTIONLIB", "QTE", "ETAT", "ETATLIB", "MOTSCLESSS") AS
select
	    attr.ID,attr.IDINGREDIENTMAINTENANCE,attr.IDPERSONNEL,attr.DATY,attr.ETATELEMENT,attr.TYPEATTRIBUTION,
	    asing.LIBELLE as IDINGREDIENTMAINTENANCELIB,
	    pers.NOM as idPersonnelLib,
	    qom.VAL as qualiteObjetMaintenanceLib,
	    case
	        when attr.TYPEATTRIBUTION = 0 then 'Sortie'
	        when attr.TYPEATTRIBUTION = 1 then 'Retour'
	        else 'Inconnu'
	        end as typeAttributionLib,
	    attr.qte AS qte,
	    attr.etat,
	    case
	        when attr.etat = 1 then 'Creee'
	        when attr.etat = 11 then 'Visee'
	        when attr.etat = 0 then 'Annulee'
	        end as etatLib,
	    attr.id || asing.libelle || pers.nom || qom.val AS motsclesss
	from
	    ATTRIBUTIONELEMENT attr
	        left join AS_INGREDIENT_MAINTENANCE ingm on attr.IDINGREDIENTMAINTENANCE = ingm.ID
	        left join AS_INGREDIENTS asing on ingm.IDINGREDIENT = asing.ID
	        left join PERSONNEL pers on attr.IDPERSONNEL = pers.ID
	        left join QUALITESOBJETMAINTENANCE qom on attr.ETATELEMENT = qom.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AUTOLIB" ("ID", "IDINGREDIENT", "DESCRIPTION", "NUMERODEPARC", "DATEPREMIEREMISEENCIRCULATION", "IMMATRICULATION", "NOTE", "FOURNISSEUR", "NUMERO", "VOLUME", "MONTANT", "TYPE", "VIN", "MARQUE", "MODELE", "ANNEE", "NOMBREDEPLACES", "NOMBREDEPORTES", "PUISSANCEFISCALE", "BAILLEUR", "VALEURINITIALE", "DATEDEBUT", "DURREEENMOIS", "MENSUALITE", "VENDEUR", "PRIX", "DATEDACHAT", "NUMERODIMMOBILISATION", "DUREEDAMORTISSEMENTENMOIS", "PNEUS", "BATTERIE", "HUILEMOTEUR", "HUILEBOITEDEVITESSE", "TYPEDECARBURANT", "CONSOMMATION", "UNITEDECONSOMMATION", "TYPECARBURANTLIB", "UNITEDECONSOMMATIONLIB") AS
select ia."ID",ia."IDINGREDIENT",ia."DESCRIPTION",ia."NUMERODEPARC",ia."DATEPREMIEREMISEENCIRCULATION",ia."IMMATRICULATION",ia."NOTE",ia."FOURNISSEUR",ia."NUMERO",ia."VOLUME",ia."MONTANT",ia."TYPE",ia."VIN",ia."MARQUE",ia."MODELE",ia."ANNEE",ia."NOMBREDEPLACES",ia."NOMBREDEPORTES",ia."PUISSANCEFISCALE",ia."BAILLEUR",ia."VALEURINITIALE",ia."DATEDEBUT",ia."DURREEENMOIS",ia."MENSUALITE",ia."VENDEUR",ia."PRIX",ia."DATEDACHAT",ia."NUMERODIMMOBILISATION",ia."DUREEDAMORTISSEMENTENMOIS",ia."PNEUS",ia."BATTERIE",ia."HUILEMOTEUR",ia."HUILEBOITEDEVITESSE",ia."TYPEDECARBURANT",ia."CONSOMMATION",ia."UNITEDECONSOMMATION", tc.val as typecarburantlib, uc.val as UNITEDECONSOMMATIONLIB from INFOSAUTO ia
                                                                                   left join Typecarburant tc on ia.TYPEDECARBURANT = tc.id
                                                                                   left join uniteconso uc on ia.UNITEDECONSOMMATION = uc.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AUTOMAINTENANCE" ("ID", "VAL", "DESCE") AS
select
    im.ID,
    ai.LIBELLE as val,
    ' ' as desce
from AS_INGREDIENT_MAINTENANCE im
         left join AS_INGREDIENTS ai on im.IDINGREDIENT = ai.ID
where im.IDENTITE = 'ENT000003';

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AUTOMATIQUEFORM" ("ID", "IDCAISSEBANQUE", "DATEMIN", "DATEMAX") AS
select
    '' as id,
    '' as idCaisseBanque,
    null as dateMin,
    null as dateMax
from dual;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AVANCE_LIB" ("ID", "IDPERSONNEL", "MONTANT", "NBREMBOURSEMENT", "REMARQUE", "DATY", "DATEAVANCE", "INTERET", "ETAT", "IDTYPEAVANCE", "MATRICULE", "DATEDEBUTREMBOURSEMENT") AS
SELECT av.id,
       (log.nom || ' ') || log.prenom AS idpersonnel,
       av.montant,
       av.nbremboursement,
       av.remarque,
       av.daty,
       av.dateavance,
       av.interet,
       av.etat,
       ty.val AS idtypeavance,
       p.matricule,
       av.DATEDEBUTREMBOURSEMENT
FROM avance av
         LEFT JOIN log_personnel log ON av.idpersonnel = log.id
         LEFT JOIN paie_info_personnel p ON p.id = log.id
         LEFT JOIN typeavance ty ON ty.id = av.idtypeavance;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AVANCE_LIB2" ("ID", "IDPERSONNEL", "MONTANT", "NBREMBOURSEMENT", "REMARQUE", "DATY", "DATEAVANCE", "INTERET", "ETAT", "DATEDEBLOCAGE", "DATEDEBUTREMBOURSEMENT", "ETATLIB", "IDTYPEAVANCE", "IDTYPEAVANCELIB", "MATRICULE", "MOISLIB", "MOIS", "DATESAISIE") AS
SELECT av.id,
       (log.nom || ' ') || log.prenom AS idpersonnel,
       av.montant,
       av.nbremboursement,
       av.remarque,
       av.daty,
       av.dateavance,
       av.interet,
       av.etat,
       av.DATEDEBLOCAGE,
       av.DATEDEBUTREMBOURSEMENT,
       CASE
           WHEN av.etat = 1  THEN '<span style= color:blue; >creee</span>'
           WHEN av.etat = 11 THEN '<span style= color:blue; >validee et impayee</span>'
           WHEN av.etat = 21 THEN '<span style= color:blue; >validee et payee </span>'
           ELSE NULL
           END AS etatlib,
       av.idtypeavance,
       ty.val AS idtypeavancelib,
       p.matricule,
       TO_CHAR(
               TO_DATE(TO_CHAR(av.mois, 'FM00'), 'MM'),
               'FMMonth',
               'NLS_DATE_LANGUAGE=FRENCH'
       ) AS moisLib,
       av.MOIS,
       av.dateSaisie
FROM avance av
         LEFT JOIN log_personnel log ON av.idpersonnel = log.id
         LEFT JOIN paie_info_personnel p ON p.id = log.id
         LEFT JOIN typeavance ty ON ty.id = av.idtypeavance
 ORDER BY TO_NUMBER(REGEXP_REPLACE(matricule, '[^0-9]', ''));

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AVANCE_LIB_CREE" ("ID", "IDPERSONNEL", "MONTANT", "NBREMBOURSEMENT", "REMARQUE", "DATY", "DATEAVANCE", "INTERET", "ETAT", "ETATLIB", "IDTYPEAVANCE", "IDTYPEAVANCELIB", "MATRICULE") AS
select "ID","IDPERSONNEL","MONTANT","NBREMBOURSEMENT","REMARQUE","DATY","DATEAVANCE","INTERET","ETAT","ETATLIB","IDTYPEAVANCE","IDTYPEAVANCELIB","MATRICULE" from AVANCE_LIB2 where etat = 1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AVANCE_LIB_PAYE" ("ID", "IDPERSONNEL", "MONTANT", "NBREMBOURSEMENT", "REMARQUE", "DATY", "DATEAVANCE", "INTERET", "ETAT", "ETATLIB", "IDTYPEAVANCE", "IDTYPEAVANCELIB", "MATRICULE") AS
select "ID","IDPERSONNEL","MONTANT","NBREMBOURSEMENT","REMARQUE","DATY","DATEAVANCE","INTERET","ETAT","ETATLIB","IDTYPEAVANCE","IDTYPEAVANCELIB","MATRICULE" from AVANCE_LIB2 where etat = 21;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AVANCE_LIB_VISEE" ("ID", "IDPERSONNEL", "MONTANT", "NBREMBOURSEMENT", "REMARQUE", "DATY", "DATEAVANCE", "INTERET", "ETAT", "ETATLIB", "IDTYPEAVANCE", "IDTYPEAVANCELIB", "MATRICULE") AS
select "ID","IDPERSONNEL","MONTANT","NBREMBOURSEMENT","REMARQUE","DATY","DATEAVANCE","INTERET","ETAT","ETATLIB","IDTYPEAVANCE","IDTYPEAVANCELIB","MATRICULE" from AVANCE_LIB2 where etat = 11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AVOIRACHATCALC" ("ID", "DESIGNATION", "IDMAGASIN", "DATY", "REMARQUE", "ETAT", "IDFOURNISSEUR", "IDFACTURE", "REMISE", "MONTANTREMISE", "MONTANTNONREMISE", "MONTANTHT", "MONTANTTVA", "MONTANTTTC", "MONTANTTTCAR") AS
select v."ID",v."DESIGNATION",v."IDMAGASIN",v."DATY",v."REMARQUE",v."ETAT",v."IDFOURNISSEUR",v."IDFACTURE",v."REMISE", cast(montantRemiseSansTva+ (montantHT* (nvl(v.REMISE,0)/100)) as number(30,2)) as montantRemise, montantNonRemise,
       cast(montantHT*(1-(nvl(v.REMISE,0)/100)) as number(30,2)) as montantHT,cast(montantTva*(1-(nvl(v.REMISE,0)/100)) as number(30,2)) as montantTva,
       cast(montantTTC*(1-(nvl(v.REMISE,0)/100)) as number(30,2)) as montantTTC, montantTTCAr*(1-(nvl(v.REMISE,0)/100)) as montantTTCAr
from AVOIRACHAT v left join AvoirAChatFilleCalcGroupe vdcv on v.id=vdcv.idAvoirAchat;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AVOIRACHATCALCGROUPEORIGINE" ("IDFACTURE", "MONTANTNONREMISE", "MONTANTREMISESANSTVA", "MONTANTHT", "MONTANTTTC", "MONTANTTVA", "MONTANTHTAR", "MONTANTTVAAR", "MONTANTTTCAR") AS
select aa.IDFACTURE ,cast(sum(montantNonRemise) as number(30,2)) as montantNonRemise,cast(sum(montantRemiseSansTva) as number(30,2)) as montantRemiseSansTva,
       cast(sum(montantHT) as number(30,2)) as montantHT,cast(sum(montantTTC) as number(30,2)) as montantTTC,cast(sum(montantTva) as number(30,2)) as montantTva,
       cast(sum(montantHTAr) as number(30,2)) as montantHTAr,cast(sum(montantTvaAr) as number(30,2)) as montantTvaAr,cast(sum(montantTTCAr) as number(30,2)) as montantTTCAr
from AvoirAChatFilleCalc vdc left join avoirAchat aa on aa.id=vdc.IDMERE where aa.ETAT>=11   group by aa.IDFACTURE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AVOIRACHATCALC_AVEC_LIB" ("ID", "DESIGNATION", "IDMAGASIN", "DATY", "REMARQUE", "ETAT", "IDFOURNISSEUR", "IDFACTURE", "REMISE", "MONTANTREMISE", "MONTANTNONREMISE", "MONTANTHT", "MONTANTTVA", "MONTANTTTC", "MONTANTTTCAR", "ETATLIB", "IDMAGASINLIB", "IDFOURNISSEURLIB") AS
select a."ID",
       a."DESIGNATION",
       a."IDMAGASIN",
       a."DATY",
       a."REMARQUE",
       a."ETAT",
       a."IDFOURNISSEUR",
       a."IDFACTURE",
       a."REMISE",
       a."MONTANTREMISE",
       a."MONTANTNONREMISE",
       a."MONTANTHT",
       a."MONTANTTVA",
       a."MONTANTTTC",
       a."MONTANTTTCAR",
       case
           when a.etat = 1 then 'CR&Eacute;&Eacute;(E)'
           when a.etat = 11 then 'VIS&Eacute;(E)'
           when a.etat = 11 then 'ANNUL&Eacute;(E)'
           end as etatlib,
       m.VAL AS idmagasinLib,
       f.nom AS idfournisseurLib
from AVOIRACHATCALC a
         left join AvoirAChatFilleCalcGroupe vdcv on a.id = vdcv.idAvoirAchat
         LEFT JOIN MAGASIN2 m ON a.IDMAGASIN = m.ID
         LEFT JOIN FOURNISSEUR f ON a.IDFOURNISSEUR = f.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AVOIRACHATFILLECALC" ("ID", "IDMERE", "IDPRODUIT", "QTE", "PU", "REMISE", "TVA", "IDDEVISE", "TAUX", "DESIGNATION", "IDFACTUREDETAILS", "RISTOURNE", "TAUXDECHANGE", "MONTANTNONREMISE", "MONTANTREMISESANSTVA", "MONTANTHT", "PUREMISE", "MONTANTHTAR", "MONTANTTVA", "MONTANTTVAAR", "MONTANTTTC", "MONTANTTTCAR") AS
select vd."ID",vd."IDMERE",vd."IDPRODUIT",vd."QTE",vd."PU",vd."REMISE",vd."TVA",vd."IDDEVISE",vd."TAUX",vd."DESIGNATION",vd."IDFACTUREDETAILS",vd."RISTOURNE",vd."TAUXDECHANGE",cast(vd.QTE*vd.pu as number(30,2)) as montantNonRemise,
       cast(vd.QTE*vd.pu*((nvl(vd.REMISE,0)+nvl(vd.RISTOURNE,0))/100) as number(30,2)) as montantRemiseSansTva,
       cast(vd.QTE*vd.pu*(1-(nvl(vd.REMISE,0)/100))*(1-(nvl(vd.RISTOURNE,0)/100)) as number(30,2)) as montantHT,
       cast(vd.pu*(1-(nvl(vd.REMISE,0)/100))*(1-(nvl(vd.RISTOURNE,0)/100)) as number(30,2)) as puRemise,
       cast(vd.QTE*vd.pu*(1-(nvl(vd.REMISE,0)/100))*(1-(nvl(vd.RISTOURNE,0)/100))*nvl(vd.TAUXDECHANGE,1) as number(30,2)) as montantHTAr,
       cast(vd.QTE*vd.pu*(1-(nvl(vd.REMISE,0)/100))*(1-(nvl(vd.RISTOURNE,0)/100))*nvl(vd.tva,0)/100 as number(30,2)) as montantTva,
       cast(vd.QTE*vd.pu*(1-(nvl(vd.REMISE,0)/100))*(1-(nvl(vd.RISTOURNE,0)/100))*nvl(vd.TAUXDECHANGE,1)*nvl(vd.tva,0)/100 as number(30,2)) as montantTvaAr,
       cast(vd.QTE*vd.pu*(1-(nvl(vd.REMISE,0)/100))*(1-(nvl(vd.RISTOURNE,0)/100))*(1+(nvl(vd.tva,0)/100)) as number(30,2)) as montantTTC,
       cast(vd.QTE*vd.pu*(1-(nvl(vd.REMISE,0)/100))*(1-(nvl(vd.RISTOURNE,0)/100))*(1+(nvl(vd.tva,0)/100))*nvl(vd.TAUXDECHANGE,1) as number(30,2)) as montantTTCAr from AVOIRAchatFILLE vd;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AVOIRACHATFILLECALCGROUPE" ("IDAVOIRACHAT", "MONTANTNONREMISE", "MONTANTREMISESANSTVA", "MONTANTHT", "MONTANTTTC", "MONTANTTVA", "MONTANTHTAR", "MONTANTTVAAR", "MONTANTTTCAR") AS
select vdc.IDMERE as idAvoirAchat ,cast(sum(montantNonRemise) as number(30,2)) as montantNonRemise,cast(sum(montantRemiseSansTva) as number(30,2)) as montantRemiseSansTva,
       cast(sum(montantHT) as number(30,2)) as montantHT,cast(sum(montantTTC) as number(30,2)) as montantTTC,cast(sum(montantTva) as number(30,2)) as montantTva,
       cast(sum(montantHTAr) as number(30,2)) as montantHTAr,cast(sum(montantTvaAr) as number(30,2)) as montantTvaAr,cast(sum(montantTTCAr) as number(30,2)) as montantTTCAr
from AvoirAChatFilleCalc vdc group by vdc.IDMERE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AVOIRACHATFILLELIB" ("ID", "IDMERE", "IDPRODUIT", "QTE", "PU", "REMISE", "TVA", "IDDEVISE", "TAUX", "DESIGNATION", "IDFACTUREDETAILS", "IDPRODUITLIB", "IDDEVISELIB", "MONTANT", "MONTANTREMISE", "MONTANTHT", "MONTANTTVA", "MONTANTTTC") AS
SELECT
    af.ID,
    af.IDMERE,
    af.IDPRODUIT,
    af.QTE,
    af.PU,
    af.REMISE,
    af.TVA,
    af.IDDEVISE,
    af.TAUX,
    af.DESIGNATION,
    af.IDFACTUREDETAILS,
    p.LIBELLE AS idproduitLib,
    d.val AS iddeviseLib,
    ----------------------------------------------------------
    -- 1 Montant HT brut
    ----------------------------------------------------------
    CAST(af.QTE * af.PU AS NUMBER(30, 2)) AS montant,
    ----------------------------------------------------------
    -- 2 Montant remise (appliquee sur HT)
    ----------------------------------------------------------
    CAST((NVL(af.REMISE, 0) / 100) * (af.QTE * af.PU) AS NUMBER(30, 2)) AS montantRemise,
    ----------------------------------------------------------
    -- 3 Montant HT net apres remise
    ----------------------------------------------------------
    CAST((af.QTE * af.PU) - ((NVL(af.REMISE, 0) / 100) * (af.QTE * af.PU)) AS NUMBER(30, 2)) AS montantht,
    ----------------------------------------------------------
    -- 4 TVA sur montant HT net
    ----------------------------------------------------------
    CAST(((af.QTE * af.PU) - ((NVL(af.REMISE, 0) / 100) * (af.QTE * af.PU))) * af.TVA / 100 AS NUMBER(30, 2))AS montanttva,
    ----------------------------------------------------------
    -- 5 Montant TTC net (HT net + TVA)
    ----------------------------------------------------------
    CAST( ((af.QTE * af.PU) - ((NVL(af.REMISE, 0) / 100) * (af.QTE * af.PU))) + ( ((af.QTE * af.PU) - ((NVL(af.REMISE, 0) / 100) * (af.QTE * af.PU)))  * af.TVA / 100  ) AS NUMBER(30, 2)) AS montantttc
FROM AVOIRACHATFILLE af
    LEFT JOIN AS_INGREDIENTS p ON af.IDPRODUIT = p.ID
    LEFT JOIN DEVISE d ON af.IDDEVISE = d.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AVOIRACHATLIB" ("ID", "DESIGNATION", "IDMAGASIN", "DATY", "REMARQUE", "ETAT", "IDFOURNISSEUR", "IDFACTURE", "IDMAGASINLIB", "IDFOURNISSEURLIB") AS
SELECT a.ID,a.DESIGNATION,a.IDMAGASIN,a.DATY,a.REMARQUE,a.ETAT,a.IDFOURNISSEUR,a.IDFACTURE, m.VAL AS idmagasinLib, f.nom AS idfournisseurLib
FROM AVOIRACHAT a
    LEFT JOIN MAGASIN2 m ON a.IDMAGASIN = m.ID
    LEFT JOIN FOURNISSEUR f ON a.IDFOURNISSEUR = f.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AVOIRFCFILLELIB" ("ID", "IDAVOIRFC", "IDPRODUIT", "IDORIGINE", "QTE", "PU", "REMISE", "TVA", "PUACHAT", "PUVENTE", "IDDEVISE", "TAUXDECHANGE", "DESIGNATION", "IDVENTEDETAILS", "IDPRODUITLIB", "CALORIE", "POIDS", "PTHT", "MONTANTTVA") AS
SELECT
    AF.ID,
    AF.IDAVOIRFC,
    AF.IDPRODUIT,
    AF.IDORIGINE,
    AF.QTE,
    AF.PU,
    AF.REMISE,
    AF.TVA,
    AF.PUACHAT,
    AF.PUVENTE,
    AF.IDDEVISE,
    AF.TAUXDECHANGE,
    AF.DESIGNATION,
    AF.IDVENTEDETAILS,
    nvl(P.libellevente,P.LIBELLE) AS IDPRODUITLIB,
    P.CALORIE,
    P.CALORIE * AF.QTE AS POIDS,
    AF.PU * AF.QTE AS PTHT,
    (NVL(AF.pu,0) * NVL(AF.QTE,0)) * NVL(AF.TVA,0) / 100 AS montantTVA
FROM
    AVOIRFCFILLE AF
        LEFT JOIN as_ingredients P ON
        P.id = AF.IDPRODUIT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AVOIRFCFILLELIB_PDF" ("ID", "IDAVOIRFC", "IDPRODUIT", "IDORIGINE", "QTE", "PU", "REMISE", "TVA", "PUACHAT", "PUVENTE", "IDDEVISE", "TAUXDECHANGE", "DESIGNATION", "IDVENTEDETAILS", "IDPRODUITLIB", "CALORIE", "POIDS", "PTHT", "MONTANTTVA", "TAUX") AS
SELECT
    AF.ID,
    AF.IDAVOIRFC,
    AF.IDPRODUIT,
    AF.IDORIGINE,
    AF.QTE,
    AF.PU,
    AF.REMISE,
    AF.TVA,
    AF.PUACHAT,
    AF.PUVENTE,
    AF.IDDEVISE,
    AF.TAUXDECHANGE,
    AF.DESIGNATION,
    AF.IDVENTEDETAILS,
    P.LIBELLEVENTE AS IDPRODUITLIB,
    P.CALORIE,
    P.CALORIE * AF.QTE AS POIDS,
    AF.PU * AF.QTE AS PTHT,
    (NVL(AF.pu,0) * NVL(AF.QTE,0)) * NVL(AF.TVA,0) / 100 AS montantTVA,
    AF.TAUX
FROM
    AVOIRFCFILLE AF
        LEFT JOIN as_ingredients P ON
        P.id = AF.IDPRODUIT
order by P.LIBELLEVENTE asc;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AVOIRFCFILLE_GRP" ("IDAVOIRFC", "MONTANTHT", "MONTANTTVA", "MONTANTTTC", "MONTANTHTAR", "MONTANTTVAAR", "MONTANTTTCAR", "TAUXDECHANGE", "IDDEVISE") AS
SELECT a.idavoirfc,
       CAST(nvl(sum(a.QTE * a.PU), 0) AS NUMBER(30, 2))                                          AS montantht,
       CAST(nvl(sum(a.QTE * a.PU * a.TVA / 100), 0) AS NUMBER(30, 2))                            AS montanttva,
       CAST(nvl(sum((a.QTE * a.PU) + (a.QTE * a.PU * a.TVA / 100)), 0) AS NUMBER(30, 2))         AS montantttc,
       CAST(nvl(sum(a.QTE * a.PU * nvl(a.TAUXDECHANGE, 1)), 0) AS NUMBER(30, 2))                 AS montanthtAR,
       CAST(nvl(sum((a.QTE * a.PU * a.TVA / 100) * nvl(a.TAUXDECHANGE, 1)), 0) AS NUMBER(30, 2)) AS montanttvaAR,
       CAST(nvl(sum((a.QTE * a.PU * nvl(a.TAUXDECHANGE, 1)) + (a.QTE * a.PU * a.TVA / 100) * nvl(a.TAUXDECHANGE, 1)),
                0) AS NUMBER(30, 2))                                                             AS montantttcar,
       MAX(TAUXDECHANGE)                                                                         as tauxdechange,
       a.IDDEVISE
FROM AVOIRFCFILLE a
GROUP BY a.idavoirfc, a.IDDEVISE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AVOIRFCFILLE_GRP_VISEEE" ("IDVENTEDETAILS", "QTE") AS
SELECT
IDVENTEDETAILS,
SUM(qte) AS qte
FROM
AvoirFCFille abcf
left join AvoirFC b on b.id=abcf.idAvoirFC
where b.ETAT>=11
GROUP BY IDVENTEDETAILS;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AVOIRFCLIB" ("ID", "DESIGNATION", "IDMAGASIN", "IDMAGASINLIB", "DATY", "REMARQUE", "ETAT", "IDORIGINE", "IDCLIENT", "COMPTE", "COMPTEAUXILIAIRE", "IDVENTE", "IDVENTELIB", "IDMOTIF", "IDMOTIFLIB", "IDCATEGORIE", "IDCATEGORIELIB", "IDDEVISE", "TAUXDECHANGE", "MONTANTHT", "MONTANTTVA", "MONTANTTTC", "MONTANTHTAR", "MONTANTTVAAR", "MONTANTTTCAR", "IDRESERVATION", "TYPEAVOIR", "CLIENTLIB", "NUMAVOIR", "IDRISTOURNE", "MONTANTRESTE", "NUMFACT") AS
SELECT a.ID,
       a.DESIGNATION,
       a.IDMAGASIN,
       m.VAL         AS IDMAGASINLIB,
       a.DATY,
       a.REMARQUE,
       a.ETAT,
       a.IDORIGINE,
       a.IDCLIENT,
       t.COMPTE,
       t.compteauxiliaire,
       a.IDVENTE,
       v.DESIGNATION AS IDVENTELIB,
       a.IDMOTIF,
       ma.VAL        AS IDMOTIFLIB,
       a.IDCATEGORIE,
       c.VAL         AS IDCATEGORIELIB,
       ag.IDDEVISE,
       ag.TAUXDECHANGE,
       ag.MONTANTHT,
       ag.MONTANTTVA,
       ag.MONTANTTTC,
       ag.MONTANTHTAR,
       ag.MONTANTTVAAR,
       ag.MONTANTTTCAR,
       v.IDRESERVATION,
       ta.val        as Typeavoir,
       t.NOM         as clientlib,
       a.numavoir,
       a.idristourne,
       v.MONTANTRESTE,
       v.NUMFACT
FROM AVOIRFC a
         LEFT JOIN magasin2 m ON m.id = a.IDMAGASIN
         LEFT JOIN VENTE_CPL_SANSAVOIR v ON v.id = a.IDVENTE
         LEFT JOIN MOTIFAVOIRFC ma ON ma.id = a.IDMOTIF
         LEFT JOIN CATEGORIEAVOIRFC c ON c.id = a.IDCATEGORIE
         JOIN AVOIRFCFILLE_GRP ag ON ag.idavoirfc = a.id
         LEFT JOIN TIERS T ON T.ID = A.IDCLIENT
         left join TYPEAVOIR ta on ta.id = a.IDTYPEAVOIR;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AVOIRFCLIB_CPL" ("ID", "DESIGNATION", "IDMAGASIN", "IDMAGASINLIB", "DATY", "REMARQUE", "ETAT", "IDORIGINE", "IDCLIENT", "COMPTE", "IDVENTE", "IDVENTELIB", "IDMOTIF", "IDMOTIFLIB", "IDCATEGORIE", "IDCATEGORIELIB", "IDDEVISE", "TAUXDECHANGE", "MONTANTHT", "MONTANTTVA", "MONTANTTTC", "MONTANTHTAR", "MONTANTTVAAR", "MONTANTTTCAR", "MONTANTPAYE", "MONTANTPAYEAR", "MONTANT_RESTE_FACTURE", "MONTANT_AVOIRS_ANTERIEURS", "RESTE_CALCULE", "EXCEDENT_AR", "RESTEAPAYER", "RESTEAPAYERAR", "CLIENTLIB", "TYPEAVOIR", "NUMFACT", "MOTSCLESSS") AS
SELECT AL.ID,
       AL.DESIGNATION,
       AL.IDMAGASIN,
       AL.IDMAGASINLIB,
       AL.DATY,
       AL.REMARQUE,
       AL.ETAT,
       AL.IDORIGINE,
       AL.IDCLIENT,
       AL.COMPTE,
       AL.IDVENTE,
       AL.IDVENTELIB,
       AL.IDMOTIF,
       AL.IDMOTIFLIB,
       AL.IDCATEGORIE,
       AL.IDCATEGORIELIB,
       AL.IDDEVISE,
       AL.TAUXDECHANGE,
       AL.MONTANTHT,
       AL.MONTANTTVA,
       AL.MONTANTTTC,
       AL.MONTANTHTAR,
       AL.MONTANTTVAAR,
       AL.MONTANTTTCAR,
       NVL(M.MONTANT, 0)                                        AS MONTANTPAYE,
       NVL(M.MONTANT, 0) * NVL(AL.TAUXDECHANGE, 0)              AS MONTANTPAYEAR,

       NVL(VC.MONTANTRESTE, 0)                                  AS MONTANT_RESTE_FACTURE,

       NVL(SUM_PRECEDENTS.MONTANT_AVOIRS_PRECEDENTS, 0)         AS MONTANT_AVOIRS_ANTERIEURS,
       CASE
           WHEN NVL(VC.MONTANTRESTE, 0) = 0 THEN 0
           ELSE NVL(VC.MONTANTRESTE, 0) - NVL(SUM_PRECEDENTS.MONTANT_AVOIRS_PRECEDENTS, 0) - NVL(AL.MONTANTTTCAR, 0)
           END                                                  AS RESTE_CALCULE,
       CASE
           WHEN NVL(VC.MONTANTRESTE, 0) = 0 THEN NVL(AL.MONTANTTTCAR, 0)
           WHEN NVL(VC.MONTANTRESTE, 0) - NVL(SUM_PRECEDENTS.MONTANT_AVOIRS_PRECEDENTS, 0) - NVL(AL.MONTANTTTCAR, 0) < 0
               THEN ABS(NVL(VC.MONTANTRESTE, 0) - NVL(SUM_PRECEDENTS.MONTANT_AVOIRS_PRECEDENTS, 0) -
                        NVL(AL.MONTANTTTCAR, 0))
           ELSE 0
           END                                                  AS EXCEDENT_AR,
       (CASE
            WHEN NVL(VC.MONTANTRESTE, 0) = 0 THEN NVL(AL.MONTANTTTCAR, 0)
            WHEN NVL(VC.MONTANTRESTE, 0) - NVL(SUM_PRECEDENTS.MONTANT_AVOIRS_PRECEDENTS, 0) - NVL(AL.MONTANTTTCAR, 0) <
                 0
                THEN ABS(NVL(VC.MONTANTRESTE, 0) - NVL(SUM_PRECEDENTS.MONTANT_AVOIRS_PRECEDENTS, 0) -
                         NVL(AL.MONTANTTTCAR, 0))
            ELSE 0
           END) - NVL(M.MONTANT, 0)                             AS RESTEAPAYER,
       (CASE
            WHEN NVL(VC.MONTANTRESTE, 0) = 0 THEN NVL(AL.MONTANTTTCAR, 0)
            WHEN NVL(VC.MONTANTRESTE, 0) - NVL(SUM_PRECEDENTS.MONTANT_AVOIRS_PRECEDENTS, 0) - NVL(AL.MONTANTTTCAR, 0) <
                 0
                THEN ABS(NVL(VC.MONTANTRESTE, 0) - NVL(SUM_PRECEDENTS.MONTANT_AVOIRS_PRECEDENTS, 0) -
                         NVL(AL.MONTANTTTCAR, 0))
            ELSE 0
           END) - (NVL(M.MONTANT, 0) * NVL(AL.TAUXDECHANGE, 0)) AS RESTEAPAYERAR,
       AL.CLIENTLIB,
       AL.TYPEAVOIR,
       VC.NUMFACT,
       (
           NVL(TO_CHAR(AL.ID), '') || ' | ' ||
           AL.ID || ' | ' || CLIENTLIB || ' | ' ||  AL.IDMAGASINLIB || ' | ' || VC.NUMFACT || ' | ' ||
           TYPEAVOIR || ' | ' || IDMOTIFLIB || ' | ' || IDCATEGORIELIB
           )                                                    AS MOTSCLESSS
FROM AVOIRFCLIB AL
         LEFT JOIN MOUVEMENTCAISSEGRPAVOIR_LP M
                   ON AL.ID = M.IDORIGINE
         LEFT JOIN VENTE_CPL_SANSAVOIR VC
                   ON VC.ID = AL.IDVENTE
         LEFT JOIN (SELECT A2.IDVENTE,
                           A2.ID                AS IDCOURANT,
                           SUM(A1.MONTANTTTCAR) AS MONTANT_AVOIRS_PRECEDENTS
                    FROM AVOIRFCLIB A1
                             JOIN AVOIRFCLIB A2 ON A1.IDVENTE = A2.IDVENTE
                    WHERE A1.ETAT <> 0
                      AND (A1.DATY < A2.DATY OR (A1.DATY = A2.DATY AND A1.ID < A2.ID))
                    GROUP BY A2.IDVENTE, A2.ID) SUM_PRECEDENTS
                   ON SUM_PRECEDENTS.IDVENTE = AL.IDVENTE
                       AND SUM_PRECEDENTS.IDCOURANT = AL.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AVOIRFCLIB_CPL_CREE" ("ID", "DESIGNATION", "IDMAGASIN", "IDMAGASINLIB", "DATY", "REMARQUE", "ETAT", "IDORIGINE", "IDCLIENT", "COMPTE", "IDVENTE", "IDVENTELIB", "IDMOTIF", "IDMOTIFLIB", "IDCATEGORIE", "IDCATEGORIELIB", "IDDEVISE", "TAUXDECHANGE", "MONTANTHT", "MONTANTTVA", "MONTANTTTC", "MONTANTHTAR", "MONTANTTVAAR", "MONTANTTTCAR", "MONTANTPAYE", "MONTANTPAYEAR", "RESTEAPAYER", "RESTEAPAYERAR") AS
SELECT
	ID,
	DESIGNATION,
	IDMAGASIN,
	IDMAGASINLIB,
	DATY,
	REMARQUE,
	ETAT,
	IDORIGINE,
	IDCLIENT,
	COMPTE,
	IDVENTE,
	IDVENTELIB,
	IDMOTIF,
	IDMOTIFLIB,
	IDCATEGORIE,
	IDCATEGORIELIB,
	IDDEVISE,
	TAUXDECHANGE,
	MONTANTHT,
	MONTANTTVA,
	MONTANTTTC,
	MONTANTHTAR,
	MONTANTTVAAR,
	MONTANTTTCAR,
	MONTANTPAYE,
	MONTANTPAYEAR,
	RESTEAPAYER,
	RESTEAPAYERAR
FROM
	avoirfclib_cpl
WHERE
	ETAT != 1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AVOIRFCLIB_CPL_GRP" ("IDVENTE", "IDDEVISE", "MONTANTHT_AVR", "MONTANTTVA_AVR", "MONTANTTTC_AVR", "MONTANTHTAR_AVR", "MONTANTTVAAR_AVR", "MONTANTTTCAR_AVR", "MONTANTPAYE", "MONTANTPAYEAR", "RESTEAPAYER_AVR", "RESTEAPAYERAR_AVR", "IMPUTEEFACT", "IMPUTEEFACTAR") AS
SELECT AL.IDVENTE,
       AL.IDDEVISE,
       SUM(MONTANTHT)     as MONTANTHT_avr,
       SUM(MONTANTTVA)    as MONTANTTVA_avr,
       SUM(MONTANTTTC)    as MONTANTTTC_avr,
       SUM(MONTANTHTAR)   as MONTANTHTAR_avr,
       SUM(MONTANTTVAAR)  as MONTANTTVAAR_avr,
       SUM(MONTANTTTCAR)  as MONTANTTTCAR_avr,
       SUM(MONTANTPAYE)   as MONTANTPAYE,
       SUM(MONTANTPAYEAR) as MONTANTPAYEAR,
       SUM(RESTEAPAYER)   as resteapayer_avr,
       SUM(RESTEAPAYERAR) as resteapayerar_avr,
       SUM(imputeefact)   as imputeefact,
       SUM(imputeefactar) as imputeefactar
from avoirfclib_cpl_visee AL
group by IDVENTE, IDDEVISE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AVOIRFCLIB_CPL_NON_CREE" ("ID", "DESIGNATION", "IDMAGASIN", "IDMAGASINLIB", "DATY", "REMARQUE", "ETAT", "IDORIGINE", "IDCLIENT", "COMPTE", "IDVENTE", "IDVENTELIB", "IDMOTIF", "IDMOTIFLIB", "IDCATEGORIE", "IDCATEGORIELIB", "IDDEVISE", "TAUXDECHANGE", "MONTANTHT", "MONTANTTVA", "MONTANTTTC", "MONTANTHTAR", "MONTANTTVAAR", "MONTANTTTCAR", "MONTANTPAYE", "MONTANTPAYEAR", "RESTEAPAYER", "RESTEAPAYERAR") AS
SELECT
