CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AVOIRFCLIB_CPL_V2" ("ID", "DESIGNATION", "IDMAGASIN", "IDMAGASINLIB", "DATY", "REMARQUE", "ETAT", "IDORIGINE", "IDCLIENT", "COMPTE", "IDVENTE", "IDVENTELIB", "IDMOTIF", "IDMOTIFLIB", "IDCATEGORIE", "IDCATEGORIELIB", "IDDEVISE", "TAUXDECHANGE", "MONTANTHT", "MONTANTTVA", "MONTANTTTC", "MONTANTHTAR", "MONTANTTVAAR", "MONTANTTTCAR", "MONTANTPAYE", "MONTANTPAYEAR", "MONTANT_RESTE_FACTURE", "MONTANT_AVOIRS_ANTERIEURS", "RESTE_CALCULE", "EXCEDENT_AR", "RESTEAPAYER", "RESTEAPAYERAR", "CLIENTLIB", "TYPEAVOIR", "NUMFACT") AS
SELECT AL.ID,
       AL.DESIGNATION,
       AL.IDMAGASIN,
       AL.IDMAGASINLIB,
       AL.DATY,
       AL.REMARQUE,
       AL.ETAT,
       AL.IDORIGINE,
       AL.IDCLIENT,
       AL.COMPTE,
       AL.IDVENTE,
       AL.IDVENTELIB,
       AL.IDMOTIF,
       AL.IDMOTIFLIB,
       AL.IDCATEGORIE,
       AL.IDCATEGORIELIB,
       AL.IDDEVISE,
       AL.TAUXDECHANGE,
       AL.MONTANTHT,
       AL.MONTANTTVA,
       AL.MONTANTTTC,
       AL.MONTANTHTAR,
       AL.MONTANTTVAAR,
       AL.MONTANTTTCAR,
       nvl(M.montant, 0)                                        AS MONTANTPAYE,
       NVL(M.montant, 0) * NVL(AL.TAUXDECHANGE, 0)              AS MONTANTPAYEAR,

       NVL(AL.MONTANTRESTE, 0)                                  AS MONTANT_RESTE_FACTURE ,

       0         AS MONTANT_AVOIRS_ANTERIEURS,
       -- Cas 1 : facture deja soldee -> chaque avoir = credit direct (exedent)
       CASE
           WHEN NVL(AL.MONTANTRESTE, 0) = 0 THEN 0
           ELSE NVL(AL.MONTANTRESTE, 0)  - NVL(AL.MONTANTTTCAR, 0)
           END                                                  AS RESTE_CALCULE,
       -- Excedent a rembourser ou a reporter
       CASE
           WHEN NVL(AL.MONTANTRESTE, 0) = 0 THEN NVL(AL.MONTANTTTCAR, 0)
           WHEN NVL(AL.MONTANTRESTE, 0) - NVL(AL.MONTANTTTCAR, 0) < 0
               THEN ABS(NVL(AL.MONTANTRESTE, 0)  -
                        NVL(AL.MONTANTTTCAR, 0))
           ELSE 0
           END                                                  AS EXCEDENT_AR,
       (CASE
            WHEN NVL(AL.MONTANTRESTE, 0) = 0 THEN NVL(AL.MONTANTTTCAR, 0)
            WHEN NVL(AL.MONTANTRESTE, 0) - NVL(AL.MONTANTTTCAR, 0) <
                 0
                THEN ABS(NVL(AL.MONTANTRESTE, 0)  -
                         NVL(AL.MONTANTTTCAR, 0))
            ELSE 0
           END) - NVL(M.montant, 0)                             AS resteapayer,
       (CASE
            WHEN NVL(AL.MONTANTRESTE, 0) = 0 THEN NVL(AL.MONTANTTTCAR, 0)
            WHEN NVL(AL.MONTANTRESTE, 0)  - NVL(AL.MONTANTTTCAR, 0) <
                 0
                THEN ABS(NVL(AL.MONTANTRESTE, 0)  -
                         NVL(AL.MONTANTTTCAR, 0))
            ELSE 0
           END) - (NVL(M.montant, 0) * NVL(AL.TAUXDECHANGE, 0)) AS resteapayerar,
       AL.clientlib,
       AL.Typeavoir,
       AL.NUMFACT
FROM AVOIRFCLIB AL
         LEFT JOIN MOUVEMENTCAISSEGRPAVOIR_LP M
                   ON AL.ID = M.IDORIGINE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AVOIRFCLIB_CPL_V2_GRP" ("IDVENTE", "IDDEVISE", "MONTANTHT_AVR", "MONTANTTVA_AVR", "MONTANTTTC_AVR", "MONTANTHTAR_AVR", "MONTANTTVAAR_AVR", "MONTANTTTCAR_AVR", "MONTANTPAYE", "MONTANTPAYEAR", "RESTEAPAYER_AVR", "RESTEAPAYERAR_AVR", "IMPUTEEFACT", "IMPUTEEFACTAR") AS
SELECT AL.IDVENTE,
       AL.IDDEVISE,
       SUM(MONTANTHT)     as MONTANTHT_avr,
       SUM(MONTANTTVA)    as MONTANTTVA_avr,
       SUM(MONTANTTTC)    as MONTANTTTC_avr,
       SUM(MONTANTHTAR)   as MONTANTHTAR_avr,
       SUM(MONTANTTVAAR)  as MONTANTTVAAR_avr,
       SUM(MONTANTTTCAR)  as MONTANTTTCAR_avr,
       SUM(MONTANTPAYE)   as MONTANTPAYE,
       SUM(MONTANTPAYEAR) as MONTANTPAYEAR,
       SUM(RESTEAPAYER)   as resteapayer_avr,
       SUM(RESTEAPAYERAR) as resteapayerar_avr,
       SUM(imputeefact)   as imputeefact,
       SUM(imputeefactar) as imputeefactar
from AVOIRFCLIB_CPL_V2_VISEE AL
group by IDVENTE, IDDEVISE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AVOIRFCLIB_CPL_V2_VISEE" ("ID", "DESIGNATION", "IDMAGASIN", "IDMAGASINLIB", "DATY", "REMARQUE", "ETAT", "IDORIGINE", "IDCLIENT", "COMPTE", "IDVENTE", "IDVENTELIB", "IDMOTIF", "IDMOTIFLIB", "IDCATEGORIE", "IDCATEGORIELIB", "IDDEVISE", "TAUXDECHANGE", "MONTANTHT", "MONTANTTVA", "MONTANTTTC", "MONTANTHTAR", "MONTANTTVAAR", "MONTANTTTCAR", "MONTANTPAYE", "MONTANTPAYEAR", "RESTEAPAYER", "RESTEAPAYERAR", "IMPUTEEFACT", "IMPUTEEFACTAR") AS
select ID,
       DESIGNATION,
       IDMAGASIN,
       IDMAGASINLIB,
       DATY,
       REMARQUE,
       ETAT,
       IDORIGINE,
       IDCLIENT,
       COMPTE,
       IDVENTE,
       IDVENTELIB,
       IDMOTIF,
       IDMOTIFLIB,
       IDCATEGORIE,
       IDCATEGORIELIB,
       IDDEVISE,
       TAUXDECHANGE,
       MONTANTHT,
       MONTANTTVA,
       MONTANTTTC,
       MONTANTHTAR,
       MONTANTTVAAR,
       MONTANTTTCAR,
       MONTANTPAYE,
       MONTANTPAYEAR,
       RESTEAPAYER,
       RESTEAPAYERAR,
       MONTANTTTC - MONTANTPAYE     as imputeefact,
       MONTANTTTCar - MONTANTPAYEar as imputeefactar
from AVOIRFCLIB_CPL_V2
where ETAT >= 11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AVOIRFCLIB_CPL_VISEE" ("ID", "DESIGNATION", "IDMAGASIN", "IDMAGASINLIB", "DATY", "REMARQUE", "ETAT", "IDORIGINE", "IDCLIENT", "COMPTE", "IDVENTE", "IDVENTELIB", "IDMOTIF", "IDMOTIFLIB", "IDCATEGORIE", "IDCATEGORIELIB", "IDDEVISE", "TAUXDECHANGE", "MONTANTHT", "MONTANTTVA", "MONTANTTTC", "MONTANTHTAR", "MONTANTTVAAR", "MONTANTTTCAR", "MONTANTPAYE", "MONTANTPAYEAR", "RESTEAPAYER", "RESTEAPAYERAR", "IMPUTEEFACT", "IMPUTEEFACTAR") AS
select ID,
       DESIGNATION,
       IDMAGASIN,
       IDMAGASINLIB,
       DATY,
       REMARQUE,
       ETAT,
       IDORIGINE,
       IDCLIENT,
       COMPTE,
       IDVENTE,
       IDVENTELIB,
       IDMOTIF,
       IDMOTIFLIB,
       IDCATEGORIE,
       IDCATEGORIELIB,
       IDDEVISE,
       TAUXDECHANGE,
       MONTANTHT,
       MONTANTTVA,
       MONTANTTTC,
       MONTANTHTAR,
       MONTANTTVAAR,
       MONTANTTTCAR,
       MONTANTPAYE,
       MONTANTPAYEAR,
       RESTEAPAYER,
       RESTEAPAYERAR,
       MONTANTTTC - MONTANTPAYE     as imputeefact,
       MONTANTTTCar - MONTANTPAYEar as imputeefactar
from avoirfclib_cpl
where ETAT >= 11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AVOIRFCLIB_PDF" ("ID", "DESIGNATION", "IDMAGASIN", "IDMAGASINLIB", "DATY", "REMARQUE", "ETAT", "IDORIGINE", "IDCLIENT", "COMPTE", "COMPTEAUXILIAIRE", "IDVENTE", "IDVENTELIB", "IDMOTIF", "IDMOTIFLIB", "IDCATEGORIE", "IDCATEGORIELIB", "IDDEVISE", "TAUXDECHANGE", "MONTANTHT", "MONTANTTVA", "MONTANTTTC", "MONTANTHTAR", "MONTANTTVAAR", "MONTANTTTCAR", "IDRESERVATION", "TYPEAVOIR", "CLIENTLIB", "NUMAVOIR", "IDRISTOURNE", "NUMFACT") AS
SELECT a.ID,
       a.DESIGNATION,
       a.IDMAGASIN,
       m.VAL         AS IDMAGASINLIB,
       a.DATY,
       a.REMARQUE,
       a.ETAT,
       a.IDORIGINE,
       a.IDCLIENT,
       t.COMPTE,
       t.compteauxiliaire,
       a.IDVENTE,
       v.DESIGNATION AS IDVENTELIB,
       a.IDMOTIF,
       ma.VAL        AS IDMOTIFLIB,
       a.IDCATEGORIE,
       c.VAL         AS IDCATEGORIELIB,
       ag.IDDEVISE,
       ag.TAUXDECHANGE,
       ag.MONTANTHT,
       ag.MONTANTTVA,
       ag.MONTANTTTC,
       ag.MONTANTHTAR,
       ag.MONTANTTVAAR,
       ag.MONTANTTTCAR,
       v.IDRESERVATION,
       ta.val        as Typeavoir,
       t.NOM         as clientlib,
       a.numavoir,
       a.idristourne,
       v.NUMEROFACTURE as numfact
FROM AVOIRFC a
         LEFT JOIN magasin2 m ON m.id = a.IDMAGASIN
         LEFT JOIN VENTE v ON v.id = a.IDVENTE
         LEFT JOIN MOTIFAVOIRFC ma ON ma.id = a.IDMOTIF
         LEFT JOIN CATEGORIEAVOIRFC c ON c.id = a.IDCATEGORIE
         JOIN AVOIRFCFILLE_GRP ag ON ag.idavoirfc = a.id
         LEFT JOIN TIERS T ON T.ID = A.IDCLIENT
         left join TYPEAVOIR ta on ta.id = a.IDTYPEAVOIR;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AVOIRFCMONTANT" ("ID", "DESIGNATION", "IDMAGASIN", "IDMAGASINLIB", "DATY", "REMARQUE", "ETAT", "IDORIGINE", "IDCLIENT", "COMPTE", "COMPTEAUXILIAIRE", "IDVENTE", "IDVENTELIB", "IDMOTIF", "IDMOTIFLIB", "IDCATEGORIE", "IDCATEGORIELIB", "IDDEVISE", "TAUXDECHANGE", "MONTANTHT", "MONTANTTVA", "MONTANTTTC", "MONTANTHTAR", "MONTANTTVAAR", "MONTANTTTCAR", "IDRESERVATION", "TYPEAVOIR", "CLIENTLIB", "MONTANTPAYEAR") AS
SELECT a.ID,
       a.DESIGNATION,
       a.IDMAGASIN,
       ''         AS IDMAGASINLIB,
       a.DATY,
       a.REMARQUE,
       a.ETAT,
       a.IDORIGINE,
       a.IDCLIENT,
       '' as COMPTE,
        '' as compteauxiliaire,
       a.IDVENTE,
       '' AS IDVENTELIB,
       a.IDMOTIF,
       ''        AS IDMOTIFLIB,
       a.IDCATEGORIE,
       ''         AS IDCATEGORIELIB,
       ag.IDDEVISE,
       ag.TAUXDECHANGE,
       ag.MONTANTHT,
       ag.MONTANTTVA,
       ag.MONTANTTTC,
       ag.MONTANTHTAR,
       ag.MONTANTTVAAR,
       ag.MONTANTTTCAR,
        '' as IDRESERVATION,
       ''        as Typeavoir,
       ''         as clientlib,
       NVL(M.montant, 0) * NVL(ag.TAUXDECHANGE, 0)              AS MONTANTPAYEAR
FROM AVOIRFC a
         --LEFT JOIN magasin2 m ON m.id = a.IDMAGASIN
         --LEFT JOIN VENTE v ON v.id = a.IDVENTE
         --LEFT JOIN MOTIFAVOIRFC ma ON ma.id = a.IDMOTIF
         --LEFT JOIN CATEGORIEAVOIRFC c ON c.id = a.IDCATEGORIE
         JOIN AVOIRFCFILLE_GRP ag ON ag.idavoirfc = a.id
         --LEFT JOIN TIERS T ON T.ID = A.IDCLIENT
         LEFT JOIN MOUVEMENTCAISSEGRPAVOIR_LP M
                   ON A.ID = M.IDORIGINE
where a.ETAT>=11 and a.IDORIGINE is not NULL;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AVOIRFCMONTANT_GBVENTE" ("IDVENTE", "MONTANTHT", "MONTANTTVA", "MONTANTTTC", "MONTANTHTAR", "MONTANTTVAAR", "MONTANTTTCAR", "MONTANTPAYEAR") AS
SELECT
    IDVENTE,
    SUM(NVL(MONTANTHT, 0))     AS MONTANTHT,
    SUM(NVL(MONTANTTVA, 0))    AS MONTANTTVA,
    SUM(NVL(MONTANTTTC, 0))    AS MONTANTTTC,
    SUM(NVL(MONTANTHTAR, 0))   AS MONTANTHTAR,
    SUM(NVL(MONTANTTVAAR, 0))  AS MONTANTTVAAR,
    SUM(NVL(MONTANTTTCAR, 0))  AS MONTANTTTCAR,
    SUM(NVL(MONTANTPAYEAR, 0)) AS MONTANTPAYEAR
FROM AVOIRFCMONTANT
GROUP BY IDVENTE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AVOIRFC_GRP_ANNULEE" ("IDAVOIRFC", "COMPTE", "MONTANTHT", "MONTANTTVA", "MONTANTTTC", "MONTANTHTAR", "MONTANTTVAAR", "MONTANTTTCAR", "ETAT", "TAUXDECHANGE") AS
select "IDAVOIRFC","COMPTE","MONTANTHT","MONTANTTVA","MONTANTTTC","MONTANTHTAR","MONTANTTVAAR","MONTANTTTCAR","ETAT","TAUXDECHANGE" from AVOIRFC_GRP_TOUS where etat < 1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AVOIRFC_GRP_CREEE" ("IDAVOIRFC", "COMPTE", "MONTANTHT", "MONTANTTVA", "MONTANTTTC", "MONTANTHTAR", "MONTANTTVAAR", "MONTANTTTCAR", "ETAT", "TAUXDECHANGE") AS
select "IDAVOIRFC","COMPTE","MONTANTHT","MONTANTTVA","MONTANTTTC","MONTANTHTAR","MONTANTTVAAR","MONTANTTTCAR","ETAT","TAUXDECHANGE" from AVOIRFC_GRP_TOUS where etat = 1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AVOIRFC_GRP_TOUS" ("IDAVOIRFC", "COMPTE", "MONTANTHT", "MONTANTTVA", "MONTANTTTC", "MONTANTHTAR", "MONTANTTVAAR", "MONTANTTTCAR", "ETAT", "TAUXDECHANGE") AS
select idavoirfc,
       compte,
       cast(sum(montantHT) as NUMBER(30, 2)) as montantHT,
       cast(sum(montantTVA) as NUMBER(30, 2)) as montantTVA,
       cast(sum(montantTTC) as NUMBER(30, 2)) as montantTTC,
       cast(sum(montantHT * TAUXDECHANGE) as NUMBER(30, 2)) as montantHTAR,
       cast(sum(montantTVA * TAUXDECHANGE) as NUMBER(30, 2)) as montantTVAAR,
       cast(sum(montantTTC * TAUXDECHANGE) as NUMBER(30, 2)) as montantTTCAR,
       ETAT,
       max(TAUXDECHANGE) AS TAUXDECHANGE 
from AVOIR_MF
group by idavoirfc, compte, etat;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AVOIRFC_GRP_VISEE" ("IDAVOIRFC", "COMPTE", "MONTANTHT", "MONTANTTVA", "MONTANTTTC", "MONTANTHTAR", "MONTANTTVAAR", "MONTANTTTCAR", "ETAT", "TAUXDECHANGE") AS
select "IDAVOIRFC","COMPTE","MONTANTHT","MONTANTTVA","MONTANTTTC","MONTANTHTAR","MONTANTTVAAR","MONTANTTTCAR","ETAT","TAUXDECHANGE" from AVOIRFC_GRP_TOUS where etat >= 11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AVOIRFC_MERE_MONTANT" ("ID", "DESIGNATION", "IDMAGASIN", "DATY", "REMARQUE", "ETAT", "IDORIGINE", "IDCLIENT", "MONTANTHT", "MONTANTTVA", "MONTANTTTC", "MONTANTHTAR", "MONTANTTVAAR", "MONTANTTTCAR", "TAUXDECHANGE", "CLIENTLIB", "COMPTE") AS
select v.ID,v.DESIGNATION,v.IDMAGASIN,v.DATY,v.REMARQUE,v.ETAT,v.IDORIGINE,v.IDCLIENT,
       vt.MONTANTHT,
       vt.MONTANTTVA,
       vt.MONTANTTTC,
       vt.MONTANTHTAR,
       vt.MONTANTTVAAR,
       vt.MONTANTTTCAR,
       vt.TAUXDECHANGE,
        CL.NOM AS CLIENTLIB,
       CL.COMPTE
from AVOIRFC v
left join AVOIRFC_GRP_TOUS vt on vt.IDAVOIRFC = v.id
left join CLIENT CL on CL.ID = v.IDCLIENT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AVOIRFC_MF" ("ID", "DESIGNATION", "IDMAGASIN", "DATY", "REMARQUE", "ETAT", "IDORIGINE", "IDCLIENT", "IDVENTE", "IDMOTIF", "IDCATEGORIE") AS
SELECT 
a1."ID",a1."DESIGNATION",a1."IDMAGASIN",a1."DATY",a1."REMARQUE",a1."ETAT",a1."IDORIGINE",a1."IDCLIENT",a1."IDVENTE",a1."IDMOTIF",a1."IDCATEGORIE"
FROM AVOIRFCFILLE a 
JOIN AVOIRFC a1 ON a1.ID = a.IDAVOIRFC;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AVOIR_MF" ("ID", "IDAVOIRFC", "IDPRODUIT", "IDORIGINE", "QTE", "PU", "REMISE", "TVA", "PUACHAT", "PUVENTE", "DESIGNATION", "IDMAGASIN", "DATY", "REMARQUE", "ETAT", "IDCLIENT", "MONTANTHT", "MONTANTTVA", "MONTANTTTC", "TAUXDECHANGE", "COMPTE") AS
select vd.ID,vd.idavoirfc,vd.IDPRODUIT,vd.IDORIGINE,vd.QTE,vd.PU,vd.REMISE,vd.TVA,vd.PUACHAT,vd.PUVENTE,
		v.DESIGNATION,
       v.IDMAGASIN,
       v.DATY,
       v.REMARQUE,
       v.ETAT,
       v.IDCLIENT,
         cast((vd.PU * vd.qte) as NUMBER(30, 2)) as montantHT,
       cast((vd.PU * vd.qte*(vd.tva/100)) as NUMBER(30, 2)) as montantTVA,
       cast(vd.PU * vd.qte + (vd.PU * vd.qte*(vd.tva/100))  as NUMBER(30, 2)) as montantTTC,
       vd.TAUXDECHANGE AS tauxdechange,
       p.COMPTE_VENTE AS compte
from avoirfcfille vd
 left outer join AVOIRFC  V on V.ID = vd.idavoirfc
         left outer join PRODUIT_LIBCPL p on p.ID = vd.IDPRODUIT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."BALANCE_CLIENT" ("IDPRODUIT", "LIBELLE", "IDFAMILLE", "FAMILLE", "QTE", "PU", "MONTANT", "IDCLIENT", "IDPROVINCE", "VAL", "DATY", "REMISE") AS
select
    vd.IDPRODUIT,
    ing.LIBELLE,
    nvl(ing.IDFAMILLE,'AUTRE') as IDFAMILLE,
    nvl(fam.VAL,'AUTRE') as famille,
    sum(vd.QTE) as qte,
    sum(vd.PU*vd.QTE)/sum(vd.QTE) as pu,
    sum(vd.QTE * vd.PU) as montant,
    v.IDCLIENT,
    cl.IDPROVINCE,
    p.VAL,
    v.DATY,
    SUM(vd.QTE * vd.PU * NVL(vd.remise, 0) / 100) AS remise
from VENTE_DETAILS vd
    join Vente v on vd.IDVENTE=v.id
    join AS_INGREDIENTS ing on ing.id=vd.IDPRODUIT
    left join FAMILLEPRODUIT fam on fam.id=ing.IDFAMILLE
    join Client cl on cl.id=v.IDCLIENT
    left join Province p on p.id=cl.IDPROVINCE
group by vd.IDPRODUIT, ing.LIBELLE, nvl(ing.IDFAMILLE,'AUTRE'),nvl(fam.VAL,'AUTRE'), v.IDCLIENT, cl.IDPROVINCE, p.VAL, v.DATY;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."BALANCE_VIDE" ("COMPTE", "CHIFFRE3", "CHIFFRE2", "LIBELLECOMPTE", "ANTERIEURDEBIT", "ANTERIEURCREDIT", "MOUVEMENTDEBIT", "MOUVEMENTCREDIT") AS
SELECT
    '-' AS compte,
    '-' AS chiffre3,
    '-' AS chiffre2,
    '-' AS libelleCompte,
    CAST(0 AS NUMBER(30,
        2)) AS anterieurDebit,
    CAST(0 AS NUMBER(30,
        2)) AS anterieurCredit,
    CAST(0 AS NUMBER(30,
        2)) AS mouvementDebit,
    CAST(0 AS NUMBER(30,
        2)) AS mouvementCredit
FROM
    dual;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."BANQUEAGENCELIB" ("ID", "NOM", "CODEAGENCE", "IDBANQUE", "IDBANQUELIB") AS
SELECT
       bqa.id,
       bqa.nom,
       bqa.codeAgence,
       bqa.idBanque,
       b.val as idBanqueLib
FROM BANQUE_AGENCE bqa
   LEFT JOIN Banque b ON bqa.idBanque = b.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."BANQUE_COMPTA" ("ID", "VAL", "DESCE") AS
SELECT id,
       val,
       COMPTE AS desce
FROM CAISSE c
WHERE IDTYPECAISSE = 'TCA001'
  AND actif = 1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."BATIMENTDETAIL_LIB" ("ID", "IDMERE", "IDPARQUET", "SURFACE", "CAPACITE", "IDLOT", "IDSEXE", "DENSITE", "IDPARQUETLIB", "IDLOTLIB", "IDSEXELIB", "EFFECTIF") AS
SELECT
    bd."ID",bd."IDMERE",bd."IDPARQUET",bd."SURFACE",bd."CAPACITE",bd."IDLOT",bd."IDSEXE",bd."DENSITE",
    p.val    AS idParquetLib,
    l.nomLot AS idLotLib,
    s.val    AS idSexeLib,
    NVL(bd."SURFACE" * bd."DENSITE", 0) AS EFFECTIF
FROM batimentDetail bd
         LEFT JOIN parquet p ON bd.idParquet = p.id
         LEFT JOIN lot  l ON bd.idLot     = l.id
         LEFT JOIN sexe s ON bd.idSexe    = s.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."BATIMENTVIDESANITAIREDETAILLIB" ("ID", "IDMERE", "IDPRODUIT", "QTE", "REMARQUE", "IDPRODUITLIB", "IDUNITE", "IDUNITELIB", "PU") AS
SELECT 
	bvsd.id AS ID,
	bvsd.idmere AS IDMERE,
	bvsd.idproduit AS IDPRODUIT,
	bvsd.qte AS QTE,
	bvsd.remarque AS REMARQUE,
	ai.LIBELLE AS IDPRODUITLIB,
	ai.UNITE AS IDUNITE,
	asu.VAL AS IDUNITELIB,
	ai.PU AS PU
FROM batimentVideSanitaireDetail bvsd
LEFT JOIN AS_INGREDIENTS ai ON bvsd.idproduit = ai.ID
LEFT JOIN AS_UNITE asu ON ai.UNITE = asu.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."BATIMENTVIDESANITAIRE_LIB" ("ID", "IDBATIMENT", "IDRESPONSABLE", "DATY", "HEUREDEBUT", "HEUREFIN", "IDBATIMENTLIB", "IDFERME", "IDFERMELIB", "IDRESPONSABLELIB", "ETAT", "ETATLIB") AS
SELECT
	bvs.id AS ID,
	bvs.idbatiment AS IDBATIMENT,
	bvs.idresponsable AS IDRESPONSABLE,
	bvs.daty AS DATY,
	bvs.heuredebut AS HEUREDEBUT,
	bvs.heurefin AS HEUREFIN,
	b.NOMBATIMENT AS IDBATIMENTLIB,
	b.IDFERME AS IDFERME,
	m.VAL AS IDFERMELIB,
	lp.NOM || ' ' || lp.PRENOM AS IDRESPONSABLELIB,
	bvs.etat,
	CASE
        WHEN bvs.etat = 1 THEN 'CREE'
            WHEN bvs.etat = 0 THEN 'ANNULEE'
            WHEN bvs.etat = 11 THEN 'VISEE'
        END AS etatLib
FROM batimentVideSanitaire bvs
LEFT JOIN BATIMENT b ON bvs.idbatiment = b.ID
LEFT JOIN MAGASIN2 m ON b.IDFERME = m.ID
LEFT JOIN LOG_PERSONNEL lp ON bvs.idresponsable = lp.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."BATIMENT_LIB" ("ID", "IDFERME", "NOMBATIMENT", "SURFACE", "CAPACITE", "DENSITE", "LONGUEUR", "LARGEUR", "IDFERMELIB") AS
SELECT
    b.ID,b.IDFERME,b.NOMBATIMENT,b.SURFACE,b.CAPACITE,b.DENSITE,b.LONGUEUR,b.LARGEUR,
    m.val AS idFermeLib
FROM batiment b
         LEFT JOIN MAGASIN2 m ON b.idFerme = m.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."BCCLIENT_FILLE_GRP" ("ID", "QUANTITE") AS
SELECT 
bc.ID,
nvl( sum(bcf.QUANTITE) ,0) AS QUANTITE
FROM BONDECOMMANDE_CLIENT_FILLE bcf 
LEFT JOIN BONDECOMMANDE_CLIENT bc ON bcf.IDBC = bc.ID
GROUP BY bc.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."BCFILLERESTEALIVRERLIB" ("ID", "IDBC", "IDPRODUIT", "IDPRODUITLIB", "QUANTITE", "PU", "REMISE", "TVA", "IDUNITE", "IDDEVISE", "TAUXDECHANGE") AS
SELECT 
f.ID ,
f.IDBC ,
f.PRODUIT AS idproduit,
p.VAL AS IDPRODUITLIB,
f.QUANTITE ,
f.PU ,
f.REMISE , 
f.TVA , 
p.idunite AS idunite, 
f.iddevise,
f.tauxdechange
FROM AS_BONDECOMMANDE_FILLE f 
LEFT JOIN PRODUIT p ON p.ID = f.PRODUIT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."BC_CLIENT_FILLE_CPL_LIB" ("ID", "PRODUIT", "IDBC", "QUANTITE", "PU", "MONTANT", "TVA", "REMISE", "IDDEVISE", "UNITE", "PRODUITLIB", "COMPTE", "QTERESTE", "UNITELIB", "MONTANTTOTAL", "MONTANTDELAREMISE", "MONTANTRISTOURNE", "MONTANTREMISE", "MONTANTTVA", "MONTANTTTC", "MONTANTTTCAR", "RISTOURNE", "FRAISTRANSPORT", "POIDSTOTAL", "TAUX", "REMISEARBIOCHEM", "RISTOURNEARBIOCHEM") AS
SELECT bcf.ID,
       bcf.PRODUIT,
       bcf.IDBC,
       bcf.QUANTITE,
       bcf.PU,
       bcf.MONTANT,
       bcf.TVA,
       bcf.REMISE,
       bcf.IDDEVISE,
       bcf.UNITE,
       nvl(i.LIBELLEVENTE,i.libelle)                                                                                                                  AS PRODUITlib,
       i.compte_vente                                                                                                                                 AS compte,
       NVL(bcf.quantite, 0)    - NVL(vdbc.qte, 0)    AS qtereste,   -- nanova qte reste : atao moins qte vendu  avy aminy vente_details_qte_grp
       au.val                                                                                                                                         AS UNITELIB,
       cast(NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0) as Number(30, 2))                                                                                   AS MONTANTTOTAL,
       cast(((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100)) as number(30, 2))                                                          as montantdelaremise,
       cast((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0) - ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100))) *
            (bcf.ristourne / 100) as number(30, 2))                                                                                                   as montantristourne,
       cast(NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0) - ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100)) -
            ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0) - ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100))) *
             (bcf.ristourne / 100)) -
            nvl(i.CALORIE * bcf.QUANTITE * bc.fraislivraison, 0) as number(30, 2))                                                                    as montantremise,
       CAST(
               (((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) -
                 (((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100)) +
                  ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0) -
                    ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100))) * (bcf.ristourne / 100))) -
                 nvl(i.CALORIE * bcf.QUANTITE * bc.fraislivraison, 0)) *
                (nvl(bcf.TVA, 0) / 100))
           AS NUMBER(30, 2)
       )                                                                                                                                              AS MONTANTTVA,
       cast((cast((bcf.quantite * bcf.PU) - ((bcf.quantite * bcf.PU) * NVL(bcf.remise, 0)) / 100 as NUMBER(30, 2)) -
             (cast((bcf.quantite * bcf.PU) - ((bcf.quantite * bcf.PU) * NVL(bcf.remise, 0)) / 100 as NUMBER(30, 2)) *
              nvl(bcf.ristourne, 0) /
              100) - nvl(i.CALORIE * bcf.QUANTITE * bc.fraislivraison, 0)) + (nvl(bcf.TVA, 0) / 100) *
                                                                             (cast((bcf.quantite * bcf.PU) -
                                                                                   ((bcf.quantite * bcf.PU) * NVL(bcf.remise, 0)) /
                                                                                   100 as NUMBER(30, 2)) -
                                                                              (cast((bcf.quantite * bcf.PU) -
                                                                                    ((bcf.quantite * bcf.PU) * NVL(bcf.remise, 0)) /
                                                                                    100 as NUMBER(30, 2)) *
                                                                               nvl(bcf.ristourne, 0) / 100) -
                                                                              nvl(i.CALORIE * bcf.QUANTITE * bc.fraislivraison, 0)) as number(30, 2)) AS MONTANTTTC,
       cast(((cast((bcf.quantite * bcf.PU) - ((bcf.quantite * bcf.PU) * NVL(bcf.remise, 0)) / 100 as NUMBER(30, 2)) -
              (cast((bcf.quantite * bcf.PU) - ((bcf.quantite * bcf.PU) * NVL(bcf.remise, 0)) / 100 as NUMBER(30, 2)) *
               nvl(bcf.ristourne, 0) /
               100) - nvl(i.CALORIE * bcf.QUANTITE * bc.fraislivraison, 0)) + (nvl(bcf.TVA, 0) / 100) *
                                                                              (cast((bcf.quantite * bcf.PU) -
                                                                                    ((bcf.quantite * bcf.PU) * NVL(bcf.remise, 0)) /
                                                                                    100 as NUMBER(30, 2)) -
                                                                               (cast((bcf.quantite * bcf.PU) -
                                                                                     ((bcf.quantite * bcf.PU) * NVL(bcf.remise, 0)) /
                                                                                     100 as NUMBER(30, 2)) *
                                                                                nvl(bcf.ristourne, 0) / 100) -
                                                                               nvl(i.CALORIE * bcf.QUANTITE * bc.fraislivraison, 0)))*bcf.TAUX as number(30, 2)) AS MONTANTTTCAR,
       bcf.ristourne,
       nvl(i.CALORIE * bcf.QUANTITE * bc.fraislivraison, 0)                                                                                           as fraistransport,
       CAST(NVL(i.CALORIE * bcf.QUANTITE,0) AS NUMBER(30,2)) AS poidstotal,bcf.taux,
       bcf.remiseArbiochem,
       bcf.ristourneArbiochem
FROM bondecommande_client_fille bcf
         left JOIN as_ingredients i ON i.id = bcf.PRODUIT
         LEFT JOIN vente_details_qte_grp vdbc ON bcf.id = vdbc.idbcfille
         LEFT JOIN AS_UNITE au ON au.id = i.unite
         LEFT JOIN BONDECOMMANDE_CLIENT bc on bc.id = bcf.IDBC;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."BC_CLIENT_FILLE_CPL_LIB2" ("ID", "PRODUIT", "IDBC", "QUANTITE", "PU", "MONTANT", "TVA", "REMISE", "IDDEVISE", "UNITE", "PRODUITLIB", "COMPTE", "QTERESTE", "UNITELIB", "MONTANTTOTAL", "MONTANTDELAREMISE", "MONTANTRISTOURNE", "MONTANTREMISE", "MONTANTTVA", "MONTANTTTC", "MONTANTTTCAR", "RISTOURNE", "FRAISTRANSPORT", "POIDSTOTAL", "TAUX", "REMISEARBIOCHEM", "RISTOURNEARBIOCHEM", "QTELIVRE", "QTEFACTURE") AS
SELECT bcf.ID,
       bcf.PRODUIT,
       bcf.IDBC,
       bcf.QUANTITE,
       bcf.PU,
       bcf.MONTANT,
       bcf.TVA,
       bcf.REMISE,
       bcf.IDDEVISE,
       bcf.UNITE,
       nvl(i.LIBELLEVENTE,i.libelle)                                                                                                                  AS PRODUITlib,
       i.compte_vente                                                                                                                                 AS compte,
       NVL(bcf.quantite, 0)    - NVL(vdbc.qte, 0)    AS qtereste,   -- nanova qte reste : atao moins qte vendu  avy aminy vente_details_qte_grp
       au.val                                                                                                                                         AS UNITELIB,
       cast(NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0) as Number(30, 2))                                                                                   AS MONTANTTOTAL,
       -- montantRemise : remise classique (%) + remise Arbiochem (montant fixe par unite)
       cast((((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100))+ (nvl(bcf.remiseArbiochem,0) * bcf.QUANTITE)) as number(30, 2))          as montantdelaremise,

       -- montantristourne : ristourne classique (%) + ristourne Arbiochem (montant fixe par unite)
       cast(
               ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0) - ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100))) *
                (bcf.ristourne / 100))
                   + (nvl(bcf.ristourneArbiochem, 0) * bcf.QUANTITE)
           as number(30, 2)
       )                                                                                                                                              as montantristourne,

       -- montantremise : base HT nette = brut - remise% - ristourne% (incl. ristourneArbiochem) - frais transport - remiseArbiochem
       cast(
               NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)
                   - ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100))
                   - (
                   ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0) - ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100))) *
                    (bcf.ristourne / 100))
                       + (nvl(bcf.ristourneArbiochem, 0) * bcf.QUANTITE)
                   )
                   - nvl(i.CALORIE * bcf.QUANTITE * bc.fraislivraison, 0)
                   - (nvl(bcf.remiseArbiochem, 0) * bcf.QUANTITE)
           as number(30, 2)
       )                                                                                                                                              as montantremise,

       -- MONTANTTVA : TVA calculee sur le nouveau montantremise (donc corrigee des montants Arbiochem)
       CAST(
               (
                   (NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)
                       - ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100))
                       - (
                        ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0) - ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100))) *
                         (bcf.ristourne / 100))
                            + (nvl(bcf.ristourneArbiochem, 0) * bcf.QUANTITE)
                        )
                       - nvl(i.CALORIE * bcf.QUANTITE * bc.fraislivraison, 0)
                       - (nvl(bcf.remiseArbiochem, 0) * bcf.QUANTITE)
                       ) * (nvl(bcf.TVA, 0) / 100)
                   )
           AS NUMBER(30, 2)
       )                                                                                                                                              AS MONTANTTVA,

       -- MONTANTTTC : montantremise (corrige) + MONTANTTVA (corrigee)
       cast(
               (
                   NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)
                       - ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100))
                       - (
                       ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0) - ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100))) *
                        (bcf.ristourne / 100))
                           + (nvl(bcf.ristourneArbiochem, 0) * bcf.QUANTITE)
                       )
                       - nvl(i.CALORIE * bcf.QUANTITE * bc.fraislivraison, 0)
                       - (nvl(bcf.remiseArbiochem, 0) * bcf.QUANTITE)
                   )
                   + (
                   (
                       NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)
                           - ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100))
                           - (
                           ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0) - ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100))) *
                            (bcf.ristourne / 100))
                               + (nvl(bcf.ristourneArbiochem, 0) * bcf.QUANTITE)
                           )
                           - nvl(i.CALORIE * bcf.QUANTITE * bc.fraislivraison, 0)
                           - (nvl(bcf.remiseArbiochem, 0) * bcf.QUANTITE)
                       ) * (nvl(bcf.TVA, 0) / 100)
                   )
           as number(30, 2)
       )                                                                                                                                              AS MONTANTTTC,

       -- MONTANTTTCAR : simplifie, les montants Arbiochem sont deja pris en compte en amont dans montantremise
       cast(
               (
                   (
                       NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)
                           - ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100))
                           - (
                           ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0) - ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100))) *
                            (bcf.ristourne / 100))
                               + (nvl(bcf.ristourneArbiochem, 0) * bcf.QUANTITE)
                           )
                           - nvl(i.CALORIE * bcf.QUANTITE * bc.fraislivraison, 0)
                           - (nvl(bcf.remiseArbiochem, 0) * bcf.QUANTITE)
                       )
                       + (
                       (
                           NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)
                               - ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100))
                               - (
                               ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0) - ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100))) *
                                (bcf.ristourne / 100))
                                   + (nvl(bcf.ristourneArbiochem, 0) * bcf.QUANTITE)
                               )
                               - nvl(i.CALORIE * bcf.QUANTITE * bc.fraislivraison, 0)
                               - (nvl(bcf.remiseArbiochem, 0) * bcf.QUANTITE)
                           ) * (nvl(bcf.TVA, 0) / 100)
                       )
                   ) * bcf.TAUX
           as number(30, 2)
       )                                                                                                                                              AS MONTANTTTCAR,

       bcf.ristourne,
       nvl(i.CALORIE * bcf.QUANTITE * bc.fraislivraison, 0)                                                                                           as fraistransport,
       CAST(NVL(i.CALORIE * bcf.QUANTITE,0) AS NUMBER(30,2)) AS poidstotal,bcf.taux,
       nvl(bcf.remiseArbiochem,0) as remiseArbiochem,
       nvl(bcf.ristourneArbiochem,0) as ristourneArbiochem,
       cast(nvl(blf.QUANTITE,0) as number(30,2)) as qtelivre, cast(nvl(vdbc.qte,0) as number(30,2)) as qteFacture
FROM bondecommande_client_fille bcf
         left JOIN as_ingredients i ON i.id = bcf.PRODUIT
         LEFT JOIN vente_details_qte_grp vdbc ON bcf.id = vdbc.idbcfille
         LEFT JOIN AS_UNITE au ON au.id = i.unite
         LEFT JOIN BONDECOMMANDE_CLIENT bc on bc.id = bcf.IDBC
         left join as_BLClientFilleGrpBCFille blf on blf.IDBC_FILLE=bcf.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."BC_CLIENT_FILLE_CPL_LIBB" ("ID", "PRODUIT", "IDBC", "QUANTITE", "PU", "MONTANTREMISE", "MONTANTTOTAL", "MONTANT", "TVA", "MONTANTTVA", "REMISE", "IDDEVISE", "UNITE", "UNITELIB", "PRODUITLIB", "COMPTE", "QTERESTE") AS
SELECT
    bcf.ID,
    bcf.PRODUIT,
    bcf.IDBC,
    bcf.QUANTITE,
    bcf.PU,
    (nvl(nvl(bcf.QUANTITE,0)*nvl(bcf.PU,0),0)*bcf.REMISE)/100 as montantremise,
    nvl(bcf.QUANTITE,0)*nvl(bcf.PU,0)-((nvl(nvl(bcf.QUANTITE,0)*nvl(bcf.PU,0),0)*bcf.REMISE)/100)+((((nvl(bcf.QUANTITE,0)*nvl(bcf.PU,0)-(nvl(nvl(bcf.QUANTITE,0)*nvl(bcf.PU,0),0)*bcf.REMISE)/100)*bcf.tva)/100)) as montanttotal,
    bcf.MONTANT as montant,
    bcf.TVA,
    (((nvl(bcf.QUANTITE,0)*nvl(bcf.PU,0)-(nvl(nvl(bcf.QUANTITE,0)*nvl(bcf.PU,0),0)*bcf.REMISE)/100)*bcf.tva)/100) as montanttva,
    bcf.REMISE,
    bcf.IDDEVISE,
    bcf.UNITE,
    un.VAL as unitelib,
    i.LIBELLE AS PRODUITlib,
    i.compte_vente AS compte,
    GREATEST(NVL(bcf.quantite, 0) - NVL(vdbc.qte, 0), 0) AS qtereste
FROM
bondecommande_client_fille bcf
JOIN as_ingredients i ON i.id = bcf.PRODUIT
    left join AS_UNITE un on un.id=bcf.UNITE
LEFT JOIN vente_details_qte_grp vdbc ON bcf.id = vdbc.idbcfille;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."BC_CLIENT_FILLE_CPL_LIB_PDF" ("ID", "PRODUIT", "IDBC", "QUANTITE", "PU", "MONTANT", "TVA", "REMISE", "IDDEVISE", "UNITE", "PRODUITLIB", "COMPTE", "QTERESTE", "UNITELIB", "MONTANTTOTAL", "MONTANTDELAREMISE", "MONTANTRISTOURNE", "MONTANTREMISE", "MONTANTTVA", "MONTANTTTC", "RISTOURNE", "FRAISTRANSPORT", "POIDSTOTAL", "PUINGREDIENT", "CONTENUE", "UNITE2", "REMISEARBIOCHEM") AS
SELECT bcf.ID,
       bcf.PRODUIT,
       bcf.IDBC,
       bcf.QUANTITE,
       bcf.PU,
       bcf.MONTANT,
       bcf.TVA,
       bcf.REMISE,
       bcf.IDDEVISE,
       bcf.UNITE,
       nvl(i.LIBELLEVENTE,i.libelle)                                                                                                                                      AS PRODUITlib,
       i.compte_vente                                                                                                                                 AS compte,
       NVL(bcf.quantite, 0)    - NVL(vdbc.qte, 0)    AS qtereste,   -- nanova qte reste : atao moins qte vendu  avy aminy vente_details_qte_grp
       au.val                                                                                                                                         AS UNITELIB,
       cast(NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0) as Number(30, 2))                                                                                   AS MONTANTTOTAL,
       cast(((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100)) as number(30, 2))                                                          as montantdelaremise,
       cast((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0) - ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100))) *
            (bcf.ristourne / 100) as number(30, 2))                                                                                                   as montantristourne,
       cast(NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0) - ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100)) as number(30, 2))                                                                    as montantremise,
       CAST(
               (((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) -
                 (((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100)) +
                  ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0) -
                    ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100))) * (bcf.ristourne / 100))) -
                 nvl(i.CALORIE * bcf.QUANTITE * bc.fraislivraison, 0)) *
                (nvl(bcf.TVA, 0) / 100))
           AS NUMBER(30, 2)
       )                                                                                                                                              AS MONTANTTVA,
       cast((cast((bcf.quantite * bcf.PU) - ((bcf.quantite * bcf.PU) * NVL(bcf.remise, 0)) / 100 as NUMBER(30, 2)) -
             (cast((bcf.quantite * bcf.PU) - ((bcf.quantite * bcf.PU) * NVL(bcf.remise, 0)) / 100 as NUMBER(30, 2)) *
              nvl(bcf.ristourne, 0) /
              100) - nvl(i.CALORIE * bcf.QUANTITE * bc.fraislivraison, 0)) + (nvl(bcf.TVA, 0) / 100) *
                                                                             (cast((bcf.quantite * bcf.PU) -
                                                                                   ((bcf.quantite * bcf.PU) * NVL(bcf.remise, 0)) /
                                                                                   100 as NUMBER(30, 2)) -
                                                                              (cast((bcf.quantite * bcf.PU) -
                                                                                    ((bcf.quantite * bcf.PU) * NVL(bcf.remise, 0)) /
                                                                                    100 as NUMBER(30, 2)) *
                                                                               nvl(bcf.ristourne, 0) / 100) -
                                                                              nvl(i.CALORIE * bcf.QUANTITE * bc.fraislivraison, 0)) as number(30, 2)) AS MONTANTTTC,
       bcf.ristourne,
       nvl(i.CALORIE * bcf.QUANTITE * bc.fraislivraison, 0)                                                                                           as fraistransport,
       CAST(NVL(i.CALORIE * bcf.QUANTITE,0) AS NUMBER(30,2)) AS poidstotal,
       CAST((bcf.pu/nvl(eq.QUANTITE,1)) AS NUMBER (30,2)) as puingredient,
       nvl(eq.QUANTITE,1) as contenue,
       i.UNITE2,
       bcf.REMISEARBIOCHEM 
FROM bondecommande_client_fille bcf
         left JOIN as_ingredients i ON i.id = bcf.PRODUIT
         LEFT JOIN vente_details_qte_grp vdbc ON bcf.id = vdbc.idbcfille
         LEFT JOIN AS_UNITE au ON au.id = i.unite
         LEFT JOIN BONDECOMMANDE_CLIENT bc on bc.id = bcf.IDBC
         LEFT JOIN EQUIVALENCEVENTE eq on eq.IDPRODUIT1=i.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."BC_CLIENT_FILLE_CPL_LIB_VISEE" ("ID", "IDBC", "IDDEVISE", "MONTANT", "PRODUIT", "PU", "QUANTITE", "REMISE", "TVA", "UNITE", "QTEOF", "QTEOFRESTANTE", "QTEFAB", "QTEFABRESTANTE", "QTELIVRE", "QTENONLIVRE", "LIBELLEPRODUIT", "PRODUITLIB") AS
select bc."ID",bc."IDBC",bc."IDDEVISE",bc."MONTANT",bc."PRODUIT",bc."PU",bc."QUANTITE",bc."REMISE",bc."TVA",bc."UNITE",bc."QTEOF",bc."QTEOFRESTANTE",bc."QTEFAB",bc."QTEFABRESTANTE",bc."QTELIVRE",bc."QTENONLIVRE",bc."LIBELLEPRODUIT",i.LIBELLE as produitlib
from BONDECOMMANDE_CLIENT_FILLE_CPL bc
join AS_INGREDIENTS i
on i.ID = bc.PRODUIT
JOIN BONDECOMMANDE_CLIENT mere
on mere.ID = bc.IDBC
where ETAT >=11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."BC_DETAILS_RESTE" ("ID", "PRODUIT", "UNITE", "QUANTITE", "RESTE", "IDBC") AS
SELECT 
bcf.id AS id,
bcf.produit,
bcf.UNITE AS unite,
bcf.QUANTITE  AS QUANTITE,
nvl(bcf.QUANTITE,0) - nvl(bl.QUANTITE,0) AS reste,
bcf.IDBC AS IDBC
FROM 
BONDECOMMANDE_CLIENT_FILLE bcf LEFT JOIN 
BL_CLIENT_FILLE_grp_bc bl ON bcf.ID = bl.idbc_fille;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."BC_GROUPE_ING" ("BCLIST", "PRODUIT", "LIBELLEPRODUIT", "CLIENTLIST", "QTEOFRESTANTE") AS
SELECT
    LISTAGG(ID || ':' || QTEOFRESTANTE, ';') WITHIN GROUP (ORDER BY ID) AS BCLIST,
    PRODUIT,
    LIBELLEPRODUIT,
    LISTAGG(IDCLIENTLIB , ';') WITHIN GROUP (ORDER BY ID) AS CLIENTLIST,
    SUM(QTEOFRESTANTE) AS QTEOFRESTANTE
    FROM
    ASYNCARTISANAT.BONDECOMMANDE_CLIENT_GLOBALE
    WHERE
    QTEOFRESTANTE > 0
    GROUP BY
    PRODUIT,
    LIBELLEPRODUIT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."BLCF_GRPVENTEDET" ("IDVENTEDETAIL", "QUANTITE") AS
SELECT 
IDVENTEDETAIL,
sum(quantite) AS quantite
FROM 
AS_BONDELIVRAISON_CLIENT_FILLE group by IDVENTEDETAIL;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."BLCLIENT_FILLE_GRP" ("IDBC_FILLE", "IDBC", "QUANTITE", "PRODUIT", "NUMBL", "IDVENTEDETAIL", "UNITE") AS
SELECT 
abcf.IDBC_FILLE ,
bcf.IDBC,
nvl(sum(abcf.QUANTITE),0) AS QUANTITE,
abcf.PRODUIT,
abcf.NUMBL,
abcf.IDVENTEDETAIL,
abcf.UNITE
FROM AS_BONDELIVRAISON_CLIENT_FILLE abcf 
LEFT JOIN BONDECOMMANDE_CLIENT_FILLE bcf ON bcf.id = abcf.IDBC_FILLE
GROUP BY abcf.IDBC_FILLE,bcf.IDBC,abcf.PRODUIT,abcf.NUMBL,abcf.IDVENTEDETAIL,abcf.UNITE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."BLC_NONFACTURE" ("ID", "REMARQUE", "IDBC", "DATY", "ETAT", "MAGASIN", "MAGASINLIB", "ETATLIB", "IDVENTE", "IDVENTELIB", "IDCLIENT", "IDCLIENTLIB") AS
SELECT
	ID,
	REMARQUE,
	IDBC,
	DATY,
	ETAT,
	MAGASIN,
	MAGASINLIB,
	ETATLIB,
	IDVENTE,
	IDVENTELIB,
	IDCLIENT ,
    IDCLIENTLIB
FROM
	AS_BONDELIVRAISONCLIENT_LIB
WHERE
	idVente IS NULL AND ETAT >=11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."BLGROUPBYIDBC" ("IDBC_FILLE", "QUANTITE") AS
SELECT 
    f.IDBC_FILLE,
    SUM(f.QUANTITE) AS quantite
FROM AS_BONDELIVRAISON_CLIENT_FILLE f
LEFT JOIN AS_BONDELIVRAISON_CLIENT m ON m.ID = f.NUMBL
WHERE m.ETAT >= 11
GROUP BY f.IDBC_FILLE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."BL_CLIENT_FILLE_BC" ("ID", "IDBC", "PRODUIT", "IDPRODUIT", "QUANTITE", "DATY") AS
SELECT
	ABCF.id,
	ABC.IDBC ,
	pl.LIBELLE AS PRODUIT,
	ABCF.PRODUIT AS IDPRODUIT,
	ABCF.QUANTITE ,
	ABC.DATY 
 FROM AS_BONDELIVRAISON_CLIENT_FILLE abcf 
	JOIN BONDECOMMANDE_CLIENT_FILLE bcfc ON BCFC.ID = ABCF.IDBC_FILLE 
	JOIN AS_BONDELIVRAISON_CLIENT abc ON abc.ID = ABCF.NUMBL 
	JOIN AS_INGREDIENTS pl ON pl.ID = ABCF.PRODUIT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."BL_CLIENT_FILLE_GRP_BC" ("IDBC_FILLE", "QUANTITE") AS
SELECT
    IDBC_FILLE,
    SUM(QUANTITE) AS QUANTITE
FROM
    AS_BONDELIVRAISON_CLIENT_FILLE abcf
        left join BONDECOMMANDE_CLIENT b on b.id=abcf.NUMBL
        left join AS_BONDELIVRAISON_CLIENT abc on abc.ID = NUMBL
where abc.ETAT =11
GROUP BY IDBC_FILLE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."BL_CLIENT_FILLE_GRP_VENTE" ("IDVENTEDETAIL", "QUANTITE") AS
SELECT IDVENTEDETAIL,
       SUM(QUANTITE) AS QUANTITE
FROM AS_BONDELIVRAISON_CLIENT_FILLE abcf
GROUP BY IDVENTEDETAIL;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."BL_NONFACTURE" ("ID", "REMARQUE", "IDBC", "DATY", "ETAT", "MAGASIN", "MAGASINLIB", "ETATLIB", "IDFOURNISSEUR", "IDFOURNISSEURLIB") AS
SELECT
	    abl.ID,abl.REMARQUE,abl.IDBC,abl.DATY,abl.ETAT,abl.MAGASIN,abl.MAGASINLIB,abl.ETATLIB,abl.IDFOURNISSEUR,abl.IDFOURNISSEURLIB
	FROM AS_BONDELIVRAISON_LIB abl
	WHERE abl.IDFACTUREFOURNISSEUR IS NULL;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."BL_QTELIVREE_BY_IDBCFILLE" ("IDBC_FILLE", "QUANTITE_LIVREE") AS
SELECT
  IDBC_FILLE,
  SUM(QUANTITE) AS QUANTITE_LIVREE
FROM AS_BONDELIVRAISON_CLIENT_FILLE
GROUP BY IDBC_FILLE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."BONCOMMANDEDETAILSCARTON_CPL" ("ID", "IDBC", "PRODUITLIB", "PRODUIT", "QUANTITEBF", "QUANTITECF", "RESTECF") AS
SELECT 
bc.ID ,
bc.idbc AS idbc ,
ai.LIBELLE AS produitlib,
ai.id AS produit,
nvl(bc.QUANTITE,0) AS quantitebf ,
nvl(c.QUANTITE,0) AS quantitecf,
nvl(bc.QUANTITE,0) - nvl(c.QUANTITE,0) AS restecf
FROM BONDECOMMANDE_CLIENT_FILLE bc 
LEFT JOIN CARTONFILLE c  ON c.IDBCFILLE = bc.ID 
LEFT JOIN AS_INGREDIENTS ai ON ai.ID = bc.PRODUIT
GROUP BY bc.ID, bc.idbc, ai.LIBELLE, ai.id, bc.QUANTITE, c.QUANTITE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."BONCOMMANDEFABDETAILS" ("IDINGREDIENTS", "LIBELLEEXTACTE", "IDBC", "QTE", "IDFABRICATION") AS
SELECT
	fl.IDINGREDIENTS ,
	i.LIBELLE,
	bc.ID,
	sum(fl.QTE) qte,
	fl.IDMERE AS IDFABRICATION
FROM FABRICATIONFILLE fl
LEFT JOIN BONDECOMMANDE_CLIENT_FILLE bcf ON bcf.ID = fl.IDBCFILLE
LEFT JOIN BONDECOMMANDE_CLIENT bc ON bc.ID = bcf.IDBC
LEFT JOIN FABRICATION f
ON f.ID = fl.IDMERE
JOIN AS_INGREDIENTS i
ON fl.IDINGREDIENTS = i.ID
WHERE f.ETAT >= 11
GROUP BY fl.IDINGREDIENTS ,i.LIBELLE,bc.ID, fl.IDMERE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."BONDECOMMANDEFACTURER" ("PRODUIT", "QUANTITE", "IDPROFORMA") AS
select PRODUIT,sum(bcf.QUANTITE) - sum(vdf.QTE) as quantite, bc.IDPROFORMA from bondecommande_client_fille bcf join VENTE_DETAILS vdf ON bcf.id = vdf.idbcfille join vente v on v.id=vdf.IDVENTE join BONDECOMMANDE_CLIENT bc on bc.ID=bcf.IDBC where v.ETAT>=11 group by PRODUIT, bc.IDPROFORMA;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."BONDECOMMANDE_CLIENTF_TAUX" ("ID", "PRODUIT", "IDBC", "QUANTITE", "PU", "MONTANT", "TVA", "REMISE", "IDDEVISE", "UNITE", "TAUX") AS
SELECT bcc.ID,bcc.PRODUIT,bcc.IDBC,bcc.QUANTITE,bcc.PU,bcc.MONTANT,bcc.TVA,bcc.REMISE,bcc.IDDEVISE,bcc.UNITE, CASE WHEN 
  bcc.iddevise = 'AR' THEN 1 ELSE 
  tm.taux
  END AS taux 
  FROM BONDECOMMANDE_CLIENT_FILLE bcc,TAUXDECHANGE_MAXDATY tm 
  WHERE bcc.IDDEVISE = tm.IDDEVISE (+);

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."BONDECOMMANDE_CLIENT_CPL" ("ID", "DATY", "ETAT", "REMARQUE", "DESIGNATION", "MODEPAIEMENT", "MODEPAIEMENTLIB", "IDCLIENT", "IDCLIENTLIB", "REFERENCE", "IDMAGASINLIB", "ETATLIB", "IDPROFORMA", "NBFACTURE", "MODELIVRAISONLIB", "DATELIVRAISON", "LIEULIVRAISON", "NUMEROBC", "FRAISLIVRAISON") AS
SELECT
    bc.ID,
    bc.DATY,
    bc.ETAT,
    bc.REMARQUE,
    bc.DESIGNATION,
    bc.MODEPAIEMENT,
    m.VAL AS MODEPAIEMENTLIB,
    bc.IDCLIENT,
    c.NOM AS IDCLIENTLIB,
    bc.REFERENCE,
    m2.VAL AS IDMAGASINLIB,
    CASE
        WHEN bc.ETAT = 0 THEN '<span style=color: green;>ANNUL&Eacute;</span>'
        WHEN bc.ETAT = 1 THEN '<span style=color: green;>CR&Eacute;&Eacute;</span>'
        WHEN bc.ETAT = 11 THEN '<span style=color: green;>VALID&Eacute;</span>'
        END AS ETATLIB,
    bc.IDPROFORMA,
    nvl(vo.nombre,0) as nbfacture,
    CASE
        WHEN bc.modelivraison = 1 THEN '<span style=color: green;>LIVRAISON</span>'
        WHEN bc.modelivraison = 2 THEN '<span style=color: green;>RECUPERATION</span>'
        END AS modelivraisonlib,
    bc.dateLivraison,
    bc.lieuLivraison,
    bc.NUMEROBC,
    FRAISLIVRAISON
FROM BONDECOMMANDE_CLIENT bc
         LEFT JOIN CLIENT c ON c.id = bc.IDCLIENT
         LEFT JOIN MODEPAIEMENT m ON m.id = bc.MODEPAIEMENT
         LEFT JOIN MAGASIN2 m2 ON m2.id = bc.IDMAGASIN
         left join vente_origine vo on vo.IDORIGINE=bc.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."BONDECOMMANDE_CLIENT_CPL_A" ("ID", "DATY", "ETAT", "REMARQUE", "DESIGNATION", "MODEPAIEMENT", "MODEPAIEMENTLIB", "IDCLIENT", "IDCLIENTLIB", "REFERENCE", "ETATLIB") AS
SELECT "ID","DATY","ETAT","REMARQUE","DESIGNATION","MODEPAIEMENT","MODEPAIEMENTLIB","IDCLIENT","IDCLIENTLIB","REFERENCE","ETATLIB" FROM BONDECOMMANDE_CLIENT_CPL WHERE etat=0;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."BONDECOMMANDE_CLIENT_CPL_C" ("ID", "DATY", "ETAT", "REMARQUE", "DESIGNATION", "MODEPAIEMENT", "MODEPAIEMENTLIB", "IDCLIENT", "IDCLIENTLIB", "REFERENCE", "ETATLIB") AS
SELECT "ID","DATY","ETAT","REMARQUE","DESIGNATION","MODEPAIEMENT","MODEPAIEMENTLIB","IDCLIENT","IDCLIENTLIB","REFERENCE","ETATLIB" FROM BONDECOMMANDE_CLIENT_CPL WHERE etat=1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."BONDECOMMANDE_CLIENT_CPL_M" ("ID", "DATY", "ETAT", "REMARQUE", "DESIGNATION", "MODEPAIEMENT", "MODEPAIEMENTLIB", "IDCLIENT", "IDCLIENTLIB", "REFERENCE", "IDMAGASINLIB", "ETATLIB", "IDPROFORMA", "NBFACTURE", "MODELIVRAISONLIB", "DATELIVRAISON", "LIEULIVRAISON", "NUMEROBC", "QTERESTE", "MONTANTTTC", "MONTANTTTCAR", "FACTURELIB", "MOTSCLESSS", "IDMAGASIN", "MONTANTHT", "MONTANTREMISE", "MONTANTTVA", "IDDEVISE") AS
SELECT BC.ID,
       BC.DATY,
       CASE
           WHEN (SUM(BCF.QTERESTE)) = 0 THEN 12
           ELSE BC.ETAT
           END           AS ETAT,
       BC.REMARQUE,
       BC.DESIGNATION,
       BC.MODEPAIEMENT,
       M.VAL             AS MODEPAIEMENTLIB,
       BC.IDCLIENT,
       C.NOM             AS IDCLIENTLIB,
       BC.REFERENCE,
       M2.VAL            AS IDMAGASINLIB,
       CASE
           WHEN (SUM(BCF.QTERESTE)) = 0 THEN '<span style=color: green;>Valid&eacute;e</span>'
           WHEN BC.ETAT = 0 THEN '<span style=color: green;>Annul&eacute;e</span>'
           WHEN BC.ETAT = 1 THEN '<span style=color: green;>Cr&eacute;&eacute;</span>'
           WHEN BC.ETAT = 11 THEN '<span style=color: green;>Valid&eacute;e</span>'
           WHEN BC.ETAT = 12 THEN '<span style=color: green;>Valid&eacute;e</span>'
           END           AS ETATLIB,
       BC.IDPROFORMA,
       NVL(VO.NOMBRE, 0) AS NBFACTURE,
       CASE
           WHEN BC.MODELIVRAISON = 1 THEN '<span style=color: green;>LIVRAISON</span>'
           WHEN BC.MODELIVRAISON = 2 THEN '<span style=color: green;>R&Eacute;CUP&Eacute;RATION</span>'
           END           AS MODELIVRAISONLIB,
       BC.DATELIVRAISON,
       BC.LIEULIVRAISON,
       BC.NUMEROBC,
       SUM(BCF.QTERESTE) AS QTERESTE, sum(BCF.MONTANTTTC) as montantTTC,sum(BCF.MONTANTTTCAR) as montantTTCAR,
       CASE
           WHEN NVL(VO.NOMBRE, 0) > 0 THEN '<span style=color: green;>FACTUR&Eacute;</span>'
           WHEN NVL(VO.NOMBRE, 0) = 0 THEN '<span style=color: red;>NON FACTUR&Eacute;</span>'
           END           AS FACTURELIB,
       (
           BC.id || ' | ' ||  C.NOM  || ' | ' || designation || ' | ' || reference || ' | ' || M.VAL || ' | ' || BC.remarque || ' | ' || numeroBc
           )             AS MOTSCLESSS,
       BC.IDMAGASIN,
       cast(sum(bcf.montantremise) as number(30,2)) as montantHT,
       cast(sum(bcf.montantdelaremise) as number(30,2)) as montantremise,cast(sum(bcf.MONTANTTVA) as number(30,2)) as MONTANTTVA,
       bc.IDDEVISE
FROM BONDECOMMANDE_CLIENT BC
         LEFT JOIN CLIENT C ON C.ID = BC.IDCLIENT
         LEFT JOIN MODEPAIEMENT M ON M.ID = BC.MODEPAIEMENT
         LEFT JOIN MAGASIN2 M2 ON M2.ID = BC.IDMAGASIN
         LEFT JOIN VENTE_ORIGINE VO ON VO.IDORIGINE = BC.ID
         LEFT JOIN BC_CLIENT_FILLE_CPL_LIB2 BCF ON BCF.IDBC = BC.ID
GROUP BY BC.ID,
         BC.DATY,
         BC.ETAT,
         BC.REMARQUE,
         BC.DESIGNATION,
         BC.MODEPAIEMENT,
         M.VAL,
         BC.IDCLIENT,
         C.NOM,
         BC.REFERENCE,
         M2.VAL,
         BC.IDPROFORMA,
         VO.NOMBRE,
         BC.DATELIVRAISON,
         BC.LIEULIVRAISON,
         BC.NUMEROBC,
         BC.MODELIVRAISON, BC.IDMAGASIN, bc.IDDEVISE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."BONDECOMMANDE_CLIENT_CPL_V" ("ID", "DATY", "ETAT", "REMARQUE", "DESIGNATION", "MODEPAIEMENT", "MODEPAIEMENTLIB", "IDCLIENT", "IDCLIENTLIB", "REFERENCE", "ETATLIB") AS
SELECT "ID","DATY","ETAT","REMARQUE","DESIGNATION","MODEPAIEMENT","MODEPAIEMENTLIB","IDCLIENT","IDCLIENTLIB","REFERENCE","ETATLIB" FROM BONDECOMMANDE_CLIENT_CPL WHERE etat=11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."BONDECOMMANDE_CLIENT_FILLE_CPL" ("ID", "IDBC", "IDDEVISE", "MONTANT", "PRODUIT", "PU", "QUANTITE", "REMISE", "TVA", "UNITE", "QTEOF", "QTEOFRESTANTE", "QTEFAB", "QTEFABRESTANTE", "QTELIVRE", "QTENONLIVRE", "LIBELLEPRODUIT", "ETAT", "DATY", "IDCLIENT", "MOTSCLESSS") AS
SELECT SQ."ID",SQ."IDBC",SQ."IDDEVISE",SQ."MONTANT",SQ."PRODUIT",SQ."PU",SQ."QUANTITE",SQ."REMISE",SQ."TVA",SQ."UNITE",SQ."QTEOF",SQ."QTEOFRESTANTE",SQ."QTEFAB",SQ."QTEFABRESTANTE",SQ."QTELIVRE",SQ."QTENONLIVRE",SQ."LIBELLEPRODUIT",SQ."ETAT",SQ."DATY",SQ."IDCLIENT",
       (NVL(TO_CHAR("ID"),'') || ' | ' || NVL(TO_CHAR(IDBC),'') || ' | ' || NVL(TO_CHAR(IDDEVISE),'') || ' | ' || NVL(TO_CHAR(MONTANT),'') || ' | ' || NVL(TO_CHAR(PRODUIT),'') || ' | ' || NVL(TO_CHAR(PU),'') || ' | ' || NVL(TO_CHAR(QUANTITE),'') || ' | ' || NVL(TO_CHAR(REMISE),'') || ' | ' || NVL(TO_CHAR(TVA),'') || ' | ' || NVL(TO_CHAR(UNITE),'') || ' | ' || NVL(TO_CHAR(QTEOF),'') || ' | ' || NVL(TO_CHAR(QTEOFRESTANTE),'') || ' | ' || NVL(TO_CHAR(QTEFAB),'') || ' | ' || NVL(TO_CHAR(QTEFABRESTANTE),'') || ' | ' || NVL(TO_CHAR(QTELIVRE),'') || ' | ' || NVL(TO_CHAR(QTENONLIVRE),'') || ' | ' || NVL(TO_CHAR(LIBELLEPRODUIT),'')) AS MOTSCLESSS
FROM (
         SELECT
             bcf.id,
             bcf.IDBC,
             bcf.IDDEVISE,
             avg(bcf.MONTANT) as montant,
             bcf.PRODUIT,
             avg(bcf.PU) as pu,
             avg(bcf.QUANTITE) as quantite,
             avg(bcf.REMISE) as remise,
             avg(bcf.TVA) as tva,
             ing.UNITE as unite,

             nvl(avg(o.QTE),0) AS QTEOF,
             NVL(sum(bcf.QUANTITE) - nvl(avg(o.QTE),0), 0) AS QTEOFRESTANTE,

             nvl(avg(f.QTE),0) AS QTEFAB,
             NVL(sum(bcf.QUANTITE) - nvl(avg(f.QTE),0), 0) AS QTEFABRESTANTE,

             AVG(NVL(abcf.QUANTITE, 0)) AS QTELIVRE,
             NVL(avg(bcf.QUANTITE) - AVG(NVL(abcf.QUANTITE,0)), 0) AS QTENONLIVRE,
             ing.LIBELLE as libelleProduit,
             bccli.ETAT,
             bccli.daty,
             bccli.idclient

         FROM BONDECOMMANDE_CLIENT_FILLE bcf



                  LEFT JOIN BONDECOMMANDE_CLIENT bccli ON bccli.id = bcf.IDBC
                  LEFT JOIN OfGroupByIdbc o ON o.IDBCFILLE = bcf.ID


                  LEFT JOIN fabrGroupByIdbc f ON f.IDBCFILLE = bcf.ID

                  LEFT JOIN BLGroupByIdbc abcf ON abcf.IDBC_FILLE = bcf.ID

                  left join AS_INGREDIENTS ing on ing.id=bcf.PRODUIT

         GROUP BY
             bcf.IDBC,
             bcf.id,
             bcf.IDDEVISE,
             bcf.PRODUIT,
             ing.LIBELLE, ing.UNITE,
             bccli.ETAT,
             bccli.DATY,
             bccli.idclient
     ) SQ;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."BONDECOMMANDE_CLIENT_FILLE_V" ("ID", "PRODUIT", "IDBC", "QUANTITE", "PU", "MONTANT", "TVA", "REMISE", "IDDEVISE", "UNITE", "DESIGNATION", "UNITELIB", "PUNET", "MONTANTHT", "MONTANTTTC", "RISTOURNE", "CALORIE", "RISTOURNEARBIOCHEM", "REMISEARBIOCHEM") AS
select p.ID,
       p.PRODUIT,
       p.IDBC,
       p.QUANTITE,
       p.PU,
       p.MONTANT,
       p.TVA,
       p.REMISE,
       p.IDDEVISE,
       p.UNITE,
       p.DESIGNATION,
       uni.val as unitelib,
       0  as punet,
       0  as montantht,
       0  as montantttc,
       p.RISTOURNE,
       ing.calorie,
       p.ristourneArbiochem,
       p.remiseArbiochem
from BONDECOMMANDE_CLIENT_FILLE p
         LEFT JOIN as_unite uni ON p.unite = uni.id
         LEFT JOIN  AS_INGREDIENTS ing ON p.PRODUIT = ing.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."BONDECOMMANDE_CLIENT_GLOBALE" ("ID", "IDBC", "IDDEVISE", "MONTANT", "PRODUIT", "PU", "QUANTITE", "REMISE", "TVA", "UNITE", "QTEOF", "QTEOFRESTANTE", "QTEFAB", "QTEFABRESTANTE", "QTELIVRE", "QTENONLIVRE", "LIBELLEPRODUIT", "IDCLIENT", "IDCLIENTLIB", "DATY", "ETAT", "ETATLIB") AS
SELECT BCFC."ID",BCFC."IDBC",BCFC."IDDEVISE",BCFC."MONTANT",BCFC."PRODUIT",BCFC."PU",BCFC."QUANTITE",BCFC."REMISE",BCFC."TVA",BCFC."UNITE",BCFC."QTEOF",BCFC."QTEOFRESTANTE",BCFC."QTEFAB",BCFC."QTEFABRESTANTE",BCFC."QTELIVRE",BCFC."QTENONLIVRE",BCFC."LIBELLEPRODUIT",bc.IDCLIENT,bc.IDCLIENTLIB , bc.DATY,bc.ETAT , bc.ETATLIB  FROM 
	BONDECOMMANDE_CLIENT_FILLE_CPL bcfc
	JOIN BONDECOMMANDE_CLIENT_CPL bc ON bc.ID = BCFC.IDBC;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."BONDECOMMANDE_OFDETAILS" ("IDINGREDIENTS", "LIBELLEEXACTE", "IDBC", "QTE", "DATY") AS
SELECT off.IDINGREDIENTS,i.LIBELLEEXTACTE,bc.IDBC, sum(off.QTE) qte, o.DATY  FROM 
OFFILLE off 
LEFT JOIN BONDECOMMANDE_CLIENT_FILLE bc 
ON bc.ID = off.IDBCFILLE 
LEFT JOIN OFAB o 
ON o.ID = off.IDMERE 
JOIN AS_INGREDIENTS i
ON off.IDINGREDIENTS = i.ID 
WHERE o.ETAT >= 11
GROUP BY off.IDINGREDIENTS,i.LIBELLEEXTACTE,bc.IDBC,o.DATY;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."BUDGET_DEPENSE_SUM_VIEW" ("COMPTE", "MOIS", "ANNEE", "MOISLIB", "DEPENSES", "IDSERVICELIB", "SERVICE") AS
select COMPTE,
	       mois,
	       annee,
	       moislib,
	       sum(debit) as depenses,
	       IDSERVICELIB,
	       SERVICE
	from PREVISION_CPL
	group by COMPTE, mois, annee, moislib, IDSERVICELIB, SERVICE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."BUDGET_DEPENSE_SUM_VIEW_BUDGET" ("COMPTE", "MOIS", "ANNEE", "MOISLIB", "DEPENSES", "IDSERVICELIB", "SERVICE") AS
SELECT "COMPTE","MOIS","ANNEE","MOISLIB","DEPENSES","IDSERVICELIB","SERVICE" FROM budget_depense_sum_view WHERE mois IS NOT NULL AND ANNEE IS NOT NULL;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."BUDGET_RECETTE_SUM_VIEW" ("COMPTE", "MOIS", "ANNEE", "MOISLIB", "DEPENSES", "IDSERVICELIB", "SERVICE") AS
SELECT SQ.COMPTE,
       SQ.MOIS,
       SQ.ANNEE,
       SQ.MOISLIB,
       SQ.DEPENSES,
       SQ.IDSERVICELIB,
       SQ.SERVICE
FROM (
    select COMPTE,
        mois,
        annee,
        moislib,
        sum(credit) as depenses,
        IDSERVICELIB,
        SERVICE
    from PREVISION_CPL
    where mois is not null and ANNEE is not null
    group by COMPTE, mois, annee, moislib, IDSERVICELIB, SERVICE
) SQ;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CAISSEBANQUE" ("ID", "VAL", "DESCE") AS
SELECT id,
       val,
       desce
FROM CAISSE
WHERE IDTYPECAISSE = 'TCA001'
    AND actif = 1
   OR id = 'CAIS001';

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CAISSECPL" ("ID", "VAL", "DESCE", "IDTYPECAISSE", "IDTYPECAISSELIB", "IDPOINT", "IDPOINTLIB", "IDPOMPISTE", "ETAT", "COMPTE", "ETATLIB", "IDCATEGORIECAISSE", "IDCATEGORIECAISSELIB", "IDMAGASIN", "IDMAGASINLIB", "MOTSCLESSS") AS
SELECT SQ.ID,SQ.VAL,SQ.DESCE,SQ.IDTYPECAISSE,SQ.IDTYPECAISSELIB,SQ.IDPOINT,SQ.IDPOINTLIB,SQ.IDPOMPISTE,SQ.ETAT,SQ.COMPTE,SQ.ETATLIB,SQ.IDCATEGORIECAISSE,SQ.IDCATEGORIECAISSELIB,SQ.IDMAGASIN,SQ.IDMAGASINLIB,
	       (NVL(TO_CHAR(ID),'') || ' | ' || NVL(TO_CHAR(VAL),'') || ' | ' || NVL(TO_CHAR(DESCE),'') || ' | ' || NVL(TO_CHAR(IDTYPECAISSE),'') || ' | ' || NVL(TO_CHAR(IDTYPECAISSELIB),'') || ' | ' || NVL(TO_CHAR(IDPOINT),'') || ' | ' || NVL(TO_CHAR(IDPOINTLIB),'') || ' | ' || NVL(TO_CHAR(IDPOMPISTE),'') || ' | ' || NVL(TO_CHAR(ETAT),'') || ' | ' || NVL(TO_CHAR(COMPTE),'') || ' | ' || NVL(TO_CHAR(ETATLIB),'') || ' | ' || NVL(TO_CHAR(IDCATEGORIECAISSE),'') || ' | ' || NVL(TO_CHAR(IDCATEGORIECAISSELIB),'') || ' | ' || NVL(TO_CHAR(IDMAGASIN),'') || ' | ' || NVL(TO_CHAR(IDMAGASINLIB),'')) AS MOTSCLESSS
	FROM (
	         SELECT c.ID,
	                c.VAL,
	                c.DESCE,
	                c.IDTYPECAISSE,
	                t.VAL   AS IDTYPECAISSELIB,
	                c.IDPOINT,
	                p.VAL   AS IDPOINTLIB,
	                c.IDPOMPISTE,
	                c.ETAT,
	                cop.LIBELLE||'('||cop.COMPTE||')' as compte ,
	                CASE
	                    WHEN c.ETAT = 0
	                        THEN 'ANNUL&Eacute;'
	                    WHEN c.ETAT = 1
	                        THEN 'CR&Eacute;&Eacute;'
	                    WHEN c.ETAT = 11
	                        THEN 'VIS&Eacute;'
	                    END AS ETATLIB,
	                c.idCategorieCaisse,
	                c2.VAL  AS idCategorieCaisseLib,
	                c.IDMAGASIN ,
	                m.val AS idMagasinLib
	         FROM CAISSE c
	                  LEFT JOIN TYPECAISSE t ON t.ID = c.IDTYPECAISSE
	                  LEFT JOIN POINT p ON p.ID = c.IDPOINT
	                  LEFT JOIN CATEGORIECAISSE c2 ON c2.ID = c.idCategorieCaisse
	                  LEFT JOIN COMPTA_COMPTE cop ON cop.COMPTE = c.COMPTE
	                  LEFT JOIN MAGASIN2 m ON m.ID =c.IDMAGASIN
	
	
	     ) SQ;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CAISSETRAITE" ("ID", "VAL", "DESCE") AS
select ID,VAL,DESCE from caisse where id = 'CAIS00000T00016';

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CAISSE_POMPISTE" ("ID", "VAL", "DESCE", "IDTYPECAISSE", "IDTYPECAISSELIB", "IDPOINT", "IDPOINTLIB", "IDPOMPISTE", "ETAT", "ETATLIB", "IDCATEGORIECAISSE", "IDCATEGORIECAISSELIB") AS
SELECT 
c.ID ,
c.VAL ,
c.DESCE ,
c.IDTYPECAISSE ,
t.VAL AS IDTYPECAISSELIB,
c.IDPOINT ,
p.VAL AS IDPOINTLIB,
c.IDPOMPISTE ,
c.ETAT ,
CASE 
	WHEN c.ETAT  = 0 
	THEN 'ANNULEE'
	WHEN c.ETAT  = 1 
	THEN 'CREE'
	WHEN c.ETAT  = 11
	THEN 'VISEE'
END AS ETATLIB,
c.idCategorieCaisse,
c2.VAL AS idCategorieCaisseLib
FROM CAISSE c 
LEFT JOIN TYPECAISSE t ON t.ID = c.IDTYPECAISSE 
LEFT JOIN POINT p ON p.ID = c.IDPOINT 
LEFT JOIN CATEGORIECAISSE c2 ON c2.ID = c.idCategorieCaisse
WHERE c.IDPOMPISTE IS NOT NULL;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CANDIDATURESLIB" ("ID", "IDCANDIDAT", "IDCANDIDATLIB", "IDOFFREEMPLOIE", "IDOFFREEMPLOIELIB", "ETAT", "ETATLIB", "DATEAPPLICATION", "REMARQUE", "RAISONREFUS") AS
SELECT
    c.id,
    c.idCandidat,
    (ca.nom || ' ' || ca.prenom) AS idCandidatlib,
    c.idOffreEmploie,
    o.titre AS idOffreEmploielib,
    c.etat,
    CASE
        WHEN c.etat = 1 THEN 'Creee'
        WHEN c.etat = 11 THEN 'Validee'
        WHEN c.etat = 13 THEN 'Embauchee'
        WHEN c.etat = -1 THEN 'Refuser'
        ELSE 'Inconnu'
        END AS etatlib,
    c.dateApplication,
    c.remarque,
    c.raisonRefus
FROM candidatures c
         LEFT JOIN candidat ca
                   ON c.idCandidat = ca.id
         LEFT JOIN offre_emploi o
                   ON c.idOffreEmploie = o.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CARTONFILLE_CPL" ("ID", "IDMERE", "IDINGREDIENT", "QUANTITE", "REMARQUE", "IDBCFILLE", "PRODUITLIB", "IDBC") AS
select cf.ID,
 		cf.IDMERE,
 		cf.IDINGREDIENT,
 		cf.QUANTITE,
 		cf.REMARQUE,
 		cf.IDBCFILLE,
 		ai.libelle AS PRODUITLIB,
		c.IDBC AS IDBC
       from CARTONFILLE cf 
   LEFT JOIN AS_INGREDIENTS ai ON cf.IDINGREDIENT = ai.ID
   LEFT JOIN CARTON c ON cf.IDMERE = c.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CATEGORIEINGREDIENTLIB" ("ID", "VAL", "DESCE") AS
select cat.id,cat.val,ti.val as DESCE from CATEGORIEINGREDIENT cat
left join typeCATEGORIEINGREDIENT ti on cat.DESCE=ti.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CATEGORIEINGREDIENTLIB_ACHT" ("ID", "VAL", "DESCE") AS
SELECT
	cat.id,
	cat.val,
	cat.desce
FROM
	CATEGORIEINGREDIENT cat
	WHERE estachat=1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CATEGORIEINGREDIENT_ACTIF" ("ID", "VAL", "DESCE", "ESTACHAT", "ACTIF") AS
select "ID","VAL","DESCE","ESTACHAT","ACTIF" from CATEGORIEINGREDIENT where ACTIF=1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CATEGORIELIB" ("ID", "VAL", "DESCE", "IDTYPEPRODUIT", "IDTYPEPRODUITLIB") AS
(
SELECT
	c.ID AS id,
	c.VAL AS VAL,
	c.DESCE AS DESCE,
	c.IDTYPEPRODUIT AS IDTYPEPRODUIT,
	tp.VAL AS IDTYPEPRODUITLIB 
FROM CATEGORIEINGREDIENT c
LEFT JOIN TYPE_PRODUIT tp ON tp.id=c.IDTYPEPRODUIT 
);

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CATEGORIEQUALIFICATION_LIB" ("ID", "MATRICULE", "NOMPERSONNEL", "MONTANT", "CATEGORIELIB", "QUALIFICATIONLIB") AS
SELECT
	    log.id,
	    log.MATRICULE,
	    log.nom || ' ' || log.prenom as nomPersonnel,
	    c.MONTANT,
	    cp.val as categorieLib,
	    qp.val as qualificationLib
	FROM LOG_PERSONNEL_FIN log
	         LEFT JOIN CATEGORIE_QUALIFICATION c
	                   ON c.IDQUALIFICATION = log.IDQUALIFICATION
	                       AND c.IDCATEGORIE = log.IDCATEGORIE_PAIE
	                       AND (
	                          (c.REMARQUE IS NULL)
	                              OR (c.REMARQUE = log.ID)
	                          ) AND c.etat = 1
	         LEFT JOIN CATEGORIE_PAIE cp ON cp.id = c.IDCATEGORIE
	         LEFT JOIN QUALIFICATION_PAIE qp ON qp.id = c.IDQUALIFICATION;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CATEGORIE_PAIE_LIB" ("ID", "VAL", "DESCE", "MONTANT", "REMARQUE", "DROIT_HEURE_SUP", "ESSAIE") AS
SELECT cp.id,
       cp.val,
       cp.desce,
       cp.montant,
       cp.remarque,
       CASE
           WHEN cp.droit_heure_sup = 'o' THEN 'OUI'
           WHEN cp.droit_heure_sup = 'n' THEN 'NON'
           ELSE NULL
           END AS droit_heure_sup,
       cp.essaie
FROM categorie_paie cp;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CATEGORIE_PAIE_SALAIRE" ("ID", "VAL", "DESCE", "MONTANT", "REMARQUE", "DROIT_HEURE_SUP", "ESSAIE") AS
SELECT ID,VAL,DESCE,MONTANT,REMARQUE,DROIT_HEURE_SUP,ESSAIE FROM CATEGORIE_PAIE cp WHERE id in('CP0000010','CP0000011');

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CATEGORIE_QUALIFICATION_LIBC" ("ID", "IDCATEGORIE", "IDQUALIFICATION", "REMARQUE", "ETAT", "MONTANT", "IDCATEGORIELIB", "CATEGORIE_QUALIFICATIONLIB") AS
SELECT
    cq.id,
    cq.idcategorie,
    cq.idqualification,
    cq.remarque,
    cq.etat,
    cq.montant,
    cp.val AS idcategorielib,
    qp.val AS categorie_qualificationlib
FROM categorie_qualification cq
         JOIN qualification_paie qp ON TO_CHAR(qp.id) = TO_CHAR(cq.idqualification)
         JOIN categorie_paie cp ON TO_CHAR(cp.id) = TO_CHAR(cq.idcategorie);

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CATEGORIE_QUALIFICATION_VW" ("ID", "IDCATEGORIE", "IDQUALIFICATION", "REMARQUE", "ETAT", "MONTANT", "DATE_DEBUT", "DATE_FIN", "AVENANT", "IDPOSTE", "INDICE", "CATEGORIELIB", "QUALIFICATIONLIB", "ETATLIB") AS
SELECT
    cq."ID",cq."IDCATEGORIE",cq."IDQUALIFICATION",cq."REMARQUE",cq."ETAT",cq."MONTANT",cq."DATE_DEBUT",cq."DATE_FIN",cq."AVENANT",cq."IDPOSTE",cq."INDICE",
    cp.val AS categorieLib,
    qual.val AS qualificationLib,
    CASE
        WHEN cq.etat = 1 THEN 'ACTIF'
        WHEN cq.etat = -1 THEN 'INACTIF'
        ELSE 'INCONNU'
    END AS etatLib
FROM CATEGORIE_QUALIFICATION cq
LEFT JOIN CATEGORIE_PAIE cp
    ON cp.id = cq.idcategorie
LEFT JOIN QUALIFICATION_PAIE qual
    ON cq.idqualification = qual.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CATEG_QUALILIBCOMPLET" ("ID", "IDCATEGORIE", "IDQUALIFICATION", "REMARQUE", "ETAT", "MONTANT", "ETATLIBELLE", "ETATVAL", "MATRICULE", "DATE_DEBUT", "DATE_FIN", "NOMCPL", "PRENOM") AS
SELECT cq.id,
       cp.val AS idcategorie,
       qp.val AS idqualification,
       cq.remarque,
       cq.etat,
       cq.montant,
       CASE
           WHEN cq.etat = 1 THEN 'actif'
           ELSE 'inactif'
           END AS etatlibelle,
       ecq.desce AS etatval,
       vim.matricule,
       cq.date_debut,
       cq.date_fin,
       vim.NOM || vim.PRENOM AS nomCpl,
       vim.PRENOM
FROM categorie_qualification cq
         JOIN categorie_paie cp ON cp.id = cq.idcategorie
         JOIN qualification_paie qp ON qp.id = cq.idqualification
         JOIN etat_categ_qualif2 ecq ON ecq.id = cq.etat
         LEFT JOIN vue_id_matricule vim ON vim.id = cq.remarque;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CATEG_QUALI_CONTRAT" ("ID", "IDCATEGORIE", "IDQUALIFICATION", "REMARQUE", "ETAT", "MONTANT", "DATE_DEBUT", "DATE_FIN", "AVENANT") AS
SELECT cq.id,
       cq.idcategorie,
       cq.idqualification,
       cq.remarque,
       cq.etat,
       cq.montant,
       cq.date_debut,
       cq.date_fin,
       cq.avenant
FROM categorie_qualification cq
WHERE cq.avenant >=0 AND cq.remarque IS NOT NULL;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CATEG_QUALI_CONTRAT_2" ("ID", "IDCATEGORIE", "IDQUALIFICATION", "REMARQUE", "ETAT", "MONTANT", "DATE_DEBUT", "DATE_FIN", "DATEFIN", "AVENANT", "NUMERO") AS
SELECT
    cq.id,
    cq.idcategorie,
    cq.idqualification,
    cq.remarque,
    cq.etat,
    cq.montant,
    cq.date_debut,
    cq.date_fin,

    -- Utilisation de LEAD pour datefin
    NVL(
            LEAD(cq.date_debut) OVER (PARTITION BY cq.remarque ORDER BY cq.date_debut) - 1,
            cq.date_fin
    ) AS datefin,

    -- Generation de l''avenant
    CASE
        WHEN ROW_NUMBER() OVER (PARTITION BY cq.remarque ORDER BY cq.date_debut) = 1 THEN 'initial'
        ELSE 'Avenant N?' || (ROW_NUMBER() OVER (PARTITION BY cq.remarque ORDER BY cq.date_debut) - 1)
        END AS avenant,

    -- Numero de l''avenant
    CASE
        WHEN ROW_NUMBER() OVER (PARTITION BY cq.remarque ORDER BY cq.date_debut) = 1 THEN '0'
        ELSE TO_CHAR(ROW_NUMBER() OVER (PARTITION BY cq.remarque ORDER BY cq.date_debut) - 1)
        END AS numero

FROM categ_quali_contrat cq;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CATEG_QUALI_LIBCOMPLET" ("ID", "IDCATEGORIE", "IDQUALIFICATION", "REMARQUE", "ETAT", "MONTANT", "IDCATEGORIELIB", "CATEGORIE_QUALIFICATIONLIB") AS
SELECT cq.id,
       cq.idcategorie,
       cq.idqualification,
       cq.remarque,
       cq.etat,
       cq.montant,
       cp.val AS idcategorielib,
       qp.val AS categorie_qualificationlib
FROM categorie_qualification cq
         JOIN qualification_paie qp ON qp.id = cq.idqualification
         JOIN categorie_paie cp ON cq.idcategorie = cp.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CA_ANNEE_MOIS" ("ANNEE", "JANVIER", "FEVRIER", "MARS", "AVRIL", "MAI", "JUIN", "JUILLET", "AOUT", "SEPTEMBRE", "OCTOBRE", "NOVEMBRE", "DECEMBRE") AS
SELECT
    annee,
    SUM(CASE WHEN mois = 1 THEN montant ELSE 0 END) AS janvier,
    SUM(CASE WHEN mois = 2 THEN montant ELSE 0 END) AS fevrier,
    SUM(CASE WHEN mois = 3 THEN montant ELSE 0 END) AS mars,
    SUM(CASE WHEN mois = 4 THEN montant ELSE 0 END) AS avril,
    SUM(CASE WHEN mois = 5 THEN montant ELSE 0 END) AS mai,
    SUM(CASE WHEN mois = 6 THEN montant ELSE 0 END) AS juin,
    SUM(CASE WHEN mois = 7 THEN montant ELSE 0 END) AS juillet,
    SUM(CASE WHEN mois = 8 THEN montant ELSE 0 END) AS aout,
    SUM(CASE WHEN mois = 9 THEN montant ELSE 0 END) AS septembre,
    SUM(CASE WHEN mois = 10 THEN montant ELSE 0 END) AS octobre,
    SUM(CASE WHEN mois = 11 THEN montant ELSE 0 END) AS novembre,
    SUM(CASE WHEN mois = 12 THEN montant ELSE 0 END) AS decembre
FROM CA_ANNEE_VIEW
GROUP BY annee
ORDER BY annee;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CA_ANNEE_VIEW" ("MONTANT", "ANNEE", "MOIS") AS
WITH deja AS (
  SELECT
    SUM(montant) AS montant,
    TO_NUMBER(annee) AS annee,
    TO_NUMBER(mois)  AS mois
  FROM ca_annee_anterieur
  GROUP BY TO_NUMBER(annee), TO_NUMBER(mois)
),
recalc AS (
  SELECT
    EXTRACT(YEAR  FROM daty) AS annee,
    EXTRACT(MONTH FROM daty) AS mois,
    SUM(putotal) AS montant
  FROM vente_details_cpl_2_visee
  GROUP BY EXTRACT(YEAR  FROM daty), EXTRACT(MONTH FROM daty)
),
manquants AS (
  SELECT r.montant, r.annee, r.mois
  FROM recalc r
  WHERE NOT EXISTS (
    SELECT 1
    FROM deja d
    WHERE d.annee = r.annee
      AND d.mois  = r.mois
  )
)
SELECT montant, annee, mois FROM deja
UNION ALL
SELECT montant, annee, mois FROM manquants;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CA_JOURNALIER" ("MONTANT", "ANNEE", "MOIS", "MOISLIB", "DATY") AS
WITH agg AS (
  SELECT
    TRUNC(daty) AS jour,
    SUM(putotal) AS montant
  FROM vente_details_cpl_2_visee
  GROUP BY TRUNC(daty)
)
SELECT
    a.montant,
    EXTRACT(YEAR  FROM a.jour) AS annee,
    EXTRACT(MONTH FROM a.jour) AS mois,
    TO_CHAR(a.jour, 'Month', 'NLS_DATE_LANGUAGE=FRENCH') AS moislib,
    a.jour AS daty
FROM agg a
WHERE NOT EXISTS (
    SELECT 1
    FROM ca_jour j
    WHERE j.daty = a.jour
);

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CA_JOURNALIER_UNION" ("MONTANT", "ANNEE", "MOIS", "DATY") AS
select cj.MONTANT,
       cj.ANNEE,
       cj.MOIS,
       cj.DATY
from ca_jour cj
union all
select cj.montant, annee, mois, daty
from ca_journalier cj;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CA_JOURNALIER_UNION_GP" ("MONTANT", "ANNEE", "MOIS", "DATY") AS
select sum(montant) as montant, annee, mois, daty from ca_journalier_union group by annee, mois, daty;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CA_JOUR_DETAILS" ("DATY", "JOUR", "SEMAINEMOIS", "MOIS", "ANNEE", "JOURLIB", "MONTANT", "IDJOURSEMAINE", "NUMEROJOURSEMAINE") AS
select vj2n.DATY,
       vj2n.JOUR,
       vj2n.semainemois,
       vj2n.MOIS,
       vj2n.ANNEE,
       vj2n.JOURLIB,
       cast(nvl(cj.MONTANT, 0) as number(38, 2)) as montant,
       js.id as idjoursemaine,
       vj2n.numerojoursemaine
from V_JOURS_2016_now vj2n
         left join ca_journalier_union_gp cj on cj.DATY = vj2n.DATY
         left join joursemaine js on js.numsemaine = vj2n.semainemois and js.numjour = vj2n.numerojoursemaine;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CA_JOUR_DETAILS_CA" ("DATY", "JOUR", "SEMAINEMOIS", "MOIS", "ANNEE", "JOURLIB", "MONTANT", "IDJOURSEMAINE", "NUMEROJOURSEMAINE") AS
select vj2n.DATY,
       vj2n.JOUR,
       vj2n.semainemois,
       vj2n.MOIS,
       vj2n.ANNEE,
       vj2n.JOURLIB,
       cast(nvl(cj.MONTANT, 0) as number(38, 2)) as montant,
       js.id as idjoursemaine,
       vj2n.numerojoursemaine
from V_JOURS_2016_now vj2n
         left join Ventecpljour cj on cj.DATY = vj2n.DATY
         left join joursemaine js on js.numsemaine = vj2n.semainemois and js.numjour = vj2n.numerojoursemaine;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CA_JOUR_DETAILS_CA_V2" ("DATY", "JOUR", "SEMAINEMOIS", "MOIS", "ANNEE", "JOURLIB", "MONTANT", "IDJOURSEMAINE", "NUMEROJOURSEMAINE", "IDPROVINCE", "PROVINCELIB") AS
select vj2n.DATY,
       vj2n.JOUR,
       vj2n.semainemois,
       vj2n.MOIS,
       vj2n.ANNEE,
       vj2n.JOURLIB,
       cast(nvl(cj.MONTANT, 0) as number(38, 2)) as montant,
       js.id as idjoursemaine,
       vj2n.numerojoursemaine,
       cj.idprovince,
       cj.provincelib
from V_JOURS_2016_now vj2n
         left join VENTECPLJOUR_V2 cj on cj.DATY = vj2n.DATY
         left join joursemaine js on js.numsemaine = vj2n.semainemois and js.numjour = vj2n.numerojoursemaine;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CA_MENSUEL" ("ANNEE", "MOIS", "MOISLIB", "MONTANT") AS
WITH agg AS (
  SELECT
    TRUNC(daty) AS jour,
    CAST(SUM(putotal) AS NUMBER(30,5))  AS montant
  FROM vente_details_cpl_2_visee
  GROUP BY TRUNC(daty)
),
agg_mois AS (
  SELECT
    EXTRACT(YEAR FROM jour)  AS annee,
    EXTRACT(MONTH FROM jour) AS mois,
    TO_CHAR(jour, 'Month', 'NLS_DATE_LANGUAGE=FRENCH') AS moislib,
    CAST(SUM(montant)AS NUMBER(30,5)) AS montant
  FROM agg
  GROUP BY
    EXTRACT(YEAR FROM jour),
    EXTRACT(MONTH FROM jour),
    TO_CHAR(jour, 'Month', 'NLS_DATE_LANGUAGE=FRENCH')
)
SELECT ANNEE,MOIS,MOISLIB,MONTANT
FROM agg_mois m
WHERE NOT EXISTS (
    SELECT 1
    FROM ca_jour j
    WHERE EXTRACT(YEAR  FROM j.daty) = m.annee
      AND EXTRACT(MONTH FROM j.daty) = m.mois
);

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CHARGEGROUPBYOFF" ("IDOFF", "MONTANTENTREE", "MONTANTSORTIE") AS
select ofile.id as idoff, cast(0 as number(30,3)) as montantentree,cast(nvl(sum(c.pu*c.qte),0) as number(30,3)) as montantsortie
from charge c
         left join fabrication fabb on c.IDFABRICATION=fabb.id
         left join OFFILLE ofile on fabb.IDOFFILLE=ofile.ID
where c.etat>=11 group by ofile.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CHARGEGROUPEBYOFF" ("IDOFF", "MONTANTENTREE", "MONTANTSORTIE") AS
SELECT ofile.id AS idoff , CAST(0 AS NUMBER(30,3)) AS montantentree  ,
cast(nvl(sum(c.pu*c.qte),0) AS NUMBER(30,3)) AS montantsortie FROM charge c
LEFT JOIN fabrication fabb ON c.IDFABRICATION=fabb.ID 
LEFT JOIN OFFILLE ofile ON fabb.IDoffilLe=ofile.id
WHERE c.etat>=11 GROUP BY OFILE.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CHARGEMONTANT" ("ID", "DATY", "LIBELLE", "PU", "TYPE", "IDFABRICATION", "ETAT", "IDINGREDIENTS", "QTE", "MONTANT") AS
SELECT c."ID",c."DATY",c."LIBELLE",c."PU",c."TYPE",c."IDFABRICATION",c."ETAT",c."IDINGREDIENTS",c."QTE", cast(c.pu * c.qte AS NUMBER(30,10)) AS montant FROM charge c;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CHARGEPERSONNEL_CPL" ("ID", "IDRESSPARFAB", "HEURENORMALE", "HS", "MN", "JF", "HD", "IF", "ETAT", "REMARQUE", "IDPERSONNE", "IDFABRICATION", "DATEFABRICATION", "ETATLIB", "IDPERSONNELIB", "MATRICULE", "TAUXHORAIRE", "TAUXHORAIREEFFECTIVE", "TEMPORAIRE", "MONTANTTOTAL", "IDQUALIFICATION", "VALEURJF", "VALEURHD", "VALEURIF", "VALEURMN", "VALEURHN", "VALEURHS", "IDDEPARTEMENT", "DEPARTEMENTLIB", "TH") AS
SELECT
    hs."ID",hs."IDRESSPARFAB",hs."HEURENORMALE",hs."HS",hs."MN",hs."JF",hs."HD",hs."IF",hs."ETAT",hs."REMARQUE",hs."IDPERSONNE",hs."IDFABRICATION",hs."DATEFABRICATION",hs."ETATLIB",hs."IDPERSONNELIB",hs."MATRICULE",hs."TAUXHORAIRE",hs."TAUXHORAIREEFFECTIVE",hs."TEMPORAIRE",hs."MONTANTTOTAL",hs."IDQUALIFICATION",hs."VALEURJF",hs."VALEURHD",hs."VALEURIF",hs."VALEURMN",hs."VALEURHN",hs."VALEURHS",hs."IDDEPARTEMENT",hs."DEPARTEMENTLIB",
    hs.TAUXHORAIRE as th

FROM HEURESUPFABRICATION_CPL_VISEE hs;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CHARGE_CPL" ("ID", "DATY", "LIBELLE", "PU", "QTE", "TYPE", "IDFABRICATION", "ETAT", "TYPELIB", "ETATLIB") AS
SELECT
	    c.ID,
	    c.DATY,
	    c.LIBELLE,
	    c.PU,
	    c.QTE,
	    c.TYPE,
	    c.IDFABRICATION,
	    c.ETAT,
	    t.val AS typelib,
	    CASE
	        WHEN c.ETAT = 0
	            THEN 'ANNULEE'
	        WHEN c.ETAT = 1
	            THEN 'CREEE'
	        WHEN c.ETAT = 11
	            THEN 'VISEE'
	        ELSE 'INCONNU'
	        END AS etatlib
	FROM
	    CHARGE c
	        LEFT JOIN TYPECHARGE t ON t.id = c.TYPE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CHARGE_CPL_A" ("ID", "DATY", "LIBELLE", "PU", "QTE", "TYPE", "IDFABRICATION", "ETAT", "TYPELIB", "ETATLIB") AS
SELECT 
"ID","DATY","LIBELLE","PU","QTE","TYPE","IDFABRICATION","ETAT","TYPELIB","ETATLIB" 
FROM CHARGE_CPL 
WHERE etat = 0;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CHARGE_CPL_C" ("ID", "DATY", "LIBELLE", "PU", "QTE", "TYPE", "IDFABRICATION", "ETAT", "TYPELIB", "ETATLIB") AS
SELECT 
"ID","DATY","LIBELLE","PU","QTE","TYPE","IDFABRICATION","ETAT","TYPELIB","ETATLIB" 
FROM CHARGE_CPL 
WHERE etat = 1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CHARGE_CPL_V" ("ID", "DATY", "LIBELLE", "PU", "QTE", "TYPE", "IDFABRICATION", "ETAT", "TYPELIB", "ETATLIB") AS
SELECT 
"ID","DATY","LIBELLE","PU","QTE","TYPE","IDFABRICATION","ETAT","TYPELIB","ETATLIB" 
FROM CHARGE_CPL 
WHERE etat = 11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CHARGE_LIB" ("ID", "DATY", "LIBELLE", "PU", "TYPE", "IDFABRICATION", "ETAT", "IDINGREDIENTS", "QTE", "IDOFFILLE", "IDOF", "MOTSCLESSS", "TYPECHARGELIB", "IDINGREDIENTSLIB", "MONTANT") AS
SELECT SQ.ID,SQ.DATY,SQ.LIBELLE,SQ.PU,SQ.TYPE,SQ.IDFABRICATION,SQ.ETAT,SQ.IDINGREDIENTS,SQ.QTE,SQ.IDOFFILLE,SQ.IDOF,
	  (NVL(TO_CHAR(ID),'') || ' | ' || NVL(TO_CHAR(DATY,'YYYY-MM-DD HH24:MI:SS'),'') || ' | ' || NVL(TO_CHAR(LIBELLE),'') || ' | ' || NVL(TO_CHAR(PU),'') || ' | ' || NVL(TO_CHAR(TYPE),'') || ' | ' || NVL(TO_CHAR(IDFABRICATION),'') || ' | ' || NVL(TO_CHAR(ETAT),'') || ' | ' || NVL(TO_CHAR(IDINGREDIENTS),'') || ' | ' || NVL(TO_CHAR(QTE),'') || ' | ' || NVL(TO_CHAR(IDOFFILLE),'') || ' | ' || NVL(TO_CHAR(IDOF),'')) AS MOTSCLESSS,typechargelib,idingredientslib,montant
	FROM (
	  SELECT 
	c.id ,
	c.daty ,
	c.libelle,
	c.pu ,
	c.type ,
	c.idfabrication,
	c.etat , 
	c.idingredients,
	c.qte ,
	f.IDOFFILLE,
	f.IDOF,
	tc.val AS typechargelib,
	ing.libelle AS idingredientslib,
	CAST(NVL(c.pu * c.qte, 0) AS NUMBER(30,2)) AS montant
	FROM CHARGE c 
	LEFT JOIN FABRICATION f ON f.id = c.idfabrication  
	LEFT JOIN typecharge tc ON c.TYPE=tc.id
	LEFT JOIN as_ingredients ing ON c.idingredients=ing.id 
	) SQ;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CHECKINAVECCHEKOUT" ("ID", "RESERVATION", "DATY", "HEURE", "REMARQUE", "CLIENT", "IDPRODUIT", "ETAT", "IDCLIENT", "QTE", "CHECKOUT") AS
select c."ID",c."RESERVATION",c."DATY",c."HEURE",c."REMARQUE",c."CLIENT",c."IDPRODUIT",c."ETAT",c."IDCLIENT", c.qte,o.id as checkOut from CHECKIN c left join CHECKOUT o on c.id=o.RESERVATION;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CHECKINAVECCHEKOUTCOMPLET" ("RESERVATION", "ID", "DATY", "ETAT", "HEURE", "REMARQUE", "CHECKOUT") AS
select c.RESERVATION ,o.id,o.DATY,o.ETAT,  o.HEURE,o.REMARQUE, o.RESERVATION as checkOut from CHECKIN c left join CHECKOUT o on c.id=o.RESERVATION;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CHECKINLIBELLE" ("ID", "RESERVATION", "DATY", "HEURE", "REMARQUE", "CLIENT", "IDPRODUIT", "ETAT", "IDCLIENT", "CHECKOUT", "PRODUITLIBELLE", "PU", "TVA", "ETATLIB") AS
SELECT
	c.ID,
	c.RESERVATION,
	c.DATY,
	c.HEURE,
	c.REMARQUE,
	cl.nom AS CLIENT,
	c.IDPRODUIT,
	c.ETAT,
	c.IDCLIENT,
	c.CHECKOUT,
	i.LIBELLE AS produitLibelle,
	i.pu,
	i.tva,
	CASE
	WHEN c.ETAT = 0
	THEN 'ANNULEE'
	WHEN c.ETAT = 1
	THEN 'CREE'
	WHEN c.ETAT = 11
	THEN 'VISEE'
END AS ETATLIB
FROM
	checkInAvecChekOut c
LEFT JOIN AS_INGREDIENTS i ON c.IDPRODUIT = i.id
LEFT JOIN CLIENT cl ON c.IDCLIENT=cl.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CHECKINSANSCHEKOUT" ("ID", "RESERVATION", "DATY", "HEURE", "REMARQUE", "CLIENT", "IDPRODUIT", "ETAT", "IDCLIENT") AS
select c."ID",c."RESERVATION",c."DATY",c."HEURE",c."REMARQUE",c."CLIENT",c."IDPRODUIT",c."ETAT",c."IDCLIENT" from CHECKIN c where c.id not in (select o.reservation from CHECKOUT o where o.ETAT>=11);

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CHECKINSANSCHEKOUTCPL" ("ID", "RESERVATION", "DATY", "HEURE", "REMARQUE", "CLIENT", "IDPRODUIT", "ETAT", "IDCLIENT", "CHAMBRE") AS
select
    ch."ID",ch."RESERVATION",ch."DATY",ch."HEURE",ch."REMARQUE",ch."CLIENT",ch."IDPRODUIT",ch."ETAT",ch."IDCLIENT",
    ing.LIBELLE as chambre
from CHECKINSANSCHEKOUT ch
         join AS_INGREDIENTS ing on ch.idproduit = ing.id
where ing.CATEGORIEINGREDIENT = 'CAT001';

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CHECKLIST_MERE_LIB" ("ID", "DATY", "IDPERSONNEL", "TYPECHECKLISTE", "TYPECHECKLISTELIB", "IDPERSONNELLIB", "MATRICULE", "IDFONCTION", "IDFONCTIONLIB", "IDSERVICE", "IDSERVICELIB", "IDDIRECTION", "IDDIRECTIONLIB") AS
SELECT cm.ID,
       cm.DATY,
       cm.IDPERSONNEL,
       cm.TYPECHECKLISTE,
       -- typeCheckListeLib (0 => entree, 1 => sortie)
       CASE cm.TYPECHECKLISTE
           WHEN 0 THEN 'entree'
           WHEN 1 THEN 'sortie'
           ELSE 'Inconnu'
           END AS typeCheckListeLib,
       -- idPersonnelLib : Nom + prenom depuis table log_personnel
       lp.NOM || ' ' || lp.PRENOM AS idPersonnelLib,
       -- Matricule et idFonction depuis paie_info_personnel
       pip.MATRICULE,
       pip.IDFONCTION,
       -- idFonctionLib : Recuperer val depuis table paie_fonction
       pf.VAL AS idFonctionLib,
       -- idService depuis log_personnel et idServiceLib depuis log_service
       lp.SERVICE AS idService,
       ls.LIBELLE AS idServiceLib,
       -- idDirection depuis log_personnel et idDirectionLib depuis log_direction
       lp.DIRECTION AS idDirection,
       ld.VAL AS idDirectionLib
FROM CHECKLIST_MERE cm
         LEFT JOIN LOG_PERSONNEL lp ON lp.ID = cm.IDPERSONNEL
         LEFT JOIN PAIE_INFO_PERSONNEL pip ON pip.ID = lp.ID
         LEFT JOIN PAIE_FONCTION pf ON pf.ID = pip.IDFONCTION
         LEFT JOIN LOG_SERVICE ls ON ls.ID = lp.SERVICE
         LEFT JOIN LOG_DIRECTION ld ON ld.ID = lp.DIRECTION;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CHECKOUTLIB" ("ID", "RESERVATION", "DATY", "HEURE", "REMARQUE", "ETAT", "PRODUITLIBELLE", "ETATLIB") AS
select
    ch."ID",ch."RESERVATION",ch."DATY",ch."HEURE",ch."REMARQUE",ch."ETAT",
    ci.PRODUITLIBELLE,
    case when ch.ETAT = 1 then 'CREE'
    when ch.ETAT = 11 then 'VALIDEE'
    END as etatlib
from CHECKOUT ch
join CHECKINLIBELLE ci on ci.ID = ch.RESERVATION;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CHEQUECPL" ("ID", "REFERENCE", "IDCAISSE", "IDCAISSELIB", "MONTANT", "DATY", "ETAT", "ETATLIB", "REMARQUE") AS
SELECT 
c.ID ,
c.REFERENCE ,
c.IDCAISSE ,
c2.VAL AS IDCAISSELIB,
c.MONTANT ,
c.DATY ,
c.ETAT ,
CASE 
	WHEN c.ETAT = 1 
	THEN 'CREE'
	WHEN c.ETAT = 11 
	THEN 'VALIDEE'
	WHEN c.ETAT = 20 
	THEN 'TOUCHEE'
END AS ETATLIB,
c.REMARQUE 
FROM CHEQUE c 
LEFT JOIN CAISSE c2 ON c2.ID = c.IDCAISSE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CHEQUECPL_CREE" ("ID", "REFERENCE", "IDCAISSE", "IDCAISSELIB", "MONTANT", "DATY", "ETAT", "ETATLIB", "REMARQUE") AS
SELECT 
c."ID",c."REFERENCE",c."IDCAISSE",c."IDCAISSELIB",c."MONTANT",c."DATY",c."ETAT",c."ETATLIB",c."REMARQUE"
FROM CHEQUECPL c 
WHERE c.ETAT = 1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CHEQUECPL_TOUCHEE" ("ID", "REFERENCE", "IDCAISSE", "IDCAISSELIB", "MONTANT", "DATY", "ETAT", "ETATLIB", "REMARQUE") AS
SELECT 
c."ID",c."REFERENCE",c."IDCAISSE",c."IDCAISSELIB",c."MONTANT",c."DATY",c."ETAT",c."ETATLIB",c."REMARQUE"
FROM CHEQUECPL c 
WHERE c.ETAT = 20;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CHEQUECPL_VISEE" ("ID", "REFERENCE", "IDCAISSE", "IDCAISSELIB", "MONTANT", "DATY", "ETAT", "ETATLIB", "REMARQUE") AS
SELECT 
c."ID",c."REFERENCE",c."IDCAISSE",c."IDCAISSELIB",c."MONTANT",c."DATY",c."ETAT",c."ETATLIB",c."REMARQUE"
FROM CHEQUECPL c 
WHERE c.ETAT = 11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CLIENTLIB" ("ID", "NOM", "TELEPHONE", "MAIL", "ADRESSE", "REMARQUE", "COMPTE", "IDNATIONALITE", "COMPTEAUXILIAIRE", "IDTYPECLIENT", "IDTYPECLIENTLIB", "CODECLIENT", "DATECARTE", "TAXE", "IDPROVINCE", "ECHEANCE", "TELFIXE", "NIF", "STAT", "CARTE", "PROVINCELIB", "SEUIL") AS
SELECT
    c.ID,c.NOM,c.TELEPHONE,c.MAIL,c.ADRESSE,c.REMARQUE,c.COMPTE,c.IDNATIONALITE,c.COMPTEAUXILIAIRE,c.IDTYPECLIENT,
    t.val AS idTypeClientLib,
    c.codeclient,c.datecarte,c.taxe,c.idprovince,c.echeance,c.telfixe,c.nif,c.stat,c.carte,p.val AS provincelib,
    c.SEUIL
FROM CLIENT c
LEFT JOIN typeclient t
ON c.idTypeClient = t.id
LEFT JOIN province p ON c.idprovince=p.id where ESTACTIF=1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CLIENT_ACTIF" ("ID", "NOM", "TELEPHONE", "MAIL", "ADRESSE", "REMARQUE", "COMPTE", "IDNATIONALITE", "COMPTEAUXILIAIRE", "IDTYPECLIENT", "IDPROVINCE", "ECHEANCE", "TELFIXE", "NIF", "STAT", "CARTE", "DATECARTE", "TAXE", "CODECLIENT") AS
select ID, NOM, TELEPHONE, MAIL, ADRESSE, REMARQUE, COMPTE, IDNATIONALITE, COMPTEAUXILIAIRE, IDTYPECLIENT, IDPROVINCE, ECHEANCE, TELFIXE, NIF, STAT, CARTE, DATECARTE, TAXE, CODECLIENT from Client where estactif = 1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CLOTURECAISSE_CPL" ("ID", "DATY", "REMARQUE", "ETAT", "IDPOINT", "IDPOINTLIB", "ETATLIB") AS
SELECT
    cc.ID,cc.DATY,cc.REMARQUE,cc.ETAT,cc.IDPOINT,
    p.val AS idpointlib,
    CASE
        WHEN cc.etat = 1 THEN 'CR&Eacute;&Eacute;E'
        WHEN cc.etat >= 11 THEN 'VIS&Eacute;E'
        ELSE 'AUTRE' end as etatLib
FROM CLOTURECAISSE cc
         LEFT JOIN POINT p ON cc.idPoint = p.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CNAPS_T1" ("IDPERSONNEL", "MATRICULE", "PERSONNEL", "PRENOM", "NUMERO_CNAPS", "DIRECTION", "DATEEMBAUCHE", "ANNEE", "MOIS1", "CNAPS_TRAVAILLEUR1", "CNAPS_EMPLOYEUR1", "MOIS2", "CNAPS_TRAVAILLEUR2", "CNAPS_EMPLOYEUR2", "MOIS3", "CNAPS_TRAVAILLEUR3", "CNAPS_EMPLOYEUR3", "COTISATION_TRAVAILLEUR", "COTISATION_EMPLOYEUR") AS
SELECT
    pec.idpersonnel,
    pipl.matricule,
    pipl.nom AS personnel,
    pipl.prenom as prenom,
    pipl.numero_cnaps,
    pipl.direction,
    pipl.dateembauche,
    pec.annee,

    NVL(s1.brut, 0) AS mois1,
    NVL(s1.cnaps_travailleur, 0) AS cnaps_travailleur1,
    NVL(s1.cnaps_employeur, 0) AS cnaps_employeur1,

    NVL(s2.brut, 0) AS mois2,
    NVL(s2.cnaps_travailleur, 0) AS cnaps_travailleur2,
    NVL(s2.cnaps_employeur, 0) AS cnaps_employeur2,

    NVL(s3.brut, 0) AS mois3,
    NVL(s3.cnaps_travailleur, 0) AS cnaps_travailleur3,
    NVL(s3.cnaps_employeur, 0) AS cnaps_employeur3,

    (NVL(s1.cnaps_travailleur, 0) + NVL(s2.cnaps_travailleur, 0) + NVL(s3.cnaps_travailleur, 0)) AS cotisation_travailleur,
    (NVL(s1.cnaps_employeur, 0) + NVL(s2.cnaps_employeur, 0) + NVL(s3.cnaps_employeur, 0)) AS cotisation_employeur

FROM
    paie_edition_cnaps pec
        JOIN paie_info_personnel_libcomplet pipl
             ON TO_CHAR(pipl.id) = TO_CHAR(pec.idpersonnel)
                 AND pec.mois IN (1, 2, 3)

        LEFT JOIN (
        SELECT idpersonnel, annee, brut, cnaps_travailleur, cnaps_employeur
        FROM paie_edition_cnaps
        WHERE mois = 1
    ) s1 ON TO_CHAR(pec.idpersonnel) = TO_CHAR(s1.idpersonnel) AND pec.annee = s1.annee

        LEFT JOIN (
        SELECT idpersonnel, annee, brut, cnaps_travailleur, cnaps_employeur
        FROM paie_edition_cnaps
        WHERE mois = 2
    ) s2 ON TO_CHAR(pec.idpersonnel) = TO_CHAR(s2.idpersonnel) AND pec.annee = s2.annee

        LEFT JOIN (
        SELECT idpersonnel, annee, brut, cnaps_travailleur, cnaps_employeur
        FROM paie_edition_cnaps
        WHERE mois = 3
    ) s3 ON TO_CHAR(pec.idpersonnel) = TO_CHAR(s3.idpersonnel) AND pec.annee = s3.annee

GROUP BY
    pec.idpersonnel, pipl.matricule, pipl.nom, pipl.prenom ,pipl.numero_cnaps, pipl.direction, pec.annee,
    s1.brut, s1.cnaps_travailleur, s1.cnaps_employeur, pipl.dateembauche,
    s2.brut, s2.cnaps_travailleur, s2.cnaps_employeur,
    s3.brut, s3.cnaps_travailleur, s3.cnaps_employeur;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CNAPS_T2" ("IDPERSONNEL", "MATRICULE", "PERSONNEL", "PRENOM", "NUMERO_CNAPS", "DATEEMBAUCHE", "DIRECTION", "ANNEE", "MOIS1", "CNAPS_TRAVAILLEUR1", "CNAPS_EMPLOYEUR1", "MOIS2", "CNAPS_TRAVAILLEUR2", "CNAPS_EMPLOYEUR2", "MOIS3", "CNAPS_TRAVAILLEUR3", "CNAPS_EMPLOYEUR3", "COTISATION_TRAVAILLEUR", "COTISATION_EMPLOYEUR") AS
SELECT
    pec.idpersonnel,
    pipl.matricule,
    pipl.nom AS personnel,
    pipl.prenom as prenom,
    pipl.numero_cnaps,
    pipl.dateembauche,
    pipl.direction,
    pec.annee,

    NVL(s1.brut, 0) AS mois1,
    NVL(s1.cnaps_travailleur, 0) AS cnaps_travailleur1,
    NVL(s1.cnaps_employeur, 0) AS cnaps_employeur1,

    NVL(s2.brut, 0) AS mois2,
    NVL(s2.cnaps_travailleur, 0) AS cnaps_travailleur2,
    NVL(s2.cnaps_employeur, 0) AS cnaps_employeur2,

    NVL(s3.brut, 0) AS mois3,
    NVL(s3.cnaps_travailleur, 0) AS cnaps_travailleur3,
    NVL(s3.cnaps_employeur, 0) AS cnaps_employeur3,

    ROUND(NVL(s1.cnaps_travailleur, 0) + NVL(s2.cnaps_travailleur, 0) + NVL(s3.cnaps_travailleur, 0), 2) AS cotisation_travailleur,
    ROUND(NVL(s1.cnaps_employeur, 0) + NVL(s2.cnaps_employeur, 0) + NVL(s3.cnaps_employeur, 0), 2) AS cotisation_employeur

FROM paie_edition_cnaps pec
         JOIN paie_info_personnel_libcomplet pipl
              ON pipl.id = pec.idpersonnel
                  AND pec.mois IN (4, 5, 6)

         LEFT JOIN (
    SELECT idpersonnel, mois, annee, brut, cnaps_travailleur, cnaps_employeur
    FROM paie_edition_cnaps
    WHERE mois = 4
) s1 ON pec.idpersonnel = s1.idpersonnel AND pec.annee = s1.annee

         LEFT JOIN (
    SELECT idpersonnel, mois, annee, brut, cnaps_travailleur, cnaps_employeur
    FROM paie_edition_cnaps
    WHERE mois = 5
) s2 ON pec.idpersonnel = s2.idpersonnel AND pec.annee = s2.annee

         LEFT JOIN (
    SELECT idpersonnel, mois, annee, brut, cnaps_travailleur, cnaps_employeur
    FROM paie_edition_cnaps
    WHERE mois = 6
) s3 ON pec.idpersonnel = s3.idpersonnel AND pec.annee = s3.annee

GROUP BY
    pec.idpersonnel, pipl.matricule, pipl.nom, pipl.numero_cnaps, pipl.prenom,    pipl.dateembauche,
    pipl.direction, pec.annee,
    s1.brut, s1.cnaps_travailleur, s1.cnaps_employeur,
    s2.brut, s2.cnaps_travailleur, s2.cnaps_employeur,
    s3.brut, s3.cnaps_travailleur, s3.cnaps_employeur;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CNAPS_T3" ("IDPERSONNEL", "MATRICULE", "PERSONNEL", "PRENOM", "NUMERO_CNAPS", "DATEEMBAUCHE", "DIRECTION", "ANNEE", "MOIS1", "CNAPS_TRAVAILLEUR1", "CNAPS_EMPLOYEUR1", "MOIS2", "CNAPS_TRAVAILLEUR2", "CNAPS_EMPLOYEUR2", "MOIS3", "CNAPS_TRAVAILLEUR3", "CNAPS_EMPLOYEUR3", "COTISATION_TRAVAILLEUR", "COTISATION_EMPLOYEUR") AS
SELECT
    pec.idpersonnel,
    pipl.matricule,
    pipl.nom AS personnel,
    pipl.prenom as prenom,
    pipl.numero_cnaps,
    pipl.dateembauche,
    pipl.direction,
    pec.annee,
    ROUND(NVL(s1.brut, 0), 2) AS mois1,
    ROUND(NVL(s1.cnaps_travailleur, 0), 2) AS cnaps_travailleur1,
    ROUND(NVL(s1.cnaps_employeur, 0), 2) AS cnaps_employeur1,
    ROUND(NVL(s2.brut, 0), 2) AS mois2,
    ROUND(NVL(s2.cnaps_travailleur, 0), 2) AS cnaps_travailleur2,
    ROUND(NVL(s2.cnaps_employeur, 0), 2) AS cnaps_employeur2,
    ROUND(NVL(s3.brut, 0), 2) AS mois3,
    ROUND(NVL(s3.cnaps_travailleur, 0), 2) AS cnaps_travailleur3,
    ROUND(NVL(s3.cnaps_employeur, 0), 2) AS cnaps_employeur3,
    ROUND(NVL(s1.cnaps_travailleur, 0) + NVL(s2.cnaps_travailleur, 0) + NVL(s3.cnaps_travailleur, 0), 2) AS cotisation_travailleur,
    ROUND(NVL(s1.cnaps_employeur, 0) + NVL(s2.cnaps_employeur, 0) + NVL(s3.cnaps_employeur, 0), 2) AS cotisation_employeur
FROM
    paie_edition_cnaps pec
        JOIN paie_info_personnel_libcomplet pipl ON pipl.id = pec.idpersonnel
        LEFT JOIN (
        SELECT idpersonnel, annee, brut, cnaps_travailleur, cnaps_employeur
        FROM paie_edition_cnaps
        WHERE mois = 7
    ) s1 ON pec.idpersonnel = s1.idpersonnel AND pec.annee = s1.annee
        LEFT JOIN (
        SELECT idpersonnel, annee, brut, cnaps_travailleur, cnaps_employeur
        FROM paie_edition_cnaps
        WHERE mois = 8
    ) s2 ON pec.idpersonnel = s2.idpersonnel AND pec.annee = s2.annee
        LEFT JOIN (
        SELECT idpersonnel, annee, brut, cnaps_travailleur, cnaps_employeur
        FROM paie_edition_cnaps
        WHERE mois = 9
    ) s3 ON pec.idpersonnel = s3.idpersonnel AND pec.annee = s3.annee
WHERE
    pec.mois IN (7, 8, 9)
GROUP BY
    pec.idpersonnel,
    pipl.matricule,
    pipl.nom,
    pipl.prenom,
    pipl.numero_cnaps,
    pipl.dateembauche,
    pipl.direction,
    pec.annee,
    s1.brut, s1.cnaps_travailleur, s1.cnaps_employeur,
    s2.brut, s2.cnaps_travailleur, s2.cnaps_employeur,
    s3.brut, s3.cnaps_travailleur, s3.cnaps_employeur;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CNAPS_T4" ("IDPERSONNEL", "MATRICULE", "PERSONNEL", "PRENOM", "NUMERO_CNAPS", "DATEEMBAUCHE", "DIRECTION", "ANNEE", "MOIS1", "CNAPS_TRAVAILLEUR1", "CNAPS_EMPLOYEUR1", "MOIS2", "CNAPS_TRAVAILLEUR2", "CNAPS_EMPLOYEUR2", "MOIS3", "CNAPS_TRAVAILLEUR3", "CNAPS_EMPLOYEUR3", "COTISATION_TRAVAILLEUR", "COTISATION_EMPLOYEUR") AS
SELECT
    pec.idpersonnel,
    pipl.matricule,
    pipl.nom AS personnel,
    pipl.prenom,
    pipl.numero_cnaps,
    pipl.dateembauche,
    pipl.direction,
    pec.annee,

    ROUND(NVL(s1.brut, 0), 2) AS mois1,
    ROUND(NVL(s1.cnaps_travailleur, 0), 2) AS cnaps_travailleur1,
    ROUND(NVL(s1.cnaps_employeur, 0), 2) AS cnaps_employeur1,

    ROUND(NVL(s2.brut, 0), 2) AS mois2,
    ROUND(NVL(s2.cnaps_travailleur, 0), 2) AS cnaps_travailleur2,
    ROUND(NVL(s2.cnaps_employeur, 0), 2) AS cnaps_employeur2,

    ROUND(NVL(s3.brut, 0), 2) AS mois3,
    ROUND(NVL(s3.cnaps_travailleur, 0), 2) AS cnaps_travailleur3,
    ROUND(NVL(s3.cnaps_employeur, 0), 2) AS cnaps_employeur3,

    ROUND(NVL(s1.cnaps_travailleur, 0) + NVL(s2.cnaps_travailleur, 0) + NVL(s3.cnaps_travailleur, 0), 2) AS cotisation_travailleur,
    ROUND(NVL(s1.cnaps_employeur, 0) + NVL(s2.cnaps_employeur, 0) + NVL(s3.cnaps_employeur, 0), 2) AS cotisation_employeur

FROM
    paie_edition_cnaps pec
        JOIN paie_info_personnel_libcomplet pipl
             ON pipl.id = pec.idpersonnel
                 AND pec.mois IN (10, 11, 12)

        LEFT JOIN (
        SELECT
            idpersonnel, mois, annee, brut, cnaps_travailleur, cnaps_employeur
        FROM paie_edition_cnaps
        WHERE mois = 10
    ) s1 ON pec.idpersonnel = s1.idpersonnel AND pec.annee = s1.annee

        LEFT JOIN (
        SELECT
            idpersonnel, mois, annee, brut, cnaps_travailleur, cnaps_employeur
        FROM paie_edition_cnaps
        WHERE mois = 11
    ) s2 ON pec.idpersonnel = s2.idpersonnel AND pec.annee = s2.annee

        LEFT JOIN (
        SELECT
            idpersonnel, mois, annee, brut, cnaps_travailleur, cnaps_employeur
        FROM paie_edition_cnaps
        WHERE mois = 12
    ) s3 ON pec.idpersonnel = s3.idpersonnel AND pec.annee = s3.annee;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CODE_ROME_LIB" ("ID", "IDSOUSFAMILLE", "CODE", "IDSOUSFAMILLELIB") AS
(
    select
       cr.ID,cr.IDSOUSFAMILLE,cr.CODE,
       sfp.val as idSousFamilleLib
    from code_rome cr
       left join sous_famille_pro sfp on sfp.id=cr.idsousfamille

);

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMMANDECPL" ("ID", "DATY", "ETAT", "REMARQUE", "DESIGNATION", "MODEPAIEMENT", "IDCLIENT", "REFERENCE", "IDDEVISE", "IDMAGASIN", "DATEBESOIN", "IDPROFORMA", "MODELIVRAISON", "DATELIVRAISON", "LIEULIVRAISON", "FRAISLIVRAISON", "IDMAGASINLIB", "IDCLIENTLIB", "ETATLIB", "MODELIVRAISONLIB", "MODEPAIEMENTLIB", "MONTANTTTC", "MOTSCLESSS") AS
SELECT CMD.ID,
       CMD.DATY,
       CMD.ETAT,
       CMD.REMARQUE,
       CMD.DESIGNATION,
       CMD.MODEPAIEMENT,
       CMD.IDCLIENT,
       CMD.REFERENCE,
       CMD.IDDEVISE,
       CMD.IDMAGASIN,
       CMD.DATEBESOIN,
       CMD.IDPROFORMA,
       CMD.MODELIVRAISON,
       CMD.DATELIVRAISON,
       CMD.LIEULIVRAISON,
       CMD.FRAISLIVRAISON,
       P.VAL   AS IDMAGASINLIB,
       CL.NOM  AS IDCLIENTLIB,
       CASE
           WHEN CMD.ETAT = 1 THEN 'CR&Eacute;&Eacute;E'
           WHEN CMD.ETAT = 11 THEN 'VIS&Eacute;E'
           WHEN CMD.ETAT = 0 THEN 'ANNUL&Eacute;E'
           ELSE 'Inconnu'
           END AS ETATLIB,
       CASE
           WHEN CMD.MODELIVRAISON = 1 THEN '<span style=color: green;>LIVRAISON</span>'
           WHEN CMD.MODELIVRAISON = 2 THEN '<span style=color: green;>RECUPERATION</span>'
           END AS MODELIVRAISONLIB,
       MP.VAL  AS MODEPAIEMENTLIB,
       CMM.MONTANTTTC,
       (
           CMD.ID || ' | ' || REFERENCE || ' | ' || CL.NOM || ' | ' || DESIGNATION || ' | ' || CMD.REMARQUE
           )   AS MOTSCLESSS
FROM COMMANDE CMD
         LEFT JOIN MAGASIN2 P
                   ON P.ID = CMD.IDMAGASIN
         LEFT JOIN CLIENT CL
                   ON CL.ID = CMD.IDCLIENT
         LEFT JOIN MODEPAIEMENT MP
                   ON MP.ID = CMD.MODEPAIEMENT
         LEFT JOIN COMMANDEMONTANT CMM
                   ON CMM.ID = CMD.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMMANDEFILLECPL" ("ID", "PRODUIT", "IDC", "QUANTITE", "PU", "MONTANT", "TVA", "REMISE", "IDDEVISE", "UNITE", "DESIGNATION", "RISTOURNE", "PRODUITLIB") AS
SELECT cmd."ID",cmd."PRODUIT",cmd."IDC",cmd."QUANTITE",cmd."PU",cmd."MONTANT",cmd."TVA",cmd."REMISE",cmd."IDDEVISE",cmd."UNITE",cmd."DESIGNATION",cmd."RISTOURNE",
       p.LIBELLE as produitLib
FROM COMMANDEFILLE cmd
         LEFT JOIN AS_INGREDIENTS p
                   ON p.id = cmd.PRODUIT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMMANDEFILLEVIDE" ("ID", "PRODUIT", "IDC", "QUANTITE", "PU", "MONTANT", "TVA", "REMISE", "IDDEVISE", "UNITE", "DESIGNATION", "RISTOURNE", "CALORIE", "UNITELIB") AS
select cm."ID",cm."PRODUIT",cm."IDC",cm."QUANTITE",cm."PU",cm."MONTANT",cm."TVA",cm."REMISE",cm."IDDEVISE",cm."UNITE",cm."DESIGNATION",cm."RISTOURNE",cm."CALORIE",'' as uniteLib from COMMANDEFILLE cm;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMMANDEFILLE_ARBIOCHEM" ("ID", "PRODUIT", "IDC", "QUANTITE", "PU", "MONTANT", "TVA", "REMISE", "IDDEVISE", "UNITE", "DESIGNATION", "RISTOURNE", "CALORIE", "MONTANTRISTOURNE", "MONTANTREMISE") AS
select "ID","PRODUIT","IDC","QUANTITE","PU","MONTANT","TVA","REMISE","IDDEVISE","UNITE","DESIGNATION","RISTOURNE","CALORIE",    0 AS montantRistourne,
       0 AS montantRemise from COMMANDEFILLE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMMANDEFILLE_CPL_LIB" ("ID", "PRODUIT", "IDC", "QUANTITE", "PU", "MONTANT", "TVA", "REMISE", "IDDEVISE", "UNITE", "PRODUITLIB", "COMPTE", "QTERESTE", "UNITELIB", "MONTANTTOTAL", "MONTANTDELAREMISE", "MONTANTRISTOURNE", "MONTANTREMISE", "MONTANTTVA", "MONTANTTTC", "RISTOURNE", "FRAISTRANSPORT", "POIDSTOTAL", "CALORIE") AS
SELECT bcf.ID,
       bcf.PRODUIT,
       bcf.IDC,
       bcf.QUANTITE,
       bcf.PU,
       bcf.MONTANT,
       bcf.TVA,
       bcf.REMISE,
       bcf.IDDEVISE,
       bcf.UNITE,
       nvl(i.LIBELLEVENTE,i.libelle)                                                                                                                                      AS PRODUITlib,
       i.compte_vente                                                                                                                                 AS compte,
       NVL(bcf.quantite, 0) - NVL(vdbc.qte, 0)                                                                                                        AS qtereste,
       au.val                                                                                                                                         AS UNITELIB,
       cast(NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0) as Number(30, 2))                                                                                   AS MONTANTTOTAL,
       cast(((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100)) as number(30, 2))                                                          as montantdelaremise,
       cast((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0) - ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100))) *
            (bcf.ristourne / 100) as number(30, 2))                                                                                                   as montantristourne,
       cast(NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0) - ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100)) -
            ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0) - ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100))) *
             (bcf.ristourne / 100)) -
            nvl(i.CALORIE * bcf.QUANTITE * bc.fraislivraison, 0) as number(30, 2))                                                                    as montantremise,
       CAST(
               (((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) -
                 (((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100)) +
                  ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0) -
                    ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100))) * (bcf.ristourne / 100))) -
                 nvl(i.CALORIE * bcf.QUANTITE * bc.fraislivraison, 0)) *
                (nvl(bcf.TVA, 0) / 100))
           AS NUMBER(30, 2)
       )                                                                                                                                              AS MONTANTTVA,
       cast((cast((bcf.quantite * bcf.PU) - ((bcf.quantite * bcf.PU) * NVL(bcf.remise, 0)) / 100 as NUMBER(30, 2)) -
             (cast((bcf.quantite * bcf.PU) - ((bcf.quantite * bcf.PU) * NVL(bcf.remise, 0)) / 100 as NUMBER(30, 2)) *
              nvl(bcf.ristourne, 0) /
              100) - nvl(i.CALORIE * bcf.QUANTITE * bc.fraislivraison, 0)) + (nvl(bcf.TVA, 0) / 100) *
                                                                             (cast((bcf.quantite * bcf.PU) -
                                                                                   ((bcf.quantite * bcf.PU) * NVL(bcf.remise, 0)) /
                                                                                   100 as NUMBER(30, 2)) -
                                                                              (cast((bcf.quantite * bcf.PU) -
                                                                                    ((bcf.quantite * bcf.PU) * NVL(bcf.remise, 0)) /
                                                                                    100 as NUMBER(30, 2)) *
                                                                               nvl(bcf.ristourne, 0) / 100) -
                                                                              nvl(i.CALORIE * bcf.QUANTITE * bc.fraislivraison, 0)) as number(30, 2)) AS MONTANTTTC,
       bcf.ristourne,
       nvl(i.CALORIE * bcf.QUANTITE * bc.fraislivraison, 0)                                                                                           as fraistransport,
       CAST(NVL(i.CALORIE * bcf.QUANTITE,0) AS NUMBER(30,2)) AS poidstotal,
       i.CALORIE
FROM COMMANDEFILLE bcf
         left JOIN as_ingredients i ON i.id = bcf.PRODUIT
         LEFT JOIN vente_details_qte_grp vdbc ON bcf.id = vdbc.idbcfille
         LEFT JOIN AS_UNITE au ON au.id = i.unite
         LEFT JOIN COMMANDE bc on bc.id = bcf.IDC;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMMANDEFILLE_V" ("ID", "PRODUIT", "IDC", "QUANTITE", "PU", "MONTANT", "TVA", "REMISE", "IDDEVISE", "UNITE", "DESIGNATION", "UNITELIB", "PUNET", "MONTANTHT", "MONTANTTTC", "RISTOURNE", "CALORIE") AS
select p.ID,
       p.PRODUIT,
       p.IDC,
       p.QUANTITE,
       p.PU,
       p.MONTANT,
       p.TVA,
       p.REMISE,
       p.IDDEVISE,
       p.UNITE,
       p.DESIGNATION,
       uni.val as unitelib,
       0  as punet,
       0  as montantht,
       0  as montantttc,
       p.RISTOURNE,
       ing.calorie
from COMMANDEFILLE p
         LEFT JOIN as_unite uni ON p.unite = uni.id
         LEFT JOIN  AS_INGREDIENTS ing ON p.PRODUIT = ing.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMMANDEMONTANT" ("ID", "POIDSTOTAL", "MONTANT", "MONTANTREMISE", "MONTANTRISTOURNE", "FRAISTRANSPORT", "MONTANTTOTAL", "MONTANTTOTALACHAT", "MONTANTTVA", "MONTANTTTC", "IDDEVISE", "TAUXDECHANGE", "MONTANTTTCAR") AS
SELECT v.ID,
       cast(SUM(poidstotal) as number(30, 2))                            AS poidstotal,
       cast(SUM(PU) as number(30, 2))                               AS montant,
       cast(SUM(MONTANTREMISE) as number(30, 2))                         as montantremise,
       cast(SUM(montantristourne) as number(30, 2))                      as montantristourne,
       cast(SUM(vd.fraistransport) as number(30, 2))                     as fraistransport,
       cast(SUM(montanttotal) as number(30, 2))                          AS montanttotal,
       cast(SUM((NVL(vd.QUANTITE, 0) * NVL(vd.PU, 0))) as number(30, 2)) AS montanttotalachat,
       cast(SUM(montanttva) as number(30, 2))                            AS montantTva,
       cast(SUM(vd.MONTANTTTC) as number(30, 2))                            as montantTTC,
       NVL(vd.IDDEVISE, 'AR')                                            AS IDDEVISE,
       NVL(avg(1), 1)                                      AS tauxDeChange,
       cast(SUM(MONTANTTTC) as number(30, 2))          as montantTTCAR
FROM COMMANDEFILLE_CPL_LIB vd
         LEFT JOIN COMMANDE v ON v.ID = vd.IDC
GROUP BY v.ID, vd.IDDEVISE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPARAISONPRIXFACTBC" ("ID", "IDPRODUIT", "IDPRODUITLIB", "IDFACTUREFOURNISSEUR", "PUFACT", "PUBC", "ECART") AS
SELECT
    f.idFactureFournisseur as id,
    f.idProduit,
    f.idProduitLib,
    f.idFactureFournisseur,
    f.pu          AS puFact,
    ASB.pu        AS puBc,
    f.pu - ASB.pu AS ecart
FROM FACTUREFOURNISSEURFILLECPL f

         LEFT JOIN FACTUREFOURNISSEUR ff
                   ON ff.ID = f.IDFACTUREFOURNISSEUR

         LEFT JOIN AS_BONDECOMMANDE_CPL ASB
                   ON ASB.IDBC = ff.IDBC

WHERE ff.IDBC IS NOT NULL;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTAMOUVEMENTDETAILS_GEN_2_C" ("ID", "CONTREP", "COMPTE", "DEBIT", "CREDIT", "LIBELLEPIECE", "REMARQUE", "IDMERE", "REFERENCE_ENGAGEMENT", "COMPTE_AUX", "LETTRAGE", "JOURNAL", "EXERCICE", "ETAT", "DATY", "FOLIO", "COURSDEVISE", "MONTANTDEVISE", "COMPTEINT") AS
SELECT
    "ID","CONTREP","COMPTE","DEBIT","CREDIT","LIBELLEPIECE","REMARQUE","IDMERE","REFERENCE_ENGAGEMENT","COMPTE_AUX","LETTRAGE","JOURNAL","EXERCICE","ETAT","DATY","FOLIO","COURSDEVISE","MONTANTDEVISE","COMPTEINT"
FROM
    COMPTA_MOUVEMENT_DETAILS_GEN_2 cmdg
