CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTA_COMPTE_INGREDIENTS" ("ID", "COMPTE", "LIBELLE", "TYPECOMPTE", "CLASSY", "ANALYTIQUE_OBLI", "IDJOURNAL", "CODEIMPOT", "IDINGREDIENT", "LIBELLEINGREDIENT") AS
SELECT
	c.ID,
	c.COMPTE,
	c.LIBELLE,
	c.TYPECOMPTE,
	c.CLASSY,
	c.ANALYTIQUE_OBLI,
	c.IDJOURNAL,
	c.CODEIMPOT,
	si.ID AS idingredient,
	si.LIBELLE AS libelleIngredient
FROM
	COMPTA_COMPTE c
LEFT JOIN ST_INGREDIENTSAUTOACHAT_CPL si ON
	c.COMPTE = si.COMPTE_ACHAT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTA_COMPTE_LIB" ("ID", "COMPTE", "LIBELLE", "TYPECOMPTE", "CLASSY", "ANALYTIQUE_OBLI", "IDJOURNAL") AS
select ID,
	       Compte,
	       LIBELLE||' : '||COMPTE as libelle,
	       TYPECOMPTE,
	       CLASSY,
	       ANALYTIQUE_OBLI,
	       IDJOURNAL
	from COMPTA_COMPTE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTA_COMPTE_LIBELLE" ("ID", "COMPTE", "LIBELLE", "TYPECOMPTE", "CLASSE", "IDJOURNAL", "IDTYPECOMPTE") AS
(SELECT   compta_compte.ID,
            compta_compte.compte,
            compta_compte.libelle,
            compta_type_compte.val AS typecompte,
            compta_classe_compte.val  AS classe ,
            (compta_journal.VAL ||'|'|| compta_journal.DESCE) as idjournal,
            compta_type_compte.id AS idtypecompte
  FROM compta_compte
  join compta_type_compte on compta_type_compte.ID = compta_compte.typecompte
  left join compta_classe_compte on compta_classe_compte.ID = compta_compte.classy
  left join compta_journal on compta_compte.idjournal = compta_journal.id);

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTA_ECRITURE_FICHE" ("ID", "DATY", "DATECOMPTABLE", "EXERCICE", "DESIGNATION", "REMARQUE", "ETAT", "HORSEXERCICE", "JOURNAL", "OD", "ORIGINE", "CREDIT", "DEBIT", "IDUSER", "PERIODE", "TRIMESTRE", "ANNEE", "IDOBJET", "LETTRAGE", "LIEN", "DATESAISIE", "DATEMODIF", "IDMODIFICATEUR", "IDMODIFICATEURLIB", "JOURNALLIB") AS
select ce."ID",
       ce."DATY",
       ce."DATECOMPTABLE",
       ce."EXERCICE",
       ce."DESIGNATION",
       ce."REMARQUE",
       ce."ETAT",
       ce."HORSEXERCICE",
       ce."JOURNAL",
       ce."OD",
       ce."ORIGINE",
       ce."CREDIT",
       ce."DEBIT",
       ce."IDUSER",
       ce."PERIODE",
       ce."TRIMESTRE",
       ce."ANNEE",
       ce."IDOBJET",
       ce."LETTRAGE",
       vc.FICHE  as lien,
       ce.dateSaisie,
       ce.DATEMODIF,
       ce.idModificateur,
       u.NOMUSER as idModificateurlib,
       cj.VAL as journalLib
from COMPTA_ECRITURE ce
         left join V_CLASSEETFICHE vc on substr(ce.IDOBJET, 1, 3) = vc.LIBELLE
         left join utilisateur u on ce.idmodificateur = u.REFUSER
        left join COMPTA_JOURNAL cj on cj.id=ce.JOURNAL;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTA_ECRITURE_FILLE" ("ID", "MOIS", "JOUR", "COMPTE", "FOLIO", "SOURCE", "LIBELLE", "DEBIT", "CREDIT", "DATY", "ANALYTIQUE", "JOURNAL", "EXERCICE") AS
SELECT id,
		EXTRACT(MONTH FROM daty ) as mois,
		EXTRACT(DAY FROM daty ) as jour,
		compte,
		folio,
		SOURCE,
		libellepiece AS libelle,
		debit,
		credit,
		daty,
		analytique,
		journal,
		exercice
	FROM COMPTA_SOUS_ECRITURE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTA_ECRITURE_LIB" ("ID", "DATY", "DATECOMPTABLE", "EXERCICE", "DESIGNATION", "REMARQUE", "ETAT", "HORSEXERCICE", "JOURNAL", "OD", "ORIGINE", "CREDIT", "DEBIT", "IDUSER", "PERIODE", "TRIMESTRE", "ANNEE", "IDOBJET", "MONTANT", "JOURNALLIB", "JOURNALCODE", "ETATLIB", "TIERSLIB", "PIECE") AS
SELECT ce.ID,
       ce.DATY,
       ce.DATECOMPTABLE,
       ce.EXERCICE,
       ce.DESIGNATION,
       ce.REMARQUE,
       ce.ETAT,
       ce.HORSEXERCICE,
       ce.JOURNAL,
       ce.OD,
       ce.ORIGINE,
       ce.CREDIT,
       ce.DEBIT,
       ce.IDUSER,
       ce.PERIODE,
       ce.TRIMESTRE,
       ce.ANNEE,
       COALESCE(ce.IDOBJET , '-') as IDOBJET,
       CAST(cm.montant AS NUMBER(38, 2))                        AS montant,
       cj.desce                                                 AS JOURNALLIB,
       cj.val                                                   as JOURNALCODE,
       CASE
           WHEN ce.ETAT = 1 THEN 'Cree'
           WHEN ce.ETAT = 11 THEN 'Valide'
           ELSE 'Autre'
           END                                                  AS etatlib,
       COALESCE(fc.IDFOURNISSEURLIB, vc.idClientlib, mvc.tiers, '-') AS tierslib,
       CASE
           WHEN ce.ORIGINE = 'AVR' THEN '-'
           WHEN ce.ORIGINE = 'MTC' THEN COALESCE(vc_mtc.NUMEROFACTURE, fc_mtc.NUMERO, '-')
           WHEN ce.ORIGINE = 'MVT' THEN '-'
           WHEN ce.ORIGINE = 'VNT' THEN vc.NUMEROFACTURE
           WHEN ce.ORIGINE = 'FCF' THEN fc.NUMERO
           ELSE '-'
           END                                AS piece
FROM COMPTA_ECRITURE ce
         JOIN COMPTA_MONTANT cm ON ce.id = cm.IDMERE
         LEFT JOIN COMPTA_JOURNAL cj ON cj.id = ce.JOURNAL
         LEFT JOIN FACTUREFOURNISSEURCPL fc ON fc.id = ce.idobjet
         LEFT JOIN VENTE_CPL vc ON vc.id = ce.idobjet
         LEFT JOIN MOUVEMENTCAISSECPL mvc ON mvc.id = ce.idobjet
         LEFT JOIN VENTE_CPL vc_mtc ON vc_mtc.ID = mvc.IDORIGINE
         LEFT JOIN FACTUREFOURNISSEURCPL fc_mtc ON fc_mtc.ID = mvc.IDORIGINE
order by ce.DATY DESC;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTA_ECRITURE_LIB_ACHAT" ("ID", "DATY", "DATECOMPTABLE", "EXERCICE", "DESIGNATION", "REMARQUE", "ETAT", "HORSEXERCICE", "JOURNAL", "OD", "ORIGINE", "CREDIT", "DEBIT", "IDUSER", "PERIODE", "TRIMESTRE", "ANNEE", "IDOBJET", "MONTANT", "JOURNALLIB", "JOURNALCODE", "ETATLIB", "TIERSLIB", "PIECE") AS
SELECT ce.ID,
       ce.DATY,
       ce.DATECOMPTABLE,
       ce.EXERCICE,
       ce.DESIGNATION,
       ce.REMARQUE,
       ce.ETAT,
       ce.HORSEXERCICE,
       ce.JOURNAL,
       ce.OD,
       ce.ORIGINE,
       ce.CREDIT,
       ce.DEBIT,
       ce.IDUSER,
       ce.PERIODE,
       ce.TRIMESTRE,
       ce.ANNEE,
       COALESCE(ce.IDOBJET , '-') as IDOBJET,
       CAST(cm.montant AS NUMBER(38, 2))                        AS montant,
       cj.desce                                                 AS JOURNALLIB,
       cj.val                                                   as JOURNALCODE,
       CASE
           WHEN ce.ETAT = 1 THEN 'Cree'
           WHEN ce.ETAT = 11 THEN 'Valide'
           ELSE 'Autre'
           END                                                  AS etatlib,
       COALESCE(fc.IDFOURNISSEURLIB, vc.idClientlib, mvc.tiers, '-') AS tierslib,
       CASE
           WHEN ce.ORIGINE = 'AVR' THEN '-'
           WHEN ce.ORIGINE = 'MTC' THEN COALESCE(vc_mtc.NUMEROFACTURE, fc_mtc.NUMERO)
           WHEN ce.ORIGINE = 'MVT' THEN '-'
           WHEN ce.ORIGINE = 'VNT' THEN vc.NUMEROFACTURE
           WHEN ce.ORIGINE = 'FCF' THEN fc.NUMERO
           ELSE '-'
           END                                AS piece
FROM COMPTA_ECRITURE ce
         JOIN COMPTA_MONTANT cm ON ce.id = cm.IDMERE
         LEFT JOIN COMPTA_JOURNAL cj ON cj.id = ce.JOURNAL
         LEFT JOIN FACTUREFOURNISSEURCPL fc ON fc.id = ce.idobjet
         LEFT JOIN VENTE_CPL vc ON vc.id = ce.idobjet
         LEFT JOIN MOUVEMENTCAISSECPL mvc ON mvc.id = ce.idobjet
         LEFT JOIN VENTE_CPL vc_mtc ON vc_mtc.ID = mvc.IDORIGINE
         LEFT JOIN FACTUREFOURNISSEURCPL fc_mtc ON fc_mtc.ID = mvc.IDORIGINE
where ce.IDOBJET like '%FCF%'
order by ce.DATY DESC;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTA_ECRITURE_LIB_AVOIRFC" ("ID", "DATY", "DATECOMPTABLE", "EXERCICE", "DESIGNATION", "REMARQUE", "ETAT", "HORSEXERCICE", "JOURNAL", "OD", "ORIGINE", "CREDIT", "DEBIT", "IDUSER", "PERIODE", "TRIMESTRE", "ANNEE", "IDOBJET", "MONTANT", "JOURNALLIB", "JOURNALCODE", "ETATLIB", "TIERSLIB", "PIECE") AS
