CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTA_ECRITURE_LIB_VENTE" ("ID", "DATY", "DATECOMPTABLE", "EXERCICE", "DESIGNATION", "REMARQUE", "ETAT", "HORSEXERCICE", "JOURNAL", "OD", "ORIGINE", "CREDIT", "DEBIT", "IDUSER", "PERIODE", "TRIMESTRE", "ANNEE", "IDOBJET", "MONTANT", "JOURNALLIB", "JOURNALCODE", "ETATLIB", "TIERSLIB", "PIECE") AS
