       cj.desce                                                 AS JOURNALLIB,
       cj.val                                                   as JOURNALCODE,
       CASE
           WHEN ce.ETAT = 1 THEN 'Cree'
           WHEN ce.ETAT = 11 THEN 'Valide'
           ELSE 'Autre'
           END                                                  AS etatlib,
       COALESCE(fc.IDFOURNISSEURLIB, vc.idClientlib, mvc.tiers, '-') AS tierslib,
