CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTA_ECRITURE_MERE" ("ID", "MOIS", "EXERCICE", "JOURNAL") AS
SELECT
	id,
	EXTRACT(MONTH FROM daty ) AS mois,
	exercice,
	journal
FROM
	COMPTA_SOUS_ECRITURE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTA_ECRITURE_MF" ("ID", "DATY", "DATECOMPTABLE", "EXERCICE", "DESIGNATION", "REMARQUE", "ETAT", "HORSEXERCICE", "JOURNAL", "OD", "ORIGINE", "IDUSER", "PERIODE", "TRIMESTRE", "ANNEE", "IDOBJET", "LETTRAGE", "COMPTE", "DEBIT", "CREDIT") AS
SELECT
    ce.ID,
    ce.DATY,
    ce.DATECOMPTABLE,
    ce.EXERCICE,
    ce.DESIGNATION,
    ce.REMARQUE,
    ce.ETAT,
    ce.HORSEXERCICE,
    ce.JOURNAL,
    ce.OD,
    ce.ORIGINE,
    ce.IDUSER,
    ce.PERIODE,
    ce.TRIMESTRE,
    ce.ANNEE,
    ce.IDOBJET,
    ce.LETTRAGE,
    cse.COMPTE ,
    CAST( SUM(cse.DEBIT) AS NUMBER(30,2))  AS DEBIT,
    CAST( SUM(cse.CREDIT) AS NUMBER(30,2)) AS CREDIT
FROM COMPTA_ECRITURE ce
         LEFT JOIN COMPTA_SOUS_ECRITURE cse ON ce.ID = cse.IDMERE
GROUP BY
    ce.ID,
    ce.DATY,
    ce.DATECOMPTABLE,
    ce.EXERCICE,
    ce.DESIGNATION,
    ce.REMARQUE,
    ce.ETAT,
    ce.HORSEXERCICE,
    ce.JOURNAL,
    ce.OD,
    ce.ORIGINE,
    ce.IDUSER,
    ce.PERIODE,
    ce.TRIMESTRE,
    ce.ANNEE,
    ce.IDOBJET,
    ce.LETTRAGE,
    cse.COMPTE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTA_JOURNAL_COMPTE" ("ID", "VAL", "DESCE") AS
SELECT ID,
       CASE
           WHEN COMPTE IS NOT NULL THEN VAL || ' - ' || COMPTE
           ELSE VAL
           END                               AS VAL,
       VAL || '|' || DESCE || '**' || COMPTE AS DESCE
FROM COMPTA_JOURNAL
WHERE VAL != 'COMP000015';

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTA_JOURNAL_ECRITURE_VIEW" ("ID", "VAL", "DESCE") AS
SELECT
	ID,
	CASE
		WHEN COMPTE IS NOT NULL THEN VAL || ' - ' || COMPTE
		ELSE VAL
	END AS VAL,
	VAL || '|' || DESCE || '**' || COMPTE AS DESCE
FROM
	COMPTA_JOURNAL
WHERE
	VAL != 'COMP000015';

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTA_JOURNAL_MOTSCLESSS" ("ID", "VAL", "DESCE", "COMPTE", "MOTSCLESSS") AS
SELECT 
cj.ID,
cj.VAL,
cj.DESCE,
cj.COMPTE,
cj.id || '' || cj.val || '' || cj.desce || '' || cj.compte AS motsclesss
FROM COMPTA_JOURNAL cj;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTA_JOURNAL_VIEW" ("ID", "VAL", "DESCE") AS
SELECT ID, VAL, VAL||'|'||DESCE AS DESCE FROM COMPTA_JOURNAL;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTA_LETTRAGE_LIB" ("ID", "LETTRE", "DATE_LETTRAGE", "COMPTE", "MONTANT", "REMARQUE", "JOURNAL") AS
SELECT cl.id, cl.LETTRE, cl.DATE_LETTRAGE, cc.COMPTE, cl.montant, cl.remarque,
  jrn.desce as journal
FROM compta_lettrage cl
         LEFT JOIN COMPTA_SOUS_ECRITURE cse ON cse.LETTRAGE = cl.ID
         LEFT JOIN COMPTA_COMPTE cc ON cc.COMPTE = cse.compte
         LEFT JOIN COMPTA_JOURNAL jrn ON cse.JOURNAL = jrn.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTA_MONTANT" ("MONTANT", "IDMERE") AS
SELECT
sum(nvl(cse.DEBIT,0)) AS montant ,
cse.IDMERE
FROM COMPTA_SOUS_ECRITURE cse
GROUP BY IDMERE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTA_MOUVEMENT_ANALYTIQUE" ("DEBIT", "CREDIT", "COMPTE", "ETAT", "LIBELLE_COMPTE", "TYPECOMPTE", "MOIS", "ANNEE", "CHIFFRE3", "CHIFFRE2") AS
SELECT
    CAST(sum(debit) AS NUMBER(30,
        2)) AS debit,
    CAST(sum(credit) AS NUMBER(30,
        2)) AS credit,
    compte,
    etat,
    libelle_compte,
    typecompte,
    mois,
    annee,
    chiffre3,
    chiffre2
FROM
    (
        SELECT
            cse.id,
            cse.debit AS debit,
            cse.credit AS credit,
            cse.analytique AS compte,
            cc.LIBELLE AS libelle_compte,
            cse.daty AS daty,
            cse.etat,
            cc.typecompte AS typecompte,
            EXTRACT(MONTH FROM cse.daty) AS mois,
            EXTRACT(YEAR FROM cse.daty) AS annee,
            substr(analytique, 1, 3)|| substr(analytique, 5, 1) AS chiffre3,
            substr(analytique, 1, 2) AS chiffre2
        FROM
            compta_sous_ecriture cse
                JOIN compta_compte cc ON
                cc.compte = cse.analytique
        WHERE
            cse.journal!='COMP000015'
          AND (cse.debit + cse.credit)>0
          AND cse.etat = 11
          AND NOT EXISTS(
            SELECT
                rs.id
            FROM
                reportsolde rs
            WHERE
                rs.id = cse.id
        )

        --group by   ce.id, cse.analytique, ce.daty, cse.etat, cc.LIBELLE, cc.typecompte , extract(month from cse.daty),
        --extract(year from cse.daty)
    )
GROUP BY compte,
         etat,
         libelle_compte,
         typecompte,
         mois,
         annee,
         chiffre3,
         chiffre2
ORDER BY
    chiffre3 ASC;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTA_MOUVEMENT_ANAL_C" ("ID", "CONTREP", "COMPTE", "DEBIT", "CREDIT", "LIBELLEPIECE", "REMARQUE", "IDMERE", "REFERENCE_ENGAGEMENT", "COMPTE_AUX", "LETTRAGE", "JOURNAL", "EXERCICE", "ETAT", "DATY", "FOLIO") AS
SELECT
    "ID","CONTREP","COMPTE","DEBIT","CREDIT","LIBELLEPIECE","REMARQUE","IDMERE","REFERENCE_ENGAGEMENT","COMPTE_AUX","LETTRAGE","JOURNAL","EXERCICE","ETAT","DATY","FOLIO"
FROM
    COMPTA_MOUVEMENT_DETAILS_ANAL2 cmda
WHERE cmda.etat = 1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTA_MOUVEMENT_ANAL_V" ("ID", "CONTREP", "COMPTE", "DEBIT", "CREDIT", "LIBELLEPIECE", "REMARQUE", "IDMERE", "REFERENCE_ENGAGEMENT", "COMPTE_AUX", "LETTRAGE", "JOURNAL", "EXERCICE", "ETAT", "DATY", "FOLIO") AS
SELECT
    "ID","CONTREP","COMPTE","DEBIT","CREDIT","LIBELLEPIECE","REMARQUE","IDMERE","REFERENCE_ENGAGEMENT","COMPTE_AUX","LETTRAGE","JOURNAL","EXERCICE","ETAT","DATY","FOLIO"
FROM
    COMPTA_MOUVEMENT_DETAILS_ANAL2 cmda
WHERE cmda.etat = 11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTA_MOUVEMENT_AUX_2_C" ("ID", "CONTREP", "COMPTE", "DEBIT", "CREDIT", "LIBELLEPIECE", "REMARQUE", "IDMERE", "REFERENCE_ENGAGEMENT", "COMPTE_AUX", "LETTRAGE", "JOURNAL", "EXERCICE", "ETAT", "DATY", "FOLIO", "COMPTE_AUXLIB", "COURSDEVISE", "MONTANTDEVISE", "COMPTEINT") AS
SELECT "ID","CONTREP","COMPTE","DEBIT","CREDIT","LIBELLEPIECE","REMARQUE","IDMERE","REFERENCE_ENGAGEMENT","COMPTE_AUX","LETTRAGE","JOURNAL","EXERCICE","ETAT","DATY","FOLIO","COMPTE_AUXLIB","COURSDEVISE","MONTANTDEVISE","COMPTEINT" FROM COMPTA_MOUVEMENT_DETAILS_AUX_2 WHERE etat = 1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTA_MOUVEMENT_AUX_2_V" ("ID", "CONTREP", "COMPTE", "DEBIT", "CREDIT", "LIBELLEPIECE", "REMARQUE", "IDMERE", "REFERENCE_ENGAGEMENT", "COMPTE_AUX", "LETTRAGE", "JOURNAL", "EXERCICE", "ETAT", "DATY", "FOLIO", "COMPTE_AUXLIB", "COURSDEVISE", "MONTANTDEVISE", "COMPTEINT") AS
SELECT "ID","CONTREP","COMPTE","DEBIT","CREDIT","LIBELLEPIECE","REMARQUE","IDMERE","REFERENCE_ENGAGEMENT","COMPTE_AUX","LETTRAGE","JOURNAL","EXERCICE","ETAT","DATY","FOLIO","COMPTE_AUXLIB","COURSDEVISE","MONTANTDEVISE","COMPTEINT" FROM COMPTA_MOUVEMENT_DETAILS_AUX_2 WHERE etat = 11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTA_MOUVEMENT_DETAILAUX" ("ID", "CONTREP", "COMPTE_AUXLIB", "COMPTE", "DEBIT", "CREDIT", "LIBELLEPIECE", "REMARQUE", "IDMERE", "REFERENCE_ENGAGEMENT", "COMPTE_AUX", "LETTRAGE", "JOURNAL", "EXERCICE", "ETAT", "DATY", "FOLIO", "COURSDEVISE", "MONTANTDEVISE") AS
SELECT
	cse.id,
	(
	SELECT
		MIN(csec.compte) KEEP (DENSE_RANK FIRST
	ORDER BY
		GREATEST(csec.debit, csec.credit) DESC)
	FROM
		compta_sous_ecriture csec
	WHERE
		csec.idmere = cse.idmere
		AND csec.id <> cse.id
		AND (

            (cse.debit > 0
			AND csec.credit > 0)
		OR

            (cse.credit > 0
			AND csec.debit > 0)

            )

    ) AS contrep,
	t.nom AS compte_auxlib,
	t.compteauxiliaire AS compte,
	cse.debit,
	cse.credit,
	cse.libellepiece,
	cse.remarque,
	cse.idmere,
	cse.analytique AS REFERENCE_ENGAGEMENT,
	cse.compte_aux,
	lettre.lettre AS lettrage,
	cj.val AS journal,
	EXTRACT(YEAR FROM cse.daty) AS exercice,
	cse.etat,
	cse.daty,
	cse.folio,
	CAST(0 AS NUMBER(20, 2)) AS coursdevise,
	CAST(0 AS NUMBER(20, 2)) AS montantdevise
FROM
	COMPTA_SOUS_ECRITURE cse
LEFT JOIN TIERS t ON
	cse.COMPTE_AUX = t.id
LEFT JOIN COMPTA_JOURNAL_VIEW cj ON
	cj.id = cse.journal
LEFT JOIN compta_compte cc ON
	cse.compte = cc.compte
LEFT JOIN compta_type_compte ctc ON
	cc.typecompte = ctc.id
LEFT JOIN COMPTA_LETTRAGE lettre ON
	lettre.id = cse.lettrage
WHERE
	1<2
	AND cj.id <> 'COMP000015'
	AND ((cse.DEBIT>0
		AND cse.credit = 0)
	OR (cse.DEBIT = 0
		AND cse.credit>0));

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTA_MOUVEMENT_DETAILGEN" ("ID", "CONTREP", "COMPTE", "DEBIT", "CREDIT", "LIBELLEPIECE", "REMARQUE", "MERE", "REFERENCE_ENGAGEMENT", "COMPTE_AUX", "LETTRAGE", "JOURNAL", "EXERCICE", "ETAT", "DATY", "FOLIO", "COURSDEVISE", "MONTANTDEVISE") AS
SELECT
	cse.id,
	(
	SELECT
		MIN(csec.compte) KEEP (DENSE_RANK FIRST
	ORDER BY
		GREATEST(csec.debit, csec.credit) DESC)
	FROM
		compta_sous_ecriture csec,
		COMPTA_JOURNAL_VIEW cjv
	WHERE
		csec.idmere = cse.idmere
		AND csec.id <> cse.id
		AND cjv.id = csec.journal
		AND (

            (cse.debit > 0
			AND csec.credit > 0)
		OR

            (cse.credit > 0
			AND csec.debit > 0)

            )
		AND cjv.id <> 'COMP000015'

    ) AS contrep,
	cse.compte,
	cse.debit,
	cse.credit,
	cse.libellepiece,
	cse.remarque,
	cse.idmere,
	cse.analytique AS REFERENCE_ENGAGEMENT,
	cse.compte_aux,
	lettre.lettre AS lettrage,
	cj.val AS journal,
	EXTRACT(YEAR FROM cse.daty) AS exercice,
	cse.etat,
	cse.daty,
	cse.folio,
	CAST(0 AS NUMBER(20, 2)) AS coursdevise,
	CAST(0 AS NUMBER(20, 2)) AS montantdevise
FROM
	COMPTA_SOUS_ECRITURE cse
LEFT JOIN COMPTA_JOURNAL_VIEW cj ON
	cj.id = cse.journal
LEFT JOIN compta_compte cc ON
	cse.compte = cc.compte
LEFT JOIN compta_type_compte ctc ON
	cc.typecompte = ctc.id
LEFT JOIN COMPTA_LETTRAGE lettre ON
	lettre.id = cse.lettrage
WHERE
	1<2
	AND cj.id <> 'COMP000015'
	AND ((cse.DEBIT>0
		AND cse.credit = 0)
	OR (cse.DEBIT = 0
		AND cse.credit>0));

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTA_MOUVEMENT_DETAILS_ANAL2" ("ID", "CONTREP", "COMPTE", "DEBIT", "CREDIT", "LIBELLEPIECE", "REMARQUE", "IDMERE", "REFERENCE_ENGAGEMENT", "COMPTE_AUX", "LETTRAGE", "JOURNAL", "EXERCICE", "ETAT", "DATY", "FOLIO") AS
SELECT
	cse.id,
	(
	SELECT
		csec.analytique
	FROM
		compta_sous_ecriture csec,
		COMPTA_JOURNAL_VIEW cjv,
		compta_compte cco,
		compta_type_compte ctcp
	WHERE
		csec.idmere = cse.idmere
		AND csec.credit>0
		AND cjv.id = csec.journal
		AND csec.analytique = cco.compte
		AND cco.typecompte = ctcp.id
		AND cjv.val <> 'COMP000015'
		AND rownum = 1) AS contrep,
	cse.analytique,
	cse.debit,
	cse.credit,
	cse.libellepiece,
	cse.remarque,
	cse.idmere,
	cse.reference_engagement,
	cse.compte_aux,
	lettre.lettre AS lettrage,
	cj.val AS journal,
	EXTRACT(YEAR FROM cse.daty),
	cse.etat,
	cse.daty,
	cse.folio
FROM
	COMPTA_SOUS_ECRITURE cse
JOIN compta_ecriture ce ON
	ce.id = cse.idmere
JOIN COMPTA_JOURNAL_VIEW cj ON
	cj.id = cse.journal
JOIN compta_compte cc ON
	cse.analytique = cc.compte
JOIN compta_type_compte ctc ON
	cc.typecompte = ctc.id
LEFT JOIN COMPTA_LETTRAGE lettre ON
	lettre.id = cse.lettrage
WHERE
	1<2
	AND cj.id <> 'COMP000015'
	AND cse.DEBIT>0
UNION

SELECT
	cse.id,
	(
	SELECT
		csec.analytique
	FROM
		compta_sous_ecriture csec,
		COMPTA_JOURNAL_VIEW cjv,
		compta_compte cco,
		compta_type_compte ctcp
	WHERE
		csec.idmere = cse.idmere
		AND csec.debit>0
		AND cjv.id = csec.journal
		AND csec.analytique = cco.compte
		AND cco.typecompte = ctcp.id
		AND cjv.id <> 'COMP000015'
		AND rownum = 1) AS contrep,
	cse.analytique,
	cse.debit,
	cse.credit,
	cse.libellepiece,
	cse.remarque,
	cse.idmere,
	cse.reference_engagement,
	cse.compte_aux,
	lettre.lettre AS lettrage,
	cj.val AS journal,
	EXTRACT(YEAR FROM cse.daty),
	cse.etat,
	cse.daty,
	cse.folio
FROM
	COMPTA_SOUS_ECRITURE cse
JOIN compta_ecriture ce ON
	ce.id = cse.idmere
JOIN COMPTA_JOURNAL_VIEW cj ON
	cj.id = cse.journal
JOIN compta_compte cc ON
	cse.analytique = cc.compte
JOIN compta_type_compte ctc ON
	cc.typecompte = ctc.id
LEFT JOIN COMPTA_LETTRAGE lettre ON
	lettre.id = cse.lettrage
WHERE
	1<2
	AND cj.id <> 'COMP000015'
	AND cse.CREDIT>0;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTA_MOUVEMENT_DETAILS_AUX_2" ("ID", "CONTREP", "COMPTE", "DEBIT", "CREDIT", "LIBELLEPIECE", "REMARQUE", "IDMERE", "REFERENCE_ENGAGEMENT", "COMPTE_AUX", "LETTRAGE", "JOURNAL", "EXERCICE", "ETAT", "DATY", "FOLIO", "COMPTE_AUXLIB", "COURSDEVISE", "MONTANTDEVISE", "COMPTEINT") AS
SELECT
	ID,
	CONTREP,
	COMPTE,
	DEBIT,
	CREDIT,
	LIBELLEPIECE,
	REMARQUE,
	idmere AS IDMERE,
	REFERENCE_ENGAGEMENT,
	COMPTE_AUX,
	LETTRAGE,
	JOURNAL,
	EXERCICE,
	ETAT,
	DATY,
	FOLIO,
	compte_auxlib,
	CAST(COURSDEVISE AS NUMBER(20,

        2)) AS COURSDEVISE,
	CAST(MONTANTDEVISE AS NUMBER(20,

        2)) AS MONTANTDEVISE,
	TO_NUMBER(REGEXP_SUBSTR(TRIM(compte), '^[0-9]+')) AS compteInt
FROM
	COMPTA_MOUVEMENT_DETAILAUX
WHERE
	REGEXP_LIKE(TRIM(compte), '^[0-9]+');

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTA_MOUVEMENT_DETAILS_GEN_2" ("ID", "CONTREP", "COMPTE", "DEBIT", "CREDIT", "LIBELLEPIECE", "REMARQUE", "IDMERE", "REFERENCE_ENGAGEMENT", "COMPTE_AUX", "LETTRAGE", "JOURNAL", "EXERCICE", "ETAT", "DATY", "FOLIO", "COURSDEVISE", "MONTANTDEVISE", "COMPTEINT") AS
SELECT
    ID,
    CONTREP,
    COMPTE,
    DEBIT,
    CREDIT,
    LIBELLEPIECE,
    REMARQUE,
    MERE AS IDMERE,
    REFERENCE_ENGAGEMENT,
    COMPTE_AUX,
    LETTRAGE,
    JOURNAL,
    EXERCICE,
    ETAT,
    DATY,
    FOLIO,
    CAST(COURSDEVISE AS NUMBER(20,
                               2)) AS COURSDEVISE,
    CAST(MONTANTDEVISE AS NUMBER(20,
                                 2)) AS MONTANTDEVISE,
    TO_NUMBER(REGEXP_SUBSTR(TRIM(compte), '^[0-9]+')) AS compteInt
FROM
    COMPTA_MOUVEMENT_DETAILGEN
where REGEXP_LIKE(TRIM(compte), '^[0-9]+');

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTA_MOUVEMENT_GENERAL" ("DEBIT", "CREDIT", "COMPTE", "ETAT", "LIBELLE_COMPTE", "TYPECOMPTE", "MOIS", "ANNEE", "CHIFFRE3", "CHIFFRE2") AS
SELECT
    CAST(sum(debit)AS NUMBER(30,
        2)) AS debit,
    CAST(sum(credit) AS NUMBER(30,
        2)) AS credit,
    compte,
    etat,
    libelle_compte,
    typecompte,
    mois,
    annee,
    chiffre3,
    chiffre2
FROM
    (
        SELECT
            cse.id,
            cse.debit AS debit,
            cse.credit AS credit,
            cse.compte AS compte,
            cc.LIBELLE AS libelle_compte,
            cse.daty AS daty,
            cse.etat,
            cc.typecompte AS typecompte,
            EXTRACT(MONTH FROM cse.daty) AS mois,
            EXTRACT(YEAR FROM cse.daty) AS annee,
            CASE
                WHEN substr(cse.compte, 1, 4) = '4007' THEN '407'
                ELSE substr(cse.compte, 1, 2)|| substr(cse.compte, 5, 1)
                END AS chiffre3,
            substr(cse.compte, 1, 2) AS chiffre2
        FROM
            compta_sous_ecriture cse
                JOIN compta_compte cc ON
                cc.compte = cse.compte
                JOIN compta_journal cj ON
                cj.id = cse.JOURNAL
        WHERE
            (cse.debit + cse.credit)>0
          AND NOT EXISTS(
            SELECT
                rs.id
            FROM
                reportsolde rs
            WHERE
                rs.id = cse.id
        )
    )
GROUP BY compte,
         etat,
         libelle_compte,
         typecompte,
         mois,
         annee,
         chiffre3,
         chiffre2
ORDER BY
    chiffre3 ASC;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTA_REPORT" ("ID", "COMPTE", "LIBELLE_COMPTE", "DEBIT", "CREDIT", "DATY", "TYPECOMPTE", "MOIS", "ANNEE") AS
SELECT
    cse.ID,
    cse.compte,
    '-',
    CAST(sum(cse.debit) AS number(20,2)) AS debit,
    CAST(sum(cse.credit) AS number(20,2)) AS credit,
    NULL,
    1,
    12,
    cse.exercice
FROM
    compta_sous_ecriture cse,
    compta_compte cc,
    compta_journal cj
WHERE cse.compte = cc.compte
  AND cse.journal = cj.ID
  AND cse.etat = 11
  AND cc.typecompte = '1'
  AND cc.CLASSY  NOT IN ('6', '7')
GROUP BY
    cse.ID,
    cse.compte,
    cse.exercice;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTA_SOUSECRITURE_CREE2" ("ID", "NUMERO", "COMPTE", "JOURNAL", "IDJOURNAL", "ECRITURE", "DATY", "CREDIT", "DEBIT", "DATECOMPTABLE", "EXERCICE", "REMARQUE", "ETAT", "HORSEXERCICE", "OD", "ORIGINE", "TIERS", "LIBELLEPIECE", "COMPTE_AUX", "FOLIO", "ANALYTIQUE") AS
select
    sousecr.id,
    cpt.LIBELLE,
    cpt.COMPTE,
    jrn.val||'| '|| jrn.DESCE as JOURNAL,
    jrn.id,
    sousecr.REMARQUE ,
    SOUSECR.DATY ,
    sousecr.CREDIT,
    sousecr.DEBIT,
    sousecr.DATY as DATECOMPTABLE,
    SOUSECR.EXERCICE,
    sousecr.REMARQUE,
    sousecr.ETAT ,
    cast(0 as number) AS HORSEXERCICE,
    cast('-' as varchar(50)) AS OD,
    cast('' as varchar(50)) AS ORIGINE,
    cast('' as varchar2(50)) as tiers,
    sousecr.LIBELLEPIECE,
    cast('' as varchar(100)) as RAISONSOCIAL ,
    sousecr.folio,
    SOUSECR.ANALYTIQUE
from
    COMPTA_SOUS_ECRITURE sousecr
        join COMPTA_COMPTE cpt on  sousecr.COMPTE = cpt.COMPTE
        join COMPTA_JOURNAL jrn on sousecr.JOURNAL = jrn.ID
where sousecr.etat = 1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTA_SOUSECRITURE_ECRITURE" ("ID", "NUMERO", "COMPTE", "JOURNAL", "IDJOURNAL", "ECRITURE", "DATY", "CREDIT", "DEBIT", "DATECOMPTABLE", "EXERCICE", "REMARQUE", "ETAT", "HORSEXERCICE", "OD", "ORIGINE", "TIERS", "LIBELLEPIECE", "COMPTE_AUX", "RAISONSOCIAL", "FOLIO", "LETTRAGE", "ANALYTIQUE", "IDOBJET") AS
select
    sousecr.id,
    cpt.LIBELLE,
    cpt.COMPTE,
    jrn.val||'| '|| jrn.DESCE ,
    jrn.id,
    sousecr.REMARQUE as DESIGNATION,
    sousecr.DATY,
    sousecr.CREDIT,
    sousecr.DEBIT,
    sousecr.DATY AS DATECOMPTABLE,
    sousecr.EXERCICE,
    sousecr.REMARQUE,
    sousecr.ETAT,
    cast(0 as number) AS HORSEXERCICE,
    cast('-' as varchar(50)) AS OD,
    cast('' as varchar(50)) AS ORIGINE,
    cast('' as varchar2(50)) as tiers,
    sousecr.LIBELLEPIECE,
    sousecr.COMPTE_AUX,
    cast('' as varchar(100)) as RAISONSOCIAL ,
    sousecr.folio ,
    sousecr.LETTRAGE ,
    ANALYTIQUE,
    ce.IDOBJET
from
    COMPTA_SOUS_ECRITURE sousecr
        join COMPTA_COMPTE cpt on  sousecr.COMPTE = cpt.COMPTE
        join COMPTA_JOURNAL jrn on sousecr.JOURNAL = jrn.ID
        JOIN COMPTA_ECRITURE ce ON ce.id = sousecr.IDMERE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTA_SOUSECRITURE_LETTRE" ("ID", "NUMERO", "COMPTE", "JOURNAL", "IDJOURNAL", "ECRITURE", "DATY", "CREDIT", "DEBIT", "DATECOMPTABLE", "EXERCICE", "REMARQUE", "ETAT", "IDMERE", "HORSEXERCICE", "OD", "ORIGINE", "TIERS", "LIBELLEPIECE", "COMPTE_AUX", "RAISONSOCIAL", "FOLIO", "LETTRAGE", "ANALYTIQUE", "IDVENTE", "LETTRE", "MONTANT") AS
SELECT
    lib.ID,lib.NUMERO,lib.COMPTE,lib.JOURNAL,lib.IDJOURNAL,lib.ECRITURE,lib.DATY,lib.CREDIT,lib.DEBIT,lib.DATECOMPTABLE,lib.EXERCICE,lib.REMARQUE,lib.ETAT,lib.IDMERE,lib.HORSEXERCICE,lib.OD,lib.ORIGINE,lib.TIERS,lib.LIBELLEPIECE,lib.COMPTE_AUX,lib.RAISONSOCIAL,lib.FOLIO,lib.LETTRAGE,lib.ANALYTIQUE,
    COALESCE(mtc.IDORIGINE, ecr.IDOBJET) AS IDVENTE,CLTR.lettre,
     CASE
        WHEN NVL(lib.DEBIT, 0) = 0 THEN lib.CREDIT
        WHEN NVL(lib.CREDIT, 0) = 0 THEN lib.DEBIT
        ELSE lib.DEBIT - lib.CREDIT
    END AS MONTANT
FROM
    COMPTA_SOUSECRITURE_LIB lib
        JOIN COMPTA_ECRITURE ecr ON lib.IDMERE = ecr.ID
        LEFT JOIN MOUVEMENTCAISSE mtc ON ecr.IDOBJET = mtc.ID
        LEFT JOIN compta_lettrage cltr on cltr.id=lib.lettrage
     WHERE lib.etat=11
order by IDVENTE DESC;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTA_SOUSECRITURE_LETTRE2" ("ID", "NUMERO", "COMPTE", "JOURNAL", "IDJOURNAL", "ECRITURE", "DATY", "CREDIT", "DEBIT", "DATECOMPTABLE", "EXERCICE", "REMARQUE", "ETAT", "IDMERE", "HORSEXERCICE", "OD", "ORIGINE", "TIERS", "LIBELLEPIECE", "COMPTE_AUX", "RAISONSOCIAL", "FOLIO", "LETTRAGE", "ANALYTIQUE", "MONTANTRESTE", "IDVENTE", "MOTSCLESSS") AS
SELECT SQ.ID,SQ.NUMERO,SQ.COMPTE,SQ.JOURNAL,SQ.IDJOURNAL,SQ.ECRITURE,SQ.DATY,SQ.CREDIT,SQ.DEBIT,SQ.DATECOMPTABLE,SQ.EXERCICE,SQ.REMARQUE,SQ.ETAT,SQ.IDMERE,SQ.HORSEXERCICE,SQ.OD,SQ.ORIGINE,SQ.TIERS,SQ.LIBELLEPIECE,SQ.COMPTE_AUX,SQ.RAISONSOCIAL,SQ.FOLIO,SQ.LETTRAGE,SQ.ANALYTIQUE,SQ.MONTANTRESTE,SQ.IDVENTE,
       (NVL(TO_CHAR(ID),'') || ' | ' || NVL(TO_CHAR(NUMERO),'') || ' | ' || NVL(TO_CHAR(COMPTE),'') || ' | ' || NVL(TO_CHAR(JOURNAL),'') || ' | ' || NVL(TO_CHAR(IDJOURNAL),'') || ' | ' || NVL(TO_CHAR(ECRITURE),'') || ' | ' || NVL(TO_CHAR(DATY,'YYYY-MM-DD HH24:MI:SS'),'') || ' | ' || NVL(TO_CHAR(CREDIT),'') || ' | ' || NVL(TO_CHAR(DEBIT),'') || ' | ' || NVL(TO_CHAR(DATECOMPTABLE,'YYYY-MM-DD HH24:MI:SS'),'') || ' | ' || NVL(TO_CHAR(EXERCICE),'') || ' | ' || NVL(TO_CHAR(REMARQUE),'') || ' | ' || NVL(TO_CHAR(ETAT),'') || ' | ' || NVL(TO_CHAR(IDMERE),'') || ' | ' || NVL(TO_CHAR(HORSEXERCICE),'') || ' | ' || NVL(TO_CHAR(OD),'') || ' | ' || NVL(TO_CHAR(ORIGINE),'') || ' | ' || NVL(TO_CHAR(TIERS),'') || ' | ' || NVL(TO_CHAR(LIBELLEPIECE),'') || ' | ' || NVL(TO_CHAR(COMPTE_AUX),'') || ' | ' || NVL(TO_CHAR(RAISONSOCIAL),'') || ' | ' || NVL(TO_CHAR(FOLIO),'') || ' | ' || NVL(TO_CHAR(LETTRAGE),'') || ' | ' || NVL(TO_CHAR(ANALYTIQUE),'') || ' | ' || NVL(TO_CHAR(MONTANTRESTE),'') || ' | ' || NVL(TO_CHAR(IDVENTE),'')) AS MOTSCLESSS
FROM (

SELECT
             lib.ID, lib.NUMERO, lib.COMPTE, lib.JOURNAL, lib.IDJOURNAL,
             lib.ECRITURE, lib.DATY, lib.CREDIT, lib.DEBIT, lib.DATECOMPTABLE,
             lib.EXERCICE, lib.REMARQUE, lib.ETAT, lib.IDMERE,
             lib.HORSEXERCICE, lib.OD, lib.ORIGINE, lib.TIERS,
             lib.LIBELLEPIECE, lib.COMPTE_AUX, lib.RAISONSOCIAL,
             lib.FOLIO, lib.LETTRAGE, lib.ANALYTIQUE,
             cast(nvl(V2.MONTANTTTC, 0) - nvl(mv.montant, 0) - nvl(ACG.MONTANTTTCAR-acg.MONTANTPAYEAR, 0) AS number(30, 5)) AS MONTANTRESTE,
             v.id as idVente
         FROM COMPTA_SOUSECRITURE_LIB_2 lib
                  JOIN VENTE v ON v.ID = lib.IDOBJET
                  JOIN VENTEMONTANTLEGER v2 ON v2.ID = v.ID
         		  LEFT JOIN LIAISONPAIEMENTTOTAL mv ON v.id = mv.id2
                  LEFT JOIN AVOIRFCMONTANT ACG on ACG.IDVENTE = v.ID
                  
                  UNION ALL
                  
                  
         -- CAS 2 : MOUVEMENTCAISSE ? VENTE
         SELECT
             lib.ID, lib.NUMERO, lib.COMPTE, lib.JOURNAL, lib.IDJOURNAL,
             lib.ECRITURE, lib.DATY, lib.CREDIT, lib.DEBIT, lib.DATECOMPTABLE,
             lib.EXERCICE, lib.REMARQUE, lib.ETAT, lib.IDMERE,
             lib.HORSEXERCICE, lib.OD, mvt.IDORIGINE, lib.TIERS,
             lib.LIBELLEPIECE, lib.COMPTE_AUX, lib.RAISONSOCIAL,
             lib.FOLIO, lib.LETTRAGE, lib.ANALYTIQUE,
             0 AS MONTANTRESTE,
             mvt.IDORIGINE as idVente
         FROM COMPTA_SOUSECRITURE_LIB_2 lib
                  JOIN MOUVEMENTCAISSE mvt ON mvt.ID = lib.IDOBJET
                  WHERE  EXISTS (SELECT 1 FROM VENTE v WHERE v.ID = mvt.IDORIGINE)

         UNION ALL

         -- CAS 3 : FACTURE FOURNISSEUR
         SELECT
             lib.ID, lib.NUMERO, lib.COMPTE, lib.JOURNAL, lib.IDJOURNAL,
             lib.ECRITURE, lib.DATY, lib.CREDIT, lib.DEBIT, lib.DATECOMPTABLE,
             lib.EXERCICE, lib.REMARQUE, lib.ETAT, lib.IDMERE,
             lib.HORSEXERCICE, lib.OD, lib.ORIGINE, lib.TIERS,
             lib.LIBELLEPIECE, lib.COMPTE_AUX, lib.RAISONSOCIAL,
             lib.FOLIO, lib.LETTRAGE, lib.ANALYTIQUE,
             CAST(nvl((cast(f3.MONTANTTTC-nvl(mv.debit,0) AS number(30,5)) * cast(nvl(f3.tauxdechange,0) AS  number(30,5))),0)  AS NUMBER(30,5))  AS MONTANTRESTE,
             v.ID as idVente
         FROM COMPTA_SOUSECRITURE_LIB_2 lib
                  JOIN FACTUREFOURNISSEUR  v ON v.ID = lib.IDOBJET
                  JOIN FACTUREFOURNISSEURMONTANT f3 ON v.ID = f3.id
    			  LEFT JOIN mouvementcaisseGroupeFacture mv ON v.id=mv.IDORIGINE

         UNION ALL

         -- CAS 4 : ECRITURE COMPTABLE SANS LIEN AVEC VENTE NI FACTURE FOURNISSEUR
         SELECT
             lib.ID, lib.NUMERO, lib.COMPTE, lib.JOURNAL, lib.IDJOURNAL,
             lib.ECRITURE, lib.DATY, lib.CREDIT, lib.DEBIT, lib.DATECOMPTABLE,
             lib.EXERCICE, lib.REMARQUE, lib.ETAT, lib.IDMERE,
             lib.HORSEXERCICE, lib.OD, lib.ORIGINE, lib.TIERS,
             lib.LIBELLEPIECE, lib.COMPTE_AUX, lib.RAISONSOCIAL,
             lib.FOLIO, lib.LETTRAGE, lib.ANALYTIQUE,
             NULL AS MONTANTRESTE,
             NULL AS idVente
         FROM COMPTA_SOUSECRITURE_LIB_2 lib
         WHERE NOT  EXISTS (SELECT 1 FROM VENTE v WHERE v.ID = lib.IDOBJET)
         AND NOT EXISTS (SELECT 1 FROM FACTUREFOURNISSEUR f WHERE f.ID = lib.IDOBJET )
                ) SQ
order by IDVENTE desc;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTA_SOUSECRITURE_LIB" ("ID", "NUMERO", "COMPTE", "JOURNAL", "IDJOURNAL", "ECRITURE", "DATY", "CREDIT", "DEBIT", "DATECOMPTABLE", "EXERCICE", "REMARQUE", "ETAT", "IDMERE", "HORSEXERCICE", "OD", "ORIGINE", "TIERS", "LIBELLEPIECE", "COMPTE_AUX", "RAISONSOCIAL", "FOLIO", "LETTRAGE", "ANALYTIQUE", "COMPTEAUXILIAIRE", "COMPTE_AUXLIB", "IDOBJET") AS
select
    sousecr.id,
    cpt.LIBELLE as numero,
    cpt.COMPTE,
    jrn.val as journal ,
    jrn.id as idjournal,
    sousecr.REMARQUE as ecriture,
    sousecr.DATY,
    sousecr.CREDIT,
    sousecr.DEBIT,
    sousecr.DATY AS DATECOMPTABLE,
    sousecr.EXERCICE,
    sousecr.REMARQUE,
    sousecr.ETAT,
    sousecr.idmere,
    cast(0 as number) AS HORSEXERCICE,
    cast('-' as varchar(50)) AS OD,
    CE.ORIGINE AS ORIGINE,
    cast('' as varchar2(50)) as tiers,
    sousecr.LIBELLEPIECE,
    sousecr.COMPTE_AUX,
    cast('' as varchar(100)) as RAISONSOCIAL ,
    sousecr.folio ,
    sousecr.LETTRAGE ,
    sousecr.ANALYTIQUE,
    te.COMPTEAUXILIAIRE as compteauxiliaire,
    te.NOM as compte_auxlib,
    ce.IDOBJET as idobjet
from
    COMPTA_SOUS_ECRITURE sousecr
        join COMPTA_COMPTE cpt on  sousecr.COMPTE = cpt.COMPTE
        join COMPTA_JOURNAL jrn on sousecr.JOURNAL = jrn.ID
        left join tiersensemble te on sousecr.COMPTE_AUX=te.id
        LEFT JOIN COMPTA_ECRITURE CE ON CE.ID = sousecr.idMERE;

