CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTA_SOUSECRITURE_LIB_J" ("ID", "NUMERO", "COMPTE", "JOURNAL", "IDJOURNAL", "ECRITURE", "DATY", "CREDIT", "DEBIT", "DATECOMPTABLE", "EXERCICE", "REMARQUE", "ETAT", "IDMERE", "HORSEXERCICE", "OD", "ORIGINE", "TIERS", "LIBELLEPIECE", "COMPTE_AUX", "RAISONSOCIAL", "FOLIO", "LETTRAGE", "ANALYTIQUE", "DESIGNATIONMERE", "JOUR", "MOIS", "ANNEE") AS
select cse."ID",cse."NUMERO",cse."COMPTE",cse."JOURNAL",cse."IDJOURNAL",cse."ECRITURE",cse."DATY",cse."CREDIT",cse."DEBIT",cse."DATECOMPTABLE",cse."EXERCICE",cse."REMARQUE",cse."ETAT",cse."IDMERE",cse."HORSEXERCICE",cse."OD",cse."ORIGINE",cse."TIERS",cse."LIBELLEPIECE",cse."COMPTE_AUX",cse."RAISONSOCIAL",cse."FOLIO",cse."LETTRAGE",cse."ANALYTIQUE",ce.DESIGNATION as designationmere,
       EXTRACT(DAY FROM cse.DATY)   AS jour,
       EXTRACT(MONTH FROM cse.DATY) AS mois,
       EXTRACT(YEAR FROM cse.DATY)  AS annee  from COMPTA_SOUSECRITURE_LIB cse join COMPTA_ECRITURE ce on cse.IDMERE=ce.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTA_SOUSECRITURE_SANSPG" ("ID", "NUMERO", "COMPTE", "JOURNAL", "IDJOURNAL", "ECRITURE", "DATY", "CREDIT", "DEBIT", "DATECOMPTABLE", "EXERCICE", "REMARQUE", "ETAT", "HORSEXERCICE", "OD", "ORIGINE", "TIERS", "LIBELLEPIECE", "COMPTE_AUX", "RAISONSOCIAL", "FOLIO", "LETTRAGE", "ANALYTIQUE", "IDOBJET", "IDMERE") AS
select
    sousecr.id,
    cpt.LIBELLE,
    cpt.COMPTE,
    jrn.val||'| '|| jrn.DESCE ,
    jrn.id,
    sousecr.REMARQUE as DESIGNATION,
    sousecr.DATY,
    sousecr.CREDIT,
    sousecr.DEBIT,
    sousecr.DATY AS DATECOMPTABLE,
    sousecr.EXERCICE,
    sousecr.REMARQUE,
    sousecr.ETAT,
    cast(0 as number) AS HORSEXERCICE,
    cast('-' as varchar(50)) AS OD,
    cast('' as varchar(50)) AS ORIGINE,
    cast('' as varchar2(50)) as tiers,
    sousecr.LIBELLEPIECE,
    sousecr.COMPTE_AUX,
    cast('' as varchar(100)) as RAISONSOCIAL ,
    sousecr.folio ,
    sousecr.LETTRAGE ,
    ANALYTIQUE,
    CASE
        WHEN ce.IDOBJET= pe.id THEN pe.idorigine
        ELSE ce.idobjet
        END
        AS idobjet,
      sousecr.IDMERE
from
    COMPTA_SOUS_ECRITURE sousecr
        join COMPTA_COMPTE cpt on  sousecr.COMPTE = cpt.COMPTE
        join COMPTA_JOURNAL jrn on sousecr.JOURNAL = jrn.ID
        JOIN COMPTA_ECRITURE ce ON ce.id = sousecr.IDMERE
        LEFT JOIN PERTEGAINIMPREVUE pe ON ce.idobjet=pe.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTA_SOUSECRITURE_VISEE" ("ID", "NUMERO", "COMPTE", "JOURNAL", "IDJOURNAL", "ECRITURE", "DATY", "CREDIT", "DEBIT", "DATECOMPTABLE", "EXERCICE", "REMARQUE", "ETAT", "HORSEXERCICE", "OD", "ORIGINE", "TIERS", "LIBELLEPIECE", "COMPTE_AUX", "FOLIO", "ANALYTIQUE") AS
select
    sousecr.id,
    cpt.LIBELLE,
    cpt.COMPTE,
    jrn.val||'| '|| jrn.DESCE ,
    jrn.id,
    sousecr.REMARQUE as DESIGNATION,
    sousecr.DATY,
    sousecr.CREDIT,
    sousecr.DEBIT,
    sousecr.DATY AS DATECOMPTABLE,
    sousecr.EXERCICE,
    sousecr.REMARQUE,
    sousecr.ETAT,
    cast(0 as number) AS HORSEXERCICE,
    cast('-' as varchar(50)) AS OD,
    cast('' as varchar(50)) AS ORIGINE,
    cast('' as varchar2(50)) as tiers,
    sousecr.LIBELLEPIECE,
    cast('' as varchar(100)) as RAISONSOCIAL ,
    sousecr.folio,
    sousecr.ANALYTIQUE
from
    COMPTA_SOUS_ECRITURE sousecr
        join COMPTA_COMPTE cpt on  sousecr.COMPTE = cpt.COMPTE
        join COMPTA_JOURNAL jrn on sousecr.JOURNAL = jrn.ID
where sousecr.etat = 11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTA_SOUS_ECRITURE_ANAL" ("ID", "COMPTE", "DEBIT", "CREDIT", "LIBELLEPIECE", "REMARQUE", "IDMERE", "REFERENCE_ENGAGEMENT", "COMPTE_AUX", "LETTRAGE", "JOURNAL", "EXERCICE", "ETAT", "DATY", "FOLIO") AS
SELECT cse.id, cse.analytique as compte, cse.debit, cse.credit,cse.libellepiece, cse.remarque,cse.idMere, cse.reference_engagement, cse.compte_aux, lettre.lettre as lettrage,cj.val as journal,cse.exercice, cse.etat,cse.daty, cse.folio FROM COMPTA_SOUS_ECRITURE cse
join COMPTA_JOURNAL_VIEW cj on cj.id = cse.journal
join compta_compte cc on cse.analytique=cc.compte
join compta_type_compte ctc on cc.typecompte=ctc.id
left join COMPTA_LETTRAGE lettre on lettre.id = cse.lettrage;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTA_SOUS_ECRITURE_AUX" ("ID", "COMPTE", "DEBIT", "CREDIT", "REMARQUE", "LIBELLEPIECE", "IDMERE", "REFERENCE_ENGAGEMENT", "COMPTE_AUX", "LETTRAGE", "JOURNAL", "EXERCICE", "ETAT", "DATY", "FOLIO", "ANALYTIQUE", "SOURCE") AS
SELECT
    cse.ID,
    cse.COMPTE,
    cse.DEBIT,
    cse.CREDIT,
    cse.REMARQUE,
    cse.LIBELLEPIECE,
    cse.IDMERE,
    cse.REFERENCE_ENGAGEMENT,
    t.COMPTEAUXILIAIRE AS COMPTE_AUX,
    cse.LETTRAGE,
    cse.JOURNAL,
    cse.EXERCICE,
    cse.ETAT,
    cse.DATY,
    cse.FOLIO,
    cse.ANALYTIQUE,
    cse.SOURCE
FROM COMPTA_SOUS_ECRITURE cse
LEFT JOIN TIERS t ON cse.COMPTE_AUX = t.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTA_SOUS_ECRITURE_CSEMF" ("ID", "COMPTE", "DEBIT", "CREDIT", "REMARQUE", "LIBELLEPIECE", "IDMERE", "REFERENCE_ENGAGEMENT", "COMPTE_AUX", "LETTRAGE", "JOURNAL", "EXERCICE", "ETAT", "DATY", "FOLIO", "ANALYTIQUE", "SOURCE", "ORIGINE", "MONTANT") AS
SELECT 
    CSE.ID,
    CSE.COMPTE,
    CSE.DEBIT,
    CSE.CREDIT,
    CSE.REMARQUE,
    CSE.LIBELLEPIECE,
    CSE.IDMERE,
    CSE.REFERENCE_ENGAGEMENT,
    CSE.COMPTE_AUX,
    CSE.LETTRAGE,
    CSE.JOURNAL,
    CSE.EXERCICE,
    CSE.ETAT,
    CSE.DATY,
    CSE.FOLIO,
    CSE.ANALYTIQUE,
    CSE.SOURCE,
    CE.ORIGINE,
     CASE
        WHEN NVL(CSE.DEBIT, 0) = 0 THEN CSE.CREDIT
        WHEN NVL(CSE.CREDIT, 0) = 0 THEN CSE.DEBIT
        ELSE CSE.DEBIT - CSE.CREDIT
    END AS MONTANT
FROM COMPTA_SOUS_ECRITURE CSE
LEFT JOIN COMPTA_ECRITURE CE
    ON CE.ID = CSE.IDMERE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTA_SOUS_ECRITURE_GEN" ("ID", "COMPTE", "DEBIT", "CREDIT", "LIBELLEPIECE", "REMARQUE", "IDMERE", "REFERENCE_ENGAGEMENT", "COMPTE_AUX", "LETTRAGE", "JOURNAL", "EXERCICE", "ETAT", "DATY", "FOLIO") AS
SELECT cse.id, cse.compte, cse.debit, cse.credit,cse.libellepiece, cse.remarque,cse.idMere, cse.reference_engagement, cse.compte_aux, lettre.lettre as lettrage,cj.val as journal,cse.exercice, cse.etat,cse.daty, cse.folio FROM COMPTA_SOUS_ECRITURE cse
join COMPTA_JOURNAL_VIEW cj on cj.id = cse.journal
join compta_compte cc on cse.compte=cc.compte
join compta_type_compte ctc on cc.typecompte=ctc.id
left join COMPTA_LETTRAGE lettre on lettre.id = cse.lettrage;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTA_VIEW_FOLIO" ("ID", "JOURNAL", "MOIS", "EXERCICE", "COMPTE", "FOLIO", "TYPECOMPTE") AS
SELECT
    ' ' AS id ,
    ' ' AS journal ,
    ' ' AS mois ,
    ' ' AS exercice,
    ' ' AS compte ,
    ' ' AS folio ,
    ' ' AS typeCompte
FROM
    dual;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTE6" ("ID", "COMPTE", "LIBELLE", "TYPECOMPTE", "CLASSY", "ANALYTIQUE_OBLI", "IDJOURNAL") AS
SELECT "ID","COMPTE","LIBELLE","TYPECOMPTE","CLASSY","ANALYTIQUE_OBLI","IDJOURNAL"
FROM COMPTA_COMPTE c
WHERE compte LIKE '6%';

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTEURCPL" ("ID", "DATY", "IDLIGNE", "ANCIEN", "VALEUR", "ECART", "IDCATEGORIE", "IDLIGNELIB", "IDCATEGORIELIB", "ETAT", "ETATLIB", "IDMAGASIN", "IDMAGASINLIB") AS
SELECT
    c.id,
    c.daty,
    c.idligne,
    c.ancien,
    c.valeur,
    c.ecart,
    c.idcategorie,
    l.val        AS idlignelib,
    cc.libelle       AS idcategorielib,
    c.etat,
       CASE
	        WHEN c.ETAT = 0
	            THEN 'ANNUL&Eacute;E'
	        WHEN c.ETAT = 1
	            THEN 'CR&Eacute;&Eacute;E'
	        WHEN c.ETAT = 11
	            THEN 'VIS&Eacute;(E) par Chef de Fabrication'
	        WHEN c.ETAT = 3
	            THEN 'VIS&Eacute;(E) par Releveur'
	        END AS etatlib,
    c.IDMAGASIN,
    m.VAL AS idMagasinLib
FROM compteurmaintenance c
         LEFT JOIN ligne l
                   ON l.id = c.idligne
         LEFT JOIN AS_INGREDIENTS_CONSOMMABLE cc
                   ON cc.id = c.idcategorie
         LEFT JOIN MAGASIN2 m ON m.ID = c.IDMAGASIN;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTEURCPLRECENT" ("ID", "DATY", "IDLIGNE", "VALEUR", "ECART", "IDCATEGORIE", "IDMAGASIN", "ETAT", "ANCIEN", "IDLIGNELIB", "IDCATEGORIELIB", "IDMAGASINLIB", "RN") AS
SELECT "ID","DATY","IDLIGNE","VALEUR","ECART","IDCATEGORIE","IDMAGASIN","ETAT","ANCIEN","IDLIGNELIB","IDCATEGORIELIB","IDMAGASINLIB","RN"
FROM (
    SELECT 
        cm.ID,
        cm.DATY,
        cm.IDLIGNE,
        cm.VALEUR,
        cm.ECART,
        cm.IDCATEGORIE,
        cm.IDMAGASIN,
        cm.ETAT,
        cm.ANCIEN,
        cm.IDLIGNELIB ,
        cm.IDCATEGORIELIB ,
        cm.IDMAGASINLIB ,
        ROW_NUMBER() OVER (
            PARTITION BY cm.IDLIGNE, cm.IDCATEGORIE, cm.IDMAGASIN
            ORDER BY cm.DATY DESC
        ) AS rn
        
    FROM CompteurCPL cm
)
WHERE rn = 1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTEURCPLRECENTELECTRICITE" ("ID", "DATY", "IDLIGNE", "VALEUR", "ECART", "IDCATEGORIE", "IDMAGASIN", "ETAT", "ANCIEN", "REMARQUE", "HEURE", "IDMACHINE", "IDMERE", "LIGNE", "CATEGORIELIB", "MAGASINLIB", "MACHINELIB", "LIGNELIB", "RN") AS
SELECT ID,DATY,IDLIGNE,VALEUR,ECART,IDCATEGORIE,IDMAGASIN,ETAT,ANCIEN,
       REMARQUE,HEURE,IDMACHINE,IDMERE,LIGNE,CATEGORIELIB,MAGASINLIB,
       MACHINELIB,LIGNELIB,RN
FROM (
    SELECT
        cm.ID,
        cm.DATY,
        cm.IDLIGNE,
        cm.VALEUR,
        cm.ECART,
        cm.IDCATEGORIE,
        cm.IDMAGASIN,
        cm.ETAT,
        cm.ANCIEN,
        cm.REMARQUE,
        cm.HEURE,
        cm.IDMACHINE,
        cm.IDMERE,
        cm.LIGNE,
        cm.CATEGORIELIB,
        cm.MAGASINLIB,
        cm.MACHINELIB,
        cm.LIGNELIB,
        ROW_NUMBER() OVER (
            PARTITION BY cm.IDLIGNE, cm.IDCATEGORIE, cm.IDMAGASIN
            ORDER BY cm.DATY DESC
        ) AS rn

    FROM COMPTEURELECTRICITECPL cm
)
WHERE rn = 1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTEURELECTRICITECPL" ("ID", "DATY", "IDLIGNE", "VALEUR", "ECART", "IDCATEGORIE", "IDMAGASIN", "ETAT", "ANCIEN", "REMARQUE", "HEURE", "IDMACHINE", "IDMERE", "LIGNE", "CATEGORIELIB", "MAGASINLIB", "MACHINELIB", "LIGNELIB") AS
SELECT c2.ID,c2.DATY,c2.IDLIGNE,c2.VALEUR,c2.ECART,c2.IDCATEGORIE,c2.IDMAGASIN,c2.ETAT,c2.ANCIEN,c2.REMARQUE,c2.HEURE
  ,c2.IDMACHINE,c2.IDMERE, c.LIGNE   ,ai.libelle as CATEGORIELIB, m2.val AS MAGASINLIB,
  aim.libelle AS MACHINELIB,
  l.val AS LIGNELIB
  FROM COMPTEURELECTRICITEMERE c
	JOIN COMPTEURELECTRICITE c2 ON c.ID = c2.IDMERE
	LEFT JOIN as_ingredients ai ON ai.id = c2.IDCATEGORIE
	LEFT JOIN magasin2 m2 ON m2.id = c2.IDMAGASIN
	LEFT JOIN as_ingredient_machine aim ON aim.id = c2.IDMACHINE
	LEFT JOIN ligne l ON l.id = c2.IDLIGNE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTEURELECTRICITELIB" ("ID", "DATY", "IDLIGNE", "VALEUR", "ECART", "IDCATEGORIE", "IDMAGASIN", "ETAT", "ANCIEN", "REMARQUE", "HEURE", "IDMACHINE", "IDMERE", "IDLIGNELIB", "IDMACHINELIB", "IDCATEGORIELIB", "PU", "MONTANT") AS
SELECT
    ce.ID,ce.DATY,ce.IDLIGNE,ce.VALEUR,ce.ECART,ce.IDCATEGORIE,ce.IDMAGASIN,ce.ETAT,ce.ANCIEN,ce.REMARQUE,ce.HEURE,ce.IDMACHINE,ce.IDMERE,
    l.VAL AS IdLigneLib,
    m.LIBELLE AS IdMachineLib,
    cat.LIBELLE AS IdCategorieLib,
    cat.pu AS pu,
    cat.pu * ce.ECART AS montant
FROM CompteurElectricite ce
         LEFT JOIN Ligne l ON ce.IdLigne = l.id
         LEFT JOIN AS_INGREDIENT_MACHINE m ON ce.IdMachine = m.ID
         LEFT JOIN AS_INGREDIENTS_CONSOMMABLE cat ON ce.IdCategorie = cat.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTEURELECTRICITEMERELIB" ("ID", "DATY", "LIGNE", "REMARQUE", "ETAT", "LIGNELIB", "CONSOMMATION", "MONTANT", "ETATLIB") AS
SELECT
    c.ID,
    c.DATY,
    c.LIGNE,
    c.REMARQUE,
    c.ETAT,
    l.VAL AS LIGNELIB,
    NVL(f.CONSOMMATION, 0) AS CONSOMMATION,
    NVL(f.MONTANT, 0) AS MONTANT,
    CASE
        WHEN c.ETAT = 0
            THEN 'ANNUL&Eacute;E'
        WHEN c.ETAT = 1
            THEN 'CR&Eacute;&Eacute;E'
        WHEN c.ETAT = 11
            THEN 'VIS&Eacute;(E) par Chef de Fabrication'
        WHEN c.ETAT = 3
            THEN 'VIS&Eacute;(E) par Releveur'
        END AS etatlib
FROM
    COMPTEURELECTRICITEMERE c
        LEFT JOIN LIGNE l
                  ON l.ID = c.LIGNE
        LEFT JOIN (
            SELECT
                fe.IDMERE AS ID_MERE,
                SUM(fe.ECART)    AS CONSOMMATION,
                SUM(fe.MONTANT)    AS MONTANT
            FROM
                COMPTEURELECTRICITELIB fe
            GROUP BY
                fe.IDMERE
        ) f ON f.ID_MERE = c.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTEURLIB" ("ID", "NOMBRE", "IDFABRICATION", "IDMACHINE", "DATY", "HEURE", "DEBUT", "ETAT", "IDORIGINE", "IDFABRICATIONLIB", "IDMACHINELIB", "ETATLIB") AS
SELECT
	    c.ID,
	    c.NOMBRE,
	    c.IDFABRICATION,
	    c.IDMACHINE,
	    c.DATY,
	    c.HEURE,
	    c.DEBUT,
	    c.ETAT,
	    c.IDORIGINE,
	    f.LIBELLE AS idfabricationlib,
	    aim.INGREDIENTLIB AS idmachinelib,
	     CASE
	        WHEN c.ETAT = 0
	            THEN 'ANNUL&Eacute;E'
	        WHEN c.ETAT = 1
	            THEN 'CR&Eacute;&Eacute;E'
	        WHEN c.ETAT = 11
	            THEN 'VIS&Eacute;(E) par Chef de Fabrication'
	        WHEN c.ETAT = 3
	            THEN 'VIS&Eacute;(E) par Releveur'
	        END AS etatlib
	FROM COMPTEUR c
	         LEFT JOIN FABRICATION f ON f.id = c.idfabrication
	         LEFT JOIN AS_INGREDIENT_MACHINE aim    ON aim.id = c.idmachine;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTEURLIBANNULER" ("ID", "NOMBRE", "IDFABRICATION", "IDMACHINE", "DATY", "HEURE", "DEBUT", "ETAT", "IDORIGINE", "IDFABRICATIONLIB", "IDMACHINELIB", "ETATLIB") AS
SELECT 
"ID","NOMBRE","IDFABRICATION","IDMACHINE","DATY","HEURE","DEBUT","ETAT","IDORIGINE","IDFABRICATIONLIB","IDMACHINELIB","ETATLIB"
FROM COMPTEURLIB 
WHERE etat = 0;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTEURLIBCREER" ("ID", "NOMBRE", "IDFABRICATION", "IDMACHINE", "DATY", "HEURE", "DEBUT", "ETAT", "IDORIGINE", "IDFABRICATIONLIB", "IDMACHINELIB", "ETATLIB") AS
SELECT 
"ID","NOMBRE","IDFABRICATION","IDMACHINE","DATY","HEURE","DEBUT","ETAT","IDORIGINE","IDFABRICATIONLIB","IDMACHINELIB","ETATLIB"
FROM COMPTEURLIB 
WHERE etat = 1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTEURLIBVISER" ("ID", "NOMBRE", "IDFABRICATION", "IDMACHINE", "DATY", "HEURE", "DEBUT", "ETAT", "IDORIGINE", "IDFABRICATIONLIB", "IDMACHINELIB", "ETATLIB") AS
SELECT 
"ID","NOMBRE","IDFABRICATION","IDMACHINE","DATY","HEURE","DEBUT","ETAT","IDORIGINE","IDFABRICATIONLIB","IDMACHINELIB","ETATLIB"
FROM COMPTEURLIB 
WHERE etat = 11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTE_ANALYTIQUE" ("ID", "COMPTE", "LIBELLE", "TYPECOMPTE", "CLASSY", "ANALYTIQUE_OBLI", "IDJOURNAL", "CODEIMPOT") AS
select "ID","COMPTE","LIBELLE","TYPECOMPTE","CLASSY","ANALYTIQUE_OBLI","IDJOURNAL","CODEIMPOT" from COMPTA_COMPTE where TYPECOMPTE='3';

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMPTE_AUX" ("LIBELLE", "COMPTE") AS
select nom as libelle,COMPTEAUXILIAIRE as compte from CLIENT union select nom as libelle,COMPTEAUXILIAIRE as compte from FOURNISSEUR;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CONFIGPOIDS_LIB" ("ID", "POIDSMIN", "POIDSMAX", "PAS") AS
SELECT '1' AS "ID",
       1.0   AS "POIDSMIN",
       1.0   AS "POIDSMAX",
       1.0   AS "PAS"
FROM DUAL;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CONF_CNAPS" ("PLAFOND", "DATY") AS
SELECT
    ROUND(configuration.valmin * 1000, 2) AS plafond,
    NVL(configuration.daty, SYSDATE) AS daty
FROM configcnaps_plafond configuration
WHERE configuration.remarque = 'cnaps_plafond'
ORDER BY NVL(configuration.daty, SYSDATE);

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CONGECOLLECTIF_LIB" ("ID", "IDPERSONNEL", "MATRICULE", "IDFONCTION", "FONCTIONLIB", "IDTYPEDEMANDE", "TYPEDEMANDELIB", "TITRE", "HORAIRENORMAL", "HEUREDEPART", "HEUREARRIVE", "IDTYPEABSENCE", "TYPEABSENCELIB", "MOTIF", "NUMERO", "DESCE", "ETAT", "DATY", "DUREE", "DATEDEPART", "DATERETOUR", "OBSERVATION", "REMARQUE", "NOM", "PRENOM", "IDDIRECTION", "DIRECTIONLIB", "ETATLIB", "REFUSER", "RANGUSER", "IDREMPLACENTS", "REMPLACENTS", "MATRICULES", "DATEFIN", "PERSONNEL", "IDSUP", "AVENANT", "ANNULER", "SUPERIEUR", "MOTIFREFU", "WEEKENDDECOMPTELIB", "IDDEPARTEMENT", "DEPARTEMENTLIB") AS
SELECT
	ID,
	IDPERSONNEL,
	MATRICULE,
	IDFONCTION,
	FONCTIONLIB,
	IDTYPEDEMANDE,
	TYPEDEMANDELIB,
	TITRE,
	HORAIRENORMAL,
	HEUREDEPART,
	HEUREARRIVE,
	IDTYPEABSENCE,
	TYPEABSENCELIB,
	MOTIF,
	NUMERO,
	DESCE,
	ETAT,
	DATY,
	DUREE,
	DATEDEPART,
	DATERETOUR,
	OBSERVATION,
	REMARQUE,
	NOM,
	PRENOM,
	IDDIRECTION,
	DIRECTIONLIB,
	ETATLIB,
	REFUSER,
	RANGUSER,
	IDREMPLACENTS,
	REMPLACENTS,
	MATRICULES,
	DATEFIN,
	PERSONNEL,
	IDSUP,
	AVENANT,
	ANNULER,
	SUPERIEUR,
	MOTIFREFU,
	WEEKENDDECOMPTELIB,
	IDDEPARTEMENT,
	DEPARTEMENTLIB
FROM
	DEMANDE_LIBCOMPLET
WHERE
	idtypeabsence = 'TYPCOL0004';

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CONGEPRIS" ("ID", "IDPERSONNEL", "IDTYPEDEMANDE", "TITRE", "HORAIRENORMAL", "HEUREDEPART", "HEUREARRIVE", "IDTYPEABSENCE", "MOTIF", "NUMERO", "DESCE", "ETAT", "DATY", "DUREE", "DATEDEPART", "DATERETOUR", "OBSERVATION", "REMARQUE", "IDREMPLACENTS", "RESTE_CONGE", "DATEFIN") AS
SELECT demande.id,
       demande.idpersonnel,
       demande.idtypedemande,
       demande.titre,
       demande.horairenormal,
       demande.heuredepart,
       demande.heurearrive,
       demande.idtypeabsence,
       demande.motif,
       demande.numero,
       demande.desce,
       demande.etat,
       demande.daty,
       demande.duree,
       demande.datedepart,
       demande.dateretour,
       demande.observation,
       demande.remarque,
       demande.idremplacents,
       demande.reste_conge,
       demande.datefin
FROM demande
WHERE demande.etat = 11 AND demande.idtypeabsence = 'TYP000004';

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CONGEPRISGROUPBYPERS" ("IDPERSONNEL", "CONGE") AS
SELECT congepris.idpersonnel,
       sum(congepris.duree) AS conge
FROM congepris
GROUP BY congepris.idpersonnel;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CONGE_DROIT" ("ID", "IDPERSONNEL", "MOIS", "ANNEE", "CONGE", "ETAT") AS
SELECT 'CONG-' || pip.id AS id,
       pip.id AS idpersonnel,
       0 AS mois,
       0 AS annee,
       (round(pijm.jourconge * 2) / 2) AS conge,
       11 AS etat
FROM paie_info_personnel pip
         LEFT JOIN paie_info_jours_mois3 pijm ON pip.id = pijm.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CONGE_DROIT_LIB" ("ID", "IDPERSONNEL", "MOIS", "ANNEE", "CONGE", "ETAT", "MATRICULE", "ETATLIB") AS
SELECT cd.id,
       (lp.nom || ' ') || lp.prenom AS idpersonnel,
       cd.mois,
       cd.annee,
       cd.conge,
       cd.etat,
       lp.matricule,
       CASE
           WHEN cd.etat = 1 THEN 'CREE(E)'
           WHEN cd.etat = 11 THEN 'VISE(E)'
           WHEN cd.etat <= 0 THEN 'ANNULE(E)'
           ELSE NULL
           END AS etatlib
FROM conge_droit cd
         JOIN log_personnel_infocomplet lp ON lp.id = cd.idpersonnel;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CONGE_DROIT_LIBCOMPLET" ("ID", "IDPERSONNEL", "MOIS", "ANNEE", "CONGE", "ETAT", "IDPERSONNELLIB") AS
SELECT cd.id,
       cd.idpersonnel,
       cd.mois,
       cd.annee,
       cd.conge,
       cd.etat,
       (lp.nom || ' ') || lp.prenom AS idpersonnellib
FROM conge_droit cd
         JOIN log_personnel lp ON lp.id = cd.idpersonnel;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CONGE_DROIT_LIBCREE" ("ID", "IDPERSONNEL", "MOIS", "ANNEE", "CONGE", "ETAT", "MATRICULE", "ETATLIB") AS
SELECT conge_droit_lib.id,
       conge_droit_lib.idpersonnel,
       conge_droit_lib.mois,
       conge_droit_lib.annee,
       conge_droit_lib.conge,
       conge_droit_lib.etat,
       conge_droit_lib.matricule,
       conge_droit_lib.etatlib
FROM conge_droit_lib
WHERE conge_droit_lib.etat = 1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CONGE_DROIT_LIBTOUS" ("ID", "IDPERSONNEL", "MOIS", "ANNEE", "CONGE", "ETAT", "MATRICULE", "ETATLIB") AS
SELECT conge_droit_lib.id,
       conge_droit_lib.idpersonnel,
       conge_droit_lib.mois,
       conge_droit_lib.annee,
       conge_droit_lib.conge,
       conge_droit_lib.etat,
       conge_droit_lib.matricule,
       conge_droit_lib.etatlib
FROM conge_droit_lib;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CONGE_DROIT_LIBVISE" ("ID", "IDPERSONNEL", "MOIS", "ANNEE", "CONGE", "ETAT", "MATRICULE", "ETATLIB") AS
SELECT conge_droit_lib.id,
       conge_droit_lib.idpersonnel,
       conge_droit_lib.mois,
       conge_droit_lib.annee,
       conge_droit_lib.conge,
       conge_droit_lib.etat,
       conge_droit_lib.matricule,
       conge_droit_lib.etatlib
FROM conge_droit_lib
WHERE conge_droit_lib.etat = 11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CONSOMMABLEMACHINELIB" ("ID", "IDMACHINE", "IDCONSOMMABLE", "IDTYPEMAINTENANCE", "QTE", "IDUNITE", "FREQUENCE", "IDTYPEMAINTENANCELIB", "IDMACHINELIB", "IDCONSOMMABLELIB", "IDUNITELIB", "FREQUENCELIB") AS
SELECT
    c."ID",c."IDMACHINE",c."IDCONSOMMABLE",c."IDTYPEMAINTENANCE",c."QTE",c."IDUNITE",c."FREQUENCE",
    tm.VAL AS idTypeMaintenanceLib,
    aim.LIBELLE AS idMachineLib,
    ai.LIBELLE AS idConsommableLib,
    u.VAL AS idUniteLib,
    fr.VAL AS frequenceLib
FROM CONSOMMABLEMACHINE c
         LEFT JOIN TYPEMAINTENANCE tm ON tm.ID = c.IDTYPEMAINTENANCE
         LEFT JOIN UNITEMAINTENANCE fr ON fr.ID = c.frequence
         LEFT JOIN AS_INGREDIENTS ai ON ai.ID = c.idConsommable
         LEFT JOIN AS_UNITE u ON u.ID = c.idUnite
         LEFT JOIN AS_INGREDIENT_MAINTENANCE aim ON aim.ID = c.IDMACHINE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CONSOMMATIONDETAILSLIB" ("ID", "IDMERE", "IDINGREDIENTS", "QTE", "IDUNITE", "IDUNITELIB", "IDINGREDIENTSLIB") AS
SELECT
    c."ID",c."IDMERE",c."IDINGREDIENTS",c."QTE",c."IDUNITE",
    au.VAL AS idUniteLib,
    ai.LIBELLE AS idIngredientsLib
FROM CONSOMMATIONDETAILS c
         LEFT JOIN AS_UNITE au ON au.ID = c.IDUNITE
         LEFT JOIN AS_INGREDIENTS ai ON ai.ID = c.IDINGREDIENTS;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CONSOMMATIONLIB" ("ID", "DATY", "IDTYPEMAINTENANCE", "IDMACHINE", "DESCE", "ETAT", "IDTYPEMAINTENANCELIB", "IDMACHINELIB", "ETATLIB") AS
SELECT
    c."ID",c."DATY",c."IDTYPEMAINTENANCE",c."IDMACHINE",c."DESCE",c."ETAT",
    tm.VAL AS idTypeMaintenanceLib,
    aim.LIBELLE AS idMachineLib,
    CASE
        WHEN c.ETAT = 1 THEN 'CR&Eacute;&Eacute;E'
        WHEN c.ETAT = 11 THEN 'VIS&Eacute;E'
        WHEN c.ETAT = 0 THEN 'ANNUL&Eacute;E'
        END AS ETATLIB
FROM CONSOMMATION c
         LEFT JOIN TYPEMAINTENANCE tm ON tm.ID = c.IDTYPEMAINTENANCE
         LEFT JOIN AS_INGREDIENT_MAINTENANCE aim ON aim.ID = c.IDMACHINE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COUTSMAINTENANCE" ("IDMACHINE", "NOMMACHINE", "IDLIGNE", "IDLIGNELIB", "IDTRAVAUX", "DATY", "COUTTOTAL") AS
SELECT
    o.IDINGREDIENTS AS idMachine,
    aim.DESCRIPTIONOBJET AS nomMachine,
    l.ID AS IDLIGNE ,
    l.VAL AS IDLIGNELIB,
    tr.ID AS idTravaux,
    t.DATY ,
    CAST (tr.MONTANTTOTAL AS NUMBER(10,2)) AS CoutTotal
FROM TRAVAUX_RECAP tr
         LEFT JOIN TRAVAUX t
                   ON tr.id = t.ID
         LEFT JOIN ORDRETRAVAUXFILLE o
                   ON t.IDOFFILLE = o.id
         LEFT JOIN AS_INGREDIENT_MAINTENANCE aim
                   ON o.IDINGREDIENTS = aim.ID
         LEFT JOIN LIGNE l
                   ON aim.IDLIGNE = l.ID
WHERE o.IDINGREDIENTS IS NOT NULL;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COUT_FAB_PAR_OF" ("IDMERE", "DATYBESOIN", "INGREDIENTS", "COUTDEPRODUCTION") AS
SELECT 
    base.IDMERE,
    base.DATYBESOIN,
    base.IDINGREDIENTS AS INGREDIENTS,
    ROUND(
        SUM(
            CASE 
                WHEN base.QTEFABRIQUE = 0 OR base.QTEFABRIQUE IS NULL THEN 0
                ELSE base.MONTANTSORTIE / base.QTEFABRIQUE
            END
        ) , 2
    ) / 1000000 AS COUTDEPRODUCTION
FROM 
    OFFILLELIBSTOCK base
    JOIN OFAB fb ON fb.id = base.idmere AND fb.etat >= 11
GROUP BY 
    base.IDMERE,
    base.DATYBESOIN,
    base.IDINGREDIENTS
ORDER BY 
    base.IDMERE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COUT_FAB_PAR_OF_TEMP" ("IDMERE", "DATYBESOIN", "INGREDIENTS", "COUTDEPRODUCTION", "MOTSCLESSS") AS
SELECT SQ.IDMERE,SQ.DATYBESOIN,SQ.INGREDIENTS,CAST(SQ.COUTDEPRODUCTION AS NUMBER(30,5)) AS COUTDEPRODUCTION ,
	  (NVL(TO_CHAR(IDMERE),'') || ' | ' || NVL(TO_CHAR(DATYBESOIN,'YYYY-MM-DD HH24:MI:SS'),'') || ' | ' || NVL(TO_CHAR(INGREDIENTS),'') || ' | ' || NVL(TO_CHAR(COUTDEPRODUCTION),'')) AS MOTSCLESSS
	FROM (
	  SELECT 
	    base.IDMERE,
	    base.DATYBESOIN,
	    base.IDINGREDIENTS AS INGREDIENTS,
	    ROUND(
	        SUM(montantsortie) , 2
	    )  AS COUTDEPRODUCTION
	FROM 
	    OFFILLELIBSTOCK base
	    JOIN OFAB fb ON fb.id = base.idmere AND fb.etat >= 11
	GROUP BY 
	    base.IDMERE,
	    base.DATYBESOIN,
	    base.IDINGREDIENTS
	ORDER BY 
	    base.IDMERE
	 
	) SQ;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CV_LIB" ("ID", "NOMCANDIDAT", "PRENOMCANDIDAT", "TITRECV", "RESUMEPROFIL", "DATY", "IDFICHEPOSTE", "IDFICHEPOSTELIB", "ETATLIB") AS
SELECT
    c.ID,c.NOMCANDIDAT,c.PRENOMCANDIDAT,c.TITRECV,c.RESUMEPROFIL,c.DATY,c.IDFICHEPOSTE,
    f.TITRE AS idFichePosteLib,
    CASE
        WHEN f.ETAT = '1'  THEN 'Cree'
        WHEN f.ETAT = '11' THEN 'Valide'
        WHEN f.ETAT = '0'  THEN 'Annule'
        ELSE 'Inconnu'
    END AS ETATLIB
FROM CV c
LEFT JOIN FICHE_POSTE f ON f.ID = c.IDFICHEPOSTE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."DECALAGEPREVISION" ("ID", "IDPREVISION", "DEBIT", "CREDIT", "DATYNOUVEAU") AS
SELECT 
    ' ' AS id,
    ' ' AS idPrevision,
    CAST(0 AS NUMBER(30,2)) AS debit,
    CAST(0 AS NUMBER(30,2)) AS credit,
    CAST(null AS DATE) AS datyNouveau 
FROM dual;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."DECLARATIONTVALIB" ("ID", "DESIGNATION", "DATYDEBUT", "DATYFIN", "ETAT", "ETATLIB", "MONTANTPAYER", "PAYEMENTLIB") AS
SELECT
             de.id,
             de.designation,
             de.datyDebut,
             de.datyFin,
             de.etat,
             CASE
                 WHEN de.etat = 1 THEN 'Cree'
                 WHEN de.etat = 11 THEN 'Valide'
                 ELSE 'Inconnu'
                 END AS etatLib,
             nvl(mv.DEBIT,nvl(fd.MONTANTTTC,0)) as montantpayer,
             case
                 when mv.IDORIGINE is null then case when fd.IDBC='CREDIT' then 'Reporte' else 'Non paye' end
                 else 'Paye'
                 END as payementLib
         FROM DeclarationTVA de left join FACTUREDECLARATIONCPL fd on de.id=fd.IDOBJET left join mouvementcaisse mv on mv.IDORIGINE=fd.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."DECLARATIONTVA_VIDE" ("ID", "DESIGNATION", "DATYDEBUT", "DATYFIN", "ETAT", "MOIS", "ANNEE") AS
SELECT
	dtva.id,
	dtva.designation,
	dtva.datydebut,
	dtva.datyfin,
	dtva.etat,
	0 AS mois,
	0 AS annee
FROM
	DECLARATIONTVA dtva;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."DEMANDETRANSFERTCPL" ("ID", "DESIGNATION", "IDMAGASINDEPART", "IDMAGASINDEPARTLIB", "IDMAGASINARRIVE", "IDMAGASINARRIVELIB", "DATY", "ETAT", "IDOF", "CATEGORIEINGREDIENT", "CATEGORIEINGREDIENTLIB", "MONTANTQUANTITE", "ETATLIB") AS
SELECT
    t.ID ,
    t.DESIGNATION ,
    t.IDMAGASINDEPART ,
    m.VAL AS IDMAGASINDEPARTLIB,
    t.IDMAGASINARRIVE ,
    m2.VAL AS IDMAGASINARRIVELIB,
    t.DATY ,
    t.ETAT ,
    t.idof,
    t.CATEGORIEINGREDIENT,
    c.VAL  AS CATEGORIEINGREDIENTLIB,
    CAST(dfg.montantQuantite AS NUMBER(30,2)) AS montantQuantite,
    CASE
        WHEN t.ETAT = 0
            THEN 'Annul&eacute;'
        WHEN t.ETAT = 1
            THEN 'Cr&eacute;&eacute;'
        WHEN t.ETAT = 11
            THEN 'Vis&eacute;'
        END AS ETATLIB
FROM demandetransfert t
         LEFT JOIN MAGASINPOINT m ON m.ID = t.IDMAGASINDEPART
         LEFT JOIN MAGASINPOINT m2 ON m2.ID = t.IDMAGASINARRIVE
         LEFT JOIN CATEGORIEINGREDIENT c ON c.ID = t.CATEGORIEINGREDIENT
         LEFT JOIN DEMTRANSFILLEGROUPEMERE dfg ON dfg.IDDEMANDETRANSFERT = t.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."DEMANDETRANSFERTFILLECPL" ("ID", "IDDEMANDETRANSFERT", "IDDEMANDETRANSFERTLIB", "IDPRODUIT", "IDPRODUITLIB", "QUANTITE", "TYPESTOCK", "UNITE", "PU") AS
SELECT
    t.ID ,
    t.IDdemandetransfert ,
    t2.DESIGNATION AS IDdemandetransfertLIB,
    t.IDPRODUIT ,
    p.libelle AS IDPRODUITLIB,
    t.QUANTITE,
    p.TYPESTOCK,
    p.UNITE,
    CAST(p.PU AS NUMBER(30, 5)) AS PU
FROM demandetransfertfille t
         LEFT JOIN demandetransfert t2 ON t2.ID = t.IDdemandetransfert
         LEFT JOIN AS_INGREDIENTS  p ON p.ID = t.IDPRODUIT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."DEMANDETRAVAUX_CPL" ("ID", "IDENTITE", "IDSITUATION", "IDMACHINE", "DATY", "DATEBESOIN", "PRIORITE", "ESTEXISTANT", "DESCRIPTION", "ETAT", "IDDEPARTEMENT", "IDENTITELIB", "IDSITUATIONLIB", "IDMACHINELIB", "ESTEXISTANTLIB", "ETATLIB", "IDDEPARTEMENTMAINTENANCE", "IDDEPARTEMENTMAINTENANCELIB", "PRIORITELIB", "IDDEPARTEMENTLIB", "IDOTFILLE", "IDTYPEMAINTENANCE", "IDTYPEMAINTENANCELIB", "PERSONNELLIB", "MOTSCLESSS") AS
SELECT SQ.ID,SQ.IDENTITE,SQ.IDSITUATION,SQ.IDMACHINE,SQ.DATY,SQ.DATEBESOIN,SQ.PRIORITE,SQ.ESTEXISTANT,SQ.DESCRIPTION,SQ.ETAT,SQ.IDDEPARTEMENT,SQ.IDENTITELIB,SQ.IDSITUATIONLIB,SQ.IDMACHINELIB,SQ.ESTEXISTANTLIB,SQ.ETATLIB,SQ.IDDEPARTEMENTMAINTENANCE,SQ.IDDEPARTEMENTMAINTENANCELIB,SQ.PRIORITELIB,SQ.IDDEPARTEMENTLIB,SQ.IDOTFILLE,SQ.IDTYPEMAINTENANCE,SQ.IDTYPEMAINTENANCELIB,SQ.PERSONNELLIB,
       (NVL(TO_CHAR(ID),'') || ' | ' || NVL(TO_CHAR(IDENTITE),'') || ' | ' || NVL(TO_CHAR(IDSITUATION),'') || ' | ' || NVL(TO_CHAR(IDMACHINE),'') || ' | ' || NVL(TO_CHAR(DATY,'YYYY-MM-DD HH24:MI:SS'),'') || ' | ' || NVL(TO_CHAR(DATEBESOIN,'YYYY-MM-DD HH24:MI:SS'),'') || ' | ' || NVL(TO_CHAR(PRIORITE),'') || ' | ' || NVL(TO_CHAR(ESTEXISTANT),'') || ' | ' || NVL(TO_CHAR(DESCRIPTION),'') || ' | ' || NVL(TO_CHAR(ETAT),'') || ' | ' || NVL(TO_CHAR(IDDEPARTEMENT),'') || ' | ' || NVL(TO_CHAR(IDENTITELIB),'') || ' | ' || NVL(TO_CHAR(IDSITUATIONLIB),'') || ' | ' || NVL(TO_CHAR(IDMACHINELIB),'') || ' | ' || NVL(TO_CHAR(ESTEXISTANTLIB),'') || ' | ' || NVL(TO_CHAR(ETATLIB),'') || ' | ' || NVL(TO_CHAR(IDDEPARTEMENTMAINTENANCE),'') || ' | ' || NVL(TO_CHAR(IDDEPARTEMENTMAINTENANCELIB),'') || ' | ' || NVL(TO_CHAR(PRIORITELIB),'') || ' | ' || NVL(TO_CHAR(IDDEPARTEMENTLIB),'') || ' | ' || NVL(TO_CHAR(IDOTFILLE),'') || ' | ' || NVL(TO_CHAR(IDTYPEMAINTENANCE),'') || ' | ' || NVL(TO_CHAR(IDTYPEMAINTENANCELIB),'') || ' | ' || NVL(TO_CHAR(PERSONNELLIB),'')) AS MOTSCLESSS
FROM (
         SELECT
             dmd.ID, dmd.IDENTITE, dmd.IDSITUATION, dmd.IDMACHINE, dmd.DATY, dmd.DATEBESOIN, dmd.PRIORITE, dmd.ESTEXISTANT, dmd.DESCRIPTION, dmd.ETAT, dmd.IDDEPARTEMENT,
             e.VAL AS idEntiteLib,
             s.VAL AS idSituationLib,
             m.LIBELLE AS idMachineLib,
             CASE dmd.ESTEXISTANT
                 WHEN 0 THEN 'NON'
                 WHEN 1 THEN 'OUI'
                 ELSE 'Non specifie'
                 END AS estExistantLib,
             CASE dmd.ETAT
                 WHEN 1 THEN 'CR&Eacute;&Eacute;E'
                 WHEN 11 THEN 'VALID&Eacute;E' 
                 ELSE 'CR&Eacute;&Eacute;E'
                 END AS etatLib,
             d.id AS IDDEPARTEMENTMAINTENANCE,
             d.VAL AS IDDEPARTEMENTMAINTENANCELIB,
             pri.val AS prioritelib,
             departement.val AS IDDEPARTEMENTLIB,
             otf.ID AS idOtFille,
             pl.idtypemaintenance AS idtypemaintenance,
             tm.val AS idtypemaintenancelib,
             pers.NOMUSER as personnelLib
         FROM DEMANDETRAVAUX dmd
                  LEFT JOIN ENTITE e ON e.ID = dmd.IDENTITE
                  LEFT JOIN SITUATION s ON s.ID = dmd.IDSITUATION
                  LEFT JOIN AS_INGREDIENT_MAINTENANCE m ON m.ID = dmd.IDMACHINE
                  LEFT JOIN DEPARTEMENTMAINTENANCE d ON d.ID = dmd.IDDEPARTEMENTMAINTENANCE
                  LEFT JOIN PRIORITE pri ON dmd.priorite = pri.ID
                  LEFT JOIN DEPARTEMENT departement ON departement.id = dmd.iddepartement
                  LEFT JOIN ORDRETRAVAUX o ON o.IDBC = dmd.ID
                  LEFT JOIN ORDRETRAVAUXFILLE otf ON otf.IDMERE = o.ID
                  LEFT JOIN PLANNING pl ON pl.id = dmd.idplanning
                  LEFT JOIN TYPEMAINTENANCE tm ON tm.id = pl.idtypemaintenance
                  LEFT JOIN UTILISATEUR pers ON pers.REFUSER = dmd.DEMANDEUR
     ) SQ;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."DEMANDETRAVAUX_CPL_NOMBRE" ("ID", "IDENTITE", "IDSITUATION", "IDMACHINE", "DATY", "DATEBESOIN", "PRIORITE", "ESTEXISTANT", "DESCRIPTION", "ETAT", "IDDEPARTEMENT", "IDENTITELIB", "IDSITUATIONLIB", "IDMACHINELIB", "ESTEXISTANTLIB", "ETATLIB", "IDDEPARTEMENTMAINTENANCE", "IDDEPARTEMENTMAINTENANCELIB", "PRIORITELIB", "IDDEPARTEMENTLIB", "IDOTFILLE", "QTE") AS
SELECT
    ID,
    IDENTITE,
    IDSITUATION,
    IDMACHINE,
    DATY,
    DATEBESOIN,
    PRIORITE,
    ESTEXISTANT,
    DESCRIPTION,
    ETAT,
    IDDEPARTEMENT,
    IDENTITELIB,
    IDSITUATIONLIB,
    IDMACHINELIB,
    ESTEXISTANTLIB,
    ETATLIB,
    IDDEPARTEMENTMAINTENANCE,
    IDDEPARTEMENTMAINTENANCELIB,
    PRIORITELIB,
    IDDEPARTEMENTLIB,
    IDOTFILLE,
    COUNT(*) AS qte
FROM DEMANDETRAVAUX_CPL
GROUP BY
    ID,
    IDENTITE,
    IDSITUATION,
    IDMACHINE,
    DATY,
    DATEBESOIN,
    PRIORITE,
    ESTEXISTANT,
    DESCRIPTION,
    ETAT,
    IDDEPARTEMENT,
    IDENTITELIB,
    IDSITUATIONLIB,
    IDMACHINELIB,
    ESTEXISTANTLIB,
    ETATLIB,
    IDDEPARTEMENTMAINTENANCE,
    IDDEPARTEMENTMAINTENANCELIB,
    PRIORITELIB,
    IDDEPARTEMENTLIB,
    IDOTFILLE
ORDER BY qte DESC;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."DEMANDE_LIBCOMPLET" ("ID", "IDPERSONNEL", "MATRICULE", "IDFONCTION", "FONCTIONLIB", "IDTYPEDEMANDE", "TYPEDEMANDELIB", "TITRE", "HORAIRENORMAL", "HEUREDEPART", "HEUREARRIVE", "IDTYPEABSENCE", "TYPEABSENCELIB", "MOTIF", "NUMERO", "DESCE", "ETAT", "DATY", "DUREE", "DATEDEPART", "DATERETOUR", "OBSERVATION", "REMARQUE", "NOM", "PRENOM", "IDDIRECTION", "DIRECTIONLIB", "ETATLIB", "REFUSER", "RANGUSER", "IDREMPLACENTS", "REMPLACENTS", "MATRICULES", "DATEFIN", "PERSONNEL", "IDSUP", "AVENANT", "ANNULER", "SUPERIEUR", "MOTIFREFU", "WEEKENDDECOMPTELIB", "IDDEPARTEMENT", "DEPARTEMENTLIB") AS
SELECT d.id,
	       d.idpersonnel,
	       pip.matricule,
	       pip.idfonction,
	       pf.val AS fonctionlib,
	       d.idtypedemande,
	       t.val AS typedemandelib,
	       d.titre,
	       d.horairenormal,
	       d.heuredepart,
	       d.heurearrive,
	       d.idtypeabsence,
	       t2.desce AS typeabsencelib,
	       d.motif,
	       d.numero,
	       d.desce,
	       d.etat,
	       d.daty,
	       d.duree,
	       d.datedepart,
	       d.dateretour,
	       d.observation,
	       d.remarque,
	       lp.nom,
	       lp.prenom,
	       lp.direction AS iddirection,
	       ld.val AS directionlib,
	       CASE
	           WHEN d.etat = 1 THEN 'Cree'
	           WHEN d.etat = 11 THEN 'Valide'
	           WHEN d.etat = -1 THEN 'Refusee'
	           ELSE 'AUTRE'
	           END AS etatlib,
	       u.refuser,
	       r.rang AS ranguser,
	       d.idremplacents,
	       rmp.remplacents,
	       pip.matricule AS matricules,
	       d.datefin,
	       (lp.nom || ' ') || lp.prenom AS personnel,
	       lp.idsup,
	       d.avenant,
	       CASE
	           WHEN d.avenant IS NOT NULL THEN 'OUI'
	           ELSE NULL
	           END AS annuler,
	       (pl.nom || ' ') || pl.prenom AS superieur,
	       d.MOTIFREFU,
	       CASE WHEN
	                WEEKENDDECOMPTE = 1 THEN 'OUI'
	            WHEN WEEKENDDECOMPTE = 0 THEN 'NON'
	           END AS weekendDecompteLib,
	       d.IDDEPARTEMENT,
	       dp.DESCE as departementLib
	FROM demande d
	         LEFT JOIN paie_info_personnel pip ON d.idpersonnel = pip.id
	         LEFT JOIN paie_fonction pf ON pf.id = pip.idfonction
	         LEFT JOIN typedemande t ON t.id = d.idtypedemande
	         LEFT JOIN typeabsence t2 ON t2.id = d.idtypeabsence
	         LEFT JOIN log_personnel lp ON lp.id = pip.id
	         LEFT JOIN log_direction ld ON ld.id = lp.direction
	         LEFT JOIN utilisateur u ON u.refuser = lp.refuser
	         LEFT JOIN roles r ON r.idrole = u.idrole
	         LEFT JOIN demande_remplacents rmp ON rmp.id = d.id
	         LEFT JOIN log_personnel pl ON pl.id = lp.idsup
	         LEFT JOIN DEPARTEMENT dp ON dp.id = d.IDDEPARTEMENT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."DEMANDE_LIBCOMPLET2" ("ID", "IDPERSONNEL", "MATRICULES", "IDFONCTION", "FONCTIONLIB", "IDTYPEDEMANDE", "TYPEDEMANDELIB", "TITRE", "HORAIRENORMAL", "HEUREDEPART", "HEUREARRIVE", "IDTYPEABSENCE", "TYPEABSENCELIB", "MOTIF", "NUMERO", "DESCE", "ETAT", "DATY", "DUREE", "DATEDEPART", "DATEFIN", "DATERETOUR", "OBSERVATION", "REMARQUE", "NOM", "PRENOM", "PERSONNEL", "IDDIRECTION", "DIRECTIONLIB", "ETATLIB", "REFUSER", "RANGUSER", "IDREMPLACENTS", "REMPLACENTS", "AVENANT") AS
SELECT d.id,
       d.idpersonnel,
       pip.matricule AS matricules,
       pip.idfonction,
       pf.val AS fonctionlib,
       d.idtypedemande,
       t.val AS typedemandelib,
       d.titre,
       d.horairenormal,
       d.heuredepart,
       d.heurearrive,
       d.idtypeabsence,
       t2.desce AS typeabsencelib,
       d.motif,
       d.numero,
       d.desce,
       d.etat,
       d.daty,
       d.duree,
       d.datedepart,
       d.datefin,
       d.dateretour,
       d.observation,
       d.remarque,
       lp.nom,
       lp.prenom,
       (lp.nom || ' ') || lp.prenom AS personnel,
       lp.direction AS iddirection,
       ld.val AS directionlib,
       CASE
           WHEN d.etat = 1 THEN '<span style="color:green;">CR&Eacute;&Eacute;E</span>'
           WHEN d.etat = 11 THEN '<span style="color:blue;">VIS&Eacute;E</span>'
           WHEN d.etat = -1 THEN '<span style="color:red;">REFUS&Eacute;E</span>'
           ELSE '<span style="color: yellow;">AUTRE</span>'
           END AS etatlib,
       u.refuser,
       r.rang AS ranguser,
       d.idremplacents,
       rmp.remplacents,
       d.avenant
FROM demande d
         LEFT JOIN paie_info_personnel pip ON d.idpersonnel = pip.id
         LEFT JOIN paie_fonction pf ON pf.id = pip.idfonction
         LEFT JOIN typedemande t ON t.id = d.idtypedemande
         LEFT JOIN typeabsence t2 ON t2.id = d.idtypeabsence
         LEFT JOIN log_personnel lp ON lp.id = pip.id
         LEFT JOIN log_direction ld ON ld.id = lp.direction
         LEFT JOIN utilisateur u ON u.refuser = lp.refuser
         LEFT JOIN roles r ON r.idrole = u.idrole
         LEFT JOIN demande_remplacents rmp ON rmp.id = d.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."DEMANDE_LIBCOMPLET3" ("ID", "IDPERSONNEL", "MATRICULE", "IDFONCTION", "FONCTIONLIB", "IDTYPEDEMANDE", "TYPEDEMANDELIB", "TITRE", "HORAIRENORMAL", "HEUREDEPART", "HEUREARRIVE", "IDTYPEABSENCE", "TYPEABSENCELIB", "MOTIF", "NUMERO", "DESCE", "ETAT", "DATY", "DUREE", "DATEDEPART", "DATERETOUR", "OBSERVATION", "REMARQUE", "NOM", "PRENOM", "IDDIRECTION", "DIRECTIONLIB", "ETATLIB", "REFUSER", "RANGUSER", "IDREMPLACENTS", "REMPLACENTS", "MATRICULES", "DATEFIN", "PERSONNEL", "IDSUP", "AVENANT", "ANNULER", "SUPERIEUR", "MOTIFREFU", "IDDEPARTEMENT") AS
SELECT d.id,
       d.idpersonnel,
       pip.matricule,
       pip.idfonction,
       pf.val AS fonctionlib,
       d.idtypedemande,
       t.val AS typedemandelib,
       d.titre,
       d.horairenormal,
       d.heuredepart,
       d.heurearrive,
       d.idtypeabsence,
       t2.desce AS typeabsencelib,
       d.motif,
       d.numero,
       d.desce,
       d.etat,
       d.daty,
       d.duree,
       d.datedepart,
       d.dateretour,
       d.observation,
       d.remarque,
       lp.nom,
       lp.prenom,
       lp.direction AS iddirection,
       ld.val AS directionlib,
       CASE
           WHEN d.etat = 1 THEN '<span style="color:green;">CR&Eacute;&Eacute;E</span>'
           WHEN d.etat = 11 THEN '<span style="color:blue;">VIS&Eacute;E</span>'
           WHEN d.etat = -1 THEN '<span style="color:red;">REFUS&Eacute;E</span>'
           ELSE '<span style="color: yellow;">AUTRE</span>'
           END AS etatlib,
       u.refuser,
       r.rang AS ranguser,
       d.idremplacents,
       rmp.remplacents,
       pip.matricule AS matricules,
       d.datefin,
       (lp.nom || ' ') || lp.prenom AS personnel,
       lp.idsup,
       d.avenant,
       CASE
           WHEN d.avenant IS NOT NULL THEN 'OUI'
           ELSE NULL
           END AS annuler,
       (pl.nom || ' ') || pl.prenom AS superieur,
       d.MOTIFREFU,
       pip.IDDEPARTEMENT
FROM demande d
         LEFT JOIN paie_info_personnel pip ON d.idpersonnel = pip.id
         LEFT JOIN paie_fonction pf ON pf.id = pip.idfonction
         LEFT JOIN typedemande t ON t.id = d.idtypedemande
         LEFT JOIN typeabsence t2 ON t2.id = d.idtypeabsence
         LEFT JOIN log_personnel lp ON lp.id = pip.id
         LEFT JOIN log_direction ld ON ld.id = lp.direction
         LEFT JOIN utilisateur u ON u.refuser = lp.refuser
         LEFT JOIN roles r ON r.idrole = u.idrole
         LEFT JOIN demande_remplacents rmp ON rmp.id = d.id
         LEFT JOIN log_personnel pl ON pl.id = lp.idsup;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."DEMANDE_REMPLACENTS" ("ID", "REMPLACENTS") AS
SELECT d.id,
       LISTAGG(t.nom || ' ' || t.prenom, '   ,    ') WITHIN GROUP (ORDER BY t.nom) AS remplacents
FROM demande d
    LEFT JOIN employe_complet_libelle2 t ON INSTR(d.idremplacents, t.id) > 0
GROUP BY d.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."DEMANDE_VIDE" ("IDPERSONNEL", "MATRICULE", "IDFONCTION", "FONCTIONLIB", "IDTYPEDEMANDE", "TYPEDEMANDELIB", "TITRE", "HORAIRENORMAL", "IDTYPEABSENCE", "TYPEABSENCELIB", "NOM", "PRENOM", "REFUSER", "RANGUSER", "IDSUP", "ANNULER", "DUREEFINAL", "TETAT", "ASIDDIRECTION", "DIRECTIONLIB", "ETATLIB", "DATY") AS
SELECT
    CAST(NULL AS VARCHAR2(100)) AS idpersonnel,
    CAST(NULL AS VARCHAR2(100)) AS matricule,
    CAST(NULL AS VARCHAR2(100)) AS idfonction,
    CAST(NULL AS VARCHAR2(100)) AS fonctionlib,
    CAST(NULL AS VARCHAR2(100)) AS idtypedemande,
    CAST(NULL AS VARCHAR2(100)) AS typedemandelib,
    CAST(NULL AS VARCHAR2(100)) AS titre,
    CAST(NULL AS VARCHAR2(100)) AS horairenormal,
    CAST(NULL AS VARCHAR2(100)) AS idtypeabsence,
    CAST(NULL AS VARCHAR2(100)) AS typeabsencelib,
    CAST(NULL AS VARCHAR2(100)) AS nom,
    CAST(NULL AS VARCHAR2(100)) AS prenom,
    0 AS refuser,
    0 AS ranguser,
    CAST(NULL AS VARCHAR2(100)) AS idsup,
    CAST(NULL AS VARCHAR2(100)) AS annuler,
    CAST(0 AS NUMBER(32, 0)) AS dureefinal,
    0 AS tetat,
    CAST(NULL AS VARCHAR2(100)) AS asiddirection,
    CAST(NULL AS VARCHAR2(100)) AS directionlib,
    CAST(NULL AS VARCHAR2(100)) AS etatlib,
    SYSDATE AS daty
FROM dual;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."DEMTRANSFILLEGROUPEMERE" ("IDDEMANDETRANSFERT", "MONTANTQUANTITE") AS
select f.IDDEMANDETRANSFERT,cast(sum(nvl(f.pu*f.QUANTITE,0)) as number(30,2)) as montantQuantite
from DEMANDETRANSFERTFILLE f group by f.IDDEMANDETRANSFERT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."DEPARTEMENT_ACTIF" ("ID", "VAL", "DESCE", "ACTIF") AS
select "ID","VAL","DESCE","ACTIF" from DEPARTEMENT where ACTIF=1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."DEPENSEBONDELIVRAISON" ("ID", "REMARQUE", "IDBC", "DATY", "ETAT", "IDFOURNISSEUR", "MAGASIN", "IDFACTUREFOURNISSEUR", "IDDEPENSEDIVERS", "DATYDEPENSE", "FOURNISSEURDEPENSE", "REMARQUEDEPENSE", "IDMODEPAIEMENT", "COMPTECHEQUE", "ACHETEUR", "IDMAGASIN", "IDCATEGORIE", "ETATDEPENSE", "MAGASINLIB") AS
SELECT
    bl.ID,
    bl.REMARQUE,
    bl.IDBC,
    bl.DATY,
    bl.ETAT,
    bl.IDFOURNISSEUR,
    bl.MAGASIN,
    bl.IDFACTUREFOURNISSEUR,
    bl.IDDEPENSEDIVERS,

    dd.DATY          AS DATYDEPENSE,
    dd.FOURNISSEUR   AS FOURNISSEURDEPENSE,
    dd.REMARQUE      AS REMARQUEDEPENSE,
    dd.IDMODEPAIEMENT,
    dd.COMPTECHEQUE,
    dd.ACHETEUR,
    dd.IDMAGASIN,
    dd.IDCATEGORIE,
    dd.ETAT          AS ETATDEPENSE,
    m2.val AS magasinlib

FROM AS_BONDELIVRAISON bl
LEFT JOIN DEPENSEDIVERS dd ON dd.ID = bl.IDDEPENSEDIVERS
        LEFT join MAGASIN2 m2 ON m2.id = bl.MAGASIN;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."DEPENSEDFACTUREFOURNISSEUR" ("ID", "IDBC", "DESIGNATION", "IDFOURNISSEURLIB", "IDDEVISE", "DATY", "MONTANTTTC", "MONTANTPAYE", "MONTANTRESTE", "DATEECHEANCEPAIEMENT", "IDSERVICELIB", "ETATLIB", "IDFOURNISSEUR", "IDMODEPAIEMENT", "DEVISE", "TAUX", "IDMAGASIN", "ETATFACTURE", "IDBONDELIVRAISON", "REMARQUEBONDELIVRAISON", "MAGASIN", "IDDEPENSEDIVERS", "IDDEPENSEDIVERSREF", "DATYDEPENSE", "FOURNISSEURDEPENSE", "REMARQUEDEPENSE", "IDMODEPAIEMENTDEPENSE", "COMPTECHEQUE", "ACHETEUR", "IDMAGASINDEPENSE", "IDCATEGORIE", "ETATDEPENSE") AS
SELECT
    ff.ID                     AS ID,
    ff.IDBC,
    ff.DESIGNATION,
    ff.IDFOURNISSEURLIB,
    ff.IDDEVISE               AS IDDEVISE,
    ff.DATY,
    ff.MONTANTTTC,
    ff.MONTANTPAYE,
    ff.MONTANTRESTE,
    ff.DATEECHEANCEPAIEMENT,
    ff.IDSERVICELIB,
    ff.ETATLIB,

    ff.IDFOURNISSEUR,
    ff.IDMODEPAIEMENT,
    ff.DEVISE,
    ff.TAUX,
    ff.IDMAGASIN,
    ff.ETAT                   AS ETATFACTURE,

    bl.ID                     AS IDBONDELIVRAISON,
    bl.REMARQUE               AS REMARQUEBONDELIVRAISON,
    bl.MAGASIN,
    bl.IDDEPENSEDIVERS,

    dd.ID                     AS IDDEPENSEDIVERSREF,
    dd.DATY                   AS DATYDEPENSE,
    dd.FOURNISSEUR            AS FOURNISSEURDEPENSE,
    dd.REMARQUE               AS REMARQUEDEPENSE,
    dd.IDMODEPAIEMENT         AS IDMODEPAIEMENTDEPENSE,
    dd.COMPTECHEQUE,
    dd.ACHETEUR,
    dd.IDMAGASIN              AS IDMAGASINDEPENSE,
    dd.IDCATEGORIE,
    dd.ETAT                   AS ETATDEPENSE

FROM AS_BONDELIVRAISON bl
INNER JOIN FACTUREFOURNISSEURCPL_TOUS ff
    ON ff.ID = bl.IDFACTUREFOURNISSEUR
LEFT JOIN DEPENSEDIVERS dd
    ON dd.ID = bl.IDDEPENSEDIVERS;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."DEPENSEDIVERSFILLELIB" ("ID", "IDMERE", "IDPRODUIT", "DESIGNATION", "QUANTITE", "PU", "IDPRODUITLIB", "MONTANT", "TVA") AS
SELECT
    d.ID,
    d.IDMERE,
    d.IDPRODUIT,
    d.DESIGNATION,
    d.QUANTITE,
    d.PU,
    ail.LIBELLE AS idProduitLib,
    NVL(d.QUANTITE, 0) * NVL(d.PU, 0) AS montant,
    d.tva
FROM DEPENSEDIVERSFILLE d
LEFT JOIN AS_INGREDIENTS_LIB ail ON d.IDPRODUIT = ail.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."DEPENSEDIVERSLIB" ("ID", "DATY", "FOURNISSEUR", "REMARQUE", "IDMODEPAIEMENT", "COMPTECHEQUE", "ACHETEUR", "IDMAGASIN", "IDCATEGORIE", "ETAT", "FOURNISSEURLIB", "IDMODEPAIEMENTLIB", "IDMAGASINLIB", "IDCATEGORIELIB", "ETATLIB", "SERVICELIB", "IDSECTIONLIB", "SERVICE", "IDSECTION", "MONTANTTOTAL", "SURPLUSTOTAL", "RENDUTOTAL") AS
SELECT
    d.ID, d.DATY, d.FOURNISSEUR, d.REMARQUE, d.IDMODEPAIEMENT, d.COMPTECHEQUE, d.ACHETEUR, d.IDMAGASIN, d.IDCATEGORIE, d.ETAT,
    f.NOM AS fournisseurLib,
    m.VAL AS IDMODEPAIEMENTLIB,
    m2.val AS idMagasinLib,
    c.VAL AS idCategorieLib,
    CASE
        WHEN d.ETAT = 0 THEN 'ANNUL&Eacute;E'
        WHEN d.ETAT = 1 THEN 'CR&Eacute;&Eacute;E'
        WHEN d.ETAT = 3 THEN 'VIS&Eacute;E par Chef de D&eacutepartement'
        WHEN d.ETAT = 4 THEN 'VIS&Eacute;E par Directeur de D&eacutepartement'
        WHEN d.ETAT = 5 THEN 'VIS&Eacute;E par Le Directeur'
        WHEN d.ETAT = 11 THEN 'VIS&Eacute;E par Contr&ocirc;le'
        END AS etatlib,
    s.LIBELLE AS serviceLib,
    sec.VAL AS idSectionLib,
    d.service,
    d.idSection,
    (SELECT NVL(SUM(NVL(df.QUANTITE, 0) * NVL(df.PU, 0)), 0)
     FROM DEPENSEDIVERSFILLE df
     WHERE df.IDMERE = d.ID
    ) AS montantTotal,
    CASE
        WHEN EXISTS (
            SELECT 1 FROM MOUVEMENTCAISSE mc
            WHERE mc.IDORIGINE = d.ID
               OR mc.IDORIGINE IN (SELECT b.IDFACTUREFOURNISSEUR FROM AS_BONDELIVRAISON b WHERE b.IDDEPENSEDIVERS = d.ID)
        )
            THEN (SELECT NVL(SUM(NVL(mc.DEBIT, 0)), 0)
                  FROM MOUVEMENTCAISSE mc
                  WHERE mc.IDORIGINE = d.ID
                     OR mc.IDORIGINE IN (SELECT b.IDFACTUREFOURNISSEUR FROM AS_BONDELIVRAISON b WHERE b.IDDEPENSEDIVERS = d.ID)
                 ) - (SELECT NVL(SUM(NVL(df.QUANTITE, 0) * NVL(df.PU, 0)), 0)
                      FROM DEPENSEDIVERSFILLE df
                      WHERE df.IDMERE = d.ID)
        ELSE 0
        END AS surplusTotal,
    CASE
        WHEN EXISTS (
            SELECT 1 FROM MOUVEMENTCAISSE mc
            WHERE mc.IDORIGINE = d.ID
               OR mc.IDORIGINE IN (SELECT b.IDFACTUREFOURNISSEUR FROM AS_BONDELIVRAISON b WHERE b.IDDEPENSEDIVERS = d.ID)
        )
            THEN (SELECT NVL(SUM(NVL(mc.CREDIT, 0)), 0)
                  FROM MOUVEMENTCAISSE mc
                  WHERE mc.IDORIGINE = d.ID
                     OR mc.IDORIGINE IN (SELECT b.IDFACTUREFOURNISSEUR FROM AS_BONDELIVRAISON b WHERE b.IDDEPENSEDIVERS = d.ID)
        )
        ELSE 0
        END AS renduTotal
FROM DEPENSEDIVERS d
         LEFT JOIN FOURNISSEUR f ON d.FOURNISSEUR = f.ID
         LEFT JOIN MODEPAIEMENT m ON d.IDMODEPAIEMENT = m.ID
         LEFT JOIN MAGASIN2 m2 ON d.IDMAGASIN = m2.ID
         LEFT JOIN CATEGORIEINGREDIENT c ON d.IDCATEGORIE = c.ID
         LEFT JOIN departementDivers s ON s.id = d.SERVICE
         LEFT JOIN SECTION sec ON sec.ID = d.IDSECTION;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."DEPENSEENCAISSEMENT" ("ID", "DESIGNATION", "IDENCAISSEMENT", "DATY", "ETAT", "MONTANT") AS
SELECT 
cast(' ' AS varchar(255)) AS id,
cast(' ' AS varchar(255)) AS designation,
cast(' ' AS varchar(255)) AS idEncaissement,
cast(NULL AS date) AS daty,
cast(-1 AS int) AS etat,
cast(0 AS NUMBER(30,2)) AS montant
FROM dual;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."DEPENSEFAB" ("IDOBJET", "IDPRODUIT", "ENTREE", "SORTIE", "PU", "MONTANTENTREE", "MONTANTSORTIE", "IDMERE", "ID") AS
select c.IDFABRICATION as idobjet,c.IDINGREDIENTS as IDPRODUIT,cast(0 as number(15,2)) as entree,cast(sum(c.qte) as number (15,2)) as sortie,cast(avg(c.PU) as number(30,2)) as pu,cast(0 as number(30,3)) as montantentree,cast(nvl(avg(c.pu)*sum(c.qte),0) as number(30,3)) as montantsortie,ofile.IDMERE,ofile.id
from charge c
left join fabrication fabb on c.IDFABRICATION=fabb.id
left join OFFILLE ofile on fabb.IDOFFILLE=ofile.ID
where c.etat>=11 group by c.IDFABRICATION, c.IDINGREDIENTS,ofile.IDMERE,ofile.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."DEPENSEFILLESAISIE" ("ID", "IDFACTUREFOURNISSEUR", "IDPRODUIT", "IDBCDETAIL", "DEVISE", "IDDEVISE", "DESIGNATION", "COMPTE", "COMPTEANALYTIQUE", "LIBELLE", "INTITULE", "PU", "PUHT", "TAUXDECHANGE", "REMISES", "MOIS", "ANNEE", "QTE", "MONTANTPERTEGAIN", "DEBIT", "CREDIT", "TVA", "MONTANTTVA") AS
SELECT
    '' AS ID,
    '' AS IDFACTUREFOURNISSEUR,
    '' AS IDPRODUIT,
    '' AS IDBCDETAIL,
    '' AS DEVISE,
    '' AS IDDEVISE,
    '' AS DESIGNATION,
    '' AS COMPTE,
    '' AS COMPTEANALYTIQUE,
    '' AS LIBELLE,
    '' AS INTITULE,
    CAST(NULL AS NUMBER(30, 2)) AS PU,
    CAST(NULL AS NUMBER(30, 2)) AS PUHT,
    CAST(NULL AS NUMBER(30, 2)) AS TAUXDECHANGE,
    CAST(NULL AS NUMBER(30, 2)) AS REMISES,
    CAST(NULL AS NUMBER) AS MOIS,
    CAST(NULL AS NUMBER) AS ANNEE,
    CAST(NULL AS NUMBER(30, 2)) AS QTE,
    CAST(NULL AS NUMBER(30, 2)) AS MONTANTPERTEGAIN,
    CAST(NULL AS NUMBER(30, 2)) AS DEBIT,
    CAST(NULL AS NUMBER(30, 2)) AS CREDIT,
    CAST(NULL AS NUMBER(30, 2)) AS TVA,
    CAST(NULL AS NUMBER(30, 2)) AS MONTANTTVA
FROM DUAL;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."DEPENSELIB" ("ID", "DESIGNATION", "IDCAISSE", "IDCAISSELIB", "IDOP", "IDORIGINE", "DATY", "MONTANT", "ETAT", "ETATLIB") AS
SELECT
    d.ID ,
    d.DESIGNATION ,
    d.IDCAISSE ,
    c.VAL AS IDCAISSELIB,
    d.IDOP ,
    d.IDORIGINE ,
    d.DATY ,
    d.MONTANT ,
    d.ETAT ,
    CASE
        WHEN d.ETAT = 1
            THEN 'CREEE'
        WHEN d.ETAT = 11
            THEN 'VISEE'
        WHEN d.ETAT = 0
            THEN 'ANNULEE'
        END AS ETATLIB
FROM DEPENSE d
         LEFT JOIN CAISSE c ON c.ID = d.IDCAISSE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."DEPENSELIB_ANNULEE" ("ID", "DESIGNATION", "IDCAISSE", "IDCAISSELIB", "IDOP", "IDORIGINE", "DATY", "MONTANT", "ETAT", "ETATLIB") AS
SELECT 
d."ID",d."DESIGNATION",d."IDCAISSE",d."IDCAISSELIB",d."IDOP",d."IDORIGINE",d."DATY",d."MONTANT",d."ETAT",d."ETATLIB"
FROM depenseLib d 
WHERE d.ETAT = 0;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."DEPENSELIB_CREE" ("ID", "DESIGNATION", "IDCAISSE", "IDCAISSELIB", "IDOP", "IDORIGINE", "DATY", "MONTANT", "ETAT", "ETATLIB") AS
SELECT 
d."ID",d."DESIGNATION",d."IDCAISSE",d."IDCAISSELIB",d."IDOP",d."IDORIGINE",d."DATY",d."MONTANT",d."ETAT",d."ETATLIB"
FROM depenseLib d 
WHERE d.ETAT = 1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."DEPENSELIB_VISEE" ("ID", "DESIGNATION", "IDCAISSE", "IDCAISSELIB", "IDOP", "IDORIGINE", "DATY", "MONTANT", "ETAT", "ETATLIB") AS
SELECT 
d."ID",d."DESIGNATION",d."IDCAISSE",d."IDCAISSELIB",d."IDOP",d."IDORIGINE",d."DATY",d."MONTANT",d."ETAT",d."ETATLIB"
FROM depenseLib d 
WHERE d.ETAT = 11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."DEPENSESAISIE" ("ID", "IDFOURNISSEUR", "IDMODEPAIEMENT", "IDTYPEFACTURE", "IDDEVISE", "DATY", "DATYPREVU", "DATEECHEANCEPAIEMENT", "ESTPREVU", "ETAT", "TAUX", "DEVISE", "DESIGNATION", "REFERENCE", "IDBC", "IDMAGASIN", "NUMERO", "TYPEACHAT", "TYPE_FACTURE", "IDOBJET", "IDREF", "IDDMDACHAT", "EXERCICE", "PERIODE", "LIBELLE", "TOTALFACTURE", "TYPETVA", "TYPEFACTUREFOURNISSEUR", "JOUR") AS
SELECT
    '' AS ID,
    '' AS IDFOURNISSEUR,
    '' AS IDMODEPAIEMENT,
    '' AS IDTYPEFACTURE,
    '' AS IDDEVISE,
    CAST(NULL AS DATE) AS DATY,
    CAST(NULL AS DATE) AS DATYPREVU,
    CAST(NULL AS DATE) AS DATEECHEANCEPAIEMENT,
    CAST(NULL AS NUMBER(1)) AS ESTPREVU,
    CAST(NULL AS NUMBER) AS ETAT,
    CAST(NULL AS NUMBER(30, 2)) AS TAUX,
    '' AS DEVISE,
    '' AS DESIGNATION,
    '' AS REFERENCE,
    '' AS IDBC,
    '' AS IDMAGASIN,
    '' AS NUMERO,
    '' AS TYPEACHAT,
    '' AS TYPE_FACTURE,
    '' AS IDOBJET,
    '' AS IDREF,
    '' AS IDDMDACHAT,
    CAST(NULL AS NUMBER) AS EXERCICE,
    '' AS PERIODE,
    '' AS LIBELLE,
    CAST(NULL AS NUMBER(30, 2)) AS TOTALFACTURE,
    '' AS TYPETVA,
    '' AS TYPEFACTUREFOURNISSEUR,
    '' AS JOUR
FROM DUAL;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."DEPENSE_MAT_PREM" ("DATY", "ID", "DESIGNATION", "QUANTITE", "PU", "DEPENSE") AS
SELECT 
	f.DATY ,
	ff.idproduit AS id,
	ai.LIBELLE AS designation,
	nvl(sum(ff.qte),0) AS quantite,
	nvl(avg(ff.pu),0) AS pu,
	nvl(sum(ff.qte)*avg(ff.pu),0) AS depense
FROM 
FACTUREFOURNISSEURFILLE ff
LEFT JOIN FACTUREFOURNISSEUR f 
ON f.ID = ff.IDFACTUREFOURNISSEUR 
LEFT JOIN AS_INGREDIENTS ai 
ON ai.ID = ff.idproduit
WHERE f.etat >=11
GROUP BY 
	ff.idproduit, 
	ai.LIBELLE,
	f.DATY;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."DEPENSE_VALIDEE" ("IDORIGINE", "DEPENSE") AS
SELECT 
d.IDORIGINE ,
sum(nvl(d.MONTANT,0) ) AS depense
FROM DEPENSE d 
WHERE d.ETAT > 1 
GROUP BY d.IDORIGINE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."DERNIERATTRIBUTIONELEMENT" ("ID", "IDINGREDIENTMAINTENANCE", "IDPERSONNEL", "DATY", "ETATELEMENT", "TYPEATTRIBUTION", "QTE", "ETAT") AS
SELECT ae."ID",ae."IDINGREDIENTMAINTENANCE",ae."IDPERSONNEL",ae."DATY",ae."ETATELEMENT",ae."TYPEATTRIBUTION",ae."QTE",ae."ETAT"
FROM ATTRIBUTIONELEMENT ae
         INNER JOIN (
    SELECT
        IDINGREDIENTMAINTENANCE,
        MAX(DATY) AS max_daty
    FROM ATTRIBUTIONELEMENT
    GROUP BY IDINGREDIENTMAINTENANCE
) derniere ON ae.IDINGREDIENTMAINTENANCE = derniere.IDINGREDIENTMAINTENANCE
    AND ae.DATY = derniere.max_daty;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."DERNIER_DEBAUCHE_BY_EMPLOYE" ("IDLOGPERS", "DATEAPPLICATION", "IDTYPEDEBAUCHE", "DATE_DECISION", "DATE_REINTEGRATION", "RK", "DATEFIN") AS
WITH summary AS (
    SELECT
        p.idlogpers,
        p.dateapplication,
        p.idtypedebauche,
        p.date_decision,
        p.date_reintegration,
        ROW_NUMBER() OVER (PARTITION BY p.idlogpers ORDER BY p.date_decision DESC) AS rk,
        p.datefin
    FROM log_personnel_non_valide p
    WHERE p.idtypedebauche IN (
                               'TYD000013', 'TYD000002', 'TYD000003', 'TYD000004',
                               'TYD000012', 'TYD000014', 'TYD000001'
        )
      AND p.etat >= 11
)
SELECT
    s.idlogpers,
    s.dateapplication,
    s.idtypedebauche,
    s.date_decision,
    s.date_reintegration,
    s.rk,
    s.datefin
FROM summary s
WHERE s.rk = 1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."DERNIER_DEBAUCHE_LPNV" ("ID", "IDLOGPERS", "DATEAPPLICATION", "IDTYPEDEBAUCHE", "ETAT", "IDUSER", "MOTIF", "DATE_REINTEGRATION", "DATE_DECISION", "REFDECISION", "IDAVANCEMENT") AS
SELECT lpnv.id,
       lpnv.idlogpers,
       lpnv.dateapplication,
       lpnv.idtypedebauche,
       lpnv.etat,
       lpnv.iduser,
       lpnv.motif,
       lpnv.date_reintegration,
       lpnv.date_decision,
       lpnv.refdecision,
       lpnv.idavancement
FROM dernier_debauche_by_employe debauche,
     log_personnel_non_valide lpnv
WHERE debauche.idlogpers = lpnv.idlogpers AND debauche.dateapplication = lpnv.dateapplication AND debauche.date_decision = lpnv.date_decision;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."DETAILSBONCAISSECPL" ("ID", "IDCAISSE", "IDCAISSELIB", "IDPOINT", "IDPOINTLIB", "DEBIT", "CREDIT", "IDCLIENT", "IDCLIENTLIB", "IDPRECISIONDETAILENCAISSEMENT", "DATY", "REMARQUE", "ETAT", "ETATLIB") AS
SELECT 
d.ID ,
d.IDCAISSE ,
c.VAL AS IDCAISSELIB,
c.IDPOINT ,
p.VAL AS IDPOINTLIB,
d.DEBIT ,
d.CREDIT ,
d.IDCLIENT ,
c2.NOM AS IDCLIENTLIB,
d.IDPRECISIONDETAILENCAISSEMENT ,
d.DATY ,
d.REMARQUE ,
d.ETAT ,
CASE 
	WHEN d.ETAT = 1 
	THEN 'CREE'
	WHEN d.ETAT = 11
	THEN 'VISEE'
	WHEN d.ETAT = 0 
	THEN 'ANNULEE'
END AS ETATLIB
FROM DETAILSBONCAISSE d 
LEFT JOIN CAISSE c ON c.ID = d.IDCAISSE 
LEFT JOIN POINT p ON p.ID = c.IDPOINT 
LEFT JOIN CLIENT c2 ON c2.ID = d.IDCLIENT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."DETAILS_PAIE_EDITION_FINALPDF" ("ID", "NOM", "POSTE", "SALAIRE_DE_BASE", "TAUX", "JUILLET", "INDEMNITEDEPRESENTATIONBRUT", "INDEMNITE_DE_TRANSPORT", "AVANTAGES_EN_NATURE", "MONTANT_BRUT", "CNAPS", "BRUTCNAPS", "IMPOSABLE", "IRSA", "NETAPRESCALCUL", "REDUCTIONPOURPERSONNESACHARGE", "IRSANET", "NET_A_PAYER", "MOIS", "ANNEE", "DATEEMBAUCHE", "NUMERO_CNAPS", "MATRICULE", "IDEDITION", "MOISLIB") AS
SELECT d.idpersonnel AS id,
       o.cturgence_nom_prenom AS nom,
       pf.desce AS poste,
       sum(d.salaire_de_base) AS salaire_de_base,
       sum(d.taux) AS taux,
       sum(d.juillet) AS juillet,
       sum(d.indemnitedepresentationbrut) AS indemnitedepresentationbrut,
       sum(d.indemnite_de_transport) AS indemnite_de_transport,
       sum(d.avantages_en_nature) AS avantages_en_nature,
       sum(d.juillet) + sum(d.indemnitedepresentationbrut) + sum(d.indemnite_de_transport) + sum(d.avantages_en_nature) AS montant_brut,
       sum(d.cnaps_travailleur) AS cnaps,
       sum(d.juillet) + sum(d.indemnitedepresentationbrut) + sum(d.indemnite_de_transport) + sum(d.avantages_en_nature) - sum(d.cnaps_travailleur) AS brutcnaps,
       100 * trunc((sum(d.juillet) + sum(d.indemnitedepresentationbrut) + sum(d.indemnite_de_transport) + sum(d.avantages_en_nature) - sum(d.cnaps_travailleur)) / 100) AS imposable,
       sum(d.irsa) AS irsa,
       round((sum(d.juillet) + sum(d.indemnitedepresentationbrut) + sum(d.indemnite_de_transport) + sum(d.avantages_en_nature) - sum(d.cnaps_travailleur) - sum(d.irsa)), 1) AS netaprescalcul,
       sum(d.reductionpourpersonnesacharge) AS reductionpourpersonnesacharge,
       sum(d.irsanet) AS irsanet,
       sum(d.net_a_payer) AS net_a_payer,
       d.mois,
       d.annee,
       o.dateembauche,
       o.numero_cnaps,
       o.matricule,
       d.idedition,
       TO_CHAR(
               TO_DATE(TO_CHAR(d.mois, 'FM00'), 'MM'),
               'FMMonth',
               'NLS_DATE_LANGUAGE=FRENCH'
       ) AS moisLib
FROM details_paie_edition_pdf d
         LEFT JOIN paie_info_personnel_libcomplet o ON o.id = d.idpersonnel
         LEFT JOIN paie_info_personnel pip ON pip.id = d.idpersonnel
         LEFT JOIN paie_fonction pf ON pf.id = pip.idfonction
GROUP BY d.idpersonnel, o.cturgence_nom_prenom, pf.desce, d.mois, d.annee, o.dateembauche, o.numero_cnaps, o.matricule, d.idedition;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."DETAILS_PAIE_EDITION_PDF" ("IDPERSONNEL", "IDELEMENTPAIE", "GAIN", "RETENUE", "SALAIRE_DE_BASE", "TAUX", "JUILLET", "INDEMNITE_DE_TRANSPORT", "INDEMNITEDEPRESENTATIONBRUT", "AVANTAGES_EN_NATURE", "MONTANT_BRUT", "CNAPS_TRAVAILLEUR", "BRUTCNAPS", "REDUCTIONPOURPERSONNESACHARGE", "IRSA", "NETAPRESCALCUL", "IRSANET", "NET_A_PAYER", "MOIS", "ANNEE", "IDEDITION") AS
SELECT paie_edition.idpersonnel,
       paie_edition.idelementpaie,
       paie_edition.gain,
       paie_edition.retenue,
       CASE
           WHEN paie_edition.idelementpaie = 'PR000041' AND cq2.montant IS NOT NULL THEN cq2.montant
           WHEN paie_edition.idelementpaie = 'PR000041' AND cq2.montant IS NULL THEN cq.montant
           ELSE 0
           END AS salaire_de_base,
       CASE
           WHEN paie_edition.idelementpaie = 'PR000041' AND cq2.montant IS NOT NULL THEN cq2.montant
           WHEN paie_edition.idelementpaie = 'PR000041' AND cq2.montant IS NULL THEN cq.montant
           ELSE 0
           END / 30 AS taux,
       CASE
           WHEN paie_edition.idelementpaie = 'PR000041' THEN paie_edition.gain
           ELSE 0
           END AS juillet,
       CASE
           WHEN paie_edition.idelementpaie = 'PR000001' THEN paie_edition.gain
           ELSE 0
           END AS indemnite_de_transport,
       CASE
           WHEN paie_edition.idelementpaie = 'PR000021' THEN paie_edition.gain
           ELSE 0
           END AS indemnitedepresentationbrut,
       CASE
           WHEN paie_edition.idelementpaie = 'PR000201' THEN paie_edition.gain
           ELSE 0
           END AS avantages_en_nature,
       0 AS montant_brut,
       CASE
           WHEN paie_edition.idelementpaie = 'PR000101' THEN paie_edition.retenue
           ELSE 0
           END AS cnaps_travailleur,
       0 AS brutcnaps,
       CASE
           WHEN paie_edition.idelementpaie = 'PR000181' THEN paie_edition.gain
           ELSE 0
           END AS reductionpourpersonnesacharge,
       CASE
           WHEN paie_edition.idelementpaie = 'PR000141' THEN GREATEST(paie_edition.retenue, 3000)
           ELSE 0
           END AS irsa,
       0 AS netaprescalcul,
       CASE
           WHEN paie_edition.idelementpaie = 'PR000141NET' THEN paie_edition.retenue
           ELSE 0
           END AS irsanet,
       CASE
           WHEN paie_edition.idelementpaie = 'PR000210A' THEN paie_edition.gain
           ELSE 0
           END AS net_a_payer,
       paie_edition.mois,
       paie_edition.annee,
       paie_edition.idedition
FROM paie_edition
         JOIN paie_info_personnel pip ON pip.id = paie_edition.idpersonnel
         LEFT JOIN categorie_qualification cq ON cq.idcategorie = pip.idcategorie_paie AND cq.idqualification = pip.idqualification AND cq.remarque = '''' AND cq.etat = 1
         LEFT JOIN categorie_qualification cq2 ON cq2.idcategorie = pip.idcategorie_paie AND cq2.idqualification = pip.idqualification AND cq2.remarque = paie_edition.idpersonnel AND cq2.remarque = pip.id AND cq2.etat = 1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."DET_PAIE_EDIT_FINAL_PDF_CONID" ("ID", "NOM", "POSTE", "SALAIRE_DE_BASE", "TAUX", "JUILLET", "INDEMNITEDEPRESENTATIONBRUT", "INDEMNITE_DE_TRANSPORT", "AVANTAGES_EN_NATURE", "MONTANT_BRUT", "CNAPS", "BRUTCNAPS", "IMPOSABLE", "IRSA", "NETAPRESCALCUL", "REDUCTIONPOURPERSONNESACHARGE", "IRSANET", "NET_A_PAYER", "MOIS", "ANNEE", "DATEEMBAUCHE", "NUMERO_CNAPS", "MATRICULE", "IDEDITION", "MOISLIB") AS
SELECT (d.idpersonnel || '//') || d.idedition AS id,
       o.cturgence_nom_prenom AS nom,
       pf.desce AS poste,
       sum(d.salaire_de_base) AS salaire_de_base,
       sum(d.taux) AS taux,
       sum(d.juillet) AS juillet,
       sum(d.indemnitedepresentationbrut) AS indemnitedepresentationbrut,
       sum(d.indemnite_de_transport) AS indemnite_de_transport,
       sum(d.avantages_en_nature) AS avantages_en_nature,
       sum(d.juillet) + sum(d.indemnitedepresentationbrut) + sum(d.indemnite_de_transport) + sum(d.avantages_en_nature) AS montant_brut,
       sum(d.cnaps_travailleur) AS cnaps,
       sum(d.juillet) + sum(d.indemnitedepresentationbrut) + sum(d.indemnite_de_transport) + sum(d.avantages_en_nature) - sum(d.cnaps_travailleur) AS brutcnaps,
       100 * trunc((sum(d.juillet) + sum(d.indemnitedepresentationbrut) + sum(d.indemnite_de_transport) + sum(d.avantages_en_nature) - sum(d.cnaps_travailleur)) / 100) AS imposable,
       sum(d.irsa) AS irsa,
       round((sum(d.juillet) + sum(d.indemnitedepresentationbrut) + sum(d.indemnite_de_transport) + sum(d.avantages_en_nature) - sum(d.cnaps_travailleur) - sum(d.irsa)), 1) AS netaprescalcul,
       sum(d.reductionpourpersonnesacharge) AS reductionpourpersonnesacharge,
       sum(d.irsanet) AS irsanet,
       sum(d.net_a_payer) AS net_a_payer,
       d.mois,
       d.annee,
       o.dateembauche,
       o.numero_cnaps,
       o.matricule,
       d.idedition,
       TO_CHAR(
               TO_DATE(TO_CHAR(d.mois, 'FM00'), 'MM'),
               'FMMonth',
               'NLS_DATE_LANGUAGE=FRENCH'
       ) AS moisLib
FROM details_paie_edition_pdf d
         LEFT JOIN paie_info_personnel_libcomplet o ON o.id = d.idpersonnel
         LEFT JOIN paie_info_personnel pip ON pip.id = d.idpersonnel
         LEFT JOIN paie_fonction pf ON pf.id = pip.idfonction
GROUP BY d.idpersonnel, o.cturgence_nom_prenom, pf.desce, d.mois, d.annee, o.dateembauche, o.numero_cnaps, o.matricule, d.idedition;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."DIRECTION_LISTE" ("IDDIR", "LIBELLEDIR", "DESCDIR", "IDDIRECTEUR", "ABBREVDIR") AS
SELECT ''     AS IDDIR,
       'Tous' AS LIBELLEDIR,
       'Tous' AS DESCDIR,
       0      AS IDDIRECTEUR,
       'Tous' AS ABBREVDIR
FROM DUAL

UNION ALL

SELECT "IDDIR","LIBELLEDIR","DESCDIR","IDDIRECTEUR","ABBREVDIR"
FROM DIRECTION;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."DISPONIBLITESTOCKOF_VIDE" ("IDINGREDIENTS", "LIBINGREDIENTS", "UNITE", "TYPESTOCK", "CATEGORIEINGREDIENT", "IDMAGASINLIB", "QTEAV", "QTETOTAL", "QUANTITE", "RESTE", "DATY") AS
SELECT '-'                          AS idIngredients,
       '-'                          AS libIngredients,
       '-'                          AS unite,
       '-'                          AS typestock,
       '-'                          AS categorieingredient,
       '-'                          AS idMagasinLib,
       CAST(0 AS NUMBER(30, 2))     AS qteAv,
       CAST(0 AS NUMBER(30, 2))     AS qteTotal,
       CAST(0 AS NUMBER(30, 2))     AS quantite,
       CAST(0 AS NUMBER(30, 2))     AS reste,
       CAST(NULL AS DATE)            AS daty
FROM DUAL;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."DISTRIBUTIONALIMENTDETAIL_LIB" ("ID", "IDMERE", "IDBATIMENT", "IDPARQUET", "IDALIMENT", "IDLOTSTOCK", "QTE", "RATIONPARTETE", "IDBATIMENTLIB", "IDPARQUETLIB", "IDALIMENTLIB") AS
SELECT
    dd."ID",dd."IDMERE",dd."IDBATIMENT",dd."IDPARQUET",dd."IDALIMENT",dd."IDLOTSTOCK",dd."QTE",dd."RATIONPARTETE",
    b.nombatiment AS idBatimentLib,
    p.val         AS idParquetLib,
    ai.libelle    AS idAlimentLib
FROM distributionAlimentDetail dd
         LEFT JOIN batiment b ON dd.idBatiment = b.id
         LEFT JOIN parquet p ON dd.idParquet = p.id
         LEFT JOIN as_ingredients ai ON dd.idAliment = ai.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."DISTRIBUTIONALIMENT_LIB" ("ID", "DATY", "IDFERME", "IDLOT", "IDFERMELIB", "IDLOTLIB", "IDSOUCHELIB", "ETAT", "ETATLIB") AS
SELECT
    d.ID,d.DATY,d.IDFERME,d.IDLOT,
    b2.val   AS idFermeLib,
    l.nomLot AS idLotLib,
    s.val AS idSoucheLib,
    d.ETAT AS ETAT,
    CASE d.ETAT
        WHEN 1  THEN 'CREE'
        WHEN 11 THEN 'VALIDE'
        WHEN 0  THEN 'ANULLE'
        END AS ETATLIB
FROM distributionAliment d
         LEFT JOIN magasin2 b2 ON d.idFerme = b2.id
         LEFT JOIN lot l ON d.idLot = l.id
         LEFT JOIN SOUCHE s ON l.idSouche = s.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."DMDACHATFILLE_LIB" ("ID", "IDMERE", "IDPRODUIT", "DESIGNATION", "QUANTITE", "PU", "TVA", "QTESTOCK", "UNITE", "REFERENCE") AS
SELECT
    d."ID",d."IDMERE",d."IDPRODUIT",d."DESIGNATION",d."QUANTITE",d."PU",d."TVA",d."QTESTOCK",
    au.val AS unite, d.REFERENCE
FROM DMDACHATFILLE d
         LEFT JOIN AS_INGREDIENTS ai
                   ON ai.id = d.idproduit
         LEFT JOIN AS_UNITE au
                   ON au.id = ai.UNITE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."DMDACHATFILLE_LIB_PRD" ("ID", "IDMERE", "IDPRODUIT", "DESIGNATION", "QUANTITE", "PU", "TVA", "QTESTOCK", "UNITE", "IDPRODUITLIB") AS
(
select d."ID",d."IDMERE",d."IDPRODUIT",d."DESIGNATION",d."QUANTITE",d."PU",d."TVA",d."QTESTOCK",d."UNITE", i.LIBELLE as idproduitLib
from DMDACHATFILLE_LIB d
         join AS_INGREDIENTS i on i.ID = d.IDPRODUIT);

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."DMDACHATLIB" ("ID", "DATY", "FOURNISSEUR", "FOURNISSEURLIB", "REMARQUE", "DATELIMITE", "IDMAGASINLIB", "IDCATEGORIELIB", "ETAT", "ETATLIB", "IDOBJET", "IDSERVICELIB", "IDPROVENANCE", "IDPROVENANCELIB", "SERVICE") AS
SELECT
    da.id,
    da.daty,
    da.fournisseur,
    f.nom AS fournisseurlib,
    da.remarque,
    da.dateLimite,
    m.val AS idMagasinLib,
    ci.val AS idCategorieLib,
    da.etat,
    CASE
        WHEN da.ETAT = 0
            THEN 'ANNULEE'
        WHEN da.ETAT = 1
            THEN 'CREEE'
        WHEN da.ETAT = 3
            THEN 'VISEE par Chef de departement'
        WHEN da.ETAT = 11
            THEN 'VISEE'
        END AS etatlib,
    da.idObjet,
    d.VAL AS idServiceLib,
    da.idProvenance,
    pr.val AS idProvenanceLib,
    da.SERVICE
FROM DMDACHAT da
         LEFT JOIN FOURNISSEUR f ON f.ID = da.fournisseur
         LEFT JOIN MAGASIN2 m ON da.idMagasin = m.ID
         LEFT JOIN categorieIngredient ci ON da.idCategorie = ci.id
         LEFT JOIN DEPARTEMENT d ON da.SERVICE = d.id
         LEFT JOIN provenance pr ON da.idProvenance=pr.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."DMDACHATLIB_TRAITE" ("ID", "DATY", "FOURNISSEUR", "FOURNISSEURLIB", "REMARQUE", "DATELIMITE", "IDMAGASINLIB", "IDCATEGORIELIB", "ETAT", "ETATLIB", "IDOBJET", "IDSERVICELIB", "SERVICE", "IDTRAITE", "TRAITE", "IDPROVENANCE", "IDPROVENANCELIB") AS
SELECT
    d.ID,
    d.DATY,
    d.FOURNISSEUR,
    d.FOURNISSEURLIB,
    d.REMARQUE,
    d.DATELIMITE,
    d.IDMAGASINLIB,
    d.IDCATEGORIELIB,
    d.ETAT,
    d.ETATLIB,
    d.IDOBJET,
    d.IDSERVICELIB,
    d.service,
    CASE
        WHEN suivi.totalCommande = 0 THEN '0'
        WHEN suivi.totalReste = 0 THEN '2'
        WHEN suivi.totalReste > 0 AND suivi.totalCommande > 0 THEN '1'
        ELSE '3'
        END AS IDTRAITE,
    CASE
        WHEN suivi.totalCommande = 0 THEN 'Non Trait&eacute;'
        WHEN suivi.totalReste = 0 THEN 'Trait&eacute;'
        WHEN suivi.totalReste > 0 AND suivi.totalCommande > 0 THEN 'Trait&eacute; Partiellement'
        ELSE 'Trait&eacute; avec surplus'
        END AS TRAITE,
    d.idProvenance,
    d.IDPROVENANCELIB
FROM DMDACHATLIB d
LEFT JOIN DMDACHATSUIVICOMMANDEGROUPEE suivi ON d.id = suivi.iddmdachat;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."DMDACHATSUIVICOMMANDE" ("PRODUIT", "PRODUITDESIGNATION", "IDDMDACHAT", "QUANTITEDEMANDE", "QUANTITEDEJACOMMANDE", "RESTEACOMMANDER") AS
SELECT
    df.IDPRODUIT AS produit,
    df.DESIGNATION AS produitDesignation,
    df.IDMERE AS idDmdAchat,
    df.QUANTITE AS quantiteDemande,
    NVL(bcf_sum.quantiteCommande, 0) AS quantiteDejaCommande,
    df.QUANTITE - NVL(bcf_sum.quantiteCommande, 0) AS resteACommander
FROM DMDACHATFILLE df
LEFT JOIN DMDACHAT d
    ON d.ID = df.IDMERE
LEFT JOIN (
    SELECT
        bc.IDDMDACHAT,
        bcf.PRODUIT,
        SUM(bcf.QUANTITE) AS quantiteCommande
    FROM AS_BONDECOMMANDE bc
    INNER JOIN AS_BONDECOMMANDE_FILLE bcf
        ON bcf.IDBC = bc.ID
    WHERE bc.IDDMDACHAT IS NOT NULL
      AND bcf.PRODUIT IS NOT NULL
      AND bc.ETAT <> 0
    GROUP BY bc.IDDMDACHAT, bcf.PRODUIT
) bcf_sum
    ON bcf_sum.IDDMDACHAT = df.IDMERE
   AND bcf_sum.PRODUIT = df.IDPRODUIT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."DMDACHATSUIVICOMMANDEGROUPEE" ("IDDMDACHAT", "TOTALCOMMANDE", "TOTALRESTE") AS
SELECT d.IDDMDACHAT, sum (d.QUANTITEDEJACOMMANDE ) AS totalCommande , sum (d.RESTEACOMMANDER ) AS totalReste FROM DMDACHATSUIVICOMMANDE d GROUP BY d.IDDMDACHAT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."DROITCONGE_PERS" ("ID", "DROIT", "NOMPERSONNEL", "MATRICULE", "IDDIRECTION") AS
SELECT
    sp.IDPERSONNEL AS id ,
    CAST(sp.PLUS AS NUMBER(30, 2)) AS droit,
    sp.NOM || ' ' || sp.PRENOM AS nomPersonnel,
    log.matricule ,
    log.iddirection
FROM SOLDECONGE_PERS sp
         LEFT JOIN LOG_PERSONNEL_V2 log ON log.id = sp.IDPERSONNEL;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."DROITDECONGE_PARPERS" ("IDPERSONNEL", "CONGE") AS
SELECT cd.idpersonnel AS idpersonnel,
       sum(cd.conge) AS conge
FROM soldeconge_fin_2023 cd
GROUP BY cd.idpersonnel;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."DROITDECONGE_PARPERSONNE" ("IDPERSONNEL", "CONGE") AS
SELECT dp.idpersonnel,
       round((dp.conge + pij.jourconge) * 2) / 2 - 1.5 AS conge
FROM droitdeconge_parpers dp
         LEFT JOIN paie_info_jours_mois3_bis pij ON dp.idpersonnel = pij.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."DUREETRAVAUXMACHINE" ("IDMACHINE", "NOMMACHINE", "DATY", "IDTRAVAUX", "DUREEESTIMATIF", "DUREE", "ECART") AS
SELECT
    IDINGREDIENTS AS idMachine,
    DESCRIPTIONOBJET AS nomMachine,
    DATY,
    ID_TRAVAUX AS idTravaux,
    DUREE_ESTIMATIVE_HEURES AS DureeEstimatif ,
    DUREE_REELLE_HEURES as Duree ,
    ECART_HEURES AS ecart
FROM V_DUREE_TRAVAUX_MACHINE
ORDER BY DATY DESC;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."DUREE_CYCLE_FAB" ("IDMERE", "TEMPS") AS
SELECT 
    off.IDMERE,
    ROUND(SUM(p.ecart) / 60, 2) AS temps 
FROM 
    PROCESS p
    JOIN FABRICATION fab ON fab.id = p.refobjet AND fab.etat >= 11
    JOIN OFFILLE off ON off.id = fab.IDOFFILLE
    JOIN OFAB o ON o.id = off.IDMERE
GROUP BY 
    off.IDMERE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."ECART_CARBU_GRAPH" ("IDMAGASINLIB", "DATY", "ECART") AS
(
SELECT
    i.IDMAGASINLIB AS IDMAGASINLIB,
    i.DATY AS daty,
    ifc.QUANTITETHEORIQUE - ifc.QUANTITE AS ecart
FROM INVENTAIRELIB i
JOIN INVENTAIRE_FILLE_CPL ifc ON ifc.IDINVENTAIRE = i.ID
JOIN MAGASIN m ON m.id = i.IDMAGASIN
);

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."ECLOSIONDETAIL_LIB" ("ID", "IDMERE", "IDQUALITEECLOSION", "QTE", "REMARQUE", "IDQUALITEECLOSIONLIB") AS
SELECT d."ID",
       d."IDMERE",
       d."IDQUALITEECLOSION",
       d."QTE",
       d."REMARQUE",
       qe."VAL" AS "IDQUALITEECLOSIONLIB"
FROM "ECLOSIONDETAIL" d
LEFT JOIN "QUALITEECLOSION" qe ON qe."ID" = d."IDQUALITEECLOSION";

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."ECLOSION_LIB" ("ID", "IDLOT", "DATEECLOSION", "NOMBREOEUFINITIAL", "IDECLOSOIR", "IDINCUBATEUR", "IDBATIMENT", "IDPARQUET", "ETAT", "IDINCUBATEURLIB", "IDBATIMENTLIB", "IDPARQUETLIB", "IDECLOSOIRLIB", "ETATLIB") AS
SELECT e."ID",
       e."IDLOT",
       e."DATEECLOSION",
       e."NOMBREOEUFINITIAL",
       e."IDECLOSOIR",
       e."IDINCUBATEUR",
       e."IDBATIMENT",
       e."IDPARQUET",
       e."ETAT",
       inc."VAL"       AS "IDINCUBATEURLIB",
       b."NOMBATIMENT" AS "IDBATIMENTLIB",
       p."VAL"         AS "IDPARQUETLIB",
       ec."VAL"        AS "IDECLOSOIRLIB",
       CASE e."ETAT"
           WHEN 1  THEN 'CREE'
           WHEN 11 THEN 'VALIDE'
           WHEN 0  THEN 'ANULLE'
           END              AS "ETATLIB"
FROM "ECLOSION" e
         LEFT JOIN "INCUBATEUR" inc ON inc."ID" = e."IDINCUBATEUR"
         LEFT JOIN "BATIMENT" b ON b."ID" = e."IDBATIMENT"
         LEFT JOIN "PARQUET" p ON p."ID" = e."IDPARQUET"
         LEFT JOIN ECLOSOIR ec ON ec.ID = e.IDECLOSOIR;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."ECRITURE_DELA_PAIE" ("IDELEMENTPAIE", "MOIS", "ANNEE", "GAIN", "RETENUE", "IDEDITION", "COMPTEGEN_DB", "COMPTEGEN_CR", "COMPTEANA_DB", "COMPTEANA_CR", "TYPERUBRIQUE", "RUBRIQUE_LIBELLE", "IDDIRECTION", "IMPOSABLE") AS
SELECT peel.idelementpaie,
       peel.mois,
       peel.annee,
       sum(peel.gain) AS gain,
       sum(peel.retenue) AS retenue,
       peel.idedition,
       peel.comptegen_db,
       peel.comptegen_cr,
       peel.compteana_db,
       peel.compteana_cr,
       peel.typerubrique,
       peel.rubrique_libelle,
       peel.iddirection,
       peel.imposable
FROM paie_edition_ecriture_ligne peel
GROUP BY peel.idelementpaie, peel.mois, peel.annee, peel.idedition, peel.comptegen_db, peel.comptegen_cr, peel.compteana_db, peel.compteana_cr, peel.typerubrique, peel.rubrique_libelle, peel.iddirection, peel.code, peel.imposable
ORDER BY peel.typerubrique DESC, peel.code;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."ECRITURE_DELA_PAIE_CREDIT" ("MOIS", "ANNEE", "GAIN", "RETENUE", "IDEDITION", "COMPTEGEN_DEBIT", "COMPTEGEN_CREDIT", "TYPERUBRIQUE", "IDDIRECTION") AS
SELECT e.mois,
       e.annee,
       sum(e.gain) AS gain,
       sum(e.retenue) AS retenue,
       e.idedition,
       CAST('''' AS varchar(250)) AS comptegen_debit,
       e.comptegen_cr AS comptegen_credit,
       e.typerubrique,
       e.iddirection
FROM ecriture_dela_paie e
WHERE e.comptegen_cr IS NOT NULL
GROUP BY e.mois, e.annee, e.idedition, e.comptegen_cr, e.typerubrique, e.iddirection;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."ECRITURE_DELA_PAIE_DEBIT" ("MOIS", "ANNEE", "GAIN", "RETENUE", "IDEDITION", "COMPTEGEN_DEBIT", "COMPTEGEN_CREDIT", "TYPERUBRIQUE", "IDDIRECTION") AS
SELECT e.mois,
       e.annee,
       sum(e.gain) AS gain,
       sum(e.retenue) AS retenue,
       e.idedition,
       e.comptegen_db AS comptegen_debit,
       CAST('''' AS varchar(250)) AS comptegen_credit,
       e.typerubrique,
       e.iddirection
FROM ecriture_dela_paie e
WHERE e.comptegen_db IS NOT NULL
GROUP BY e.mois, e.annee, e.idedition, e.comptegen_db, e.typerubrique, e.iddirection;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."ECRITURE_DELA_PAIE_REGR" ("MOIS", "ANNEE", "GAIN", "RETENUE", "IDEDITION", "COMPTEGEN_DEBIT", "COMPTEGEN_CREDIT", "TYPERUBRIQUE", "IDDIRECTION") AS
SELECT ed.mois,
       ed.annee,
       ed.gain,
       ed.retenue,
       ed.idedition,
       ed.comptegen_debit,
       ed.comptegen_credit,
       ed.typerubrique,
       ed.iddirection
FROM ecriture_dela_paie_debit ed
UNION
SELECT ec.mois,
       ec.annee,
       ec.gain,
       ec.retenue,
       ec.idedition,
       ec.comptegen_debit,
       ec.comptegen_credit,
       ec.typerubrique,
       ec.iddirection
FROM ecriture_dela_paie_credit ec;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."ECRITURE_DELA_PAIE_REGR_COMPTE" ("MOIS", "ANNEE", "GAIN", "RETENUE", "IDEDITION", "COMPTEGEN_DEBIT", "COMPTEGEN_CREDIT", "TYPERUBRIQUE", "IDDIRECTION", "COMPTELIBELLE") AS
SELECT edpr.mois,
       edpr.annee,
       edpr.gain,
       edpr.retenue,
       edpr.idedition,
       edpr.comptegen_debit,
       edpr.comptegen_credit,
       edpr.typerubrique,
       edpr.iddirection,
       cc.libelle AS comptelibelle
FROM ecriture_dela_paie_regr edpr
         LEFT JOIN compta_compte cc ON cc.compte = COALESCE(edpr.comptegen_debit, edpr.comptegen_credit);

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."ECRITURE_IMPOT" ("ID", "COMPTE", "DEBIT", "CREDIT", "REMARQUE", "LIBELLEPIECE", "IDMERE", "REFERENCE_ENGAGEMENT", "COMPTE_AUX", "LETTRAGE", "JOURNAL", "EXERCICE", "ETAT", "DATY", "FOLIO", "ANALYTIQUE", "SOURCE", "DATYMERE", "CODEIMPOT", "MOISDECLARATION") AS
select
    se.ID,
    se.COMPTE,
    se.DEBIT,
    se.CREDIT,
    se.REMARQUE,
    se.LIBELLEPIECE,
    se.IDMERE,
    se.REFERENCE_ENGAGEMENT,
    se.COMPTE_AUX,
    se.LETTRAGE,
    se.JOURNAL,
    se.EXERCICE,
    se.ETAT,
    se.DATY,
    se.FOLIO,
    se.ANALYTIQUE,
    se.SOURCE,
    ce.daty as datymere,
    cc.COMPTE as codeimpot,
    sed.MOISDECLARATION
from COMPTA_SOUS_ECRITURE se
         join COMPTA_ECRITURE ce on ce.id=se.IDMERE
         join COMPTA_COMPTE cc on cc.COMPTE=se.COMPTE
         JOIN SOUSECRITUREDECLARER sed ON sed.IDSOUSECRITURE = se.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."EFFECTIF_LOG_PERSONNEL" ("SEXE", "NOMBRE", "IDCATEGORIE", "IDCATEGORIELIB", "IDDEPARTEMENT", "DEPARTEMENTLIB") AS
SELECT
    CASE
        WHEN sexe = 'Masculin' THEN 'Masculin'
        WHEN sexe = 'Feminin' THEN 'Feminin'
        ELSE 'Non defini'
    END AS sexe,
    COUNT(*) AS nombre,
    idCategorie,
    idCategorieLib,
    IDDEPARTEMENT AS idDepartement,
    departementLib
FROM LOG_PERSONNEL_GRAPHE
GROUP BY
    CASE
        WHEN sexe = 'Masculin' THEN 'Masculin'
        WHEN sexe = 'Feminin' THEN 'Feminin'
        ELSE 'Non defini'
    END,
    idCategorie,
    idCategorieLib,
    IDDEPARTEMENT,
    departementLib;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."ELEMENTINSPECTIONMACHINELIB" ("ID", "IDELEMENTINSPECTION", "IDMACHINE", "IDELEMENTINSPECTIONLIB", "IDMACHINELIB", "MOTSCLESSS") AS
SELECT SQ.ID,SQ.IDELEMENTINSPECTION,SQ.IDMACHINE,SQ.IDELEMENTINSPECTIONLIB,SQ.IDMACHINELIB,
	       (NVL(TO_CHAR(ID),'') || ' | ' || NVL(TO_CHAR(IDELEMENTINSPECTION),'') || ' | ' || NVL(TO_CHAR(IDMACHINE),'') || ' | ' || NVL(TO_CHAR(IDELEMENTINSPECTIONLIB),'') || ' | ' || NVL(TO_CHAR(IDMACHINELIB),'')) AS MOTSCLESSS
	FROM (
	         SELECT
	             eim.id,
	             eim.idElementInspection as idElementInspection,
	             eim.idMachine as idMachine,
	             ei.val      AS idElementInspectionLib,
	             m.DESCRIPTIONOBJET       AS idMachineLib
	         FROM ElementInspectionMachine eim
	                  LEFT JOIN ElementInspection ei
	                            ON eim.idElementInspection = ei.id
	                  LEFT JOIN AS_INGREDIENT_MAINTENANCE m
	                            ON eim.idMachine = m.id
	
	     ) SQ;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."EMPLOI_LIB" ("ID", "VAL", "DESCE", "IDMETIER", "IDMETIERLIB", "IDCODEROMELIB", "IDSOUSFAMILLEPROLIB", "IDFAMILLEPROLIB") AS
(
       select
       e.ID,e.VAL,e.DESCE,e.IDMETIER,
       m.val as idmetierlib,
       m.idcoderomelib,
       m.idsousfamilleprolib,
       m.idfamilleprolib
       from
       emploi e
       left join metierlib m on e.idmetier=m.id
);

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."EMPLOYEEONBOARDINGCHECKLISTCPL" ("ID", "IDSESSIONONBOARDING", "IDONBOARDINGITEM", "ESTTERMINER", "DATEFIN", "REMARQUE", "ESTTERMINERLIB", "IDSESSION", "PROGRESSION", "ETAT", "ETATLIB", "IDONBOARDINGITEMLIB") AS
SELECT
    c.ID,c.IDSESSIONONBOARDING,c.IDONBOARDINGITEM,c.ESTTERMINER,c.DATEFIN,c.REMARQUE,
    CASE
        WHEN c.estTerminer = 0 THEN 'Non'
        WHEN c.estTerminer = 1 THEN 'Oui'
        END AS estTerminerLib,

    s.id AS idSession,
    s.progression,
    s.etat,
    CASE
        WHEN s.etat = 1  THEN 'En cours'
        WHEN s.etat = 11 THEN 'Termine'
        END AS etatlib,

    ofi.titre AS idOnboardingItemlib

FROM employee_onboarding_checklist c
         JOIN employee_onboarding_sessions s
              ON c.idSessionOnboarding = s.id
         JOIN onboarding_fille ofi
              ON c.idOnboardingItem = ofi.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."EMPLOYEEONBOARDINGSESSIONSCPL" ("ID", "DATEDEBUT", "DATEFIN", "ETAT", "PROGRESSION", "IDPERSONNEL", "PERSONNELLIB", "IDONBOARDING", "ONBOARDINGLIB") AS
SELECT
    s.id,
    s.dateDebut,
    s.dateFin,
    s.etat,
    s.progression,

    p.id AS idPersonnel,
    p.nom as personnelLib,

    o.id AS idOnboarding,
    o.nom as onboardinglib
FROM employee_onboarding_sessions s
         JOIN log_personnel_v2 p ON s.idPersonnel = p.id
         JOIN onboarding_mere o ON s.idOnboarding = o.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."EMPLOYE_COMPLET" ("ID", "NOM", "PRENOM", "ID_PERS", "INITIALE", "MATRICULE", "DATE_NAISSANCE", "LIEU_NAISSANCE_COMMUNE", "SEXE", "NUMERO_CIN", "DATE_CIN", "DATE_DUPL_CIN", "LIEU_DELIVRANCE_CIN", "ADRESSE", "DIRECTION", "FOKOTANY", "NATIONALITE", "ACTE_NAISSANCE", "SITUATION_MATRIMONIAL", "IDCONJOINT", "SERVICE", "IDFONCTION", "CTG", "IDCATEGORIE", "CLASSEE", "INDICEGRADE", "INDICE_FONCTIONNEL", "MATRICULE_PATRON", "STATUT", "MODE_PAIEMENT", "CODE_AGENCE_BANQUE", "BANQUE_NUMERO_COMPTE", "BANQUE_COMPTE_CLE", "PERMIS_CONDUIRE", "REMARQUE", "CHEMIN_PERMIS", "CTURGENCE_NOM_PRENOM", "CTURGENCE_TELEPHONE1", "CTURGENCE_TELEPHONE2", "CTURGENCE_TELEPHONE3", "DATEEMBAUCHE", "DATESAISIE", "CODE_DR", "BANQUE_CODE", "ECHELON", "ETAT", "VEHICULEE", "DATE_DERNIERPROMO", "DROIT_HS", "HEUREJOURNALIER", "HEUREHEBDOMADAIRE", "HEUREMENSUEL", "NUMERO_CNAPS", "NUMERO_OSTIE", "TEMPORAIRE", "NBENFANT", "INDESIRABLE", "DUREE", "TELEPHONE", "MAIL", "IDCATEGORIE_PAIE", "IDQUALIFICATION", "DISCIPLINE", "FORMATION", "ANNEEEXPERIENCE", "PERSONNEL_ETAT", "DEBUTCONTRAT", "FINCONTRAT", "REFUSER", "IDETATHIERARCHIE", "ETATVISA", "ETATANNULE", "TYPECONTRAT", "CHEMINIMAGE", "CODE_POSTAL", "IDDEPARTEMENT", "MERE", "PERE", "IDCIVILITELIB", "IDCIVILITE", "IDBANQUE", "IDBANQUELIB", "IDAGENCE", "CODEAGENCE", "IDAGENCELIB", "IDSTATUT", "IDSTATUTLIB", "UNITE", "RETRAITECOMPL") AS
SELECT logp.id,
       logp.nom,
       logp.prenom,
       logp.id_pers,
       paie.initiale,
       paie.matricule,
       logp.date_naissance,
       paie.lieu_naissance_commune,
       logp.sexe,
       logp.numero_cin,
       logp.date_cin,
       logp.date_dupl_cin,
       paie.lieu_delivrance_cin,
       logp.adresse,
       logp.direction,
       logp.fokotany,
       logp.nationalite,
       logp.acte_naissance,
       paie.situation_matrimonial,
       paie.idconjoint,
       logp.service,
       paie.idfonction,
       paie.ctg,
       paie.idcategorie,
       paie.classee,
       paie.indicegrade,
       paie.indice_fonctionnel,
       paie.matricule_patron,
       paie.statut,
       paie.mode_paiement,
       paie.code_agence_banque,
       paie.banque_numero_compte,
       paie.banque_compte_cle,
       logp.permis_conduire,
       logp.remarque,
       logp.chemin_permis,
       paie.cturgence_nom_prenom,
       paie.cturgence_telephone1,
       paie.cturgence_telephone2,
       paie.cturgence_telephone3,
       paie.dateembauche,
       paie.datesaisie,
       serv.code_dr,
       trs.val AS banque_code,
       paie.echelon,
       paie.etat,
       paie.vehiculee,
       tab.date_dernierpromo,
       paie.droit_hs,
       paie.heurejournalier,
       paie.heurehebdomadaire,
       paie.heuremensuel,
       paie.numero_cnaps,
       paie.numero_ostie,
       paie.temporaire,
       paie.nbenfant,
       paie.indesirable,
       paie.duree,
       paie.telephone,
       paie.mail,
       paie.idcategorie_paie,
       paie.idqualification,
       paie.discipline,
       paie.formation,
       paie.anneeexperience,
       paie.personnel_etat,
       paie.debutcontrat,
       paie.fincontrat,
       logp.refuser,
       logp.idhierarchie AS idetathierarchie,
       et.etatvisa,
       et.etatannule,
       paie.typecontrat,
       logp.cheminImage,
       paie.code_postal,
       paie.IDDEPARTEMENT,
       logp.mere,
       logp.pere,
       civ.val as idcivilitelib,
       logp.IDCIVILITE,
       paie.idbanque,
       bnq.val as idbanquelib,
       paie.idagence,
       bnqa.codeagence,
       bnqa.nom as idagencelib,
       paie.idstatut,
       stat.val as idStatutLib,
       paie.unite,
       paie.retraiteCompl
FROM log_personnel logp
         LEFT JOIN ( SELECT paie_avancement.id_logpers,
                            max(paie_avancement.datedecision) AS date_dernierpromo
                     FROM paie_avancement
                     GROUP BY paie_avancement.id_logpers) tab ON logp.id = tab.id_logpers
         LEFT JOIN paie_info_personnel paie ON logp.id = paie.id
         LEFT JOIN log_service serv ON serv.id = logp.service
         LEFT JOIN trs_banques_agences trs ON paie.code_agence_banque = trs.id
         LEFT JOIN categorie_paie cp ON cp.id = paie.idcategorie_paie
         LEFT JOIN qualification_paie qp ON qp.id = paie.idqualification
         LEFT JOIN categorie_qualification cq ON cq.idcategorie = paie.idcategorie_paie AND cq.idqualification = paie.idqualification AND cq.REMARQUE = logp.id
         LEFT JOIN etathierarchie et ON et.id = logp.idhierarchie
         LEFT JOIN civilite civ ON logp.idcivilite = civ.id
         LEFT JOIN banque bnq ON bnq.id = paie.idbanque
         LEFT JOIN BANQUE_AGENCE bnqa ON bnqa.id = paie.idagence
         LEFT JOIN PAIE_STATUT stat ON stat.id = paie.idStatut;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."EMPLOYE_COMPLET2" ("ID", "NOM", "PRENOM", "ID_PERS", "INITIALE", "MATRICULE", "DATE_NAISSANCE", "LIEU_NAISSANCE_COMMUNE", "SEXE", "NUMERO_CIN", "DATE_CIN", "DATE_DUPL_CIN", "LIEU_DELIVRANCE_CIN", "ADRESSE", "FOKOTANY", "NATIONALITE", "ACTE_NAISSANCE", "SITUATION_MATRIMONIAL", "IDCONJOINT", "DIRECTION", "SERVICE", "IDFONCTION", "CTG", "IDCATEGORIE", "CLASSEE", "INDICEGRADE", "INDICE_FONCTIONNEL", "MATRICULE_PATRON", "STATUT", "MODE_PAIEMENT", "CODE_AGENCE_BANQUE", "BANQUE_NUMERO_COMPTE", "BANQUE_COMPTE_CLE", "PERMIS_CONDUIRE", "REMARQUE", "CHEMIN_PERMIS", "CTURGENCE_NOM_PRENOM", "CTURGENCE_TELEPHONE1", "CTURGENCE_TELEPHONE2", "CTURGENCE_TELEPHONE3", "DATEEMBAUCHE", "DATESAISIE", "CODE_DR", "BANQUE_CODE", "ECHELON", "ETAT", "VEHICULEE", "DATE_DERNIERPROMO", "DROIT_HS", "HEUREJOURNALIER", "HEUREHEBDOMADAIRE", "HEUREMENSUEL", "NUMERO_CNAPS", "NUMERO_OSTIE", "TEMPORAIRE", "NBENFANT", "INDESIRABLE", "DUREE", "TELEPHONE", "MAIL", "IDCATEGORIE_PAIE", "IDQUALIFICATION", "DISCIPLINE", "FORMATION", "ANNEEEXPERIENCE", "PERSONNEL_ETAT", "REFUSER", "IDETATHIERARCHIE", "ETATVISA", "ETATANNULE", "IDROLE", "RANG", "IDDEPARTEMENT") AS
SELECT logp.id,
       logp.nom,
       logp.prenom,
       logp.id_pers,
       paie.initiale,
       paie.matricule,
       logp.date_naissance,
       paie.lieu_naissance_commune,
       logp.sexe,
       logp.numero_cin,
       logp.date_cin,
       logp.date_dupl_cin,
