CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."FACTUREFOURNISSEURCPL_TOUS_FAE" ("ID", "IDFOURNISSEUR", "IDFOURNISSEURLIB", "IDMODEPAIEMENT", "IDMODEPAIEMENTLIB", "DATY", "DESIGNATION", "DATEECHEANCEPAIEMENT", "ETATLIB", "REFERENCE", "IDBC", "IDMAGASIN", "IDMAGASINLIB", "DEVISE", "IDDEVISE", "ETAT", "TAUX", "MONTANTTVA", "MONTANTHT", "TAUXDECHANGE", "MONTANTTTC", "MONTANTPAYE", "MONTANTRESTE", "IDOBJET", "IDREF", "IDSERVICELIB", "IDTYPEFACTURE", "IDFACTUREPRINCIPALE", "TYPEFACTURE") AS
