CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."FACTUREFOURNISSEURCPL_TRAVAUX" ("ID", "IDFOURNISSEUR", "IDFOURNISSEURLIB", "IDMODEPAIEMENT", "IDMODEPAIEMENTLIB", "DATY", "DESIGNATION", "DATEECHEANCEPAIEMENT", "ETAT", "ETATLIB", "REFERENCE", "IDBC", "IDMAGASIN", "DEVISE", "TAUX", "IDMAGASINLIB", "IDDEVISE", "MONTANTTVA", "MONTANTHT", "MONTANTTTC", "MONTANTTTCAR", "MONTANTPAYE", "MONTANTRESTE", "TAUXDECHANGE", "IDPREVISION", "ESTPREVULIB", "IDOBJET", "IDREF", "IDTYPEFACTURE", "TYPEFACTURE", "NUMERO", "TYPEACHAT", "IDTRAVAUX") AS
SELECT f.ID,
	       f.IDFOURNISSEUR,
	       f2.NOM  AS IDFOURNISSEURLIB,
	       f.IDMODEPAIEMENT,
	       m.VAL   AS IDMODEPAIEMENTLIB,
	       f.DATY,
	       f.DESIGNATION,
	       f.DATEECHEANCEPAIEMENT,
	       f.ETAT,
	       CASE
	           WHEN f.ETAT = 1
	               THEN 'CREEE'
	           WHEN f.ETAT = 0
	               THEN 'ANNULEE'
	           WHEN f.ETAT = 11
	               THEN 'VISEE'
	           END AS ETATLIB,
	       f.REFERENCE,
	       f.IDBC,
	       f.IDMAGASIN,
	       f.DEVISE,
	       case
	           when f.TAUX=0 then 1
	           else f.TAUX
	           end as taux,
	       p.VAL   AS idMagasinLib,
	       f3.IDDEVISE,
	       cast(f3.MONTANTTVA as number(30,2)) as MONTANTTVA,
	       CAST(f3.MONTANTTTC-f3.MONTANTTVA as number(30,2)) AS MONTANTHT,
	       cast(f3.MONTANTTTC as number(30,2)) as montantttc,
	       cast(f3.MONTANTTTC*f3.tauxdechange as number(30,2)) as MONTANTTTCAR,
	       cast(nvl(mv.debit,0) AS NUMBER(30,2)) AS montantpaye,
	       cast(f3.MONTANTTTC-nvl(mv.debit,0) AS NUMBER(30,2)) AS montantreste,
	       cast(nvl(f3.tauxdechange,0) AS  NUMBER(30,2)) AS tauxdechange,
	       prev.id as idPrevision,
	       CASE
	           WHEN f.estprevu=0 THEN 'NON'
	           ELSE 'OUI'
	           END
	           AS estprevulib,
	       f.IDOBJET,
	       f.IDREF,
	       f.IDTYPEFACTURE,
	       tf.VAL as typefacture,
	       f.numero,
	       f.typeachat,
	       t.id AS idTravaux
	FROM FACTUREFOURNISSEUR f
	         LEFT JOIN FOURNISSEUR f2 ON f2.ID = f.IDFOURNISSEUR
	         LEFT JOIN MODEPAIEMENT m ON m.ID = f.IDMODEPAIEMENT
	         LEFT JOIN MAGASIN p ON p.ID = f.IDMAGASIN
	         JOIN FACTUREFOURNISSEURMONTANT f3 ON f.ID = f3.id
	         LEFT JOIN mouvementcaisseGroupeFacture mv ON f.id=mv.IDORIGINE
	         LEFT JOIN prevision prev ON prev.idfacture=f.id
	         left join type_facture tf on tf.id = f.IDTYPEFACTURE
	         LEFT JOIN dmdAchat d ON f.idDmdAchat = d.id
	         LEFT JOIN TRAVAUX t ON d.idObjet = t.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."FACTUREFOURNISSEURCPL_USD" ("ID", "IDFOURNISSEUR", "IDFOURNISSEURLIB", "IDMODEPAIEMENT", "IDMODEPAIEMENTLIB", "DATY", "DESIGNATION", "DATEECHEANCEPAIEMENT", "ETAT", "ETATLIB", "REFERENCE", "IDBC", "IDMAGASIN", "DEVISE", "TAUX", "IDMAGASINLIB", "IDDEVISE", "MONTANTTVA", "MONTANTHT", "MONTANTTTC", "MONTANTTTCAR", "MONTANTPAYE", "MONTANTRESTE", "TAUXDECHANGE", "IDTYPEFACTURE", "IDFACTUREPRINCIPALE", "IDSERVICELIB") AS
SELECT
	ID,
	IDFOURNISSEUR,
	IDFOURNISSEURLIB,
	IDMODEPAIEMENT,
	IDMODEPAIEMENTLIB,
	DATY,
	DESIGNATION,
	DATEECHEANCEPAIEMENT,
	ETAT,
	ETATLIB,
	REFERENCE,
	IDBC,
	IDMAGASIN,
	DEVISE,
	TAUX,
	IDMAGASINLIB,
	IDDEVISE,
	CAST(MONTANTTVA AS NUMBER(30,5)) AS MONTANTTVA,
	CAST(MONTANTHT AS NUMBER(30,5)) AS MONTANTHT,
	CAST(MONTANTTTC AS NUMBER(30,5)) AS MONTANTTTC,
	CAST(MONTANTTTCAR AS NUMBER(30,5)) AS MONTANTTTCAR,
	CAST(MONTANTPAYE AS NUMBER(30,5)) AS MONTANTPAYE,
	CAST(MONTANTRESTE AS NUMBER(30,5)) AS MONTANTRESTE,
	TAUXDECHANGE,
	IDTYPEFACTURE,
	IDFACTUREPRINCIPALE,
	idServiceLib
FROM
	FACTUREFOURNISSEURCPL
WHERE
	idDEVISE = 'USD';

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."FACTUREFOURNISSEURCPL_USD_FAE" ("ID", "IDFOURNISSEUR", "IDFOURNISSEURLIB", "IDMODEPAIEMENT", "IDMODEPAIEMENTLIB", "DATY", "DESIGNATION", "DATEECHEANCEPAIEMENT", "ETAT", "ETATLIB", "REFERENCE", "IDBC", "IDMAGASIN", "DEVISE", "TAUX", "IDMAGASINLIB", "IDDEVISE", "MONTANTTVA", "MONTANTHT", "MONTANTTTC", "MONTANTTTCAR", "MONTANTPAYE", "MONTANTRESTE", "TAUXDECHANGE", "IDTYPEFACTURE", "IDFACTUREPRINCIPALE", "IDSERVICELIB", "TYPEFACTURE") AS
SELECT
    ID,
    IDFOURNISSEUR,
    IDFOURNISSEURLIB,
    IDMODEPAIEMENT,
    IDMODEPAIEMENTLIB,
    DATY,
    DESIGNATION,
    DATEECHEANCEPAIEMENT,
    ETAT,
    ETATLIB,
    REFERENCE,
    IDBC,
    IDMAGASIN,
    DEVISE,
    TAUX,
    IDMAGASINLIB,
    IDDEVISE,
    CAST(MONTANTTVA AS NUMBER(30,5)) AS MONTANTTVA,
    CAST(MONTANTHT AS NUMBER(30,5)) AS MONTANTHT,
    CAST(MONTANTTTC AS NUMBER(30,5)) AS MONTANTTTC,
    CAST(MONTANTTTCAR AS NUMBER(30,5)) AS MONTANTTTCAR,
    CAST(MONTANTPAYE AS NUMBER(30,5)) AS MONTANTPAYE,
    CAST(MONTANTRESTE AS NUMBER(30,5)) AS MONTANTRESTE,
    TAUXDECHANGE,
    IDTYPEFACTURE,
    IDFACTUREPRINCIPALE,
    idServiceLib,
    TYPEFACTURE 
FROM
    FACTUREFOURNISSEURCPL
WHERE
    idDEVISE = 'USD' AND
    id NOT IN (
        SELECT idfactureprincipale
        FROM FACTUREFOURNISSEURCPL
        WHERE idfactureprincipale IS NOT NULL );

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."FACTUREFOURNISSEURCPL_VISEE" ("ID", "IDFOURNISSEUR", "IDFOURNISSEURLIB", "IDMODEPAIEMENT", "IDMODEPAIEMENTLIB", "DATY", "DESIGNATION", "DATEECHEANCEPAIEMENT", "ETAT", "ETATLIB", "REFERENCE", "IDBC", "IDMAGASIN", "DEVISE", "TAUX", "IDMAGASINLIB") AS
SELECT f."ID",f."IDFOURNISSEUR",f."IDFOURNISSEURLIB",f."IDMODEPAIEMENT",f."IDMODEPAIEMENTLIB",f."DATY",f."DESIGNATION",f."DATEECHEANCEPAIEMENT",f."ETAT",f."ETATLIB",f."REFERENCE",f."IDBC",f."IDMAGASIN",f."DEVISE",f."TAUX",f."IDMAGASINLIB"
FROM FACTUREFOURNISSEURCPL f
WHERE f.ETAT = 11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."FACTUREFOURNISSEURFILLECPL" ("ID", "IDFACTUREFOURNISSEUR", "IDPRODUIT", "IDPRODUITLIB", "QTE", "PU", "REMISES", "IDBCDETAIL", "TVA", "COMPTE", "IDDEVISE", "DATY", "MONTANT", "MONTANTTOTAL", "MONTANTREMISE", "MONTANTHT", "MONTANTTVA", "MONTANTTTC", "FRAISACCESOIRE", "MONTANTAVECFRAISACCESSOIRE", "PUAVECFRAISACCESSOIRE", "LIBELLEEXACTE", "IDPREVISION", "IDPOINT", "IDPOINTLIB", "IDMAGASIN", "IDMAGASINLIB", "IDCATEGORIE", "IDCATEGORIELIB", "DESIGNATION") AS
(
SELECT f.ID,
       f.IDFACTUREFOURNISSEUR,
       f.IDPRODUIT,
       p.LIBELLE                                                         AS IDPRODUITLIB,
       f.QTE,
       f.PU,
       f.REMISES,
       f.IDBCDETAIL,
       f.TVA,
       f.COMPTE,
       f.IDDEVISE,
       f2.DATY,

       ----------------------------------------------------------
       -- 1 Montant HT brut
       ----------------------------------------------------------
       CAST(f.QTE * f.PU AS NUMBER(30, 2))                               AS montant,
       CAST(f.QTE * f.PU AS NUMBER(30, 2))                               AS montanttotal,

       ----------------------------------------------------------
       -- 2 Montant remise (appliquee sur HT)
       ----------------------------------------------------------
       CAST((NVL(f.remises, 0) / 100) * (f.QTE * f.PU) AS NUMBER(30, 2)) AS montantRemise,

       ----------------------------------------------------------
       -- 3 Montant HT net apres remise
       ----------------------------------------------------------
       CAST((f.QTE * f.PU) - ((NVL(f.remises, 0) / 100) * (f.QTE * f.PU))
           AS NUMBER(30, 2))                                             AS montantht,

       ----------------------------------------------------------
       -- 4 TVA sur montant HT net
       ----------------------------------------------------------
       CAST(
               ((f.QTE * f.PU) - ((NVL(f.remises, 0) / 100) * (f.QTE * f.PU)))
                   * f.TVA / 100
           AS NUMBER(30, 2)
       )                                                                 AS montanttva,

       ----------------------------------------------------------
       -- 5 Montant TTC net (HT net + TVA)
       ----------------------------------------------------------
       CAST(
               ((f.QTE * f.PU) - ((NVL(f.remises, 0) / 100) * (f.QTE * f.PU)))
                   + (
                   ((f.QTE * f.PU) - ((NVL(f.remises, 0) / 100) * (f.QTE * f.PU)))
                       * f.TVA / 100
                   )
           AS NUMBER(30, 2)
       )                                                                 AS montantttc,

       ----------------------------------------------------------
       -- 6 Frais accessoires
       ----------------------------------------------------------
       NVL(r.montant, 0)                                                 AS fraisaccesoire,

       ----------------------------------------------------------
       -- 7 Montant total avec frais (TTC + accessoires)
       ----------------------------------------------------------
       CAST(
               (
                   ((f.QTE * f.PU * f.TAUXDECHANGE) - ((NVL(f.remises, 0) / 100) * (f.QTE * f.PU * f.TAUXDECHANGE)))
                   )
                   + NVL(r.montant, 0)
           AS NUMBER(30, 2)
       )                                                                 AS montantavecfraisaccessoire,

       ----------------------------------------------------------
       -- 8 PU unitaire HT + accessoires
       ----------------------------------------------------------
       CAST(
               (
                   (
                       ((f.QTE * f.PU * f.TAUXDECHANGE) - ((NVL(f.remises, 0) / 100) * (f.QTE * f.PU * f.TAUXDECHANGE)))
                       )
                       + NVL(r.montant, 0)
                   ) / f.QTE
           AS NUMBER(30, 2)
       )                                                                 AS puavecfraisaccessoire,

       ----------------------------------------------------------
       -- Info produit & localisation
       ----------------------------------------------------------
       NVL(p.LIBELLEEXTACTE, p.LIBELLE)                                  AS libelleexacte,
       f.IDPREVISION,
       p2.ID                                                             AS idpoint,
       p2.VAL                                                            AS idpointlib,
       m.ID                                                              AS idmagasin,
       m.VAL                                                             AS idmagasinlib,
       c.ID                                                              AS idcategorie,
       c.VAL                                                             AS idcategorielib,
       f.designation

FROM FACTUREFOURNISSEURFILLE f
         LEFT JOIN FACTUREFOURNISSEUR f2
                   ON f2.ID = f.IDFACTUREFOURNISSEUR
         LEFT JOIN MAGASIN m
                   ON m.ID = f2.IDMAGASIN
         LEFT JOIN POINT p2
                   ON p2.ID = m.IDPOINT
         LEFT JOIN AS_INGREDIENTS p
                   ON p.ID = f.IDPRODUIT
         LEFT JOIN CATEGORIEINGREDIENT c
                   ON c.ID = p.CATEGORIEINGREDIENT
         LEFT JOIN REPARTIRIONPGGROUPEE r
                   ON r.IDFACTUREFILLE = f.ID
    );

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."FACTUREFOURNISSEURFILLECPLC" ("ID", "IDFACTUREFOURNISSEUR", "IDPRODUIT", "IDPRODUITLIB", "QTE", "PU", "REMISES", "IDBCDETAIL", "TVA", "IDDEVISE", "DATY", "MONTANT", "MONTANTREMISE", "MONTANTHT", "MONTANTTVA", "MONTANTTTC", "FRAISACCESOIRE", "MONTANTAVECFRAISACCESSOIRE", "PUAVECFRAISACCESSOIRE", "LIBELLEEXACTE", "IDPREVISION", "COMPTE") AS
SELECT
    f."ID",f."IDFACTUREFOURNISSEUR",f."IDPRODUIT",f."IDPRODUITLIB",f."QTE",f."PU",f."REMISES",f."IDBCDETAIL",f."TVA",f."IDDEVISE",f."DATY",f."MONTANT",f."MONTANTREMISE",f."MONTANTHT",f."MONTANTTVA",f."MONTANTTTC",f."FRAISACCESOIRE",f."MONTANTAVECFRAISACCESSOIRE",f."PUAVECFRAISACCESSOIRE",f."LIBELLEEXACTE",f."IDPREVISION" ,
    f2.COMPTE
FROM FACTUREFOURNISSEURFILLECPL f
         LEFT JOIN FACTUREFOURNISSEURFILLE f2
                   ON f.ID  = f2.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."FACTUREFOURNISSEURFILLEVALIDE" ("ID", "IDFACTUREFOURNISSEUR", "IDPRODUIT", "PU", "REMISES", "IDBCDETAIL", "TVA", "DEVISE", "TAUXDECHANGE", "IDDEVISE", "DESIGNATION", "COMPTE", "MOIS", "ANNEE", "QTE", "MONTANTPERTEGAIN", "IDPREVISION") AS
SELECT ff."ID",ff."IDFACTUREFOURNISSEUR",ff."IDPRODUIT",ff."PU",ff."REMISES",ff."IDBCDETAIL",ff."TVA",ff."DEVISE",ff."TAUXDECHANGE",ff."IDDEVISE",ff."DESIGNATION",ff."COMPTE",ff."MOIS",ff."ANNEE",ff."QTE",ff."MONTANTPERTEGAIN",ff."IDPREVISION" FROM FACTUREFOURNISSEURFILLE ff JOIN facturefournisseur f ON f.id=ff.idfacturefournisseur WHERE f.etat>=11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."FACTUREFOURNISSEURFILLE_PAYE" ("ID", "IDFACTUREFOURNISSEUR", "IDPRODUIT", "QTE", "PU", "REMISES", "IDBCDETAIL", "TVA", "PRODUITLIB", "COMPTE", "COMPTEREGR", "ETAT", "IDDEVISE", "TAUXDECHANGE", "MONTANTTTC", "MOIS", "ANNEE", "DATY", "POURCENTAGEPAYE", "MONTANTFILLEPAYE", "RESTEAPAYERFILLE", "MONTANTFILLEPAYEAR", "MONTANTFILLE", "SERVICE") AS
SELECT FFF.ID,
	       FFF.IDFACTUREFOURNISSEUR,
	       FFF.IDPRODUIT,
	       FFF.QTE,
	       FFF.PU,
	       FFF.REMISES,
	       FFF.IDBCDETAIL,
	       FFF.TVA,
	       FFF.PRODUITLIB,
	       FFF.COMPTE,
	       FFF.COMPTE                                                               AS compteregr,
	       FFF.ETAT,
	       FFF.IDDEVISE,
	       FFF.TAUXDECHANGE,
	       FF.MONTANTTTC,
	       FFF.MOIS,
	       FFF.ANNEE,
	       FF.DATY,
	       FF.MONTANTPAYE * 100 / NULLIF(FF.MONTANTTTC, 0)                                                     AS pourcentagepaye,
	       (FF.MONTANTPAYE / NULLIF(FF.MONTANTTTC, 0)) * (FFF.QTE * FFF.PU)                                    AS MontantFillePaye,
	       (FFF.QTE * FFF.PU) - ((FF.MONTANTPAYE / NULLIF(FF.MONTANTTTC, 0)) * (FFF.QTE * FFF.PU))             AS resteapayerfille,
	       ((FF.MONTANTPAYE / NULLIF(FF.MONTANTTTC, 0)) * (FFF.QTE * FFF.PU)) * FFF.TAUXDECHANGE               AS MontantFillePayeAr,
	       (FFF.QTE * FFF.PU)                                                                                   AS montantfille,
	       FF.SERVICE
	FROM FACTUREFOURNISSEUR_FILLECPL FFF
	         LEFT JOIN FACTUREFOURNISSEURCPL FF ON FF.ID = FFF.IDFACTUREFOURNISSEUR;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."FACTUREFOURNISSEURFILLE_U" ("ID", "IDFACTUREFOURNISSEUR", "IDPRODUIT", "PU", "REMISES", "IDBCDETAIL", "TVA", "DEVISE", "TAUXDECHANGE", "IDDEVISE", "DESIGNATION", "COMPTE", "MOIS", "ANNEE", "QTE", "MONTANTPERTEGAIN", "IDPREVISION", "REMISE", "RISTOURNE", "COMPTEANALYTIQUE", "UNITE", "IDUNITE") AS
(
select f."ID",f."IDFACTUREFOURNISSEUR",f."IDPRODUIT",f."PU",f."REMISES",f."IDBCDETAIL",f."TVA",f."DEVISE",f."TAUXDECHANGE",f."IDDEVISE",f."DESIGNATION",f."COMPTE",f."MOIS",f."ANNEE",f."QTE",f."MONTANTPERTEGAIN",f."IDPREVISION",f."REMISE",f."RISTOURNE",f."COMPTEANALYTIQUE", au.id as UNITE, au.val as IDUNITE
from FACTUREFOURNISSEURFILLE f
         left join AS_ingredients ai on ai.ID = f.IDPRODUIT
         left join as_unite au on au.ID = ai.UNITE
    );

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."FACTUREFOURNISSEURMONTANT" ("ID", "MONTANTTOTAL", "MONTANTTVA", "MONTANTTTC", "IDDEVISE", "TAUXDECHANGE") AS
SELECT v.ID,
            cast(SUM ((1-nvl(vd.remises/100,0))* (NVL (vd.QTE, 0) * NVL (vd.PU, 0))) as number(30,2)) AS montanttotal, 
            cast(SUM ((1-nvl(vd.REMISES /100,0))* (NVL (vd.QTE, 0) * NVL (vd.PU, 0))* (NVL (VD.TVA , 0))/100) as number(30,2)) AS montantTva,
            cast(SUM ((1-nvl(vd.remises/100,0))* (NVL (vd.QTE, 0) * NVL (vd.PU, 0))* (NVL (VD.TVA , 0))/100)+SUM ((1-nvl(vd.remises/100,0))* (NVL (vd.QTE, 0) * NVL (vd.PU, 0)))as number(30,2))  as montantTTC,
            NVL (vd.IDDEVISE,'AR') AS IDDEVISE,
            nvl (vd.tauxdechange,1) AS tauxdechange
            FROM FactureFournisseurFille vd LEFT JOIN facturefournisseur v ON v.ID = vd.idfacturefournisseur
   GROUP BY v.ID, vd.IDDEVISE,vd.tauxdechange;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."FACTUREFOURNISSEUR_COMPTEREGR" ("COMPTEREGR", "MOIS", "ANNEE", "MONTANT", "MONTANTPAYE", "RESTEAPAYER") AS
select compteregr,
	       mois,
	       annee,
	       sum(montantfille * TAUXDECHANGE)     as montant,
	       sum(MontantFillePaye * TAUXDECHANGE) as montantpaye,
	       sum(resteapayerfille * TAUXDECHANGE) as resteapayer
	from facturefournisseurfille_paye
	group by compteregr, mois, annee;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."FACTUREFOURNISSEUR_CPL" ("ID", "IDFOURNISSEUR", "IDMODEPAIEMENT", "DATY", "DESIGNATION", "DATEECHEANCEPAIEMENT", "ETAT", "REFERENCE", "IDBC", "DEVISE", "TAUX", "IDMAGASIN", "FOURNISSEURLIB", "MODEDEPAIMENTLIB", "COMPTE", "COMPTEAUXILIAIRE") AS
select ff."ID",ff."IDFOURNISSEUR",ff."IDMODEPAIEMENT",ff."DATY",ff."DESIGNATION",ff."DATEECHEANCEPAIEMENT",ff."ETAT",ff."REFERENCE",ff."IDBC",ff."DEVISE",ff."TAUX",ff."IDMAGASIN",
       f.NOM as fournisseurlib,
       mp.VAL as modedepaimentlib,
       f.COMPTE,
       f.compteauxiliaire
from FACTUREFOURNISSEUR ff
         left join FOURNISSEUR f on ff.IDFOURNISSEUR = f.ID
         left join MODEPAIEMENT mp on ff.IDMODEPAIEMENT = mp.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."FACTUREFOURNISSEUR_FILLECOMPTE" ("COMPTE", "IDFACTUREFOURNISSEUR", "ETAT", "MONTANTHT", "MONTANTTVA", "MONTANTTTC", "MONTANTTTCAR", "IDDEVISE", "TAUXDECHANGE") AS
select ff.COMPTE,
       ff.IDFACTUREFOURNISSEUR,
       f.etat,
       cast(sum(MONTANTHT) as number(30, 2))                            as montantht,
       cast(sum(MONTANTTVA) as number(30, 2))              as montanttva,
       cast(sum(MONTANTTTC) as number(30, 2)) as montantttc,
       cast(sum(MONTANTTTCAr) as number(30, 2)) as montantttcAr,
       ff.iddevise,
       ff.tauxdechange
from FFFILLECALC ff join FACTUREFOURNISSEUR f on f.id=ff.IDFACTUREFOURNISSEUR
group by COMPTE, IDFACTUREFOURNISSEUR, f.etat,ff.iddevise,ff.tauxdechange;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."FACTUREFOURNISSEUR_FILLECPL" ("ID", "IDFACTUREFOURNISSEUR", "IDPRODUIT", "QTE", "PU", "REMISES", "IDBCDETAIL", "TVA", "PRODUITLIB", "COMPTE", "ETAT", "IDDEVISE", "TAUXDECHANGE", "MOIS", "ANNEE") AS
select ff.ID,
	       ff.IDFACTUREFOURNISSEUR,
	       ff.IDPRODUIT,
	       ff.QTE,
	       ff.PU,
	       ff.REMISES,
	       ff.IDBCDETAIL,
	       ff.TVA,
	       p.LIBELLE as produitlib,
	       ff.compte,
	       f.ETAT,
	       ff.iddevise,
	       ff.tauxdechange,
	       ff.MOIS,
	       ff.ANNEE
	from FACTUREFOURNISSEURFILLE ff
	    left join PRODUIT_LIBCPL p on p.id = ff.idproduit
	    left join FACTUREFOURNISSEUR F on F.ID = ff.IDFACTUREFOURNISSEUR;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."FACTUREFOURNISSEUR_FILLE_CREE" ("COMPTE", "IDFACTUREFOURNISSEUR", "ETAT", "MONTANTHT", "MONTANTTVA", "MONTANTTTC") AS
select "COMPTE","IDFACTUREFOURNISSEUR","ETAT","MONTANTHT","MONTANTTVA","MONTANTTTC"
from FACTUREFOURNISSEUR_FILLECOMPTE
where etat = 1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."FACTUREFOURNISSEUR_FILLE_ECR" ("COMPTE", "IDFACTUREFOURNISSEUR", "ETAT", "MONTANTHT", "MONTANTTVA", "MONTANTTTC", "IDDEVISE", "TAUXDECHANGE", "IDPRODUIT") AS
select ff.COMPTE,
       ff.IDFACTUREFOURNISSEUR,
       ff.etat,
       cast(sum(ff.pu * ff.QTE) as number(30, 2))                            as montantht,
       cast(sum(ff.pu * ff.QTE * (ff.tva / 100)) as number(30, 2))              as montanttva,
       cast(sum((ff.pu * ff.QTE) + ff.pu * ff.QTE * (ff.tva / 100)) as number(30, 2)) as montantttc,
       ff.iddevise,
       ff.tauxdechange,
       ing.ID as IDPRODUIT
from FACTUREFOURNISSEUR_FILLECPL ff left join AS_INGREDIENTS ing on ing.id=ff.IDPRODUIT
group by COMPTE, IDFACTUREFOURNISSEUR, ff.etat,ff.iddevise,ff.tauxdechange, ing.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."FACTUREFOURNISSEUR_FILLE_MERE" ("IDFACTUREFOURNISSEUR", "MONTANT") AS
select IDFACTUREFOURNISSEUR,
       cast(sum(PU * QTE) as number(30, 2)) as montant
from FACTUREFOURNISSEUR_FILLECPL
group by IDFACTUREFOURNISSEUR;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."FACTUREFOURNISSEUR_FILLE_VISE" ("COMPTE", "IDFACTUREFOURNISSEUR", "ETAT", "MONTANTHT", "MONTANTTVA", "MONTANTTTC", "IDDEVISE", "TAUXDECHANGE") AS
select COMPTE,IDFACTUREFOURNISSEUR,ETAT,MONTANTHT,MONTANTTVA,MONTANTTTC,iddevise,tauxdechange
from FACTUREFOURNISSEUR_FILLECOMPTE
where etat = 11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."FACTUREFOURNISSEUR_FL_COMPTE" ("COMPTE", "IDFACTUREFOURNISSEUR", "MONTANTHT", "IDDEVISE", "TAUXDECHANGE") AS
SELECT 
ff.compte,
ff.idfacturefournisseur,
cast(sum(ff.pu * ff.QTE) as number(30, 2))                            as montantht,
ff.iddevise,
ff.tauxdechange
FROM FACTUREFOURNISSEUR_FILLECPL ff
GROUP BY compte, IDFACTUREFOURNISSEUR, iddevise, tauxdechange;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."FACTUREFOURNISSEUR_FL_ERITURE" ("COMPTE", "IDFACTUREFOURNISSEUR", "MONTANTHT", "IDDEVISE", "TAUXDECHANGE") AS
select "COMPTE","IDFACTUREFOURNISSEUR",cast (MONTANTHT as NUMBER(32,2)) as montantHT,"IDDEVISE","TAUXDECHANGE" from (
SELECT "COMPTE","IDFACTUREFOURNISSEUR",cast (MONTANTHT as NUMBER(32,2)) as montantHT,"IDDEVISE","TAUXDECHANGE" FROM FACTUREFOURNISSEUR_FL_COMPTE UNION ALL
SELECT "COMPTE","IDFACTUREFOURNISSEUR",cast ("MONTANTHT"as NUMBER(32,2)) as montantHT,"IDDEVISE","TAUXDECHANGE" FROM FACTUREFOURNISSEUR_FL_TVA);

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."FACTUREFOURNISSEUR_FL_TVA" ("COMPTE", "IDFACTUREFOURNISSEUR", "MONTANTHT", "IDDEVISE", "TAUXDECHANGE") AS
SELECT
    nvl(ai.compte_tva, '445600') AS compte,
    ff.idfacturefournisseur,
    cast(sum(ff.pu * ff.QTE * (ff.tva / 100)) as number(30, 2))              as montanttva,
    ff.iddevise,
    ff.tauxdechange
FROM FACTUREFOURNISSEUR_FILLECPL ff
         LEFT JOIN AS_INGREDIENTS ai ON ai.id = ff.idproduit
GROUP BY ai.compte_tva, IDFACTUREFOURNISSEUR, iddevise, tauxdechange;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."FACTUREFOURNISSEUR_LIVRENONPAY" ("ID", "IDFOURNISSEUR", "IDFOURNISSEURLIB", "IDMODEPAIEMENT", "IDMODEPAIEMENTLIB", "DATY", "DESIGNATION", "DATEECHEANCEPAIEMENT", "ETAT", "ETATLIB", "REFERENCE", "IDBC", "IDMAGASIN", "DEVISE", "TAUX", "IDMAGASINLIB", "MONTANT", "MONTANTPAYER", "MONTANTRESTE") AS
SELECT "ID","IDFOURNISSEUR","IDFOURNISSEURLIB","IDMODEPAIEMENT","IDMODEPAIEMENTLIB","DATY","DESIGNATION","DATEECHEANCEPAIEMENT","ETAT","ETATLIB","REFERENCE","IDBC","IDMAGASIN","DEVISE","TAUX","IDMAGASINLIB","MONTANT","MONTANTPAYER","MONTANTRESTE"
FROM FACTUREFOURNISSEURCPL_montant
WHERE ETAT = 13;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."FACTUREFOURNISSEUR_MERECMPT" ("ID", "IDFOURNISSEUR", "IDMODEPAIEMENT", "DATY", "DESIGNATION", "DATEECHEANCEPAIEMENT", "ETAT", "REFERENCE", "IDBC", "DEVISE", "TAUX", "IDMAGASIN", "FOURNISSEURLIB", "MODEDEPAIMENTLIB", "COMPTE", "COMPTEAUXILIAIRE", "MONTANTHT", "MONTANTTVA", "MONTANTTTC", "MONTANTTTCAR") AS
select ff."ID",
       ff."IDFOURNISSEUR",
       ff."IDMODEPAIEMENT",
       ff."DATY",
       ff."DESIGNATION",
       ff."DATEECHEANCEPAIEMENT",
       ff."ETAT",
       ff."REFERENCE",
       ff."IDBC",
       ff."DEVISE",
       ff."TAUX",
       ff."IDMAGASIN",
       ff."FOURNISSEURLIB",
       ff."MODEDEPAIMENTLIB",
       ff."COMPTE",
       ff.compteauxiliaire,
       fm.MONTANTHT,
       fm.MONTANTTVA,
       fm.MONTANTTTC,fm.montantttcAr
from FACTUREFOURNISSEUR_CPL ff
         left join FACTUREFOURNISSEUR_FILLECOMPTE fm on fm.IDFACTUREFOURNISSEUR = ff.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."FACTUREFOURNISSEUR_MF" ("ID", "IDFACTUREFOURNISSEUR", "IDPRODUIT", "QTE", "PU", "REMISES", "IDBCDETAIL", "TVA", "DEVISE", "TAUXDECHANGE", "IDDEVISE", "DESIGNATION", "COMPTE", "MONTANTPERTEGAIN", "IDFOURNISSEUR", "ETAT", "DATY", "PUREMISE") AS
SELECT ff.ID,
       ff.IDFACTUREFOURNISSEUR,
       ff.IDPRODUIT,
       ff.QTE,
       ff.PU,
       ff.REMISES,
       ff.IDBCDETAIL,
       ff.TVA,
       ff.DEVISE,
       ff.TAUXDECHANGE,
       ff.IDDEVISE,
       ff.DESIGNATION,
       ff.COMPTE,
       ff.MONTANTPERTEGAIN,
       f.IDFOURNISSEUR,
       f.ETAT,
       f.DATY,
       ff.PUREMISE
FROM FFFilleCalc ff
         JOIN FACTUREFOURNISSEUR f ON ff.IDFACTUREFOURNISSEUR = f.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."FACTUREFOURNISSEUR_MONTANT" ("IDFACTUREFOURNISSEUR", "MONTANT") AS
select iDFACTUREFOURNISSEUR,
       cast(sum(pu * QTE) as number(30, 2)) as montant

from FACTUREFOURNISSEURFILLE
group by IDFACTUREFOURNISSEUR;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."FACTUREFOURNISSEUR_PAYELIVRE" ("ID", "IDFOURNISSEUR", "IDFOURNISSEURLIB", "IDMODEPAIEMENT", "IDMODEPAIEMENTLIB", "DATY", "DESIGNATION", "DATEECHEANCEPAIEMENT", "ETAT", "ETATLIB", "REFERENCE", "IDBC", "IDMAGASIN", "DEVISE", "TAUX", "IDMAGASINLIB", "MONTANT", "MONTANTPAYER", "MONTANTRESTE") AS
SELECT "ID","IDFOURNISSEUR","IDFOURNISSEURLIB","IDMODEPAIEMENT","IDMODEPAIEMENTLIB","DATY","DESIGNATION","DATEECHEANCEPAIEMENT","ETAT","ETATLIB","REFERENCE","IDBC","IDMAGASIN","DEVISE","TAUX","IDMAGASINLIB","MONTANT","MONTANTPAYER","MONTANTRESTE"FROM FACTUREFOURNISSEURCPL_montant
WHERE ETAT = 14;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."FACTUREFOURNISSEUR_PAYENOLIVRE" ("ID", "IDFOURNISSEUR", "IDFOURNISSEURLIB", "IDMODEPAIEMENT", "IDMODEPAIEMENTLIB", "DATY", "DESIGNATION", "DATEECHEANCEPAIEMENT", "ETAT", "ETATLIB", "REFERENCE", "IDBC", "IDMAGASIN", "DEVISE", "TAUX", "IDMAGASINLIB", "MONTANT", "MONTANTPAYER", "MONTANTRESTE") AS
SELECT "ID","IDFOURNISSEUR","IDFOURNISSEURLIB","IDMODEPAIEMENT","IDMODEPAIEMENTLIB","DATY","DESIGNATION","DATEECHEANCEPAIEMENT","ETAT","ETATLIB","REFERENCE","IDBC","IDMAGASIN","DEVISE","TAUX","IDMAGASINLIB","MONTANT","MONTANTPAYER","MONTANTRESTE"
FROM FACTUREFOURNISSEURCPL_montant
WHERE ETAT = 12;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."FACTUREFOURNISSEUR_PERTE" ("ID", "IDFOURNISSEUR", "IDMODEPAIEMENT", "DATY", "DESIGNATION", "DATEECHEANCEPAIEMENT", "ETAT", "REFERENCE", "IDBC", "DEVISE", "TAUX", "IDMAGASIN", "IDDEVISE", "ESTPREVU", "DATYPREVU", "MONTANTPERTEGAIN", "NUMERO", "TYPEACHAT", "IDTYPEFACTURE", "IDOBJET", "IDREF", "IDDMDACHAT", "IDFACTUREPRINCIPALE", "SERVICE", "TYPEFACTUREFOURNISSEUR") AS
SELECT f.ID,
       f.IDFOURNISSEUR,
       f.IDMODEPAIEMENT,
       f.DATY,
       f.DESIGNATION,
       f.DATEECHEANCEPAIEMENT,
       f.ETAT,
       f.REFERENCE,
       f.IDBC,
       f.DEVISE,
       f.TAUX,
       f.IDMAGASIN,
       f.IDDEVISE,
       f.ESTPREVU,
       f.DATYPREVU,
       cast (nvl(p.MONTANTAR, 0) as number(30,2)) AS MONTANTPERTEGAIN,
       f.numero ,
       f.TYPEACHAT ,
       f.IDTYPEFACTURE ,
       f.IDOBJET ,
       f.IDREF ,
       f.IDDMDACHAT ,
       f.IDFACTUREPRINCIPALE ,
       f.SERVICE ,
       f.TYPEFACTUREFOURNISSEUR
FROM FACTUREFOURNISSEUR f
         left JOIN perte_grporigine_fact p ON p.idorigine = f.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."FACTUREFOURNISSEUR_RECAP_JOUR" ("DATY", "MONTANTTTC", "MONTANTPAYE", "MONTANTRESTE", "NOMBRE", "MONTANTRESTEACEJOUR") AS
WITH BORNES AS (
    SELECT
        DATE '2026-06-01' AS DATE_MIN,
        TRUNC(SYSDATE) AS DATE_MAX
    FROM DUAL
),
CALENDRIER AS (
    SELECT
        DATE_MIN + LEVEL - 1 AS DATY
    FROM BORNES
    CONNECT BY LEVEL <= DATE_MAX - DATE_MIN + 1
),
FACTURE_JOUR AS (
    SELECT
        TRUNC(DATY) AS DATY,
        SUM(NVL(MONTANTTTC, 0)) AS MONTANTTTC,
        SUM(NVL(MONTANTPAYE, 0)) AS MONTANTPAYE,
        SUM(NVL(MONTANTRESTE, 0)) AS MONTANTRESTE,
        COUNT(*) AS NOMBRE
    FROM FACTUREFOURNISSEURCPL_TOUS_FAE
    WHERE IDTYPEFACTURE = 'TPF0002'
      AND ETAT = 11
      AND DATY >= DATE '2026-06-01'
    GROUP BY TRUNC(DATY)
)
SELECT
    c.DATY,

    CAST(NVL(f.MONTANTTTC, 0) AS NUMBER(30,5)) AS MONTANTTTC,
    CAST(NVL(f.MONTANTPAYE, 0) AS NUMBER(30,5)) AS MONTANTPAYE,
    CAST(NVL(f.MONTANTRESTE, 0) AS NUMBER(30,5)) AS MONTANTRESTE,
    CAST(NVL(f.NOMBRE, 0) AS NUMBER(10,0)) AS NOMBRE,

    CAST(
        SUM(NVL(f.MONTANTRESTE, 0))
        OVER (
            ORDER BY c.DATY
            ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
        )
        AS NUMBER(30,5)
    ) AS MONTANTRESTEACEJOUR

FROM CALENDRIER c
LEFT JOIN FACTURE_JOUR f
    ON c.DATY = f.DATY;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."FACTURESTANDARD" ("ID", "IDFOURNISSEUR", "IDFOURNISSEURLIB", "IDMODEPAIEMENT", "IDMODEPAIEMENTLIB", "DATY", "DESIGNATION", "DATEECHEANCEPAIEMENT", "ETATLIB", "REFERENCE", "IDBC", "IDMAGASIN", "IDMAGASINLIB", "DEVISE", "IDDEVISE", "ETAT", "TAUX", "MONTANTTVA", "MONTANTHT", "TAUXDECHANGE", "MONTANTTTC", "MONTANTPAYE", "MONTANTRESTE", "IDOBJET", "IDREF", "TYPEACHAT", "IDECRITURE", "COMPTE", "NUMERO") AS
SELECT
    fcpl.id,
    fcpl.idfournisseur,
    fcpl.idfournisseurlib,
    fcpl.idmodepaiement,
    fcpl.idmodepaiementlib,
    fcpl.daty,
    fcpl.designation,
    fcpl.dateecheancepaiement,
    fcpl.etatlib,
    fcpl.reference,
    fcpl.idbc,
    fcpl.idmagasin,
    fcpl.idmagasinlib,
    fcpl.devise,
    fcpl.iddevise,
    fcpl.etat,
    fcpl.taux,
    fcpl.montanttva,
    fcpl.montantht,
    fcpl.tauxdechange,
    fcpl.montantttc AS MONTANTTTC,
    nvl((fcpl.montantpaye * fcpl.TAUXDECHANGE), 0) AS MONTANTPAYE,
    nvl((fcpl.montantreste * fcpl.TAUXDECHANGE), 0) AS MONTANTRESTE,
    fcpl.IDOBJET,
    fcpl.IDREF,
    fcpl.typeachat,
    ce.id AS idecriture,
    '-' AS compte,
    fcpl.numero AS numero
FROM
    FACTUREFOURNISSEURCPL fcpl
        LEFT JOIN compta_ecriture ce ON
        ce.idobjet = fcpl.id
/*  LEFT JOIN compta_compte cc ON cc.idjournal=ce.journal */
WHERE
    fcpl.typeachat = 'PS';

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."FFAVECPERTE_FF" ("ID", "IDFACTUREFOURNISSEUR", "IDPRODUIT", "QTE", "PU", "REMISES", "IDBCDETAIL", "TVA", "DEVISE", "TAUXDECHANGE", "IDDEVISE", "DESIGNATION", "COMPTE", "MONTANTPERTEGAIN", "IDFOURNISSEUR", "ETAT", "DATY", "PUPERTEGAIN", "MONTANTAVECPERTEGAIN", "LIBELLEPRODUIT") AS
SELECT
    ff.ID,
    ff.IDFACTUREFOURNISSEUR,
    ff.IDPRODUIT,
    ff.QTE,
    ff.PU,
    ff.REMISES,
    ff.IDBCDETAIL,
    ff.TVA,
    ff.DEVISE,
    ff.TAUXDECHANGE,
    ff.IDDEVISE,
    ff.DESIGNATION,
    ff.COMPTE,
    CAST(nvl(rep.montant,0) AS NUMBER(30,2) ) AS MONTANTPERTEGAIN ,
    ff.IDFOURNISSEUR,
    ff.ETAT,ff.DATY,
    CAST(((ff.PUREMISE*TAUXDECHANGE)+(nvl(rep.MONTANT,0)/qte)) AS NUMBER(30,2) ) AS pupertegain ,
    CAST(((qte*ff.PUREMISE*TAUXDECHANGE)+nvl(rep.montant,0)) AS NUMBER(30,2) ) AS montantavecpertegain,
    asi.LIBELLE AS LIBELLEPRODUIT
FROM
    FACTUREFOURNISSEUR_mf ff
        LEFT JOIN AS_INGREDIENTS asi ON ASI.ID = ff.IDPRODUIT
        left join RepartirionPG rep on rep.IDFACTUREFILLE=ff.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."FFAVECPERTE_FF_IDPG" ("ID", "IDFACTUREFOURNISSEUR", "IDPRODUIT", "QTE", "PU", "REMISES", "IDBCDETAIL", "TVA", "DEVISE", "TAUXDECHANGE", "IDDEVISE", "DESIGNATION", "COMPTE", "MONTANTPERTEGAIN", "IDFOURNISSEUR", "ETAT", "DATY", "PUPERTEGAIN", "MONTANTAVECPERTEGAIN", "LIBELLEPRODUIT") AS
SELECT
    ff.ID,
    ff.IDFACTUREFOURNISSEUR,
    ff.IDPRODUIT,
    ff.QTE,
    ff.PU,
    ff.REMISES,
    p.IDBCDETAIL as IDBCDETAIL,
    ff.TVA,
    ff.DEVISE,
    ff.TAUXDECHANGE,
    ff.IDDEVISE,
    ff.DESIGNATION,
    ff.COMPTE,
    CAST( nvl((CASE WHEN fg.MONTANTPERTEGAIN =0 THEN NULL ELSE  ff.MONTANTPERTEGAIN end),(p.montantAr*qte*p.TAUX*ff.pu/fg.montanttotal)) AS NUMBER(30,2) ) AS MONTANTPERTEGAIN ,
    ff.IDFOURNISSEUR,
    ff.ETAT,ff.DATY,
    CAST( (qte*ff.pu*TAUXDECHANGE+nvl((CASE WHEN fg.MONTANTPERTEGAIN =0 THEN NULL ELSE  ff.MONTANTPERTEGAIN end),0))/qte AS NUMBER(30,2) ) AS pupertegain ,
    CAST( (qte*ff.pu*TAUXDECHANGE+nvl((CASE WHEN fg.MONTANTPERTEGAIN =0 THEN NULL ELSE  ff.MONTANTPERTEGAIN end),0)) AS NUMBER(30,2) ) AS montantavecpertegain,
    asi.LIBELLE AS LIBELLEPRODUIT
FROM
    FACTUREFOURNISSEUR_mf ff
        left JOIN perte_grporigine_fact p ON p.idorigine=ff.idfacturefournisseur
        LEFT JOIN ff_grpmere fg ON fg.idfacturefournisseur=ff.idfacturefournisseur
        LEFT JOIN AS_INGREDIENTS asi ON ASI.ID = ff.IDPRODUIT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."FFFILLECALC" ("ID", "IDFACTUREFOURNISSEUR", "IDPRODUIT", "PU", "REMISES", "IDBCDETAIL", "TVA", "DEVISE", "TAUXDECHANGE", "IDDEVISE", "DESIGNATION", "COMPTE", "MOIS", "ANNEE", "QTE", "MONTANTPERTEGAIN", "IDPREVISION", "REMISE", "RISTOURNE", "MONTANTNONREMISE", "MONTANTREMISESANSTVA", "MONTANTHT", "PUREMISE", "MONTANTHTAR", "MONTANTTVA", "MONTANTTVAAR", "MONTANTTTC", "MONTANTTTCAR") AS
select vd."ID",vd."IDFACTUREFOURNISSEUR",vd."IDPRODUIT",vd."PU",vd."REMISES",vd."IDBCDETAIL",vd."TVA",vd."DEVISE",vd."TAUXDECHANGE",vd."IDDEVISE",vd."DESIGNATION",vd."COMPTE",vd."MOIS",vd."ANNEE",vd."QTE",vd."MONTANTPERTEGAIN",vd."IDPREVISION",vd."REMISE",vd."RISTOURNE",cast(vd.QTE*vd.pu as number(30,2)) as montantNonRemise,
cast(vd.QTE*vd.pu*((nvl(vd.REMISE,0)+nvl(vd.RISTOURNE,0))/100) as number(30,2)) as montantRemiseSansTva,
cast(vd.QTE*vd.pu*(1-(nvl(vd.REMISE,0)/100))*(1-(nvl(vd.RISTOURNE,0)/100)) as number(30,2)) as montantHT,
cast(vd.pu*(1-(nvl(vd.REMISE,0)/100))*(1-(nvl(vd.RISTOURNE,0)/100)) as number(30,2)) as puRemise,
cast(vd.QTE*vd.pu*(1-(nvl(vd.REMISE,0)/100))*(1-(nvl(vd.RISTOURNE,0)/100))*nvl(vd.TAUXDECHANGE,1) as number(30,2)) as montantHTAr,
cast(vd.QTE*vd.pu*(1-(nvl(vd.REMISE,0)/100))*(1-(nvl(vd.RISTOURNE,0)/100))*nvl(vd.tva,0)/100 as number(30,2)) as montantTva,
cast(vd.QTE*vd.pu*(1-(nvl(vd.REMISE,0)/100))*(1-(nvl(vd.RISTOURNE,0)/100))*nvl(vd.TAUXDECHANGE,1)*nvl(vd.tva,0)/100 as number(30,2)) as montantTvaAr,
cast(vd.QTE*vd.pu*(1-(nvl(vd.REMISE,0)/100))*(1-(nvl(vd.RISTOURNE,0)/100))*(1+(nvl(vd.tva,0)/100)) as number(30,2)) as montantTTC,
cast(vd.QTE*vd.pu*(1-(nvl(vd.REMISE,0)/100))*(1-(nvl(vd.RISTOURNE,0)/100))*(1+(nvl(vd.tva,0)/100))*nvl(vd.TAUXDECHANGE,1) as number(30,2)) as montantTTCAr from FACTUREFOURNISSEURFILLE vd;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."FFFILLECALCGROUPEFF" ("IDFACTUREFOURNISSEUR", "MONTANTNONREMISE", "MONTANTREMISESANSTVA", "MONTANTHT", "MONTANTTTC", "MONTANTTVA", "MONTANTHTAR", "MONTANTTVAAR", "MONTANTTTCAR") AS
select vdc.IDFACTUREFOURNISSEUR ,cast(sum(montantNonRemise) as number(30,2)) as montantNonRemise,cast(sum(montantRemiseSansTva) as number(30,2)) as montantRemiseSansTva,
       cast(sum(montantHT) as number(30,2)) as montantHT,cast(sum(montantTTC) as number(30,2)) as montantTTC,cast(sum(montantTva) as number(30,2)) as montantTva,
       cast(sum(montantHTAr) as number(30,2)) as montantHTAr,cast(sum(montantTvaAr) as number(30,2)) as montantTvaAr,cast(sum(montantTTCAr) as number(30,2)) as montantTTCAr
from FFFilleCalc vdc group by vdc.IDFACTUREFOURNISSEUR;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."FFFILLECPL_MONTANT" ("ID", "IDFACTUREFOURNISSEUR", "IDPRODUIT", "IDPRODUITLIB", "QTE", "PU", "REMISES", "IDBCDETAIL", "TVA", "MONTANTTOTAL", "MONTANTTTC", "IDPOINT", "IDPOINTLIB", "IDMAGASIN", "IDMAGASINLIB", "IDCATEGORIE", "IDCATEGORIELIB", "DATY", "IDDEVISE") AS
SELECT 
f.ID ,
f.IDFACTUREFOURNISSEUR ,
f.IDPRODUIT ,
nvl(i.LIBELLE,p.VAL) AS IDPRODUITLIB,
f.QTE ,
CAST(f.PU AS NUMBER(30,5)) AS PU ,
CAST(f.REMISES AS NUMBER(30,5)) AS REMISES ,
f.IDBCDETAIL,
CAST(f.TVA AS NUMBER(10,5)) AS TVA,
CAST(nvl(f.QTE*f.PU,0)  AS NUMBER(30,5))  AS MONTANTTOTAL,
CAST(
    nvl(
        ((f.QTE * f.PU) - ((NVL(f.remises, 0) / 100) * (f.QTE * f.PU)))
        + (((f.QTE * f.PU) - ((NVL(f.remises, 0) / 100) * (f.QTE * f.PU))) * NVL(f.TVA, 0) / 100)
    , 0) 
AS NUMBER(30,5)) AS MONTANTTTC,
p2.ID AS IDPOINT,
p2.VAL AS IDPOINTLIB,
m.ID AS IDMAGASIN,
m.VAL AS IDMAGASINLIB,
c.ID AS IDCATEGORIE,
c.VAL AS IDCATEGORIELIB,
f2.DATY AS daty,
f.IDDEVISE
FROM FACTUREFOURNISSEURFILLE f 
LEFT JOIN FACTUREFOURNISSEUR f2 ON f2.ID = f.IDFACTUREFOURNISSEUR 
LEFT JOIN MAGASIN m ON m.ID = f2.IDMAGASIN 
LEFT JOIN POINT p2 ON m.IDPOINT = p2.ID  
LEFT JOIN PRODUIT p ON p.ID = f.IDPRODUIT
LEFT JOIN CATEGORIE c ON p.IDCATEGORIE = c.ID
LEFT JOIN AS_INGREDIENTS i ON i.ID = f.IDPRODUIT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."FFFILLECPL_VISEE" ("ID", "IDFACTUREFOURNISSEUR", "IDPRODUIT", "IDPRODUITLIB", "QTE", "PU", "REMISES", "IDBCDETAIL", "TVA", "IDDEVISE", "DATY", "MONTANTHT", "MONTANTTTC", "MONTANTTVA", "MONTANTREMISE", "MONTANT", "IDPREVISION") AS
SELECT
    f.ID ,
    f.IDFACTUREFOURNISSEUR ,
    f.IDPRODUIT ,
    nvl(i.LIBELLE,p.LIBELLE) AS IDPRODUITLIB,
    f.QTE ,
    f.PU ,
    f.REMISES ,
    f.IDBCDETAIL ,
    f.TVA ,
    f.IDDEVISE,
    f2.DATY,
    CAST(f.QTE * f.PU AS NUMBER(30,2)) AS montantht,
    CAST(f.QTE * f.PU + (f.QTE * f.PU * f.TVA/100) AS NUMBER(30,2)) AS montantttc,
    CAST(f.QTE * f.PU * f.TVA/100 AS NUMBER(30,2)) AS montanttva,
    CAST((nvl(f.remises/100,0))*(f.QTE * f.PU) AS NUMBER(30,2)) AS montantRemise,
    CAST((1-nvl(f.remises/100,0))*(f.QTE * f.PU) AS NUMBER(30,2)) AS montant,
    f.idprevision
FROM FACTUREFOURNISSEURFILLE f
         LEFT JOIN FACTUREFOURNISSEUR f2 ON f2.ID = f.IDFACTUREFOURNISSEUR
         LEFT JOIN AS_INGREDIENTS p ON p.ID = f.IDPRODUIT
         LEFT JOIN AS_INGREDIENTS i ON i.ID = f.IDPRODUIT
where f2.ETAT >= 11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."FFFILLERESTEALIVRER" ("ID", "IDFACTUREFOURNISSEUR", "IDPRODUIT", "QTE", "PU", "REMISES", "IDBCDETAIL", "TVA", "IDUNITE", "IDPRODUITLIB", "UNITELIB", "PUPERTEGAIN") AS
SELECT f.id,
       f.IDFACTUREFOURNISSEUR,
       f.IDPRODUIT,
       cast(f.QTE - nvl(sum(abf.QUANTITE), 0) as number(38, 2)) AS qte,
       f.PU,
       f.REMISES,
       f.IDBCDETAIL,
       f.TVA,
       au.id as idunite,
       ai.LIBELLE as idproduitlib,
       au.val as unitelib,
       cast(fac.PUPERTEGAIN as number(38, 2)) as PUPERTEGAIN
FROM FACTUREFOURNISSEURFILLE f
         LEFT JOIN AS_BONDELIVRAISON_FILLE abf ON f.ID = abf.IDBC_FILLE
    LEFT JOIN AS_INGREDIENTS ai on ai.id = f.idproduit
    LEFT JOIN AS_UNITE au on au.id = ai.UNITE
    LEFT JOIN FFAVECPERTE_ff fac on fac.id = f.id
GROUP BY f.id, f.IDFACTUREFOURNISSEUR, f.IDPRODUIT, f.QTE, f.PU, f.REMISES, f.IDBCDETAIL, f.TVA, ai.LIBELLE, au.val, au.id, ai.id, fac.PUPERTEGAIN;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."FFFILLERESTEALIVRERLIB" ("ID", "IDFACTUREFOURNISSEUR", "IDPRODUIT", "IDPRODUITLIB", "QTE", "PU", "REMISES", "IDBCDETAIL", "TVA", "IDUNITE") AS
SELECT 
f.ID ,
f.IDFACTUREFOURNISSEUR ,
f.IDPRODUIT ,
p.VAL AS IDPRODUITLIB,
f.QTE ,
f.PU ,
f.REMISES ,
f.IDBCDETAIL ,
f.TVA , 
p.idunite
FROM FFFILLERESTEALIVRER f 
LEFT JOIN FACTUREFOURNISSEUR f2 ON f2.ID = f.IDFACTUREFOURNISSEUR 
LEFT JOIN PRODUIT p ON p.ID = f.IDPRODUIT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."FF_FILLEBC_GRP" ("IDPRODUIT", "IDBCDETAIL", "QTE") AS
SELECT
	ff.idproduit,
	ff.IDBCDETAIL,
	sum(ff.qte) AS qte
	FROM (SELECT ff.* FROM FACTUREFOURNISSEURFILLE ff JOIN facturefournisseur f ON f.id=ff.idfacturefournisseur WHERE f.etat>=11  ) ff
GROUP BY idproduit,IDBCDETAIL;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."FF_FILLEBC_GRP_MERE" ("IDPRODUIT", "IDBC", "QTE") AS
SELECT
	ff.idproduit,
	ff.idbc,
	sum(ff.qte) AS qte
	FROM (SELECT ff.*, f.IDBC FROM FACTUREFOURNISSEURFILLE ff JOIN facturefournisseur f ON f.id=ff.idfacturefournisseur WHERE f.etat>=11) ff
GROUP BY idproduit, ff.idbc;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."FF_FILLEBL_GRP" ("PRODUIT", "IDBC_FILLE", "QTE") AS
SELECT
	produit,
	IDBC_FILLE,
	sum(quantite) AS qte
	FROM (SELECT blf.* FROM AS_BONDELIVRAISON_FILLE blf JOIN AS_BONDELIVRAISON bl ON bl.id=blf.NUMBL WHERE bl.etat>=11  )
GROUP BY produit,IDBC_FILLE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."FF_GRPMERE" ("IDFACTUREFOURNISSEUR", "MONTANTTOTAL", "MONTANTPERTEGAIN") AS
SELECT
idfacturefournisseur,
sum(qte*pu) AS montanttotal,
sum(MONTANTPERTEGAIN) AS MONTANTPERTEGAIN
FROM facturefournisseurfille
GROUP BY idfacturefournisseur;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."FICHE_POSTE_COMPETENCES_LIB" ("ID", "IDFICHEPOSTE", "IDTYPECOMPETENCESFP", "IDTYPECOMPETENCESFPLIB", "DESCRIPTION", "NIVEAU", "NIVEAULIB") AS
SELECT
    fpc.ID,
    fpc.IDFICHEPOSTE,
    fpc.IDTYPECOMPETENCESFP,
    t.VAL AS IDTYPECOMPETENCESFPLIB,
    fpc.DESCRIPTION,
    fpc.NIVEAU,

    CASE
        WHEN fpc.NIVEAU = 0 THEN 'Non acquis'
        WHEN fpc.NIVEAU = 1 THEN 'En cours d''acquisition'
        WHEN fpc.NIVEAU = 2 THEN 'Acquis'
        WHEN fpc.NIVEAU = 3 THEN 'Maitrise'
        ELSE 'Inconnu'
        END AS NIVEAULIB

FROM FICHE_POSTE_COMPETENCES fpc
         LEFT JOIN TYPE_COMPETENCES_FP t
                   ON t.ID = fpc.IDTYPECOMPETENCESFP;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."FICHE_POSTE_COMPETENCES_VIDE" ("ID", "IDFICHEPOSTE", "IDTYPECOMPETENCESFP", "DESCRIPTION", "NIVEAU") AS
SELECT
    ID,
    IDFICHEPOSTE,
    IDTYPECOMPETENCESFP,
    DESCRIPTION,
    NIVEAU
FROM FICHE_POSTE_COMPETENCES;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."FICHE_POSTE_LIB" ("ID", "IDDEPARTEMENT", "IDTYPECONTRAT", "TITRE", "REFERENCE", "DESCRIPTION", "MISSIONS", "EXIGENCEPOSTE", "SALAIREMIN", "SALAIREMAX", "ETAT", "DATY", "LIEUTRAVAIL", "MATERIELDOCUMENT", "OUTILS", "CONDITIONTRAVAIL", "MODECONTROLE", "IDNIVEAUFORMATION", "IDPERMIS", "IDFONCTION", "IDBU", "AUTRE", "IDCATEGORIEPAIE", "IDQUALIFICATIONPAIE", "IDDEPARTEMENTLIB", "IDTYPECONTRATLIB", "IDFONCTIONLIB", "IDNIVEAUFORMATIONLIB", "IDPERMISLIB", "IDBULIB", "IDCATEGORIEPAIELIB", "IDQUALIFICATIONPAIELIB", "ETATLIB", "IDFAMILLEPROFESSIONELLIB", "IDMETIERLIB", "IDEMPLOILIB", "IDCODEROMELIB") AS
SELECT
    f.ID,f.IDDEPARTEMENT,f.IDTYPECONTRAT,f.TITRE,f.REFERENCE,f.DESCRIPTION,f.MISSIONS,f.EXIGENCEPOSTE,f.SALAIREMIN,f.SALAIREMAX,f.ETAT,f.DATY,f.LIEUTRAVAIL,f.MATERIELDOCUMENT,f.OUTILS,f.CONDITIONTRAVAIL,f.MODECONTROLE,f.IDNIVEAUFORMATION,f.IDPERMIS,f.IDFONCTION,f.IDBU,f.AUTRE,f.IDCATEGORIEPAIE,f.IDQUALIFICATIONPAIE,
    d.VAL AS IDDEPARTEMENTLIB,
    t.VAL AS IDTYPECONTRATLIB,
    pf.VAL AS IDFONCTIONLIB,
    nf.DESCE AS idNiveauFormationLib,
    p.DESCE AS idPermisLib,
    bu.VAL AS idBuLib,
    cp.VAL AS idCategoriePaieLib,
    qp.VAL AS idQualificationPaieLib,

    CASE
        WHEN f.ETAT = '1'  THEN 'Cree'
        WHEN f.ETAT = '11' THEN 'Valide'
        WHEN f.ETAT = '0'  THEN 'Annule'
        ELSE 'Inconnu'
        END AS ETATLIB,
    fp.val AS idFamilleProfessionelLib,
    m.val AS idMetierLib,
    em.val AS idEmploiLib,
    cr.code AS idCodeRomeLib
FROM FICHE_POSTE f
         LEFT JOIN DEPARTEMENT d ON d.ID = f.IDDEPARTEMENT
         LEFT JOIN TYPE_CONTRAT t ON t.ID = f.IDTYPECONTRAT
         LEFT JOIN PAIE_FONCTION pf ON pf.ID = f.IDFONCTION
         LEFT JOIN FORMATION_DIPLOME nf ON nf.ID = f.idNiveauFormation
         LEFT JOIN PERMIS p ON p.ID = f.idPermis
         LEFT JOIN BUSINESS_UNITE bu ON bu.ID = f.idBu
         LEFT JOIN CATEGORIE_PAIE cp ON cp.ID = f.idCategoriePaie
         LEFT JOIN QUALIFICATION_PAIE qp ON qp.ID = f.idQualificationPaie
         LEFT JOIN FAMILLE_PROFESSIONNELLE fp ON fp.id = f.idFamilleProfessionel
         LEFT JOIN METIER m ON m.id = f.idMetier
         LEFT JOIN emploi em ON em.id = f.idEmploi
         LEFT JOIN code_rome cr ON cr.id = f.idCodeRome;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."FOURNISSEURCPL" ("ID", "NOM", "NIF", "STAT", "ADRESSE", "CONTACT", "CODEPOSTAL", "COMPTE", "IDTYPEFOURNISSEUR", "COMPTEAUXILIAIRE", "ESTACTIF", "NB") AS
SELECT f."ID",f."NOM",f."NIF",f."STAT",f."ADRESSE",f."CONTACT",f."CODEPOSTAL",f."COMPTE",f."IDTYPEFOURNISSEUR",f."COMPTEAUXILIAIRE",f."ESTACTIF",
       1 as nb
FROM FOURNISSEUR f;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."FRAIS_MEDICAUXMOIS" ("IDPERSONNEL", "MOIS", "ANNEE", "TOTAL_BRUT", "FRAIS_MEDICAUX") AS
SELECT pe.idpersonnel,
       pe.mois,
       pe.annee,
       sum(pe.gain) AS total_brut,
       COALESCE(prfrm.gain, 0) AS frais_medicaux
FROM paie_edition pe
         LEFT JOIN paie_edition prfrm ON pe.idpersonnel = prfrm.idpersonnel AND pe.mois = prfrm.mois AND pe.annee = prfrm.annee AND prfrm.idelementpaie = 'PR000FRM'
WHERE (pe.idelementpaie IN ( SELECT pr.id
                             FROM paie_rubrique pr
                             WHERE pr.typerubrique = 'G' AND (pr.id NOT IN ('PR000210A', 'PR000FRM', 'PR000181'))))
GROUP BY pe.idpersonnel, pe.mois, pe.annee, prfrm.gain;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."FRAIS_MEDICAUX_ALL" ("ID", "MATRICULE", "NOM", "POSTE", "DATEEMBAUCHE", "NUMERO_CNAPS", "TOTAL_BRUT", "FRAIS_MEDICAUX", "MOIS", "ANNEE", "TEST", "MOISLIB") AS
SELECT pip.id,
       pip.matricule,
       lp.nom || lp.prenom AS nom,
       pf.desce AS poste,
       pip.dateembauche,
       pip.numero_cnaps,
       frm.total_brut,
       frm.frais_medicaux,
       frm.mois,
       frm.annee AS annee,
       (frm.total_brut * 0.06) AS test,
       mo.val AS moislib
FROM paie_info_personnel pip
         LEFT JOIN paie_fonction pf ON pip.idfonction = pf.id
         LEFT JOIN log_personnel lp ON lp.id = pip.id
         LEFT JOIN frais_medicauxmois frm ON frm.idpersonnel = pip.id
         LEFT JOIN moiscp mo ON mo.id = frm.mois;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."FREQUENCE_PANNE_MACHINE" ("ID", "IDENTITE", "IDSITUATION", "IDMACHINE", "DATY", "DATEBESOIN", "PRIORITE", "ESTEXISTANT", "DESCRIPTION", "ETAT", "IDDEPARTEMENT", "CAUSE", "DEMANDEUR", "IDDEPARTEMENTMAINTENANCE", "IDMACHINELIB", "QTE") AS
SELECT
    d."ID",d."IDENTITE",d."IDSITUATION",d."IDMACHINE",d."DATY",d."DATEBESOIN",d."PRIORITE",d."ESTEXISTANT",d."DESCRIPTION",d."ETAT",d."IDDEPARTEMENT",d."CAUSE",d."DEMANDEUR",d."IDDEPARTEMENTMAINTENANCE" ,
    ai.LIBELLE AS idMachineLib,
    1 AS qte
FROM DEMANDETRAVAUX d
         LEFT JOIN AS_INGREDIENT_MAINTENANCE m
                   ON d.IDMACHINE = m.ID
         LEFT JOIN AS_INGREDIENTS ai
                   ON m.IDINGREDIENT = ai.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."FRM_MOIS_ANNEE" ("MOIS", "ANNEE", "TOTAL_FRM") AS
SELECT fma.mois,
       fma.annee AS annee,
       CAST(sum(fma.frais_medicaux) AS NUMBER(15,2)) AS total_frm
FROM frais_medicaux_all fma
GROUP BY fma.mois, fma.annee;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."FUMIGATION_LIB" ("ID", "DATY", "IDNUMEROVAGUE", "IDOPERATEUR", "IDLOT", "IDBATIMENT", "IDPARQUET", "NOMBREOAC", "HEUREDEBUTFUMIGATION", "HEUREFINFUMIGATION", "HEUREDEBUTEXTRACTION", "HEUREFINEXTRACTION", "IDPRODUIT", "QTE", "TEMPERATUREMIN", "TEMPERATUREMAX", "ETAT", "IDNUMEROVAGUELIB", "IDOPERATEURLIB", "IDLOTLIB", "IDBATIMENTLIB", "IDPARQUETLIB", "IDPRODUITLIB", "ETATLIB") AS
SELECT f.ID,
       f.DATY,
       f.IDNUMEROVAGUE,
       f.IDOPERATEUR,
       f.IDLOT,
       f.IDBATIMENT,
       f.IDPARQUET,
       f.NOMBREOAC,
       f.HEUREDEBUTFUMIGATION,
       f.HEUREFINFUMIGATION,
       f.HEUREDEBUTEXTRACTION,
       f.HEUREFINEXTRACTION,
       f.IDPRODUIT,
       f.QTE,
       f.TEMPERATUREMIN,
       f.TEMPERATUREMAX,
       f.ETAT,
       nc.VAL                          AS IDNUMEROVAGUELIB,
       op.NOM || ' ' || op.PRENOM    AS IDOPERATEURLIB,
       l.NOMLOT                        AS IDLOTLIB,
       b.NOMBATIMENT                   AS IDBATIMENTLIB,
       p.VAL                           AS IDPARQUETLIB,
       ai.LIBELLE                      AS IDPRODUITLIB,
       CASE f.ETAT
           WHEN 1  THEN 'CREE'
           WHEN 11 THEN 'VALIDE'
           WHEN 0  THEN 'ANULLE'
           END                                AS ETATLIB
FROM FUMIGATION f
         LEFT JOIN NUMEROCOLLECTE nc ON nc.ID = f.IDNUMEROVAGUE
         LEFT JOIN LOG_PERSONNEL op ON op.ID = f.IDOPERATEUR
         LEFT JOIN LOT l ON l.ID = f.IDLOT
         LEFT JOIN BATIMENT b ON b.ID = f.IDBATIMENT
         LEFT JOIN PARQUET p ON p.ID = f.IDPARQUET
         LEFT JOIN AS_INGREDIENTS ai ON ai.ID = f.IDPRODUIT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."GETNUMERO_CARTON_NEXT" ("ID", "IDBC", "ETAT", "IDBL", "NUMERO", "DATECREATION", "REMARQUE", "NUMEROCARTON") AS
SELECT 
    c.ID,
    c.IDBC,
    c.ETAT,
    c.IDBL,
    c.NUMERO,
    c.DATECREATION,
    c.REMARQUE,
    COUNT(*) AS NUMEROCARTON
FROM CARTON c 
WHERE c.ETAT >= 11
GROUP BY 
    c.ID,
    c.IDBC,
    c.ETAT,
    c.IDBL,
    c.NUMERO,
    c.DATECREATION,
    c.REMARQUE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."HEURESUPFABRICATION_CPL" ("ID", "IDRESSPARFAB", "HEURENORMALE", "HS", "MN", "JF", "HD", "IF", "ETAT", "REMARQUE", "IDPERSONNE", "IDFABRICATION", "DATEFABRICATION", "ETATLIB", "IDPERSONNELIB", "MATRICULE", "TAUXHORAIRE", "TAUXHORAIREEFFECTIVE", "TEMPORAIRE", "MONTANT", "IDQUALIFICATION", "MONTANTJF", "MONTANTHD", "MONTANTIF", "MONTANTMN", "MONTANTHN", "IDDEPARTEMENT", "DEPARTEMENTLIB", "POSTE", "POSTELIB", "DATEIMPORT", "MONTANTHEURESUPP") AS
SELECT
    h.ID,h.IDRESSPARFAB,h.HEURENORMALE ,h.HS,h.MN,h.JF,h.HD,h.IF,h.ETAT,h.REMARQUE,
    p.id AS  idPersonne,
    h.idFabrication,
    h.daty as dateFabrication,
    CASE
        WHEN h.etat=0
            THEN 'ANNULE'
        WHEN h.etat=1
            THEN 'CREE'
        WHEN h.etat=11
            THEN 'VISE'
        END AS etatlib,
    pm.NOM || ' ' || pm.PRENOM AS idPersonnelib,
    p.MATRICULE,
    h.TAUXHORAIRE,
    CAST(nvl(c.montant,0)/((40*52)/12) AS NUMBER(30,2) ) AS TAUXHORAIREEFFECTIVE,
    p.temporaire,
    h.MONTANT,
    r.IDQUALIFICATION,
    NVL(h.montantJF, 0) as montantJF,
    NVL(h.montantHD, 0) as montantHD,
    NVL(h.montantIF,0) as montantIF,
    NVL(h.montantMN, 0) as montantMN,
    NVL(h.MONTANTHN, 0) as montantHN,
    p.IDDEPARTEMENT,
    d.val as departementLib,
    h.poste,
    pf.val as PosteLib,
    h.DATEIMPORT,
    h.MONTANTHEURESUPP
FROM HEURESUPFABRICATION h
         LEFT JOIN RESSOURCEPARFABRICATIONCOMPLET r ON r.id = h.IDRESSPARFAB
         LEFT JOIN PAIE_INFO_PERSONNEL p ON p.id = r.idRessource
         LEFT JOIN CATEGORIE_QUALIFICATION c
                   ON c.IDQUALIFICATION = r.IDQUALIFICATION
                       AND c.IDCATEGORIE = r.IDCATEGORIE
                       AND (
                          (c.REMARQUE IS NULL)
                              OR (c.REMARQUE = r.IDRESSOURCE)
                          ) AND c.etat = 1
         LEFT JOIN LOG_PERSONNEL pm ON pm.id = r.IDRESSOURCE
         LEFT JOIN FABRICATION fab ON fab.ID = h.IDFABRICATION
         LEFT JOIN DEPARTEMENT d on d.id = p.IDDEPARTEMENT
         LEFT JOIN PAIE_FONCTION pf on pf.id = h.poste;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."HEURESUPFABRICATION_CPL_VISEE" ("ID", "IDRESSPARFAB", "HEURENORMALE", "HS", "MN", "JF", "HD", "IF", "ETAT", "REMARQUE", "IDPERSONNE", "IDFABRICATION", "DATEFABRICATION", "ETATLIB", "IDPERSONNELIB", "MATRICULE", "TAUXHORAIRE", "TAUXHORAIREEFFECTIVE", "TEMPORAIRE", "MONTANTTOTAL", "IDQUALIFICATION", "VALEURJF", "VALEURHD", "VALEURIF", "VALEURMN", "VALEURHN", "VALEURHS", "IDDEPARTEMENT", "DEPARTEMENTLIB") AS
SELECT
    hs.ID,
    hs.IDRESSPARFAB,
    hs.HEURENORMALE,
    hs.HS,
    hs.MN,
    hs.JF,
    hs.HD,
    hs.IF,
    hs.ETAT,
    hs.REMARQUE,
    hs.IDPERSONNE,
    hs.IDFABRICATION,
    hs.DATEFABRICATION,
    hs.ETATLIB,
    hs.IDPERSONNELIB,
    hs.MATRICULE,
    CAST(hs.TAUXHORAIRE AS NUMBER(30,2)) as TAUXHORAIRE,
    hs.TAUXHORAIREEFFECTIVE,
    hs.TEMPORAIRE,
    CAST(hs.MONTANT AS NUMBER(30,2)) AS montantTotal,
    hs.IDQUALIFICATION,
    hs.MONTANTJF AS valeurJF,
    hs.MONTANTHD AS valeurHD,
    hs.MONTANTIF AS valeurIF,
    hs.MONTANTMN AS valeurMN,
    hs.MONTANTHN AS valeurHN,
    hs.MONTANTHEURESUPP AS valeurHS,
    hs.IDDEPARTEMENT,
    hs.DEPARTEMENTLIB
FROM HEURESUPFABRICATION_CPL hs
WHERE hs.ETAT = 11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."HEURESUPFABRICATION_CUMUL" ("IDPERSONNE", "IDPERSONNELIB", "MATRICULE", "SEMAINE", "JOUR", "HEUREJOUR", "HEUREDEJACUMULEES") AS
SELECT
    p.id AS idPersonne,
    pm.NOM AS idPersonnelib,
    p.MATRICULE,
    TO_CHAR(h.daty, 'IYYY-IW') AS semaine,
    h.daty AS jour,
    SUM(h.HS) AS heureJour,
    SUM(SUM(h.HS)) OVER (
        PARTITION BY p.id, TO_CHAR(h.daty, 'IYYY-IW')
        ORDER BY h.daty
        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
    ) - SUM(h.HS) AS heureDejaCumulees
FROM HEURESUPFABRICATION h
         LEFT JOIN RESSOURCEPARFABRICATIONCOMPLET r ON r.id = h.IDRESSPARFAB
         LEFT JOIN PAIE_INFO_PERSONNEL p ON p.id = r.idRessource
         LEFT JOIN PERSONNEL_MATRICULE pm ON pm.id = r.IDRESSOURCE
         LEFT JOIN FABRICATION fab ON fab.ID = h.IDFABRICATION
WHERE h.ETAT >= 11
GROUP BY p.id, pm.NOM, p.MATRICULE, h.daty;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."HEURESUPFABRICATION_TOTAL" ("IDPERSONNE", "IDPERSONNELIB", "MATRICULE", "TAUXHORAIRE", "TAUXHORAIREEFFECTIVE", "TEMPORAIRE", "SEMAINE", "TOTALHEURESEMAINE") AS
SELECT
    p.id AS idPersonne,
    pm.NOM AS idPersonnelib,
    p.MATRICULE,
    r.TAUXHORAIRE,
    CAST(NVL(c.montant,0)/((40*52)/12) AS NUMBER(30,2)) AS TAUXHORAIREEFFECTIVE,
    p.temporaire,
    TO_CHAR(h.daty, 'IYYY-IW') AS semaine,
    SUM(h.HS) AS totalHeureSemaine
FROM HEURESUPFABRICATION h
         LEFT JOIN RESSOURCEPARFABRICATIONCOMPLET r ON r.id = h.IDRESSPARFAB
         LEFT JOIN PAIE_INFO_PERSONNEL p ON p.id = r.idRessource
         LEFT JOIN CATEGORIE_QUALIFICATION c ON c.IDQUALIFICATION = p.IDQUALIFICATION
         LEFT JOIN PERSONNEL_MATRICULE pm ON pm.id = r.IDRESSOURCE
         LEFT JOIN FABRICATION fab ON fab.ID = h.IDFABRICATION
GROUP BY p.id, pm.NOM, p.MATRICULE, r.TAUXHORAIRE, p.temporaire,
         TO_CHAR(h.daty, 'IYYY-IW'), c.montant;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."HISTOINSERTVUE" ("IDHISTORIQUE", "DATEHISTORIQUE", "HEURE", "OBJET", "ACTION", "IDUTILISATEUR", "REFOBJET", "REMARQUE") AS
SELECT 
h.IDHISTORIQUE,
h.DATEHISTORIQUE,
h.HEURE,
h.OBJET,
h.ACTION,
h.IDUTILISATEUR,
h.REFOBJET,
h.REMARQUE||' '||h.REFOBJET AS REMARQUE
FROM HISTOINSERT h;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."HISTORIQUEAVECUSER" ("IDHISTORIQUE", "DATEHISTORIQUE", "HEURE", "OBJET", "ACTION", "IDUTILISATEUR", "REFOBJET") AS
select
    idhistorique,
    datehistorique,
    heure,
    SUBSTR(objet, INSTR(objet, '.', -1) + 1) as objet,
    action,
    u.LOGINUSER as idutilisateur,
    refobjet
from HISTORIQUE h
         join UTILISATEUR u on u.REFUSER = h.IDUTILISATEUR
order by h.DATEHISTORIQUE desc, h.heure desc;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."HISTORIQUEDEMANDEMAX" ("IDDEMANDE", "DATY", "HEURE") AS
SELECT h.iddemande,
       max(h.daty) AS daty,
       max(h.heure) AS heure
FROM historiquedemande h
GROUP BY h.iddemande;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."HISTORIQUEINSPECTIONFILLELIB" ("ID", "IDMERE", "IDELEMENT", "ETATINSPECTION", "REMARQUE", "IDELEMENTLIB") AS
SELECT
    hif.id,
    hif.idmere,
    hif.idelement,
    hif.etatinspection,
    hif.remarque,
    eim.IDELEMENTINSPECTIONLIB AS idElementLib
FROM historiqueinspectionfille hif
         LEFT JOIN ELEMENTINSPECTIONMACHINELIB eim
                   ON hif.idelement = eim.IDELEMENTINSPECTION;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."HISTORIQUEINSPECTIONLIB" ("ID", "DATY", "HEURE", "IDINSPECTEUR", "IDELEMENT", "REMARQUE", "ETAT", "IDINSPECTEURLIB", "IDELEMENTLIB") AS
SELECT
    hi.id,
    hi.daty,
    hi.heure,
    hi.idinspecteur,
    hi.idelement,
    hi.remarque,
    hi.etat,
    p.nom AS idInspecteurLib,
    aim.libelle AS idElementLib
FROM HISTORIQUEINSPECTIONMERE hi
         JOIN personnel p
              ON hi.idinspecteur = p.id
         JOIN as_ingredient_maintenance aim
              ON hi.idelement = aim.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."HISTORIQUEPRIXLIB" ("ID", "PRODUIT", "DATY", "PV", "IDPRODUIT", "IDFACTUREFOURNISSEURFILLE", "REMARQUE", "ETAT", "ETATLIB") AS
SELECT 
  	h.ID,
  	ing.LIBELLE AS produit,
	h.DATY,
	h.PV,
	h.idProduit,
	h.idFacturefournisseurfille,
	h.REMARQUE,
	h.ETAT,
	CASE
		WHEN h.ETAT=1
		THEN 'CR&Eacute;&Eacute;'
		WHEN h.ETAT=11
		THEN 'VALID&Eacute;'
		WHEN h.ETAT=0
		THEN 'ANNUL&Eacute;'
	    WHEN h.ETAT=21
		THEN 'ENTAM&Eacute;'
	    WHEN h.ETAT=31
		THEN 'BLOQU&Eacute;'
	    WHEN h.ETAT=41
		THEN 'TERMIN&Eacute;'
	END AS ETATLIB
FROM HISTORIQUEPRIX h 
	LEFT JOIN AS_INGREDIENTS ing ON ing.ID = h.idProduit;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."HISTORIQUEPUINGTRIE" ("ID", "DATY", "PU", "REMARQUE", "IDINGREDIENTS") AS
select "ID","DATY","PU","REMARQUE","IDINGREDIENTS" from HISTORIQUEPUING order by DATY desc;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."HISTORIQUEPVINGTRIE" ("ID", "DATY", "PU", "REMARQUE", "IDINGREDIENTS") AS
select "ID","DATY","PU","REMARQUE","IDINGREDIENTS" from HISTORIQUEPVING order by DATY desc;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."HISTORIQUE_PRODUIT_LIB" ("ID", "DATY", "IDPRODUIT", "IDPRODUITLIB", "PUACHAT", "PUVENTE") AS
SELECT 
hp.ID ,
hp.DATY ,
hp.IDPRODUIT ,
p.VAL AS IDPRODUITLIB,
hp.PUACHAT ,
hp.PUVENTE 
FROM HISTORIQUE_PRODUIT hp 
LEFT JOIN PRODUIT p ON p.ID = hp.IDPRODUIT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."HSMOIS_CPL" ("ID", "IDCATEGORIE", "MOIS", "ANNEE", "MOISLIB", "DATY", "IDDEPARTEMENT", "ETAT", "IDCATEGORIELIB", "IDDEPARTEMENTLIB", "ETATLIB") AS
SELECT
    hs."ID",hs."IDCATEGORIE",hs."MOIS",hs."ANNEE",
    TO_CHAR(

            TO_DATE(TO_CHAR(hs.mois, 'FM00'), 'MM'),

            'FMMonth',

            'NLS_DATE_LANGUAGE=FRENCH'

    ) AS moisLib,
    hs."DATY",hs."IDDEPARTEMENT",hs."ETAT",
    c.val AS idCategorieLib,
    d.val AS idDepartementLib,
    CASE
        WHEN hs.etat = 1 THEN 'CREE'
        WHEN hs.etat = 11 THEN 'VISEE'
        ELSE 'INCONNU'
        END AS etatLib
FROM
    HSMOIS hs
        LEFT JOIN CATEGORIE_PAIE c ON hs.idCategorie = c.id
        LEFT JOIN departement d ON hs.idDepartement = d.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."HS_FABBRICATION_SEMAINECPL" ("ID", "IDPERSONNE", "ANNEE", "MOIS", "SEMAINE", "HS_TOTAL", "HS30", "HS50", "MATRICULE", "NOMPERSONNEL", "DATEDEBUTSEMAINE", "DATEFINSEMAINE", "IF", "JF", "MN", "HD", "HS") AS
SELECT
    hs."IDPERSONNE" as id, hs."IDPERSONNE",hs."ANNEE",hs."MOIS",hs."SEMAINE",hs."HS_TOTAL",hs."HS30",hs."HS50",
    pip.matricule,
    log.nom || ' ' || log.prenom as nomPersonnel,
    CAST(
            TRUNC(TO_DATE(SUBSTR(hs.SEMAINE, 1, 4) || '-01-04', 'YYYY-MM-DD'), 'IW')
                + (TO_NUMBER(SUBSTR(hs.SEMAINE, 6, 2)) - 1) * 7
        AS DATE
    ) AS DATEDEBUTSEMAINE,
    CAST(
            TRUNC(TO_DATE(SUBSTR(hs.SEMAINE, 1, 4) || '-01-04', 'YYYY-MM-DD'), 'IW')
                + (TO_NUMBER(SUBSTR(hs.SEMAINE, 6, 2)) - 1) * 7
                + 6
        AS DATE
    ) AS DATEFINSEMAINE,
    hs.IF AS IF,
    hs.JF AS JF,
    hs.MN AS MN,
    hs.HD AS HD,
    hs.hs_total AS HS
FROM HS_FABRICATION_SEMAINE hs

         LEFT JOIN PAIE_INFO_PERSONNEL pip ON pip.id = hs.IDPERSONNE

         LEFT JOIN LOG_PERSONNEL log ON log.id = hs.IDPERSONNE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."HS_FABRICATION_SEMAINE" ("IDPERSONNE", "ANNEE", "MOIS", "SEMAINE", "HS_TOTAL", "HS30", "HS50", "IF", "JF", "MN", "HD") AS
SELECT
    hp.idPersonne,
    p.annee,
    p.mois,
    TO_CHAR(hp.DATEFABRICATION, 'IYYY-IW') AS semaine,
    SUM(hp.HS) AS hs_total,
    LEAST(SUM(hp.HS), 8) AS hs30,
    GREATEST(SUM(hp.HS) - 8, 0) AS hs50,
    SUM( hp.IF) AS if, sum(hp.JF) as JF, SUM(hp.MN) as MN , SUM( hp.HD) as HD
FROM HEURESUPFABRICATION_CPL hp
         LEFT JOIN FABRICATION f ON f.id = hp.IDFABRICATION
         LEFT JOIN PERIODEPAIE p ON hp.DATEFABRICATION BETWEEN p.datedebut AND p.datefin
GROUP BY hp.idPersonne, p.annee, p.mois, TO_CHAR(hp.DATEFABRICATION, 'IYYY-IW');

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."HS_FAB_SEMAINE_PARTRANCHE" ("IDPERSONNE", "IDRESSPARFAB", "SEMAINE", "ANNEE", "MOIS", "HS_TOTAL", "HS30", "HS50", "MONTANT_TOTAL", "IDDEPARTEMENT", "IDCATEGORIE") AS
SELECT
    pip.id as idpersonne,
    hp.IDRESSPARFAB,
    TO_CHAR(f.daty, 'IYYY-IW') AS semaine,
    p.annee,
    p.mois,

    SUM(hp.HS) AS hs_total,

    CASE
        WHEN SUM(hp.HS) <= 8 THEN SUM(hp.HS)
        ELSE 8
        END AS hs30,

    CASE
        WHEN SUM(hp.HS) <= 8 THEN 0
        ELSE SUM(hp.HS) - 8
        END AS hs50,

    SUM(hp.MONTANT) AS montant_total,

    pip.IDDEPARTEMENT,
    pip.IDCATEGORIE_PAIE AS idCategorie

FROM HEURESUPFABRICATION hp
         JOIN FABRICATION f ON f.id = hp.IDFABRICATION
         LEFT JOIN PERIODEPAIE p
                   ON f.daty BETWEEN p.datedebut AND p.datefin
         LEFT JOIN RESSOURCEPARFABRICATION ress ON ress.id = hp.IDRESSPARFAB
         LEFT JOIN PAIE_INFO_PERSONNEL pip
                   ON pip.id = ress.IDRESSOURCE

GROUP BY
    pip.id,
    hp.IDRESSPARFAB,
    TO_CHAR(f.daty, 'IYYY-IW'),
    p.annee,
    p.mois,
    pip.IDDEPARTEMENT,
    pip.IDCATEGORIE_PAIE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."HS_GROUPE" ("ID", "MATRICULE", "DATE_DEBUT", "DATE_FIN", "RETENUE", "REMARQUE", "NOMPERSONNEL", "ETAT", "ID_OBJET", "IDUSER", "MOISREGULARISATION", "ANNEEREGULARISATION", "IDCATEGORIE_QUALIFICATION", "IDFONCTION", "POURCENTAGE", "ETATLIB", "HS_30_NI", "HS_30_I", "HS_50_NI", "HS_50_I") AS
SELECT "ID","MATRICULE","DATE_DEBUT","DATE_FIN","RETENUE","REMARQUE","NOMPERSONNEL","ETAT","ID_OBJET","IDUSER","MOISREGULARISATION","ANNEEREGULARISATION","IDCATEGORIE_QUALIFICATION","IDFONCTION","POURCENTAGE","ETATLIB","HS_30_NI","HS_30_I","HS_50_NI","HS_50_I"
FROM (
         SELECT
             p.idpersonnel as id,
             p.matricule,
             p.id_code_rubrique,
--         p.nomRubrique,
             p.date_debut,
             p.date_fin,
             p.gain,
             p.retenue,
             p.remarque,
             p.nomPersonnel,
             p.etat,
             p.id_objet,
             p.iduser,
             p.moisregularisation,
             p.anneeregularisation,
             p.idcategorie_qualification,
             p.idfonction,
             p.pourcentage,
             p.etatLib
         FROM PAIEPERS_ELP_CPL p
     )
         PIVOT (
                SUM(gain)
    FOR id_code_rubrique IN (
        'PR0000130'  AS "HS_30_NI",
        'PR0000130I' AS "HS_30_I",
        'PR0000150'  AS "HS_50_NI",
        'PR0000150I' AS "HS_50_I"
        )
        ) ORDER BY matricule ASC;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."HS_MOIS" ("IDPERSONNEL", "ANNEE", "MOIS", "HS30_MOIS", "HS50_MOIS", "IDDEPARTEMENT", "IDCATEGORIE") AS
SELECT
    IDPERSONNE as idPersonnel,
    annee,
    mois,
    SUM(hs30) AS hs30_mois,
    SUM(hs50) AS hs50_mois,
    pip.IDDEPARTEMENT,
    pip.IDCATEGORIE_PAIE as idCategorie
FROM HS_FABRICATION_SEMAINE hs
         LEFT JOIN PAIE_INFO_PERSONNEL pip on pip.id = hs.idPersonne
GROUP BY idPersonne, annee, mois, pip.IDDEPARTEMENT, pip.IDCATEGORIE_PAIE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."HS_MOIS_PARTRANCHE" ("IDPERSONNE", "ANNEE", "MOIS", "HS30_MOIS", "HS50_MOIS", "IDDEPARTEMENT", "IDCATEGORIE") AS
SELECT
    idPersonne,
    annee,
    mois,

    SUM(hs30) AS hs30_mois,
    SUM(hs50) AS hs50_mois,

    pip.IDDEPARTEMENT,
    pip.IDCATEGORIE_PAIE AS idCategorie

FROM HS_FABRICATION_SEMAINE hs
         LEFT JOIN PAIE_INFO_PERSONNEL pip
                   ON pip.id = hs.idPersonne

GROUP BY
    idPersonne,
    annee,
    mois,
    pip.IDDEPARTEMENT,
    pip.IDCATEGORIE_PAIE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."HS_NON_PAYE" ("ID", "IDRESSPARFAB", "HS", "MN", "JF", "HD", "IF", "ETAT", "IDPERSONNE", "IDFABRICATION", "ETATLIB", "NOMPERSONNEL", "MONTANTJF", "MONTANTHD", "TOTAL", "MATRICULE") AS
SELECT hs.ID,hs.IDRESSPARFAB,hs.HS,hs.MN,hs.JF,hs.HD,hs.IF,hs.ETAT,hs.IDPERSONNE,hs.IDFABRICATION,hs.ETATLIB,hs.IDPERSONNELIB AS nomPersonnel,hsf.MONTANTJF ,hsf.MONTANTHD ,hsf.MONTANTJF+hsf.MONTANTHD AS total,hsf.MATRICULE
FROM HEURESUPFABRICATION_CPL_VISEE hs
         LEFT JOIN HEURESUPFABRICATION_CPL hsf ON hsf.id=hs.id
WHERE hs.ID NOT IN (
    SELECT IDHS
    FROM PAIEMENTHEURESUP
    WHERE IDHS IS NOT NULL
);

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."HS_PAR_FAB" ("IDMERE", "CATEGORIE", "MONTANTPERSONNEL") AS
SELECT
    fab.id AS idMere,
    'CATING000001' AS CATEGORIE,
    CAST(SUM(hs.MONTANT) AS NUMBER(30,2)) AS montantPersonnel
FROM HEURESUPFABRICATION hs
         JOIN FABRICATION fab ON fab.id = hs.IDFABRICATION
GROUP BY fab.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."HS_PAR_FABRICATION" ("IDFABRICATION", "IDPERSONNE", "DATY", "HS30", "HS50", "MOIS", "ANNEE") AS
SELECT
    d.IDFABRICATION,
    d.idPersonne,
    d.daty,
    d.hs30,
    d.hs50,
    d.mois,
    d.annee
FROM V_HS_FABRICATION_DETAIL d
ORDER BY d.idPersonne, d.daty;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."HS_PAR_OF" ("IDMERE", "CATEGORIE", "MONTANTPERSONNEL") AS
SELECT
    fille.IDMERE AS idMere,
    'CATING000001' AS CATEGORIE,
    CAST(SUM(hs.MONTANT) AS NUMBER(30,2)) AS montantPersonnel
FROM HEURESUPFABRICATION hs
         JOIN FABRICATION fab ON fab.id = hs.IDFABRICATION
         JOIN OFFILLE fille ON fille.id = fab.IDOFFILLE
GROUP BY fille.IDMERE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."HS_PAR_OFFILLE" ("IDMERE", "CATEGORIE", "MONTANTPERSONNEL") AS
SELECT
    fille.id AS idMere,
    'CATING000001' AS CATEGORIE,
    CAST(SUM(hs.MONTANT) AS NUMBER(30,2)) AS montantPersonnel
FROM HEURESUPFABRICATION hs
         JOIN FABRICATION fab ON fab.id = hs.IDFABRICATION
         JOIN OFFILLE fille ON fille.id = fab.IDOFFILLE
GROUP BY fille.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."IMPORTOAC" ("ID", "DATERECEPTION", "DATEPONTE", "DATECOLLECTE", "IDNUMEROCOLLECTE", "HEUREDEPARTFERME", "HEUREARRIVEECOUVOIR", "IDRESPONSABLE", "IDCHAMBREFROIDE", "IDCHAUFFEUR", "IDVEHICULE", "TEMPERATUREMINVEHICULE", "TEMPERATUREMAXVEHICULE", "IDPROVENANCE", "ETAT", "IDNUMEROCOLLECTELIB", "IDRESPONSABLELIB", "IDCHAMBREFROIDELIB", "IDCHAUFFEURLIB", "IDVEHICULELIB", "ETATLIB", "IDPROVENANCELIB") AS
SELECT rl."ID",
       rl."DATERECEPTION",
       rl."DATEPONTE",
       rl."DATECOLLECTE",
       rl."IDNUMEROCOLLECTE",
       rl."HEUREDEPARTFERME",
       rl."HEUREARRIVEECOUVOIR",
       rl."IDRESPONSABLE",
       rl."IDCHAMBREFROIDE",
       rl."IDCHAUFFEUR",
       rl."IDVEHICULE",
       rl."TEMPERATUREMINVEHICULE",
       rl."TEMPERATUREMAXVEHICULE",
       rl."IDPROVENANCE",
       rl."ETAT",
       rl."IDNUMEROCOLLECTELIB",
       rl."IDRESPONSABLELIB",
       rl."IDCHAMBREFROIDELIB",
       rl."IDCHAUFFEURLIB",
       rl."IDVEHICULELIB",
       rl."ETATLIB",
       o."VAL" AS "IDPROVENANCELIB"
FROM "IMPORTRECEPTIONOAC" rl
         LEFT JOIN "ORIGINELOT" o ON o."ID" = rl."IDPROVENANCE"
WHERE rl."IDPROVENANCE" IS NOT NULL;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."IMPORTOAC_LIB" ("ID", "DATERECEPTION", "DATEPONTE", "DATECOLLECTE", "IDNUMEROCOLLECTE", "HEUREDEPARTFERME", "HEUREARRIVEECOUVOIR", "IDRESPONSABLE", "IDCHAMBREFROIDE", "IDCHAUFFEUR", "IDVEHICULE", "TEMPERATUREMINVEHICULE", "TEMPERATUREMAXVEHICULE", "IDPROVENANCE", "IDNUMEROCOLLECTELIB", "IDRESPONSABLELIB", "IDCHAMBREFROIDELIB", "IDCHAUFFEURLIB", "IDVEHICULELIB") AS
SELECT r."ID",
       r."DATERECEPTION",
       r."DATEPONTE",
       r."DATECOLLECTE",
       r."IDNUMEROCOLLECTE",
       r."HEUREDEPARTFERME",
       r."HEUREARRIVEECOUVOIR",
       r."IDRESPONSABLE",
       r."IDCHAMBREFROIDE",
       r."IDCHAUFFEUR",
       r."IDVEHICULE",
       r."TEMPERATUREMINVEHICULE",
       r."TEMPERATUREMAXVEHICULE",
       r."IDPROVENANCE",
       nc."VAL"                          AS "IDNUMEROCOLLECTELIB",
       resp."NOM" || ' ' || resp."PRENOM" AS "IDRESPONSABLELIB",
       cf."VAL"                          AS "IDCHAMBREFROIDELIB",
       chf."NOM" || ' ' || chf."PRENOM"  AS "IDCHAUFFEURLIB",
       v."VAL"                           AS "IDVEHICULELIB"
FROM "RECEPTIONOAC" r
         LEFT JOIN "NUMEROCOLLECTE" nc ON nc."ID" = r."IDNUMEROCOLLECTE"
         LEFT JOIN "LOG_PERSONNEL" resp ON resp."ID" = r."IDRESPONSABLE"
         LEFT JOIN "MAGASIN2" cf ON cf."ID" = r."IDCHAMBREFROIDE"
         LEFT JOIN "LOG_PERSONNEL" chf ON chf."ID" = r."IDCHAUFFEUR"
         LEFT JOIN "VEHICULE" v ON v."ID" = r."IDVEHICULE" WHERE r.IDPROVENANCE IS NOT NULL;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."IMPORTRECEPTIONOAC" ("ID", "DATERECEPTION", "DATEPONTE", "DATECOLLECTE", "IDNUMEROCOLLECTE", "HEUREDEPARTFERME", "HEUREARRIVEECOUVOIR", "IDRESPONSABLE", "IDCHAMBREFROIDE", "IDCHAUFFEUR", "IDVEHICULE", "TEMPERATUREMINVEHICULE", "TEMPERATUREMAXVEHICULE", "IDPROVENANCE", "ETAT", "IDNUMEROCOLLECTELIB", "IDRESPONSABLELIB", "IDCHAMBREFROIDELIB", "IDCHAUFFEURLIB", "IDVEHICULELIB", "ETATLIB") AS
SELECT r."ID",
       r."DATERECEPTION",
       r."DATEPONTE",
       r."DATECOLLECTE",
       r."IDNUMEROCOLLECTE",
       r."HEUREDEPARTFERME",
       r."HEUREARRIVEECOUVOIR",
       r."IDRESPONSABLE",
       r."IDCHAMBREFROIDE",
       r."IDCHAUFFEUR",
       r."IDVEHICULE",
       r."TEMPERATUREMINVEHICULE",
       r."TEMPERATUREMAXVEHICULE",
       r."IDPROVENANCE",
       r."ETAT",
       nc."VAL"                          AS "IDNUMEROCOLLECTELIB",
       resp."NOM" || ' ' || resp."PRENOM" AS "IDRESPONSABLELIB",
       cf."VAL"                          AS "IDCHAMBREFROIDELIB",
       chf."NOM" || ' ' || chf."PRENOM"  AS "IDCHAUFFEURLIB",
       v."VAL"                           AS "IDVEHICULELIB",
       CASE r."ETAT"
            WHEN 1  THEN 'CREE'
            WHEN 11 THEN 'VALIDE'
            WHEN 0  THEN 'ANULLE'
       END                                AS "ETATLIB"
FROM "RECEPTIONOAC" r
         LEFT JOIN "NUMEROCOLLECTE" nc ON nc."ID" = r."IDNUMEROCOLLECTE"
         LEFT JOIN "LOG_PERSONNEL" resp ON resp."ID" = r."IDRESPONSABLE"
         LEFT JOIN "MAGASIN2" cf ON cf."ID" = r."IDCHAMBREFROIDE"
         LEFT JOIN "LOG_PERSONNEL" chf ON chf."ID" = r."IDCHAUFFEUR"
         LEFT JOIN "VEHICULE" v ON v."ID" = r."IDVEHICULE";

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."IMPRIMEDECLARATIONLIB" ("ID", "NUMERO", "RUBRIQUE", "MONTANT", "MONTANTADECLARER") AS
SELECT
    i."ID",i."NUMERO",i."RUBRIQUE",
    0 AS montant,
    0 AS montantadeclarer
FROM IMPRIMEDECLARATION i;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."INFOSAUTOLIB" ("ID", "IDINGREDIENT", "DESCRIPTION", "NUMERODEPARC", "DATEPREMIEREMISEENCIRCULATION", "IMMATRICULATION", "NOTE", "FOURNISSEUR", "NUMERO", "VOLUME", "MONTANT", "TYPE", "VIN", "MARQUE", "MODELE", "ANNEE", "NOMBREDEPLACES", "NOMBREDEPORTES", "PUISSANCEFISCALE", "BAILLEUR", "VALEURINITIALE", "DATEDEBUT", "DURREEENMOIS", "MENSUALITE", "VENDEUR", "PRIX", "DATEDACHAT", "NUMERODIMMOBILISATION", "DUREEDAMORTISSEMENTENMOIS", "PNEUS", "BATTERIE", "HUILEMOTEUR", "HUILEBOITEDEVITESSE", "TYPEDECARBURANT", "CONSOMMATION", "UNITEDECONSOMMATION", "IDINGREDIENTLIB", "TYPEDECARBURANTLIB", "UNITEDECONSOMMATIONLIB") AS
(
    select
    ia."ID",ia."IDINGREDIENT",ia."DESCRIPTION",ia."NUMERODEPARC",ia."DATEPREMIEREMISEENCIRCULATION",ia."IMMATRICULATION",ia."NOTE",ia."FOURNISSEUR",ia."NUMERO",ia."VOLUME",ia."MONTANT",ia."TYPE",ia."VIN",ia."MARQUE",ia."MODELE",ia."ANNEE",ia."NOMBREDEPLACES",ia."NOMBREDEPORTES",ia."PUISSANCEFISCALE",ia."BAILLEUR",ia."VALEURINITIALE",ia."DATEDEBUT",ia."DURREEENMOIS",ia."MENSUALITE",ia."VENDEUR",ia."PRIX",ia."DATEDACHAT",ia."NUMERODIMMOBILISATION",ia."DUREEDAMORTISSEMENTENMOIS",ia."PNEUS",ia."BATTERIE",ia."HUILEMOTEUR",ia."HUILEBOITEDEVITESSE",ia."TYPEDECARBURANT",ia."CONSOMMATION",ia."UNITEDECONSOMMATION",
    ing.libelle as idingredientLib,
    tc.val as typeDeCarburantLib,
    uc.val as unitedeconsommationLib
    from INFOSAUTO ia
    left join AS_INGREDIENTS ing on ia.idingredient=ing.id
    left join TYPECARBURANT tc on tc.id=ia.TYPEDECARBURANT
    left join UNITECONSO uc on uc.id=ia.unitedeconsommation
);

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."INSERTION_FACTURE_FOURNISSEUR" ("ID", "IDFOURNISSEUR", "IDMODEPAIEMENT", "DATY", "DESIGNATION", "DATEECHEANCEPAIEMENT", "ETAT", "REFERENCE", "IDBC", "DEVISE", "TAUX", "IDMAGASIN", "IDDEVISE") AS
SELECT 
f."ID",f."IDFOURNISSEUR",f."IDMODEPAIEMENT",f."DATY",f."DESIGNATION",f."DATEECHEANCEPAIEMENT",f."ETAT",f."REFERENCE",f."IDBC",f."DEVISE",f."TAUX",f."IDMAGASIN",
cast(' ' AS varchar(100)) AS iddevise
FROM FACTUREFOURNISSEUR f;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."INSERTION_VENTE" ("ID", "DESIGNATION", "IDMAGASIN", "DATY", "REMARQUE", "ETAT", "IDORIGINE", "IDCLIENT", "IDDEVISE", "ESTPREVU", "DATYPREVU", "IDRESERVATION", "ECHEANCEFACTURE", "MODEPAIEMENT", "MODELIVRAISON", "FRAISLIVRAISON", "REFERENCEFACT", "LIEULIVRAISON", "DATELIVRAISON", "IDREPRESENTANT") AS
SELECT v.ID,
       v.DESIGNATION,
       v.IDMAGASIN,
       v.DATY,
       v.REMARQUE,
       v.ETAT,
       v.IDORIGINE,
       v.IDCLIENT,
       CAST(' ' AS varchar(100)) AS iddevise,
       v.ESTPREVU,
       v.DATYPREVU,
       v.IDRESERVATION,
       v.echeancefacture,
       v.modepaiement,
       v.modelivraison,
       v.fraislivraison,
       v.referencefact,
       v.LIEULIVRAISON,
       v.DATELIVRAISON,
       V.IDREPRESENTANT
FROM VENTE v;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."INSERTION_VENTEAUTOCOMPLETE" ("ID", "DESIGNATION", "IDMAGASIN", "DATY", "REMARQUE", "ETAT", "IDORIGINE", "IDCLIENT", "IDDEVISE", "ESTPREVU", "DATYPREVU", "IDRESERVATION", "ECHEANCEFACTURE", "MODEPAIEMENT", "MODELIVRAISON", "FRAISLIVRAISON", "REFERENCEFACT", "LIEULIVRAISON", "DATELIVRAISON") AS
SELECT 
i.ID,
i.DESIGNATION,
i.IDMAGASIN,
i.DATY,
i.REMARQUE,
i.ETAT,
i.IDORIGINE,
CASE
	WHEN i.IDCLIENT IS NULL 
	THEN i.IDCLIENT
	ELSE i.IDCLIENT||'---'||c.nom 
END AS IDCLIENT ,
i.IDDEVISE,
i.ESTPREVU,
i.DATYPREVU,
i.IDRESERVATION,
i.ECHEANCEFACTURE,
i.MODEPAIEMENT,
i.MODELIVRAISON,
i.FRAISLIVRAISON,
i.REFERENCEFACT,
i.LIEULIVRAISON,
i.DATELIVRAISON
FROM INSERTION_VENTE i 
LEFT JOIN CLIENT c ON c.id = i.IDCLIENT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."INSERTION_VENTE_PERSONNEL" ("ID", "DESIGNATION", "IDMAGASIN", "DATY", "REMARQUE", "ETAT", "IDORIGINE", "IDCLIENT", "IDDEVISE", "ESTPREVU", "DATYPREVU", "IDRESERVATION", "IDCOMMERCIAL", "IDMODEPAIEMENT", "REMISE", "REMISEMONTANT", "HEURESAISIE", "IDRESPONSABLE") AS
SELECT v.ID,
       v.DESIGNATION,
       v.IDMAGASIN,
       v.DATY,
       v.REMARQUE,
       v.ETAT,
       v.IDORIGINE,
       v.IDCLIENT,
       CAST(' ' AS varchar(100)) AS iddevise,
       v.ESTPREVU,
       v.DATYPREVU,
       v.IDRESERVATION,
       v.idCommercial,
       v.idmodepaiement,
       v.remise,
       v.remiseMontant,
       v.HEURESAISIE,
       v.IDRESPONSABLE
FROM VENTE v;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."INSERTION_VENTE_PERSONNEL_VIDE" ("ID", "DATY", "DESIGNATION", "IDMAGASIN", "REMARQUE", "ETAT", "IDORIGINE", "IDCLIENT", "IDDEVISE", "ESTPREVU", "DATYPREVU", "IDRESERVATION", "IDCOMMERCIAL", "IDMODEPAIEMENT", "REMISE", "REMISEMONTANT", "HEURESAISIE", "IDRESPONSABLE") AS
SELECT id,daty,designation,idmagasin,remarque,etat,idorigine,idclient,iddevise,estprevu,datyprevu,idreservation,idcommercial,idmodepaiement,remise,remisemontant,HEURESAISIE, IDRESPONSABLE FROM INSERTION_VENTE_PERSONNEL;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."INSPECTIONFILLECPL" ("ID", "IDMERE", "IDELEMENT", "IDETATINSPECTION", "IDETATINSPECTIONLIB", "IDELEMENTLIB", "REMARQUE", "IDMACHINELIB", "IDMACHINE", "IDLIGNE", "IDLIGNELIB") AS
select 
    ifl.id,
    ifl.idMere,
    ifl.idElement ,
    ifl.idEtatInspection,
    ifl.idEtatInspectionlib ,
    ifl.idElementLib,
    ifl.remarque,
    ifl.idMachineLib,
    ifl.idMachine,
    l.id AS idLigne,
    l.VAL AS idLigneLib
from inspectionFIlleLib ifl 
join inspectionMere im on ifl.idMere = im.id
join as_ingredient_Maintenance am on im.IDELEMENT = am.id
left join ligne l on am.IDLIGNE = l.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."INSPECTIONFILLELIB" ("ID", "IDMERE", "IDELEMENT", "IDELEMENTLIB", "IDETATINSPECTION", "REMARQUE", "IDETATINSPECTIONLIB", "IDMACHINELIB", "IDMACHINE", "IDLIGNE", "IDLIGNELIB") AS
(
SELECT
    ifi.id,
    ifi.idmere,
    ifi.idElement,
    eis.val     AS idElementlib,
    ifi.idEtatInspection,
    ifi.remarque,
    ei.val    AS idEtatInspectionlib,
    m.libelle AS idMachinelib,
    m.id AS idMachine,
     l.id AS idLigne,
    l.VAL AS idLigneLib
FROM InspectionFille ifi
         LEFT JOIN ElementInspection eis
                   ON ifi.idElement = eis.id
         LEFT JOIN ElementInspectionMachine ai
                   ON ai.idelementinspection = ifi.idelement
         LEFT JOIN AS_INGREDIENT_MAINTENANCE m
                   ON ai.idMachine = m.id
         LEFT JOIN EtatInspection ei
                   ON ifi.idEtatInspection = ei.id
         left join ligne l on m.IDLIGNE = l.id);

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."INSPECTIONMERELIB" ("ID", "DATY", "HEURE", "IDINSPECTEUR", "IDELEMENT", "REMARQUE", "ETAT", "IDINSPECTEURLIB") AS
SELECT
    i."ID",i."DATY",i."HEURE",i."IDINSPECTEUR",i."IDELEMENT",i."REMARQUE",i."ETAT",
    p.NOM AS IDINSPECTEURLIB
FROM INSPECTIONMERE i
         LEFT JOIN PERSONNEL p ON i.IDINSPECTEUR = p.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."INVENTAIREAVECVIDE" ("ID", "DATY", "DESIGNATION", "IDMAGASIN", "ETAT", "REMARQUE", "IDCATEGORIE") AS
select "ID","DATY","DESIGNATION","IDMAGASIN","ETAT","REMARQUE","IDCATEGORIE" from INVENTAIRE union all select "ID","DATY","DESIGNATION","IDMAGASIN","ETAT","REMARQUE","IDCATEGORIE" from inventaireMereVideMagasin;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."INVENTAIREDATEHEURE" ("ID", "DATY", "DESIGNATION", "IDMAGASIN", "ETAT", "REMARQUE", "IDCATEGORIE", "HEURE") AS
select i.ID, TO_DATE(TO_CHAR(i.DATY, 'YYYY-MM-DD') || ' ' || NVL(i.HEURE, '00:00:00'), 'YYYY-MM-DD HH24:MI:SS') as DATY, DESIGNATION, IDMAGASIN, ETAT, REMARQUE, IDCATEGORIE, HEURE from INVENTAIRE i;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."INVENTAIREFILLEAUTOCOMPLETE" ("ID", "IDINVENTAIRE", "IDPRODUIT", "EXPLICATION", "IDJAUGE", "QUANTITETHEORIQUE", "QUANTITE", "MVTSRC", "PU", "IDFOURNISSEUR", "DATY") AS
SELECT
    inf.id,
    inf.idinventaire,
    CASE
        WHEN inf.idproduit IS NOT NULL
            THEN inf.idproduit||'---'||ai.libelle
        END AS idproduit,
    inf.explication AS explication,
    inf.idjauge,
    inf.quantitetheorique,
    inf.quantite,
    inf.mvtsrc,
    inf.pu,
    inf.idfournisseur,
    inf.daty
FROM inventairefille inf
         LEFT JOIN AS_INGREDIENTS ai ON ai.id=inf.idproduit;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."INVENTAIREFILLEAVECVIDE" ("ID", "IDINVENTAIRE", "IDPRODUIT", "EXPLICATION", "IDJAUGE", "QUANTITETHEORIQUE", "QUANTITE", "MVTSRC", "PU", "IDFOURNISSEUR", "DATY") AS
select "ID","IDINVENTAIRE","IDPRODUIT","EXPLICATION","IDJAUGE","QUANTITETHEORIQUE","QUANTITE","MVTSRC","PU","IDFOURNISSEUR","DATY" from INVENTAIREFILLE union all select "ID","IDINVENTAIRE","IDPRODUIT","EXPLICATION","IDJAUGE","QUANTITETHEORIQUE","QUANTITE","MVTSOURCE","PU","IDFOURNISSEUR","DATY" from inventaireFilleVide;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."INVENTAIREFILLECOMPLET" ("ID", "IDINVENTAIRE", "IDPRODUIT", "EXPLICATION", "IDJAUGE", "PU", "QUANTITETHEORIQUE", "QUANTITE", "MVTSRC", "IDMAGASIN", "RESTE", "MVTENTREE") AS
SELECT
	i."ID",i."IDINVENTAIRE",i."IDPRODUIT",i."EXPLICATION",i."IDJAUGE",i."PU",i."QUANTITETHEORIQUE",i."QUANTITE",i."MVTSRC",i."IDMAGASIN",
	vee.RESTE , vee.MVTSRC AS mvtentree
FROM
	INVENTAIREFILLEMERE i
LEFT JOIN V_ETATSTOCK_PU vee ON
	vee.ID = i.IDPRODUIT
	AND vee.pu = i.PU
	AND i.IDMAGASIN = vee.IDMAGASIN;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."INVENTAIREFILLEGROUPEMERE" ("IDINVENTAIRE", "MONTANTQUANTITE") AS
select f.IDINVENTAIRE,cast(sum(nvl(f.pu*f.QUANTITE,0)) as number(30,2)) as montantQuantite
from INVENTAIREFILLE f group by f.IDINVENTAIRE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."INVENTAIREFILLELIB" ("ID", "IDINVENTAIRE", "IDPRODUIT", "IDPRODUITLIB", "EXPLICATION", "QUANTITETHEORIQUE", "QUANTITE", "LIBELLEEXTACTE", "PU", "ECART", "ETAT", "ETATLIB") AS
SELECT
    i.ID ,
    i.IDINVENTAIRE ,
    i.IDPRODUIT ,
    p.libelle AS IDPRODUITLIB,
    i.EXPLICATION ,
    i.QUANTITETHEORIQUE ,
    i.QUANTITE,
    p.LIBELLEEXTACTE,
    i.pu,
    cast((i.QUANTITE - i.QUANTITETHEORIQUE) as decimal(30,2)) AS ecart,
    i.ETAT,
    CASE
        WHEN i.ETAT = 0
            THEN 'ANNUL&Eacute;E'
        WHEN i.ETAT = 1
            THEN 'CR&Eacute;&Eacute;E'
        WHEN i.ETAT = 11
            THEN 'VALID&Eacute;E'
        END AS ETATLIB
FROM INVENTAIREFILLE i
     LEFT JOIN AS_INGREDIENTS  p ON p.ID  = i.IDPRODUIT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."INVENTAIREFILLEMERE" ("ID", "IDINVENTAIRE", "IDPRODUIT", "EXPLICATION", "IDJAUGE", "PU", "QUANTITETHEORIQUE", "QUANTITE", "MVTSRC", "IDMAGASIN") AS
SELECT
	i."ID",i."IDINVENTAIRE",i."IDPRODUIT",i."EXPLICATION",i."IDJAUGE",i."PU",i."QUANTITETHEORIQUE",i."QUANTITE",i."MVTSRC",
	i2.IDMAGASIN
FROM
	INVENTAIREFILLE i
JOIN INVENTAIRE i2 ON
	i.IDINVENTAIRE = i2.ID 
WHERE ETAT>0;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."INVENTAIREFILLETYPEMVT" ("ID", "IDINVENTAIRE", "IDPRODUIT", "EXPLICATION", "IDJAUGE", "QUANTITETHEORIQUE", "QUANTITE", "MVTSRC", "PU", "IDFOURNISSEUR", "DATY", "TYPESTOCK") AS
select f."ID",f."IDINVENTAIRE",f."IDPRODUIT",f."EXPLICATION",f."IDJAUGE",f."QUANTITETHEORIQUE",f."QUANTITE",f."MVTSRC",f."PU",f."IDFOURNISSEUR",f."DATY",ing.TYPESTOCK from INVENTAIREFILLE f left join AS_INGREDIENTS ing on f.IDPRODUIT=ing.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."INVENTAIREFILLEUPDATE" ("ID", "IDINVENTAIRE", "IDPRODUIT", "EXPLICATION", "IDJAUGE", "QUANTITETHEORIQUE", "QUANTITE", "MVTSRC", "PU", "IDFOURNISSEUR", "DATY") AS
SELECT
    inf.id,
    inf.idinventaire,
    CASE
        WHEN inf.idproduit IS NOT NULL
            THEN inf.idproduit||'---'||ai.libelle
        END AS idproduit,
    ai.LIBELLE ||' - '|| inf.explication AS explication,
    inf.idjauge,
    inf.quantitetheorique,
    inf.quantite,
    inf.mvtsrc,
    inf.pu,
    inf.idfournisseur,
    inf.daty
FROM inventairefille inf
         LEFT JOIN AS_INGREDIENTS ai ON ai.id=inf.idproduit;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."INVENTAIREFILLEVIDE" ("ID", "IDINVENTAIRE", "IDPRODUIT", "EXPLICATION", "IDJAUGE", "QUANTITETHEORIQUE", "QUANTITE", "MVTSOURCE", "PU", "IDFOURNISSEUR", "DATY") AS
select 'invvidef'||mfv.ID as id,'invVide' as idinventaire,mfv.IDPRODUIT,'inv Auto Vide' as explication,null as idjauge,cast( 0 as number(30,10)) as QUANTITETHEORIQUE,cast(0 as number(30,10)) as quantite,mfv.ID as mvtsource
         ,cast(1 as number(30,5)) as pu,null as idfournisseur, null as daty from mvtStockFilleSansInventaire mfv;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."INVENTAIRELIB" ("ID", "DATY", "DESIGNATION", "IDMAGASIN", "IDMAGASINLIB", "ETAT", "HEURE", "ETATLIB", "IDCATEGORIE", "IDCATEGORIELIB", "MOTSCLESSS", "REMARQUE", "MONTANTQUANTITE") AS
SELECT
    i.ID ,
    i.DATY ,
    i.DESIGNATION ,
    i.IDMAGASIN ,
    m.VAL AS IDMAGASINLIB,
    i.ETAT , i.heure,
    CASE
        WHEN i.ETAT = 0
            THEN 'ANNUL&Eacute;'
        WHEN i.ETAT = 1
            THEN 'CR&Eacute;&Eacute;'
        WHEN i.ETAT = 11
            THEN 'VALID&Eacute;'
        END AS ETATLIB,
    i.idcategorie,
    c.VAL AS idcategorieLib,
    UPPER(
            NVL(i.DESIGNATION, '') || ' ' ||
            NVL(m.VAL, '') || ' ' ||
            NVL(c.VAL, '') || ' ' ||
            NVL(i.ID, '') || ' ' ||
            TO_CHAR(i.DATY, 'DD/MM/YYYY') || ' ' ||
            NVL(
                    CASE
                        WHEN i.ETAT = 0 THEN 'ANNUL&Eacute;'
                        WHEN i.ETAT = 1 THEN 'CR&Eacute;&Eacute;'
                        WHEN i.ETAT = 11 THEN 'VALID&Eacute;'
                        END
                , '')
    ) AS MOTSCLESSS,
    i.REMARQUE,
    CAST(ifgm.montantQuantite AS NUMBER(30,2) ) AS montantQuantite
FROM INVENTAIRE i
         LEFT JOIN MAGASINPOINT m ON m.ID = i.IDMAGASIN
         LEFT JOIN CATEGORIEINGREDIENT c ON c.id = i.idcategorie
         LEFT JOIN INVENTAIREFILLEGROUPEMERE ifgm ON ifgm.IDINVENTAIRE = i.id
order by daty desc;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."INVENTAIRELIB_ANNULEE" ("ID", "DATY", "DESIGNATION", "IDMAGASIN", "IDMAGASINLIB", "ETAT", "ETATLIB", "MOTSCLESSS", "MONTANTQUANTITE") AS
SELECT 
i.ID,i.DATY,i.DESIGNATION,i.IDMAGASIN,i.IDMAGASINLIB,i.ETAT,i.ETATLIB,i.MOTSCLESSS,i.montantQuantite
FROM INVENTAIRELIB i 
WHERE i.ETAT = 0;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."INVENTAIRELIB_CREE" ("ID", "DATY", "DESIGNATION", "IDMAGASIN", "IDMAGASINLIB", "ETAT", "ETATLIB", "MOTSCLESSS", "MONTANTQUANTITE") AS
SELECT 
i.ID,i.DATY,i.DESIGNATION,i.IDMAGASIN,i.IDMAGASINLIB,i.ETAT,i.ETATLIB,i.MOTSCLESSS,i.montantQuantite
FROM INVENTAIRELIB i 
WHERE i.ETAT = 1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."INVENTAIRELIB_VALIDEE" ("ID", "DATY", "DESIGNATION", "IDMAGASIN", "IDMAGASINLIB", "ETAT", "ETATLIB", "MOTSCLESSS", "MONTANTQUANTITE") AS
SELECT 
i.ID,i.DATY,i.DESIGNATION,i.IDMAGASIN,i.IDMAGASINLIB,i.ETAT,i.ETATLIB,i.MOTSCLESSS,i.montantQuantite
FROM INVENTAIRELIB i 
WHERE i.ETAT = 11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."INVENTAIREMEREVIDE" ("ID", "DATY", "DESIGNATION", "IDMAGASIN", "ETAT") AS
select 'invVide' as id, TO_DATE('01/01/2026', 'DD-MM-YYYY') as daty, 'inventaire vide' as designation,'' as idmagasin,11 as etat from dual;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."INVENTAIREMEREVIDEMAGASIN" ("ID", "DATY", "DESIGNATION", "IDMAGASIN", "ETAT", "REMARQUE", "IDCATEGORIE") AS
select inventaireMereVide.id, daty, designation, magasin2.id as idmagasin, inventaireMereVide.etat,'inv vide' as remarque,null as idcategorie from inventaireMereVide,magasin2;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."INVENTAIRE_FILLE_CPL" ("ID", "IDINVENTAIRE", "IDPRODUIT", "IDPRODUITLIB", "EXPLICATION", "QUANTITETHEORIQUE", "QUANTITE", "DATY", "IDMAGASIN", "IDJAUGE", "ETAT", "MVTSRC") AS
SELECT
i.ID ,
i.IDINVENTAIRE ,
i.IDPRODUIT ,
p.LIBELLE AS IDPRODUITLIB,
i.EXPLICATION ,
i.QUANTITETHEORIQUE ,
i.QUANTITE ,
i2.DATY ,
i2.IDMAGASIN ,
i.idJauge,
i2.ETAT,
i.MVTSRC
FROM INVENTAIREFILLE i
LEFT JOIN AS_INGREDIENTS  p ON p.ID  = i.IDPRODUIT
LEFT JOIN INVENTAIRE i2 ON i2.ID  = i.IDINVENTAIRE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."INVENTAIRE_FILLE_CPL_ING" ("ID", "IDINVENTAIRE", "IDPRODUIT", "IDPRODUITLIB", "EXPLICATION", "QUANTITETHEORIQUE", "QUANTITE", "DATY", "IDMAGASIN", "IDJAUGE", "ETAT") AS
SELECT
i.ID ,
i.IDINVENTAIRE ,
NVL(i.IDPRODUIT,p.ID) AS IDPRODUIT,
p.LIBELLE AS IDPRODUITLIB,
NVL(i.EXPLICATION,'Inventaire 0') AS  EXPLICATION,
NVL(i.QUANTITETHEORIQUE,0) AS QUANTITETHEORIQUE,
NVL(i.QUANTITE,0) AS QUANTITE ,
NVL(i2.DATY, TO_DATE('01-01-2001', 'DD-MM-YYYY')) AS DATY ,
NVL(i2.IDMAGASIN, p.IDMAGASIN) AS IDMAGASIN ,
i.idJauge,
NVL(i2.ETAT,11) AS ETAT
FROM AS_INGREDIENTS_MAGASIN p
LEFT JOIN INVENTAIREFILLE i ON p.ID  = i.IDPRODUIT
LEFT JOIN INVENTAIRE i2 ON i2.ID  = i.IDINVENTAIRE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."INVENTAIRE_FILLE_CPL_VALIDE" ("ID", "IDINVENTAIRE", "IDPRODUIT", "IDPRODUITLIB", "EXPLICATION", "QUANTITETHEORIQUE", "QUANTITE", "DATY", "IDMAGASIN", "IDJAUGE", "MVTSRC", "ETAT") AS
SELECT
i."ID",i."IDINVENTAIRE",i."IDPRODUIT",i."IDPRODUITLIB",i."EXPLICATION",i."QUANTITETHEORIQUE",i."QUANTITE",i."DATY",i."IDMAGASIN",i."IDJAUGE",i.MVTSRC,i."ETAT"
FROM INVENTAIRE_FILLE_CPL i
JOIN INVENTAIRE inventaire ON inventaire.ID  = i.IDINVENTAIRE
WHERE inventaire.ETAT >=11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."JAUGELIB" ("ID", "IDMAGASIN", "IDMAGASINLIB", "QTE", "DATY", "ETAT", "ETATLIB") AS
SELECT 
j.ID ,
j.IDMAGASIN ,
m.VAL AS IDMAGASINLIB,
j.QTE ,
j.DATY ,
j.ETAT ,
CASE 
	WHEN j.ETAT = 0 
	THEN 'ANNULEE'
	WHEN j.ETAT = 1 
	THEN 'CREE'
	WHEN j.ETAT = 11 
	THEN 'VALIDEE'
END AS ETATLIB
FROM JAUGE j 
JOIN MAGASIN m ON m.ID  = j.IDMAGASIN;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."JAUGE_LIB_ANNULEE" ("ID", "IDMAGASIN", "IDMAGASINLIB", "QTE", "DATY", "ETAT", "ETATLIB") AS
SELECT 
j."ID",j."IDMAGASIN",j."IDMAGASINLIB",j."QTE",j."DATY",j."ETAT",j."ETATLIB"
FROM JAUGELIB j 
WHERE j.ETAT = 0;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."JAUGE_LIB_CREE" ("ID", "IDMAGASIN", "IDMAGASINLIB", "QTE", "DATY", "ETAT", "ETATLIB") AS
SELECT 
j."ID",j."IDMAGASIN",j."IDMAGASINLIB",j."QTE",j."DATY",j."ETAT",j."ETATLIB"
FROM JAUGELIB j 
WHERE j.ETAT = 1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."JAUGE_LIB_VALIDEE" ("ID", "IDMAGASIN", "IDMAGASINLIB", "QTE", "DATY", "ETAT", "ETATLIB") AS
SELECT 
j."ID",j."IDMAGASIN",j."IDMAGASINLIB",j."QTE",j."DATY",j."ETAT",j."ETATLIB"
FROM JAUGELIB j 
WHERE j.ETAT = 11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."JOURS_PAR_MOIS" ("ANNEE", "MOIS", "NB_JOUR", "CONGE_JOURNALIER") AS
SELECT
    EXTRACT(YEAR FROM ADD_MONTHS(DATE '2019-01-01', LEVEL - 1)) AS annee,
    EXTRACT(MONTH FROM ADD_MONTHS(DATE '2019-01-01', LEVEL - 1)) AS mois,
    TO_NUMBER(TO_CHAR(LAST_DAY(ADD_MONTHS(DATE '2019-01-01', LEVEL - 1)), 'DD')) AS nb_jour,
    ROUND(2.5 / TO_NUMBER(TO_CHAR(LAST_DAY(ADD_MONTHS(DATE '2019-01-01', LEVEL - 1)), 'DD')), 6) AS conge_journalier
FROM dual
    CONNECT BY ADD_MONTHS(DATE '2019-01-01', LEVEL - 1) < SYSDATE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."LIAISONCODELIB" ("ID", "IDCODEIMPOT", "IDCOMPTE", "FORMULE", "TAXABLE", "IDCODEIMPOTLIB") AS
SELECT
    ls.id,
    ls.idCodeImpot,
    ls.idCompte,
    ls.FORMULE,
    CASE
        WHEN ls.TAXABLE = 1 THEN 'Oui'
        WHEN ls.TAXABLE = 0 THEN 'Non'
        ELSE NULL
        END AS TAXABLE,
      i.rubrique AS IDCODEIMPOTLIB
FROM LiaisonCodeImpot ls
LEFT JOIN imprimedeclaration i ON  ls.idcodeimpot=i.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."LIAISONCODESAISIE" ("ID", "IDCODEIMPOT", "IDCOMPTE", "VALEUR", "FORMULE", "TAXABLE") AS
SELECT
    id,
    idCodeImpot,
    idCompte,
    ' ' AS valeur,
    FORMULE,
    TAXABLE
FROM LiaisonCodeImpot;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."LIAISONPAIEMENTMVTCAISSEGRP" ("IDMVTCAISSE", "MONTANT") AS
select id1 as idmvtcaisse, sum(MONTANT) as montant from LIAISONPAIEMENT where etat = 11
group by id1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."LIAISONPAIEMENTMVTCAISSEGRP2" ("IDMVTCAISSE", "MONTANT") AS
select id1 as idmvtcaisse, cast(sum(nvl(MONTANT, 0)) as number(30,2)) as montant from LIAISONPAIEMENT where etat = 11
group by id1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."LIAISONPAIEMENTTOTAL" ("ID2", "MONTANT") AS
select id2,sum(nvl(montant,0)) as montant from LIAISONPAIEMENT where etat>=11 group by id2;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."LISTECOLONNETABLE" ("OWNER", "TABLE_NAME", "COLUMN_NAME", "DATA_TYPE", "DATA_TYPE_MOD", "DATA_TYPE_OWNER", "DATA_LENGTH", "DATA_PRECISION", "DATA_SCALE", "NULLABLE", "COLUMN_ID", "DEFAULT_LENGTH", "DATA_DEFAULT", "NUM_DISTINCT", "LOW_VALUE", "HIGH_VALUE", "DENSITY", "NUM_NULLS", "NUM_BUCKETS", "LAST_ANALYZED", "SAMPLE_SIZE", "CHARACTER_SET_NAME", "CHAR_COL_DECL_LENGTH", "GLOBAL_STATS", "USER_STATS", "AVG_COL_LEN", "CHAR_LENGTH", "CHAR_USED", "V80_FMT_IMAGE", "DATA_UPGRADED", "HISTOGRAM") AS
select 'a' as owner , ua."TABLE_NAME",ua."COLUMN_NAME",ua."DATA_TYPE",ua."DATA_TYPE_MOD",ua."DATA_TYPE_OWNER",ua."DATA_LENGTH",ua."DATA_PRECISION",ua."DATA_SCALE",ua."NULLABLE",ua."COLUMN_ID",ua."DEFAULT_LENGTH",ua."DATA_DEFAULT",ua."NUM_DISTINCT",ua."LOW_VALUE",ua."HIGH_VALUE",ua."DENSITY",ua."NUM_NULLS",ua."NUM_BUCKETS",ua."LAST_ANALYZED",ua."SAMPLE_SIZE",ua."CHARACTER_SET_NAME",ua."CHAR_COL_DECL_LENGTH",ua."GLOBAL_STATS",ua."USER_STATS",ua."AVG_COL_LEN",ua."CHAR_LENGTH",ua."CHAR_USED",ua."V80_FMT_IMAGE",ua."DATA_UPGRADED",ua."HISTOGRAM" from USER_TAB_COLUMNS ua union all
select tc.OWNER,syn.SYNONYM_NAME as table_name, tc.COLUMN_NAME,tc.DATA_TYPE,tc.DATA_TYPE_MOD,
       tc.DATA_TYPE_OWNER,tc.DATA_LENGTH,tc.DATA_PRECISION,tc.DATA_SCALE,tc.NULLABLE,tc.COLUMN_ID,
       tc.DEFAULT_LENGTH,tc.DATA_DEFAULT,tc.NUM_DISTINCT,tc.LOW_VALUE,tc.HIGH_VALUE,tc.DENSITY,
       tc.NUM_NULLS,tc.NUM_BUCKETS,tc.LAST_ANALYZED,tc.SAMPLE_SIZE,tc.CHARACTER_SET_NAME,
       tc.CHAR_COL_DECL_LENGTH,
       tc.GLOBAL_STATS,tc.USER_STATS,tc.AVG_COL_LEN,tc.CHAR_LENGTH,tc.CHAR_USED,tc.V80_FMT_IMAGE,
       tc.DATA_UPGRADED,tc.HISTOGRAM
from ALL_TAB_COLUMNS tc join USER_SYNONYMS syn on syn.TABLE_NAME=tc.TABLE_NAME and syn.TABLE_OWNER=tc.OWNER;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."LOG_PERSONNEL_AVECCONGE" ("ID", "PERMIS_CONDUIRE", "CHEMIN_PERMIS", "REMARQUE", "ID_PERS", "NOM", "PRENOM", "DATE_NAISSANCE", "SEXE", "NUMERO_CIN", "DATE_CIN", "DATE_DUPL_CIN", "NATIONALITE", "ADRESSE", "FOKOTANY", "ACTE_NAISSANCE", "DIRECTION", "SERVICE", "CODE_DR", "MATRICULE", "IDCATEGORIE", "CTG", "INDICEGRADE", "INDICE_FONCTIONNEL", "STATUT", "CATEGORIEVAL", "CTGVAL", "NUMERO_CNAPS", "NUMERO_OSTIE", "TEMPORAIRE", "DROIT", "PRIE", "RESTECONGE", "ETAT", "IDPERSONNEL", "IDDIRECTION", "IDDEPARTEMENT", "DEPARTEMENTLIB", "IDQUALIFICATION", "QUALIFICATIONLIB", "ETATLIB") AS
SELECT l.id,
       l.permis_conduire,
       l.chemin_permis,
       l.remarque,
       l.id_pers,
       l.nom,
       l.prenom,
       l.date_naissance,
       sex.desce AS sexe,
       l.numero_cin,
       l.date_cin,
       l.date_dupl_cin,
       l.nationalite,
       l.adresse,
       l.fokotany,
       l.acte_naissance,
       d.val AS direction,
       s.libelle AS service,
       s.code_dr,
       TO_CHAR(paie.matricule) AS matricule,
       paie.idcategorie,
       paie.ctg,
       paie.indicegrade,
       paie.indice_fonctionnel,
       paie.statut,
       c.taux AS categorieval,
       '' AS ctgval,
       paie.numero_cnaps,
       paie.numero_ostie,
       CASE
           WHEN paie.temporaire = -1 THEN 'Temporaire'
           WHEN paie.temporaire = 0 THEN 'Permanent'
           WHEN paie.temporaire = 1 THEN 'Cadre'
           ELSE NULL
           END AS temporaire,
       CAST(NVL(sc.PLUS , 0) AS NUMBER(30, 2)) AS droit ,
       CAST(NVL(sp.CONGEPRIS , 0) AS NUMBER(30, 2)) AS prie,
       CAST(NVL(sc.SOLDE, 0) AS NUMBER(30, 2)) AS resteconge,
       paie.etat,
       l.id AS idpersonnel,
       l.direction AS iddirection,
       dp.id AS idDepartement,
       dp.val AS departementlib,
       qp.id AS idQualification,
       qp.val as qualificationLib,
       CASE
           WHEN paie.etat < 1 THEN 'Debauches'
           WHEN paie.etat = 1 THEN 'A Valider'
           WHEN paie.etat = 11 THEN 'Valides'
           ELSE NULL
           END AS etatLib
FROM log_personnel l
         LEFT JOIN log_service s ON l.service = s.id
         LEFT JOIN paie_info_personnel paie ON paie.id = l.id
         LEFT JOIN sexe sex ON l.sexe = sex.id
         LEFT JOIN log_direction d ON d.id = l.direction
         LEFT JOIN paie_categorie c ON c.id = paie.idcategorie
         LEFT JOIN SOLDECONGEPRIS_PERS sp ON l.id = sp.id
         LEFT JOIN SOLDECONGE_PERS sc ON l.id = sc.idPersonnel
         LEFT JOIN departement dp ON paie.idDepartement = dp.id
         LEFT JOIN QUALIFICATION_PAIE qp ON qp.id = paie.IDQUALIFICATION;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."LOG_PERSONNEL_FIN" ("ID", "PERMIS_CONDUIRE", "CHEMIN_PERMIS", "REMARQUE", "ID_PERS", "NOM", "PRENOM", "DATE_NAISSANCE", "SEXE", "NUMERO_CIN", "DATE_CIN", "DATE_DUPL_CIN", "NATIONALITE", "ADRESSE", "FOKOTANY", "ACTE_NAISSANCE", "DIRECTION", "SERVICE", "CODE_DR", "MATRICULE", "IDCATEGORIE", "CTG", "INDICEGRADE", "INDICE_FONCTIONNEL", "STATUT", "CATEGORIEVAL", "CTGVAL", "NUMERO_CNAPS", "NUMERO_OSTIE", "TEMPORAIRE", "DROIT", "PRIE", "RESTECONGE", "ETAT", "IDPERSONNEL", "IDDIRECTION", "DEPARTEMENTLIB", "IDDEPARTEMENT", "IDQUALIFICATION", "QUALIFICATIONLIB", "IDCATEGORIE_PAIE") AS
SELECT l.id,
       l.permis_conduire,
       l.chemin_permis,
       l.remarque,
       l.id_pers,
       l.nom,
       l.prenom,
       l.date_naissance,
       sex.desce AS sexe,
       l.numero_cin,
       l.date_cin,
       l.date_dupl_cin,
       l.nationalite,
       l.adresse,
       l.fokotany,
       l.acte_naissance,
       d.val AS direction,
       s.code_service AS service,
       s.code_dr,
       TO_CHAR(paie.matricule) AS matricule,
       paie.idcategorie,
       paie.ctg,
       paie.indicegrade,
       paie.indice_fonctionnel,
       paie.statut,
       c.taux AS categorieval,
       '''' AS ctgval,
       paie.numero_cnaps,
       paie.numero_ostie,
       CASE
           WHEN paie.temporaire = -1 THEN 'Temporaire'
           WHEN paie.temporaire = 0 THEN 'Permanent'
           WHEN paie.temporaire = 1 THEN 'Cadre'
           ELSE NULL
           END AS temporaire,
       NVL(dr.conge, 0) AS droit,
       NVL(cg.conge, 0) AS prie,
       NVL(dr.conge, 0) - NVL(cg.conge, 0) AS resteconge,
       paie.etat,
       l.id AS idpersonnel,
       l.direction AS iddirection,
       dp.val as departementLib,
       paie.IDDEPARTEMENT,
       paie.IDQUALIFICATION,
       qp.val AS qualificationLib,
       paie.IDCATEGORIE_PAIE
FROM log_personnel l
         LEFT JOIN log_service s ON l.service = s.id
         LEFT JOIN paie_info_personnel paie ON paie.id = l.id
         LEFT JOIN sexe sex ON l.sexe = sex.id
         LEFT JOIN log_direction d ON d.id = l.direction
         LEFT JOIN paie_categorie c ON c.id = paie.idcategorie
         LEFT JOIN droitdeconge_parpersonne dr ON dr.idpersonnel = l.id
         LEFT JOIN congeprisgroupbypers cg ON cg.idpersonnel = l.id
         LEFT JOIN DEPARTEMENT dp ON dp.id = paie.IDDEPARTEMENT
         LEFT JOIN QUALIFICATION_PAIE qp ON qp.id = paie.IDQUALIFICATION;

