CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."LOG_PERSONNEL_GRAPHE" ("ID", "PERMIS_CONDUIRE", "CHEMIN_PERMIS", "REMARQUE", "ID_PERS", "NOM", "PRENOM", "DATE_NAISSANCE", "SEXE", "NUMERO_CIN", "DATE_CIN", "DATE_DUPL_CIN", "NATIONALITE", "ADRESSE", "FOKOTANY", "ACTE_NAISSANCE", "DIRECTION", "SERVICE", "CODE_DR", "MATRICULE", "IDCATEGORIE", "IDCATEGORIELIB", "INDICEGRADE", "INDICE_FONCTIONNEL", "STATUT", "CATEGORIEVAL", "CTGVAL", "NUMERO_CNAPS", "NUMERO_OSTIE", "TEMPORAIRE", "DROIT", "PRIE", "RESTECONGE", "ETAT", "IDPERSONNEL", "IDDIRECTION", "DEPARTEMENTLIB", "IDDEPARTEMENT") AS
SELECT l.id,
       l.permis_conduire,
