                                     FROM log_personnel_non_valide
                                     WHERE log_personnel_non_valide.etat >= 11));

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."LOG_PERSONNEL_V2" ("ID", "PERMIS_CONDUIRE", "CHEMIN_PERMIS", "REMARQUE", "ID_PERS", "NOM", "PRENOM", "DATE_NAISSANCE", "SEXE", "NUMERO_CIN", "DATE_CIN", "DATE_DUPL_CIN", "NATIONALITE", "ADRESSE", "FOKOTANY", "ACTE_NAISSANCE", "DIRECTION", "SERVICE", "CODE_DR", "MATRICULE", "IDCATEGORIE", "CTG", "INDICEGRADE", "INDICE_FONCTIONNEL", "STATUT", "CATEGORIEVAL", "CTGVAL", "NUMERO_CNAPS", "NUMERO_OSTIE", "TEMPORAIRE", "RESTECONGE", "CATEGORIE", "QUALIFICATION", "IDDIRECTION", "IDDEPARTEMENT", "IDCATEGORIE_PAIE") AS
SELECT lpv.id,
       lpv.permis_conduire,
       lpv.chemin_permis,
       lpv.remarque,
       lpv.id_pers,
       lpv.nom,
       lpv.prenom,
       lpv.date_naissance,
       lpv.sexe,
       lpv.numero_cin,
       lpv.date_cin,
       lpv.date_dupl_cin,
       lpv.nationalite,
       lpv.adresse,
       lpv.fokotany,
       lpv.acte_naissance,
       lpv.direction,
       lpv.service,
       lpv.code_dr,
       lpv.matricule,
       lpv.idcategorie,
       lpv.ctg,
       lpv.indicegrade,
       lpv.indice_fonctionnel,
       lpv.statut,
       lpv.categorieval,
       lpv.ctgval,
       lpv.numero_cnaps,
       lpv.numero_ostie,
       lpv.temporaire,
       lpv.resteconge,
       cpl.val AS categorie,
       qp.val AS qualification,
       lpv.idDIRECTION,
       pinfo.iddepartement,
       pinfo.idcategorie_paie
FROM log_personnel_v lpv
         LEFT JOIN paie_info_personnel pinfo ON pinfo.id = lpv.id
         LEFT JOIN categorie_paie_lib cpl ON cpl.id = pinfo.idcategorie_paie
         LEFT JOIN qualification_paie qp ON qp.id = pinfo.idqualification;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."LOG_PERSONNEL_V2_USER" ("ID", "PERMIS_CONDUIRE", "CHEMIN_PERMIS", "REMARQUE", "ID_PERS", "NOM", "PRENOM", "DATE_NAISSANCE", "SEXE", "NUMERO_CIN", "DATE_CIN", "DATE_DUPL_CIN", "NATIONALITE", "ADRESSE", "FOKOTANY", "ACTE_NAISSANCE", "DIRECTION", "SERVICE", "CODE_DR", "MATRICULE", "IDCATEGORIE", "CTG", "INDICEGRADE", "INDICE_FONCTIONNEL", "STATUT", "CATEGORIEVAL", "CTGVAL", "NUMERO_CNAPS", "NUMERO_OSTIE", "TEMPORAIRE", "RESTECONGE", "CATEGORIE", "QUALIFICATION", "IDDIRECTION", "IDDEPARTEMENT", "IDCATEGORIE_PAIE", "IDUTILISATEUR") AS
Select
    l.ID,l.PERMIS_CONDUIRE,l.CHEMIN_PERMIS,l.REMARQUE,l.ID_PERS,l.NOM,l.PRENOM,l.DATE_NAISSANCE,l.SEXE,l.NUMERO_CIN,l.DATE_CIN,l.DATE_DUPL_CIN,l.NATIONALITE,l.ADRESSE,l.FOKOTANY,l.ACTE_NAISSANCE,l.DIRECTION,l.SERVICE,l.CODE_DR,l.MATRICULE,l.IDCATEGORIE,l.CTG,l.INDICEGRADE,l.INDICE_FONCTIONNEL,l.STATUT,l.CATEGORIEVAL,l.CTGVAL,l.NUMERO_CNAPS,l.NUMERO_OSTIE,l.TEMPORAIRE,l.RESTECONGE,l.CATEGORIE,l.QUALIFICATION,l.IDDIRECTION,l.IDDEPARTEMENT,l.IDCATEGORIE_PAIE,
    up.idUtilisateur as idutilisateur
from log_personnel_v2 l
         JOIN utilisateur_personnel up ON up.idpersonnel=l.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."LOG_PERSONNEL_V_FRAIS_MEDICAUX" ("ID", "PERMIS_CONDUIRE", "CHEMIN_PERMIS", "REMARQUE", "ID_PERS", "NOM", "PRENOM", "DATE_NAISSANCE", "SEXE", "NUMERO_CIN", "DATE_CIN", "DATE_DUPL_CIN", "NATIONALITE", "ADRESSE", "FOKOTANY", "ACTE_NAISSANCE", "DIRECTION", "SERVICE", "CODE_DR", "MATRICULE", "IDCATEGORIE", "CTG", "INDICEGRADE", "INDICE_FONCTIONNEL", "STATUT", "CATEGORIEVAL", "CTGVAL", "NUMERO_CNAPS", "NUMERO_OSTIE", "TEMPORAIRE", "RESTECONGE", "RESTE_FRAIS_MEDICAUX") AS
