CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."LOG_PERSONNE_NON_VALIDE_VUE" ("ID", "PERMIS_CONDUIRE", "CHEMIN_PERMIS", "REMARQUE", "ID_PERS", "NOM", "PRENOM", "DATE_NAISSANCE", "SEXE", "NUMERO_CIN", "DATE_CIN", "DATE_DUPL_CIN", "NATIONALITE", "ADRESSE", "FOKOTANY", "ACTE_NAISSANCE", "DIRECTION", "SERVICE", "CODE_DR", "MATRICULE", "IDCATEGORIE", "CTG", "INDICEGRADE", "INDICE_FONCTIONNEL", "STATUT", "CATEGORIEVAL", "CTGVAL", "NUMERO_CNAPS", "NUMERO_OSTIE", "TEMPORAIRE", "DROIT", "PRIE", "RESTECONGE", "IDDEPARTEMENT", "DEPARTEMENTLIB", "IDQUALIFICATION", "QUALIFICATIONLIB", "ETAT", "ETATLIB") AS
SELECT lpf.id,
