CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."LOG_PERS_NON_VALIDE_LIB" ("ID", "IDLOGPERS", "SEXE", "DATEAPPLICATION", "IDTYPEDEBAUCHE", "ETAT", "IDUSER", "MATRICULE", "DATE_DECISION", "REFDECISION", "ETATLIB") AS
SELECT
	    lpnv.id,
	    lp.nom || ' ' || lp.prenom AS idlogpers,
	    lp.sexe,
	    lpnv.dateapplication,
	    td.val AS idtypedebauche,
	    lpnv.etat,
	    lpnv.iduser,
	    pif.matricule,
	    lpnv.date_decision,
	    lpnv.refdecision,
	    CASE
	        WHEN lpnv.etat = 1 THEN
	            'Cree'
	        WHEN lpnv.etat = 11 THEN
	            'Valide'
	        WHEN lpnv.etat = 0 THEN
	            'Annule'
	        ELSE
	            'Inconnu'
	        END AS etatLib
	FROM log_personnel_non_valide lpnv
	         LEFT JOIN type_depart td
	                   ON td.id = lpnv.idtypedebauche
	         LEFT JOIN paie_info_personnel pif
	                   ON pif.id = lpnv.idlogpers
	         LEFT JOIN log_personnel lp
	                   ON lp.id = lpnv.idlogpers
	WHERE lpnv.date_reintegration IS NULL;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."LOG_PERS_NON_VALIDE_LIB_3" ("ID", "IDLOGPERS", "DATEAPPLICATION", "DATE_DECISION", "IDTYPEDEBAUCHE", "TYPEDEBAUCHE", "REFDECISION", "IDAVANCEMENT", "MOTIF", "SEXE", "ETAT", "PERSONNELID", "MATRICULE") AS
SELECT lpnv.id,
       lp.id AS idlogpers,
       lpnv.dateapplication,
       lpnv.date_decision,
       lpnv.idtypedebauche,
       ddt.val AS typedebauche,
       lpnv.refdecision,
       lpnv.idavancement,
       lpnv.motif,
       lp.sexe,
       lpnv.etat,
       lpnv.idlogpers AS personnelid,
       pif.matricule
FROM log_personnel_non_valide lpnv
         JOIN paie_info_personnel pif ON pif.id = lpnv.idlogpers
         JOIN log_personnel lp ON lpnv.idlogpers = lp.id
         JOIN dec_decision_type ddt ON ddt.id = lpnv.idtypedebauche
WHERE lpnv.date_reintegration IS NULL;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."LOG_PERS_NON_VALIDE_LIB_4" ("ID", "IDLOGPERS", "DATEAPPLICATION", "DATE_DECISION", "IDTYPEDEBAUCHE", "TYPEDEBAUCHE", "REFDECISION", "IDAVANCEMENT", "MOTIF", "SEXE", "ETAT", "PERSONNELID", "MATRICULE") AS
SELECT lpnv.id,
       lp.id AS idlogpers,
       lpnv.dateapplication,
       lpnv.date_decision,
       lpnv.idtypedebauche,
       ddt.val AS typedebauche,
       lpnv.refdecision,
       lpnv.idavancement,
       lpnv.motif,
       lp.sexe,
       lpnv.etat,
       (lp.nom || ' ') || lp.prenom AS personnelid,
       pif.matricule
FROM log_personnel_non_valide lpnv
         JOIN paie_info_personnel pif ON pif.id = lpnv.idlogpers
         JOIN log_personnel lp ON lpnv.idlogpers = lp.id
         JOIN type_depart ddt ON ddt.id = lpnv.idtypedebauche
WHERE lpnv.date_reintegration IS NULL;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."LOG_PERS_NON_VALIDE_LIB_5" ("ID", "IDLOGPERS", "DATEAPPLICATION", "DATE_DECISION", "IDTYPEDEBAUCHE", "TYPEDEBAUCHE", "REFDECISION", "IDAVANCEMENT", "MOTIF", "SEXE", "ETAT", "PERSONNELID", "PASSATIONIB", "MATRICULE", "IDPASSATION") AS
SELECT lpnv.id,
       lp.id AS idlogpers,
       lpnv.dateapplication,
       lpnv.date_decision,
       lpnv.idtypedebauche,
       ddt.val AS typedebauche,
       lpnv.refdecision,
       lpnv.idavancement,
       lpnv.motif,
       lp.sexe,
       lpnv.etat,
       (lp.nom || ' ') || lp.prenom AS personnelid,
       (lp2.nom || ' ') || lp2.prenom AS passationib,
       pif.matricule,
       lpnv.idpassation
FROM log_personnel_non_valide lpnv
         JOIN paie_info_personnel pif ON pif.id = lpnv.idlogpers
         JOIN log_personnel lp ON lpnv.idlogpers = lp.id
         LEFT JOIN log_personnel lp2 ON lpnv.idpassation = lp2.id
         JOIN type_depart ddt ON ddt.id = lpnv.idtypedebauche
