CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."LOG_PERS_NON_VALIDE_LIB_5_TEST" ("ID", "IDLOGPERS", "DATEAPPLICATION", "DATE_DECISION", "IDTYPEDEBAUCHE", "TYPEDEBAUCHE", "REFDECISION", "IDAVANCEMENT", "MOTIF", "SEXE", "ETAT", "PERSONNELID", "PASSATIONIB", "MATRICULE", "IDPASSATION") AS
(
SELECT lpnv.id,
    lp.id AS idlogpers,
