CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."LOG_PERS_NON_VALIDE_LIB_VISE" ("ID", "IDLOGPERS", "SEXE", "DATEAPPLICATION", "IDTYPEDEBAUCHE", "ETAT", "IDUSER", "MATRICULE", "DATE_DECISION", "REFDECISION", "ETATLIB") AS
