CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."LOG_PERS_STC" ("ID", "IDLOGPERS", "DATEAPPLICATION", "DATE_DECISION", "IDTYPEDEBAUCHE", "REFDECISION", "IDAVANCEMENT", "MOTIF", "SEXE", "ETAT", "IDUSER", "MATRICULE") AS
