CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."LOG_SERVICE_CRT" ("ID", "VAL", "DESCE") AS
SELECT log_service.id,
       log_service.code_service AS val,
       log_service.libelle AS desce
FROM log_service;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."LOG_SERVICE_LIB" ("ID", "CODE_DR", "DR_RATTACHE", "LIBELLE", "CODE_SERVICE", "LIBELLEDIRECTION") AS
SELECT
    ls.ID ,
    ls.CODE_DR ,
    ls.DR_RATTACHE ,
    ls.LIBELLE ,
    ls.CODE_SERVICE ,
    ld.val AS libelleDirection

FROM LOG_SERVICE ls
         LEFT JOIN LOG_DIRECTION ld ON ld.id = ls.DR_RATTACHE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."LOG_SERVICE_LIBELLE" ("ID", "LIBELLE", "CODE_DR", "DR_RATTACHE", "CODE_SERVICE") AS
SELECT ls.id,
       ls.libelle,
       sd.val AS code_dr,
       ls.dr_rattache,
       ls.code_service
FROM log_service ls
         LEFT JOIN sig_dr sd ON ls.code_dr = sd.id AND ls.id <> 'SERV00001';

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."LOT_LIB" ("ID", "NOMLOT", "REFERENCE", "DATEECLOSION", "DATEARRIVEE", "SOURCE", "IDFERME", "IDARTICLE", "IDORIGINE", "IDPROGRAMME", "ETAT", "IDFERMELIB", "IDARTICLELIB", "IDORIGINELIB", "IDPROGRAMMELIB", "IDSOUCHELIB", "ETATLIB", "IDCATEGORIELOTLIB", "DATECLOTURE", "AGEJOUR", "AGESEMAINE") AS
SELECT l.ID,l.NOMLOT,l.REFERENCE,l.DATEECLOSION,l.DATEARRIVEE,l.SOURCE,l.IDFERME,l.IDARTICLE,l.IDORIGINE,l.IDPROGRAMME,l.ETAT,
       m.VAL      AS IDFERMELIB,
       ai.LIBELLE AS IDARTICLELIB,
       o.VAL      AS IDORIGINELIB,
       pz.CODE || '-' || pz.IDSOUCHELIB AS IDPROGRAMMELIB,
       s.val AS idsouchelib,
       CASE l.ETAT
           WHEN 1  THEN 'CR&Eacute;&Eacute;'
           WHEN 11 THEN 'VALID&Eacute;'
           WHEN 0  THEN 'ANULL&Eacute;'
           WHEN 17  THEN 'CL&Ocirc;TUR&Eacute;'
           END AS ETATLIB,
       cl.val AS idcategorielotlib,
       l.datecloture AS datecloture,
       TRUNC(SYSDATE) - TRUNC(dateEclosion) + 1 AS ageJour,
       FLOOR((TRUNC(SYSDATE) - TRUNC(dateEclosion) + 1 - 1) / 7) + 1 AS ageSemaine
FROM LOT l
         LEFT JOIN MAGASIN2 m ON m.ID = l.IDFERME
         LEFT JOIN AS_INGREDIENTS ai ON ai.ID = l.IDARTICLE
         LEFT JOIN ORIGINELOT o ON o.ID = l.IDORIGINE
         LEFT JOIN PROGRAMMEZOOTECHNIQUE_LIB pz ON pz.ID = l.IDPROGRAMME
         LEFT JOIN SOUCHE s ON s.id=l.idsouche
         LEFT JOIN CATEGORIELOT cl ON cl.id=l.idcategorielot;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MAGASIN" ("ID", "VAL", "DESCE", "IDPOINT", "IDPRODUIT", "IDTYPEMAGASIN", "ETAT") AS
select p.ID,
    p.VAL,
    p.DESCE,
    p.id as idPoint,
    '-' as idProduit,
    '' as idtypemagasin,
    11 as etat
    from point p;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MAGASIN2_ACTIF" ("ID", "VAL", "DESCE", "IDPOINT", "IDPRODUIT", "IDTYPEMAGASIN", "ETAT", "CAPACITE", "COMPTEUR", "IDMAGASINMERE", "IDLIGNE", "ACTIF") AS
select "ID","VAL","DESCE","IDPOINT","IDPRODUIT","IDTYPEMAGASIN","ETAT","CAPACITE","COMPTEUR","IDMAGASINMERE","IDLIGNE","ACTIF" from magasin2 where ACTIF = 1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MAGASINLIB" ("ID", "VAL", "DESCE", "IDPOINT", "IDPOINTLIB", "IDTYPEMAGASIN", "IDTYPEMAGASINLIB", "IDPRODUIT", "IDPRODUITLIB", "IDLIGNE", "IDLIGNELIB") AS
SELECT
    m.ID ,
    m.VAL ,
    m.DESCE ,
    m.IDPOINT ,
    p.VAL AS IDPOINTLIB,
    m.IDTYPEMAGASIN ,
    t.VAL AS IDTYPEMAGASINLIB,
    m.IDPRODUIT ,
    p2.LIBELLE AS IDPRODUITLIB,
    m.idLigne,
    lig.val as idLigneLib
FROM MAGASIN2 m
         LEFT JOIN POINT p ON p.ID = m.IDPOINT
         LEFT JOIN TYPEMAGASIN t ON t.ID = m.IDTYPEMAGASIN
         LEFT JOIN AS_INGREDIENTS p2 ON p2.ID = m.IDPRODUIT
        LEFT JOIN Ligne lig ON lig.id = m.idLigne;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MAGASINLIBCOMPTA" ("ID", "VAL", "DESCE", "IDPOINT", "IDPOINTLIB", "IDTYPEMAGASIN", "IDTYPEMAGASINLIB", "IDPRODUIT", "IDPRODUITLIB", "COMPTE", "IDMAGASINCOMPTE") AS
SELECT
	    m.ID ,
	    m.VAL ,
	    m.DESCE ,
	    m.IDPOINT ,
	    p.VAL AS IDPOINTLIB,
	    m.IDTYPEMAGASIN ,
	    t.VAL AS IDTYPEMAGASINLIB,
	    m.IDPRODUIT ,
	    p2.LIBELLE AS IDPRODUITLIB,
	    mc.DESCE as compte,
	    mc.id as idMagasincompte
	FROM MAGASIN2 m
	         LEFT JOIN POINT p ON p.ID = m.IDPOINT
	         LEFT JOIN TYPEMAGASIN t ON t.ID = m.IDTYPEMAGASIN
	         LEFT JOIN AS_INGREDIENTS p2 ON p2.ID = m.IDPRODUIT
	         LEFT JOIN magasin_compte mc ON mc.VAL = m.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MAGASINLIB_ILOT" ("ID", "VAL", "DESCE", "IDPOINT", "IDPOINTLIB", "IDTYPEMAGASIN", "IDTYPEMAGASINLIB", "IDPRODUIT", "IDPRODUITLIB") AS
SELECT 
m."ID",m."VAL",m."DESCE",m."IDPOINT",m."IDPOINTLIB",m."IDTYPEMAGASIN",m."IDTYPEMAGASINLIB",m."IDPRODUIT",m."IDPRODUITLIB"
FROM MAGASINLIB m 
WHERE m.IDTYPEMAGASIN = 'TYPMG000023';

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MAGASINPOINT" ("ID", "VAL", "DESCE", "IDPRODUIT", "IDTYPEMAGASIN", "IDPOINT", "ETAT") AS
SELECT
    m.ID AS ID,
    m.VAL,
    m.DESCE,
    m.IDPRODUIT,
    m.IDTYPEMAGASIN,
    m.IDPOINT,
    m.ETAT
FROM MAGASIN2 m where m.ACTIF=1 UNION ALL SELECT
    p.ID AS ID,
    p.VAL,
    p.DESCE,
    NULL AS IDPRODUIT,
    NULL AS IDTYPEMAGASIN,
    p.ID AS IDPOINT,
    11 AS ETAT
FROM POINT p
WHERE p.ACTIF=1 and p.ID NOT IN (
    SELECT m.IDPOINT FROM MAGASIN2 m WHERE m.IDPOINT IS NOT NULL
);

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MAGASINVENTE" ("ID", "VAL", "DESCE", "IDPOINT", "IDPRODUIT", "IDTYPEMAGASIN", "ETAT", "CAPACITE", "COMPTEUR", "IDMAGASINMERE") AS
select "ID","VAL","DESCE","IDPOINT","IDPRODUIT","IDTYPEMAGASIN","ETAT","CAPACITE","COMPTEUR","IDMAGASINMERE" from MAGASIN2 where ACTIF=1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MAGASIN_COMPTE_CPL" ("ID", "VAL", "DESCE", "NOMCOMPTE") AS
select m."ID",m."VAL",m."DESCE", c.LIBELLE as nomCompte
	from MAGASIN_COMPTE m
	         left join COMPTA_COMPTE c on m.DESCE = c.COMPTE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MAGASIN_SANSRESERVOIR" ("ID", "VAL", "DESCE", "IDPOINT", "IDPRODUIT", "IDTYPEMAGASIN") AS
SELECT 
m."ID",m."VAL",m."DESCE",m."IDPOINT",m."IDPRODUIT",m."IDTYPEMAGASIN"
FROM MAGASIN m 
WHERE m.IDTYPEMAGASIN != 'TYPMG000001';

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."METIERLIB" ("ID", "VAL", "DESCE", "IDCODEROME", "IDCODEROMELIB", "IDSOUSFAMILLEPROLIB", "IDFAMILLEPROLIB") AS
SELECT
    m.ID,m.VAL,m.DESCE,m.idcoderome,
    cr.code AS idcoderomelib,
    sfp.val AS idsousfamilleprolib,
    fp.val AS idfamilleprolib
FROM metier m
         LEFT JOIN code_rome cr ON cr.id=m.idcoderome
         LEFT JOIN sous_famille_pro sfp ON sfp.id=cr.idsousfamille
         LEFT JOIN famille_professionnelle fp ON fp.id=sfp.idfamille;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MIRAGEDETAIL_LIB" ("ID", "IDMERE", "IDBATIMENT", "IDPARQUET", "IDQUALITEMIRAGE", "QTE", "REMARQUE", "IDBATIMENTLIB", "IDPARQUETLIB", "IDQUALITEMIRAGELIB") AS
SELECT d."ID",
       d."IDMERE",
       d."IDBATIMENT",
       d."IDPARQUET",
       d."IDQUALITEMIRAGE",
       d."QTE",
       d."REMARQUE",
       b."NOMBATIMENT" AS "IDBATIMENTLIB",
       p."VAL"         AS "IDPARQUETLIB",
       qm."VAL"        AS "IDQUALITEMIRAGELIB"
FROM "MIRAGEDETAIL" d
LEFT JOIN "BATIMENT" b ON b."ID" = d."IDBATIMENT"
LEFT JOIN "PARQUET" p ON p."ID" = d."IDPARQUET"
LEFT JOIN "QUALITEMIRAGE" qm ON qm."ID" = d."IDQUALITEMIRAGE";

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MIRAGE_LIB" ("ID", "DATY", "NOMBREOEUFSINITIAL", "IDMACHINE", "IDMACHINELIB") AS
SELECT m."ID",
       m."DATY",
       m."NOMBREOEUFSINITIAL",
       m."IDMACHINE",
       ma."VAL" AS "IDMACHINELIB"
FROM "MIRAGE" m
LEFT JOIN "MACHINE" ma ON ma."ID" = m."IDMACHINE";

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MISEENINCUBATEURDETAIL_LIB" ("ID", "IDMERE", "IDLOT", "IDBATIMENT", "IDPARQUET", "HEUREDEMARRAGE", "HEUREFIN", "DATEPONTE", "QTE", "POIDSMOYEN", "IDLOTLIB", "IDBATIMENTLIB", "IDPARQUETLIB") AS
SELECT d."ID",
       d."IDMERE",
       d."IDLOT",
       d."IDBATIMENT",
       d."IDPARQUET",
       d."HEUREDEMARRAGE",
       d."HEUREFIN",
       d."DATEPONTE",
       d."QTE",
       d."POIDSMOYEN",
       l."NOMLOT"      AS "IDLOTLIB",
       b."NOMBATIMENT" AS "IDBATIMENTLIB",
       p."VAL"         AS "IDPARQUETLIB"
FROM "MISEENINCUBATEURDETAIL" d
LEFT JOIN "LOT" l ON l."ID" = d."IDLOT"
LEFT JOIN "BATIMENT" b ON b."ID" = d."IDBATIMENT"
LEFT JOIN "PARQUET" p ON p."ID" = d."IDPARQUET";

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MISEENINCUBATEUR_LIB" ("ID", "DATEMISEENMACHINE", "DATEECLOSIONPREVUE", "IDINCUBATEUR", "IDRESPONSABLE", "TEMPERATEURCIBLE", "HUMIDITECIBLE", "HEUREPRECHAUFFAGE", "HEUREDEBUTINCUBATION", "IDINCUBATEURLIB", "IDRESPONSABLELIB") AS
SELECT m."ID",
       m."DATEMISEENMACHINE",
       m."DATEECLOSIONPREVUE",
       m."IDINCUBATEUR",
       m."IDRESPONSABLE",
       m."TEMPERATEURCIBLE",
       m."HUMIDITECIBLE",
       m."HEUREPRECHAUFFAGE",
       m."HEUREDEBUTINCUBATION",
       inc."VAL"                       AS "IDINCUBATEURLIB",
       resp."NOM" || ' ' || resp."PRENOM" AS "IDRESPONSABLELIB"
FROM "MISEENINCUBATEUR" m
LEFT JOIN "INCUBATEUR" inc ON inc."ID" = m."IDINCUBATEUR"
LEFT JOIN "LOG_PERSONNEL" resp ON resp."ID" = m."IDRESPONSABLE";

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MODEPAIEMENTMAJ" ("ID", "VAL", "DESCE") AS
select id, upper(val) as val, upper(desce) as desce from MODEPAIEMENT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MONTANTAPAYER" ("MONTANTAPAYER", "IDFACTUREFOURNISSEUR", "IDORIGINE") AS
SELECT 
 	sum(DEBIT) AS montantapayer,
 	f.id AS idfacturefournisseur,
 	m.IDORIGINE AS IDORIGINE 
 FROM MOUVEMENTCAISSE m 
 LEFT JOIN FACTUREFOURNISSEUR f ON m.IDORIGINE =f.ID 
 GROUP BY f.ID , m.IDORIGINE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MONTANTCAISSE" ("CAISSELIB", "IDCAISSE", "MONTANTTHEORIQUE", "MONTANT", "DATEDERNIERREPORT", "EXPLICATION", "IDCLOTURE") AS
SELECT
    etatcaisse.idcaisseLib AS caisselib,
    etatcaisse.idcaisse,
    CAST(ROUND(etatcaisse.reste, 0) AS NUMBER(30,0)) AS montantTheorique,
    0 AS montant,
    etatcaisse.dateDernierReport AS dateDernierReport,
    '' AS explication,
    '' AS idcloture
FROM V_ETATCAISSE_CLOTURE etatcaisse
WHERE TRUNC(etatcaisse.dateDernierReport) <= TRUNC(SYSDATE);

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MONTANTENCAISSEMENT" ("IDENCAISSEMENT", "IDORIGINE", "MONTANTTOTALENCAISSEMENT") AS
SELECT 
ed.IDENCAISSEMENT ,
ed.IDORIGINE,
sum( nvl( ed.MONTANT ,0 ) ) AS montantTotalEncaissement
FROM ENCAISSEMENT_DETAILS ed 
GROUP BY ed.IDENCAISSEMENT,ed.IDORIGINE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MONTANTPRECISIONENCAISSEMENT" ("IDENCAISSEMENT", "IDCATEGORIECAISSE", "MONTANTTOTALPRECISION") AS
SELECT 
pde.IDENCAISSEMENT ,
pde.IDCATEGORIECAISSE ,
sum( nvl(pde.MONTANT , 0) ) AS montantTotalPrecision 
FROM PRECISION_DETAIL_ENCAISSEMENT pde 
GROUP BY pde.IDENCAISSEMENT , pde.IDCATEGORIECAISSE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MONTANT_STOCK" ("IDPRODUIT", "ENTREE", "SORTIE", "QUANTITE", "MONTANTENTREE", "MONTANTSORTIE", "MONTANT", "IDMAGASIN") AS
SELECT
    mf.IDPRODUIT,
    SUM(NVL(mf.ENTREE,0)) AS ENTREE,
    SUM(NVL(mf.SORTIE,0)) AS SORTIE,
    SUM(NVL(mf.ENTREE,0)) - SUM(NVL(mf.SORTIE,0)) AS quantite,
    cast(sum(mf.montantEntree) as number(30,2))  AS montantEntree,
    cast(sum(mf.montantSortie) as number(30,2))  AS montantSortie,
    CAST(NVL(ai.PU, 0) * (SUM(NVL(mf.ENTREE,0)) - SUM(NVL(mf.SORTIE,0))) AS NUMBER(30,2)) AS montant,
    m.IDMAGASIN
FROM
    mvtStockFilleMontant mf
        JOIN MVTSTOCK m ON m.id = mf.IDMVTSTOCK
        JOIN AS_INGREDIENTS ai ON ai.ID = mf.IDPRODUIT
WHERE
    m.ETAT >= 11
  AND mf.IDPRODUIT IS NOT NULL
GROUP BY
    mf.IDPRODUIT,
    ai.PU,m.IDMAGASIN;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MONTANT_STOCK_ENG" ("IDPRODUIT", "ENTREE", "SORTIE", "QUANTITE", "MONTANTENTREE", "MONTANTSORTIE", "MONTANT", "IDMAGASIN", "IDMVTSTOCK") AS
SELECT
    mf.IDPRODUIT,
    SUM(NVL(mf.ENTREE,0)) AS ENTREE,
    SUM(NVL(mf.SORTIE,0)) AS SORTIE,
    SUM(NVL(mf.ENTREE,0)) - SUM(NVL(mf.SORTIE,0)) AS quantite,
    cast(sum(mf.montantEntree) as number(30,2))  AS montantEntree,
    cast(sum(mf.montantSortie) as number(30,2))  AS montantSortie,
    CAST(NVL(ai.PU, 0) * (SUM(NVL(mf.ENTREE,0)) - SUM(NVL(mf.SORTIE,0))) AS NUMBER(30,2)) AS montant,
    m.IDMAGASIN,
    MAX(mf.IDMVTSTOCK) AS IDMVTSTOCK
FROM
    mvtStockFilleMontant_eng mf
        JOIN MVTstock_eng m ON m.id = mf.IDMVTSTOCK
        JOIN AS_INGREDIENTS ai ON ai.ID = mf.IDPRODUIT
WHERE
    m.ETAT >= 11
  AND mf.IDPRODUIT IS NOT NULL
GROUP BY
    mf.IDPRODUIT,
    ai.PU,m.IDMAGASIN;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MONTANT_TRAITE_FC" ("ID", "IDTRAITE", "MONTANTTRAITE") AS
select
    ID,IDTRAITE,
    sum(montant) AS montanttraite
from TRAITE_FC
GROUP BY ID,IDTRAITE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MOTRAVAUXLIB" ("ID", "IDPERSONNEL", "IDTRAVAUX", "DUREEESTIMATIF", "TAUXHORAIRE", "DUREEESTIMATIFLIB", "MONTANT", "IDPERSONNELLIB") AS
SELECT
    mo."ID",mo."IDPERSONNEL",mo."IDTRAVAUX",mo."DUREEESTIMATIF",mo."TAUXHORAIRE",
    LPAD(FLOOR(TO_NUMBER(mo.DUREEESTIMATIF) / 3600), 2, '0') || ':' ||
    LPAD(FLOOR(MOD(TO_NUMBER(mo.DUREEESTIMATIF), 3600) / 60), 2, '0') || ':' ||
    LPAD(MOD(TO_NUMBER(mo.DUREEESTIMATIF), 60), 2, '0')
                                               AS dureeEstimatifLib,
    ((mo.DUREEESTIMATIF/60)/60)*mo.TAUXHORAIRE AS montant,
    p.NOM AS idPersonnelLib
FROM MOTRAVAUX mo
         LEFT JOIN PERSONNEL p ON p.ID = mo.IDPERSONNEL;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MOUVEMENTCAISSEAUTOCOMPLETE" ("ID", "DESIGNATION", "IDCAISSE", "IDVENTEDETAIL", "IDVIREMENT", "DATY", "ETAT", "IDOP", "IDORIGINE", "IDDEVISE", "IDTIERS", "COMPTE", "IDPREVISION", "IDTRAITE", "ETATVERSEMENT", "IDMODEPAIEMENT", "IDMVTCAISSEMERE", "REFERENCE", "UPDATED_AT", "DATYCOMPTABILISATION", "ACQUEREUR", "IDTYPEPAIEMENT", "DEBIT", "CREDIT", "TAUX", "HEURE", "IDREPORT", "IDCAISSIER", "MONTANTRETOURNER") AS
SELECT
    mc.ID,
    mc.DESIGNATION,
    mc.IDCAISSE,
    mc.IDVENTEDETAIL,
    mc.IDVIREMENT,
    mc.DATY,
    mc.ETAT,
    mc.IDOP,
    mc.IDORIGINE,
    mc.IDDEVISE,
    CASE
        WHEN mc.IDTIERS IS NOT NULL
            THEN mc.IDTIERS||'---'||c.nom
        END AS IDTIERS,
    mc.COMPTE,
    CASE
        WHEN mc.IDPREVISION IS NOT NULL
            THEN mc.IDPREVISION||'---'||p.designation
        END AS IDPREVISION,
    mc.IDTRAITE,
    mc.ETATVERSEMENT,
    mc.IDMODEPAIEMENT,
    mc.IDMVTCAISSEMERE,
    mc.REFERENCE,
    mc.UPDATED_AT,
    mc.DATYCOMPTABILISATION,
    mc.ACQUEREUR,
    mc.IDTYPEPAIEMENT,
    mc.DEBIT,
    mc.CREDIT,
    mc.TAUX,
    mc.HEURE,
    mc.idReport,
    mc.idCaissier,
    mc.montantRetourner
FROM mouvementcaisse mc
     LEFT JOIN CLIENT c ON c.id=mc.IDTIERS
     LEFT JOIN prevision p ON p.id=mc.IDPREVISION;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MOUVEMENTCAISSEAVECHEURE" ("ID", "DESIGNATION", "IDCAISSE", "IDVENTEDETAIL", "IDVIREMENT", "DATY", "ETAT", "IDOP", "IDORIGINE", "IDDEVISE", "IDTIERS", "COMPTE", "IDPREVISION", "IDTRAITE", "ETATVERSEMENT", "IDMODEPAIEMENT", "IDMVTCAISSEMERE", "REFERENCE", "UPDATED_AT", "DATYCOMPTABILISATION", "ACQUEREUR", "IDTYPEPAIEMENT", "DEBIT", "CREDIT", "TAUX", "HEURE", "IDREPORT") AS
SELECT
    m.ID,
    m.DESIGNATION,
    m.IDCAISSE,
    m.IDVENTEDETAIL,
    m.IDVIREMENT,
    CASE
        WHEN m.HEURE IS NOT NULL AND m.HEURE != '00:00:00'
        THEN m.DATY + (TO_NUMBER(SUBSTR(m.HEURE, 1, 2)) / 24)
                   + (TO_NUMBER(SUBSTR(m.HEURE, 4, 2)) / 1440)
                   + (TO_NUMBER(SUBSTR(m.HEURE, 7, 2)) / 86400)
        ELSE m.DATY
    END AS DATY,
    m.ETAT,
    m.IDOP,
    m.IDORIGINE,
    m.IDDEVISE,
    m.IDTIERS,
    m.COMPTE,
    m.IDPREVISION,
    m.IDTRAITE,
    m.ETATVERSEMENT,
    m.IDMODEPAIEMENT,
    m.IDMVTCAISSEMERE,
    m.REFERENCE,
    m.UPDATED_AT,
    m.DATYCOMPTABILISATION,
    m.ACQUEREUR,
    m.IDTYPEPAIEMENT,
    m.DEBIT,
    m.CREDIT,
    m.TAUX,
    m.HEURE,
    m.idReport
FROM MOUVEMENTCAISSE m;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MOUVEMENTCAISSECPL" ("ID", "DESIGNATION", "IDCAISSE", "IDCAISSELIB", "IDVENTEDETAIL", "IDVIREMENT", "DEBIT", "CREDIT", "SOLDECREDIT", "SOLDEDEBIT", "DATY", "ETAT", "ETATLIB", "IDVENTE", "IDORIGINE", "IDTIERS", "TIERS", "IDPREVISION", "IDOP", "TAUX", "COMPTE", "IDDEVISE", "IDTRAITE", "IDMODEPAIEMENTLIB", "IDMVTCAISSEMERE", "REFERENCE", "DATYCOMPTABILISATION", "UPDATED_AT", "HEURE", "IDREPORT", "MOTSCLESSS", "IDECRITURE", "IDBC") AS
SELECT m.ID,
       m.DESIGNATION,
       m.IDCAISSE,
       c.VAL   AS IDCAISSELIB,
       m.IDVENTEDETAIL,
       m.IDVIREMENT,
       m.DEBIT,
       m.CREDIT,
       CAST(
               CASE
                   WHEN m.credit > 0 THEN NVL(m.CREDIT, 0) - NVL(l.MONTANT, 0)
                   ELSE 0
                   END AS NUMBER(36,5)
       ) AS soldecredit,
       CAST(
               CASE
                   WHEN m.debit > 0 THEN NVL(m.DEBIT, 0) - NVL(l.MONTANT, 0)
                   ELSE 0
                   END AS NUMBER(36,5)
       ) AS soldedebit,
       m.DATY,
       m.ETAT,
       CASE
           WHEN m.ETAT = 0
               THEN 'ANNUL&Eacute;E'
           WHEN m.ETAT = 1
               THEN 'CR&Eacute;&Eacute;E'
           WHEN m.ETAT = 11
               THEN 'VALID&Eacute;E'
           WHEN m.ETAT = 8
               THEN '&Agrave; COMPTABILISER'
           END AS ETATLIB,
       vd.IDVENTE,
       m.IDORIGINE as idorigine,
       m.idtiers,
       t.NOM AS tiers,
       m.idPrevision,
       m.idOP,
       m.taux,
       m.COMPTE,
       m.IDDEVISE,
       m.idtraite,
       mp.VAL as idModePaiementLib,
       m.idmvtcaissemere,
       m.reference,
       m.datycomptabilisation,
       m.UPDATED_AT, m.heure,
       m.IDREPORT,
       m.ID || '' || m.DATY || '' || m.DESIGNATION || '' || t.NOM || '' || m.IDCAISSE || '' || c.VAL AS MOTSCLESS,
       ce.id as idecriture,
       m.IDBC
FROM MOUVEMENTCAISSE m
         LEFT JOIN CAISSE c ON c.ID = m.IDCAISSE
         LEFT JOIN VENTE_DETAILS vd ON vd.ID = m.IDVENTEDETAIL
         LEFT JOIN tiers t ON t.ID = m.idtiers
         left join liaisonpaiementmvtcaissegrp l on l.idmvtcaisse=m.id
         left join modepaiement mp on m.idmodepaiement = mp.id
         left join COMPTA_ECRITURE ce on ce.IDOBJET=m.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MOUVEMENTCAISSECPL_A" ("ID", "DESIGNATION", "IDCAISSE", "IDCAISSELIB", "IDVENTEDETAIL", "IDVIREMENT", "DEBIT", "CREDIT", "DATY", "ETAT", "ETATLIB", "IDVENTE", "IDORIGINE", "IDTIERS", "TIERS", "MOTSCLESSS") AS
SELECT
	    ID,DESIGNATION,IDCAISSE,IDCAISSELIB,IDVENTEDETAIL,IDVIREMENT,DEBIT,CREDIT,DATY,ETAT,ETATLIB,IDVENTE,IDORIGINE,IDTIERS,TIERS,MOTSCLESSS
	FROM
	    MOUVEMENTCAISSECPL m
	WHERE
	        m.etat = 8;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MOUVEMENTCAISSECPL_ANNULE" ("ID", "DESIGNATION", "IDCAISSE", "IDCAISSELIB", "IDVENTEDETAIL", "IDVIREMENT", "DEBIT", "CREDIT", "DATY", "ETAT", "ETATLIB", "IDVENTE", "IDORIGINE", "IDTIERS", "TIERS") AS
SELECT
			ID,DESIGNATION,IDCAISSE,IDCAISSELIB,IDVENTEDETAIL,IDVIREMENT,DEBIT,CREDIT,DATY,ETAT,ETATLIB,IDVENTE,IDORIGINE,IDTIERS,TIERS
		FROM 
			MOUVEMENTCAISSECPL m 
		WHERE 
			m.etat = 0;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MOUVEMENTCAISSECPL_A_VALIDER" ("ID", "DESIGNATION", "IDCAISSE", "IDCAISSELIB", "IDVENTEDETAIL", "IDVIREMENT", "DEBIT", "CREDIT", "DATY", "ETAT", "ETATLIB", "IDVENTE", "IDORIGINE", "IDTIERS", "TIERS", "DATYCOMPTABILISATION") AS
SELECT
    ID,DESIGNATION,IDCAISSE,IDCAISSELIB,IDVENTEDETAIL,IDVIREMENT,DEBIT,CREDIT,DATY,ETAT,ETATLIB,IDVENTE,IDORIGINE,IDTIERS,TIERS,DATYCOMPTABILISATION
FROM
    MOUVEMENTCAISSECPL m
WHERE
    etat > 7 and ETAT < 11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MOUVEMENTCAISSECPL_CREE" ("ID", "DESIGNATION", "IDCAISSE", "IDCAISSELIB", "IDVENTEDETAIL", "IDVIREMENT", "DEBIT", "CREDIT", "DATY", "ETAT", "ETATLIB", "IDVENTE", "IDORIGINE", "IDTIERS", "TIERS", "MOTSCLESSS") AS
SELECT
			ID,DESIGNATION,IDCAISSE,IDCAISSELIB,IDVENTEDETAIL,IDVIREMENT,DEBIT,CREDIT,DATY,ETAT,ETATLIB,IDVENTE,IDORIGINE,IDTIERS,TIERS,MOTSCLESSS
		FROM 
			MOUVEMENTCAISSECPL m 
		WHERE 
			m.etat = 1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MOUVEMENTCAISSECPL_NATTACH" ("ID", "DESIGNATION", "IDCAISSE", "IDCAISSELIB", "IDVENTEDETAIL", "IDVIREMENT", "DEBIT", "CREDIT", "DATY", "ETAT", "ETATLIB", "IDVENTE", "IDORIGINE", "IDTIERS", "TIERS", "IDPREVISION", "IDOP", "TAUX", "COMPTE", "IDDEVISE") AS
SELECT "ID","DESIGNATION","IDCAISSE","IDCAISSELIB","IDVENTEDETAIL","IDVIREMENT","DEBIT","CREDIT","DATY","ETAT","ETATLIB","IDVENTE","IDORIGINE","IDTIERS","TIERS","IDPREVISION","IDOP","TAUX","COMPTE","IDDEVISE" FROM MOUVEMENTCAISSECPL m  
WHERE NOT EXISTS (SELECT mvp.id FROM MVTCAISSEPREVISION mvp WHERE mvp.id1=m.id) AND m.ETAT >=11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MOUVEMENTCAISSECPL_VALIDER" ("ID", "DESIGNATION", "IDCAISSE", "IDCAISSELIB", "IDVENTEDETAIL", "IDVIREMENT", "DEBIT", "CREDIT", "DATY", "ETAT", "ETATLIB", "IDVENTE", "IDORIGINE", "IDTIERS", "TIERS", "MOTSCLESSS") AS
SELECT SQ.ID,SQ.DESIGNATION,SQ.IDCAISSE,SQ.IDCAISSELIB,SQ.IDVENTEDETAIL,SQ.IDVIREMENT,SQ.DEBIT,SQ.CREDIT,SQ.DATY,SQ.ETAT,SQ.ETATLIB,SQ.IDVENTE,SQ.IDORIGINE,SQ.IDTIERS,SQ.TIERS,
	       (NVL(TO_CHAR(ID),'') || ' | ' || NVL(TO_CHAR(DESIGNATION),'') || ' | ' || NVL(TO_CHAR(IDCAISSE),'') || ' | ' || NVL(TO_CHAR(IDCAISSELIB),'') || ' | ' || NVL(TO_CHAR(IDVENTEDETAIL),'') || ' | ' || NVL(TO_CHAR(IDVIREMENT),'') || ' | ' || NVL(TO_CHAR(DEBIT),'') || ' | ' || NVL(TO_CHAR(CREDIT),'') || ' | ' || NVL(TO_CHAR(DATY,'YYYY-MM-DD HH24:MI:SS'),'') || ' | ' || NVL(TO_CHAR(ETAT),'') || ' | ' || NVL(TO_CHAR(ETATLIB),'') || ' | ' || NVL(TO_CHAR(IDVENTE),'') || ' | ' || NVL(TO_CHAR(IDORIGINE),'') || ' | ' || NVL(TO_CHAR(IDTIERS),'') || ' | ' || NVL(TO_CHAR(TIERS),'')) AS MOTSCLESSS
	FROM (
	         SELECT
	             ID,DESIGNATION,IDCAISSE,IDCAISSELIB,IDVENTEDETAIL,IDVIREMENT,DEBIT,CREDIT,DATY,ETAT,ETATLIB,IDVENTE,IDORIGINE,IDTIERS,TIERS
	         FROM
	             MOUVEMENTCAISSECPL m
	         WHERE
	                 m.etat = 11
	
	     ) SQ;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MOUVEMENTCAISSECPL_V_DISPATCH" ("ID", "DESIGNATION", "IDCAISSE", "IDCAISSELIB", "IDVENTEDETAIL", "IDVIREMENT", "DEBIT", "CREDIT", "MONTANTIMPUTE", "DATY", "ETAT", "ETATLIB", "IDVENTE", "IDORIGINE", "IDTIERS", "TIERS", "IDPAIEMENT", "REFERENCEPAIEMENT", "DESIGNATIONPAIEMENT") AS
SELECT m.ID,
       DESIGNATION,
       IDCAISSE,
       IDCAISSELIB,
       IDVENTEDETAIL,
       IDVIREMENT,
       DEBIT,
       CREDIT,
       lp.MONTANT as montantimpute,
       DATY,
       m.ETAT,
       ETATLIB,
       IDVENTE,
       id2 as IDORIGINE,
       IDTIERS,
       TIERS,
       id1 as idpaiement,
       m.REFERENCE as referencepaiement,
       m.DESIGNATION as designationpaiement
FROM LIAISONPAIEMENT lp LEFT JOIN
    MOUVEMENTCAISSECPL m on m.id = lp.ID1
WHERE m.etat > 7;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MOUVEMENTCAISSECPL_V_D_AVOIR" ("ID", "DESIGNATION", "IDCAISSE", "IDCAISSELIB", "IDVENTEDETAIL", "IDVIREMENT", "DEBIT", "CREDIT", "MONTANTIMPUTE", "DATY", "ETAT", "ETATLIB", "IDVENTE", "IDORIGINE", "IDTIERS", "TIERS", "IDPAIEMENT", "REFERENCEPAIEMENT", "DESIGNATIONPAIEMENT") AS
SELECT m.ID,
       DESIGNATION,
       IDCAISSE,
       IDCAISSELIB,
       IDVENTEDETAIL,
       IDVIREMENT,
       DEBIT,
       CREDIT,
       lp.MONTANT as montantimpute,
       DATY,
       m.ETAT,
       ETATLIB,
       IDVENTE,
       id2 as IDORIGINE,
       IDTIERS,
       TIERS,
       id1 as idpaiement,
       m.REFERENCE as referencepaiement,
       m.DESIGNATION as designationpaiement
FROM LIAISONPAIEMENT lp LEFT JOIN
    MOUVEMENTCAISSECPL m on m.id = lp.ID1
WHERE m.etat > 7
UNION ALL
SELECT m.ID,
       m.DESIGNATION,
       '' as IDCAISSE,
       '' as IDCAISSELIB,
       '' as IDVENTEDETAIL,
       '' as IDVIREMENT,
       0 as DEBIT,
       m.MONTANTTTCAR as CREDIT,
       lp.MONTANT as montantimpute,
       DATY,
       m.ETAT,
       '' as ETATLIB,
       IDVENTE,
       id2 as IDORIGINE,
       m.IDCLIENT as IDTIERS,
       m.CLIENTLIB as TIERS,
       id1 as idpaiement,
       m.id as referencepaiement,
       'NOTE DE CREDIT'as designationpaiement
FROM LIAISONPAIEMENT lp LEFT JOIN
    AVOIRFCLIB_CPL m on m.id = lp.ID1
WHERE m.etat > 7;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MOUVEMENTCAISSEFILLECPL" ("ID", "DESIGNATION", "IDCAISSE", "IDVENTEDETAIL", "IDVIREMENT", "DATY", "ETAT", "IDOP", "IDORIGINE", "IDDEVISE", "IDTIERS", "COMPTE", "IDPREVISION", "IDTRAITE", "ETATVERSEMENT", "IDMODEPAIEMENT", "IDMVTCAISSEMERE", "REFERENCE", "UPDATED_AT", "DATYCOMPTABILISATION", "ACQUEREUR", "IDTYPEPAIEMENT", "DEBIT", "CREDIT", "TAUX", "HEURE", "IDREPORT", "IDCAISSIER", "MONTANTRETOURNER", "IDCAISSELIB") AS
select m."ID",m."DESIGNATION",m."IDCAISSE",m."IDVENTEDETAIL",m."IDVIREMENT",m."DATY",m."ETAT",m."IDOP",m."IDORIGINE",m."IDDEVISE",m."IDTIERS",m."COMPTE",m."IDPREVISION",m."IDTRAITE",m."ETATVERSEMENT",m."IDMODEPAIEMENT",m."IDMVTCAISSEMERE",m."REFERENCE",m."UPDATED_AT",m."DATYCOMPTABILISATION",m."ACQUEREUR",m."IDTYPEPAIEMENT",m."DEBIT",m."CREDIT",m."TAUX",m."HEURE",m."IDREPORT",m."IDCAISSIER",m."MONTANTRETOURNER", c.VAL as idCaisseLib from mouvementcaisse m
left join caisse c on m.IDCAISSE = c.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MOUVEMENTCAISSEGROUPEFACTURE" ("IDORIGINE", "CREDIT", "DEBIT", "IDDEVISE") AS
select idorigine, sum(credit) as credit,sum(debit) as debit, C.IDDEVISE from mouvementcaisse m
LEFT JOIN caisse c on  c.id=idcaisse
  where m.etat>=11 and idorigine is not null
group by idorigine,c.iddevise;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MOUVEMENTCAISSEGROUPERESA" ("IDORIGINE", "CREDIT", "DEBIT", "IDDEVISE") AS
select m.idop as idorigine, sum(credit) as credit,sum(debit) as debit, C.IDDEVISE from mouvementcaisse m
LEFT JOIN caisse c on  c.id=idcaisse
  where m.etat>=11 and idop is not null
group by m.idop,c.iddevise;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MOUVEMENTCAISSEGRPAVOIR_LP" ("IDORIGINE", "MONTANT", "IDDEVISE") AS
select m.id1 as idorigine, sum(montant) as montant, 'AR' as IDDEVISE
from LIAISONPAIEMENT m
where m.etat >= 11
  and id1 is not null
group by m.id1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MOUVEMENTCAISSEMERELIB" ("ID", "DESIGNATION", "IDMODEPAIEMENT", "CREDIT", "DEBIT", "IDTIERS", "IDORIGINE", "DATY", "ETAT", "IDMODEPAIEMENTLIB", "IDTIERSLIB", "ETATLIB") AS
SELECT
    m."ID",m."DESIGNATION",m."IDMODEPAIEMENT",m."CREDIT",m."DEBIT",m."IDTIERS",m."IDORIGINE",m."DATY",m."ETAT",
    mp.VAL AS idmodepaiementlib,
    c.NOM AS idtierslib,
    CASE
        WHEN m.ETAT = 1 THEN 'CREEE'
        WHEN m.ETAT = 11 THEN 'VISEE'
        WHEN m.ETAT = 0 THEN 'ANNULEE'
        END AS etatlib
FROM mouvementcaissemere m
         LEFT JOIN MODEPAIEMENT mp ON mp.id = m.idmodepaiement
         LEFT JOIN CLIENT c ON c.id = m.idtiers;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MOUVEMENTCAISSE_DETAIL" ("ID", "DESIGNATION", "IDMAGASIN", "IDMAGASINLIB", "DATY", "REMARQUE", "ETAT", "ETATLIB", "MONTANTTOTAL", "IDDEVISE", "IDCLIENT", "IDCLIENTLIB", "MONTANTTVA", "MONTANTTTC", "MONTANTTTCAR", "MONTANTPAYE", "MONTANTRESTE", "AVOIR", "TAUXDECHANGE", "MONTANTREVIENT", "MARGEBRUTE", "IDRESERVATION", "IDOBJET", "MONTANTIMPUTE", "REFERENCEPAIEMENT", "IDPAIEMENT", "DESIGNATIONPAIEMENT", "NUMEROFACTURE", "UPDATED_AT") AS
select v.ID,
       v.DESIGNATION,
       v.IDMAGASIN,
       v.IDMAGASINLIB,
       v.DATY,
       v.REMARQUE,
       v.ETAT,
       v.ETATLIB,
       v.MONTANTTOTAL,
       v.IDDEVISE,
       v.IDCLIENT,
       v.IDCLIENTLIB,
       v.MONTANTTVA,
       v.MONTANTTTC,
       v.MONTANTTTCAR,
       v.MONTANTPAYE,
       v.MONTANTRESTE,
       v.AVOIR,
       v.TAUXDECHANGE,
       v.MONTANTREVIENT,
       v.MARGEBRUTE,
       v.IDRESERVATION,
       mv.id as idobjet,
       mv.montantimpute,
       referencepaiement,
       idpaiement,
       designationpaiement,
       v.NUMEROFACTURE,
       v.UPDATED_AT
from VENTE_CPL v
         left join MOUVEMENTCAISSECPL_V_D_avoir mv on v.id = mv.idorigine;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MOUVEMENTCAISSE_DETAIL_UNIQUE" ("ID", "DESIGNATION", "IDMAGASIN", "IDMAGASINLIB", "DATY", "REMARQUE", "ETAT", "ETATLIB", "MONTANTTOTAL", "IDDEVISE", "IDCLIENT", "IDCLIENTLIB", "MONTANTTVA", "MONTANTTTC", "MONTANTTTCAR", "MONTANTPAYE", "MONTANTRESTE", "AVOIR", "TAUXDECHANGE", "MONTANTREVIENT", "MARGEBRUTE", "IDRESERVATION", "NUMEROFACTURE", "UPDATED_AT", "TOTALIMPUTE", "REFERENCES_PAIEMENT") AS
SELECT
    v.ID,
    v.DESIGNATION,
    v.IDMAGASIN,
    v.IDMAGASINLIB,
    v.DATY,
    v.REMARQUE,
    v.ETAT,
    v.ETATLIB,
    v.MONTANTTOTAL,
    v.IDDEVISE,
    v.IDCLIENT,
    v.IDCLIENTLIB,
    v.MONTANTTVA,
    v.MONTANTTTC,
    v.MONTANTTTCAR,
    v.MONTANTPAYE,
    v.MONTANTRESTE,
    v.AVOIR,
    v.TAUXDECHANGE,
    v.MONTANTREVIENT,
    v.MARGEBRUTE,
    v.IDRESERVATION,
    v.NUMEROFACTURE,
    v.UPDATED_AT,
    -- ? Somme des montants imputes
    SUM(v.montantimpute) AS TOTALIMPUTE,
    -- ? Concatenation des references paiement (separees par //)
    LISTAGG(v.designationpaiement ||' '|| v.referencepaiement, ' // ') WITHIN GROUP (ORDER BY v.designationpaiement || v.referencepaiement) AS REFERENCES_PAIEMENT
FROM MOUVEMENTCAISSE_DETAIL v
GROUP BY
    v.ID,
    v.DESIGNATION,
    v.IDMAGASIN,
    v.IDMAGASINLIB,
    v.DATY,
    v.REMARQUE,
    v.ETAT,
    v.ETATLIB,
    v.MONTANTTOTAL,
    v.IDDEVISE,
    v.IDCLIENT,
    v.IDCLIENTLIB,
    v.MONTANTTVA,
    v.MONTANTTTC,
    v.MONTANTTTCAR,
    v.MONTANTPAYE,
    v.MONTANTRESTE,
    v.AVOIR,
    v.TAUXDECHANGE,
    v.MONTANTREVIENT,
    v.MARGEBRUTE,
    v.IDRESERVATION, v.NUMEROFACTURE, v.UPDATED_AT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MOUVEMENTCAISSE_VISE" ("ID", "DESIGNATION", "IDCAISSE", "IDVENTEDETAIL", "IDVIREMENT", "DEBIT", "CREDIT", "DATY", "ETAT", "IDOP", "IDORIGINE", "IDDEVISE", "TAUX", "IDTIERS", "COMPTE", "IDPREVISION", "IDTRAITE", "ETATVERSEMENT", "IDMODEPAIEMENT", "IDMVTCAISSEMERE", "REFERENCE") AS
select "ID","DESIGNATION","IDCAISSE","IDVENTEDETAIL","IDVIREMENT","DEBIT","CREDIT","DATY","ETAT","IDOP","IDORIGINE","IDDEVISE","TAUX","IDTIERS","COMPTE","IDPREVISION","IDTRAITE","ETATVERSEMENT","IDMODEPAIEMENT","IDMVTCAISSEMERE","REFERENCE" from MOUVEMENTCAISSE
WHERE ETAT=11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MOYENNEPANNESTRAVAUX" ("IDMACHINE", "NOMMACHINE", "ECARTJOURS") AS
SELECT
    idMachine,
    nomMachine,
    cast (ROUND(AVG(ECART_JOURS), 2) as number(10,2)) AS ECARTJOURS
FROM TempsMoyenPannes
WHERE ECART_JOURS IS NOT NULL
GROUP BY idMachine, nomMachine;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MOYENNETRAVAUXMACHINE" ("IDMACHINE", "NOMMACHINE", "MOYENNEDUREEESTIMATIF", "MOYENNEDUREE", "MOYENNEECART") AS
SELECT
    d.IDMACHINE,
    d.NOMMACHINE ,
    CAST (AVG(d.DUREEESTIMATIF) AS NUMBER(10, 2)) AS moyenneDureeEstimatif,
    CAST (AVG(d.DUREE) AS NUMBER(10, 2)) AS moyenneDuree,
    CAST (AVG(d.ECART) AS NUMBER(10, 2)) as moyenneEcart
FROM DUREETRAVAUXMACHINE d
GROUP BY d.IDMACHINE, d.NOMMACHINE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MTBFDETAIL" ("ID", "IDMACHINE", "IDMACHINELIB", "DATY", "ECART") AS
select
    otf.id,
    otf.IDINGREDIENTS as idMachine,
    ai.LIBELLE as idMachineLib,
    ot.DATY,
    nvl(
            ot.DATY - lead(ot.DATY) over (
                partition by otf.IDINGREDIENTS
                order by ot.DATY desc
                ),
            0
    ) as ecart
from ORDRETRAVAUX ot
         left join ORDRETRAVAUXFILLE otf
                   on otf.IDMERE = ot.ID
         left join AS_INGREDIENT_MAINTENANCE ai
                   on ai.ID = otf.IDINGREDIENTS;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTCAISSECPLORIGINE" ("ID", "DESIGNATION", "IDCAISSE", "IDCAISSELIB", "IDVENTEDETAIL", "IDVIREMENT", "DEBIT", "CREDIT", "SOLDECREDIT", "SOLDEDEBIT", "DATY", "ETAT", "ETATLIB", "IDVENTE", "IDORIGINE", "IDTIERS", "TIERS", "IDPREVISION", "IDOP", "TAUX", "COMPTE", "IDDEVISE", "IDTRAITE", "IDMODEPAIEMENTLIB", "IDMVTCAISSEMERE", "REFERENCE", "DATYCOMPTABILISATION", "UPDATED_AT", "HEURE", "IDREPORT", "MOTSCLESS", "IDECRITURE") AS
SELECT m.ID,
       m.DESIGNATION,
       m.IDCAISSE,
       c.VAL   AS IDCAISSELIB,
       m.IDVENTEDETAIL,
       m.IDVIREMENT,
       m.DEBIT,
       m.CREDIT,
       CAST(
               CASE
                   WHEN m.credit > 0 THEN NVL(m.CREDIT, 0) - NVL(l.MONTANT, 0)
                   ELSE 0
                   END AS NUMBER(36,5)
       ) AS soldecredit,
       CAST(
               CASE
                   WHEN m.debit > 0 THEN NVL(m.DEBIT, 0) - NVL(l.MONTANT, 0)
                   ELSE 0
                   END AS NUMBER(36,5)
       ) AS soldedebit,
       m.DATY,
       m.ETAT,
       CASE
           WHEN m.ETAT = 0
               THEN 'ANNULEE'
           WHEN m.ETAT = 1
               THEN 'CREEE'
           WHEN m.ETAT = 11
               THEN 'VALIDEE'
           WHEN m.ETAT = 8
               THEN 'A COMPTABILISER'
           END AS ETATLIB,
       vd.IDVENTE,
       lp.ID2 as idorigine,
       m.idtiers,
       t.NOM AS tiers,
       m.idPrevision,
       m.idOP,
       m.taux,
       m.COMPTE,
       m.IDDEVISE,
       m.idtraite,
       mp.VAL as idModePaiementLib,
       m.idmvtcaissemere,
       m.reference,
       m.datycomptabilisation,
       m.UPDATED_AT, m.heure,
       m.IDREPORT,
       m.ID || '' || m.DATY || '' || m.DESIGNATION || '' || t.NOM || '' || m.IDCAISSE || '' || c.VAL AS MOTSCLESS,
       cr.id as idecriture
FROM MOUVEMENTCAISSE m
         LEFT JOIN CAISSE c ON c.ID = m.IDCAISSE
         LEFT JOIN VENTE_DETAILS vd ON vd.ID = m.IDVENTEDETAIL
         LEFT JOIN tiers t ON t.ID = m.idtiers
         left join liaisonpaiementmvtcaissegrp l on l.idmvtcaisse=m.id
         left join modepaiement mp on m.idmodepaiement = mp.id
         LEFT JOIN COMPTA_ECRITURE cr on cr.IDOBJET=m.id
         JOIN LIAISONPAIEMENT lp ON lp.ID1 = m.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTCAISSECPLORIGINE_A" ("ID", "DESIGNATION", "IDCAISSE", "IDCAISSELIB", "IDVENTEDETAIL", "IDVIREMENT", "DEBIT", "CREDIT", "SOLDECREDIT", "SOLDEDEBIT", "DATY", "ETAT", "ETATLIB", "IDVENTE", "IDORIGINE", "IDTIERS", "TIERS", "IDPREVISION", "IDOP", "TAUX", "COMPTE", "IDDEVISE", "IDTRAITE", "IDMODEPAIEMENTLIB", "IDMVTCAISSEMERE", "REFERENCE", "DATYCOMPTABILISATION", "UPDATED_AT", "HEURE", "IDREPORT", "MOTSCLESS", "IDECRITURE") AS
select m."ID",m."DESIGNATION",m."IDCAISSE",m."IDCAISSELIB",m."IDVENTEDETAIL",m."IDVIREMENT",m."DEBIT",m."CREDIT",m."SOLDECREDIT",m."SOLDEDEBIT",m."DATY",m."ETAT",m."ETATLIB",m."IDVENTE",m."IDORIGINE",m."IDTIERS",m."TIERS",m."IDPREVISION",m."IDOP",m."TAUX",m."COMPTE",m."IDDEVISE",m."IDTRAITE",m."IDMODEPAIEMENTLIB",m."IDMVTCAISSEMERE",m."REFERENCE",m."DATYCOMPTABILISATION",m."UPDATED_AT",m."HEURE",m."IDREPORT",m."MOTSCLESS",m."IDECRITURE" from MVTCAISSECPLORIGINE m where m.etat = 8;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTCAISSECPLORIGINE_ANNULE" ("ID", "DESIGNATION", "IDCAISSE", "IDCAISSELIB", "IDVENTEDETAIL", "IDVIREMENT", "DEBIT", "CREDIT", "SOLDECREDIT", "SOLDEDEBIT", "DATY", "ETAT", "ETATLIB", "IDVENTE", "IDORIGINE", "IDTIERS", "TIERS", "IDPREVISION", "IDOP", "TAUX", "COMPTE", "IDDEVISE", "IDTRAITE", "IDMODEPAIEMENTLIB", "IDMVTCAISSEMERE", "REFERENCE", "DATYCOMPTABILISATION", "UPDATED_AT", "HEURE", "IDREPORT", "MOTSCLESS", "IDECRITURE") AS
select m."ID",m."DESIGNATION",m."IDCAISSE",m."IDCAISSELIB",m."IDVENTEDETAIL",m."IDVIREMENT",m."DEBIT",m."CREDIT",m."SOLDECREDIT",m."SOLDEDEBIT",m."DATY",m."ETAT",m."ETATLIB",m."IDVENTE",m."IDORIGINE",m."IDTIERS",m."TIERS",m."IDPREVISION",m."IDOP",m."TAUX",m."COMPTE",m."IDDEVISE",m."IDTRAITE",m."IDMODEPAIEMENTLIB",m."IDMVTCAISSEMERE",m."REFERENCE",m."DATYCOMPTABILISATION",m."UPDATED_AT",m."HEURE",m."IDREPORT",m."MOTSCLESS",m."IDECRITURE" from MVTCAISSECPLORIGINE m where m.etat = 0;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTCAISSECPLORIGINE_CREER" ("ID", "DESIGNATION", "IDCAISSE", "IDCAISSELIB", "IDVENTEDETAIL", "IDVIREMENT", "DEBIT", "CREDIT", "SOLDECREDIT", "SOLDEDEBIT", "DATY", "ETAT", "ETATLIB", "IDVENTE", "IDORIGINE", "IDTIERS", "TIERS", "IDPREVISION", "IDOP", "TAUX", "COMPTE", "IDDEVISE", "IDTRAITE", "IDMODEPAIEMENTLIB", "IDMVTCAISSEMERE", "REFERENCE", "DATYCOMPTABILISATION", "UPDATED_AT", "HEURE", "IDREPORT", "MOTSCLESS", "IDECRITURE") AS
select m."ID",m."DESIGNATION",m."IDCAISSE",m."IDCAISSELIB",m."IDVENTEDETAIL",m."IDVIREMENT",m."DEBIT",m."CREDIT",m."SOLDECREDIT",m."SOLDEDEBIT",m."DATY",m."ETAT",m."ETATLIB",m."IDVENTE",m."IDORIGINE",m."IDTIERS",m."TIERS",m."IDPREVISION",m."IDOP",m."TAUX",m."COMPTE",m."IDDEVISE",m."IDTRAITE",m."IDMODEPAIEMENTLIB",m."IDMVTCAISSEMERE",m."REFERENCE",m."DATYCOMPTABILISATION",m."UPDATED_AT",m."HEURE",m."IDREPORT",m."MOTSCLESS",m."IDECRITURE" from MVTCAISSECPLORIGINE m where m.etat = 1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTCAISSECPLORIGINE_VALIDER" ("ID", "DESIGNATION", "IDCAISSE", "IDCAISSELIB", "IDVENTEDETAIL", "IDVIREMENT", "DEBIT", "CREDIT", "SOLDECREDIT", "SOLDEDEBIT", "DATY", "ETAT", "ETATLIB", "IDVENTE", "IDORIGINE", "IDTIERS", "TIERS", "IDPREVISION", "IDOP", "TAUX", "COMPTE", "IDDEVISE", "IDTRAITE", "IDMODEPAIEMENTLIB", "IDMVTCAISSEMERE", "REFERENCE", "DATYCOMPTABILISATION", "UPDATED_AT", "HEURE", "IDREPORT", "MOTSCLESS", "IDECRITURE") AS
select m."ID",m."DESIGNATION",m."IDCAISSE",m."IDCAISSELIB",m."IDVENTEDETAIL",m."IDVIREMENT",m."DEBIT",m."CREDIT",m."SOLDECREDIT",m."SOLDEDEBIT",m."DATY",m."ETAT",m."ETATLIB",m."IDVENTE",m."IDORIGINE",m."IDTIERS",m."TIERS",m."IDPREVISION",m."IDOP",m."TAUX",m."COMPTE",m."IDDEVISE",m."IDTRAITE",m."IDMODEPAIEMENTLIB",m."IDMVTCAISSEMERE",m."REFERENCE",m."DATYCOMPTABILISATION",m."UPDATED_AT",m."HEURE",m."IDREPORT",m."MOTSCLESS",m."IDECRITURE" from MVTCAISSECPLORIGINE m where m.etat = 11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTCAISSEGROUPEFACTURE_PDF" ("IDORIGINE", "DEBIT", "CREDIT", "MONTANTRETOURNER", "IDDEVISE") AS
select id2 AS idorigine, sum(l.MONTANT ) as debit, sum(m.credit) as credit, sum(m.montantretourner) as montantretourner, c.IDDEVISE
from LIAISONPAIEMENT l
         left join MOUVEMENTCAISSE m on m.id = l.id1
         left join caisse c on c.ID = m.idcaisse
where l.etat >= 11
  and id1 is not NULL
group BY id2, c.IDDEVISE, m.montantretourner;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTCAISSEGROUPPREVISIONSOM" ("ID", "ID1", "ID2", "ETAT", "REMARQUE", "MONTANTMERE", "MONTANTCREDIT", "TAUX", "DEVISE") AS
SELECT '-' AS id, id1,'' AS id2,etat,'-' AS remarque,sum(montantMere) AS montantMere,sum(montantCredit) AS montantCredit,nvl(max(taux),1) AS taux,devise 
FROM MVTCAISSEPREVISIONVise GROUP BY id1,etat,devise;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTCAISSEPREVISIONVISE" ("ID", "ID1", "ID2", "MONTANTMERE", "ETAT", "REMARQUE", "MONTANTCREDIT", "DEVISE", "TAUX") AS
select "ID","ID1","ID2","MONTANTMERE","ETAT","REMARQUE","MONTANTCREDIT","DEVISE","TAUX" from MVTCAISSEPREVISION where etat>=1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTCAISSESOMPREVISIONGROUP" ("ID", "ID1", "ID2", "ETAT", "REMARQUE", "MONTANTMERE", "MONTANTCREDIT", "TAUX", "DEVISE") AS
SELECT '-' AS id, '' AS id1,id2,etat,'-' AS remarque,sum(montantMere) AS montantMere,sum(montantCredit) AS montantCredit,nvl(max(taux),1) AS taux,devise  
FROM MVTCAISSEPREVISIONVise GROUP BY id2,etat,devise;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTCONGEBYMOISANNEE" ("IDPERSONNEL", "PLUS", "MOIS", "ANNEE") AS
SELECT
    m.IDPERSONNEL,
    SUM(m.PLUS) AS plus,
    m.MOIS,
    m.ANNEE
FROM MOUVEMENTABSENCE m
GROUP BY m.IDPERSONNEL, m.MOIS, m.ANNEE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTINTRACAISSETRAITE" ("ID", "DATY", "CAISSEDEPART", "CAISSEARRIVEE", "MONTANT", "MODEPAIEMENT", "REMARQUE", "ETAT", "DESIGNATION", "IDTRAITE", "ETATVERSEMENT", "IDFINALEDESTINATION", "DATETRAITE", "DATEECHEANCE", "MONTANTTRAITE") AS
select
    mit.ID,mit.DATY,mit.CAISSEDEPART,mit.CAISSEARRIVEE,mit.MONTANT,mit.MODEPAIEMENT,mit.REMARQUE,mit.ETAT,mit.DESIGNATION,mit.IDTRAITE,mit.ETATVERSEMENT,mit.IDFINALEDESTINATION,
    t.daty as datetraite,
    t.dateecheance,
    t.montant as montanttraite
from MvtIntraCaisse mit
         left join Traite t on t.id = mit.idtraite;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTINTRACAISSETRAITENONVERSEE" ("ID", "DATY", "CAISSEDEPART", "CAISSEARRIVEE", "MONTANT", "MODEPAIEMENT", "REMARQUE", "ETAT", "DESIGNATION", "IDTRAITE", "ETATVERSEMENT", "IDFINALEDESTINATION", "DATEECHEANCE") AS
SELECT
    mic.ID,mic.DATY,mic.CAISSEDEPART,mic.CAISSEARRIVEE,mic.MONTANT,mic.MODEPAIEMENT,mic.REMARQUE,mic.ETAT,mic.DESIGNATION,mic.IDTRAITE,mic.ETATVERSEMENT,mic.IDFINALEDESTINATION,
    t.DATEECHEANCE
from mvtintracaisse mic
         JOIN traite t on t.id = mic.idtraite;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTINTRACAISSETRAITEV" ("ID", "DATY", "CAISSEDEPART", "CAISSEARRIVEE", "MONTANT", "MODEPAIEMENT", "REMARQUE", "ETAT", "DESIGNATION", "IDTRAITE", "ETATVERSEMENT", "IDFINALEDESTINATION", "DATEECHEANCE", "REFERENCE", "TIERS", "CODECLIENT", "CAISSEDEPARTLIB", "CAISSEARRIVEELIB", "MODEPAIEMENTLIB", "ETATLIB", "ETATVERSEMENTLIB", "FINALEDESTINATIONLIB", "FACTURE") AS
SELECT
    mic.ID,mic.DATY,mic.CAISSEDEPART,mic.CAISSEARRIVEE,mic.MONTANT,mic.MODEPAIEMENT,mic.REMARQUE,mic.ETAT,mic.DESIGNATION,mic.IDTRAITE,mic.ETATVERSEMENT,mic.IDFINALEDESTINATION,
    t.Dateecheance,t.reference,t.tiers,t.CDCLT AS codeclient,
    c1.val AS caissedepartlib,
    c2.val AS caissearriveelib,
    m.Desce as modepaiementlib,
    case
        when mic.etat = 1 then 'CREE'
        when mic.etat >= 11 then 'VISE'
        else '' end                           as etatlib,
    case
        when mic.etatversement = -2 then 'encaissee'
        when mic.etatversement = 11 then 'versee'
        else '' end                           as etatversementlib,
    c3.val AS finaledestinationlib,
    grp.code AS facture
from mvtintracaisse mic
         JOIN traite_lib t on t.id = mic.idtraite
         LEFT JOIN CAISSE C1 on C1.id = mic.caissedepart
         LEFT JOIN CAISSE C2 on C2.id = mic.caissearrivee
         LEFT JOIN caisse C3 ON c3.id= mic.IDFINALEDESTINATION
         LEFT JOIN MODEPAIEMENT m on m.id = mic.modepaiement
         LEFT JOIN TRAITELIB_GRP grp ON mic.IDTRAITE = grp.idTraite
where mic.etatversement = 11 AND mic.IDTRAITE NOT IN (SELECT IDTRAITE FROM mvtintracaisse WHERE ETATVERSEMENT  = -2);

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTINTRACAISSETRAITEVCAISSE" ("ID", "DATY", "CAISSEDEPART", "CAISSEARRIVEE", "MONTANT", "MODEPAIEMENT", "REMARQUE", "ETAT", "DESIGNATION", "IDTRAITE", "ETATVERSEMENT", "IDFINALEDESTINATION", "DATEECHEANCE") AS
SELECT
    mic.ID,
    mic.DATY,
    mic.CAISSEDEPART,
    mic.CAISSEARRIVEE,
    CAST(mic.MONTANT AS NUMBER(30,2)) AS MONTANT,
    mic.MODEPAIEMENT,
    mic.REMARQUE,
    mic.ETAT,
    mic.DESIGNATION,
    mic.IDTRAITE,
    mic.ETATVERSEMENT,
    mic.IDFINALEDESTINATION,
    t.DATEECHEANCE
FROM
    mvtintracaisse mic
        JOIN traite t ON
        t.id = mic.idtraite
WHERE
    mic.etatversement IN (11, -2);

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTINTRACAISSE_LIB" ("ID", "DATY", "CAISSEDEPARTLIB", "CAISSEARRIVEELIB", "CAISSEDEPART", "CAISSEARRIVEE", "MONTANT", "MODEPAIEMENT", "REMARQUE", "ETAT", "DESIGNATION") AS
select mv.id,
       daty,
       mv.CAISSEDEPART  as caissedepartlib,
       mv.CAISSEARRIVEE as caissearriveelib,
       ca.VAL as caissedepart,
       ca1.VAL as caissearrivee,
       montant,
       mp.VAL as modepaiement,
       remarque,
       etat ,
       mv.designation
from mvtintracaisse mv
         left join CAISSE ca on ca.id=mv.caissedepart
         left join CAISSE ca1 on ca1.id=mv.caissearrivee
         left join MODEPAIEMENT mp on mp.id=mv.modepaiement;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTINTRACAISSE_LIBCOMPLET" ("ID", "DATY", "CAISSEDEPART", "CAISSEARRIVEE", "MONTANT", "MODEPAIEMENT", "REMARQUE", "ETAT", "CAISSEDEPARTLIB", "CAISSEARRIVEELIB", "MODEPAIEMENTLIB") AS
select mv.ID,mv.DATY,mv.CAISSEDEPART,mv.CAISSEARRIVEE,mv.MONTANT,mv.MODEPAIEMENT,mv.REMARQUE,mv.ETAT,
       ca.VAL  as caissedepartlib,
       ca1.VAL as caissearriveelib,
       mp.VAL  as modepaiementlib
from mvtintracaisse mv
         left join CAISSE ca on ca.id = mv.caissedepart
         left join CAISSE ca1 on ca1.id = mv.caissearrivee
         left join MODEPAIEMENT mp on mp.id = mv.modepaiement;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTINTRACAISSE_LIB_CREE" ("ID", "DATY", "CAISSEDEPART", "CAISSEARRIVEE", "MONTANT", "MODEPAIEMENT", "REMARQUE", "ETAT") AS
select ID,DATY,CAISSEDEPART,CAISSEARRIVEE,MONTANT,MODEPAIEMENT,REMARQUE,ETAT
from mvtintracaisse_lib
where ETAT=1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTINTRACAISSE_LIB_VISEE" ("ID", "DATY", "CAISSEDEPART", "CAISSEARRIVEE", "MONTANT", "MODEPAIEMENT", "REMARQUE", "ETAT") AS
select ID,DATY,CAISSEDEPART,CAISSEARRIVEE,MONTANT,MODEPAIEMENT,REMARQUE,ETAT
from mvtintracaisse_lib
where ETAT=11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTSTFILLEFABCATVISEGROUPE" ("IDFAB", "ENTREE", "SORTIE", "MONTANT", "IDPRODUIT", "CATEGORIEINGREDIENT", "LIBELLE") AS
select idfab,cast(sum(ENTREE) as number(30,2)) as entree,cast(sum(sortie) as number(30,2)) as sortie,
           cast(sum(nvl(pu*ENTREE,0)) as number(30,2)) as montant, IDPRODUIT,CATEGORIEINGREDIENT,LIBELLE
    from MVTSTOCKFILLEFABOFCATVISE
    group by idfab,IDPRODUIT,CATEGORIEINGREDIENT,LIBELLE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTSTFILLEOFCATVISEGROUPE" ("IDOF", "ENTREE", "SORTIE", "MONTANT", "IDPRODUIT", "CATEGORIEINGREDIENT", "LIBELLE") AS
select idOf,cast(sum(ENTREE) as number(30,2)) as entree,cast(sum(sortie) as number(30,2)) as sortie,
    cast(sum(nvl(pu*ENTREE,0)) as number(30,2)) as montant     ,IDPRODUIT,CATEGORIEINGREDIENT,LIBELLE
    from MVTSTOCKFILLEFABOFCATVISE
    group by idOf,IDPRODUIT,CATEGORIEINGREDIENT,LIBELLE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTSTFILLEOFFCATVISEGROUPE" ("IDOFF", "ENTREE", "SORTIE", "MONTANT", "MONTANTSORTIE", "PV") AS
select m.idoff,cast(sum(m.ENTREE) as number(30,2)) as entree,cast(sum(m.sortie) as number(30,2)) as sortie,
           sum(m.montantEntree) as montant,sum(m.montantSortie) as montantSortie, cast(avg(m.pv) as number(30,2)) as pv
    from MVTSTOCKFILLEFABOFCATVISE m
    group by m.idoff;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTSTFILLEOFFCATVISEGROUPEDEP" ("IDOFF", "ENTREE", "SORTIE", "MONTANT", "MONTANTSORTIE", "PV") AS
select nvl(m.idoff,c.idoff) as idoff,m.entree,m.sortie,m.montant,cast (nvl(m.montantSortie,0)+nvl(c.montantsortie,0) as number(30,2)) as montantsortie,m.pv from MVTSTFILLEOFFCATVISEGROUPE m full outer join chargeGroupByOff c on m.idoff=c.idoff;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTSTOCKAUTOCOMPLETE" ("ID", "DESIGNATION", "IDMAGASIN", "IDVENTE", "IDTRANSFERT", "IDTYPEMVSTOCK", "DATY", "ETAT", "IDPOINT", "IDOBJET", "FABPRECEDENT", "IDCATEGORIESTOCK") AS
SELECT
m.ID,
m.DESIGNATION,
m.IDMAGASIN,
m.IDVENTE,
m.IDTRANSFERT,
m.IDTYPEMVSTOCK,
m.DATY,
m.ETAT,
m.IDPOINT,
m.IDOBJET,
CASE 
	WHEN m.FABPRECEDENT IS NOT NULL 
	THEN m.FABPRECEDENT||'---'||f.LIBELLE 
	ELSE m.FABPRECEDENT
END AS FABPRECEDENT,
m.IDCATEGORIESTOCK
FROM MVTSTOCK m 
LEFT JOIN FABRICATION f ON f.id = m.FABPRECEDENT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTSTOCKDATEHEURE" ("ID", "DESIGNATION", "IDMAGASIN", "IDVENTE", "IDTRANSFERT", "IDTYPEMVSTOCK", "DATY", "ETAT", "IDPOINT", "IDOBJET", "FABPRECEDENT", "IDCATEGORIESTOCK", "HEURE") AS
select m.ID, DESIGNATION, IDMAGASIN, IDVENTE, IDTRANSFERT, IDTYPEMVSTOCK, TO_DATE(TO_CHAR(m.DATY, 'YYYY-MM-DD') || ' ' || NVL(m.HEURE, '00:00:00'), 'YYYY-MM-DD HH24:MI:SS') as DATY, ETAT, IDPOINT, IDOBJET, FABPRECEDENT, IDCATEGORIESTOCK, HEURE from MVTSTOCK m;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTSTOCKENTREEAVECRESTE" ("ID", "IDMVTSTOCK", "IDPRODUIT", "ENTREE", "SORTIE", "IDVENTEDETAIL", "IDTRANSFERTDETAIL", "PU", "MVTSRC", "DATY", "RESTE", "QUANTITE", "IDMAGASIN", "IDINVENTAIREFILLE", "IDOBJET", "IDTRANSFERT") AS
SELECT
	m.ID,
	m.IDMVTSTOCK,
	m.IDPRODUIT,
	m.ENTREE,
	s.SORTIE,
	m.IDVENTEDETAIL,
	m.IDTRANSFERTDETAIL,
	m.PU,
	m.MVTSRC,
	mp.DATY,
	NVL(m.entree,0)- NVL(s.sortie, 0) AS reste,
	NVL(m.entree,0)- NVL(s.sortie, 0) AS quantite,
	--ity no reste miasa any
 mp.IDMAGASIN,
 m.IDINVENTAIREFILLE,
 mp.IDOBJET,
 mp.IDTRANSFERT
FROM
	MVTSTOCKFILLE m
LEFT JOIN MVTSTOCK mp ON
	mp.id = m.IDMVTSTOCK
LEFT JOIN sortieEntree s ON
	s.MVTSRC = m.id 
WHERE
	m.ENTREE >0
	AND mp.ETAT >= 11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTSTOCKENTREEAVECRESTE2" ("ID", "IDMVTSTOCK", "IDPRODUIT", "ENTREE", "SORTIE", "IDVENTEDETAIL", "IDTRANSFERTDETAIL", "PU", "MVTSRC", "DATY", "RESTE", "QUANTITE", "IDMAGASIN") AS
SELECT
	"ID","IDMVTSTOCK","IDPRODUIT","ENTREE","SORTIE","IDVENTEDETAIL","IDTRANSFERTDETAIL","PU","MVTSRC","DATY","RESTE","QUANTITE","IDMAGASIN"
FROM
	MVTSTOCKENTREEAVECRESTE
WHERE
	QUANTITE >0;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTSTOCKENTREEAVECRESTEGROUPE" ("IDINGREDIENT", "QUANTITE") AS
SELECT 
m.IDPRODUIT AS idingredient,
sum(nvl(m.reste,m.ENTREE)) AS quantite
FROM MVTSTOCKFILLE m 
LEFT JOIN MVTSTOCK mp ON mp.id = m.IDMVTSTOCK
WHERE m.ENTREE > 0
GROUP BY m.IDPRODUIT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTSTOCKFILLEAUTOCOMPLETE" ("ID", "IDMVTSTOCK", "IDPRODUIT", "IDVENTEDETAIL", "IDTRANSFERTDETAIL", "MVTSRC", "DESIGNATION", "ENTREE", "SORTIE", "PU", "RESTE", "IDINVENTAIREFILLE", "DATEINVENTAIRE", "QTEINVENTAIRE") AS
SELECT 
m.ID,
m.IDMVTSTOCK,
CASE 
	WHEN m.IDPRODUIT IS NOT NULL 
	THEN m.IDPRODUIT||'---'||a.libelle 
END AS IDPRODUIT,
m.IDVENTEDETAIL,
m.IDTRANSFERTDETAIL,
m.MVTSRC,
m.DESIGNATION,
m.ENTREE,
m.SORTIE,
m.PU,
m.RESTE,
m.IDINVENTAIREFILLE,
m.DATEINVENTAIRE,
m.QTEINVENTAIRE
FROM MVTSTOCKFILLE m 
LEFT JOIN AS_INGREDIENTS a ON a.id = m.IDPRODUIT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTSTOCKFILLEAVECSOURCE" ("ID", "IDMVTSTOCK", "IDPRODUIT", "IDVENTEDETAIL", "IDTRANSFERTDETAIL", "MVTSRC", "DESIGNATION", "ENTREE", "SORTIE", "PU", "RESTE") AS
select mf.ID,
    mf.IDMVTSTOCK,
    mf.IDPRODUIT,
    mf.IDVENTEDETAIL ,
    mf.IDTRANSFERTDETAIL,
    nvl(mf.MVTSRC,mf.id) as MVTSRC,
    mf.DESIGNATION,
    mf.ENTREE,
    mf.SORTIE,
    mf.PU,
    mf.RESTE
    from MVTSTOCKFILLE mf;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTSTOCKFILLECPTSTOCK" ("ID", "IDMVTSTOCK", "IDPRODUIT", "IDVENTEDETAIL", "IDTRANSFERTDETAIL", "MVTSRC", "DESIGNATION", "ENTREE", "SORTIE", "PU", "RESTE", "IDINVENTAIREFILLE", "DATEINVENTAIRE", "QTEINVENTAIRE", "COMPTE_STOCK", "COMPTE_SORTIE_STOCK") AS
select msf."ID",msf."IDMVTSTOCK",msf."IDPRODUIT",msf."IDVENTEDETAIL",msf."IDTRANSFERTDETAIL",msf."MVTSRC",msf."DESIGNATION",msf."ENTREE",msf."SORTIE",msf."PU",msf."RESTE",msf."IDINVENTAIREFILLE",msf."DATEINVENTAIRE",msf."QTEINVENTAIRE",ing.COMPTE_STOCK,ing.COMPTE_SORTIE_STOCK from MVTSTOCKFILLE msf left join AS_INGREDIENTS ing on ing.id=msf.IDPRODUIT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTSTOCKFILLEENTREEFAB" ("ID", "IDMVTSTOCK", "IDPRODUIT", "IDPRODUITLIB", "ENTREE", "SORTIE", "IDVENTEDETAIL", "IDTRANSFERTDETAIL", "PU", "MVTSRC", "RESTE", "DESIGNATION", "IDFAB") AS
select st.ID,st.IDMVTSTOCK,st.IDPRODUIT,ai.LIBELLE AS IDPRODUITLIB,st.ENTREE,st.SORTIE,st.IDVENTEDETAIL,st.IDTRANSFERTDETAIL,st.PU,st.MVTSRC,st.RESTE,st.DESIGNATION,st.IDFAB 
from MVTSTOCKFILLEFAB st
LEFT JOIN AS_INGREDIENTS ai
ON st.IDPRODUIT = ai.id
WHERE st.SORTIE <= 0;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTSTOCKFILLEFAB" ("ID", "IDMVTSTOCK", "IDPRODUIT", "ENTREE", "SORTIE", "IDVENTEDETAIL", "IDTRANSFERTDETAIL", "PU", "MVTSRC", "RESTE", "DESIGNATION", "IDFAB") AS
select st."ID",st."IDMVTSTOCK",st."IDPRODUIT",st."ENTREE",st."SORTIE",st."IDVENTEDETAIL",st."IDTRANSFERTDETAIL",st."PU",st."MVTSRC",st."RESTE",st."DESIGNATION",m.IDOBJET as idFab from MVTSTOCKFILLE st left join MVTSTOCK m on st.IDMVTSTOCK=m.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTSTOCKFILLEFABOFCATVISE" ("ID", "IDMVTSTOCK", "IDPRODUIT", "ENTREE", "SORTIE", "IDVENTEDETAIL", "IDTRANSFERTDETAIL", "PU", "MVTSRC", "RESTE", "DESIGNATION", "IDFAB", "CATEGORIEINGREDIENT", "IDOF", "LIBELLE", "IDOFF", "PV", "MONTANTENTREE", "MONTANTSORTIE") AS
select m."ID",m."IDMVTSTOCK",m."IDPRODUIT",m."ENTREE",m."SORTIE",m."IDVENTEDETAIL",m."IDTRANSFERTDETAIL",m."PU",m."MVTSRC",m."RESTE",m."DESIGNATION",m."IDFAB",cat.VAL as CATEGORIEINGREDIENT,fille.IDMERE as idOf,ing.LIBELLE,fille.id as idoff,ing.pv, cast(nvl(m.ENTREE*m.PU,0) as number(30,2)) as montantEntree ,cast(nvl(m.sortie*m.PU,0) as number(30,2)) as montantSortie
    from MVTSTOCKFILLEFABVISE m left join AS_INGREDIENTS ing on m.IDPRODUIT=ing.ID
left join CATEGORIEINGREDIENT cat on ing.CATEGORIEINGREDIENT=cat.id
left join fabrication fab on m.IDFAB=fab.id
left join OFFILLE fille on fab.IDOFFILLE=fille.ID
where ing.COMPOSE=0;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTSTOCKFILLEFABOFCATVISETOUS" ("ID", "IDMVTSTOCK", "IDPRODUIT", "ENTREE", "SORTIE", "IDVENTEDETAIL", "IDTRANSFERTDETAIL", "PU", "MVTSRC", "RESTE", "DESIGNATION", "IDFAB", "CATEGORIEINGREDIENT", "IDOF", "LIBELLE", "IDOFF", "PV", "MONTANTENTREE", "MONTANTSORTIE") AS
select m."ID",m."IDMVTSTOCK",m."IDPRODUIT",m."ENTREE",m."SORTIE",m."IDVENTEDETAIL",m."IDTRANSFERTDETAIL",m."PU",m."MVTSRC",m."RESTE",m."DESIGNATION",m."IDFAB",cat.VAL as CATEGORIEINGREDIENT,fille.IDMERE as idOf,ing.LIBELLE,fille.id as idoff,ing.pv, cast(nvl(m.ENTREE*m.PU,0) as number(30,2)) as montantEntree ,cast(nvl(m.sortie*m.PU,0) as number(30,2)) as montantSortie
    from MVTSTOCKFILLEFABVISE m left join AS_INGREDIENTS ing on m.IDPRODUIT=ing.ID
left join CATEGORIEINGREDIENT cat on ing.CATEGORIEINGREDIENT=cat.id
left join fabrication fab on m.IDFAB=fab.id
left join OFFILLE fille on fab.IDOFFILLE=fille.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTSTOCKFILLEFABVISE" ("ID", "IDMVTSTOCK", "IDPRODUIT", "ENTREE", "SORTIE", "IDVENTEDETAIL", "IDTRANSFERTDETAIL", "PU", "MVTSRC", "RESTE", "DESIGNATION", "IDFAB") AS
select st."ID",st."IDMVTSTOCK",st."IDPRODUIT",st."ENTREE",st."SORTIE",st."IDVENTEDETAIL",st."IDTRANSFERTDETAIL",st."PU",st."MVTSRC",st."RESTE",st."DESIGNATION",m.IDOBJET as idFab
from MVTSTOCKFILLE st left join MVTSTOCK m on st.IDMVTSTOCK=m.ID  where m.etat>=11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTSTOCKFILLEGROUPEMERE" ("IDMVTSTOCK", "MONTANTENTREE", "MONTANTSORTIE") AS
select f.IDMVTSTOCK,cast(sum(nvl(f.pu*f.ENTREE,0)) as number(30,2)) as montantEntree,
    cast(sum(nvl(f.pu*f.sortie,0)) as number(30,2)) as montantSortie
           from MVTSTOCKFILLE f group by f.IDMVTSTOCK;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTSTOCKFILLEGRP" ("IDMVTSTOCK", "ENTREE", "SORTIE", "COMPTE_STOCK", "COMPTE_SORTIE_STOCK") AS
SELECT
    f.IDMVTSTOCK,
    SUM(f.ENTREE * f.PU) AS entree,
    SUM(f.SORTIE * f.PU) AS SORTIE,
    ing.compte_stock,
    compte_sortie_stock
FROM MVTSTOCKFILLE f
         LEFT JOIN AS_INGREDIENTS ing ON ing.ID = f.IDPRODUIT
GROUP BY f.IDMVTSTOCK, ing.compte_stock,compte_sortie_stock;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTSTOCKFILLEGRPVARIATION" ("IDMVTSTOCK", "ENTREE", "SORTIE", "COMPTE_STOCK", "COMPTE_SORTIE_STOCK") AS
SELECT
    f.IDMVTSTOCK,
    SUM(f.ENTREE * f.PU) AS entree,
    SUM(f.SORTIE * f.PU) AS SORTIE,
     null as compte_stock,
    ing.compte_sortie_stock
FROM MVTSTOCKFILLE f
         LEFT JOIN AS_INGREDIENTS ing ON ing.ID = f.IDPRODUIT
GROUP BY f.IDMVTSTOCK, ing.compte_sortie_stock;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTSTOCKFILLELIB" ("ID", "IDMVTSTOCK", "IDPRODUIT", "IDPRODUITLIB", "ENTREE", "SORTIE", "IDVENTEDETAIL", "IDVENTEDETAILLIB", "IDTRANSFERTDETAIL", "IDTRANSFERTDETAILLIB", "DATY", "IDMAGASIN", "IDMAGASINLIB", "PU", "MONTANT", "LIBELLE", "MVTSRC", "LIBELLEEXACTE", "DATESQL", "IDOBJET", "IDTYPEMVSTOCK", "ETAT", "ETATLIB", "IDUNITE", "IDUNITELIB") AS
SELECT
    m.ID ,
    m.IDMVTSTOCK ,
    m.IDPRODUIT ,
    p.libelle  AS IDPRODUITLIB,
    m.ENTREE ,
    m.SORTIE ,
    m.IDVENTEDETAIL ,
    '' AS IDVENTEDETAILLIB,
    m.IDTRANSFERTDETAIL ,
    '' AS IDTRANSFERTDETAILLIB,
    m2.DATY ,
    m2.IDMAGASIN ,
    m3.VAL AS IDMAGASINLIB,
    m.pu,
    cast(m.pu*m.ENTREE+(m.pu*m.sortie) as number(20,5)) as montant,
    p.LIBELLE,
    m.MVTSRC,
    p.libelle AS libelleexacte,
    m2.DATY AS dateSql,
    m2.idobjet,
    m2.IDTYPEMVSTOCK,
    m2.etat,
    CASE
        WHEN m2.ETAT = 1 THEN 'CR&Eacute;&Eacute;'
        WHEN m2.ETAT = 11 THEN 'VIS&Eacute;'
        WHEN m2.ETAT = 11 THEN 'ANNUL&Eacute;'
        END    AS ETATLIB,
    p.UNITE AS idunite,
    asu.VAL AS idunitelib
FROM MVTSTOCKFILLE m
         LEFT JOIN AS_INGREDIENTS  p ON p.ID = m.IDPRODUIT
         LEFT JOIN MVTSTOCK m2 ON m2.ID = m.IDMVTSTOCK
         LEFT JOIN MAGASIN2 m3 ON m3.ID = m2.IDMAGASIN
         LEFT JOIN AS_UNITE asu ON asu.ID = p.UNITE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTSTOCKFILLELIB_ENG" ("ID", "IDMVTSTOCK", "IDPRODUIT", "IDPRODUITLIB", "ENTREE", "SORTIE", "IDVENTEDETAIL", "IDVENTEDETAILLIB", "IDTRANSFERTDETAIL", "IDTRANSFERTDETAILLIB", "DATY", "IDMAGASIN", "IDMAGASINLIB", "PU", "MONTANT", "LIBELLE", "MVTSRC", "LIBELLEEXACTE") AS
SELECT
    m.ID ,
    m.IDMVTSTOCK ,
    m.IDPRODUIT ,
    p.libelle  AS IDPRODUITLIB,
    m.ENTREE ,
    m.SORTIE ,
    m.IDVENTEDETAIL ,
    '' AS IDVENTEDETAILLIB,
    m.IDTRANSFERTDETAIL ,
    '' AS IDTRANSFERTDETAILLIB,
    m2.DATY ,
    m2.IDMAGASIN ,
    m3.VAL AS IDMAGASINLIB,
    m.pu,
    cast(m.pu*m.ENTREE+(m.pu*m.sortie) as number(20,5)) as montant,
    p.LIBELLE,
    m.MVTSRC,
    p.libelle AS libelleexacte
FROM MVTSTOCKFILLE_ENG m
         LEFT JOIN AS_INGREDIENTS  p ON p.ID = m.IDPRODUIT
         LEFT JOIN MVTSTOCK_ENG m2 ON m2.ID = m.IDMVTSTOCK
         LEFT JOIN MAGASIN2 m3 ON m3.ID = m2.IDMAGASIN;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTSTOCKFILLELIB_VISE" ("ID", "IDMVTSTOCK", "IDPRODUIT", "IDPRODUITLIB", "ENTREE", "SORTIE", "IDVENTEDETAIL", "IDVENTEDETAILLIB", "IDTRANSFERTDETAIL", "IDTRANSFERTDETAILLIB", "DATY", "IDMAGASIN", "IDMAGASINLIB") AS
SELECT m.ID,
       m.IDMVTSTOCK,
       m.IDPRODUIT,
       p.LIBELLE  AS IDPRODUITLIB,
       m.ENTREE,
       m.SORTIE,
       m.IDVENTEDETAIL,
       ''     AS IDVENTEDETAILLIB,
       m.IDTRANSFERTDETAIL,
       ''     AS IDTRANSFERTDETAILLIB,
       m2.DATY,
       m2.IDMAGASIN,
       m3.VAL AS IDMAGASINLIB
FROM MVTSTOCKFILLE m
         LEFT JOIN AS_INGREDIENTS  p ON p.ID = m.IDPRODUIT
         LEFT JOIN MVTSTOCK m2 ON m2.ID = m.IDMVTSTOCK
         LEFT JOIN MAGASIN m3 ON m3.ID = m2.IDMAGASIN
where m2.ETAT=11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTSTOCKFILLEMONTANT" ("ID", "IDMVTSTOCK", "IDPRODUIT", "ENTREE", "SORTIE", "IDVENTEDETAIL", "IDTRANSFERTDETAIL", "PU", "MVTSRC", "RESTE", "DESIGNATION", "MONTANTENTREE", "MONTANTSORTIE") AS
select mf."ID",mf."IDMVTSTOCK",mf."IDPRODUIT",mf."ENTREE",mf."SORTIE",mf."IDVENTEDETAIL",mf."IDTRANSFERTDETAIL",mf."PU",mf."MVTSRC",mf."RESTE",mf."DESIGNATION",cast(mf.PU*mf.ENTREE as number(30,5)) as montantEntree,cast(mf.PU*mf.SORTIE as number(30,5)) as montantSortie from MVTSTOCKFILLE mf;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTSTOCKFILLEMONTANT_ENG" ("ID", "IDMVTSTOCK", "IDPRODUIT", "ENTREE", "SORTIE", "IDVENTEDETAIL", "IDTRANSFERTDETAIL", "PU", "MVTSRC", "RESTE", "DESIGNATION", "MONTANTENTREE", "MONTANTSORTIE") AS
select mf.ID,
       mf.IDMVTSTOCK,
       mf.IDPRODUIT,
       mf.ENTREE,
       mf.SORTIE,
       mf.IDVENTEDETAIL,
       mf.IDTRANSFERTDETAIL,
       mf.PU,
       mf.MVTSRC,
       mf.RESTE,
       mf.DESIGNATION,
       cast(mf.PU * mf.ENTREE as number(30, 5)) as montantEntree,
       cast(mf.PU * mf.SORTIE as number(30, 5)) as montantSortie
from MVTSTOCKFILLE mf
union all
select mf.ID,
       mf.IDMVTSTOCK,
       mf.IDPRODUIT,
       mf.ENTREE,
       mf.SORTIE,
       mf.IDVENTEDETAIL,
       mf.IDTRANSFERTDETAIL,
       mf.PU,
       mf.MVTSRC,
       mf.RESTE,
       mf.DESIGNATION,
       cast(mf.PU * mf.ENTREE as number(30, 5)) as montantEntree,
       cast(mf.PU * mf.SORTIE as number(30, 5)) as montantSortie
from stock_engage_FILLE mf;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTSTOCKFILLEOFENTREEPRFINI" ("ENTREE", "IDOFF", "IDPRODUIT") AS
select cast(sum(ENTREE) as number(30,2)) as entree,idoff,IDPRODUIT from MVTSTOCKFILLEFABOFCATVISETous m group by idoff, IDPRODUIT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTSTOCKFILLEPARDATE" ("DATY", "IDMAGASIN", "IDPRODUIT", "ENTREE", "SORTIE") AS
select
    m.daty,
    m.IDMAGASIN,
    mf.IDPRODUIT,
    cast(nvl(sum(mf.ENTREE),0) as number(30,3)) as entree,
    CAST(NVL(SUM(mf.SORTIE), 0) AS NUMBER(30,3)) AS sortie
from MVTSTOCKFILLE mf
left join mvtstock m ON m.id = mf.IDMVTSTOCK
where m.ETAT >= 11
group by m.daty, mf.IDPRODUIT, m.IDMAGASIN;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTSTOCKFILLERESIDUFAB" ("ID", "IDPRODUIT", "IDPRODUITLIB", "ENTREE", "PU", "RESTE", "DESIGNATION", "IDFAB") AS
SELECT
    entree.ID ,
    entree.IDPRODUIT,
    entree.IDPRODUITLIB,
    entree.ENTREE,
    entree.PU AS PU,
    entree.RESTE AS RESTE,
    entree.DESIGNATION,
    entree.IDFAB
FROM
    MVTSTOCKFILLEENTREEFAB entree
JOIN
    MVTSTOCKFILLESORITEFAB sortie
ON
    entree.IDPRODUIT = sortie.IDPRODUIT
AND
    entree.IDFAB = sortie.IDFAB;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTSTOCKFILLERESIDUOF" ("IDPRODUIT", "IDPRODUITLIB", "ENTREE", "PU", "RESTE", "IDOF") AS
SELECT mf.IDPRODUIT, mf.IDPRODUITLIB, sum(nvl(mf.ENTREE,0)) AS ENTREE, sum(nvl(mf.PU ,0)) AS PU,sum(nvl(mf.RESTE ,0)) AS RESTE, o.IDMERE AS IDOF
FROM 
	MVTSTOCKFILLERESIDUFAB mf
JOIN FABRICATION f ON f.ID = mf.IDFAB 
JOIN OFFILLE o ON f.IDOFFILLE = o.id
GROUP BY mf.IDPRODUIT, mf.IDPRODUITLIB,o.IDMERE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTSTOCKFILLESANSINVENTAIRE" ("ID", "IDMVTSTOCK", "IDPRODUIT", "IDVENTEDETAIL", "IDTRANSFERTDETAIL", "MVTSRC", "DESIGNATION", "ENTREE", "SORTIE", "PU", "RESTE", "IDINVENTAIREFILLE") AS
select mf."ID",mf."IDMVTSTOCK",mf."IDPRODUIT",mf."IDVENTEDETAIL",mf."IDTRANSFERTDETAIL",mf."MVTSRC",mf."DESIGNATION",mf."ENTREE",mf."SORTIE",mf."PU",mf."RESTE",mf."IDINVENTAIREFILLE" from mvtStockFille mf
    left join mvtStock m on m.id=mf.IDMVTSTOCK
    where m.ETAT>=11 and mf.entree>0
      and not exists(select invf.id from INVENTAIREFILLE invf left join INVENTAIRE im on im.ID=invf.IDINVENTAIRE where invf.IDPRODUIT=mf.IDPRODUIT and invf.MVTSRC=mf.id and im.IDMAGASIN=m.IDMAGASIN);

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTSTOCKFILLESORITEFAB" ("ID", "IDMVTSTOCK", "IDPRODUIT", "IDPRODUITLIB", "ENTREE", "SORTIE", "IDVENTEDETAIL", "IDTRANSFERTDETAIL", "PU", "MVTSRC", "RESTE", "DESIGNATION", "IDFAB") AS
select st.ID,st.IDMVTSTOCK,st.IDPRODUIT,ai.LIBELLE AS IDPRODUITLIB,st.ENTREE,st.SORTIE,st.IDVENTEDETAIL,st.IDTRANSFERTDETAIL,st.PU,st.MVTSRC,st.RESTE,st.DESIGNATION,st.idFab
from MVTSTOCKFILLEFAB st
LEFT JOIN AS_INGREDIENTS ai
ON st.IDPRODUIT = ai.id
WHERE st.ENTREE  <= 0;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTSTOCKFILLETRANSFERT" ("IDTRANSFERTDETAIL", "ENTREE", "SORTIE") AS
SELECT 
m.idtransfertdetail,
CAST(sum(nvl(m.entree ,0)) AS NUMBER(30,5))  as entree,
CAST(sum(nvl(m.sortie ,0)) AS NUMBER(30,5)) as sortie
FROM mvtstockfillelib m
left JOIN mvtstock mv ON mv.id = m.idmvtstock
WHERE mv.etat >=11 
GROUP BY m.idtransfertdetail;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTSTOCKFILLEVRAISOURCE" ("ID", "IDMVTSTOCK", "IDPRODUIT", "IDVENTEDETAIL", "IDTRANSFERTDETAIL", "MVTSRC", "SOURCE2", "DESIGNATION", "ENTREE", "SORTIE", "PU", "RESTE", "IDINVENTAIREFILLE") AS
select ms.ID, ms.IDMVTSTOCK, ms.IDPRODUIT, ms.IDVENTEDETAIL, ms.IDTRANSFERTDETAIL,
       case when  (me.MVTSRC is not null and ms.SORTIE>0)
           then me.MVTSRC
           else ms.MVTSRC
        end as mvtsrc
     ,me.MVTSRC as source2
     , ms.DESIGNATION, ms.ENTREE, ms.SORTIE, ms.PU, ms.RESTE, ms.IDINVENTAIREFILLE from MVTSTOCKFILLE ms left  join
(select m.id, m.idmvtstock, m.idproduit, m.idventedetail, m.idtransfertdetail, m.mvtsrc, m.designation, m.entree, m.sortie, m.pu, m.reste, m.idinventairefille
 from MVTSTOCKFILLE m
where m.entree>0 and m.MVTSRC is not null) me
on me.ID=ms.MVTSRC
left join MVTSTOCK m on m.id=ms.IDMVTSTOCK
where m.IDTYPEMVSTOCK!='TPMVST000023';

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTSTOCKFILLE_ENG" ("ID", "IDMVTSTOCK", "IDPRODUIT", "IDVENTEDETAIL", "IDTRANSFERTDETAIL", "MVTSRC", "DESIGNATION", "ENTREE", "SORTIE", "PU", "RESTE") AS
select ID, IDMVTSTOCK, IDPRODUIT, IDVENTEDETAIL, IDTRANSFERTDETAIL, MVTSRC, DESIGNATION, ENTREE, SORTIE, PU, RESTE from MVTSTOCKFILLE
    union all
select ID, IDMVTSTOCK, IDPRODUIT, IDVENTEDETAIL, IDTRANSFERTDETAIL, MVTSRC, DESIGNATION, ENTREE, SORTIE, PU, RESTE from stock_engage_FILLE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTSTOCKLIB" ("ID", "DESIGNATION", "IDMAGASIN", "IDOBJET", "IDMAGASINLIB", "IDVENTE", "IDVENTELIB", "IDTRANSFERT", "IDTRANSFERTLIB", "IDTYPEMVSTOCK", "IDTYPEMVSTOCKLIB", "DATY", "ETAT", "HEURE", "ETATLIB", "IDRESERVATION", "MONTANTENTREE", "MONTANTSORTIE", "IDCATEGORIESTOCK", "IDCATEGORIESTOCKLIB", "MOTSCLESSS") AS
SELECT
m.ID ,
m.DESIGNATION ,
m.IDMAGASIN ,
m.IDOBJET ,
m2.VAL  AS idMagasinlib,
m.IDVENTE ,
v.DESIGNATION  AS idVentelib,
m.IDTRANSFERT ,
CAST('' AS VARCHAR2(255)) AS idTransfertlib,
m.IDTYPEMVSTOCK ,
t.VAL AS idTypeMvStocklib ,
m.DATY ,
m.ETAT ,
m.heure,
CASE
	WHEN m.ETAT = 0
	THEN 'ANNUL&Eacute;'
	WHEN m.ETAT = 1
	THEN 'CR&Eacute;&Eacute;'
	WHEN m.ETAT = 11
	THEN 'VALID&Eacute;'
END AS etatlib,
v.IDRESERVATION,
CAST(COALESCE(gm.montantEntree,0) AS NUMBER(30,5)) AS  montantEntree,
CAST(COALESCE(gm.montantSortie,0) AS NUMBER(30,5)) AS  montantSortie,
m.IDCATEGORIESTOCK,
cs.val as idCategorieStockLib,
m.ID || '' || m.DESIGNATION || '' || m.IDMAGASIN || '' || m2.VAL || '' || m.IDVENTE || '' || v.DESIGNATION || '' || t.VAL || '' || cs.val || '' || m.DATY AS MOTSCLESSS
FROM MVTSTOCK m
LEFT JOIN TYPEMVTSTOCK t ON t.ID = m.IDTYPEMVSTOCK
LEFT JOIN VENTE v ON v.ID = m.IDVENTE
LEFT JOIN MAGASIN2 m2 ON m2.ID = m.IDMAGASIN
left join mvtStockFilleGroupeMere gm on gm.IDMVTSTOCK=m.ID
LEFT JOIN categorieStock cs ON m.IDCATEGORIESTOCK = cs.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTSTOCKLIBANNULER" ("ID", "DESIGNATION", "IDMAGASIN", "IDOBJET", "IDMAGASINLIB", "IDVENTE", "IDVENTELIB", "IDTRANSFERT", "IDTRANSFERTLIB", "IDTYPEMVSTOCK", "IDTYPEMVSTOCKLIB", "DATY", "ETAT", "HEURE", "ETATLIB", "IDRESERVATION", "MONTANTENTREE", "MONTANTSORTIE", "IDCATEGORIESTOCK", "IDCATEGORIESTOCKLIB", "MOTSCLESSS") AS
SELECT
    m.ID,
    m.DESIGNATION,
    m.IDMAGASIN,
    m.IDOBJET,
    m.IDMAGASINLIB,
    m.IDVENTE,
    m.IDVENTELIB,
    m.IDTRANSFERT,
    m.IDTRANSFERTLIB,
    m.IDTYPEMVSTOCK,
    m.IDTYPEMVSTOCKLIB,
    m.DATY,
    m.ETAT,
    m.HEURE,
    m.ETATLIB,
    m.IDRESERVATION,
    m.MONTANTENTREE,
    m.MONTANTSORTIE,
    m.IDCATEGORIESTOCK,
    m.IDCATEGORIESTOCKLIB,
    m.MOTSCLESSS
FROM MVTSTOCKLIB m
WHERE m.ETAT = 0;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTSTOCKLIBCREER" ("ID", "DESIGNATION", "IDMAGASIN", "IDOBJET", "IDMAGASINLIB", "IDVENTE", "IDVENTELIB", "IDTRANSFERT", "IDTRANSFERTLIB", "IDTYPEMVSTOCK", "IDTYPEMVSTOCKLIB", "DATY", "ETAT", "HEURE", "ETATLIB", "IDRESERVATION", "MONTANTENTREE", "MONTANTSORTIE", "IDCATEGORIESTOCK", "IDCATEGORIESTOCKLIB", "MOTSCLESSS") AS
SELECT
    m.ID,
    m.DESIGNATION,
    m.IDMAGASIN,
    m.IDOBJET,
    m.IDMAGASINLIB,
    m.IDVENTE,
    m.IDVENTELIB,
    m.IDTRANSFERT,
    m.IDTRANSFERTLIB,
    m.IDTYPEMVSTOCK,
    m.IDTYPEMVSTOCKLIB,
    m.DATY,
    m.ETAT,
    m.HEURE,
    m.ETATLIB,
    m.IDRESERVATION,
    m.MONTANTENTREE,
    m.MONTANTSORTIE,
    m.IDCATEGORIESTOCK,
    m.IDCATEGORIESTOCKLIB,
    m.MOTSCLESSS
FROM MVTSTOCKLIB m
WHERE m.ETAT = 1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTSTOCKLIBFACTURE" ("ID", "DESIGNATION", "IDMAGASIN", "IDOBJET", "IDMAGASINLIB", "IDVENTE", "IDVENTELIB", "IDTRANSFERT", "IDTRANSFERTLIB", "IDTYPEMVSTOCK", "IDTYPEMVSTOCKLIB", "DATY", "ETAT", "HEURE", "ETATLIB", "IDRESERVATION", "MONTANTENTREE", "MONTANTSORTIE", "IDCATEGORIESTOCK", "IDCATEGORIESTOCKLIB", "MOTSCLESSS", "IDFACTUREFOURNISSEUR") AS
select m."ID",m."DESIGNATION",m."IDMAGASIN",m."IDOBJET",m."IDMAGASINLIB",m."IDVENTE",m."IDVENTELIB",m."IDTRANSFERT",m."IDTRANSFERTLIB",m."IDTYPEMVSTOCK",m."IDTYPEMVSTOCKLIB",m."DATY",m."ETAT",m."HEURE",m."ETATLIB",m."IDRESERVATION",m."MONTANTENTREE",m."MONTANTSORTIE",m."IDCATEGORIESTOCK",m."IDCATEGORIESTOCKLIB",m."MOTSCLESSS",
       f.id as IDFACTUREFOURNISSEUR
from MVTSTOCKlib m
         LEFT JOIN AS_BONDELIVRAISON ab ON ab.id = m.IDOBJET
         LEFT JOIN facturefournisseur f ON f.id = ab.IDFACTUREFOURNISSEUR;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTSTOCKLIBVALIDER" ("ID", "DESIGNATION", "IDMAGASIN", "IDOBJET", "IDMAGASINLIB", "IDVENTE", "IDVENTELIB", "IDTRANSFERT", "IDTRANSFERTLIB", "IDTYPEMVSTOCK", "IDTYPEMVSTOCKLIB", "DATY", "ETAT", "HEURE", "ETATLIB", "IDRESERVATION", "MONTANTENTREE", "MONTANTSORTIE", "IDCATEGORIESTOCK", "IDCATEGORIESTOCKLIB", "MOTSCLESSS") AS
SELECT
    m.ID,
    m.DESIGNATION,
    m.IDMAGASIN,
    m.IDOBJET,
    m.IDMAGASINLIB,
    m.IDVENTE,
    m.IDVENTELIB,
    m.IDTRANSFERT,
    m.IDTRANSFERTLIB,
    m.IDTYPEMVSTOCK,
    m.IDTYPEMVSTOCKLIB,
    m.DATY,
    m.ETAT,
    m.HEURE,
    m.ETATLIB,
    m.IDRESERVATION,
    m.MONTANTENTREE,
    m.MONTANTSORTIE,
    m.IDCATEGORIESTOCK,
    m.IDCATEGORIESTOCKLIB,
    m.MOTSCLESSS
FROM MVTSTOCKLIB m
WHERE m.ETAT >= 11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTSTOCKPRODUIT" ("IDOBJET", "IDINGREDIENT", "IDINGREDIENTLIB", "UNITE", "IDOFFILLE", "ENTREE", "SORTIE", "PU") AS
SELECT 
    m2.idobjet ,
    m.IDPRODUIT AS idingredient ,
    ai.LIBELLE AS idingredientlib,
    ai.UNITE,
    f.IDOFFILLE,
    sum(m.ENTREE) AS entree ,
    sum(m.SORTIE) AS sortie ,
    nvl(sum(m.pu),0) AS pu 
FROM 
    MVTSTOCKFILLE m
    LEFT JOIN MVTSTOCK m2 ON m2.id = m.IDMVTSTOCK
    LEFT JOIN AS_INGREDIENTS ai ON ai.id = m.idproduit
    LEFT JOIN FABRICATION f ON f.id = m2.idobjet
GROUP BY  m2.idobjet ,
    m.IDPRODUIT , ai.LIBELLE ,ai.UNITE , f.IDOFFILLE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTSTOCK_ENG" ("ID", "DESIGNATION", "IDMAGASIN", "IDVENTE", "IDTRANSFERT", "IDTYPEMVSTOCK", "DATY", "ETAT", "IDPOINT", "IDOBJET", "FABPRECEDENT") AS
select ID, DESIGNATION, IDMAGASIN, IDVENTE, IDTRANSFERT, IDTYPEMVSTOCK, DATY, ETAT, IDPOINT, IDOBJET, FABPRECEDENT from MVTSTOCK
    union all
select ID, DESIGNATION, IDMAGASIN, IDVENTE, IDTRANSFERT, IDTYPEMVSTOCK, DATY, ETAT, IDPOINT, IDOBJET, FABPRECEDENT from stock_engage;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."NB_PERS_VALIDE" ("NBPERSONNELVALIDE") AS
SELECT COUNT(*) AS NBPERSONNELVALIDE FROM LOG_PERSONNEL_V;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."NET_MOISANNEE" ("MOIS", "ANNEE", "MONTANT") AS
SELECT pe.mois,
       pe.annee,
       CAST(sum(pe.gain) AS NUMBER(15,2)) AS montant
FROM paie_edition pe
WHERE pe.idelementpaie = 'PR000210A'
GROUP BY pe.mois, pe.annee;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."NOMBRE_PANNE_MACHINE" ("ID", "IDENTITE", "IDSITUATION", "IDMACHINE", "DATY", "DATEBESOIN", "PRIORITE", "ESTEXISTANT", "DESCRIPTION", "ETAT", "DEMANDEUR", "CAUSE", "IDDEPARTEMENT", "IDDEPARTEMENTMAINTENANCE", "IDMACHINELIB", "QTE") AS
SELECT
    d."ID",
    d."IDENTITE",
    d."IDSITUATION",
    d."IDMACHINE",
    d."DATY",
    d."DATEBESOIN",
    d."PRIORITE",
    d."ESTEXISTANT",
    d."DESCRIPTION",
    d."ETAT",
    d."DEMANDEUR",
    d."CAUSE",
    d."IDDEPARTEMENT",
    d."IDDEPARTEMENTMAINTENANCE",
    ai.LIBELLE AS idMachineLib,

    COUNT(*) OVER (PARTITION BY d.IDMACHINE, d.DATY) AS qte

FROM DEMANDETRAVAUX d
         LEFT JOIN AS_INGREDIENT_MAINTENANCE m
                   ON d.IDMACHINE = m.ID
         LEFT JOIN AS_INGREDIENTS ai
                   ON m.IDINGREDIENT = ai.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."NOTIFICATIONLIBCPLT" ("ID", "RECEIVER", "RECEIVERLIB", "MESSAGE", "DATY", "HEURE", "ETAT", "REF", "REFLIB", "ETATLIB", "LIEN", "ECARTDATE") AS
SELECT n.id,
       n.receiver,
       u.nomuser AS receiverlib,
       n.message,
       n.daty,
       n.heure,
       n.etat,
       n.ref,
       '' AS reflib,
       CASE
           WHEN n.etat = 11 THEN 'LU'
           WHEN n.etat = 1 THEN 'NON LU'
           ELSE NULL
           END AS etatlib,
       n.lien,
       CASE
           WHEN ( (SYSDATE - (TO_DATE(TO_CHAR(n.daty,'YYYY-MM-DD') || ' ' || n.heure, 'YYYY-MM-DD HH24:MI:SS'))) * 24 * 60 * 60 ) < 60
               THEN 'il y a moins d''une minute'
           WHEN ( (SYSDATE - (TO_DATE(TO_CHAR(n.daty,'YYYY-MM-DD') || ' ' || n.heure, 'YYYY-MM-DD HH24:MI:SS'))) * 24 * 60 * 60 ) < 3600
               THEN 'il y a ' || FLOOR(((SYSDATE - (TO_DATE(TO_CHAR(n.daty,'YYYY-MM-DD') || ' ' || n.heure, 'YYYY-MM-DD HH24:MI:SS'))) * 24 * 60)) || ' mn'
           WHEN ( (SYSDATE - (TO_DATE(TO_CHAR(n.daty,'YYYY-MM-DD') || ' ' || n.heure, 'YYYY-MM-DD HH24:MI:SS'))) * 24 * 60 * 60 ) < 86400
               THEN 'il y a ' || FLOOR(((SYSDATE - (TO_DATE(TO_CHAR(n.daty,'YYYY-MM-DD') || ' ' || n.heure, 'YYYY-MM-DD HH24:MI:SS'))) * 24)) || ' h'
           ELSE 'il y a ' || FLOOR((SYSDATE - (TO_DATE(TO_CHAR(n.daty,'YYYY-MM-DD') || ' ' || n.heure, 'YYYY-MM-DD HH24:MI:SS')))) || ' jrs'
           END AS ecartdate
FROM notification2 n
         LEFT JOIN utilisateur u ON u.refuser = n.receiver order by DATY desc;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."NOTIFICATIONLIBNONLU" ("ID", "RECEIVER", "MESSAGE", "DATY", "HEURE", "ETAT", "REF", "ETATLIB", "RECEIVERLIB", "LIEN", "ECARTDATE", "LIEN_HTML") AS
SELECT n.id,
       n.receiver,
       n.message,
       n.daty,
       n.heure,
       n.etat,
       n.ref,
       n.etatlib,
       n.receiverlib,
       n.lien,
       n.ecartdate,
       '<a href=XX?but=' || n.lien || '&id=' || n.ref || '>' || n.ref || '</a>' AS lien_html
FROM notificationlibcplt n
WHERE n.etat = 1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."OBJECTIF_ANNUEL_LIB" ("ID", "IDPERSONNEL", "TITRE", "DATY", "IDPERSONNELLIB", "MATRICULE", "IDFONCTION", "IDFONCTIONLIB") AS
SELECT
    oa.ID,oa.IDPERSONNEL,oa.TITRE,oa.DATY,
    lp.NOM || ' ' || lp.PRENOM AS idPersonnelLib,
    pip.MATRICULE AS matricule,
    pip.IDFONCTION AS idFonction,
    pf.VAL AS idFonctionLib
FROM OBJECTIF_ANNUEL oa
-- Jointure pour les informations de base du personnel
         LEFT JOIN LOG_PERSONNEL lp
                   ON oa.IDPERSONNEL = lp.ID
-- Jointure pour recuperer l'ID Fonction depuis la paie
         LEFT JOIN PAIE_INFO_PERSONNEL pip
                   ON oa.IDPERSONNEL = pip.ID
-- Jointure pour recuperer le libelle de la fonction
         LEFT JOIN PAIE_FONCTION pf
                   ON pip.IDFONCTION = pf.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."OFABLIB" ("ID", "LANCEPAR", "CIBLE", "REMARQUE", "LIBELLE", "BESOIN", "DATY", "ETAT", "LANCEUR", "LANCEURLIB", "ETATLIB", "MOTSCLESSS") AS
SELECT OFL.ID,
       P1.VAL     AS LANCEPAR,
       P2.VAL     AS CIBLE,
       OFL.REMARQUE,
       OFL.LIBELLE,
       OFL.BESOIN,
       OFL.DATY,
       OFL.ETAT,
       OFL.LANCEUR,
       LP.NOMUSER AS LANCEURLIB,
       CASE
           WHEN OFL.ETAT = 1 THEN 'Cr&eacute;&eacute;'
           WHEN OFL.ETAT = 11 THEN 'Valid&eacute;'
           WHEN OFL.ETAT = 0 THEN 'Annul&eacute;'
           WHEN OFL.ETAT = 21 THEN 'Entam&eacute;'
           WHEN OFL.ETAT = 31 THEN 'Bloqu&eacute;'
           WHEN OFL.ETAT = 41 THEN 'Termin&eacute;'
           END    AS ETATLIB,
       (
           OFL.id || ' | ' || libelle || ' | ' ||  besoin || ' | ' || LP.NOMUSER || ' | ' || ' | ' || P2.VAL || ' | ' ||  remarque
           )      AS MOTSCLESSS
FROM OFAB OFL
         LEFT JOIN MAGASINPOINT P1 ON P1.ID = OFL.LANCEPAR
         LEFT JOIN MAGASINPOINT P2 ON P2.ID = OFL.CIBLE
         LEFT JOIN UTILISATEUR LP ON LP.REFUSER = OFL.LANCEUR;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."OFFILLEEQUIVALENCE" ("ID", "IDINGREDIENTS", "LIBELLE", "REMARQUE", "IDMERE", "DATYBESOIN", "QTE", "IDUNITE", "IDBCFILLE", "EQUIVALENCE") AS
select o."ID",o."IDINGREDIENTS",o."LIBELLE",o."REMARQUE",o."IDMERE",o."DATYBESOIN",o."QTE",o."IDUNITE",o."IDBCFILLE",cast(nvl(e.QTE,1) as number(20,2)) as equivalence from OFFILLE o left join EQUIVALENCE e on o.IDINGREDIENTS=e.IDPRODUIT and o.IDUNITE=e.IDUNITE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."OFFILLELIB" ("ID", "IDINGREDIENTS", "LIBELLE", "REMARQUE", "IDMERE", "DATYBESOIN", "QTE", "IDUNITE", "QTEFABRIQUE", "QTERESTE", "LIBELLEEXACTE") AS
SELECT
	ofll.ID,
	ofll.IDINGREDIENTS,
	nvl(ofll.LIBELLE,ai.LIBELLE)  AS LIBELLE,
	ofll.REMARQUE,
	ofll.IDMERE,
	ofll.DATYBESOIN,
	ofll.QTE,
	nvl(au.VAL, 'unite') AS IDUNITE,
	fmf.qte AS qteFabrique,
	(ofll.qte-nvl(fmf.qte, 0)) AS qteReste,
	nvl(ofll.LIBELLE,nvl(ai.LIBELLEEXTACTE, ai.LIBELLE)) AS libelleexacte
FROM
	OFFILLE ofll
LEFT JOIN AS_INGREDIENTS ai ON
	ai.ID = ofll.IDINGREDIENTS
LEFT JOIN AS_UNITE au ON
	au.ID = ofll.IDUNITE
LEFT JOIN FabricationMereFille fmf ON
	fmf.IDOFFILLE = ofll.ID
	AND fmf.IDINGREDIENTS = ofll.IDINGREDIENTS
	AND fmf.IDBCFILLE = OFLL.IDBCFILLE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."OFFILLELIBQTERESTE" ("ID", "IDINGREDIENTS", "LIBELLE", "REMARQUE", "IDMERE", "DATYBESOIN", "QTE", "IDUNITE", "QTEFABRIQUE", "QTERESTE", "LIBELLEMERE", "DATY", "IDBCFILLE") AS
SELECT
	ofll.ID,
	ofll.IDINGREDIENTS,
	ai.LIBELLE ||' '|| ofll.LIBELLE as LIBELLE,
	ai.LIBELLE as remarque,
	ofll.IDMERE,
	ofll.DATYBESOIN,
	(ofll.qte-nvl(fmf.qte,0)) as QTE,
	nvl(au.ID,'UNT00005') AS IDUNITE,
-- 	au.id as lele,
	fmf.qte AS qteFabrique,(ofll.qte-fmf.qte) AS qteReste,
	ofa.LIBELLE as libelleMere,fmf.daty,
	ofll.IDBCFILLE

FROM OFFILLE ofll
	LEFT JOIN AS_INGREDIENTS ai ON ai.ID = ofll.IDINGREDIENTS
	LEFT JOIN AS_UNITE au ON au.ID = ofll.IDUNITE
    LEFT JOIN FabricationMereFille fmf on fmf.IDOF=ofll.IDMERE and fmf.IDINGREDIENTS=ofll.IDINGREDIENTS
left join OFAB ofa on ofa.id=ofll.IDMERE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."OFFILLELIBSTOCK" ("ID", "IDINGREDIENTS", "LIBELLE", "REMARQUE", "IDMERE", "DATYBESOIN", "QTE", "IDUNITE", "QTEFABRIQUE", "QTERESTE", "LIBELLEEXACTE", "PV", "MONTANTENTREE", "MONTANTSORTIE", "POURC", "MOTSCLESSS", "DATY") AS
SELECT SQ.ID,
       SQ.IDINGREDIENTS,
       SQ.LIBELLE,
       SQ.REMARQUE,
       SQ.IDMERE,
       SQ.DATYBESOIN,
       SQ.QTE,
       SQ.IDUNITE,
       SQ.QTEFABRIQUE,
       SQ.QTERESTE,
       SQ.LIBELLEEXACTE,
       SQ.PV,
       SQ.MONTANTENTREE,
       SQ.MONTANTSORTIE,
       SQ.POURC,
       (
           ID || ' | ' || IDINGREDIENTS || ' | ' || LIBELLEEXACTE || ' | ' || IDUNITE
           ) AS MOTSCLESSS,
       SQ.DATY
FROM (SELECT OFLL.ID,
             OFLL.IDINGREDIENTS,
             NVL(OFLL.LIBELLE, AI.LIBELLE)                         AS LIBELLE,
             OFLL.REMARQUE,
             OFLL.IDMERE,
             OB.DATY                                               AS DATYBESOIN,
             OFLL.QTE,
             NVL(AU.VAL, 'unite')                                  AS IDUNITE,
             CAST(NVL(MV.ENTREE, 0) AS NUMBER(30, 5))              AS QTEFABRIQUE,
             CAST(OFLL.QTE - NVL(MV.ENTREE, 0) AS NUMBER(30, 5))   AS QTERESTE,
             NVL(OFLL.LIBELLE, NVL(AI.LIBELLEEXTACTE, AI.LIBELLE)) AS LIBELLEEXACTE,
             CAST(OFLL.PRIXVENTE AS NUMBER(30, 5))                 AS PV,
             CAST(NVL(MV.ENTREE, 0) * AI.PV AS NUMBER(30, 5))      AS MONTANTENTREE,
             CAST(NVL(MVT.MONTANTSORTIE, 0) AS NUMBER(30, 5))      AS MONTANTSORTIE,
             CASE
                 WHEN NVL(MV.ENTREE, 0) = 0 OR AI.PV = 0 THEN 0
                 ELSE (1 - (MVT.MONTANTSORTIE / (NVL(MV.ENTREE, 0) * AI.PV))) * 100
                 END                                               AS POURC,
             OB.DATY                                               AS DATY
      FROM OFFILLE OFLL
               LEFT JOIN AS_INGREDIENTS AI ON AI.ID = OFLL.IDINGREDIENTS
               LEFT JOIN AS_UNITE AU ON AU.ID = OFLL.IDUNITE
               LEFT JOIN MVTSTFILLEOFFCATVISEGROUPEDEP MVT ON OFLL.ID = MVT.IDOFF
               LEFT JOIN MVTSTOCKFILLEOFENTREEPRFINI MV
                         ON MV.IDOFF = OFLL.ID
                             AND MV.IDPRODUIT = OFLL.IDINGREDIENTS
               LEFT JOIN OFAB OB ON OB.ID = OFLL.IDMERE) SQ;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."OFFILLELIBSTOCKIA" ("ID", "IDPRODUIT", "LIBELLE", "REMARQUE", "IDMERE", "DATYBESOIN", "QTE", "IDUNITE", "QTEFABRIQUE", "QTERESTE", "LIBELLEEXACTE", "PV", "MONTANTENTREE", "MONTANTSORTIE", "POURC", "IDPRODUITLIB", "MOTSCLESSS", "DATY") AS
SELECT SQ.ID,SQ.IDPRODUIT,SQ.LIBELLE,SQ.REMARQUE,SQ.IDMERE,SQ.DATYBESOIN,SQ.QTE,SQ.IDUNITE,SQ.QTEFABRIQUE,SQ.QTERESTE,SQ.LIBELLEEXACTE,SQ.PV,SQ.MONTANTENTREE,SQ.MONTANTSORTIE,SQ.POURC, SQ.IDPRODUITLIB,
       (NVL(TO_CHAR("ID"),'') || ' | ' || NVL(TO_CHAR(IDPRODUIT),'') || ' | ' || NVL(TO_CHAR(LIBELLE),'') || ' | ' || NVL(TO_CHAR(REMARQUE),'') || ' | ' || NVL(TO_CHAR(IDMERE),'') || ' | ' || NVL(TO_CHAR(DATYBESOIN,'YYYY-MM-DD HH24:MI:SS'),'') || ' | ' || NVL(TO_CHAR(QTE),'') || ' | ' || NVL(TO_CHAR(IDUNITE),'') || ' | ' || NVL(TO_CHAR(QTEFABRIQUE),'') || ' | ' || NVL(TO_CHAR(QTERESTE),'') || ' | ' || NVL(TO_CHAR(LIBELLEEXACTE),'') || ' | ' || NVL(TO_CHAR(PV),'') || ' | ' || NVL(TO_CHAR(MONTANTENTREE),'') || ' | ' || NVL(TO_CHAR(MONTANTSORTIE),'') || ' | ' || NVL(TO_CHAR(POURC),'')) AS MOTSCLESSS,daty
FROM (
         SELECT
             ofll.ID,
             ofll.IDINGREDIENTS AS IDPRODUIT,
             nvl(ofll.LIBELLE,ai.LIBELLE)  AS LIBELLE,
             ofll.REMARQUE,
             ofll.IDMERE,
             ob.daty AS  DATYBESOIN,
             ofll.QTE,
             nvl(au.VAL, 'unite') AS IDUNITE,
             cast(nvl(mv.entree,0) as number(30,5)) as qteFabrique,
             cast(ofll.QTE-nvl(mv.ENTREE,0)as number(30,5)) as qteReste,
             nvl(ofll.LIBELLE,nvl(ai.LIBELLEEXTACTE, ai.LIBELLE)) AS libelleexacte,
             ai.pv,
             cast(nvl(mv.ENTREE,0)*ai.pv as number(30,2)) as montantEntree,
             cast(nvl(mvt.montantSortie,0) as number(30,5)) as montantSortie,
             CASE
                 WHEN (nvl(mv.ENTREE,0)=0 or ai.pv=0) THEN 0
                 ELSE (1-(mvt.montantSortie/(nvl(mv.ENTREE,0)*ai.pv)))*100
                 END AS pourc,
             ob.daty,
             ai.libelle AS IDPRODUITLIB
         FROM
             OFFILLE ofll
                 LEFT JOIN AS_INGREDIENTS ai ON
                 ai.ID = ofll.IDINGREDIENTS
                 LEFT JOIN AS_UNITE au ON
                 au.ID = ofll.IDUNITE
                 left join MVTSTFILLEOFFCATVISEGROUPEDEP mvt on ofll.id=mvt.IDOFf
                 left join mvtStockFilleOfEntreePrFini mv on mv.idoff=ofll.id and mv.IDPRODUIT=ofll.IDINGREDIENTS
                 LEFT JOIN OFAB ob ON ob.id =  ofll.idmere

     ) SQ;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."OFFILLERESTELIB" ("ID", "IDINGREDIENTS", "LIBELLE", "REMARQUE", "IDMERE", "DATYBESOIN", "QTE", "IDUNITE", "QTEFABRIQUE", "QTERESTE") AS
SELECT o."ID",o."IDINGREDIENTS",o."LIBELLE",o."REMARQUE",o."IDMERE",o."DATYBESOIN",o."QTE",o."IDUNITE",fmf.qte AS qteFabrique,(o.qte-fmf.qte) AS qteReste FROM FabricationMereFille fmf JOIN OfFilleLib o ON fmf.idof=o.IDMERE  AND fmf.IDINGREDIENTS=o.IDINGREDIENTS;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."OFFILLESTOCK_RECAP_JOUR" ("DATY", "NOMBRE", "QTE", "QTEFABRIQUE", "QTERESTE") AS
SELECT
    TRUNC(DATY) AS DATY,
    COUNT(*) AS NOMBRE,
    CAST(SUM(NVL(QTE, 0)) AS NUMBER(30,5)) AS QTE,
    CAST(SUM(NVL(QTEFABRIQUE, 0)) AS NUMBER(30,5)) AS QTEFABRIQUE,
    CAST(SUM(NVL(QTERESTE, 0)) AS NUMBER(30,5)) AS QTERESTE
FROM OFFILLELIBSTOCK
GROUP BY TRUNC(DATY);

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."OFFRE_EMPLOILIB" ("ID", "IDFICHEPOSTE", "IDFICHEPOSTELIB", "TITRE", "DESCRIPTION", "MISSION", "EXIGENCEPOSTE", "IDTYPECONTRAT", "IDTYPECONTRATLIB", "SALAIREMIN", "SALAIREMAX", "ETAT", "DATEPUBLICATION", "DATEFERMETURE", "ETATLIB") AS
SELECT 
    o.id,
    o.idFichePoste,
    fp.titre AS idFichePostelib,
    o.titre,
    o.description,
    o.mission,
    o.exigencePoste,
    o.idTypeContrat,
    tc.val AS idTypeContratlib,
    o.salaireMin,
    o.salaireMax,
    o.etat,
    o.datePublication,
    o.dateFermeture,
     CASE
           WHEN o.ETAT = 1 THEN 'Cr&eacute;e'
           WHEN o.ETAT = 11 THEN 'Vis&eacute;e'
           WHEN o.ETAT = 0 THEN 'ANNUL&eacute;E'
           END
            AS ETATLIB

FROM offre_emploi o

LEFT JOIN type_contrat tc 
    ON o.idTypeContrat = tc.id

LEFT JOIN fiche_poste fp 
    ON o.idFichePoste = fp.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."OFGROUPBYIDBC" ("IDBCFILLE", "QTE") AS
SELECT 
    f.IDBCFILLE,
    SUM(f.QTE) AS qte
FROM OFFILLE f
LEFT JOIN OFAB m ON m.ID = f.IDMERE
WHERE m.ETAT >= 11
GROUP BY f.IDBCFILLE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."OFNONRATTACHE" ("IDOFFILLE", "DATY", "IDPRODUIT", "IDPRODUITLIB", "QTE", "QTEPETRI", "IDLIGNE", "LIGNE", "LANCEPAR") AS
SELECT
        offille.id AS idoffille,
        o.daty AS daty,
        offille.IDINGREDIENTS AS idproduit,
        ai.LIBELLE AS idproduitLib,
        offille.qte AS qte,
       (offille.qte/e.NBCARTON) AS qtepetri,
        l.id AS idligne,
        l.VAL AS ligne,
        o.lancepar
        FROM ofab o
LEFT join offille offille ON o.id=offille.idmere
LEFT JOIN AS_INGREDIENTS ai ON ai.id=offille.IDINGREDIENTS
LEFT JOIN TYPE_PRODUIT tp ON tp.ID = ai.typeproduit 
LEFT JOIN LIGNE l ON l.id=tp.IDLIGNE 
LEFT JOIN EQUIVALENCECARTON e ON e.IDCARTON = offille.IDINGREDIENTS 
WHERE o.etat = 11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."OFNONRATTACHEREEL" ("IDOFFILLE", "DATY", "IDPRODUIT", "IDPRODUITLIB", "QTE", "QTEPETRI", "IDLIGNE", "LIGNE", "LANCEPAR") AS
SELECT
        offille.id AS idoffille,
        o.daty AS daty,
        offille.IDINGREDIENTS AS idproduit,
        ai.LIBELLE AS idproduitLib,
        offille.qtefabrique as qte,
        (offille.qtefabrique/e.NBCARTON) AS qtepetri,
        l.id AS idligne,
        l.VAL AS ligne,
        o.lancepar
        FROM ofab o
LEFT join OfFilleLibStock offille ON o.id=offille.idmere
LEFT JOIN AS_INGREDIENTS ai ON ai.id=offille.IDINGREDIENTS
LEFT JOIN TYPE_PRODUIT tp ON tp.ID = ai.typeproduit 
LEFT JOIN LIGNE l ON l.id=tp.IDLIGNE 
LEFT JOIN EQUIVALENCECARTON e ON e.IDCARTON = offille.IDINGREDIENTS
WHERE o.etat = 11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."OFRATTACHE" ("ID", "IDOFFILLE", "DATY", "IDPRODUIT", "IDPRODUITLIB", "QTE", "QTEPETRI", "IDLIGNE", "LIGNE", "IDRELEVE", "POURCENTAGE") AS
SELECT 
  r.ID,
    ofn.IDOFFILLE,
    ofn.DATY,
    ofn.IDPRODUIT,
    ofn.IDPRODUITLIB,
    ofn.QTE,
    ofn.QTEPETRI,
    ofn.IDLIGNE,
    ofn.LIGNE,
    r.IDRELEVE,
    -- Pourcentage de QTEPETRI par IDRELEVE
    CAST((ofn.QTEPETRI / SUM(ofn.QTEPETRI) OVER (PARTITION BY r.IDRELEVE)) * 100 AS NUMBER(30,2) ) AS POURCENTAGE
FROM ofnonrattachereel ofn
JOIN RELEVEFAB r 
    ON r.IDFAB = ofn.IDOFFILLE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."ONBOARDING_MERE_LIB" ("ID", "NOM", "DESCRIPTION", "IDFONCTION", "IDFONCTIONLIB") AS
SELECT
    m.ID,m.NOM,m.DESCRIPTION,m.IDFONCTION,
    f.val AS idFonctionLib
FROM
    ONBOARDING_MERE m
        LEFT JOIN
    PAIE_FONCTION f ON m.idFonction = f.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."ONBOARDING_MERE_TC" ("ID", "NOM", "DESCRIPTION", "IDFONCTION") AS
SELECT ID,NOM,DESCRIPTION,IDFONCTION
FROM ONBOARDING_MERE
WHERE IDFONCTION IS NULL;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."ORDRETRAVAUXCPL" ("ID", "LANCEPAR", "CIBLE", "REMARQUE", "LIBELLE", "BESOIN", "DATY", "ETAT", "IDBC", "TYPEMAINTENANCE") AS
(
	SELECT
		o.ID,o.LANCEPAR,o.CIBLE,o.REMARQUE,o.LIBELLE,o.BESOIN,o.DATY,o.ETAT,o.IDBC,
		p.idtypemaintenance AS typemaintenance
	FROM ORDRETRAVAUX o
	LEFT JOIN DEMANDETRAVAUX d ON d.id=o.idbc
	LEFT JOIN PLANNING p ON p.id=d.idplanning
);

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."ORDRETRAVAUXFILLELIB" ("ID", "IDINGREDIENTS", "LIBELLE", "REMARQUE", "IDMERE", "DATYBESOIN", "QTE", "IDUNITE", "QTEFABRIQUE", "QTERESTE", "LIBELLEEXACTE") AS
SELECT
    ofll.ID,
    ofll.IDINGREDIENTS,
    nvl(ofll.LIBELLE,ai.LIBELLE)  AS LIBELLE,
    ofll.REMARQUE,
    ofll.IDMERE,
    ofll.DATYBESOIN,
    ofll.QTE,
    nvl(au.VAL, 'unite') AS IDUNITE,
    fmf.qte AS qteFabrique,
    (ofll.qte-nvl(fmf.qte, 0)) AS qteReste,
    nvl(ofll.LIBELLE,nvl(ai.LIBELLE, ai.LIBELLE)) AS libelleexacte
FROM
    ORDRETRAVAUXFILLE ofll
        LEFT JOIN AS_INGREDIENT_MAINTENANCE ai ON
        ai.ID = ofll.IDINGREDIENTS
        LEFT JOIN AS_UNITE au ON
        au.ID = ofll.IDUNITE
        LEFT JOIN TRAVAUXMEREFILLE fmf ON
        fmf.IDOFFILLE = ofll.ID
            AND fmf.IDINGREDIENTS = ofll.IDINGREDIENTS
            AND fmf.IDBCFILLE = OFLL.IDBCFILLE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."ORGANIGRAMMELIB" ("ID", "DESCE", "VAL", "NOMPERSONNE", "MATRICULE", "POSTE") AS
SELECT o.id,
       o.desce,
       lp.id AS val,
       (lp.nom || ' ') || lp.prenom AS nompersonne,
       lp.matricule,
       pf.desce AS poste
FROM log_personnel_fin_valide lp
         LEFT JOIN organigramme o ON lp.id = o.val
         LEFT JOIN paie_info_personnel pip ON pip.id = lp.id
         LEFT JOIN paie_fonction pf ON pf.id = pip.idfonction
ORDER BY o.desce DESC NULLS LAST;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."OTRAVFILLELIBSTOCK" ("ID", "IDINGREDIENTS", "LIBELLE", "REMARQUE", "IDMERE", "DATYBESOIN", "QTE", "IDUNITE", "QTEFABRIQUE", "QTERESTE", "LIBELLEEXACTE", "PV", "MONTANTENTREE", "MONTANTSORTIE", "POURC") AS
SELECT
    ofll.ID,
    ofll.IDINGREDIENTS,
    nvl(ofll.LIBELLE,ai.LIBELLE)  AS LIBELLE,
    ofll.REMARQUE,
    ofll.IDMERE,
    ob.daty AS  DATYBESOIN,
    ofll.QTE,
    nvl(au.VAL, 'unite') AS IDUNITE,
    cast(nvl(mv.entree,0) as number(30,2)) as qteFabrique,
    cast(ofll.QTE-nvl(mv.ENTREE,0)as number(30,2)) as qteReste,
    nvl(ofll.LIBELLE,nvl(ai.LIBELLE, ai.LIBELLE)) AS libelleexacte,
    0 AS pv,
    cast(0 as number(30,2)) as montantEntree,
    mvt.montantSortie,
    0 AS pourc
FROM
    ORDRETRAVAUXFILLE ofll
        LEFT JOIN AS_INGREDIENT_MAINTENANCE ai ON
        ai.ID = ofll.IDINGREDIENTS
        LEFT JOIN AS_UNITE au ON
        au.ID = ofll.IDUNITE
        left join MVTSTFILLEOFFCATVISEGROUPEDEP mvt on ofll.id=mvt.IDOFf
        left join mvtStockFilleOfEntreePrFini mv on mv.idoff=ofll.id and mv.IDPRODUIT=ofll.IDINGREDIENTS
        LEFT JOIN OFAB ob ON ob.id =  ofll.idmere;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."OTRAVFILLERESTELIB" ("ID", "IDINGREDIENTS", "LIBELLE", "REMARQUE", "IDMERE", "DATYBESOIN", "QTE", "IDUNITE", "QTEFABRIQUE", "QTERESTE") AS
SELECT o."ID",
       o."IDINGREDIENTS",
       o."LIBELLE",
       o."REMARQUE",
       o."IDMERE",
       o."DATYBESOIN",
       o."QTE",
       o."IDUNITE",
       fmf.qte           AS qteFabrique,
       (o.qte - fmf.qte) AS qteReste
FROM TRAVAUXMEREFILLE fmf
         JOIN ORDRETRAVAUXFILLELIB o ON fmf.idof = o.IDMERE AND fmf.IDINGREDIENTS = o.IDINGREDIENTS;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."OTRAVLIB" ("ID", "IDBC", "LANCEPAR", "CIBLE", "REMARQUE", "LIBELLE", "BESOIN", "DATY", "ETAT", "ETATLIB") AS
SELECT ofl.ID,
       ofl.IDBC,
       p1.VAL  AS LANCEPAR,
       p2.VAL  AS CIBLE,
       ofl.REMARQUE,
       ofl.LIBELLE,
       ofl.BESOIN,
       ofl.DATY,
       ofl.ETAT,
       CASE
           WHEN ofl.ETAT=1
               THEN 'CREE'
           WHEN ofl.ETAT=11
               THEN 'VALIDE'
           WHEN ofl.ETAT=0
               THEN 'ANNULE'
           WHEN ofl.ETAT=21
               THEN 'ENTAME'
           WHEN ofl.ETAT=31
               THEN 'BLOQUE'
           WHEN ofl.ETAT=41
               THEN 'TERMINE'
           END AS ETATLIB
FROM ORDRETRAVAUX ofl
         LEFT JOIN ENTITE p1 ON p1.ID = ofl.LANCEPAR
         LEFT JOIN MAGASIN p2 ON p2.ID = ofl.CIBLE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PACKINGLISTACHATFILLELIB" ("ID", "IDMERE", "IDPRODUIT", "DESIGNATION", "QTE", "IDPRODUITLIB") AS
SELECT
    p.ID,
    p.IDMERE,
    p.IDPRODUIT,
    p.DESIGNATION,
    p.QTE,
    ai.LIBELLE as idproduitlib
FROM PACKINGLISTACHATFILLE p
LEFT JOIN AS_INGREDIENTS ai on ai.id = p.IDPRODUIT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PACKINGLISTACHATFILLEUNITE" ("ID", "IDMERE", "IDPRODUIT", "DESIGNATION", "QTE", "IDUNITELIB") AS
(
select pl."ID",pl."IDMERE",pl."IDPRODUIT",pl."DESIGNATION",pl."QTE", u.val as idUniteLib
from PACKINGLISTACHATFILLE pl
         left join as_ingredients as_i on as_i.ID = pl.IDPRODUIT
         left join AS_UNITE u on u.ID = as_i.UNITE
    );

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PACKINGLISTACHATLIB" ("ID", "IDBR", "DATY", "ETAT", "ETATLIB") AS
SELECT p.ID,
       p.IDBR,
       p.DATY,
       p.ETAT,
       case
           when p.etat = 1 then 'CREEE'
           when p.etat = 11 then 'VISEE'
       end as etatlib
FROM PACKINGLISTACHAT p;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PAIEINFOPERSELTPAIECOMPLET2" ("ID", "CODE_RUBRIQUE", "DATE_DEBUT", "DATE_FIN", "MOISREGULARISATION", "ANNEEREGULARISATION", "GAIN", "RETENUE", "QUANTITE", "UNITE", "REMARQUE", "IDPERSONNEL", "VAL", "DESCE", "RANG", "COMPTEPCG", "CODE", "TYPERUBRIQUE", "BCS", "BG", "IMPOSABLE", "NATURE", "AVANTAGE", "CPT_GEN_DB", "CPT_GEN_CR", "CPT_ANA_DB", "CPT_ANA_CR", "ISRAPPEL", "ISCONFELTFIXE", "MOIS", "ANNEE", "DATESAISIE", "MATRICULE", "LIEU_NAISSANCE_COMMUNE", "LIEU_DELIVRANCE_CIN", "SITUATION_MATRIMONIAL", "INITIALE", "CTURGENCE_NOM_PRENOM", "CTURGENCE_TELEPHONE1", "CTURGENCE_TELEPHONE2", "CTURGENCE_TELEPHONE3", "IDCONJOINT", "CODE_AGENCE_BANQUE", "BANQUE_NUMERO_COMPTE", "BANQUE_COMPTE_CLE", "DATEEMBAUCHE", "IDFONCTION", "IDGROUPEFONCTION", "IDCATEGORIE", "MODE_PAIEMENT", "CLASSEE", "INDICEGRADE", "INDICE_FONCTIONNEL", "MATRICULE_PATRON", "STATUT", "DROIT_HS", "ETAT_ELEMENT", "NATIONALITE", "SERVICE", "DIRECTION", "DATEAPPLICATION", "DATEFININVALID", "DATE_DECISION", "IDTYPEDEBAUCHE", "NBENFANT", "ID_OBJET", "ETAT", "TEMPORAIRE", "PERIODE_ESSAI", "POINTINDICE", "REMARQUE_ELEMENT", "FORMU", "REGROUPEMENT", "ARRONDI", "INSERTED", "SOMMABLE", "BENEFICIAIRE", "REMARQUEFORMULE", "UNITEFORMULE", "QTEFORMULE", "IDCATEGORIE_PAIE", "IDQUALIFICATION", "IDDEPARTEMENT") AS
SELECT elt.id,
       elt.code_rubrique,
       elt.date_debut,
       elt.date_fin,
       elt.moisregularisation,
       elt.anneeregularisation,
       elt.gain,
       elt.retenue,
       elt.quantite,
       elt.unite,
       r.isinfini AS remarque,
       elt.idpersonnel,
       r.val,
       r.desce,
       r.rang,
       r.comptepcg,
       r.code,
       r.typerubrique,
       r.bcs,
       r.bg,
       r.imposable,
       r.nature,
       r.avantage,
       r.cpt_gen_db,
       r.cpt_gen_cr,
       r.cpt_ana_db,
       r.cpt_ana_cr,
       0 AS israppel,
       1 AS isconfeltfixe,
       EXTRACT(MONTH FROM elt.date_debut) AS mois,
       EXTRACT(YEAR FROM elt.date_debut) AS annee,
       info.datesaisie,
       info.matricule,
       info.lieu_naissance_commune,
       info.lieu_delivrance_cin,
       info.situation_matrimonial,
       info.initiale,
       info.cturgence_nom_prenom,
       info.cturgence_telephone1,
       info.cturgence_telephone2,
       info.cturgence_telephone3,
       info.idconjoint,
       info.code_agence_banque,
       info.banque_numero_compte,
       info.banque_compte_cle,
       info.dateembauche,
       info.idfonction,
       fonc.idgroupefonction,
       info.idcategorie,
       info.mode_paiement,
       info.classee,
       info.indicegrade,
       info.indice_fonctionnel,
       info.matricule_patron,
       info.statut,
       info.droit_hs,
       elt.etat AS etat_element,
       info.nationalite,
       info.service,
       info.direction,
       invalid.dateapplication,
       invalid.datefin AS datefininvalid,
       invalid.date_decision,
       invalid.idtypedebauche,
       info.nbenfant,
       elt.id_objet,
       info.etat,
       info.temporaire,
       info.periode_essai,
       c.valmin AS pointindice,
       elt.remarque AS remarque_element,
       formu.id AS formu,
       r.regroupement,
       r.arrondi,
       r.inserted,
       r.sommable,
       r.beneficiaire,
       r.remarque AS remarqueformule,
       r.uniteformule,
       r.qteformule,
       info.idcategorie_paie,
       info.idqualification,
       info.IDDEPARTEMENT
FROM paie_personnel_elementpaie elt
         JOIN paie_rubrique r ON elt.code_rubrique = r.id
         LEFT JOIN paie_info_personneldirect info ON elt.idpersonnel = info.id
         LEFT JOIN paie_fonction fonc ON info.idfonction = fonc.id AND info.id <> '1002067'
         LEFT JOIN dernier_debauche_by_employe invalid ON invalid.idlogpers = info.id
         LEFT JOIN configuration c ON c.id = 'CONF000250'
         LEFT JOIN detformu formu ON elt.id = formu.mere;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PAIEINFOPERSELTPAIECOMPLET4" ("ID", "CODE_RUBRIQUE", "DATE_DEBUT", "DATE_FIN", "MOISREGULARISATION", "ANNEEREGULARISATION", "GAIN", "RETENUE", "QUANTITE", "UNITE", "REMARQUE", "IDPERSONNEL", "VAL", "DESCE", "RANG", "COMPTEPCG", "CODE", "TYPERUBRIQUE", "BCS", "BG", "IMPOSABLE", "NATURE", "AVANTAGE", "CPT_GEN_DB", "CPT_GEN_CR", "CPT_ANA_DB", "CPT_ANA_CR", "ISRAPPEL", "ISCONFELTFIXE", "MOIS", "ANNEE", "DATESAISIE", "MATRICULE", "LIEU_NAISSANCE_COMMUNE", "LIEU_DELIVRANCE_CIN", "SITUATION_MATRIMONIAL", "INITIALE", "CTURGENCE_NOM_PRENOM", "CTURGENCE_TELEPHONE1", "CTURGENCE_TELEPHONE2", "CTURGENCE_TELEPHONE3", "IDCONJOINT", "CODE_AGENCE_BANQUE", "BANQUE_NUMERO_COMPTE", "BANQUE_COMPTE_CLE", "DATEEMBAUCHE", "IDFONCTION", "IDGROUPEFONCTION", "IDCATEGORIE", "MODE_PAIEMENT", "CLASSEE", "INDICEGRADE", "INDICE_FONCTIONNEL", "MATRICULE_PATRON", "STATUT", "DROIT_HS", "ETAT_ELEMENT", "NATIONALITE", "SERVICE", "DIRECTION", "DATEAPPLICATION", "DATEFININVALID", "DATE_DECISION", "IDTYPEDEBAUCHE", "NBENFANT", "ID_OBJET", "ETAT", "TEMPORAIRE", "PERIODE_ESSAI", "POINTINDICE", "REMARQUE_ELEMENT", "FORMU", "REGROUPEMENT", "ARRONDI", "INSERTED", "SOMMABLE", "BENEFICIAIRE", "REMARQUEFORMULE", "UNITEFORMULE", "QTEFORMULE", "IDCATEGORIE_PAIE", "IDQUALIFICATION", "IDDEPARTEMENT") AS
SELECT
    MIN(p.id) AS id,
    p.code_rubrique,
    p.date_debut,
    p.date_fin,
    MAX(p.moisregularisation) AS moisregularisation,
    MAX(p.anneeregularisation) AS anneeregularisation,
    SUM(p.gain) AS gain,
    SUM(p.retenue) AS retenue,
    SUM(p.quantite) AS quantite,
    MAX(p.unite) AS unite,
    MAX(p.remarque) AS remarque,
    p.idpersonnel,
    MAX(p.val) AS val,
    MAX(p.desce) AS desce,
    MAX(p.rang) AS rang,
    MAX(p.comptepcg) AS comptepcg,
    MAX(p.code) AS code,
    p.typerubrique,
    MAX(p.bcs) AS bcs,
    MAX(p.bg) AS bg,
    MAX(p.imposable) AS imposable,
    MAX(p.nature) AS nature,
    MAX(p.avantage) AS avantage,
    MAX(p.cpt_gen_db) AS cpt_gen_db,
    MAX(p.cpt_gen_cr) AS cpt_gen_cr,
    MAX(p.cpt_ana_db) AS cpt_ana_db,
    MAX(p.cpt_ana_cr) AS cpt_ana_cr,
    MAX(p.israppel) AS israppel,
    MAX(p.isconfeltfixe) AS isconfeltfixe,
    MAX(p.mois) AS mois,
    MAX(p.annee) AS annee,
    MAX(p.datesaisie) AS datesaisie,
    MAX(p.matricule) AS matricule,
    MAX(p.lieu_naissance_commune) AS lieu_naissance_commune,
    MAX(p.lieu_delivrance_cin) AS lieu_delivrance_cin,
    MAX(p.situation_matrimonial) AS situation_matrimonial,
    MAX(p.initiale) AS initiale,
    MAX(p.cturgence_nom_prenom) AS cturgence_nom_prenom,
    MAX(p.cturgence_telephone1) AS cturgence_telephone1,
    MAX(p.cturgence_telephone2) AS cturgence_telephone2,
    MAX(p.cturgence_telephone3) AS cturgence_telephone3,
    MAX(p.idconjoint) AS idconjoint,
    MAX(p.code_agence_banque) AS code_agence_banque,
    MAX(p.banque_numero_compte) AS banque_numero_compte,
    MAX(p.banque_compte_cle) AS banque_compte_cle,
    MAX(p.dateembauche) AS dateembauche,
    MAX(p.idfonction) AS idfonction,
    MAX(p.idgroupefonction) AS idgroupefonction,
    MAX(p.idcategorie) AS idcategorie,
    MAX(p.mode_paiement) AS mode_paiement,
    MAX(p.classee) AS classee,
    MAX(p.indicegrade) AS indicegrade,
    MAX(p.indice_fonctionnel) AS indice_fonctionnel,
    MAX(p.matricule_patron) AS matricule_patron,
    MAX(p.statut) AS statut,
    MAX(p.droit_hs) AS droit_hs,
    MAX(p.etat_element) AS etat_element,
    MAX(p.nationalite) AS nationalite,
    MAX(p.service) AS service,
    MAX(p.direction) AS direction,
    MAX(p.dateapplication) AS dateapplication,
    MAX(p.datefininvalid) AS datefininvalid,
    MAX(p.date_decision) AS date_decision,
    MAX(p.idtypedebauche) AS idtypedebauche,
    MAX(p.nbenfant) AS nbenfant,
    MAX(p.id_objet) AS id_objet,
    MAX(p.etat) AS etat,
    MAX(p.temporaire) AS temporaire,
    MAX(p.periode_essai) AS periode_essai,
    MAX(p.pointindice) AS pointindice,
    MAX(p.remarque_element) AS remarque_element,
    MAX(p.formu) AS formu,
    MAX(p.regroupement) AS regroupement,
    MAX(p.arrondi) AS arrondi,
    MAX(p.inserted) AS inserted,
    MAX(p.sommable) AS sommable,
    MAX(p.beneficiaire) AS beneficiaire,
    MAX(p.remarqueformule) AS remarqueformule,
    MAX(p.uniteformule) AS uniteformule,
    MAX(p.qteformule) AS qteformule,
    MAX(p.idcategorie_paie) AS idcategorie_paie,
    MAX(p.idqualification) AS idqualification,
    MAX(p.IDDEPARTEMENT) AS iddepartement
FROM PAIEINFOPERSELTPAIECOMPLET2 p
GROUP BY
    p.idpersonnel,
    p.code_rubrique,
    p.date_debut,
    p.date_fin,
    p.typerubrique;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PAIEPERS_ELP_CPL" ("ID", "MATRICULE", "ID_CODE_RUBRIQUE", "NOMRUBRIQUE", "DATE_DEBUT", "DATE_FIN", "GAIN", "RETENUE", "REMARQUE", "NOMPERSONNEL", "ETAT", "ID_OBJET", "IDUSER", "MOISREGULARISATION", "ANNEEREGULARISATION", "IDCATEGORIE_QUALIFICATION", "IDFONCTION", "POURCENTAGE", "IDPERSONNEL", "ETATLIB") AS
SELECT
    ppe.id,
    pip2.matricule,
    pr.id as id_code_rubrique,
    pr.val AS nomRubrique,
    ppe.date_debut,
    ppe.date_fin,
    ppe.gain,
    ppe.retenue,
    ppe.remarque,
    pip.nom || ' ' || pip.prenom AS nomPersonnel,
    ppe.etat,
    ppe.id_objet,
    ppe.iduser,
    ppe.moisregularisation,
    ppe.anneeregularisation,
    cq.idcategorielib || ' ' || cq.categorie_qualificationlib AS idcategorie_qualification,
    pf.desce AS idfonction,
    ppe.pourcentage,
    ppe.idpersonnel,
    CASE
        WHEN ppe.etat = 1 THEN 'CREE'
        WHEN ppe.etat = 11 THEN 'VISEE'
        ELSE 'INCONNU'
        END AS etatLib
FROM paie_personnel_elementpaie ppe
         LEFT JOIN log_personnel pip ON TO_CHAR(pip.id) = TO_CHAR(ppe.idpersonnel)
         LEFT JOIN categorie_qualification_libc cq ON TO_CHAR(ppe.idcategorie_qualification) = TO_CHAR(cq.id)
         LEFT JOIN paie_fonction pf ON TO_CHAR(ppe.idfonction) = TO_CHAR(pf.id)
         LEFT JOIN paie_rubrique pr ON TO_CHAR(pr.id) = TO_CHAR(ppe.code_rubrique)
         JOIN paie_info_personnel pip2 ON TO_CHAR(pip.id) = TO_CHAR(pip2.id);

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PAIEPERS_ELTFILLE" ("ID", "IDPERSONNEL", "PERSONNELLIB", "MATRICULE", "MONTANT", "REMARQUE", "IDDEPARTEMENT", "IDDIRECTION") AS
SELECT
    '' as ID,
    v.ID as idPersonnel,
    v.NOM || ' ' || v.PRENOM as personnelLib,
    v.MATRICULE,
    0 as montant,
    null as remarque,
    v.IDDEPARTEMENT,
    v.IDDIRECTION
FROM LOG_PERSONNEL_V2 v;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PAIE_AVANCEMENT_LIBELLE2" ("ID", "MOTIF", "IDMOTIF", "ID_LOGPERS", "MATRICULE", "IDPERS", "DATEDECISION", "REFDECISION", "DATE_APPLICATION", "DIRECTION", "SERVICE", "IDFONCTION", "CTG", "IDCATEGORIE", "ECHELON", "CLASSEE", "INDICEGRADE", "INDICE_FONCTIONNEL", "STATUT", "VEHICULEE", "REMARQUE", "SEXE", "ETAT", "MATRICULE_PATRON", "DROIT_HS", "INDICE_CT", "CODE_BANQUE", "FONCTIONLIB", "ETATLIB") AS
SELECT pav.id,
	       dt.val AS motif,
	       dt.id AS idmotif,
	       (lp.nom || ' ') || lp.prenom AS id_logpers,
	       lpad(pip.matricule, 5, '0') AS matricule,
	       pip.id AS idpers,
	       pav.datedecision,
	       pav.refdecision,
	       pav.date_application,
	       ld.val AS direction,
	       ls.code_service AS service,
	       pf.id AS idfonction,
	       pav.ctg,
	       pg.val AS idcategorie,
	       pav.echelon,
	       pav.classee,
	       pav.indicegrade,
	       pav.indice_fonctionnel,
	       CASE
	           WHEN pip.temporaire = -1 THEN 'Temporaire'
	           WHEN pip.temporaire = 0 THEN 'Permanent'
	           WHEN pip.temporaire = 1 THEN 'Cadre'
	           ELSE NULL
	           END AS statut,
	       pav.vehiculee,
	       pav.remarque,
	       lp.sexe,
	       pav.etat,
	       pav.matricule_patron,
	       pav.droit_hs,
	       pav.indice_ct,
	       pav.code_banque,
	       pf.desce AS fonctionLib,
	       CASE
	           WHEN pav.etat = 1 THEN 'NON VALIDE'
	           WHEN pav.etat = 11 THEN 'VALIDEE'
	           ELSE 'AUTRE'
	           END AS etatLib
	FROM paie_avancement pav
	         LEFT JOIN dec_decision_type dt ON dt.id = pav.motif
	         JOIN log_personnel lp ON lp.id = pav.id_logpers
	         LEFT JOIN paie_info_personnel pip ON pip.id = pav.id_logpers
	         LEFT JOIN log_direction ld ON ld.id = pav.direction
	         LEFT JOIN log_service ls ON ls.id = pav.service
	         LEFT JOIN paie_fonction pf ON pf.id = pav.idfonction
	         LEFT JOIN paie_categorie pg ON pg.id = pav.idcategorie;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PAIE_AVANCEMENT_LIBELLE4" ("ID", "MOTIF", "IDMOTIF", "ID_LOGPERS", "MATRICULE", "IDPERS", "DATEDECISION", "REFDECISION", "DATE_APPLICATION", "DIRECTION", "SERVICE", "IDFONCTION", "CTG", "IDCATEGORIE", "ECHELON", "CLASSEE", "INDICEGRADE", "INDICE_FONCTIONNEL", "STATUT", "VEHICULEE", "REMARQUE", "SEXE", "ETAT", "MATRICULE_PATRON", "DROIT_HS", "INDICE_CT", "REGION", "REGIONLIB", "VEHICULEE_STR", "CODE_BANQUE", "FONCTIONLIB", "IDTYPEAVANCEMENT", "IDTYPEAVANCEMENTLIB", "MODEPAIEMENT", "MODEPAIEMENTLIB", "UNITE", "UNITELIB") AS
SELECT pav.id,
       dt.val AS motif,
       dt.id AS idmotif,
       (lp.nom || ' ') || lp.prenom AS id_logpers,
       lpad(pip.matricule, 5, '0') AS matricule,
       pip.id AS idpers,
       pav.datedecision,
       pav.refdecision,
       pav.date_application,
       ld.val AS direction,
       ls.libelle AS service,
       pf.val AS idfonction,
       pav.ctg,
       pg.val AS idcategorie,
       pav.echelon,
       pav.classee,
       pav.indicegrade,
       pav.indice_fonctionnel,
       pav.statut,
       pav.vehiculee,
       pav.remarque,
       lp.sexe,
       pav.etat,
       pav.matricule_patron,
       pav.droit_hs,
       pav.indice_ct,
       pav.region,
       rg.val AS regionlib,
       CASE pav.vehiculee
           WHEN 0 THEN 'non'
           WHEN 1 THEN 'oui'
           ELSE NULL
           END AS vehiculee_str,
       pav.code_banque,
       pf.desce AS fonctionLib,
       pav.idTypeAvancement,
        ta.val as idTypeAvancementLib,
        pav.modepaiement,
        mp.val as MODEPAIEMENTLIB,
        pav.unite,
        lu.val as unitelib
FROM paie_avancement pav
         LEFT JOIN dec_decision_type dt ON dt.id = pav.motif
         LEFT JOIN log_personnel lp ON lp.id = pav.id_logpers
         LEFT JOIN paie_info_personnel pip ON pip.id = pav.id_logpers
         LEFT JOIN log_direction ld ON ld.id = pav.direction
         LEFT JOIN log_service ls ON ls.id = pav.service
         LEFT JOIN paie_fonction pf ON pf.id = pav.idfonction
         LEFT JOIN region rg ON rg.id = pav.region
         LEFT JOIN paie_categorie pg ON pg.id = pav.idcategorie
         LEFT JOIN TYPE_AVANCEMENT ta ON ta.id = pav.idTypeAvancement
        LEFT JOIN MODEPAIEMENT mp ON mp.id = pav.MODEPAIEMENT
        LEFT JOIN LOG_UNITE lu ON lu.id = pav.unite;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PAIE_EDITIONMOISANNEE_LIB" ("ID", "IDPERSONNEL", "MOIS", "ANNEE", "GAIN", "RETENUE", "IDUSER", "IDDIRECTION", "DATY", "MOIS_STRING", "ETAT", "MONTANT") AS
SELECT pae.id,
       (log.nom || ' ') || log.prenom AS idpersonnel,
       pae.mois,
       pae.annee,
       pae.gain,
       pae.retenue,
       u.nomuser AS iduser,
       dir.val AS iddirection,
       pae.daty,
       CASE
           WHEN pae.mois = 1 THEN 'Janvier'
           WHEN pae.mois = 2 THEN 'Fevrier'
           WHEN pae.mois = 3 THEN 'Mars'
           WHEN pae.mois = 4 THEN 'Avril'
           WHEN pae.mois = 5 THEN 'Mai'
           WHEN pae.mois = 6 THEN 'Juin'
           WHEN pae.mois = 7 THEN 'Juillet'
           WHEN pae.mois = 8 THEN 'Aout'
           WHEN pae.mois = 9 THEN 'Septembre'
           WHEN pae.mois = 10 THEN 'Octobre'
           WHEN pae.mois = 11 THEN 'Novembre'
           WHEN pae.mois = 12 THEN 'Decembre'
           WHEN pae.mois = 13 THEN '13eme MOIS'
           WHEN pae.mois = 14 THEN '13eme MOIS BIS'
           ELSE NULL
           END AS mois_string,
       pae.etat,
       CAST(round(net.montant, 2) AS NUMBER(15,2)) AS montant
FROM paie_editionmoisannee pae
         LEFT JOIN log_personnel log ON log.id_pers = pae.idpersonnel
         LEFT JOIN log_direction dir ON dir.id = pae.iddirection
         LEFT JOIN utilisateur u ON u.refuser = pae.iduser
         LEFT JOIN net_moisannee net ON pae.mois = net.mois AND pae.annee = net.annee
ORDER BY pae.annee DESC, pae.mois DESC;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PAIE_EDITIONMOISANNEE_LIB_2" ("ID", "IDPERSONNEL", "MOIS", "ANNEE", "GAIN", "RETENUE", "IDUSER", "IDDIRECTION", "DATY", "MOIS_STRING", "ETAT", "MONTANT") AS
SELECT pae.id,
       (log.nom || ' ') || log.prenom AS idpersonnel,
       pae.mois,
       pae.annee,
       pae.gain,
       pae.retenue,
       u.nomuser AS iduser,
       dir.val AS iddirection,
       pae.daty,
       CASE
           WHEN pae.mois = 1 THEN 'Janvier'
           WHEN pae.mois = 2 THEN 'Fevrier'
           WHEN pae.mois = 3 THEN 'Mars'
           WHEN pae.mois = 4 THEN 'Avril'
           WHEN pae.mois = 5 THEN 'Mai'
           WHEN pae.mois = 6 THEN 'Juin'
           WHEN pae.mois = 7 THEN 'Juillet'
           WHEN pae.mois = 8 THEN 'Aout'
           WHEN pae.mois = 9 THEN 'Septembre'
           WHEN pae.mois = 10 THEN 'Octobre'
           WHEN pae.mois = 11 THEN 'Novembre'
           WHEN pae.mois = 12 THEN 'Decembre'
           WHEN pae.mois = 13 THEN '13eme MOIS'
           WHEN pae.mois = 14 THEN '13eme MOIS BIS'
           ELSE NULL
           END AS mois_string,
       pae.etat,
       CAST(ROUND(net.montant, 0) AS NUMBER(15, 0)) AS montant
FROM paie_editionmoisannee pae
         LEFT JOIN log_personnel log ON log.id_pers = pae.idpersonnel
         LEFT JOIN log_direction dir ON dir.id = pae.iddirection
         LEFT JOIN utilisateur u ON u.refuser = pae.iduser
         LEFT JOIN net_moisannee net ON pae.mois = net.mois AND pae.annee = net.annee
ORDER BY pae.annee DESC, pae.mois DESC;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PAIE_EDITIONMOISANNEE_LIB_3" ("ID", "IDPERSONNEL", "MOIS", "ANNEE", "GAIN", "RETENUE", "IDUSER", "IDDIRECTION", "DATY", "MOIS_STRING", "ETAT", "IDPERIODEPAIE", "DATEDEBUT", "DATEFIN", "MONTANT", "CATEGORIE") AS
SELECT pae.id,
       (log.nom || ' ') || log.prenom AS idpersonnel,
       pae.mois,
       pae.annee,
       pae.gain,
       pae.retenue,
       u.nomuser AS iduser,
       dir.val AS iddirection,
       pae.daty,
       TO_CHAR(

               TO_DATE(TO_CHAR(pae.mois, 'FM00'), 'MM'),

               'FMMonth',

               'NLS_DATE_LANGUAGE=FRENCH'

       ) AS mois_string,
       pae.etat,
       pae.idperiodepaie,
       pp.datedebut,
       pp.datefin,
       CAST(ROUND(net.montant, 0) AS NUMBER(15, 0)) AS montant,
       cps.val AS categorie

FROM paie_editionmoisannee pae
         LEFT JOIN log_personnel log ON log.id_pers = pae.idpersonnel
         LEFT JOIN log_direction dir ON dir.id = pae.iddirection
         LEFT JOIN utilisateur u ON u.refuser = pae.iduser
         LEFT JOIN net_moisannee net ON pae.mois = net.mois AND pae.annee = net.annee
         LEFT JOIN periodepaie pp ON pp.id = pae.id
         LEFT JOIN categorie_paie_salaire cps ON cps.id = pp.idcategoriepaie
ORDER BY pae.annee DESC, pae.mois DESC;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PAIE_EDITION_CNAPS" ("IDPERSONNEL", "MOIS", "ANNEE", "BRUT", "CNAPS_TRAVAILLEUR", "CNAPS_EMPLOYEUR") AS
SELECT
    pe.idpersonnel,
    pe.mois,
    pe.annee,
    ROUND(SUM(pe.gain), 2) AS brut,
    NVL(edc.cnaps_travailleur, 0) AS cnaps_travailleur,
    CASE
        WHEN NVL(edc.cnaps_travailleur, 0) = 0 THEN 0
        ELSE
            CASE
                WHEN (
                         SELECT plafond
                         FROM conf_cnaps
                         WHERE conf_cnaps.daty >= pe.datefin
                           AND ROWNUM = 1
                     ) < (SUM(pe.gain) * 0.13) THEN (
                    SELECT plafond
                    FROM conf_cnaps
                    WHERE conf_cnaps.daty >= pe.datefin
                      AND ROWNUM = 1
                )
                ELSE ROUND(LEAST(NVL(edc.cnaps_travailleur, 0) * 13, SUM(pe.gain) * 0.13), 2)
                END
        END AS cnaps_employeur
FROM paie_edition pe
         JOIN paie_rubrique pr
              ON pe.idelementpaie = pr.id
                  AND pr.typerubrique = 'G'
                  AND pr.imposable = 'I'
         LEFT JOIN (
    SELECT
        pe_1.idpersonnel,
        pe_1.mois,
        pe_1.annee,
        pe_1.retenue AS cnaps_travailleur
    FROM paie_edition pe_1
    WHERE pe_1.idelementpaie = 'PR000101'
) edc
                   ON pe.idpersonnel = edc.idpersonnel
                       AND pe.mois = edc.mois
                       AND pe.annee = edc.annee
GROUP BY
    pe.idpersonnel, pe.mois, pe.annee, edc.cnaps_travailleur,  pe.datefin;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PAIE_EDITION_ECRITURE_LIGNE" ("IDPERSONNEL", "IDELEMENTPAIE", "MOIS", "ANNEE", "GAIN", "RETENUE", "DATEDEBUT", "IDEDITION", "COMPTEGEN_DB", "COMPTEGEN_CR", "COMPTEANA_DB", "COMPTEANA_CR", "TYPERUBRIQUE", "RUBRIQUE_LIBELLE", "IDDIRECTION", "CODE", "IMPOSABLE") AS
SELECT pe.idpersonnel,
       pe.idelementpaie,
       pema.mois,
       pema.annee,
       pe.gain,
       pe.retenue,
       pe.datedebut,
       pe.idedition,
       pe.comptegen_db,
       pe.comptegen_cr,
       pe.compteana_db,
       pe.compteana_cr,
       pr.typerubrique,
       pr.val AS rubrique_libelle,
       pema.iddirection,
       pr.code,
       pr.imposable
FROM paie_edition pe
         JOIN paie_rubrique pr ON pr.id = pe.idelementpaie
         JOIN paie_info_personnel pip ON pip.id = pe.idpersonnel
         JOIN paie_editionmoisannee pema ON pema.id = pe.idedition;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PAIE_EDITION_ELTPAIE" ("ID", "IDPERSONNEL", "IDELEMENTPAIE", "IDEDITION", "MOIS", "ANNEE", "DROITS", "RETENUES", "DATEDEBUT", "DATEFIN", "REMARQUE", "ELEMENT", "CODE", "RANG", "RUBRIQUEDESCE", "IMPOSABLE", "RANGBULLETIN", "AFFICHER", "HEURENORMAL", "HEURESUPNORMAL", "HEURESUPNUIT", "HEURESUPFERIE", "HEURESUPWEEKEND", "ABSENCE", "SALAIREBASE") AS
SELECT
    ed.id,
    ed.idpersonnel,
    ed.idelementpaie,
    ed.idedition,
    ed.mois,
    ed.annee,
    ed.gain AS droits,
    ed.retenue AS retenues,
    ed.datedebut,
    ed.datefin,
    ed.remarque,
    r.val AS element,
    r.code,
    r.rang,
    r.desce AS rubriquedesce,
    r.imposable,
    r.rangbulletin,
    r.afficher,
    p.HEURENORMAL,
    p.HEURESUPNORMAL,
    p.HEURESUPNUIT,
    p.HEURESUPFERIE,
    p.HEURESUPWEEKEND,
    p.ABSENCE,
    c.montant AS salairebase
FROM paie_edition ed
         LEFT JOIN paie_rubrique r
                   ON ed.idelementpaie = r.id
         LEFT JOIN pointage p
                   ON p.idpersonnel = ed.idpersonnel
                       AND p.mois = ed.mois
                       AND p.annee = ed.annee
                       AND p.etat = 11
         LEFT JOIN categorie_qualification c
                   ON c.remarque = ed.idpersonnel;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PAIE_EDITION_GAIN_IMP" ("IDPERSONNEL", "MOIS", "ANNEE", "IMPOSABLE") AS
SELECT paie_edition.idpersonnel,
       paie_edition.mois,
       paie_edition.annee,
       CAST(sum(paie_edition.gain) AS NUMBER(15,2)) AS imposable
FROM paie_edition
WHERE (paie_edition.idelementpaie IN ( SELECT paie_rubrique.id
                                       FROM paie_rubrique
                                       WHERE paie_rubrique.typerubrique = 'G' AND paie_rubrique.imposable = 'I' AND paie_rubrique.id NOT LIKE  '%AV%'))
GROUP BY paie_edition.idpersonnel, paie_edition.mois, paie_edition.annee;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PAIE_EDITION_GRP_PERSONNE2" ("GAIN", "IDPERSONNEL") AS
SELECT (grp2.gain + sfrm.montant) AS gain,
       grp2.idpersonnel
FROM ( SELECT CAST(sum(paie_edition.gain) AS NUMBER(15,2)) AS gain,
              paie_edition.idpersonnel
       FROM paie_edition
       WHERE paie_edition.idelementpaie NOT LIKE  '%PR000FRM%' AND paie_edition.annee > 2023
       GROUP BY paie_edition.idpersonnel) grp2
         LEFT JOIN solde_frm_2023 sfrm ON grp2.idpersonnel = sfrm.idpersonnel;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PAIE_EDITION_LIBCOMPLET" ("ID", "IDPERSONNEL", "IDELEMENTPAIE", "MOIS", "ANNEE", "GAIN", "RETENUE", "DATEDEBUT", "DATEFIN", "IDEDITION", "REMARQUE", "IDPERSONNELLIB", "IDELEMENTPAIELIB", "MATRICULE", "CODERUBRIQUE", "MOISLIB") AS
SELECT pe.id,
       pe.idpersonnel,
       pe.idelementpaie,
       pe.mois,
       pe.annee,
       pe.gain,
       pe.retenue,
       pe.datedebut,
       pe.datefin,
       pe.idedition,
       pe.remarque,
       (lp.nom || ' ') || lp.prenom AS idpersonnellib,
       (pr.code || ' ') || pr.val AS idelementpaielib,
       lp.matricule,
       pr.code AS coderubrique,
       TO_CHAR(
               TO_DATE(TO_CHAR(pe.mois, 'FM00'), 'MM'),
               'FMMonth',
               'NLS_DATE_LANGUAGE=FRENCH'
       ) AS moisLib
FROM paie_edition pe
         LEFT JOIN log_personnel_infocomplet lp ON lp.id = pe.idpersonnel
         LEFT JOIN paie_rubrique pr ON pr.id = pe.idelementpaie
         LEFT JOIN paie_editionmoisannee p ON pe.idedition = p.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PAIE_FONCTIONLIBELLE" ("ID", "VAL", "DESCE", "IDGROUPEFONCTION") AS
SELECT p.id,
       p.val,
       p.desce,
       pg.val AS idgroupefonction
FROM paie_fonction p
         LEFT JOIN paie_groupefonction pg ON p.idgroupefonction = pg.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PAIE_INFO_EMBAUCHE" ("ID", "DATESAISIE", "MATRICULE", "LIEU_NAISSANCE_COMMUNE", "LIEU_DELIVRANCE_CIN", "SITUATION_MATRIMONIAL", "INITIALE", "CTURGENCE_NOM_PRENOM", "CTURGENCE_TELEPHONE1", "CTURGENCE_TELEPHONE2", "CTURGENCE_TELEPHONE3", "IDCONJOINT", "CODE_AGENCE_BANQUE", "BANQUE_NUMERO_COMPTE", "BANQUE_COMPTE_CLE", "DATEEMBAUCHE", "IDFONCTION", "IDCATEGORIE", "MODE_PAIEMENT", "CLASSEE", "INDICEGRADE", "INDICE_FONCTIONNEL", "MATRICULE_PATRON", "STATUT", "DROIT_HS", "VEHICULEE", "ECHELON", "ETAT", "CTG", "IDUSER", "INDICE_CT", "DATEPROMOTION", "NUMERO_CNAPS", "NUMERO_OSTIE", "TEMPORAIRE", "N_EMBAUCHE", "DATE_DEPART", "N_DEPART", "NBENFANT", "HEUREJOURNALIER", "HEUREHEBDOMADAIRE", "HEUREMENSUEL", "DIRECTION") AS
