CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PAIE_INFO_PERSONNEL_ENFANT" ("ID", "MATRICULE", "CTURGENCE_NOM_PRENOM", "NBENFANT") AS
SELECT pip.id,
       pip.matricule,
       (((lp.nom || ' ') || lp.prenom)) AS cturgence_nom_prenom,
       pip.nbenfant
