CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PAIE_INFO_PERSONNEL_HISTORIC_3" ("ID", "IDPERSONNEL", "DATESAISIE", "MATRICULE", "LIEU_NAISSANCE_COMMUNE", "LIEU_DELIVRANCE_CIN", "SITUATION_MATRIMONIAL", "INITIALE", "CTURGENCE_NOM_PRENOM", "CTURGENCE_TELEPHONE1", "CTURGENCE_TELEPHONE2", "CTURGENCE_TELEPHONE3", "IDCONJOINT", "CODE_AGENCE_BANQUE", "BANQUE_NUMERO_COMPTE", "BANQUE_COMPTE_CLE", "DATEEMBAUCHE", "IDFONCTION", "IDCATEGORIE", "MODE_PAIEMENT", "CLASSEE", "INDICEGRADE", "INDICE_FONCTIONNEL", "MATRICULE_PATRON", "STATUT", "DROIT_HS", "VEHICULEE", "ECHELON", "ETAT", "CTG", "IDUSER", "INDICE_CT", "DATEPROMOTION", "NUMERO_CNAPS", "NUMERO_OSTIE", "TEMPORAIRE", "N_EMBAUCHE", "DATE_DEPART", "N_DEPART", "NBENFANT", "HEUREJOURNALIER", "HEUREHEBDOMADAIRE", "HEUREMENSUEL", "INDESIRABLE", "DUREE", "TELEPHONE", "MAIL", "ADRESSE_LIGNE1", "ADRESSE_LIGNE2", "CODE_POSTAL", "REGION", "IDCATEGORIE_PAIE", "IDQUALIFICATION", "FORMATION", "DISCIPLINE", "ANNEEEXPERIENCE", "PERSONNEL_ETAT", "PERIODE_ESSAI", "PERMIS_CONDUIRE", "CHEMIN_PERMIS", "REMARQUE", "ID_PERS", "NOM", "PRENOM", "DATE_NAISSANCE", "SEXE", "SEXEPDF", "PRONOMPERSONNELSUJET", "GENREPDF", "NUMERO_CIN", "DATE_CIN", "DATE_DUPL_CIN", "NATIONALITE", "ADRESSE", "FOKOTANY", "ACTE_NAISSANCE", "DIRECTION", "SERVICE", "MONTANT", "CATEGORIE_QUALIFICATIONLIB", "CATEGORIE_PAIELIB", "DATE_DEBUT", "DATE_FIN", "AVENANT", "FONCTIONLIB", "DEBUTCONTRAT", "FINCONTRAT", "NUMERO") AS
SELECT
    pip.matricule || cq.numero AS id,
    pip.id AS idpersonnel,
    pip.datesaisie,
    pip.matricule,
    pip.lieu_naissance_commune,
    pip.lieu_delivrance_cin,
    pip.situation_matrimonial,
    pip.initiale,
    pip.cturgence_nom_prenom,
    pip.cturgence_telephone1,
    pip.cturgence_telephone2,
    pip.cturgence_telephone3,
    pip.idconjoint,
    pip.code_agence_banque,
    pip.banque_numero_compte,
    pip.banque_compte_cle,
    pip.dateembauche,
    pip.idfonction,
    pip.idcategorie,
    pip.mode_paiement,
    pip.classee,
    pip.indicegrade,
    pip.indice_fonctionnel,
    pip.matricule_patron,
    pip.statut,
    pip.droit_hs,
    pip.vehiculee,
    pip.echelon,
    pip.etat,
    pip.ctg,
    pip.iduser,
    pip.indice_ct,
    pip.datepromotion,
    pip.numero_cnaps,
    pip.numero_ostie,
    pip.temporaire,
    pip.n_embauche,
    pip.date_depart,
    pip.n_depart,
    pip.nbenfant,
    pip.heurejournalier,
    pip.heurehebdomadaire,
    pip.heuremensuel,
    pip.indesirable,
    pip.duree,
    pip.telephone,
    pip.mail,
    pip.adresse_ligne1,
    pip.adresse_ligne2,
    pip.code_postal,
    pip.region,
    pip.idcategorie_paie,
    pip.idqualification,
    pip.formation,
    pip.discipline,
    pip.anneeexperience,
    pip.personnel_etat,
    pip.periode_essai,
    pip.permis_conduire,
    pip.chemin_permis,
    pip.remarque,
    pip.id_pers,
    pip.nom,
    pip.prenom,
    pip.date_naissance,
    pip.sexe,
    CASE
        WHEN pip.sexe = '0' THEN 'Madame'
        ELSE 'Monsieur'
        END AS sexepdf,
    CASE
        WHEN pip.sexe = '0' THEN 'elle'
        ELSE 'il'
        END AS pronompersonnelsujet,
    CASE
        WHEN pip.sexe = '0' THEN 'Elle'
        ELSE 'Il'
        END AS genrepdf,
    pip.numero_cin,
    pip.date_cin,
    pip.date_dupl_cin,
    pip.nationalite,
    pip.adresse,
    pip.fokotany,
    pip.acte_naissance,
    pip.direction,
    pip.service,
    cq.montant,
    qp.val AS categorie_qualificationlib,
    cp.val AS categorie_paielib,
    cq.date_debut,
    cq.date_fin,
    cq.avenant,
    pf.desce AS fonctionlib,
    pip.debutcontrat,
    pip.fincontrat,
    cq.numero
FROM
    categ_quali_contrat_2 cq
        LEFT JOIN paie_info_personnel_libcomplet pip ON pip.id = cq.remarque
        LEFT JOIN categorie_paie cp ON cp.id = pip.idcategorie_paie
        LEFT JOIN qualification_paie qp ON qp.id = pip.idqualification
        LEFT JOIN paie_fonction pf ON pf.id = pip.idfonction;

