CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PAIE_MODEPAIEMENT" ("ID", "VAL", "DESCE") AS
SELECT 
"ID","VAL","DESCE"
FROM MODEPAIEMENT m 
WHERE m.id IN ('0001',
'0002',
'0003');

