       ppe.retenue,
       ppe.remarque,
       (pip.nom || ' ') || pip.prenom AS idpersonnel,
       ppe.etat,
       ppe.id_objet,
       ppe.iduser,
       ppe.moisregularisation,
       ppe.anneeregularisation,
       (cq.idcategorielib || ' ') || cq.categorie_qualificationlib AS idcategorie_qualification,
       pf.val AS idfonction,
       ppe.pourcentage
FROM paie_personnel_elementpaie ppe
         LEFT JOIN log_personnel pip ON pip.id = ppe.idpersonnel
         LEFT JOIN categ_quali_libcomplet cq ON ppe.idcategorie_qualification = cq.id
         LEFT JOIN paie_fonction pf ON ppe.idfonction = pf.id
         LEFT JOIN paie_rubrique pr ON pr.id = ppe.code_rubrique;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PAIE_PERS_ELTPAIE_LIB2" ("ID", "MATRICULE", "ID_CODE_RUBRIQUE", "CODE_RUBRIQUE", "DATE_DEBUT", "DATE_FIN", "GAIN", "RETENUE", "REMARQUE", "IDPERSONNEL", "ETAT", "ID_OBJET", "IDUSER", "MOISREGULARISATION", "ANNEEREGULARISATION", "RUBRIQUE", "MOISLIB", "IDCATEGORIE_QUALIFICATION", "IDFONCTION", "POURCENTAGE", "ETATLIB") AS
SELECT
    ppe.id,
    pip2.matricule,
    pr.id AS id_code_rubrique,
    pr.val AS code_rubrique,
    ppe.date_debut,
    ppe.date_fin,
    ppe.gain,
    ppe.retenue,
    ppe.remarque,
    pip.nom || ' ' || pip.prenom AS idpersonnel,
    ppe.etat,
    ppe.id_objet,
    ppe.iduser,
    ppe.moisregularisation,
    ppe.anneeregularisation,
    pr.VAL as rubrique,

    TO_CHAR(
            TO_DATE(TO_CHAR(ppe.moisregularisation, 'FM00'), 'MM'),
            'FMMonth',
            'NLS_DATE_LANGUAGE=FRENCH'
    ) AS moisLib,

    cq.idcategorielib || ' ' || cq.categorie_qualificationlib AS idcategorie_qualification,
    pf.desce AS idfonction,
    ppe.pourcentage,

    CASE
        WHEN ppe.etat = '1' THEN 'CREE'
        WHEN ppe.etat = '11' THEN 'VALIDE'
        WHEN ppe.etat = '0' THEN 'ANNULE'
        ELSE 'INCONNU'
        END AS etatlib

FROM paie_personnel_elementpaie ppe
         LEFT JOIN log_personnel pip
                   ON TO_CHAR(pip.id) = TO_CHAR(ppe.idpersonnel)
         LEFT JOIN categorie_qualification_libc cq
                   ON TO_CHAR(ppe.idcategorie_qualification) = TO_CHAR(cq.id)
         LEFT JOIN paie_fonction pf
                   ON TO_CHAR(ppe.idfonction) = TO_CHAR(pf.id)
         LEFT JOIN paie_rubrique pr
                   ON TO_CHAR(pr.id) = TO_CHAR(ppe.code_rubrique)
         JOIN paie_info_personnel pip2
              ON TO_CHAR(pip.id) = TO_CHAR(pip2.id) WHERE ppe.CODE_RUBRIQUE!='PR0000150HS';

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PAIE_PERS_ELTPAIE_LIB_AV" ("ID", "MATRICULE", "ID_CODE_RUBRIQUE", "CODE_RUBRIQUE", "DATE_DEBUT", "DATE_FIN", "GAIN", "RETENUE", "REMARQUE", "IDPERSONNEL", "ETAT", "ID_OBJET", "IDUSER", "MOISREGULARISATION", "ANNEEREGULARISATION", "IDCATEGORIE_QUALIFICATION", "IDFONCTION", "POURCENTAGE", "MOISREGULARISATIONLIB") AS
SELECT
    pp."ID",
    pp."MATRICULE",
    pp."ID_CODE_RUBRIQUE",
    pp."CODE_RUBRIQUE",
    pp."DATE_DEBUT",
    pp."DATE_FIN",
    pp."GAIN",
    pp."RETENUE",
    pp."REMARQUE",
    pp."IDPERSONNEL",
    pp."ETAT",
    pp."ID_OBJET",
    pp."IDUSER",
    pp."MOISREGULARISATION",
    pp."ANNEEREGULARISATION",
    pp."IDCATEGORIE_QUALIFICATION",
    pp."IDFONCTION",
    pp."POURCENTAGE",
    -- Libelle du mois
    TO_CHAR(TO_DATE(pp.MOISREGULARISATION, 'MM'), 'MONTH', 'NLS_DATE_LANGUAGE=FRENCH')
        AS MOISREGULARISATIONLIB
FROM PAIE_PERS_ELTPAIE_LIB2 pp
WHERE pp.ID_CODE_RUBRIQUE = 'PRU0447';

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PAIE_PERS_ELTPAIE_LIB_IND" ("ID", "MATRICULE", "CODE_RUBRIQUE", "DATE_DEBUT", "DATE_FIN", "GAIN", "RETENUE", "REMARQUE", "IDPERSONNEL", "ETAT", "ETATLIB", "ID_OBJET", "IDUSER", "MOISREGULARISATION", "ANNEEREGULARISATION", "IDCATEGORIE_QUALIFICATION", "IDFONCTION", "POURCENTAGE", "MOISREGULARISATIONLIB") AS
SELECT ID,
       MATRICULE,
       CODE_RUBRIQUE,
       DATE_DEBUT,
       DATE_FIN,
       GAIN,
       RETENUE,
       REMARQUE,
       IDPERSONNEL,
       ETAT,
       ETATLIB,
       ID_OBJET,
       IDUSER,
       MOISREGULARISATION,
       ANNEEREGULARISATION,
       IDCATEGORIE_QUALIFICATION,
       IDFONCTION,
       POURCENTAGE,
       -- Libelle du mois
       TO_CHAR(TO_DATE(pp.MOISREGULARISATION, 'MM'), 'MONTH', 'NLS_DATE_LANGUAGE=FRENCH')
           AS MOISREGULARISATIONLIB
FROM PAIE_PERS_ELTPAIE_LIB2 pp
WHERE pp.id_code_rubrique = 'PR000021';

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PARQUET_BATIMENT_LIB" ("ID", "VAL", "IDBATIMENT") AS
SELECT DISTINCT
       bd.IDPARQUET   AS ID,
       p.VAL          AS VAL,
       bd.IDMERE      AS IDBATIMENT
FROM BATIMENTDETAIL bd
JOIN PARQUET p ON p.ID = bd.IDPARQUET;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PARTICIPATION_FORMATION_LIB" ("ID", "IDACTIONFORMATION", "IDPERSONNEL", "DATEINSCRIPTION", "REMARQUE", "ETAT", "PERSONNEL", "MATRICULE", "CATEGORIEEMPLOYE", "IDACTIONFORMATIONLIB", "ETATLIB") AS
SELECT
    pf.ID,pf.IDACTIONFORMATION,pf.IDPERSONNEL,pf.DATEINSCRIPTION,pf.REMARQUE,pf.ETAT,
    lp.nom || ' '|| lp.prenom as personnel,
    pip.matricule,
    cp.val AS categorieEmploye,
    af.intitule AS idActionFormationLib,
    CASE
        WHEN pf.etat = 1 THEN 'INSCRIT'
        WHEN pf.etat = 11 THEN 'VALIDE'
        ELSE 'INCONNU'
        END AS etatLib
FROM PARTICIPATION_FORMATION pf
         LEFT JOIN PAIE_INFO_PERSONNEL pip
                   ON pip.id = pf.idpersonnel
         LEFT JOIN CATEGORIE_PAIE cp
                   ON pip.idcategorie_paie = cp.id
         LEFT JOIN ACTION_FORMATION af
                   ON af.id = pf.idactionformation
        LEFT JOIN log_personnel_v2 lp ON pip.id = lp.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PERIODEPAIELIB" ("ID", "MOIS", "DATEDEBUT", "DATEFIN", "IDCATEGORIEPAIE", "ANNEE", "ETAT", "MOISLIB", "CATEGORIELIB") AS
SELECT
    p.id,
    p.mois,
    p.datedebut,
    p.datefin,
    p.idcategoriepaie,
    p.annee,
    p.etat,
    TO_CHAR(
            TO_DATE(TO_CHAR(p.mois, 'FM00'), 'MM'),
            'FMMonth',
            'NLS_DATE_LANGUAGE=FRENCH'
    ) AS moisLib,
    categ.VAL as categorieLib
FROM PERIODEPAIE p
         LEFT JOIN CATEGORIE_PAIE categ on categ.id = p.IDCATEGORIEPAIE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PERSONNELDEMAINTENANCE" ("ID", "NOM", "PRENOM", "SERVICE", "SERVICELIB") AS
SELECT
    lp.id,
    nom,
    prenom,
    service,
    ls.libelle AS serviceLib
FROM log_personnel lp
         LEFT JOIN LOG_SERVICE ls ON lp.service = ls.id
WHERE
    service LIKE 'SERVM%';

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PERSONNEL_MATRICULE" ("ID", "NOM", "MAIL", "TELEPHONE", "ADRESSE", "REMARQUE", "COMPTE") AS
SELECT p.id, p.NOM, p.MAIL, pip.MATRICULE AS TELEPHONE , p.ADRESSE, p.REMARQUE, p.COMPTE FROM PERSONNEL p 
JOIN PAIE_INFO_PERSONNEL pip 
ON pip.id  = p.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PERSONNEMAINTENANCECPL" ("ID", "NOM", "TELEPHONE", "MAIL", "ADRESSE", "REMARQUE", "COMPTE", "IDDEPARTEMENT", "IDDEPARTEMENTLIB", "IDDEPARTEMENTDESCE") AS
select p."ID",p."NOM",p."TELEPHONE",p."MAIL",p."ADRESSE",p."REMARQUE",p."COMPTE",p."IDDEPARTEMENT", dm.VAL as iddepartementlib, dm.DESCE as iddepartementdesce from PERSONNEL p
                                                                                left join DEPARTEMENTMAINTENANCE dm on p.IDDEPARTEMENT = dm.ID
where p.IDDEPARTEMENT is not null;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PERSONNE_GAIN_SORTIE_RESTE" ("ID", "DATESAISIE", "MATRICULE", "LIEU_NAISSANCE_COMMUNE", "LIEU_DELIVRANCE_CIN", "SITUATION_MATRIMONIAL", "INITIALE", "CTURGENCE_NOM_PRENOM", "CTURGENCE_TELEPHONE1", "CTURGENCE_TELEPHONE2", "CTURGENCE_TELEPHONE3", "IDCONJOINT", "CODE_AGENCE_BANQUE", "BANQUE_NUMERO_COMPTE", "BANQUE_COMPTE_CLE", "DATEEMBAUCHE", "IDFONCTION", "IDCATEGORIE", "MODE_PAIEMENT", "CLASSEE", "INDICEGRADE", "INDICE_FONCTIONNEL", "MATRICULE_PATRON", "STATUT", "DROIT_HS", "VEHICULEE", "ECHELON", "ETAT", "CTG", "IDUSER", "INDICE_CT", "DATEPROMOTION", "NUMERO_CNAPS", "NUMERO_OSTIE", "TEMPORAIRE", "N_EMBAUCHE", "DATE_DEPART", "N_DEPART", "NBENFANT", "HEUREJOURNALIER", "HEUREHEBDOMADAIRE", "HEUREMENSUEL", "INDESIRABLE", "DUREE", "TELEPHONE", "MAIL", "ADRESSE_LIGNE1", "ADRESSE_LIGNE2", "CODE_POSTAL", "REGION", "IDCATEGORIE_PAIE", "IDQUALIFICATION", "FORMATION", "DISCIPLINE", "ANNEEEXPERIENCE", "PERSONNEL_ETAT", "PERIODE_ESSAI", "PERMIS_CONDUIRE", "CHEMIN_PERMIS", "REMARQUE", "ID_PERS", "NOM", "PRENOM", "DATE_NAISSANCE", "SEXE", "NUMERO_CIN", "DATE_CIN", "DATE_DUPL_CIN", "NATIONALITE", "ADRESSE", "FOKOTANY", "ACTE_NAISSANCE", "DIRECTION", "SERVICE", "GAIN", "MONTANT", "RESTE") AS
SELECT pip.id,
       pip.datesaisie,
       pip.matricule,
       pip.lieu_naissance_commune,
       pip.lieu_delivrance_cin,
       pip.situation_matrimonial,
       pip.initiale,
       pip.cturgence_nom_prenom,
       pip.cturgence_telephone1,
       pip.cturgence_telephone2,
       pip.cturgence_telephone3,
       pip.idconjoint,
       pip.code_agence_banque,
       pip.banque_numero_compte,
       pip.banque_compte_cle,
       pip.dateembauche,
       pip.idfonction,
       pip.idcategorie,
       pip.mode_paiement,
       pip.classee,
       pip.indicegrade,
       pip.indice_fonctionnel,
       pip.matricule_patron,
       pip.statut,
       pip.droit_hs,
       pip.vehiculee,
       pip.echelon,
       pip.etat,
       pip.ctg,
       pip.iduser,
       pip.indice_ct,
       pip.datepromotion,
       pip.numero_cnaps,
       pip.numero_ostie,
       pip.temporaire,
       pip.n_embauche,
       pip.date_depart,
       pip.n_depart,
       pip.nbenfant,
       pip.heurejournalier,
       pip.heurehebdomadaire,
       pip.heuremensuel,
       pip.indesirable,
       pip.duree,
       pip.telephone,
       pip.mail,
       pip.adresse_ligne1,
       pip.adresse_ligne2,
       pip.code_postal,
       pip.region,
       pip.idcategorie_paie,
       pip.idqualification,
       pip.formation,
       pip.discipline,
       pip.anneeexperience,
       pip.personnel_etat,
       pip.periode_essai,
       pip.permis_conduire,
       pip.chemin_permis,
       pip.remarque,
       pip.id_pers,
       pip.nom,
       pip.prenom,
       pip.date_naissance,
       pip.sexe,
       pip.numero_cin,
       pip.date_cin,
       pip.date_dupl_cin,
       pip.nationalite,
       pip.adresse,
       pip.fokotany,
       pip.acte_naissance,
       pip.direction,
       pip.service,
       COALESCE(pep.gain, 0) AS gain,
       COALESCE(pe.montant, 0) AS montant,
       COALESCE(pep.gain, 0) - COALESCE(pe.montant, 0) AS reste
FROM paie_info_personnel_libcomplet pip
         LEFT JOIN paie_edition_grp_personne2 pep ON pip.id = pep.idpersonnel
         LEFT JOIN retrait_frais_medic_grppers pe ON pe.idpersonnel = pip.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PERTEGAINIMPREVUELIB" ("ID", "DESIGNATION", "IDTYPEGAINPERTE", "PERTE", "GAIN", "IDORIGINE", "DATY", "ETAT", "TVA", "TIERS", "TYPE", "COMPTE", "MONTANTTVA", "MONTANTHT", "MONTANTTTC", "TIERSLIB", "TIERSCOMPTE", "COMPTEAUXILIAIRE") AS
SELECT pgi.ID,pgi.DESIGNATION,pgi.IDTYPEGAINPERTE,pgi.PERTE,pgi.GAIN,pgi.IDORIGINE,pgi.DATY,pgi.ETAT,pgi.TVA,pgi.TIERS,
       tgp.val                                                                             AS TYPE,
       tgp.desce                                                                           AS compte,
       case when perte > 0 then perte * tva / 100 else gain * tva / 100 end                as montanttva,
       case when perte > 0 then perte else gain end                                        as montantht,
       case when perte > 0 then perte + perte * tva / 100 else gain + gain * tva / 100 end as montantttc,
       t.nom as TIERSLIB,
       t.COMPTE as tierscompte,
       t.COMPTEAUXILIAIRE
FROM pertegainimprevue pgi
         LEFT JOIN typegainperte tgp on pgi.idtypegainperte = tgp.id
         LEFT JOIN tiers t on t.id = pgi.tiers;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PERTEGAINIMPREVUELIB_A" ("ID", "DESIGNATION", "IDTYPEGAINPERTE", "PERTE", "GAIN", "IDORIGINE", "DATY", "ETAT", "TVA", "TIERS", "TYPE", "COMPTE", "MONTANTTVA", "MONTANTHT", "MONTANTTTC", "TIERSLIB", "TIERSCOMPTE") AS
SELECT "ID","DESIGNATION","IDTYPEGAINPERTE","PERTE","GAIN","IDORIGINE","DATY","ETAT","TVA","TIERS","TYPE","COMPTE","MONTANTTVA","MONTANTHT","MONTANTTTC","TIERSLIB","TIERSCOMPTE" FROM pertegainimprevuelib WHERE etat=0;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PERTEGAINIMPREVUELIB_C" ("ID", "DESIGNATION", "IDTYPEGAINPERTE", "PERTE", "GAIN", "IDORIGINE", "DATY", "ETAT", "TVA", "TIERS", "TYPE", "COMPTE", "MONTANTTVA", "MONTANTHT", "MONTANTTTC", "TIERSLIB", "TIERSCOMPTE") AS
SELECT "ID","DESIGNATION","IDTYPEGAINPERTE","PERTE","GAIN","IDORIGINE","DATY","ETAT","TVA","TIERS","TYPE","COMPTE","MONTANTTVA","MONTANTHT","MONTANTTTC","TIERSLIB","TIERSCOMPTE" FROM pertegainimprevuelib WHERE etat=1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PERTEGAINIMPREVUELIB_NP" ("ID", "DESIGNATION", "IDTYPEGAINPERTE", "PERTE", "GAIN", "IDORIGINE", "DATY", "ETAT", "TVA", "TIERS", "TYPE", "COMPTE", "MONTANTTVA", "MONTANTHT", "MONTANTTTC", "TIERSLIB", "TIERSCOMPTE") AS
SELECT "ID","DESIGNATION","IDTYPEGAINPERTE","PERTE","GAIN","IDORIGINE","DATY","ETAT","TVA","TIERS","TYPE","COMPTE","MONTANTTVA","MONTANTHT","MONTANTTTC","TIERSLIB","TIERSCOMPTE" FROM pertegainimprevuelib_V p
where NOT EXISTS (SELECT idorigine FROM MOUVEMENTCAISSE m WHERE m.idorigine=p.id );

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PERTEGAINIMPREVUELIB_P" ("ID", "DESIGNATION", "IDTYPEGAINPERTE", "PERTE", "GAIN", "IDORIGINE", "DATY", "ETAT", "TVA", "TIERS", "TYPE", "COMPTE", "MONTANTTVA", "MONTANTHT", "MONTANTTTC", "TIERSLIB", "TIERSCOMPTE") AS
SELECT "ID","DESIGNATION","IDTYPEGAINPERTE","PERTE","GAIN","IDORIGINE","DATY","ETAT","TVA","TIERS","TYPE","COMPTE","MONTANTTVA","MONTANTHT","MONTANTTTC","TIERSLIB","TIERSCOMPTE" FROM pertegainimprevuelib_V p
where  EXISTS (SELECT idorigine FROM MOUVEMENTCAISSE m WHERE m.idorigine=p.id );

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PERTEGAINIMPREVUELIB_V" ("ID", "DESIGNATION", "IDTYPEGAINPERTE", "PERTE", "GAIN", "IDORIGINE", "DATY", "ETAT", "TVA", "TIERS", "TYPE", "COMPTE", "MONTANTTVA", "MONTANTHT", "MONTANTTTC", "TIERSLIB", "TIERSCOMPTE") AS
SELECT "ID","DESIGNATION","IDTYPEGAINPERTE","PERTE","GAIN","IDORIGINE","DATY","ETAT","TVA","TIERS","TYPE","COMPTE","MONTANTTVA","MONTANTHT","MONTANTTTC","TIERSLIB","TIERSCOMPTE" FROM pertegainimprevuelib WHERE etat=11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PERTE_GRPORIGINE_FACT" ("IDORIGINE", "TAUX", "MONTANT", "MONTANTAR", "IDBCDETAIL") AS
select lf.id1 as idorigine, FFC.taux, sum(ffc.MONTANTHT) as montant, sum(ffc.montantHTAr) as montantar,LISTAGG(id2, ';;') WITHIN GROUP (ORDER BY id2) AS idbcDetail
from LIAISONFACTUREFOURNISSEURS lf
         LEFT JOIN FactFournisseurCalc FFC on FFC.id = lf.id2
    where not exists (select 1 from perteGainUtilise p where p.VAL=lf.ID2)
group by lf.id1, FFC.taux;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PESEEPOUSSINDETAIL_LIB" ("ID", "IDMERE", "POIDS", "NOMBREOISEAUX", "POIDSNOMBRE", "DANSPLAGEUNIFORMITE", "POURCENTAGEOISEAUX") AS
SELECT d."ID",d."IDMERE",d."POIDS",d."NOMBREOISEAUX",
       (d."POIDS" * d."NOMBREOISEAUX")                  AS "POIDSNOMBRE",
       CASE WHEN d."POIDS" >= m."LIMITEBASSEUNIFORMITE"
           AND d."POIDS" <= m."LIMITEHAUTEUNIFORMITE"
                THEN 'Oui' ELSE 'Non' END                   AS "DANSPLAGEUNIFORMITE",
       CASE WHEN m."NOMBREOISEAUXPESES" > 0
                THEN d."NOMBREOISEAUX" / m."NOMBREOISEAUXPESES" * 100
            ELSE NULL END                                AS "POURCENTAGEOISEAUX"
FROM "PESEEPOUSSINDETAIL" d
         LEFT JOIN "PESEEPOUSSIN_LIB" m ON m."ID" = d."IDMERE";

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PESEEPOUSSIN_LIB" ("ID", "DATEPESEE", "IDTYPEPESEE", "IDRESPONSABLE", "IDFERME", "IDBATIMENT", "IDLOT", "IDPARQUET", "IDSEXE", "REMARQUE", "ETAT", "IDTYPEPESEELIB", "IDRESPONSABLELIB", "IDFERMELIB", "IDBATIMENTLIB", "IDLOTLIB", "IDPARQUETLIB", "IDSOUCHELIB", "IDSEXELIB", "DATEECLOSION", "AGEJOUR", "AGESEMAINE", "NOMBREOISEAUXPESES", "POIDSTOTAL", "POIDSMOYEN", "ECARTTYPE", "COEFFICIENTVARIATION", "LIMITEBASSEUNIFORMITE", "LIMITEHAUTEUNIFORMITE", "NOMBREOISEAUXDANSPLAGE", "UNIFORMITE", "ETATLIB") AS
WITH agg AS (
    SELECT "IDMERE",
           SUM("NOMBREOISEAUX")                       AS NOMBREOISEAUXPESES,
           SUM("POIDS" * "NOMBREOISEAUX")              AS POIDSTOTAL,
           SUM("NOMBREOISEAUX" * "POIDS" * "POIDS")     AS SUM_N_P2,
           SUM("NOMBREOISEAUX" * "POIDS")               AS SUM_N_P
    FROM "PESEEPOUSSINDETAIL"
    GROUP BY "IDMERE"
),
stats AS (
    SELECT "IDMERE",
           NOMBREOISEAUXPESES,
           POIDSTOTAL,
           CASE WHEN NOMBREOISEAUXPESES > 0
                THEN POIDSTOTAL / NOMBREOISEAUXPESES
                ELSE NULL END AS POIDSMOYEN,
           CASE WHEN NOMBREOISEAUXPESES > 1
                THEN SQRT( (SUM_N_P2 - (POWER(SUM_N_P,2) / NOMBREOISEAUXPESES)) / (NOMBREOISEAUXPESES - 1) )
                ELSE NULL END AS ECARTTYPE
    FROM agg
),
stats2 AS (
    SELECT s.*,
           CASE WHEN POIDSMOYEN IS NOT NULL AND POIDSMOYEN <> 0
                THEN (ECARTTYPE / POIDSMOYEN) * 100
                ELSE NULL END AS COEFFICIENTVARIATION,
           POIDSMOYEN * 0.90 AS LIMITEBASSEUNIFORMITE,
           POIDSMOYEN * 1.10 AS LIMITEHAUTEUNIFORMITE
    FROM stats s
),
plage AS (
    SELECT s2."IDMERE",
           SUM(CASE WHEN d."POIDS" >= s2.LIMITEBASSEUNIFORMITE
                     AND d."POIDS" <= s2.LIMITEHAUTEUNIFORMITE
                    THEN d."NOMBREOISEAUX" ELSE 0 END) AS NOMBREOISEAUXDANSPLAGE
    FROM stats2 s2
    JOIN "PESEEPOUSSINDETAIL" d ON d."IDMERE" = s2."IDMERE"
    GROUP BY s2."IDMERE"
)
SELECT p."ID",p."DATEPESEE",p."IDTYPEPESEE",p."IDRESPONSABLE",p."IDFERME",p."IDBATIMENT",p."IDLOT",p."IDPARQUET",p."IDSEXE",p."REMARQUE",p."ETAT",
       tp."VAL"                                        AS "IDTYPEPESEELIB",
       lp."NOM" || ' ' || lp."PRENOM"                   AS "IDRESPONSABLELIB",
       fm."VAL"                                         AS "IDFERMELIB",
       b."NOMBATIMENT"                                          AS "IDBATIMENTLIB",
       l."NOMLOT"                                       AS "IDLOTLIB",
       pq."VAL"                                         AS "IDPARQUETLIB",
       pz."IDSOUCHELIB"                                 AS "IDSOUCHELIB",
       sx."VAL"                                         AS "IDSEXELIB",
       l."DATEECLOSION"                                 AS "DATEECLOSION",
       (p."DATEPESEE" - l."DATEECLOSION")                AS "AGEJOUR",
       (p."DATEPESEE" - l."DATEECLOSION") / 7             AS "AGESEMAINE",
       s2.NOMBREOISEAUXPESES                             AS "NOMBREOISEAUXPESES",
       s2.POIDSTOTAL                                     AS "POIDSTOTAL",
       s2.POIDSMOYEN                                     AS "POIDSMOYEN",
       s2.ECARTTYPE                                      AS "ECARTTYPE",
       s2.COEFFICIENTVARIATION                           AS "COEFFICIENTVARIATION",
       s2.LIMITEBASSEUNIFORMITE                          AS "LIMITEBASSEUNIFORMITE",
       s2.LIMITEHAUTEUNIFORMITE                          AS "LIMITEHAUTEUNIFORMITE",
       pl.NOMBREOISEAUXDANSPLAGE                         AS "NOMBREOISEAUXDANSPLAGE",
       CASE WHEN s2.NOMBREOISEAUXPESES > 0
                THEN pl.NOMBREOISEAUXDANSPLAGE / s2.NOMBREOISEAUXPESES * 100
            ELSE NULL END                                AS "UNIFORMITE",
       CASE p."ETAT"
           WHEN 1  THEN 'CREE'
           WHEN 11 THEN 'VALIDEE'
           END                                                AS "ETATLIB"
FROM "PESEEPOUSSIN" p
         LEFT JOIN "TYPEPESEE" tp ON tp."ID" = p."IDTYPEPESEE"
         LEFT JOIN "LOG_PERSONNEL" lp ON lp."ID" = p."IDRESPONSABLE"
         LEFT JOIN "MAGASIN2" fm ON fm."ID" = p."IDFERME"
         LEFT JOIN "BATIMENT" b ON b."ID" = p."IDBATIMENT"
         LEFT JOIN "LOT" l ON l."ID" = p."IDLOT"
         LEFT JOIN "PARQUET" pq ON pq."ID" = p."IDPARQUET"
         LEFT JOIN "SEXE" sx ON sx."ID" = p."IDSEXE"
         LEFT JOIN "PROGRAMMEZOOTECHNIQUE_LIB" pz ON pz."ID" = l."IDPROGRAMME"
         LEFT JOIN stats2 s2 ON s2."IDMERE" = p."ID"
         LEFT JOIN plage pl ON pl."IDMERE" = p."ID";

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PIECEMACHINELIB" ("ID", "IDPIECE", "IDMACHINE", "IDPIECELIB", "IDMACHINELIB") AS
SELECT
    pm."ID",pm."IDPIECE",pm."IDMACHINE",
    p.LIBELLE AS IDPIECELIB,
    m.LIBELLE AS IDMACHINELIB
FROM PIECEMACHINE pm
         JOIN AS_INGREDIENT_MAINTENANCE p
              ON p.ID = pm.IDPIECE
         JOIN AS_INGREDIENT_MAINTENANCE m
              ON m.ID = pm.IDMACHINE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PLANFORMATIONANNUELLELIB" ("ID", "ANNEE", "LIBELLE", "ETAT", "ETATLIB", "BUDGETTOTALPREVISIONEL", "DATY") AS
SELECT
    p.ID,
    p.ANNEE,
    p.LIBELLE,
    p.ETAT,
    CASE 
        WHEN p.ETAT = 1 THEN 'Cree'
        WHEN p.ETAT = 11 THEN 'Valide'
        WHEN p.ETAT = 0 THEN 'Annule'
        ELSE 'Inconnu'
    END AS ETATLIB,

    p.BUDGETTOTALPREVISIONEL,
    p.DATY
FROM PLAN_FORMATION_ANNUEL p;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PLANNINGFACTURE" ("ID", "IDCLIENT", "DESIGNATION", "DATY", "MONTANTTOTAL", "MONTANTRESTE", "MONTANTPAYE", "ETATPLANNING", "ETATPAIEMENT") AS
SELECT
    v.ID,
    v.IDCLIENT,
    v.DESIGNATION,
    v.DATYPREVU AS DATY,
    v.MONTANTTTC AS MONTANTTOTAL,
    v.MONTANTRESTE,
    v.MONTANTPAYE,
    CASE
        WHEN v.DATYPREVU < SYSDATE THEN 1
        ELSE 0
        END etatPlanning,
    CASE
        WHEN v.MONTANTRESTE = 0 THEN 1
        ELSE 0
        END etatPaiement
FROM VENTE_CPL v;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PLANNINGFACTURELIB" ("ID", "IDCLIENT", "DESIGNATION", "DATY", "MONTANTTOTAL", "MONTANTRESTE", "MONTANTPAYE", "ETATPLANNING", "ETATPAIEMENT", "ETATPAIEMENTLIB", "IDCLIENTLIB") AS
SELECT p."ID",p."IDCLIENT",p."DESIGNATION",p."DATY",p."MONTANTTOTAL",p."MONTANTRESTE",p."MONTANTPAYE",p."ETATPLANNING",p."ETATPAIEMENT",
       CASE
           WHEN p.etatPaiement = 1 THEN 'Pay&eacute;'
           ELSE 'Impay&eacute;'
           END etatPaiementLib,
       c.NOM AS idClientLib
FROM PLANNINGFACTURE p
         LEFT JOIN CLIENT c ON p.IDCLIENT = c.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PLANNING_CPL" ("ID", "REFOBJET", "ESTPERIODIQUE", "IDTYPEMAINTENANCE", "IDMACHINE", "IDLIGNE", "IDLIGNELIB", "IDSITUATION", "IDSITUATIONLIB", "UNITE", "FREQUENCE", "DATEDEBUT", "DATEFIN", "DUREE", "ETAT", "HEURE", "IDSOURCE", "IDMACHINELIB", "IDTYPEMAINTENANCELIB", "ESTPERIODIQUELIB", "ETATLIB", "UNITELIB", "PRIORITE", "PRIORITELIB", "IDDEMANDETRAVAUX", "IDORDRETRAVAUX", "IDORDRETRAVAUXFILLE", "IDTRAVAUX", "IDENTITE", "IDENTITELIB", "ETATDEMANDETRAVAUX", "ETATORDRETRAVAUX", "ETATTRAVAUX", "ETATDEMANDETRAVAUXLIB", "ETATORDRETRAVAUXLIB", "ETATTRAVAUXLIB", "COUT", "IDDEPARTEMENT", "IDDEPARTEMENTLIB", "MOTSCLESSS") AS
SELECT P.ID,
       P.REFOBJET,
       P.ESTPERIODIQUE,
       P.IDTYPEMAINTENANCE,
       P.IDMACHINE,
       P.IDLIGNE,
       li.VAL as IDLIGNELIB,
       P.IDSITUATION,
       sit.VAL AS IDSITUATIONLIB,
       P.UNITE,
       P.FREQUENCE,
       P.DATEDEBUT,
       P.DATEFIN,
       P.DUREE,
       P.ETAT,
       P.HEURE,
       P.IDSOURCE,
       AI.LIBELLE                         AS IDMACHINELIB,
       T.VAL                              AS IDTYPEMAINTENANCELIB,
       CASE
           WHEN P.ESTPERIODIQUE = 1 THEN 'OUI'
           ELSE 'NON'
           END                               ESTPERIODIQUELIB,
       CASE
           WHEN P.ETAT = 11 THEN 'VALID&Eacute;E'
           ELSE 'CR&Eacute;E'
           END                               ETATLIB,
       U.VAL                              AS UNITELIB,
       D.PRIORITE,
       D.PRIORITELIB,
       D.ID                               AS IDDEMANDETRAVAUX,
       O.ID                               AS IDORDRETRAVAUX,
       OTF.ID                             AS IDORDRETRAVAUXFILLE,
       TR.ID                              AS IDTRAVAUX,
       E.ID                               AS IDENTITE,
       E.VAL                              AS IDENTITELIB,
       D.ETAT                             AS ETATDEMANDETRAVAUX,
       O.ETAT                             AS ETATORDRETRAVAUX,
       TR.ETAT                            AS ETATTRAVAUX,
       CASE D.ETAT
           WHEN 1 THEN 'Creee'
           WHEN 11 THEN 'Visee'
           ELSE 'Aucun'
           END                            AS ETATDEMANDETRAVAUXLIB,
       CASE O.ETAT
           WHEN 1 THEN 'Creee'
           WHEN 11 THEN 'Visee'
           ELSE 'Aucun'
           END                            AS ETATORDRETRAVAUXLIB,
       CASE TR.ETAT
           WHEN 1 THEN 'Creee'
           WHEN 11 THEN 'Visee'
           WHEN 21 THEN 'Entamee'
           WHEN 41 THEN 'Terminee'
           ELSE 'Aucun'
           END                            AS ETATTRAVAUXLIB,
       COALESCE(SUM(FFF.PU * FFF.QTE), 0) AS COUT,
       AI.PARFUMS                         AS IDDEPARTEMENT,
       dept.VAL                            AS IDDEPARTEMENTLIB,
       (
           NVL(TO_CHAR(P.ID), '') || ' | ' ||
           NVL(TO_CHAR(P.REFOBJET), '') || ' | ' ||
           NVL(TO_CHAR(P.ESTPERIODIQUE), '') || ' | ' ||
           NVL(TO_CHAR(P.IDTYPEMAINTENANCE), '') || ' | ' ||
           NVL(TO_CHAR(P.IDMACHINE), '') || ' | ' ||
           NVL(TO_CHAR(P.UNITE), '') || ' | ' ||
           NVL(TO_CHAR(P.FREQUENCE), '') || ' | ' ||
           NVL(TO_CHAR(P.DATEDEBUT, 'YYYY-MM-DD HH24:MI:SS'), '') || ' | ' ||
           NVL(TO_CHAR(P.DATEFIN, 'YYYY-MM-DD HH24:MI:SS'), '') || ' | ' ||
           NVL(TO_CHAR(P.DUREE), '') || ' | ' ||
           NVL(TO_CHAR(P.ETAT), '') || ' | ' ||
           NVL(TO_CHAR(P.HEURE), '') || ' | ' ||
           NVL(TO_CHAR(P.IDSOURCE), '') || ' | ' ||
           NVL(TO_CHAR(AI.LIBELLE), '') || ' | ' ||
           NVL(TO_CHAR(T.VAL), '') || ' | ' ||
           NVL(TO_CHAR(
                       CASE
                           WHEN P.ESTPERIODIQUE = 1 THEN 'OUI'
                           ELSE 'NON'
                           END
               ), '') || ' | ' ||
           NVL(TO_CHAR(
                       CASE
                           WHEN P.ETAT = 11 THEN 'VALID&Eacute;E'
                           ELSE 'CR&Eacute;E'
                           END
               ), '') || ' | ' ||
           NVL(TO_CHAR(U.VAL), '') || ' | ' ||
           NVL(TO_CHAR(D.PRIORITE), '') || ' | ' ||
           NVL(TO_CHAR(D.PRIORITELIB), '') || ' | ' ||
           NVL(TO_CHAR(D.ID), '') || ' | ' ||
           NVL(TO_CHAR(O.ID), '') || ' | ' ||
           NVL(TO_CHAR(OTF.ID), '') || ' | ' ||
           NVL(TO_CHAR(TR.ID), '') || ' | ' ||
           NVL(TO_CHAR(E.ID), '') || ' | ' ||
           NVL(TO_CHAR(E.VAL), '') || ' | ' ||
           NVL(TO_CHAR(D.ETAT), '') || ' | ' ||
           NVL(TO_CHAR(O.ETAT), '') || ' | ' ||
           NVL(TO_CHAR(TR.ETAT), '') || ' | ' ||
           NVL(TO_CHAR(
                       CASE D.ETAT
                           WHEN 1 THEN 'Creee'
                           WHEN 11 THEN 'Visee'
                           ELSE 'Aucun'
                           END
               ), '') || ' | ' ||
           NVL(TO_CHAR(
                       CASE O.ETAT
                           WHEN 1 THEN 'Creee'
                           WHEN 11 THEN 'Visee'
                           ELSE 'Aucun'
                           END
               ), '') || ' | ' ||
           NVL(TO_CHAR(
                       CASE TR.ETAT
                           WHEN 1 THEN 'Creee'
                           WHEN 11 THEN 'Visee'
                           WHEN 21 THEN 'Entamee'
                           WHEN 41 THEN 'Terminee'
                           ELSE 'Aucun'
                           END
               ), '') || ' | ' ||
           NVL(TO_CHAR(COALESCE(SUM(FFF.PU * FFF.QTE), 0)), '') || ' | ' ||
           NVL(TO_CHAR(AI.PARFUMS), '')
           )                              AS MOTSCLESSS
FROM PLANNING P
         LEFT JOIN AS_INGREDIENT_MAINTENANCE AIM ON AIM.ID = P.IDMACHINE
         LEFT JOIN AS_INGREDIENTS AI ON AI.ID = AIM.IDINGREDIENT
         LEFT JOIN TYPEMAINTENANCE T ON T.ID = P.IDTYPEMAINTENANCE
         LEFT JOIN UNITEMAINTENANCE U ON U.ID = P.UNITE
         LEFT JOIN DEMANDETRAVAUX_CPL D ON D.ID = P.IDSOURCE
         LEFT JOIN ORDRETRAVAUX O ON O.IDBC = D.ID
         LEFT JOIN ORDRETRAVAUXFILLE OTF ON OTF.IDMERE = O.ID
         LEFT JOIN TRAVAUX TR ON TR.IDOFFILLE = OTF.ID
         LEFT JOIN TRAVAUXFILLE TRF ON TRF.IDMERE = TR.ID
         LEFT JOIN ENTITE E ON E.ID = AIM.IDENTITE
         LEFT JOIN FACTUREFOURNISSEUR F ON F.IDREF = TR.ID
         LEFT JOIN FACTUREFOURNISSEURFILLE FFF ON FFF.IDFACTUREFOURNISSEUR = F.ID
         LEFT JOIN DEPARTEMENT dept ON dept.ID = AI.PARFUMS
         LEFT JOIN SITUATION sit ON sit.ID = P.IDSITUATION
         LEFT JOIN LIGNE li ON li.ID = P.IDLIGNE
GROUP BY P.ID, P.REFOBJET, P.ESTPERIODIQUE, P.IDTYPEMAINTENANCE, P.IDMACHINE, P.UNITE,
         P.FREQUENCE, P.DATEDEBUT, P.DATEFIN, P.DUREE, P.ETAT, P.HEURE, P.IDSOURCE,
         AI.LIBELLE, T.VAL, U.VAL,
         D.PRIORITE, D.PRIORITELIB, D.ID, D.ETAT,
         O.ID, O.ETAT,
         OTF.ID,
         TR.ID, TR.ETAT,
         E.ID, E.VAL, AI.PARFUMS, dept.VAL, sit.VAL, li.VAL, P.IDLIGNE, P.IDSITUATION
ORDER BY P.DATEDEBUT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PLANNING_CR" ("NOMBREDEMANDE", "NOMBREREALISE", "POURCENTAGE") AS
SELECT
    CAST(NULL AS NUMBER(1)) AS NOMBREDEMANDE,
    CAST(NULL AS NUMBER) AS NOMBREREALISE,
    CAST(NULL AS NUMBER(30, 2)) AS pourcentage
FROM DUAL;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PLANNING_DUREENONPROGRAMME" ("DATEDEBUT", "ID", "IDMACHINELIB", "DUREE", "DUREENONPROGRAMME") AS
SELECT
    PC.DATEDEBUT,
    PC.IDMACHINE AS ID,
    PC.IDMACHINELIB,
    SUM(PC.DUREE) AS DUREE,
    COALESCE((
         SELECT SUM(T.DUREEESTIMATIF)
         FROM TRAVAUX T
                  LEFT JOIN ORDRETRAVAUXFILLE OT ON T.IDOFFILLE = OT.ID
         WHERE T.ETAT = 11
           AND PC.IDMACHINE = OT.IDINGREDIENTS
           AND T.DATY = PC.DATEDEBUT
    ),0) AS DUREENONPROGRAMME
FROM PLANNING_CPL PC
GROUP BY PC.DATEDEBUT, PC.IDMACHINE, PC.IDMACHINELIB;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PLANPAIEMENTACHATLIB" ("ID", "IDFOURNISSEUR", "IDBCF", "IDTYPEDEPART", "DUREE", "TAUX", "IDFOURNISSEURLIB", "IDTYPEDEPARTLIB") AS
SELECT
    p."ID",p."IDFOURNISSEUR",p."IDBCF",p."IDTYPEDEPART",p."DUREE",p."TAUX",
    f.nom as idFournisseurLib,
    t.val as idTypeDepartLib
FROM planPaiementAchat p
LEFT JOIN FOURNISSEUR f ON f.id = p.idFournisseur
LEFT JOIN typeDepart t on p.idTypeDepart = t.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."POINTAGECANTINE_CPL" ("ID", "IDPERSONNEL", "IDDEPARTEMENT", "MOIS", "ANNEE", "NOMBRE", "DATY", "ETAT", "MOISLIB", "NOMPERSONNEL", "MATRICULE", "DEPARTEMENTLIB", "ETATLIB") AS
SELECT
    pt.ID,
    pt.IDPERSONNEL,
    pt.IDDEPARTEMENT,
    pt.MOIS,
    pt.ANNEE,
    pt.NOMBRE,
    pt.DATY,
    pt.ETAT,

    TO_CHAR(
        TO_DATE(TO_CHAR(pt.mois, 'FM00'), 'MM'),
        'FMMonth',
        'NLS_DATE_LANGUAGE=FRENCH'
    ) AS moisLib,

    log.nom || ' ' || log.prenom AS nomPersonnel,
    pip.matricule,
    dp.val AS departementLib,

    CASE
        WHEN pt.etat = 1 THEN 'CREE'
        WHEN pt.etat = 11 THEN 'VALIDE'
        WHEN pt.etat = 0 THEN 'ANNULE'
        ELSE 'INCONNU'
    END AS etatLib

FROM POINTAGECANTINE pt
LEFT JOIN LOG_PERSONNEL log
ON log.id = pt.idpersonnel

LEFT JOIN PAIE_INFO_PERSONNEL pip
ON pip.id = pt.idpersonnel

LEFT JOIN DEPARTEMENT dp
ON dp.id = pt.iddepartement;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."POINTAGEVISEE_VISA_MULTIPLE" ("ID", "IDPERSONNEL", "MATRICULE", "PERSONNEL", "MOISLIB", "MOIS", "ANNEE", "HEURENORMAL", "HEURESUPNORMAL", "HEURESUPNUIT", "HEURESUPFERIE", "HEURESUPWEEKEND", "ABSENCE", "ETAT", "DIRECTION", "DIRECTIONLIB") AS
SELECT pp.id as id,pp.IDPERSONNEL,lpad(pif.matricule, 5, '0') as matricule, lg.nom || ' ' || lg.prenom as personnel,
       case
           when pp.mois=1 then
               'Janvier'
           when pp.mois=2
               then
               'Fevrier'
           when pp.mois=3
               then
               'Mars'
           when pp.mois=4
               then
               'Avril'
           when pp.mois=5
               then
               'Mai'
           when pp.mois=6
               then
               'Juin'
           when pp.mois=7
               then
               'Juillet'
           when pp.mois=8
               then
               'Aout'
           when pp.mois=9
               then
               'Septembre'
           when pp.mois=10
               then
               'Octobre'
           when pp.mois=11
               then
               'Novembre'
           when pp.mois=12
               then
               'Decembre'
           end as moisLib,
       pp.mois as mois,
       pp.annee,
       sum(nvl(pp.HEURENORMAL,0)) as HEURENORMAL,
       sum(nvl(pp.HEURESUPNORMAL,0)) as HEURESUPNORMAL,
       sum(nvl(pp.HEURESUPNUIT,0)) as HEURESUPNUIT,
       sum(nvl(pp.HEURESUPFERIE,0)) as HEURESUPFERIE,
       sum(nvl(pp.HEURESUPWEEKEND,0)) as HEURESUPWEEKEND,
       sum(nvl(pp.ABSENCE,0)) as ABSENCE,
       pp.etat,
       lg.direction,
       ld.VAL AS directionLib
FROM LOG_PERSONNEL lg
         JOIN Pointage pp ON lg.id = pp.idpersonnel
         JOIN paie_info_personnel pif ON pif.id = lg.id
         LEFT JOIN LOG_DIRECTION ld ON ld.id = pp.DIRECTION
GROUP BY lpad(pif.matricule, 5, '0'), lg.nom || ' ' || lg.prenom, pp.mois, pp.annee, pp.etat,pp.ID,pp.IDPERSONNEL,pp.mois,lg.direction, ld.val;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."POINTAGEVISEE_VISA_MULTIPLE_1" ("ID", "IDPERSONNEL", "MATRICULE", "PERSONNEL", "MOISLIB", "MOIS", "ANNEE", "HEURENORMAL", "HEURESUPNORMAL", "HEURESUPNUIT", "HEURESUPFERIE", "HEURESUPWEEKEND", "ABSENCE", "ETAT", "DIRECTION") AS
SELECT
    pp.id AS id,
    pp.IDPERSONNEL,
    pif.matricule AS matricule,
    CAST(lg.nom || ' ' || lg.prenom AS VARCHAR2(4000)) AS personnel,
    CASE
        WHEN pp.mois = 1 THEN 'Janvier'
        WHEN pp.mois = 2 THEN 'Fevrier'
        WHEN pp.mois = 3 THEN 'Mars'
        WHEN pp.mois = 4 THEN 'Avril'
        WHEN pp.mois = 5 THEN 'Mai'
        WHEN pp.mois = 6 THEN 'Juin'
        WHEN pp.mois = 7 THEN 'Juillet'
        WHEN pp.mois = 8 THEN 'Aout'
        WHEN pp.mois = 9 THEN 'Septembre'
        WHEN pp.mois = 10 THEN 'Octobre'
        WHEN pp.mois = 11 THEN 'Novembre'
        WHEN pp.mois = 12 THEN 'Decembre'
        END AS moisLib,
    pp.mois AS mois,
    pp.annee,
    SUM(NVL(pp.HEURENORMAL, 0)) AS HEURENORMAL,
    SUM(NVL(pp.HEURESUPNORMAL, 0)) AS HEURESUPNORMAL,
    SUM(NVL(pp.HEURESUPNUIT, 0)) AS HEURESUPNUIT,
    SUM(NVL(pp.HEURESUPFERIE, 0)) AS HEURESUPFERIE,
    SUM(NVL(pp.HEURESUPWEEKEND, 0)) AS HEURESUPWEEKEND,
    SUM(NVL(pp.ABSENCE, 0)) AS ABSENCE,
    pp.etat,
    lg.direction
FROM
    LOG_PERSONNEL lg
        JOIN
    Pointage pp ON lg.id = pp.idpersonnel
        JOIN
    paie_info_personnel pif ON pif.id = lg.id
GROUP BY
    pif.matricule,
    CAST(lg.nom || ' ' || lg.prenom AS VARCHAR2(4000)),
    pp.mois,
    pp.annee,
    pp.etat,
    pp.ID,
    pp.IDPERSONNEL,
    lg.direction;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."POINTAGE_LIB" ("ID", "IDPERSONNEL", "DIRECTION", "ANNEE", "MOIS", "HEURENORMAL", "HEURESUPFERIE", "HEURESUPNORMAL", "HEURESUPNUIT", "HEURESUPWEEKEND", "ABSENCE", "DATY", "ETAT", "DIRECTIONLIB", "MOISLIB", "MATRICULE", "NOMPERSONNEL") AS
SELECT
    p.ID,
    p.IDPERSONNEL,
    p.direction,
    p.ANNEE,
    p.MOIS,
    p.HEURENORMAL,
    p.HEURESUPFERIE,
    p.HEURESUPNORMAL,
    p.HEURESUPNUIT,
    p.HEURESUPWEEKEND,
    p.ABSENCE,
    p.DATY,
    p.ETAT,
    ld.VAL AS directionLib,
    TO_CHAR(
            TO_DATE(TO_CHAR(p.mois, 'FM00'), 'MM'),
            'FMMonth',
            'NLS_DATE_LANGUAGE=FRENCH'
    ) AS moisLib,
    ec.MATRICULE ,
    ec.nom || ' ' || ec.PRENOM AS nomPersonnel
FROM POINTAGE p
         LEFT JOIN LOG_DIRECTION ld ON ld.id = p.DIRECTION
         LEFT JOIN EMPLOYE_COMPLET ec ON ec.id = p.IDPERSONNEL;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."POINT_ACTIF" ("ID", "VAL", "DESCE", "ACTIF") AS
select "ID","VAL","DESCE","ACTIF" from point where actif = 1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."POMPISTELIB" ("REFUSER", "LOGINUSER", "PWDUSER", "NOMUSER", "ADRUSER", "TELUSER", "IDROLE") AS
SELECT 
    "REFUSER","LOGINUSER","PWDUSER","NOMUSER","ADRUSER","TELUSER","IDROLE"
FROM 
    UTILISATEUR u 
    where
u.IDROLE = 'pompiste';

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PRECISDETENCAISSEMENT_LIB" ("ID", "IDENCAISSEMENT", "IDENCAISSEMENTLIB", "IDCATEGORIECAISSE", "IDCATEGORIECAISSELIB", "IDCLIENT", "IDCLIENTLIB", "MONTANT", "REFERENCE", "DATY", "IDCAISSE") AS
SELECT
	pde.ID ,
	pde.IDENCAISSEMENT ,
	e.DESIGNATION AS IDENCAISSEMENTLIB,
	pde.IDCATEGORIECAISSE ,
	c.VAL AS IDCATEGORIECAISSELIB,
	pde.IDCLIENT ,
	c2.NOM AS IDCLIENTLIB,
	pde.MONTANT ,
	pde.REFERENCE ,
	pde.DATY,
	e.IDCAISSE 
FROM
	PRECISION_DETAIL_ENCAISSEMENT pde
LEFT JOIN ENCAISSEMENT e ON
	e.ID = pde.IDENCAISSEMENT
LEFT JOIN CATEGORIECAISSE c ON
	c.ID = pde.IDCATEGORIECAISSE
LEFT JOIN CLIENT c2 ON
	c2.ID = pde.IDCLIENT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PRELEVEMENTCPL" ("ID", "IDPRELEVEMENTANTERIEUR", "COMPTEUR", "DATY", "HEURE", "IDPOMPISTE", "IDPOMPE", "ETAT", "ETATLIB", "IDCAISSE", "IDMAGASIN", "IDPRODUIT", "PUVENTE", "MAXPOMPE") AS
SELECT 
p.ID ,
p.IDPRELEVEMENTANTERIEUR ,
p.COMPTEUR ,
p.DATY ,
p.HEURE ,
p.IDPOMPISTE ,
p.IDPOMPE ,
p.ETAT ,
CASE 
	WHEN p.ETAT = 0 
	THEN 'ANNULEE'
	WHEN p.ETAT = 1 
	THEN 'CREE'
	WHEN p.ETAT = 11 
	THEN 'VALIDEE'
END AS ETATLIB,
c.ID AS IDCAISSE,
p2.IDMAGASIN ,
p3.ID AS IDPRODUIT , 
p3.PUVENTE,
p2.MAX AS maxPompe
FROM PRELEVEMENT p 
LEFT JOIN CAISSE c ON c.IDPOMPISTE =  p.IDPOMPISTE 
LEFT JOIN POMPE p2 ON p2.ID = p.IDPOMPE 
LEFT JOIN MAGASIN m ON m.ID = p2.IDMAGASIN 
LEFT JOIN PRODUIT p3 ON p3.ID  = m.IDPRODUIT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PRELEVEMENTLIB" ("ID", "IDPRELEVEMENTANTERIEUR", "COMPTEUR", "DATY", "HEURE", "IDPOMPISTE", "IDPOMPE", "NOMUSER", "IDROLE", "NOMMAGASIN", "DESCRIPTIONMAGASIN", "ETAT", "ETATLIB", "DESIGNATION") AS
SELECT 
    p.ID AS ID,
    p.IDPRELEVEMENTANTERIEUR AS IDPRELEVEMENTANTERIEUR,
    p.COMPTEUR AS COMPTEUR,
    CASE 
  		WHEN p.HEURE IS NULL AND p.DATY IS NOT NULL  
  		THEN TO_DATE((TO_CHAR(p.DATY, 'YYYY-MM-DD') ||' '||'00:00'), 'YYYY-MM-DD HH24:MI')  
  		ELSE 
  		TO_DATE((TO_CHAR(p.DATY, 'YYYY-MM-DD') || ' ' || p.HEURE), 'YYYY-MM-DD HH24:MI')
    END AS DATY,
    p.HEURE AS HEURE,
    p.IDPOMPISTE AS IDPOMPISTE,
    p.IDPOMPE AS IDPOMPE,
    u.NOMUSER AS NOMUSER,
    u.IDROLE AS IDROLE,
    m.VAL AS NOMMAGASIN,
    m.DESCE AS DESCRIPTIONMAGASIN,
    p.ETAT ,
CASE 
	WHEN p.ETAT = 0 
	THEN 'ANNULEE'
	WHEN p.ETAT = 1 
	THEN 'CREE'
	WHEN p.ETAT = 11 
	THEN 'VALIDEE'
	WHEN p.ETAT = 22 
	THEN 'ENCAISSEE'
END AS ETATLIB,
p.DESIGNATION 
FROM 
    PRELEVEMENT p
JOIN 
    UTILISATEUR u ON u.REFUSER = p.IDPOMPISTE
JOIN 
    POMPE p2 ON p2.ID = p.IDPOMPE 
JOIN 
    MAGASINLIB m ON m.ID = p2.IDMAGASIN 
WHERE 
    u.IDROLE = 'pompiste';

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PRELEVEMENTLIB_ANNULEE" ("ID", "IDPRELEVEMENTANTERIEUR", "COMPTEUR", "DATY", "HEURE", "IDPOMPISTE", "IDPOMPE", "NOMUSER", "IDROLE", "NOMMAGASIN", "DESCRIPTIONMAGASIN", "ETAT", "ETATLIB", "DESIGNATION") AS
SELECT 
p."ID",p."IDPRELEVEMENTANTERIEUR",p."COMPTEUR",p."DATY",p."HEURE",p."IDPOMPISTE",p."IDPOMPE",p."NOMUSER",p."IDROLE",p."NOMMAGASIN",p."DESCRIPTIONMAGASIN",p."ETAT",p."ETATLIB",p."DESIGNATION"
FROM PRELEVEMENTLIB p 
WHERE p.ETAT = 0;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PRELEVEMENTLIB_CREE" ("ID", "IDPRELEVEMENTANTERIEUR", "COMPTEUR", "DATY", "HEURE", "IDPOMPISTE", "IDPOMPE", "NOMUSER", "IDROLE", "NOMMAGASIN", "DESCRIPTIONMAGASIN", "ETAT", "ETATLIB", "DESIGNATION") AS
SELECT 
p."ID",p."IDPRELEVEMENTANTERIEUR",p."COMPTEUR",p."DATY",p."HEURE",p."IDPOMPISTE",p."IDPOMPE",p."NOMUSER",p."IDROLE",p."NOMMAGASIN",p."DESCRIPTIONMAGASIN",p."ETAT",p."ETATLIB",p."DESIGNATION"
FROM PRELEVEMENTLIB p 
WHERE p.ETAT = 1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PRELEVEMENTLIB_ENCAISSEE" ("ID", "IDPRELEVEMENTANTERIEUR", "COMPTEUR", "DATY", "HEURE", "IDPOMPISTE", "IDPOMPE", "NOMUSER", "IDROLE", "NOMMAGASIN", "DESCRIPTIONMAGASIN", "ETAT", "ETATLIB", "DESIGNATION") AS
SELECT 
p."ID",p."IDPRELEVEMENTANTERIEUR",p."COMPTEUR",p."DATY",p."HEURE",p."IDPOMPISTE",p."IDPOMPE",p."NOMUSER",p."IDROLE",p."NOMMAGASIN",p."DESCRIPTIONMAGASIN",p."ETAT",p."ETATLIB",p."DESIGNATION"
FROM PRELEVEMENTLIB p 
WHERE p.ETAT = 22;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PRELEVEMENTLIB_VALIDE" ("ID", "IDPRELEVEMENTANTERIEUR", "COMPTEUR", "DATY", "HEURE", "IDPOMPISTE", "IDPOMPE", "NOMUSER", "IDROLE", "NOMMAGASIN", "DESCRIPTIONMAGASIN", "ETAT", "ETATLIB", "DESIGNATION", "IDPOMPELIB") AS
SELECT
	p.ID,
	p.IDPRELEVEMENTANTERIEUR,
	p.COMPTEUR,
	p.DATY,
	p.HEURE,
	p.IDPOMPISTE,
	p.IDPOMPE,
	p.NOMUSER,
	p.IDROLE,
	p.NOMMAGASIN,
	p.DESCRIPTIONMAGASIN,
	p.ETAT,
	p.ETATLIB,
	p.DESIGNATION,
	p2.val AS IDPOMPELIB
	
FROM
	PRELEVEMENTLIB p
	LEFT JOIN POMPE p2 ON p2.ID = p.IDPOMPE 
WHERE
	p.ETAT >= 11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PRELEVEMENTLIB_VISEE" ("ID", "IDPRELEVEMENTANTERIEUR", "COMPTEUR", "DATY", "HEURE", "IDPOMPISTE", "IDPOMPE", "NOMUSER", "IDROLE", "NOMMAGASIN", "DESCRIPTIONMAGASIN", "ETAT", "ETATLIB", "DESIGNATION", "IDPOMPELIB") AS
SELECT
	p.ID,
	p.IDPRELEVEMENTANTERIEUR,
	p.COMPTEUR,
	p.DATY,
	p.HEURE,
	p.IDPOMPISTE,
	p.IDPOMPE,
	p.NOMUSER,
	p.IDROLE,
	p.NOMMAGASIN,
	p.DESCRIPTIONMAGASIN,
	p.ETAT,
	p.ETATLIB,
	p.DESIGNATION,
	p2.val AS IDPOMPELIB
	
FROM
	PRELEVEMENTLIB p
	LEFT JOIN POMPE p2 ON p2.ID = p.IDPOMPE 
WHERE
	p.ETAT = 11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PRELEVEMENTLIB_VISEE_POP" ("ID", "IDPRELEVEMENTANTERIEUR", "COMPTEUR", "DATY", "HEURE", "IDPOMPISTE", "IDPOMPE", "IDPOMPELIB", "NOMUSER", "IDROLE", "NOMMAGASIN", "DESCRIPTIONMAGASIN", "ETAT", "ETATLIB", "DESIGNATION", "COMPTEURINIT", "DATYINIT") AS
SELECT 
pv.ID,
pv.IDPRELEVEMENTANTERIEUR,
pv.COMPTEUR,
pv.DATY,
pv.HEURE,
pv2.IDPOMPISTE ,
pv2.IDPOMPE ,
pv2.IDPOMPELIB ,
pv2.NOMUSER  ,
pv.IDROLE ,
pv.NOMMAGASIN ,
pv.DESCRIPTIONMAGASIN ,
pv.ETAT ,
pv.ETATLIB ,
pv.DESIGNATION ,
pv2.COMPTEUR AS compteurinit ,
pv2.DATY AS datyinit
FROM PRELEVEMENTLIB_VALIDE pv 
LEFT JOIN PRELEVEMENTLIB_VALIDE pv2 ON pv2.ID = pv.IDPRELEVEMENTANTERIEUR 
WHERE NOT EXISTS (SELECT * FROM  PRELEVEMENT_ENCAISSE pe  WHERE pv.ID =pe.IDPRELEVEMENT)
AND pv.IDPRELEVEMENTANTERIEUR IS NOT  NULL;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PRELEVEMENT_POMPISTE" ("INDEXF", "INDEXO", "VENTE", "PRODUIT", "PU", "MONTANT", "ID") AS
SELECT 
p2.compteur AS indexF,
p.compteur AS indexO,
p.compteur - p2.compteur AS vente ,
pro.val AS produit,
pro.puvente AS pu,
(p.compteur - p2.compteur) * pro.puvente AS montant,
pe.IDENCAISSEMENT AS ID
FROM PRELEVEMENT p 
JOIN PRELEVEMENT p2 ON p2.id = p.idprelevementanterieur 
JOIN POMPE po ON po.id = p.idpompe 
JOIN MAGASIN m ON m.id = po.idmagasin
JOIN PRODUIT pro ON pro.id = m.idproduit
JOIN PRELEVEMENT_ENCAISSE pe ON pe.IDPRELEVEMENT = p.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PREVISIONAVECMVTCAISSE" ("ID", "DESIGNATION", "IDCAISSE", "IDVENTEDETAIL", "IDVIREMENT", "DEBIT", "CREDIT", "DATY", "ETAT", "IDOP", "IDORIGINE", "IDDEVISE", "TAUX", "IDTIERS", "COMPTE", "IDFACTURE", "EFFECTIFDEB", "EFFECTIFCRED") AS
SELECT p."ID",p."DESIGNATION",p."IDCAISSE",p."IDVENTEDETAIL",p."IDVIREMENT",p."DEBIT",p."CREDIT",p."DATY",p."ETAT",p."IDOP",p."IDORIGINE",p."IDDEVISE",
  p."TAUX",p."IDTIERS",p."COMPTE",p."IDFACTURE",nvl(m.montantMere*nvl(m.taux,1),0) AS effectifdeb,nvl(m.montantCredit*nvl(m.taux,1),0) AS effectifCred 
FROM PREVISIONVALIDE p LEFT JOIN MvtCaisseSomPrevisionGroup m ON p.id=m.id2;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PREVISIONFERMELIB" ("ID", "DESIGNATION", "IDMAGASIN", "IDMVTSTOCKFILLE", "PU", "IDPRODUIT", "ENTREE", "SORTIE", "DATY", "ETAT", "IDORIGINE", "IDTIERS", "IDMAGASINLIB", "IDTIERSLIB", "IDPRODUITLIB", "SORTIEEFFECTIVE", "ENTREEEFFECTIVE", "ECARTENTREE", "ECARTSORTIE") AS
select
    p.ID,
    p.DESIGNATION,
    p.IDMAGASIN,
    p.IDMVTSTOCKFILLE,
    p.PU,
    p.IDPRODUIT,
    p.ENTREE,
    p.SORTIE,
    p.DATY,
    p.ETAT,
    p.IDORIGINE,
    p.IDTIERS,
    m.VAL AS idMagasinLib,
    t.NOM as idTiersLib,
    ai.LIBELLE as idProduitLib,
    CAST(NVL(ms.SORTIE, 0) AS NUMBER(30,3)) AS SortieEffective,
    CAST(NVL(ms.ENTREE, 0) AS NUMBER(30,3)) AS EntreeEffective,
    CAST(NVL(p.ENTREE, 0) - NVL(ms.ENTREE, 0) AS NUMBER(30,3)) AS EcartEntree,
    CAST(NVL(p.SORTIE, 0) - NVL(ms.SORTIE, 0) AS NUMBER(30,3)) AS EcartSortie
FROM PREVISIONFERME p
LEFT JOIN magasin2 m ON m.id = p.IDMAGASIN
LEFT JOIN AS_INGREDIENTS ai ON ai.id = p.idProduit
LEFT JOIN TIERS t ON t.id = p.IDTIERS
LEFT JOIN MvtStockFilleParDate ms ON ms.DATY = p.DATY AND ms.IDMAGASIN = p.IDMAGASIN AND ms.IDPRODUIT = p.IDPRODUIT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PREVISIONFERMEVIDE" ("ID", "IDPRODUIT", "IDPRODUITLIB", "IDMAGASIN", "DATY", "DATYDEBUT", "DATYFIN", "QTEINITIAL", "ENTREE", "SORTIE", "QTEFINAL", "GROUPERPAR") AS
SELECT
    ''  AS id,
    ''  AS idProduit,
    ''  AS idProduitLib,
    ''  AS idMagasin,
    CAST(NULL AS DATE) AS daty,
    CAST(NULL AS DATE) AS datyDebut,
    CAST(NULL AS DATE) AS datyFin,
    CAST(0 AS NUMBER(30,3)) AS qteInitial,
    CAST(0 AS NUMBER(30,3)) AS entree,
    CAST(0 AS NUMBER(30,3)) AS sortie,
    CAST(0 AS NUMBER(30,3)) AS qteFinal,
    '' AS grouperPar
FROM DUAL;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PREVISIONGROUPE" ("IDFACTURE", "REFERENCE", "DATY", "DEBIT", "CREDIT") AS
SELECT
    COALESCE(v.id, ff.idFactureFournisseur) AS idFacture,
    CASE
        WHEN v.id IS NOT NULL
            THEN 'vente/vente-fiche.jsp&id=' || v.id
        WHEN ff.idFactureFournisseur IS NOT NULL
            THEN 'facturefournisseur/facturefournisseur-fiche.jsp&id=' || ff.idFactureFournisseur
        ELSE NULL
        END AS reference,
    p.daty,
    SUM(p.debit)  AS debit,
    SUM(p.credit) AS credit

FROM prevision p

         LEFT JOIN vente v
                   ON v.id = p.idfacture

         LEFT JOIN facturefournisseurfille ff
                   ON ff.idFactureFournisseur = p.idfacture

GROUP BY
    v.id,
    ff.idFactureFournisseur,
    p.daty;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PREVISIONVALIDE" ("ID", "DESIGNATION", "IDCAISSE", "IDVENTEDETAIL", "IDVIREMENT", "DEBIT", "CREDIT", "DATY", "ETAT", "IDOP", "IDORIGINE", "IDDEVISE", "TAUX", "IDTIERS", "COMPTE", "IDFACTURE") AS
SELECT "ID","DESIGNATION","IDCAISSE","IDVENTEDETAIL","IDVIREMENT","DEBIT","CREDIT","DATY","ETAT","IDOP","IDORIGINE","IDDEVISE","TAUX","IDTIERS","COMPTE","IDFACTURE" FROM prevision WHERE etat>=1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PREVISION_COMPLET_CPL" ("ID", "DESIGNATION", "IDCAISSE", "IDCAISSELIB", "IDVENTEDETAIL", "IDVENTE", "IDVENTELIB", "IDVIREMENT", "DEBIT", "CREDIT", "DATY", "ETAT", "IDOP", "IDOPLIB", "IDORIGINE", "IDDEVISE", "IDDEVISELIB", "TAUX", "IDTIERS", "IDTIERSLIB", "COMPTE", "EFFECTIFDEBIT", "EFFECTIFCREDIT", "DEPENSEECART", "RECETTEECART", "IDFACTURE", "IDFACTUREMERE") AS
SELECT p.ID,
       p.DESIGNATION,
       p.IDCAISSE,
       p.IDCAISSELIB,
       p.IDVENTEDETAIL,
       p.IDVENTE,
       p.IDVENTELIB,
       p.IDVIREMENT,
       p.DEBIT,
       p.CREDIT,
       p.DATY,
       p.ETAT,
       p.IDOP,
       p.IDOPLIB,
       p.IDORIGINE,
       p.IDDEVISE,
       p.IDDEVISELIB,
       p.TAUX,
       p.IDTIERS,
       t.NOM                                                     as IDTIERSLIB,
       p.COMPTE,
       cast(NVL(pe.effectifDeb, 0) as number(30, 2))             AS effectifDebit,
       cast(NVL(pe.effectifCred, 0) as number(30, 2))            AS effectifCredit,
       cast(p.debit - NVL(pe.effectifDeb, 0) as number(30, 2))   AS depenseEcart,
       cast(p.credit - nVL(pe.effectifCred, 0) as number(30, 2)) AS recetteEcart,
       p.idfacture,
       COALESCE(v.IDVENTE, f.IDFACTUREFOURNISSEUR)               AS idfacturemere
FROM PREVISION_CPL p
         LEFT JOIN PrevisionAvecMvtCaisse pe ON pe.id = p.id
         LEFT JOIN VENTE_DETAILS v ON v.id = p.idfacture
         LEFT JOIN FACTUREFOURNISSEURFILLE f ON f.id = p.idfacture
         LEFT JOIN TIERS t ON t.id = p.IDTIERS;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PREVISION_COMPLET_CPLPOSITIF" ("ID", "DESIGNATION", "IDCAISSE", "IDCAISSELIB", "IDVENTEDETAIL", "IDVENTE", "IDVENTELIB", "IDVIREMENT", "DEBIT", "CREDIT", "DATY", "ETAT", "IDOP", "IDOPLIB", "IDORIGINE", "IDDEVISE", "IDDEVISELIB", "TAUX", "IDTIERS", "COMPTE", "EFFECTIFDEBIT", "EFFECTIFCREDIT", "DEPENSEECART", "RECETTEECART", "IDFACTURE", "IDFACTUREMERE") AS
SELECT "ID",
       "DESIGNATION",
       "IDCAISSE",
       "IDCAISSELIB",
       "IDVENTEDETAIL",
       "IDVENTE",
       "IDVENTELIB",
       "IDVIREMENT",
       "DEBIT",
       "CREDIT",
       "DATY",
       "ETAT",
       "IDOP",
       "IDOPLIB",
       "IDORIGINE",
       "IDDEVISE",
       "IDDEVISELIB",
       "TAUX",
       "IDTIERS",
       "COMPTE",
       "EFFECTIFDEBIT",
       "EFFECTIFCREDIT",
       cast (DEPENSEECART as  number(30,2)) as DEPENSEECART,
       cast(RECETTEECART as  number(30,2)) as RECETTEECART,
       "IDFACTURE",
       "IDFACTUREMERE"
from PREVISION_COMPLET_CPL pr
WHERE pr.DEPENSEECART > 0
   OR RECETTEECART > 0
order by daty asc;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PREVISION_COMPLET_CPL_DEP" ("ID", "DESIGNATION", "IDCAISSE", "IDCAISSELIB", "IDVENTEDETAIL", "IDVENTE", "IDVENTELIB", "IDVIREMENT", "DEBIT", "CREDIT", "DATY", "ETAT", "IDOP", "IDOPLIB", "IDORIGINE", "IDDEVISE", "IDDEVISELIB", "TAUX", "IDTIERS", "COMPTE", "EFFECTIFDEBIT", "EFFECTIFCREDIT", "DEPENSEECART", "RECETTEECART", "IDFACTURE") AS
SELECT "ID","DESIGNATION","IDCAISSE","IDCAISSELIB","IDVENTEDETAIL","IDVENTE","IDVENTELIB","IDVIREMENT","DEBIT","CREDIT","DATY","ETAT","IDOP","IDOPLIB","IDORIGINE","IDDEVISE","IDDEVISELIB","TAUX","IDTIERS","COMPTE","EFFECTIFDEBIT","EFFECTIFCREDIT","DEPENSEECART","RECETTEECART","IDFACTURE" FROM PREVISION_COMPLET_CPL pcc  WHERE 
debit > 0;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PREVISION_COMPLET_CPL_NR" ("ID", "DESIGNATION", "IDCAISSE", "IDCAISSELIB", "IDVENTEDETAIL", "IDVENTE", "IDVENTELIB", "IDVIREMENT", "DEBIT", "CREDIT", "DATY", "ETAT", "IDOP", "IDOPLIB", "IDORIGINE", "IDDEVISE", "IDDEVISELIB", "TAUX", "IDTIERS", "COMPTE", "EFFECTIFDEBIT", "EFFECTIFCREDIT", "DEPENSEECART", "RECETTEECART", "IDFACTURE") AS
SELECT "ID","DESIGNATION","IDCAISSE","IDCAISSELIB","IDVENTEDETAIL","IDVENTE","IDVENTELIB","IDVIREMENT","DEBIT","CREDIT","DATY","ETAT","IDOP","IDOPLIB","IDORIGINE","IDDEVISE","IDDEVISELIB","TAUX","IDTIERS","COMPTE","EFFECTIFDEBIT","EFFECTIFCREDIT","DEPENSEECART","RECETTEECART","IDFACTURE" FROM 
PREVISION_COMPLET_CPL_DEP
where depenseEcart > 0
UNION ALL 
 SELECT "ID","DESIGNATION","IDCAISSE","IDCAISSELIB","IDVENTEDETAIL","IDVENTE","IDVENTELIB","IDVIREMENT","DEBIT","CREDIT","DATY","ETAT","IDOP","IDOPLIB","IDORIGINE","IDDEVISE","IDDEVISELIB","TAUX","IDTIERS","COMPTE","EFFECTIFDEBIT","EFFECTIFCREDIT","DEPENSEECART","RECETTEECART","IDFACTURE" FROM
PREVISION_COMPLET_CPL_REC
where recetteEcart > 0;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PREVISION_COMPLET_CPL_REC" ("ID", "DESIGNATION", "IDCAISSE", "IDCAISSELIB", "IDVENTEDETAIL", "IDVENTE", "IDVENTELIB", "IDVIREMENT", "DEBIT", "CREDIT", "DATY", "ETAT", "IDOP", "IDOPLIB", "IDORIGINE", "IDDEVISE", "IDDEVISELIB", "TAUX", "IDTIERS", "COMPTE", "EFFECTIFDEBIT", "EFFECTIFCREDIT", "DEPENSEECART", "RECETTEECART", "IDFACTURE") AS
SELECT "ID","DESIGNATION","IDCAISSE","IDCAISSELIB","IDVENTEDETAIL","IDVENTE","IDVENTELIB","IDVIREMENT","DEBIT","CREDIT","DATY","ETAT","IDOP","IDOPLIB","IDORIGINE","IDDEVISE","IDDEVISELIB","TAUX","IDTIERS","COMPTE","EFFECTIFDEBIT","EFFECTIFCREDIT","DEPENSEECART","RECETTEECART","IDFACTURE" FROM PREVISION_COMPLET_CPL pcc  WHERE 
credit > 0;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PREVISION_CPL" ("ID", "DESIGNATION", "IDCAISSE", "IDCAISSELIB", "IDVENTEDETAIL", "IDVENTE", "IDVENTELIB", "IDVIREMENT", "DEBIT", "CREDIT", "DATY", "ETAT", "IDOP", "IDOPLIB", "IDORIGINE", "IDDEVISE", "IDDEVISELIB", "TAUX", "IDTIERS", "COMPTE", "IDFACTURE", "IDRESERVATION", "DATEINITIAL", "DUREERETARD", "MOIS", "ANNEE", "MOISLIB", "SERVICE", "IDSERVICELIB") AS
select
	    p.id,
	    p.designation,
	    p.idcaisse,
	    c.val as idcaisselib,
	    p.idventedetail,
	    v.IDVENTE,
	    v2.designation as idventelib,
	    p.idvirement,
	    p.debit,
	    p.credit,
	    p.daty,
	    p.etat,
	    p.idop,
	    o.DESIGNATION as idoplib ,
	    p.idorigine,
	    p.iddevise,
	    p.designation as iddeviselib,
	    p.taux,
	    p.idtiers,
	    p.compte,
	    p.idfacture,
	    v2.IDRESERVATION,
	    p.dateinitial,
	    p.dureeretard,
	    p.mois,
	    p.annee,
	    TO_CHAR(
	            TO_DATE(TO_CHAR(p.mois, 'FM00'), 'MM'),
	            'FMMonth',
	            'NLS_DATE_LANGUAGE=FRENCH'
	    ) AS moisLib,
	    p.SERVICE,
	    s.libelle AS idServiceLib
	from PREVISION p
	         left join caisse c on p.idcaisse = c.id
	         left join VENTE_DETAILS v on p.IDVENTEDETAIL=v.ID
	         left join vente v2 on v2.id=v.IDVENTE
	         left join ORDONNERPAIEMENT o on o.id=p.IDOP
	         LEFT JOIN SERVICE s ON p.SERVICE = s.COMPTE
	         left join devise d on d.id=p.IDDEVISE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PREVISION_EFFECTIF" ("IDPREVISION", "EFFECTIFDEBIT", "EFFECTIFCREDIT") AS
SELECT 
	p.id AS idprevision,   
	SUM(m.debit) as effectifDebit, 
	SUM(m.credit) as effectifCredit
FROM Prevision p 
join MOUVEMENTCAISSE m on m.idPrevision=p.id 
GROUP BY p.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PREVISION_TIERS" ("ID", "DESIGNATION", "IDCAISSE", "IDCAISSELIB", "IDVENTEDETAIL", "IDVENTE", "IDVENTELIB", "IDVIREMENT", "DEBIT", "CREDIT", "DATY", "ETAT", "IDOP", "IDOPLIB", "IDORIGINE", "IDDEVISE", "IDDEVISELIB", "TAUX", "IDTIERS", "COMPTE", "EFFECTIFDEBIT", "EFFECTIFCREDIT", "DEPENSEECART", "RECETTEECART", "IDFACTURE", "TIERSLIB") AS
select p."ID",p."DESIGNATION",p."IDCAISSE",p."IDCAISSELIB",p."IDVENTEDETAIL",p."IDVENTE",p."IDVENTELIB",p."IDVIREMENT",p."DEBIT",p."CREDIT",p."DATY",p."ETAT",p."IDOP",p."IDOPLIB",p."IDORIGINE",p."IDDEVISE",p."IDDEVISELIB",p."TAUX",p."IDTIERS",p."COMPTE",p."EFFECTIFDEBIT",p."EFFECTIFCREDIT",p."DEPENSEECART",p."RECETTEECART",p."IDFACTURE", t.nom as tierslib from PREVISION_COMPLET_CPLPositif p LEFT JOIN TIERS t on t.id = p.IDTIERS;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PRIXTEMP" ("PUTEMP", "IDPRODUIT") AS
SELECT AVG(PU)AS putemp,IDPRODUIT FROM V_ETATSTOCK_ENTREE vee GROUP BY IDPRODUIT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PRIX_MO_PRODUIT" ("ID", "LIBELLE", "PU", "CATEGORIEINGREDIENT", "CATEGORIELIB") AS
SELECT a.IDPRODUITS AS ID ,a.LIBELLEPRODUIT AS LIBELLE  , SUM(PU) AS PU,CATEGORIEINGREDIENT ,CATEGORIELIB  FROM 
	AS_RECETTE_LIB_CAT a WHERE CATEGORIEINGREDIENT = 'CAT002'
	GROUP BY IDPRODUITS , CATEGORIELIB ,LIBELLEPRODUIT,CATEGORIEINGREDIENT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PROCESSFABPETRI" ("IDHISTORIQUE", "DATEHISTORIQUE", "HEURE", "OBJET", "ACTION", "IDUTILISATEUR", "REFOBJET", "ACTEUR", "REMARQUE", "ECART") AS
SELECT 
p."IDHISTORIQUE",p."DATEHISTORIQUE",p."HEURE",p."OBJET",p."ACTION",p."IDUTILISATEUR",p."REFOBJET",p."ACTEUR",p."REMARQUE",p."ECART" 
FROM PROCESS p 
LEFT JOIN FABRICATION f ON f.ID = p.REFOBJET 
LEFT JOIN FABRICATIONFILLE f2 ON f2.IDMERE = f.ID 
LEFT JOIN AS_INGREDIENTS ai ON ai.id = f2.IDINGREDIENTS  
WHERE ai.IDFOURNISSEUR ='oui' 
AND  p."ACTION"  = 'terminer';

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PROCESSLIB" ("IDHISTORIQUE", "DATEHISTORIQUE", "HEURE", "OBJET", "REFOBJET", "REMARQUE", "IDUTILISATEUR", "ACTION", "ECART", "ECARTMINUTES", "ACTEUR") AS
SELECT
    p.IDHISTORIQUE ,
    p.DATEHISTORIQUE ,
    p.HEURE ,
    p.OBJET ,
    p.REFOBJET ,
    p.REMARQUE ,
    p.IDUTILISATEUR ,
    p."ACTION" ,
    p.ECART ,
    p.ecart / 60 AS ecartMinutes,
    pers.NOM || ' ' || pers.TELEPHONE AS acteur
FROM
    PROCESS p
        LEFT JOIN PERSONNEL pers ON
        p.acteur = pers.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PROCESSMAINTENANCEGLOBAL" ("IDTRAVAUX", "IDPERSONNEL", "DUREEREEL", "DUREEREELHMS") AS
SELECT
    pr.IDTRAVAUX,
    pr.IDPERSONNEL,
    sum(pr.ecart_seconde) as dureeReel,
    LPAD(FLOOR(TO_NUMBER(sum(pr.ecart_seconde)) / 3600), 2, '0') || ':' ||
    LPAD(FLOOR(MOD(TO_NUMBER(sum(pr.ecart_seconde)), 3600) / 60), 2, '0') || ':' ||
    LPAD(MOD(TO_NUMBER(sum(pr.ecart_seconde)), 60), 2, '0')
                          AS dureeReelHMS
FROM PROCESSMAINTENANCELIB pr
group by pr.IDTRAVAUX, pr.IDPERSONNEL;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PROCESSMAINTENANCELIB" ("ID", "IDPERSONNEL", "IDTRAVAUX", "DATEDEBUT", "DATEFIN", "HEUREDEBUT", "HEUREFIN", "DATETIME_DEBUT", "DATETIME_FIN", "ECART_SECONDE", "ECART_HMS", "IDPERSONNELLIB") AS
SELECT
    prc."ID",prc."IDPERSONNEL",prc."IDTRAVAUX",prc."DATEDEBUT",prc."DATEFIN",prc."HEUREDEBUT",prc."HEUREFIN",prc."DATETIME_DEBUT",prc."DATETIME_FIN",
    /* Ecart en secondes */
    ROUND((prc.datetime_fin - prc.datetime_debut) * 86400) AS ecart_seconde,
    /* Ecart format HH:MM:SS */
    LPAD(FLOOR(ROUND((prc.datetime_fin - prc.datetime_debut) * 86400) / 3600), 2, '0')
        || ':' ||
    LPAD(FLOOR(MOD(ROUND((prc.datetime_fin - prc.datetime_debut) * 86400), 3600) / 60), 2, '0')
        || ':' ||
    LPAD(MOD(ROUND((prc.datetime_fin - prc.datetime_debut) * 86400), 60), 2, '0')
                                                           AS ecart_hms,
    p.NOM AS idPersonnelLib
FROM (
         SELECT
             prc.*,

             /* Date + Heure debut */
             prc.DATEDEBUT
                 + (TO_DATE(prc.HEUREDEBUT, 'HH24:MI:SS')
                 - TRUNC(TO_DATE(prc.HEUREDEBUT, 'HH24:MI:SS')))
                 AS datetime_debut,

             /* Date + Heure fin */
             prc.DATEFIN
                 + (TO_DATE(prc.HEUREFIN, 'HH24:MI:SS')
                 - TRUNC(TO_DATE(prc.HEUREFIN, 'HH24:MI:SS')))
                 AS datetime_fin

         FROM ProcessMaintenance prc
     ) prc
         LEFT JOIN PERSONNEL p ON p.ID = prc.IDPERSONNEL;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PRODUITCOMMANDE" ("IDBC", "PRODUIT", "QUANTITEBC") AS
SELECT 
bcf.IDBC ,
bcf.PRODUIT,
sum(bcf.QUANTITE) AS  QUANTITEBC
FROM BONDECOMMANDE_CLIENT_FILLE bcf  
GROUP BY bcf.IDBC,bcf.PRODUIT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PRODUITCOMMANDECARTON" ("IDBC", "PRODUITLIB", "QUANTITEBC", "QUANTITECARTON", "RESTECARTON") AS
SELECT 
pc.IDBC,
ai.LIBELLE AS produitlib,
nvl(pc.QUANTITEBC,0) AS QUANTITEBC,
nvl(ps.QUANTITEcarton,0) AS QUANTITEcarton,
nvl(pc.QUANTITEBC,0) - nvl(ps.QUANTITEcarton,0) AS restecarton
FROM produitcommande pc 
LEFT JOIN produitsouscarton ps ON ps.IDBC = pc.IDBC AND pc.PRODUIT = ps.IDINGREDIENT 
LEFT JOIN AS_INGREDIENTS ai ON ai.ID = pc.PRODUIT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PRODUITCOMMANDEFILLECARTON" ("ID", "IDBC", "PRODUITLIB", "PRODUIT", "QUANTITEBCF", "QUANTITECARTONFILLE", "RESTECARTONFILLE") AS
SELECT 
bc.ID ,
bc.idbc AS idbc ,
ai.LIBELLE AS produitlib,
ai.id AS produit,
nvl(bc.QUANTITE,0) AS quantiteBCF ,
nvl(c.QUANTITE,0) AS quantitecartonfille,
nvl(bc.QUANTITE,0) - nvl(c.QUANTITE,0) AS restecartonfille
FROM BONDECOMMANDE_CLIENT_FILLE bc 
LEFT JOIN CARTONFILLE c  ON c.IDBCFILLE = bc.ID 
LEFT JOIN AS_INGREDIENTS ai ON ai.ID = bc.PRODUIT
GROUP BY bc.ID, bc.idbc, ai.LIBELLE, ai.id, bc.QUANTITE, c.QUANTITE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PRODUITSOUSCARTON" ("IDBC", "IDINGREDIENT", "QUANTITECARTON") AS
SELECT 
c2.IDBC  ,
c.IDINGREDIENT ,
sum(c.QUANTITE) AS  QUANTITEcarton
FROM CARTONFILLE c 
LEFT JOIN CARTON c2 ON c2.ID =c.IDMERE 
GROUP BY c2.IDBC  , c.IDINGREDIENT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PRODUIT_ACHAT_LIB_EURO" ("ID", "VAL", "DESCE", "IDTYPEPRODUIT", "IDTYPEPRODUITLIB", "PUACHAT", "PUVENTE", "IDUNITE", "IDUNITELIB", "IDCATEGORIE", "IDCATEGORIELIB", "IDSOUSCATEGORIELIB", "SEUILMIN", "SEUILMAX", "PUACHATUSD", "PUACHATEURO", "PUACHATAUTREDEVISE", "PUVENTEUSD", "PUVENTEEURO", "PUVENTEAUTREDEVISE", "TAUX", "ISVENTE", "COMPTE") AS
SELECT 
 pl.ID,
       pl.VAL,
       pl.DESCE,
       pl.IDTYPEPRODUIT,
       pl.IDTYPEPRODUITLIB,
       nvl(pl.puAchatUsd * t.TAUX,0)  AS PUACHAT,
       nvl(pl.puVenteUsd,0) AS PUVENTE,
       pl.IDUNITE,
       pl.IDUNITELIB,
       pl.IDCATEGORIE,
       pl.IDCATEGORIELIB,
       pl.IDSOUSCATEGORIELIB,
       pl.seuilmin,
       pl.seuilmax,
       pl.puAchatUsd,
  	   pl.puAchatEuro,
	   pl.puAchatAutreDevise,
	   pl.puVenteUsd,
	   pl.puVenteEuro,
	   pl.puVenteAutreDevise,
	   t.TAUX AS taux,
	   pl.isvente,
	   pl.compte_achat AS compte
FROM PRODUIT_LIB pl ,TAUXDECHANGE_MAXDATY t
WHERE t.IDDEVISE = 'EUR' AND pl.isAchat =1;

