CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PRODUIT_LIB" ("ID", "VAL", "DESCE", "IDTYPEPRODUIT", "IDTYPEPRODUITLIB", "PUACHAT", "PUVENTE", "IDUNITE", "IDUNITELIB", "IDCATEGORIE", "IDCATEGORIELIB", "IDSOUSCATEGORIELIB", "SEUILMIN", "SEUILMAX", "PUACHATUSD", "PUACHATEURO", "PUACHATAUTREDEVISE", "PUVENTEUSD", "PUVENTEEURO", "PUVENTEAUTREDEVISE", "ISVENTE", "ISACHAT", "COMPTE_VENTE", "COMPTE_ACHAT") AS
SELECT p.ID,
       p.LIBELLE as val,
       p.LIBELLE as DESCE,
       '-' as IDTYPEPRODUIT,
       '-' AS IDTYPEPRODUITLIB,
       p.PU as PUACHAT,
       p.pv as PUVENTE,
       p.UNITE as idunite,
       u.VAL  AS IDUNITELIB,
       p.CATEGORIEINGREDIENT as IDCATEGORIE,
       c.VAL  AS IDCATEGORIELIB,
       '-'  AS IDSOUSCATEGORIELIB,
