	   p.puVenteAutreDevise,
	   p.isvente,
	   p.isachat,
	   p.compte_vente,
	   p.compte_achat
FROM AS_INGREDIENTS p
         LEFT JOIN CATEGORIEINGREDIENT c ON c.ID = p.CATEGORIEINGREDIENT
         LEFT JOIN as_UNITE u ON u.ID = p.unite;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PRODUIT_LIBCPL" ("ID", "LIBELLE", "PU", "PV", "UNITE", "CATEGORIEINGREDIENT", "COMPTE_VENTE", "IDUNITELIB", "CATEGORIELIB", "SEUILMIN", "SEUILMAX") AS
