CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PROFORMACOMMADER" ("PRODUIT", "QUANTITE", "IDPROFORMA") AS
select PRODUIT, sum(QUANTITE) as quantite, bc.IDPROFORMA from BONDECOMMANDE_CLIENT_FILLE bcf join BONDECOMMANDE_CLIENT bc on bc.id=bcf.IDBC where bc.ETAT>=11 group by PRODUIT, bc.IDPROFORMA;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PROFORMADETAILS_CPL" ("ID", "IDPROFORMA", "IDPRODUIT", "IDORIGINE", "QTE", "PU", "REMISE", "TVA", "PUACHAT", "PUVENTE", "IDDEVISE", "TAUXDECHANGE", "DESIGNATION", "COMPTE", "PUREVIENT", "IDDEMANDEPRIXFILLE", "IDPROFORMALIB", "IDPRODUITLIB", "PUTOTAL", "UNITE", "UNITELIB", "REMISEMONTANT", "MONTANTRISTOURNE", "FRAISTRANSPORT", "MONTANTTOTAL", "MONTANTTVA", "MONTANTTTC", "DATEDEBUT", "CALORIE", "RISTOURNE", "POIDSPARKILO", "FRAISLIVRAISON", "POIDSTOTAL", "RESTEBC", "REMISEARBIOCHEM", "RISTOURNEARBIOCHEM") AS
SELECT vd.ID,
       vd.IDPROFORMA,
       vd.IDPRODUIT,
       vd.IDORIGINE,
       vd.QTE,
       vd.PU,
       vd.REMISE,
       vd.TVA,
       vd.PUACHAT,
       vd.PUVENTE,
       v.IDDEVISE,
       vd.TAUXDECHANGE,
       vd.DESIGNATION,
       vd.COMPTE,
       vd.PUREVIENT,
       vd.IDDEMANDEPRIXFILLE,
       v.DESIGNATION                                                                                       AS IDPROFORMALIB,
       nvl(p.LIBELLEVENTE,p.libelle)                                                                                           AS IDPRODUITLIB,
       cast((vd.QTE * vd.PU) as NUMBER(30, 2))                                                             AS puTotal,
       vd.unite,
       au.val                                                                                              AS uniteLib,
       cast(((vd.QTE * vd.PU) * NVL(vd.remise, 0)) / 100 as NUMBER(30, 2))                                 AS remisemontant,
       cast((cast((vd.QTE * vd.PU) - ((vd.QTE * vd.PU) * NVL(vd.remise, 0)) / 100 as NUMBER(30, 2)) * nvl(vd.ristourne, 0) /
             100) as number(30, 2))                                                                                               as montantristourne,
       cast(nvl(p.CALORIE * vd.QTE * v.fraislivraison, 0) as number(30, 2))                                as fraistransport,
       cast((cast((vd.QTE * vd.PU) - ((vd.QTE * vd.PU) * NVL(vd.remise, 0)) / 100 as NUMBER(30, 2)) -
             (cast((vd.QTE * vd.PU) - ((vd.QTE * vd.PU) * NVL(vd.remise, 0)) / 100 as NUMBER(30, 2)) * nvl(vd.ristourne, 0) /
              100)) -
            nvl(p.CALORIE * vd.QTE * v.fraislivraison, 0) as number(30 ,2))                                                       as montanttotal,
       cast((nvl(vd.TVA, 0) / 100) *
            ((cast((vd.QTE * vd.PU) - ((vd.QTE * vd.PU) * NVL(vd.remise, 0)) / 100 as NUMBER(30, 2)) -
              (cast((vd.QTE * vd.PU) - ((vd.QTE * vd.PU) * NVL(vd.remise, 0)) / 100 as NUMBER(30, 2)) *
               nvl(vd.ristourne, 0) /
               100)) -
             nvl(p.CALORIE * vd.QTE * v.fraislivraison, 0)) as number(30,2))                                                     as montanttva,
       cast(((cast((vd.QTE * vd.PU) - ((vd.QTE * vd.PU) * NVL(vd.remise, 0)) / 100 as NUMBER(30, 2)) -
              (cast((vd.QTE * vd.PU) - ((vd.QTE * vd.PU) * NVL(vd.remise, 0)) / 100 as NUMBER(30, 2)) *
               nvl(vd.ristourne, 0) /
               100)) - nvl(p.CALORIE * vd.QTE * v.fraislivraison, 0)) + (nvl(vd.TVA, 0) / 100) *
                                                                        ((cast((vd.QTE * vd.PU) - ((vd.QTE * vd.PU) * NVL(vd.remise, 0)) / 100 as NUMBER(30, 2)) -
                                                                          (cast((vd.QTE * vd.PU) - ((vd.QTE * vd.PU) * NVL(vd.remise, 0)) / 100 as NUMBER(30, 2)) *
                                                                           nvl(vd.ristourne, 0) / 100)) -
                                                                         p.CALORIE * vd.QTE *
                                                                         v.fraislivraison) as number(30, 2))                      as montantttc,
       vd.datedebut,
       cast(nvl(p.calorie, 0) as number(10,2))                                                                                   as CALORIE,
       vd.ristourne                                                                                        as ristourne,
       cast(p.CALORIE as number(30, 2))                                                                    as poidsparkilo,
       cast(v.fraislivraison as number(30, 2))                                                             as fraislivraison,
       cast(p.CALORIE * vd.QTE as number(30, 2))                                                           as poidstotal,
       ((nvl(vd.qte,0) - nvl(pfc.QUANTITE,0) ) +  nvl(bcr.QUANTITE,0) )as restebc,
       vd.remiseArbiochem,
       vd.ristourneArbiochem
--       d2.id AS idDevis
FROM PROFORMA_DETAILS vd
         LEFT JOIN PROFORMA v ON v.ID = vd.IDPROFORMA
         LEFT JOIN AS_INGREDIENTS p ON p.ID = vd.IDPRODUIT
         LEFT JOIN AS_UNITE au ON au.id = vd.unite
         LEFT JOIN PROFORMACOMMADER pfc on pfc.IDPROFORMA=v.ID and vd.IDPRODUIT=pfc.PRODUIT
         LEFT JOIN BONDECOMMANDEFACTURER bcr on v.id=bcr.IDPROFORMA and bcr.PRODUIT=vd.IDPRODUIT
order by p.LIBELLEVENTE asc;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PROFORMADETAILS_CPL2" ("ID", "IDPROFORMA", "IDPRODUIT", "IDORIGINE", "QTE", "PU", "REMISE", "TVA", "PUACHAT", "PUVENTE", "IDDEVISE", "TAUXDECHANGE", "DESIGNATION", "COMPTE", "PUREVIENT", "IDDEMANDEPRIXFILLE", "IDPROFORMALIB", "IDPRODUITLIB", "PUTOTAL", "UNITE", "UNITELIB", "REMISEMONTANT", "MONTANTRISTOURNE", "FRAISTRANSPORT", "MONTANTTOTAL", "MONTANTTVA", "MONTANTTTC", "DATEDEBUT", "CALORIE", "RISTOURNE", "POIDSPARKILO", "FRAISLIVRAISON", "POIDSTOTAL", "RESTEBC", "REMISEARBIOCHEM", "RISTOURNEARBIOCHEM") AS
SELECT vd.ID,
       vd.IDPROFORMA,
       vd.IDPRODUIT,
       vd.IDORIGINE,
       vd.QTE,
       vd.PU,
       vd.REMISE,
       vd.TVA,
       vd.PUACHAT,
       vd.PUVENTE,
       v.IDDEVISE,
       vd.TAUXDECHANGE,
       vd.DESIGNATION,
       vd.COMPTE,
       vd.PUREVIENT,
       vd.IDDEMANDEPRIXFILLE,
       v.DESIGNATION AS IDPROFORMALIB,
       NVL(p.LIBELLEVENTE, p.libelle) AS IDPRODUITLIB,
       CAST((vd.QTE * vd.PU) AS NUMBER(30, 2)) AS puTotal,
       vd.unite,
       au.val AS uniteLib,
       CAST(((vd.QTE * vd.PU * NVL(vd.remise, 0) / 100) + (vd.QTE * NVL(vd.remiseArbiochem, 0))) AS NUMBER(30, 2)) AS remisemontant,
       CAST((
           ((vd.QTE * vd.PU - ((vd.QTE * vd.PU * NVL(vd.remise, 0) / 100) + (vd.QTE * NVL(vd.remiseArbiochem, 0)))) * NVL(vd.ristourne, 0) / 100)
               + (vd.QTE * NVL(vd.ristourneArbiochem, 0))
           ) AS NUMBER(30, 2)) AS montantristourne,
       CAST(NVL(p.CALORIE * vd.QTE * v.fraislivraison, 0) AS NUMBER(30, 2)) AS fraistransport,
       CAST((
           (vd.QTE * vd.PU)
               - ((vd.QTE * vd.PU * NVL(vd.remise, 0) / 100) + (vd.QTE * NVL(vd.remiseArbiochem, 0)))
               - (
               ((vd.QTE * vd.PU - ((vd.QTE * vd.PU * NVL(vd.remise, 0) / 100) + (vd.QTE * NVL(vd.remiseArbiochem, 0)))) * NVL(vd.ristourne, 0) / 100)
                   + (vd.QTE * NVL(vd.ristourneArbiochem, 0))
               )
               - NVL(p.CALORIE * vd.QTE * v.fraislivraison, 0)
           ) AS NUMBER(30, 2)) AS montanttotal,
       CAST((
           (NVL(vd.TVA, 0) / 100) * (
               (vd.QTE * vd.PU)
                   - ((vd.QTE * vd.PU * NVL(vd.remise, 0) / 100) + (vd.QTE * NVL(vd.remiseArbiochem, 0)))
                   - (
                   ((vd.QTE * vd.PU - ((vd.QTE * vd.PU * NVL(vd.remise, 0) / 100) + (vd.QTE * NVL(vd.remiseArbiochem, 0)))) * NVL(vd.ristourne, 0) / 100)
                       + (vd.QTE * NVL(vd.ristourneArbiochem, 0))
                   )
                   - NVL(p.CALORIE * vd.QTE * v.fraislivraison, 0)
               )
           ) AS NUMBER(30, 2)) AS montanttva,
       CAST((
           (
               (vd.QTE * vd.PU)
                   - ((vd.QTE * vd.PU * NVL(vd.remise, 0) / 100) + (vd.QTE * NVL(vd.remiseArbiochem, 0)))
                   - (
                   ((vd.QTE * vd.PU - ((vd.QTE * vd.PU * NVL(vd.remise, 0) / 100) + (vd.QTE * NVL(vd.remiseArbiochem, 0)))) * NVL(vd.ristourne, 0) / 100)
                       + (vd.QTE * NVL(vd.ristourneArbiochem, 0))
                   )
                   - NVL(p.CALORIE * vd.QTE * v.fraislivraison, 0)
               ) * (1 + NVL(vd.TVA, 0) / 100)
           ) AS NUMBER(30, 2)) AS montantttc,
       vd.datedebut,
       CAST(NVL(p.calorie, 0) AS NUMBER(10, 2)) AS CALORIE,
       vd.ristourne AS ristourne,
       CAST(p.CALORIE AS NUMBER(30, 2)) AS poidsparkilo,
       CAST(v.fraislivraison AS NUMBER(30, 2)) AS fraislivraison,
       CAST(p.CALORIE * vd.QTE AS NUMBER(30, 2)) AS poidstotal,
       ((NVL(vd.qte, 0) - NVL(pfc.QUANTITE, 0)) + NVL(bcr.QUANTITE, 0)) AS restebc,
       CAST(NVL(vd.remiseArbiochem, 0) AS NUMBER(30, 2)) AS remiseArbiochem,
       CAST(NVL(vd.ristourneArbiochem, 0) AS NUMBER(30, 2)) AS ristourneArbiochem
FROM PROFORMA_DETAILS vd
         LEFT JOIN PROFORMA v ON v.ID = vd.IDPROFORMA
         LEFT JOIN AS_INGREDIENTS p ON p.ID = vd.IDPRODUIT
         LEFT JOIN AS_UNITE au ON au.id = vd.unite
         LEFT JOIN PROFORMACOMMADER pfc ON pfc.IDPROFORMA = v.ID AND vd.IDPRODUIT = pfc.PRODUIT
         LEFT JOIN BONDECOMMANDEFACTURER bcr ON v.id = bcr.IDPROFORMA AND bcr.PRODUIT = vd.IDPRODUIT
ORDER BY p.LIBELLEVENTE ASC;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PROFORMADETAILS_CPL_ING" ("ID", "IDPROFORMA", "IDPRODUIT", "IDORIGINE", "QTE", "PU", "REMISE", "TVA", "PUACHAT", "PUVENTE", "IDDEVISE", "TAUXDECHANGE", "DESIGNATION", "COMPTE", "PUREVIENT", "IDDEMANDEPRIXFILLE", "IDPROFORMALIB", "IDPRODUITLIB", "PUTOTAL", "UNITE", "UNITELIB", "REMISEMONTANT", "MONTANTRISTOURNE", "FRAISTRANSPORT", "MONTANTTOTAL", "MONTANTTVA", "MONTANTTTC", "DATEDEBUT", "CALORIE", "RISTOURNE", "POIDSPARKILO", "FRAISLIVRAISON", "POIDSTOTAL", "PUINGREDIENT", "CONTENUE") AS
SELECT vd.ID,
       vd.IDPROFORMA,
       vd.IDPRODUIT,
       vd.IDORIGINE,
       vd.QTE,
       vd.PU,
       vd.REMISE,
       vd.TVA,
       vd.PUACHAT,
       vd.PUVENTE,
       v.IDDEVISE,
       vd.TAUXDECHANGE,
       vd.DESIGNATION,
       vd.COMPTE,
       vd.PUREVIENT,
       vd.IDDEMANDEPRIXFILLE,
       v.DESIGNATION                                                                                       AS IDPROFORMALIB,
       p.LIBELLEVENTE                                                                                           AS IDPRODUITLIB,
       cast((vd.QTE * vd.PU) as NUMBER(30, 2))                                                             AS puTotal,
       vd.unite,
       au.val                                                                                              AS uniteLib,
       cast(((vd.QTE * vd.PU) * NVL(vd.remise, 0)) / 100 as NUMBER(30, 2))                                 AS remisemontant,
       cast((cast((vd.QTE * vd.PU) - ((vd.QTE * vd.PU) * NVL(vd.remise, 0)) / 100 as NUMBER(30, 2)) * nvl(vd.ristourne, 0) /
             100) as number(30, 2))                                                                                               as montantristourne,
       cast(nvl(p.CALORIE * vd.QTE * v.fraislivraison, 0) as number(30, 2))                                as fraistransport,
       cast((cast((vd.QTE * vd.PU) - ((vd.QTE * vd.PU) * NVL(vd.remise, 0)) / 100 as NUMBER(30, 2)) -
             (cast((vd.QTE * vd.PU) - ((vd.QTE * vd.PU) * NVL(vd.remise, 0)) / 100 as NUMBER(30, 2)) * nvl(vd.ristourne, 0) /
              100)) -
            nvl(p.CALORIE * vd.QTE * v.fraislivraison, 0) as number(30 ,2))                                                       as montanttotal,
       cast((nvl(vd.TVA, 0) / 100) *
            ((cast((vd.QTE * vd.PU) - ((vd.QTE * vd.PU) * NVL(vd.remise, 0)) / 100 as NUMBER(30, 2)) -
              (cast((vd.QTE * vd.PU) - ((vd.QTE * vd.PU) * NVL(vd.remise, 0)) / 100 as NUMBER(30, 2)) *
               nvl(vd.ristourne, 0) /
               100)) -
             nvl(p.CALORIE * vd.QTE * v.fraislivraison, 0)) as number(30,2))                                                     as montanttva,
       cast(((cast((vd.QTE * vd.PU) - ((vd.QTE * vd.PU) * NVL(vd.remise, 0)) / 100 as NUMBER(30, 2)) -
              (cast((vd.QTE * vd.PU) - ((vd.QTE * vd.PU) * NVL(vd.remise, 0)) / 100 as NUMBER(30, 2)) *
               nvl(vd.ristourne, 0) /
               100)) - nvl(p.CALORIE * vd.QTE * v.fraislivraison, 0)) + (nvl(vd.TVA, 0) / 100) *
                                                                        ((cast((vd.QTE * vd.PU) - ((vd.QTE * vd.PU) * NVL(vd.remise, 0)) / 100 as NUMBER(30, 2)) -
                                                                          (cast((vd.QTE * vd.PU) - ((vd.QTE * vd.PU) * NVL(vd.remise, 0)) / 100 as NUMBER(30, 2)) *
                                                                           nvl(vd.ristourne, 0) / 100)) -
                                                                         p.CALORIE * vd.QTE *
                                                                         v.fraislivraison) as number(30, 2))                      as montantttc,
       vd.datedebut,
       cast(nvl(p.calorie, 0) as number(10,2))                                                                                   as CALORIE,
       vd.ristourne                                                                                        as ristourne,
       cast(p.CALORIE as number(30, 2))                                                                    as poidsparkilo,
       cast(v.fraislivraison as number(30, 2))                                                             as fraislivraison,
       cast(p.CALORIE * vd.QTE as number(30, 2))                                                           as poidstotal,
       p.pu as puingredient,
       nvl(eq.QUANTITE,1) as contenue
--       d2.id AS idDevis
FROM PROFORMA_DETAILS vd
         LEFT JOIN PROFORMA v ON v.ID = vd.IDPROFORMA
         LEFT JOIN AS_INGREDIENTS p ON p.ID = vd.IDPRODUIT
         LEFT JOIN AS_UNITE au ON au.id = vd.unite
         LEFT JOIN EQUIVALENCEVENTE eq on eq.IDPRODUIT1=p.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PROFORMADETAILS_CPL_ING_PDF" ("ID", "IDPROFORMA", "IDPRODUIT", "IDORIGINE", "QTE", "PU", "REMISE", "TVA", "PUACHAT", "PUVENTE", "IDDEVISE", "TAUXDECHANGE", "DESIGNATION", "COMPTE", "PUREVIENT", "IDDEMANDEPRIXFILLE", "IDPROFORMALIB", "IDPRODUITLIB", "PUTOTAL", "UNITE", "UNITELIB", "REMISEMONTANT", "MONTANTRISTOURNE", "FRAISTRANSPORT", "MONTANTTOTAL", "MONTANTREMISE", "MONTANTTVA", "MONTANTTTC", "DATEDEBUT", "CALORIE", "RISTOURNE", "POIDSPARKILO", "FRAISLIVRAISON", "POIDSTOTAL", "PUINGREDIENT", "CONTENUE", "UNITE2", "REMISEARBIOCHEM") AS
SELECT
    vd.ID,
    vd.IDPROFORMA,
    vd.IDPRODUIT,
    vd.IDORIGINE,
    vd.QTE,
    vd.PU,
    vd.REMISE,
    vd.TVA,
    vd.PUACHAT,
    vd.PUVENTE,
    v.IDDEVISE,
    vd.TAUXDECHANGE,
    vd.DESIGNATION,
    vd.COMPTE,
    vd.PUREVIENT,
    vd.IDDEMANDEPRIXFILLE,

    v.DESIGNATION AS IDPROFORMALIB,

    NVL(p.LIBELLEVENTE, p.LIBELLE) AS IDPRODUITLIB,

    CAST(
        vd.QTE * vd.PU
        AS NUMBER(30,2)
    ) AS PUTOTAL,

    vd.UNITE,

    au.VAL AS UNITELIB,

    /* REMISE TOTALE */
    CAST(
        (vd.QTE * vd.PU * NVL(vd.REMISE,0) / 100)
        + (vd.QTE * NVL(vd.REMISEARBIOCHEM,0))
        AS NUMBER(30,2)
    ) AS REMISEMONTANT,

    /* RISTOURNE */
    CAST(
        (
            (vd.QTE * vd.PU)
            - (
                (vd.QTE * vd.PU * NVL(vd.REMISE,0) / 100)
                + (vd.QTE * NVL(vd.REMISEARBIOCHEM,0))
            )
        ) * NVL(vd.RISTOURNE,0) / 100
        AS NUMBER(30,2)
    ) AS MONTANTRISTOURNE,

    /* FRAIS TRANSPORT */
    CAST(
        NVL(
            p.CALORIE * vd.QTE * v.FRAISLIVRAISON,
            0
        )
        AS NUMBER(30,2)
    ) AS FRAISTRANSPORT,

    /* MONTANT TOTAL HT */
    CAST(
        (vd.QTE * vd.PU)
        - (
            (vd.QTE * vd.PU * NVL(vd.REMISE,0) / 100)
            + (vd.QTE * NVL(vd.REMISEARBIOCHEM,0))
        )
        - (
            (
                (vd.QTE * vd.PU)
                - (
                    (vd.QTE * vd.PU * NVL(vd.REMISE,0) / 100)
                    + (vd.QTE * NVL(vd.REMISEARBIOCHEM,0))
                )
            ) * NVL(vd.RISTOURNE,0) / 100
        )
        - NVL(
            p.CALORIE * vd.QTE * v.FRAISLIVRAISON,
            0
        )
        AS NUMBER(30,2)
    ) AS MONTANTTOTAL,

    /* MONTANT REMISE */
    CAST(
        (vd.QTE * vd.PU * NVL(vd.REMISE,0) / 100)
        + (vd.QTE * NVL(vd.REMISEARBIOCHEM,0))
        AS NUMBER(30,2)
    ) AS MONTANTREMISE,

    /* TVA */
    CAST(
        (NVL(vd.TVA,0) / 100) *
        (
            (vd.QTE * vd.PU)
            - (
                (vd.QTE * vd.PU * NVL(vd.REMISE,0) / 100)
                + (vd.QTE * NVL(vd.REMISEARBIOCHEM,0))
            )
            - (
                (
                    (vd.QTE * vd.PU)
                    - (
                        (vd.QTE * vd.PU * NVL(vd.REMISE,0) / 100)
                        + (vd.QTE * NVL(vd.REMISEARBIOCHEM,0))
                    )
                ) * NVL(vd.RISTOURNE,0) / 100
            )
            - NVL(
                p.CALORIE * vd.QTE * v.FRAISLIVRAISON,
                0
            )
        )
        AS NUMBER(30,2)
    ) AS MONTANTTVA,

    /* TTC */
    CAST(
        (
            (
                (vd.QTE * vd.PU)
                - (
                    (vd.QTE * vd.PU * NVL(vd.REMISE,0) / 100)
                    + (vd.QTE * NVL(vd.REMISEARBIOCHEM,0))
                )
                - (
                    (
                        (vd.QTE * vd.PU)
                        - (
                            (vd.QTE * vd.PU * NVL(vd.REMISE,0) / 100)
                            + (vd.QTE * NVL(vd.REMISEARBIOCHEM,0))
                        )
                    ) * NVL(vd.RISTOURNE,0) / 100
                )
                - NVL(
                    p.CALORIE * vd.QTE * v.FRAISLIVRAISON,
                    0
                )
            )
            * (1 + NVL(vd.TVA,0) / 100)
        )
        AS NUMBER(30,2)
    ) AS MONTANTTTC,

    vd.DATEDEBUT,

    CAST(
        NVL(p.CALORIE,0)
        AS NUMBER(10,2)
    ) AS CALORIE,

    vd.RISTOURNE,

    CAST(
        p.CALORIE
        AS NUMBER(30,2)
    ) AS POIDSPARKILO,

    CAST(
        v.FRAISLIVRAISON
        AS NUMBER(30,2)
    ) AS FRAISLIVRAISON,

    CAST(
        p.CALORIE * vd.QTE
        AS NUMBER(30,2)
    ) AS POIDSTOTAL,

    CAST(
        vd.PU / NVL(eq.QUANTITE,1)
        AS NUMBER(30,2)
    ) AS PUINGREDIENT,

    NVL(eq.QUANTITE,1) AS CONTENUE,

    p.UNITE2,
    vd.remisearbiochem

FROM PROFORMA_DETAILS vd

LEFT JOIN PROFORMA v
    ON v.ID = vd.IDPROFORMA

LEFT JOIN AS_INGREDIENTS p
    ON p.ID = vd.IDPRODUIT

LEFT JOIN AS_UNITE au
    ON au.ID = vd.UNITE

LEFT JOIN EQUIVALENCEVENTE eq
    ON eq.IDPRODUIT1 = p.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PROFORMAMONTANT2" ("ID", "POIDSTOTAL", "MONTANT", "MONTANTREMISE", "MONTANTRISTOURNE", "FRAISTRANSPORT", "MONTANTTOTAL", "MONTANTTOTALACHAT", "MONTANTTVA", "MONTANTTTC", "IDDEVISE", "TAUXDECHANGE", "MONTANTTTCAR", "MONTANTREVIENT", "IDRESERVATION") AS
SELECT v.ID,
       cast(SUM(poidstotal) as number(30, 2))                            AS poidstotal,
       cast(SUM(puTotal) as number(30, 2))                               AS montant,
       cast(SUM(remisemontant) as number(30, 2))                         as montantremise,
       cast(SUM(montantristourne) as number(30, 2))                      as montantristourne,
       cast(SUM(vd.fraistransport) as number(30, 2))                     as fraistransport,
       cast(SUM(montanttotal) as number(30, 2))                          AS montanttotal,
       cast(SUM((NVL(vd.QTE, 0) * NVL(vd.PuAchat, 0))) as number(30, 2)) AS montanttotalachat,
       cast(SUM(montanttva) as number(30, 2))                            AS montantTva,
       cast(SUM(montantttc) as number(30, 2))                            as montantTTC,
       NVL(vd.IDDEVISE, 'AR')                                            AS IDDEVISE,
       NVL(avg(vd.tauxDeChange), 1)                                      AS tauxDeChange,
       cast(SUM(montantttc * vd.TAUXDECHANGE) as number(30, 2))          as montantTTCAR,
       cast(sum(vd.PUREVIENT * vd.QTE) as number(20, 2))                 as montantRevient,
       v.IDRESERVATION
FROM PROFORMADETAILS_CPL vd
         LEFT JOIN PROFORMA v ON v.ID = vd.IDPROFORMA
GROUP BY v.ID, vd.IDDEVISE, v.IDRESERVATION;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PROFORMAMONTANTLEGER" ("ID", "MONTANTTOTAL", "MONTANTREMISE", "FRAIS", "MONTANTTOTALACHAT", "MONTANTTVA", "MONTANTTTC", "IDDEVISE", "TAUXDECHANGE", "MONTANTTTCAR", "MONTANTREVIENT", "IDRESERVATION", "POIDS", "COLIS", "MONTANTRISTOURNE") AS
SELECT v.ID,
       cast(SUM((NVL(vd.QTE, 0) * NVL(vd.PU, 0)) -
                (nvl(v.fraislivraison, 0) * nvl(ing.CALORIE, 0) * vd.QTE)) as number(30, 2))                          AS montanttotal,
       cast(SUM((NVL(vd.QTE, 0) * NVL(vd.PU, 0))) -
            SUM((1 - nvl(vd.remise / 100, 0)) * (NVL(vd.QTE, 0) * NVL(vd.PU, 0))) as number(30, 2))                  AS montantremise,
       cast(sum(nvl(v.fraislivraison, 0) * NVL(ing.CALORIE, 0) * NVL(vd.QTE, 0)) as number(30, 5)   )      as frais,
       cast(SUM((NVL(vd.QTE, 0) * NVL(vd.PuAchat, 0))) as number(30, 2))                                             AS montanttotalachat,
       cast(SUM(((1 - nvl(vd.remise / 100, 0)) * (NVL(vd.QTE, 0) * NVL(vd.PU, 0)) -
                (nvl(v.fraislivraison, 0) * nvl(ing.CALORIE, 0) * vd.QTE)) * (NVL(VD.TVA, 0)) /
                100) as number(30, 2))                                                                               AS montantTva,
       cast(SUM(((1 - nvl(vd.remise / 100, 0)) * (NVL(vd.QTE, 0) * NVL(vd.PU, 0)) -
                 (nvl(v.fraislivraison, 0) * nvl(ing.CALORIE, 0) * vd.QTE)) * (NVL(VD.TVA, 0)) / 100) +
            SUM((1 - nvl(vd.remise / 100, 0)) * (NVL(vd.QTE, 0) * NVL(vd.PU, 0)) -
                (nvl(v.fraislivraison, 0) * nvl(ing.CALORIE, 0) * vd.QTE)) as number(30, 2))                          as montantTTC,
       NVL(vd.IDDEVISE, 'AR')                                                                                        AS IDDEVISE,
       NVL(avg(vd.tauxDeChange), 1)                                                                                  AS tauxDeChange,
       cast((SUM(((1 - nvl(vd.remise / 100, 0)) * (NVL(vd.QTE, 0) * NVL(vd.PU, 0)) -
                 (nvl(v.fraislivraison, 0) * nvl(ing.CALORIE, 0) * vd.QTE)) * (NVL(VD.TVA, 0)) / 100) +
            SUM((1 - nvl(vd.remise / 100, 0)) * (NVL(vd.QTE, 0) * NVL(vd.PU, 0)) -
                (nvl(v.fraislivraison, 0) * nvl(ing.CALORIE, 0) * vd.QTE))*NVL(avg(vd.tauxDeChange), 1) ) as number(30, 2)) as montantTTCAR,
       cast(sum(vd.PUREVIENT * vd.QTE) as number(20, 2))                                                             as montantRevient,
       v.IDRESERVATION,nvl(sum(vd.QTE*ing.CALORIE),0) as poids,sum(vd.QTE) as colis,
       cast(sum((vd.QTE * vd.PU) - ((vd.QTE * vd.PU) * NVL(vd.remise, 0)) / 100  * nvl(vd.ristourne, 0) /100) as number(30, 2)) as montantristourne
FROM PROFORMA_DETAILS vd
         LEFT JOIN PROFORMA v ON v.ID = vd.IDPROFORMA
         left join AS_INGREDIENTS ing on ing.id = vd.IDPRODUIT
GROUP BY v.id, vd.IDDEVISE, v.IDRESERVATION order by v.id asc;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PROFORMAMONTANTLEGER2" ("ID", "MONTANTTOTAL", "MONTANTREMISE", "FRAIS", "MONTANTTOTALACHAT", "MONTANTTVA", "MONTANTTTC", "IDDEVISE", "TAUXDECHANGE", "MONTANTTTCAR", "MONTANTREVIENT", "IDRESERVATION", "POIDS", "COLIS", "MONTANTRISTOURNE") AS
SELECT
    v.ID,

    CAST(SUM(
            (NVL(vd.QTE,0) * NVL(vd.PU,0))
                - ((NVL(vd.QTE,0) * NVL(vd.PU,0) * NVL(vd.remise,0) / 100) + (NVL(vd.QTE,0) * NVL(vd.remiseArbiochem,0)))
                - (
                (((NVL(vd.QTE,0) * NVL(vd.PU,0)) - ((NVL(vd.QTE,0) * NVL(vd.PU,0) * NVL(vd.remise,0) / 100) + (NVL(vd.QTE,0) * NVL(vd.remiseArbiochem,0)))) * NVL(vd.ristourne,0) / 100)
                    + (NVL(vd.QTE,0) * NVL(vd.ristourneArbiochem,0))
                )
                - NVL(ing.CALORIE * vd.QTE * v.fraislivraison, 0)
         ) AS NUMBER(30,2)) AS montanttotal,

    CAST(SUM(
            (NVL(vd.QTE,0) * NVL(vd.PU,0) * NVL(vd.remise,0) / 100) + (NVL(vd.QTE,0) * NVL(vd.remiseArbiochem,0))
         ) AS NUMBER(30,2)) AS montantremise,

    CAST(SUM(NVL(v.fraislivraison,0) * NVL(ing.CALORIE,0) * NVL(vd.QTE,0)) AS NUMBER(30,5)) AS frais,

    CAST(SUM(NVL(vd.QTE,0) * NVL(vd.PUACHAT,0)) AS NUMBER(30,2)) AS montanttotalachat,

    CAST(SUM(
            NVL(vd.TVA,0) / 100 * (
                (NVL(vd.QTE,0) * NVL(vd.PU,0))
                    - ((NVL(vd.QTE,0) * NVL(vd.PU,0) * NVL(vd.remise,0) / 100) + (NVL(vd.QTE,0) * NVL(vd.remiseArbiochem,0)))
                    - (
                    (((NVL(vd.QTE,0) * NVL(vd.PU,0)) - ((NVL(vd.QTE,0) * NVL(vd.PU,0) * NVL(vd.remise,0) / 100) + (NVL(vd.QTE,0) * NVL(vd.remiseArbiochem,0)))) * NVL(vd.ristourne,0) / 100)
                        + (NVL(vd.QTE,0) * NVL(vd.ristourneArbiochem,0))
                    )
                    - NVL(ing.CALORIE * vd.QTE * v.fraislivraison, 0)
                )
         ) AS NUMBER(30,2)) AS montantTva,

    CAST(SUM(
            (NVL(vd.TVA,0) / 100 + 1) * (
                (NVL(vd.QTE,0) * NVL(vd.PU,0))
                    - ((NVL(vd.QTE,0) * NVL(vd.PU,0) * NVL(vd.remise,0) / 100) + (NVL(vd.QTE,0) * NVL(vd.remiseArbiochem,0)))
                    - (
                    (((NVL(vd.QTE,0) * NVL(vd.PU,0)) - ((NVL(vd.QTE,0) * NVL(vd.PU,0) * NVL(vd.remise,0) / 100) + (NVL(vd.QTE,0) * NVL(vd.remiseArbiochem,0)))) * NVL(vd.ristourne,0) / 100)
                        + (NVL(vd.QTE,0) * NVL(vd.ristourneArbiochem,0))
                    )
                    - NVL(ing.CALORIE * vd.QTE * v.fraislivraison, 0)
                )
         ) AS NUMBER(30,2)) AS montantTTC,

    NVL(v.IDDEVISE, 'AR') AS IDDEVISE,

    NVL(AVG(vd.tauxDeChange), 1) AS tauxDeChange,

    CAST(
            SUM(
                    (NVL(vd.TVA,0) / 100 + 1) * (
                        (NVL(vd.QTE,0) * NVL(vd.PU,0))
                            - ((NVL(vd.QTE,0) * NVL(vd.PU,0) * NVL(vd.remise,0) / 100) + (NVL(vd.QTE,0) * NVL(vd.remiseArbiochem,0)))
                            - (
                            (((NVL(vd.QTE,0) * NVL(vd.PU,0)) - ((NVL(vd.QTE,0) * NVL(vd.PU,0) * NVL(vd.remise,0) / 100) + (NVL(vd.QTE,0) * NVL(vd.remiseArbiochem,0)))) * NVL(vd.ristourne,0) / 100)
                                + (NVL(vd.QTE,0) * NVL(vd.ristourneArbiochem,0))
                            )
                            - NVL(ing.CALORIE * vd.QTE * v.fraislivraison, 0)
                        )
            ) * NVL(AVG(vd.tauxDeChange), 1)
        AS NUMBER(30,2)) AS montantTTCAR,

    CAST(SUM(vd.PUREVIENT * vd.QTE) AS NUMBER(20,2)) AS montantRevient,

    v.IDRESERVATION,

    NVL(SUM(vd.QTE * ing.CALORIE), 0) AS poids,

    SUM(vd.QTE) AS colis,

    CAST(SUM(
            (((NVL(vd.QTE,0) * NVL(vd.PU,0)) - ((NVL(vd.QTE,0) * NVL(vd.PU,0) * NVL(vd.remise,0) / 100) + (NVL(vd.QTE,0) * NVL(vd.remiseArbiochem,0)))) * NVL(vd.ristourne,0) / 100)
                + (NVL(vd.QTE,0) * NVL(vd.ristourneArbiochem,0))
         ) AS NUMBER(30,2)) AS montantristourne

FROM PROFORMA_DETAILS vd
         LEFT JOIN PROFORMA v ON v.ID = vd.IDPROFORMA
         LEFT JOIN AS_INGREDIENTS ing ON ing.ID = vd.IDPRODUIT
GROUP BY v.id, v.IDDEVISE, v.IDRESERVATION
ORDER BY v.id ASC;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PROFORMA_CPL" ("ID", "DESIGNATION", "IDMAGASIN", "IDMAGASINLIB", "DATY", "REMARQUE", "ETAT", "ETATLIB", "IDDEVISE", "IDCLIENT", "CODECLIENT", "IDCLIENTLIB", "ADRESSE", "CONTACT", "POIDSTOTAL", "MONTANT", "MONTANTREMISE", "MONTANTRISTOURNE", "FRAISLIVRAISON", "FRAISTRANSPORT", "MONTANTTOTAL", "MONTANTTVA", "MONTANTTTC", "MONTANTTTCAR", "MONTANTPAYE", "MONTANTRESTE", "AVOIR", "TAUXDECHANGE", "MONTANTREVIENT", "MARGEBRUTE", "IDRESERVATION", "IDORIGINE", "REMISE", "NUMEROPROFORMA", "IDCOMMANDE", "MODELIVRAISONLIB", "LIEULIVRAISON", "DATELIVRAISON", "REFERENCE", "MOTSCLESSS") AS
SELECT V.ID,
       V.DESIGNATION,
       V.IDMAGASIN,
       M.VAL                                                                                  AS IDMAGASINLIB,
       V.DATY,
       V.REMARQUE,
       V.ETAT,
       CASE
           WHEN V.ETAT = 1 THEN 'CR&Eacute;&Eacute;'
           WHEN V.ETAT = 11 THEN 'VIS&Eacute;'
           WHEN V.ETAT = 0 THEN 'ANNUL&Eacute;E'
           WHEN V.ETAT = 12 THEN '<span style=color: green;>CL&Ocirc;TUR&Eacute;</span>'
           END                                                                                AS ETATLIB,
       V2.IDDEVISE,
       V.IDCLIENT,
       C.CODECLIENT,
       C.NOM                                                                                  AS IDCLIENTLIB,
       C.ADRESSE,
       C.TELEPHONE                                                                            AS CONTACT,
       CAST(V2.POIDS AS NUMBER(30, 2))                                                        AS POIDSTOTAL,
       CAST(V2.MONTANTTOTAL AS NUMBER(30, 2))                                                 AS MONTANT,
       CAST(V2.MONTANTREMISE AS NUMBER(30, 2))                                                AS MONTANTREMISE,
       CAST(V2.MONTANTRISTOURNE AS NUMBER(30, 2))                                             AS MONTANTRISTOURNE,
       CAST(NVL(V.FRAISLIVRAISON, 0) AS NUMBER(10, 2))                                        AS FRAISLIVRAISON,
       CAST(V2.FRAIS AS NUMBER(30, 2))                                                        AS FRAISTRANSPORT,
       CAST(V2.MONTANTTOTAL AS NUMBER(30, 2))                                                 AS MONTANTTOTAL,
       CAST(V2.MONTANTTVA AS NUMBER(30, 2))                                                   AS MONTANTTVA,
       CAST(V2.MONTANTTTC AS NUMBER(30, 2))                                                   AS MONTANTTTC,
       CAST(V2.MONTANTTTCAR AS NUMBER(30, 2))                                                 AS MONTANTTTCAR,
       CAST(0 AS NUMBER(30, 2))                                                               AS MONTANTPAYE,
       CAST(0 AS NUMBER(30, 2))                                                               AS MONTANTRESTE,
       0                                                                                      AS AVOIR,
       CAST(V2.TAUXDECHANGE AS NUMBER(10, 2))                                                 AS TAUXDECHANGE,
       CAST(V2.MONTANTREVIENT AS NUMBER(20, 5))                                               AS MONTANTREVIENT,
       CAST((COALESCE(V2.MONTANTTTCAR, 0) - COALESCE(V2.MONTANTREVIENT, 0)) AS NUMBER(20, 5)) AS MARGEBRUTE,
       V.IDRESERVATION,
       V.IDORIGINE,
       NVL(V.REMISE, 0)                                                                       AS REMISE,
       V.NUMEROPROFORMA,
       V.IDCOMMANDE,
       CASE
           WHEN V.MODELIVRAISON = 1 THEN 'LIVRAISON'
           WHEN V.MODELIVRAISON = 2 THEN 'RECUPERATION'
           END                                                                                AS MODELIVRAISONLIB,
       V.LIEULIVRAISON                                                                        AS LIEULIVRAISON,
       V.DATELIVRAISON                                                                        AS DATELIVRAISON,
       V.REFERENCE,
       (
           V.ID || ' | ' || NUMEROPROFORMA || ' | ' || C.NOM || ' | ' || M.VAL
           )                                                                                  AS MOTSCLESSS
FROM PROFORMA V
         LEFT JOIN CLIENT C ON C.ID = V.IDCLIENT
         LEFT JOIN MAGASIN2 M ON M.ID = V.IDMAGASIN
         JOIN PROFORMAMONTANTLEGER V2 ON V2.ID = V.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PROFORMA_CPL2" ("ID", "DESIGNATION", "IDMAGASIN", "IDMAGASINLIB", "DATY", "REMARQUE", "ETAT", "ETATLIB", "IDDEVISE", "IDCLIENT", "CODECLIENT", "IDCLIENTLIB", "ADRESSE", "CONTACT", "POIDSTOTAL", "MONTANT", "MONTANTREMISE", "MONTANTRISTOURNE", "FRAISLIVRAISON", "FRAISTRANSPORT", "MONTANTTOTAL", "MONTANTTVA", "MONTANTTTC", "MONTANTTTCAR", "MONTANTPAYE", "MONTANTRESTE", "AVOIR", "TAUXDECHANGE", "MONTANTREVIENT", "MARGEBRUTE", "IDRESERVATION", "IDORIGINE", "REMISE", "NUMEROPROFORMA", "IDCOMMANDE", "MODELIVRAISONLIB", "LIEULIVRAISON", "DATELIVRAISON", "REFERENCE", "MOTSCLESSS") AS
SELECT V.ID,
       V.DESIGNATION,
       V.IDMAGASIN,
       M.VAL                                                                                  AS IDMAGASINLIB,
       V.DATY,
       V.REMARQUE,
       V.ETAT,
       CASE
           WHEN V.ETAT = 1 THEN 'CR&Eacute;&Eacute;'
           WHEN V.ETAT = 11 THEN 'VIS&Eacute;'
           WHEN V.ETAT = 0 THEN 'ANNUL&Eacute;E'
           WHEN V.ETAT = 12 THEN '<span style=color: green;>CL&Ocirc;TUR&Eacute;</span>'
           END                                                                                AS ETATLIB,
       V2.IDDEVISE,
       V.IDCLIENT,
       C.CODECLIENT,
       C.NOM                                                                                  AS IDCLIENTLIB,
       C.ADRESSE,
       C.TELEPHONE                                                                            AS CONTACT,
       CAST(V2.POIDS AS NUMBER(30, 2))                                                        AS POIDSTOTAL,
       CAST((V2.MONTANTTOTAL+V2.MONTANTREMISE )AS NUMBER(30, 2))                                                 AS MONTANT,
       CAST(V2.MONTANTREMISE AS NUMBER(30, 2))                                                AS MONTANTREMISE,
       CAST(V2.MONTANTRISTOURNE AS NUMBER(30, 2))                                             AS MONTANTRISTOURNE,
       CAST(NVL(V.FRAISLIVRAISON, 0) AS NUMBER(10, 2))                                        AS FRAISLIVRAISON,
       CAST(V2.FRAIS AS NUMBER(30, 2))                                                        AS FRAISTRANSPORT,
       CAST(V2.MONTANTTOTAL AS NUMBER(30, 2))                                                 AS MONTANTTOTAL,
       CAST(V2.MONTANTTVA AS NUMBER(30, 2))                                                   AS MONTANTTVA,
       CAST(V2.MONTANTTTC AS NUMBER(30, 2))                                                   AS MONTANTTTC,
       CAST(V2.MONTANTTTCAR AS NUMBER(30, 2))                                                 AS MONTANTTTCAR,
       CAST(0 AS NUMBER(30, 2))                                                               AS MONTANTPAYE,
       CAST(0 AS NUMBER(30, 2))                                                               AS MONTANTRESTE,
       0                                                                                      AS AVOIR,
       CAST(V2.TAUXDECHANGE AS NUMBER(10, 2))                                                 AS TAUXDECHANGE,
       CAST(V2.MONTANTREVIENT AS NUMBER(20, 5))                                               AS MONTANTREVIENT,
       CAST((COALESCE(V2.MONTANTTTCAR, 0) - COALESCE(V2.MONTANTREVIENT, 0)) AS NUMBER(20, 5)) AS MARGEBRUTE,
       V.IDRESERVATION,
       V.IDORIGINE,
       NVL(V.REMISE, 0)                                                                       AS REMISE,
       V.NUMEROPROFORMA,
       V.IDCOMMANDE,
       CASE
           WHEN V.MODELIVRAISON = 1 THEN 'LIVRAISON'
           WHEN V.MODELIVRAISON = 2 THEN 'RECUPERATION'
           END                                                                                AS MODELIVRAISONLIB,
       V.LIEULIVRAISON                                                                        AS LIEULIVRAISON,
       V.DATELIVRAISON                                                                        AS DATELIVRAISON,
       V.REFERENCE,
       (
           V.ID || ' | ' || NUMEROPROFORMA || ' | ' || C.NOM || ' | ' || M.VAL
           )                                                                                  AS MOTSCLESSS
FROM PROFORMA V
         LEFT JOIN CLIENT C ON C.ID = V.IDCLIENT
         LEFT JOIN MAGASIN2 M ON M.ID = V.IDMAGASIN
         JOIN PROFORMAMONTANTLEGER2 V2 ON V2.ID = V.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PROFORMA_CPL_CREE" ("ID", "DESIGNATION", "IDMAGASIN", "IDMAGASINLIB", "DATY", "REMARQUE", "ETAT", "ETATLIB", "IDDEVISE", "IDCLIENT", "CODECLIENT", "IDCLIENTLIB", "ADRESSE", "CONTACT", "POIDSTOTAL", "MONTANT", "MONTANTREMISE", "MONTANTRISTOURNE", "FRAISLIVRAISON", "FRAISTRANSPORT", "MONTANTTOTAL", "MONTANTTVA", "MONTANTTTC", "MONTANTTTCAR", "MONTANTPAYE", "MONTANTRESTE", "AVOIR", "TAUXDECHANGE", "MONTANTREVIENT", "MARGEBRUTE", "IDRESERVATION", "IDORIGINE", "REMISE", "NUMEROPROFORMA", "IDCOMMANDE", "MODELIVRAISONLIB", "LIEULIVRAISON", "DATELIVRAISON", "REFERENCE", "MOTSCLESSS") AS
SELECT V."ID",V."DESIGNATION",V."IDMAGASIN",V."IDMAGASINLIB",V."DATY",V."REMARQUE",V."ETAT",V."ETATLIB",V."IDDEVISE",V."IDCLIENT",V."CODECLIENT",V."IDCLIENTLIB",V."ADRESSE",V."CONTACT",V."POIDSTOTAL",V."MONTANT",V."MONTANTREMISE",V."MONTANTRISTOURNE",V."FRAISLIVRAISON",V."FRAISTRANSPORT",V."MONTANTTOTAL",V."MONTANTTVA",V."MONTANTTTC",V."MONTANTTTCAR",V."MONTANTPAYE",V."MONTANTRESTE",V."AVOIR",V."TAUXDECHANGE",V."MONTANTREVIENT",V."MARGEBRUTE",V."IDRESERVATION",V."IDORIGINE",V."REMISE",V."NUMEROPROFORMA",V."IDCOMMANDE",V."MODELIVRAISONLIB",V."LIEULIVRAISON",V."DATELIVRAISON",V."REFERENCE",V."MOTSCLESSS"
FROM PROFORMA_CPL V
WHERE ETAT = 1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PROFORMA_CPL_VISEE" ("ID", "DESIGNATION", "IDMAGASIN", "IDMAGASINLIB", "DATY", "REMARQUE", "ETAT", "ETATLIB", "IDDEVISE", "IDCLIENT", "CODECLIENT", "IDCLIENTLIB", "ADRESSE", "CONTACT", "POIDSTOTAL", "MONTANT", "MONTANTREMISE", "MONTANTRISTOURNE", "FRAISLIVRAISON", "FRAISTRANSPORT", "MONTANTTOTAL", "MONTANTTVA", "MONTANTTTC", "MONTANTTTCAR", "MONTANTPAYE", "MONTANTRESTE", "AVOIR", "TAUXDECHANGE", "MONTANTREVIENT", "MARGEBRUTE", "IDRESERVATION", "IDORIGINE", "REMISE", "NUMEROPROFORMA", "IDCOMMANDE", "MODELIVRAISONLIB", "LIEULIVRAISON", "DATELIVRAISON", "REFERENCE", "MOTSCLESSS") AS
SELECT V."ID",V."DESIGNATION",V."IDMAGASIN",V."IDMAGASINLIB",V."DATY",V."REMARQUE",V."ETAT",V."ETATLIB",V."IDDEVISE",V."IDCLIENT",V."CODECLIENT",V."IDCLIENTLIB",V."ADRESSE",V."CONTACT",V."POIDSTOTAL",V."MONTANT",V."MONTANTREMISE",V."MONTANTRISTOURNE",V."FRAISLIVRAISON",V."FRAISTRANSPORT",V."MONTANTTOTAL",V."MONTANTTVA",V."MONTANTTTC",V."MONTANTTTCAR",V."MONTANTPAYE",V."MONTANTRESTE",V."AVOIR",V."TAUXDECHANGE",V."MONTANTREVIENT",V."MARGEBRUTE",V."IDRESERVATION",V."IDORIGINE",V."REMISE",V."NUMEROPROFORMA",V."IDCOMMANDE",V."MODELIVRAISONLIB",V."LIEULIVRAISON",V."DATELIVRAISON",V."REFERENCE",V."MOTSCLESSS"
FROM PROFORMA_CPL V
WHERE ETAT = 11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PROFORMA_DETAILS_VIDE" ("ID", "IDPROFORMA", "IDPRODUIT", "IDORIGINE", "QTE", "PU", "REMISE", "TVA", "PUACHAT", "PUVENTE", "IDDEVISE", "TAUXDECHANGE", "DESIGNATION", "COMPTE", "PUREVIENT", "IDDEMANDEPRIXFILLE", "UNITE", "DATEDEBUT", "UNITELIB", "PUNET", "MONTANTHT", "MONTANTTTC", "RISTOURNE", "CALORIE", "REMISEARBIOCHEM", "RISTOURNEARBIOCHEM") AS
select p.ID,
       p.IDPROFORMA,
       p.IDPRODUIT,
       p.IDORIGINE,
       p.QTE,
       p.PU,
       p.REMISE,
       p.TVA,
       p.PUACHAT,
       p.PUVENTE,
       p.IDDEVISE,
       p.TAUXDECHANGE,
       p.DESIGNATION,
       p.COMPTE,
       p.PUREVIENT,
       p.IDDEMANDEPRIXFILLE,
       p.UNITE,
       p.DATEDEBUT,
       u.val as unitelib,
       0  as punet,
       0  as montantht,
       0  as montantttc,
       p.RISTOURNE,
       ing.CALORIE,
       p.remiseArbiochem,
       p.ristourneArbiochem
from PROFORMA_DETAILS p
         LEFT JOIN as_unite u ON p.unite=u.id
         LEFT JOIN  AS_INGREDIENTS ing ON p.IDPRODUIT = ing.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PROGRAMMEZOOTECHNIQUEDT_LIB" ("ID", "IDMERE", "AGE", "IDSEXE", "ALIMENT", "POIDS", "MORTALITE", "PONTEHEBDOMADAIRE", "PONTECUMULEE", "OEUFCUMULE", "OACPOURCENTAGE", "OACHH", "POIDSOEUF", "TAUXECLOSION", "POUSSINS", "CONSOALIMENTFEMELLE", "FEMELLEBW", "MALEBW", "RATIOPRODUCTION", "FERTILITE", "IDSEXELIB", "CONSOMMATIONEAU", "TEMPERATUREMIN", "TEMPERATUREMAX", "HUMIDITEMIN", "HUMIDITEMAX", "DUREEECLAIRAGE", "UNIFORMITECIBLE", "CVMAX") AS
SELECT
	d."ID",
	d."IDMERE",
	d."AGE",
	d."IDSEXE",
	d."ALIMENT",
	d."POIDS",
	d."MORTALITE",
	d."PONTEHEBDOMADAIRE",
	d."PONTECUMULEE",
	d."OEUFCUMULE",
	d."OACPOURCENTAGE",
	d."OACHH",
	d."POIDSOEUF",
	d."TAUXECLOSION",
	d."POUSSINS",
	d."CONSOALIMENTFEMELLE",
	d."FEMELLEBW",
	d."MALEBW",
	d."RATIOPRODUCTION",
	d."FERTILITE",
	sx."VAL" AS "IDSEXELIB",
	d."CONSOMMATIONEAU", 
	d."TEMPERATUREMIN", 
	d."TEMPERATUREMAX", 
	d."HUMIDITEMIN", 
	d."HUMIDITEMAX", 
	d."DUREEECLAIRAGE", 
	d."UNIFORMITECIBLE", 
	d."CVMAX"
	
FROM
	"PROGRAMMEZOOTECHNIQUEDETAILS" d
LEFT JOIN "SEXE" sx ON
	sx."ID" = d."IDSEXE";

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PROGRAMMEZOOTECHNIQUE_LIB" ("ID", "CODE", "IDSOUCHE", "VERSION", "DATY", "IDSOUCHELIB", "ETATLIB") AS
SELECT p."ID",p."CODE",p."IDSOUCHE",p."VERSION",p."DATY",
       s."VAL" AS "IDSOUCHELIB",
       CASE
             WHEN p.ETAT = 1 THEN 'CR&Eacute;&Eacute;'
             WHEN p.ETAT = 11 THEN 'VIS&Eacute;'
             WHEN p.ETAT = 0 THEN 'ANNUL&Eacute;'
          END
             AS ETATLIB
FROM "PROGRAMMEZOOTECHNIQUE" p
         LEFT JOIN "SOUCHE" s ON s."ID" = p."IDSOUCHE";

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PV_VISA_MULTIPLE_CREE" ("ID", "IDPERSONNEL", "MATRICULE", "PERSONNEL", "MOIS", "MOISLIB", "ANNEE", "HEURENORMAL", "HEURESUPNORMAL", "HEURESUPNUIT", "HEURESUPFERIE", "HEURESUPWEEKEND", "ABSENCE", "ETAT", "DIRECTION", "DIRECTIONLIB") AS
SELECT
    ID,
    IDPERSONNEL,
    MATRICULE,
    PERSONNEL,
    MOIS,
    MOISLIB,
    ANNEE,
    CAST(HEURENORMAL AS NUMBER(20,2)) AS HEURENORMAL,
    CAST(HEURESUPNORMAL AS NUMBER(20,2)) AS HEURESUPNORMAL,
    CAST(HEURESUPNUIT AS NUMBER(20,2)) AS HEURESUPNUIT,
    CAST(HEURESUPFERIE AS NUMBER(20,2)) AS HEURESUPFERIE,
    CAST(HEURESUPWEEKEND AS NUMBER(20,2)) AS HEURESUPWEEKEND,
    CAST(ABSENCE AS NUMBER(20,2)) AS ABSENCE,
    ETAT,
    DIRECTION,
    DIRECTIONLIB
FROM
    POINTAGEVISEE_VISA_MULTIPLE
WHERE
    etat = 1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PV_VISA_MULTIPLE_VISEE" ("ID", "IDPERSONNEL", "MATRICULE", "PERSONNEL", "MOIS", "MOISLIB", "ANNEE", "HEURENORMAL", "HEURESUPNORMAL", "HEURESUPNUIT", "HEURESUPFERIE", "HEURESUPWEEKEND", "ABSENCE", "ETAT", "DIRECTION", "DIRECTIONLIB") AS
SELECT
    ID,
    IDPERSONNEL,
    MATRICULE,
    PERSONNEL,
    MOIS,
    MOISLIB,
    ANNEE,
    CAST(HEURENORMAL AS NUMBER(20,2)) AS HEURENORMAL,
    CAST(HEURESUPNORMAL AS NUMBER(20,2)) AS HEURESUPNORMAL,
    CAST(HEURESUPNUIT AS NUMBER(20,2)) AS HEURESUPNUIT,
    CAST(HEURESUPFERIE AS NUMBER(20,2)) AS HEURESUPFERIE,
    CAST(HEURESUPWEEKEND AS NUMBER(20,2)) AS HEURESUPWEEKEND,
    CAST(ABSENCE AS NUMBER(20,2)) AS ABSENCE,
    ETAT,
    DIRECTION,
    DIRECTIONLIB
FROM
    POINTAGEVISEE_VISA_MULTIPLE
WHERE
    etat = 11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."QTEFABANDRESTFABBYIDBC" ("IDFABFILLE", "IDBCFILLE", "IDMERE", "QTEFAB", "QTEFABRESTANTE") AS
SELECT  
	f.ID AS IDFABFILLE,
	f.IDBCFILLE ,
	f.IDMERE ,
	f.QTE AS QTEFAB, 
    NVL(f.QTE, 0) - NVL(bcf.QUANTITE, 0) AS QTEFABRESTANTE
FROM FABRICATIONFILLE f 
LEFT JOIN BONDECOMMANDE_CLIENT_FILLE bcf 
	ON bcf.ID = f.IDBCFILLE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."QTEOFANDRESTOFBYIDBC" ("IDOFFILLE", "IDBCFILLE", "IDMERE", "QTEOF", "QTEOFRESTANTE") AS
SELECT  
    o.ID AS IDOFFILLE, 
    o.IDBCFILLE, 
    o.IDMERE, 
    o.QTE AS QTEOF, 
    NVL(o.QTE, 0) - NVL(bcf.QUANTITE, 0) AS QTEOFRESTANTE
FROM OFFILLE o 
LEFT JOIN BONDECOMMANDE_CLIENT_FILLE bcf 
    ON bcf.ID = o.IDBCFILLE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."QTE_DISPO_LOT_SEXE_QUALITELIB" ("IDLOT", "IDQUALITE", "IDSEXE", "QTE") AS
SELECT
    rpd.IDLOT              AS IDLOT,
    rpd.IDQUALITEPOUSSIN   AS IDQUALITE,
    rpd.IDSEXE             AS IDSEXE,
    SUM(rpd.QTE)           AS QTE
FROM RECEPTIONPOUSSINAEDETAIL_LIB rpd
GROUP BY rpd.IDLOT, rpd.IDQUALITEPOUSSIN, rpd.IDSEXE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RAPPROCHEMENTBCETAT" ("ID", "IDSOUSECRITURE", "IDRELEVERDETAIL", "VALEURSOUSECRITURE", "VALEURRELEVERDETAIL", "DATY", "ETAT", "IDMERE") AS
select rp.id,rp.IDSOUSECRITURE,rp.IDRELEVERDETAIL,rp.VALEURSOUSECRITURE,rp.VALEURRELEVERDETAIL,rp.DATY,rpm.ETAT,rp.IDMERE from RapprochementBC rp join RAPPROCHEMENTBCMERE rpm on rp.IDMERE=rpm.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RAPPROCHEMENTBCMERELIB" ("ID", "IDBANQUE", "VALEUR", "DATY", "ETAT", "IDBANQUELIB", "ETATLIB") AS
select
    rp."ID",rp."IDBANQUE",rp."VALEUR",rp."DATY",rp."ETAT",
    ca.VAL as idbanquelib,
    CASE
        WHEN rp.ETAT = 1 THEN 'CREEE'
        WHEN rp.ETAT = 11 THEN 'VISEE'
        WHEN rp.ETAT = 0 THEN 'ANNULEE'
        END
           AS ETATLIB
from RAPPROCHEMENTBCMERE rp join CAISSE ca on ca.id=rp.idBanque;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RAPPROCHEMENTGLOBALE_PIE" ("ID", "VAL", "DESCE", "MONTANT") AS
select c.id, c.VAL , c.DESCE ,sum(f.pu * f.qte) as montant from FACTUREFOURNISSEURFILLE  f
                                                                    left join AS_INGREDIENTS a on f.IDPRODUIT = a.ID
                                                                    left join CATEGORIEINGREDIENT c on c.ID = a.CATEGORIEINGREDIENT
where c.id is not null
group by c.id, c.VAL,c.DESCE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RAPPROCHEMENTTRAVAUX" ("ID", "IDTRAVAUX", "IDPERSONNEL", "IDPERSONNELLIB", "DUREEESTIMATIF_HMS", "DUREEREEL_HMS", "ECART_HMS", "DUREEESTIMATIF_SECONDE", "DUREEREEL_SECONDE", "ECART_SECONDE", "MONTANTESTIMATIF", "MONTANTREEL", "MONTANTECART", "MOTSCLESSS") AS
SELECT SQ.ID,SQ.IDTRAVAUX,SQ.IDPERSONNEL,SQ.IDPERSONNELLIB,SQ.DUREEESTIMATIF_HMS,SQ.DUREEREEL_HMS,SQ.ECART_HMS,SQ.DUREEESTIMATIF_SECONDE,SQ.DUREEREEL_SECONDE,SQ.ECART_SECONDE,SQ.MONTANTESTIMATIF,SQ.MONTANTREEL,SQ.MONTANTECART,
	       (NVL(TO_CHAR(ID),'') || ' | ' || NVL(TO_CHAR(IDTRAVAUX),'') || ' | ' || NVL(TO_CHAR(IDPERSONNEL),'') || ' | ' || NVL(TO_CHAR(IDPERSONNELLIB),'') || ' | ' || NVL(TO_CHAR(DUREEESTIMATIF_HMS),'') || ' | ' || NVL(TO_CHAR(DUREEREEL_HMS),'') || ' | ' || NVL(TO_CHAR(ECART_HMS),'') || ' | ' || NVL(TO_CHAR(DUREEESTIMATIF_SECONDE),'') || ' | ' || NVL(TO_CHAR(DUREEREEL_SECONDE),'') || ' | ' || NVL(TO_CHAR(ECART_SECONDE),'') || ' | ' || NVL(TO_CHAR(MONTANTESTIMATIF),'') || ' | ' || NVL(TO_CHAR(MONTANTREEL),'') || ' | ' || NVL(TO_CHAR(MONTANTECART),'')) AS MOTSCLESSS
	FROM (
	         SELECT
	             '' AS ID,
	             mo.IDTRAVAUX,
	             mo.IDPERSONNEL,
	             mo.idPersonnelLib,
	             mo.dureeEstimatifLib AS dureeEstimatif_hms,
	             pr.dureeReelHMS AS dureeReel_hms,
	             -- Ecart HMS calcule avec ABS pour eviter le signe -
	             LPAD(FLOOR(ABS(TO_NUMBER(mo.DUREEESTIMATIF - pr.dureeReel)) / 3600), 2, '0') || ':' ||
	             LPAD(FLOOR(MOD(ABS(TO_NUMBER(mo.DUREEESTIMATIF - pr.dureeReel)), 3600) / 60), 2, '0') || ':' ||
	             LPAD(MOD(ABS(TO_NUMBER(mo.DUREEESTIMATIF - pr.dureeReel)), 60), 2, '0')
	                 AS ecart_hms,
	             mo.DUREEESTIMATIF AS dureeEstimatif_seconde,
	             pr.dureeReel AS dureeReel_seconde,
	             -- Ecart Seconde en valeur absolue
	             ABS(mo.DUREEESTIMATIF - pr.dureeReel) AS ecart_seconde,
	             mo.montant AS montantEstimatif,
	             ((pr.dureeReel/60)/60)*mo.TAUXHORAIRE AS montantReel,
	             -- Ecart Montant en valeur absolue
	             ABS(mo.montant - (((pr.dureeReel/60)/60)*mo.TAUXHORAIRE)) AS montantEcart
	         FROM MOTRAVAUXLIB mo
	                  LEFT JOIN ProcessMaintenanceGlobal pr ON pr.IDPERSONNEL = mo.IDPERSONNEL AND pr.IDTRAVAUX = mo.IDTRAVAUX
	     ) SQ;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RAPPROCHEMENT_BF_CLIENT" ("ID", "PRODUIT", "NUMBL", "QUANTITE", "IDVENTEDETAIL", "UNITE", "IDBC_FILLE", "IDPRODUITLIB", "IDVENTE", "IDBC", "QTELIVREE", "QTERESTEALIVRER", "QTESORTIE", "RESTEASORTIR", "PU", "UNITELIB") AS
SELECT abcc.ID,
       abcc.PRODUIT,
       abcc.NUMBL,
       abcc.QUANTITE,
       abcc.IDVENTEDETAIL,
       abcc.UNITE,
       abcc.IDBC_FILLE,
       abcc.IDPRODUITLIB,
       abcc.IDVENTE,
       abcc.IDBC,
       abcc.QTELIVREE,
       abcc.QTERESTEALIVRER,
       nvl(m.qteSortie, 0)                 AS qteSortie,
       least(abcc.qtevente - nvl(m.qteSortie, 0), abcc.QUANTITE) AS resteASortir,
       abcc.pu,
       au.val AS unitelib
FROM AS_BONLIVRFILLE_CLIENT_CPL abcc
         LEFT JOIN SORTIEPRODUITparventegrp m ON m.idproduit = abcc.produit and m.IDVENTE = abcc.idvente
         LEFT JOIN MVTSTOCK mv ON mv.idobjet = abcc.numbl
         LEFT JOIN as_unite au ON au.id = abcc.UNITE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RAPPROCHEMENT_BF_FOURNISSEUR" ("ID", "PRODUIT", "NUMBL", "QUANTITE", "IDDETAILSFACTUREFOURNISSEUR", "UNITE", "IDBC_FILLE", "REMARQUE", "IDBC", "DATY", "ETAT", "MAGASIN", "PRODUITLIB", "UNITELIB", "MAGASINLIB", "LIBELLEEXACTE", "QTEENTREE", "RESTEASORTIR", "PU", "PUAR", "RESTEAENTRER") AS
SELECT
        abcc.ID,
        abcc.PRODUIT,
        abcc.NUMBL,
        abcc.QUANTITE,
        abcc.IDDETAILSFACTUREFOURNISSEUR,
        abcc.UNITE,
        abcc.IDBC_FILLE,
        abcc.REMARQUE,
        abcc.IDBC,
        abcc.DATY,
        abcc.ETAT,
        abcc.MAGASIN,
        abcc.PRODUITLIB,
        abcc.UNITELIB,
        abcc.MAGASINLIB,
        abcc.LIBELLEEXTACTE AS LIBELLEEXACTE,

        NVL(SUM(mvf.entree),0) AS QTEENTREE,

        NVL(abcc.QUANTITE,0) - NVL(SUM(mvf.entree),0) AS RESTEASORTIR,

        abcc.pu,
        abcc.puar,

        NVL(abcc.QUANTITE,0) - NVL(SUM(mvf.entree),0) AS RESTEAENTRER

    FROM AS_BONDELIVRAISON_LIBCPL abcc
    LEFT JOIN MVTSTOCKLIBVALIDER mv 
        ON mv.idobjet = abcc.numbl 
    LEFT JOIN mvtstockfille mvf 
        ON mv.id = mvf.idmvtstock  AND mvf.idproduit = abcc.produit

    GROUP BY 
        abcc.ID,
        abcc.PRODUIT,
        abcc.NUMBL,
        abcc.QUANTITE,
        abcc.IDDETAILSFACTUREFOURNISSEUR,
        abcc.UNITE,
        abcc.IDBC_FILLE,
        abcc.REMARQUE,
        abcc.IDBC,
        abcc.DATY,
        abcc.ETAT,
        abcc.MAGASIN,
        abcc.PRODUITLIB,
        abcc.UNITELIB,
        abcc.MAGASINLIB,
        abcc.LIBELLEEXTACTE,
        abcc.pu,
        abcc.puar;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RAPPROCHEMENT_BF_LIVREE" ("ID", "PRODUIT", "NUMBL", "QUANTITE", "IDDETAILSFACTUREFOURNISSEUR", "UNITE", "IDBC_FILLE", "REMARQUE", "IDBC", "DATY", "ETAT", "MAGASIN", "PRODUITLIB", "UNITELIB", "MAGASINLIB", "LIBELLEEXACTE", "QTEENTREE", "RESTEASORTIR", "PU", "PUAR", "RESTEAENTRER", "MOTSCLESSS") AS
SELECT 
    SQ.ID,
    SQ.PRODUIT,
    SQ.NUMBL,
    SQ.QUANTITE,
    SQ.IDDETAILSFACTUREFOURNISSEUR,
    SQ.UNITE,
    SQ.IDBC_FILLE,
    SQ.REMARQUE,
    SQ.IDBC,
    SQ.DATY,
    SQ.ETAT,
    SQ.MAGASIN,
    SQ.PRODUITLIB,
    SQ.UNITELIB,
    SQ.MAGASINLIB,
    SQ.LIBELLEEXACTE,
    SQ.QTEENTREE,
    SQ.RESTEASORTIR,
    SQ.PU,
    SQ.PUAR,
    SQ.RESTEAENTRER,

    (
        NVL(TO_CHAR(SQ.ID),'') || ' | ' ||
        NVL(TO_CHAR(SQ.PRODUIT),'') || ' | ' ||
        NVL(TO_CHAR(SQ.NUMBL),'') || ' | ' ||
        NVL(TO_CHAR(SQ.QUANTITE),'') || ' | ' ||
        NVL(TO_CHAR(SQ.IDDETAILSFACTUREFOURNISSEUR),'') || ' | ' ||
        NVL(TO_CHAR(SQ.UNITE),'') || ' | ' ||
        NVL(TO_CHAR(SQ.IDBC_FILLE),'') || ' | ' ||
        NVL(TO_CHAR(SQ.REMARQUE),'') || ' | ' ||
        NVL(TO_CHAR(SQ.IDBC),'') || ' | ' ||
        NVL(TO_CHAR(SQ.DATY,'YYYY-MM-DD HH24:MI:SS'),'') || ' | ' ||
        NVL(TO_CHAR(SQ.ETAT),'') || ' | ' ||
        NVL(TO_CHAR(SQ.MAGASIN),'') || ' | ' ||
        NVL(TO_CHAR(SQ.PRODUITLIB),'') || ' | ' ||
        NVL(TO_CHAR(SQ.UNITELIB),'') || ' | ' ||
        NVL(TO_CHAR(SQ.MAGASINLIB),'') || ' | ' ||
        NVL(TO_CHAR(SQ.LIBELLEEXACTE),'') || ' | ' ||
        NVL(TO_CHAR(SQ.QTEENTREE),'') || ' | ' ||
        NVL(TO_CHAR(SQ.RESTEASORTIR),'') || ' | ' ||
        NVL(TO_CHAR(SQ.PU),'') || ' | ' ||
        NVL(TO_CHAR(SQ.PUAR),'') || ' | ' ||
        NVL(TO_CHAR(SQ.RESTEAENTRER),'')
    ) AS MOTSCLESSS

FROM (
    SELECT
        abcc.ID,
        abcc.PRODUIT,
        abcc.NUMBL,
        abcc.QUANTITE,
        abcc.IDDETAILSFACTUREFOURNISSEUR,
        abcc.UNITE,
        abcc.IDBC_FILLE,
        abcc.REMARQUE,
        abcc.IDBC,
        abcc.DATY,
        abcc.ETAT,
        abcc.MAGASIN,
        abcc.PRODUITLIB,
        abcc.UNITELIB,
        abcc.MAGASINLIB,
        abcc.LIBELLEEXTACTE AS LIBELLEEXACTE,

        NVL(SUM(mvf.entree),0) AS QTEENTREE,

        NVL(abcc.QUANTITE,0) - NVL(SUM(mvf.entree),0) AS RESTEASORTIR,

        abcc.pu,
        abcc.puar,

        NVL(abcc.QUANTITE,0) - NVL(SUM(mvf.entree),0) AS RESTEAENTRER

    FROM AS_BONDELIVRAISON_LIBCPL abcc
    LEFT JOIN MVTSTOCKLIBVALIDER mv 
        ON mv.idobjet = abcc.numbl 
    LEFT JOIN mvtstockfille mvf 
        ON mv.id = mvf.idmvtstock  
       AND mvf.idproduit = abcc.produit

    GROUP BY 
        abcc.ID,
        abcc.PRODUIT,
        abcc.NUMBL,
        abcc.QUANTITE,
        abcc.IDDETAILSFACTUREFOURNISSEUR,
        abcc.UNITE,
        abcc.IDBC_FILLE,
        abcc.REMARQUE,
        abcc.IDBC,
        abcc.DATY,
        abcc.ETAT,
        abcc.MAGASIN,
        abcc.PRODUITLIB,
        abcc.UNITELIB,
        abcc.MAGASINLIB,
        abcc.LIBELLEEXTACTE,
        abcc.pu,
        abcc.puar
) SQ

WHERE SQ.RESTEAENTRER > 0;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RAPPROCHEMENT_COMPLET" ("IDMERE", "CATEGORIEINGREDIENT", "IDCATEGORIEINGREDIENT", "MONTANTSORTIE", "MONTTH", "ECART") AS
SELECT
    st.idmere,
    st.CATEGORIEINGREDIENT AS categorieIngredient,
    st.idcategorieingredient,
    CAST(SUM(montantsortie) AS NUMBER(30,2)) AS montantSortie,
    CAST(SUM(montth) AS NUMBER(30,2)) AS montth,
    CAST(SUM(montth)-SUM(montantsortie) AS NUMBER(30,2)) AS ecart
FROM stockEtDepenseOfFabTheCat st
GROUP BY st.idmere, st.CATEGORIEINGREDIENT, st.idcategorieingredient

UNION ALL

SELECT
    hs.idMere,
    'Charge personnelle' as CATEGORIE,
    hs.CATEGORIE as idCategorieIngredient,
    hs.montantPersonnel AS montantSortie,
    0 AS montth,
    -hs.montantPersonnel AS ecart
FROM HS_PAR_OF hs;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RAPPROCHEMENT_COMPLETFAB" ("IDOBJET", "CATEGORIEINGREDIENT", "IDCATEGORIEINGREDIENT", "MONTANTSORTIE", "MONTTH", "ECART") AS
select st.IDOBJET ,st.CATEGORIEINGREDIENT,st.idcategorieingredient,cast(sum(montantsortie) as number(30,2)) as montantSortie,cast(sum(montth) as number(30,2)) as montth, cast(sum(montth)-sum(montantsortie) as number(30,2)) as ecart
from stockEtDepenseFabTheCat st
group by st.idobjet,st.CATEGORIEINGREDIENT,st.idcategorieingredient

UNION ALL
SELECT
    hs.idMere,
    'Charge personnelle' as CATEGORIE,
    hs.CATEGORIE as idCategorieIngredient,
    hs.montantPersonnel AS montantSortie,
    0 AS montth,
    -hs.montantPersonnel AS ecart
FROM HS_PAR_FAB hs;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RAPPROCHEMENT_COMPLETOFFILLE" ("IDMERE", "CATEGORIEINGREDIENT", "IDCATEGORIEINGREDIENT", "MONTANTSORTIE", "MONTTH", "ECART") AS
select
    st.IDOBJET AS idmere,
    st.CATEGORIEINGREDIENT,
    st.idcategorieingredient,
    cast(sum(montantsortie) as number(30,2)) as montantSortie,
    cast(sum(montth) as number(30,2)) as montth,
    cast(sum(montth)-sum(montantsortie) as number(30,2)) as ecart
from STOCKETDEPENSEOFFILLETHECAT st
group by st.IDOBJET ,st.CATEGORIEINGREDIENT, st.idcategorieingredient

UNION ALL

SELECT
    hs.idMere,
    'Charge personnelle' as CATEGORIE,
    hs.CATEGORIE as idCategorieIngredient,
    hs.montantPersonnel AS montantSortie,
    0 AS montth,
    -hs.montantPersonnel AS ecart
FROM HS_PAR_OFFILLE hs;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RAPPROCHEMENT_FFOURNISSEUR" ("ID", "PRODUIT", "NUMBL", "IDDETAILSFACTUREFOURNISSEUR", "UNITE", "IDBC_FILLE", "REMARQUE", "IDBC", "DATY", "ETAT", "MAGASIN", "PRODUITLIB", "UNITELIB", "MAGASINLIB", "LIBELLEEXACTE", "PU", "PUAR", "QUANTITE", "QTEFACTURER", "RESTEAFACTURER") AS
SELECT
        abcc.ID,
        abcc.PRODUIT,
        abcc.NUMBL,
        abcc.IDDETAILSFACTUREFOURNISSEUR,
        abcc.UNITE,
        abcc.IDBC_FILLE,
        abcc.REMARQUE,
        abcc.IDBC,
        abcc.DATY,
        abcc.ETAT,
        abcc.MAGASIN,
        abcc.PRODUITLIB,
        abcc.UNITELIB,
        abcc.MAGASINLIB,
        abcc.LIBELLEEXTACTE AS LIBELLEEXACTE,
        abcc.pu,
        abcc.puar,
        abcc.QUANTITE,
        NVL(SUM(ffv.qte),0) AS qtefacturer,
        abcc.QUANTITE - NVL(SUM(ffv.qte),0)  as resteAfacturer
    FROM AS_BONDELIVRAISON_LIBCPL abcc
    left join FACTUREFOURNISSEURFILLEValide  ffv on ffv.idfacturefournisseur = abcc.IDFACTUREFOURNISSEUR
    GROUP BY 
        abcc.ID,
        abcc.PRODUIT,
        abcc.NUMBL,
        abcc.QUANTITE,
        abcc.IDDETAILSFACTUREFOURNISSEUR,
        abcc.UNITE,
        abcc.IDBC_FILLE,
        abcc.REMARQUE,
        abcc.IDBC,
        abcc.DATY,
        abcc.ETAT,
        abcc.MAGASIN,
        abcc.PRODUITLIB,
        abcc.UNITELIB,
        abcc.MAGASINLIB,
        abcc.LIBELLEEXTACTE,
        abcc.pu,
        abcc.puar;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RAPPROCHEMENT_FFOURNISSEURGRP" ("NUMBL", "TOTALLIVRER", "TOTALFACTURER") AS
SELECT bc.NUMBL, sum (bc.quantite ) AS totallivrer , sum (bc.qtefacturer ) AS totalFacturer FROM RAPPROCHEMENT_FFOURNISSEUR bc GROUP BY bc.NUMBL;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RECAPITULATIF_ALL_FINAL" ("MOIS", "ANNEE", "SALAIRE", "INDEMNITE", "AVANTAGE_EN_NATURE", "SALAIRE_BRUT", "IRSA", "CNAPS_TRAVAILLEUR", "MONTANT_NET_PAYER", "CNAPS_EMPLOYEUR", "CNAPS_A_PAYER", "TOTAL_FRM", "ID", "MOISLIB") AS
SELECT rs.mois,
       rs.annee,
       rs.salaire,
       rs.indemnite,
       rs.avantage_en_nature,
       rs.salaire_brut,
       rs.irsa,
       rs.cnaps_travailleur,
       CAST(rs.montant_net_payer AS NUMBER(30, 2)) AS MONTANT_NET_PAYER,
       rs.cnaps_employeur,
       rs.cnaps_a_payer,
       frm.total_frm,
       rs.id,
       TO_CHAR(TO_DATE(rs.mois, 'MM'), 'MONTH', 'NLS_DATE_LANGUAGE=FRENCH') AS MOISLIB
FROM recapitulatif_salaire_all rs
         LEFT JOIN frm_mois_annee frm ON rs.mois = frm.mois AND rs.annee = frm.annee;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RECAPITULATIF_SALAIRE_ALL" ("MOIS", "ANNEE", "SALAIRE", "INDEMNITE", "AVANTAGE_EN_NATURE", "SALAIRE_BRUT", "IRSA", "CNAPS_TRAVAILLEUR", "MONTANT_NET_PAYER", "CNAPS_EMPLOYEUR", "CNAPS_A_PAYER", "ID") AS
SELECT recap_sal_all.mois,
       recap_sal_all.annee,
       recap_sal_all.salaire AS salaire,
       recap_sal_all.indemnite AS indemnite,
       recap_sal_all.avantage_en_nature AS avantage_en_nature,
       recap_sal_all.salaire_brut AS salaire_brut,
       recap_sal_all.irsa AS irsa,
       recap_sal_all.cnaps_travailleur AS cnaps_travailleur,
       CAST(recap_sal_all.montant_net_payer AS NUMBER(30, 2)) AS montant_net_payer,
       recap_sal_all.cnaps_employeur AS cnaps_employeur,
       recap_sal_all.cnaps_a_payer AS cnaps_a_payer,
       recap_sal_all.id
FROM recap_sal_all;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RECAP_SAL_ALL" ("MOIS", "ANNEE", "SALAIRE", "INDEMNITE", "AVANTAGE_EN_NATURE", "SALAIRE_BRUT", "IRSA", "CNAPS_TRAVAILLEUR", "MONTANT_NET_PAYER", "CNAPS_EMPLOYEUR", "CNAPS_A_PAYER", "ID") AS
SELECT
    pe.mois,
    pe.annee,

    ROUND(SUM(CASE
                  WHEN pe.idelementpaie = 'PR000041' THEN NVL(pe.gain, 0)
                  ELSE 0
        END), 2) AS salaire,

    ROUND(SUM(CASE
                  WHEN pe.idelementpaie IN ('PR000021', 'PR000061', 'PR000081', 'PR000001') THEN NVL(pe.gain, 0)
                  ELSE 0
        END), 2) AS indemnite,

    ROUND(SUM(CASE
                  WHEN pe.idelementpaie = 'PR000201' THEN NVL(pe.gain, 0)
                  ELSE 0
        END), 2) AS avantage_en_nature,

    ROUND(SUM(CASE
                  WHEN pe.idelementpaie = 'PRUNI' THEN NVL(pegi.imposable, 0)
                  ELSE 0
        END), 2) AS salaire_brut,

    ROUND(SUM(CASE
                  WHEN pe.idelementpaie = 'PR000141' THEN NVL(pe.retenue, 0)
                  ELSE 0
        END), 2) AS irsa,

    ROUND(SUM(CASE
                  WHEN pe.idelementpaie = 'PR000101' THEN NVL(pe.retenue, 0)
                  ELSE 0
        END), 2) AS cnaps_travailleur,

    CAST(ROUND(SUM(CASE
                       WHEN pe.idelementpaie = 'PR000210A' THEN NVL(pe.gain, 0)
                       ELSE 0
        END), 2) AS NUMBER(30, 2))  AS montant_net_payer,

    ROUND(SUM(CASE
                  WHEN pe.idelementpaie = 'PR000101' THEN NVL(pe.retenue, 0)
                  ELSE 0
        END) * 13, 2) AS cnaps_employeur,

    ROUND(SUM(CASE
                  WHEN pe.idelementpaie = 'PR000101' THEN NVL(pe.retenue, 0)
                  ELSE 0
        END) * 14, 2) AS cnaps_a_payer,
    pe.idedition AS id

FROM paie_edition pe
         LEFT JOIN paie_edition_gain_imp pegi
                   ON pe.idpersonnel = pegi.idpersonnel
                       AND pe.mois = pegi.mois
                       AND pe.annee = pegi.annee
                       AND pe.idelementpaie IN (
                                                'PR000041', 'PR000021', 'PR000061', 'PR000081', 'PR000001',
                                                'PR000201', 'PRUNI', 'PR000141', 'PR000101', 'PR000210A'
                           )
GROUP BY pe.annee, pe.mois, pe.IDEDITION;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RECEPTIONOACDETAIL_LIB" ("ID", "IDMERE", "IDLOT", "IDBATIMENT", "IDPARQUET", "IDQUALITETRIAGEOEUF", "QTERECUS", "IDLOTLIB", "IDBATIMENTLIB", "IDPARQUETLIB", "IDQUALITETRIAGEOEUFLIB") AS
SELECT d."ID",
       d."IDMERE",
       d."IDLOT",
       d."IDBATIMENT",
       d."IDPARQUET",
       d."IDQUALITETRIAGEOEUF",
       d."QTERECUS",
       l."NOMLOT"       AS "IDLOTLIB",
       b."NOMBATIMENT"  AS "IDBATIMENTLIB",
       p."VAL"          AS "IDPARQUETLIB",
       qt."VAL"         AS "IDQUALITETRIAGEOEUFLIB"
FROM "RECEPTIONOACDETAIL" d
         LEFT JOIN "LOT" l ON l."ID" = d."IDLOT"
         LEFT JOIN "BATIMENT" b ON b."ID" = d."IDBATIMENT"
         LEFT JOIN "PARQUET" p ON p."ID" = d."IDPARQUET"
         LEFT JOIN "QUALITETRIAGEOEUF" qt ON qt."ID" = d."IDQUALITETRIAGEOEUF";

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RECEPTIONOAC_LIB" ("ID", "DATERECEPTION", "DATEPONTE", "DATECOLLECTE", "IDNUMEROCOLLECTE", "HEUREDEPARTFERME", "HEUREARRIVEECOUVOIR", "IDRESPONSABLE", "IDCHAMBREFROIDE", "IDCHAUFFEUR", "IDVEHICULE", "TEMPERATUREMINVEHICULE", "TEMPERATUREMAXVEHICULE", "IDPROVENANCE", "ETAT", "IDNUMEROCOLLECTELIB", "IDRESPONSABLELIB", "IDCHAMBREFROIDELIB", "IDCHAUFFEURLIB", "IDVEHICULELIB", "ETATLIB") AS
SELECT r."ID",
       r."DATERECEPTION",
       r."DATEPONTE",
       r."DATECOLLECTE",
       r."IDNUMEROCOLLECTE",
       r."HEUREDEPARTFERME",
       r."HEUREARRIVEECOUVOIR",
       r."IDRESPONSABLE",
       r."IDCHAMBREFROIDE",
       r."IDCHAUFFEUR",
       r."IDVEHICULE",
       r."TEMPERATUREMINVEHICULE",
       r."TEMPERATUREMAXVEHICULE",
       r."IDPROVENANCE",
       r."ETAT",
       nc."VAL"                          AS "IDNUMEROCOLLECTELIB",
       resp."NOM" || ' ' || resp."PRENOM" AS "IDRESPONSABLELIB",
       cf."VAL"                          AS "IDCHAMBREFROIDELIB",
       chf."NOM" || ' ' || chf."PRENOM"  AS "IDCHAUFFEURLIB",
       v."VAL"                           AS "IDVEHICULELIB",
       CASE r."ETAT"
            WHEN 1  THEN 'CREE'
            WHEN 11 THEN 'VALIDE'
            WHEN 0  THEN 'ANULLE'
       END                                AS "ETATLIB"
FROM "RECEPTIONOAC" r
         LEFT JOIN "NUMEROCOLLECTE" nc ON nc."ID" = r."IDNUMEROCOLLECTE"
         LEFT JOIN "LOG_PERSONNEL" resp ON resp."ID" = r."IDRESPONSABLE"
         LEFT JOIN "MAGASIN2" cf ON cf."ID" = r."IDCHAMBREFROIDE"
         LEFT JOIN "LOG_PERSONNEL" chf ON chf."ID" = r."IDCHAUFFEUR"
         LEFT JOIN "VEHICULE" v ON v."ID" = r."IDVEHICULE" WHERE r.IDPROVENANCE IS NULL;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RECEPTIONPOUSSINAEDETAIL_LIB" ("ID", "IDMERE", "IDQUALITEPOUSSIN", "IDSEXE", "QTE", "IDQUALITEPOUSSINLIB", "IDSEXELIB", "IDLOT") AS
SELECT
    rd."ID",rd."IDMERE",rd."IDQUALITEPOUSSIN",rd."IDSEXE",rd."QTE",
    qp.val AS idQualitePoussinLib,
    s.val  AS idSexeLib,
    mere.idlot AS idlot
FROM receptionPoussinAeroportDetail rd
         LEFT JOIN qualitePoussin qp ON rd.idQualitePoussin = qp.id
         LEFT JOIN sexe s ON rd.idSexe = s.id
		LEFT JOIN receptionpoussinaeroport mere ON mere.id=rd.idmere;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RECEPTIONPOUSSINAEROPORT_LIB" ("ID", "IDLOT", "DATY", "QTERECUS", "REMARQUE", "HEUREDEPART", "HEUREARRIVE", "IDLOTLIB", "NBRCARTONMALE", "NBRCARTONFEMELLE", "NBRCARTONTOTAL", "ETAT", "ETATLIB") AS
SELECT
    r.ID,r.IDLOT,r.DATY,r.QTERECUS,r.REMARQUE, r.heureDepart,r.heureArrive,
    l.nomLot AS idLotLib,
    NVL(r.nbrCartonMale, 0) AS nbrcartonmale,
    NVL(r.nbrCartonFemelle, 0) AS nbrcartonfemelle,
    NVL(r.nbrCartonMale, 0) + NVL(r.nbrCartonFemelle, 0) AS nbrCartonTotal,
    r.etat AS etat,
    CASE
        WHEN r.ETAT = 1 THEN 'CR&Eacute;&Eacute;'
        WHEN r.ETAT = 11 THEN 'VALID&Eacute;'
        END
        AS ETATLIB
FROM receptionPoussinAeroport r
         LEFT JOIN lot l ON r.idLot = l.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RECETTEMONTANT" ("ID", "IDPRODUITS", "IDINGREDIENTS", "QUANTITE", "UNITE", "LIBINGREDIENTS", "IDUNITE", "SOURCE", "COMPOSE", "QTEAV", "QTETOTAL", "TYPESTOCK", "REFPOST", "REFQUALIFICATION", "CATEGORIEINGREDIENT", "NIVEAU") AS
select
    rec.ID,rec.IDPRODUITS,rec.IDINGREDIENTS,cast(rec.QUANTITE as number(30,10)) as QUANTITE,rec.UNITE,'-' as libIngredients,'-' as IDUNITE,'' as source,0 as COMPOSE,
    cast(0 as number(30,10)) as qteav,
    cast(0 as number(30,10)) as qtetotal,
    i.TYPESTOCK,
    i.REFPOST,
    i.REFQUALIFICATION,
    i.CATEGORIEINGREDIENT ,
    0 as niveau
from as_recette rec
         left join AS_INGREDIENTS i on rec.IDINGREDIENTS=i.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RECETTE_FILLE_LIB" ("ID", "IDMERE", "IDINGREDIENT", "IDUNITE", "QTE", "IDINGREDIENTLIB", "IDUNITELIB") AS
SELECT
    rf."ID",rf."IDMERE",rf."IDINGREDIENT",rf."IDUNITE",rf."QTE",
    i.LIBELLE AS IDINGREDIENTLIB,
    u.VAL AS IDUNITELIB
FROM RECETTE_FILLE rf
         LEFT JOIN AS_INGREDIENTS i
                   ON rf.IDINGREDIENT = i.ID
         LEFT JOIN AS_UNITE u
                   ON rf.IDUNITE = u.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RECETTE_MERE_LIB" ("ID", "IDPRODUIT", "DATY", "NOMRECETTE", "VERSION", "IDPRODUITLIB") AS
SELECT
    rm."ID",rm."IDPRODUIT",rm."DATY",rm."NOMRECETTE",rm."VERSION",
    i.LIBELLE AS IDPRODUITLIB
FROM RECETTE_MERE rm
         LEFT JOIN AS_INGREDIENTS i
                   ON rm.IDPRODUIT = i.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RECLAMATIONLIB" ("ID", "IDVENTEFILLE", "DATY", "IDTYPE", "ETAT", "ETATLIB", "IDTYPELIB", "IDVENTE", "QTE") AS
SELECT
    r.ID,
    r.idVenteFille,
    r.daty,
    r.idType,
    r.etat,

    CASE r.etat
        WHEN 1  THEN 'Cree'
        WHEN 7 THEN 'Valide'
        WHEN 11 THEN 'Cloture'
        WHEN 0 THEN 'Rejete'
        ELSE 'Autre'
        END AS etatLib,

    tr.VAL AS idTypeLib,
    vd.IDVENTE,
    r.qte
FROM reclamation r
         LEFT JOIN TYPERECLAMATION tr
                   ON tr.ID = r.idType
         LEFT JOIN vente_details vd on vd.id = r.IDVENTEFILLE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RELEVECLIENT" ("ID", "JOURNAL", "REFERENCE", "DATY", "LIBELLE", "LETTRE", "DEBIT", "CREDIT", "IDCLIENT", "CLIENTLIB", "COMPTE", "UPDATED_AT", "SOLDE", "ANNEE", "MOTSCLESSS") AS
SELECT SQ.ID,
       SQ.JOURNAL,
       SQ.REFERENCE,
       SQ.DATY,
       SQ.LIBELLE,
       SQ.LETTRE,
       CAST(SQ.DEBIT AS NUMBER(30, 5))  AS DEBIT,
       CAST(SQ.CREDIT AS NUMBER(30, 5)) AS CREDIT,
       SQ.IDCLIENT,
       SQ.CLIENTLIB,
       SQ.COMPTE,
       SQ.UPDATED_AT,
       CAST(SQ.SOLDE AS NUMBER(30, 5))  AS SOLDE,
       SQ.ANNEE,
       (
           ID || ' | ' || JOURNAL || ' | ' || REFERENCE || ' | ' || CLIENTLIB || ' | ' || LIBELLE || ' | ' || LETTRE
           )                            AS MOTSCLESSS
FROM (SELECT RELEVER.ID,
             RELEVER.JOURNAL,
             RELEVER.REFERENCE,
             RELEVER.DATY,
             RELEVER.LIBELLE,
             RELEVER.LETTRE,
             RELEVER.DEBIT,
             RELEVER.CREDIT,
             RELEVER.IDCLIENT,
             T.NOM                           AS CLIENTLIB,
             NVL(RELEVER.COMPTE, T.COMPTE)   AS COMPTE,
             RELEVER.UPDATED_AT,
             RELEVER.SOLDE,
             EXTRACT(YEAR FROM RELEVER.DATY) AS ANNEE,

             ROW_NUMBER() OVER (
                 PARTITION BY RELEVER.ID, RELEVER.JOURNAL, RELEVER.REFERENCE, RELEVER.DATY
                 ORDER BY
                     CASE
                         WHEN RELEVER.LETTRE IS NOT NULL AND TRIM(RELEVER.LETTRE) IS NOT NULL THEN 0
                         ELSE 1
                         END
                 )                           AS RN

      FROM (

               /* NOTE DE CREDIT / AVOIR CLIENT */
               SELECT AV.ID                        AS ID,
                      NVL(CJ.DESCE, ' ')           AS JOURNAL,
                      AV.ID                        AS REFERENCE,
                      AV.DATY                      AS DATY,
                      'NOTE DE CREDIT : ' || AV.ID AS LIBELLE,
                      NVL(CL.LETTRE, ' ')          AS LETTRE,
                      0                            AS DEBIT,
                      AV.MONTANTTTCAR              AS CREDIT,
                      AV.IDCLIENT                  AS IDCLIENT,
                      SOUS.COMPTE                  AS COMPTE,
                      AV.DATY                      AS UPDATED_AT,
                      AV.MONTANTTTCAR * -1         AS SOLDE
               FROM AVOIRFCLIB_CPL_VISEE AV
                        JOIN COMPTA_ECRITURE ECR ON ECR.IDOBJET = AV.ID
                        JOIN COMPTA_SOUS_ECRITURE SOUS ON SOUS.IDMERE = ECR.ID
                        LEFT JOIN COMPTA_LETTRAGE CL ON CL.ID = SOUS.LETTRAGE
                        LEFT JOIN COMPTA_JOURNAL CJ ON CJ.ID = SOUS.JOURNAL
               WHERE SOUS.COMPTE LIKE '411%'

               UNION ALL

               /* FACTURE / VENTE CLIENT */
               SELECT MCD.ID                            AS ID,
                      NVL(CJ.DESCE, ' ')                AS JOURNAL,
                      MCD.NUMEROFACTURE                 AS REFERENCE,
                      MCD.DATY                          AS DATY,
                      NVL(MCD.REFERENCES_PAIEMENT, ' ') AS LIBELLE,
                      NVL(CL.LETTRE, ' ')               AS LETTRE,
                      MCD.MONTANTTTCAR                  AS DEBIT,
                      0                                 AS CREDIT,
                      MCD.IDCLIENT                      AS IDCLIENT,
                      SOUS.COMPTE                       AS COMPTE,
                      MCD.UPDATED_AT                    AS UPDATED_AT,
                      MCD.MONTANTTTCAR                  AS SOLDE
               FROM MOUVEMENTCAISSE_DETAIL_UNIQUE MCD
                        JOIN COMPTA_ECRITURE ECR ON ECR.IDOBJET = MCD.ID
                        JOIN COMPTA_SOUS_ECRITURE SOUS ON SOUS.IDMERE = ECR.ID
                        LEFT JOIN COMPTA_LETTRAGE CL ON CL.ID = SOUS.LETTRAGE
                        LEFT JOIN COMPTA_JOURNAL CJ ON CJ.ID = SOUS.JOURNAL
               WHERE MCD.ETAT >= 7
                 AND SOUS.COMPTE LIKE '411%'

               UNION ALL

               /* REGLEMENT CLIENT */
               SELECT MC.ID                   AS ID,
                      NVL(CJ.DESCE, ' ')      AS JOURNAL,
                      MC.ID                   AS REFERENCE,
                      MC.DATYCOMPTABILISATION AS DATY,
                      MC.DESIGNATION          AS LIBELLE,
                      NVL(CL.LETTRE, ' ')     AS LETTRE,
                      0                       AS DEBIT,
                      MC.CREDIT               AS CREDIT,
                      MC.IDTIERS              AS IDCLIENT,
                      SOUS.COMPTE             AS COMPTE,
                      MC.UPDATED_AT           AS UPDATED_AT,
                      MC.CREDIT * -1          AS SOLDE
               FROM MOUVEMENTCAISSECPL MC
                        JOIN COMPTA_ECRITURE ECR ON ECR.IDOBJET = MC.ID
                        JOIN COMPTA_SOUS_ECRITURE SOUS ON SOUS.IDMERE = ECR.ID
                        LEFT JOIN COMPTA_LETTRAGE CL ON CL.ID = SOUS.LETTRAGE
                        LEFT JOIN COMPTA_JOURNAL CJ ON CJ.ID = SOUS.JOURNAL
               WHERE MC.ETAT > 8
                 AND SOUS.COMPTE LIKE '411%') RELEVER
               LEFT JOIN TIERS T ON T.ID = RELEVER.IDCLIENT) SQ
WHERE SQ.RN = 1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RELEVERDETAILCPL" ("ID", "IDMERE", "DATY", "DATYVALEUR", "DESIGNATION", "DEBIT", "CREDIT", "IDCAISSE", "COMPTE") AS
select rd."ID",rd."IDMERE",rd."DATY",rd."DATYVALEUR",rd."DESIGNATION",rd."DEBIT",rd."CREDIT" , r.IDCAISSE, cai.COMPTE from ReleverDetail rd join RELEVER r on rd.IDMERE = r.id left join CAISSE cai on cai.id=r.IDCAISSE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RELEVERDETAILNR" ("ID", "DESIGNATION", "DEBIT", "CREDIT", "DATYVALEUR", "IDCAISSE", "COMPTE") AS
SELECT
    rd.ID,
    rd.DESIGNATION,
    rd.DEBIT,
    rd.CREDIT,
    rd.DATYVALEUR,
    r.IDCAISSE, cai.COMPTE
FROM RELEVERDETAIL rd
         JOIN RELEVER r ON r.ID = rd.IDMERE
         left join CAISSE cai on cai.id=r.IDCAISSE
WHERE
    r.ETAT >= 11
  AND rd.ID NOT IN (
    SELECT rpf.IDRELEVERDETAIL
    FROM RAPPROCHEMENTBC rpf join RAPPROCHEMENTBCMERE rp on rpf.idmere=rp.id
    WHERE rpf.IDRELEVERDETAIL IS NOT NULL AND rp.ETAT>=11
);

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RELEVERDETAILNRMVT" ("ID", "DESIGNATION", "DEBIT", "CREDIT", "DATYVALEUR", "IDCAISSE", "COMPTE", "MOUVEMENT") AS
SELECT
    ID,
    DESIGNATION,
    CAST(DEBIT AS NUMBER(32,2)) AS DEBIT,
    CAST(CREDIT AS NUMBER(32,2)) AS CREDIT,
    DATYVALEUR,
    IDCAISSE,
    COMPTE,
    CASE
        WHEN DEBIT > 0 THEN 1
        WHEN CREDIT > 0 THEN 2
        ELSE 0
        END AS MOUVEMENT
FROM RELEVERDETAILNR;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RELEVERDETAILORDER" ("ID", "IDMERE", "DATY", "DATYVALEUR", "DESIGNATION", "DEBIT", "CREDIT", "SOLDE") AS
select "ID","IDMERE","DATY","DATYVALEUR","DESIGNATION","DEBIT","CREDIT","SOLDE" from ReleverDetail ORDER BY TO_NUMBER(REGEXP_REPLACE(id, '[^0-9]', '')) ASC;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RELEVERDETAILR" ("ID", "DESIGNATION", "DEBIT", "CREDIT", "DATYVALEUR", "IDCAISSE", "COMPTE") AS
SELECT
    rd.ID,
    rd.DESIGNATION,
    rd.DEBIT,
    rd.CREDIT,
    rd.DATYVALEUR,
    r.IDCAISSE, cai.COMPTE
FROM RELEVERDETAIL rd
         JOIN RELEVER r ON r.ID = rd.IDMERE
         left join CAISSE cai on cai.id=r.IDCAISSE
WHERE
    r.ETAT >= 11
  AND rd.ID IN (
    SELECT rpf.IDRELEVERDETAIL
    FROM RAPPROCHEMENTBC rpf join RAPPROCHEMENTBCMERE rp on rpf.idmere=rp.id
    WHERE rpf.IDRELEVERDETAIL IS NOT NULL AND rp.ETAT>=11
);

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RELEVERDETAILRMVT" ("ID", "DESIGNATION", "DEBIT", "CREDIT", "DATYVALEUR", "IDCAISSE", "COMPTE", "MOUVEMENT") AS
SELECT
    ID,
    DESIGNATION,
    CAST(DEBIT AS NUMBER(32,2)) AS DEBIT,
    CAST(CREDIT AS NUMBER(32,2)) AS CREDIT,
    DATYVALEUR,
    IDCAISSE,
    COMPTE,
    CASE
        WHEN DEBIT > 0 THEN 1
        WHEN CREDIT > 0 THEN 2
        ELSE 0
        END AS MOUVEMENT
FROM RELEVERDETAILR;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RELEVERFABCPL" ("ID", "DATY", "IDFAB", "IDRELEVE", "ETAT", "IDCATEGORIE") AS
SELECT
    R."ID",R."DATY",R."IDFAB",R."IDRELEVE",R."ETAT",
    C.IDCATEGORIE
FROM RELEVEFAB R
    LEFT JOIN COMPTEURMAINTENANCE C ON C.ID = R.IDRELEVE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RELEVERLIB" ("ID", "DATY", "IDCAISSE", "ETAT", "IDCAISSELIB", "DATYDEBUT", "DATYFIN", "ETATLIB") AS
select
    r."ID",r."DATY",r."IDCAISSE",r."ETAT" ,
    c.val as idcaisselib,
    r.DATYDEBUT,
    r.DATYFIN,
    CASE
        WHEN r.ETAT = 1 THEN 'CREEE'
        WHEN r.ETAT = 11 THEN 'VISEE'
        WHEN r.ETAT = 0 THEN 'ANNULEE'
        END
          AS ETATLIB
from Relever r
         join caisse c on c.id = r.idcaisse;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RELEVER_CLIENT_OPT" ("DATY", "COMPTE_AUX", "LIBELLE", "SOLDE_INITIAL", "DEBIT", "CREDIT", "SOLDE_FINAL") AS
SELECT
    e.DATY                  AS daty,
    se.COMPTE_AUX            AS compte_aux,
    se.LIBELLEPIECE          AS libelle,
    0                        AS solde_initial,
    se.DEBIT                 AS debit,
    se.CREDIT                AS credit,
    0                        AS solde_final
FROM COMPTA_SOUS_ECRITURE se
         JOIN COMPTA_ECRITURE e ON e.ID = se.IDMERE
WHERE se.COMPTE_AUX IS NOT NULL;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."REMBOURSEMENTLIB" ("ID", "IDAVANCE", "MOIS", "ANNEE", "MONTANT", "REMARQUE", "DATY", "ETAT", "PERSONNEL", "TYPEAVANCELIB", "ETATLIB", "MATRICULE", "MOISLIB", "MOTSCLESSS") AS
SELECT SQ.ID,SQ.IDAVANCE,SQ.MOIS,SQ.ANNEE,SQ.MONTANT,SQ.REMARQUE,SQ.DATY,SQ.ETAT,SQ.PERSONNEL,SQ.TYPEAVANCELIB,SQ.ETATLIB,SQ.MATRICULE,SQ.MOISLIB,
	  (NVL(TO_CHAR(ID),'') || ' | ' || NVL(TO_CHAR(IDAVANCE),'') || ' | ' || NVL(TO_CHAR(MOIS),'') || ' | ' || NVL(TO_CHAR(ANNEE),'') || ' | ' || NVL(TO_CHAR(MONTANT),'') || ' | ' || NVL(TO_CHAR(REMARQUE),'') || ' | ' || NVL(TO_CHAR(DATY,'YYYY-MM-DD HH24:MI:SS'),'') || ' | ' || NVL(TO_CHAR(ETAT),'') || ' | ' || NVL(TO_CHAR(PERSONNEL),'') || ' | ' || NVL(TO_CHAR(TYPEAVANCELIB),'') || ' | ' || NVL(TO_CHAR(ETATLIB),'') || ' | ' || NVL(TO_CHAR(MATRICULE),'') || ' | ' || NVL(TO_CHAR(MOISLIB),'')) AS MOTSCLESSS
	FROM (
	  SELECT pr.id,
	       pr.idavance,
	       pr.mois,
	       pr.annee,
	       pr.montant,
	       pr.remarque,
	       pr.daty,
	       pr.etat,
	       lp.nom || ' ' || lp.prenom  AS personnel,
	       t.val AS typeavancelib,
	       CASE
	           WHEN pr.etat = 1 THEN 'CREE'
	           WHEN pr.etat = 11 THEN 'VALIDE'
	           ELSE NULL
	           END AS etatlib,
	       pip.matricule,
	       TO_CHAR(
	               TO_DATE(TO_CHAR(pr.mois, 'FM00'), 'MM'),
	               'FMMonth',
	               'NLS_DATE_LANGUAGE=FRENCH'
	       ) AS moisLib
	FROM remboursement pr
	         LEFT JOIN avance a ON a.id = pr.idavance
	         LEFT JOIN typeavance t ON t.id = a.idtypeavance
	         LEFT JOIN paie_info_personnel pip ON pip.id = a.idpersonnel
	         LEFT JOIN log_personnel lp ON lp.id=a.idpersonnel
	 
	) SQ;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."REMISEFILLELIB" ("ID", "REMISE", "IDCATEGORIECLIENT", "IDCATEGORIECLIENTLIB", "IDPRODUIT", "IDPRODUITLIB", "CATEGORIEPRODUIT", "CATEGORIEPRODUITLIB", "IDPOINT", "IDPOINTLIB", "IDREMISE") AS
SELECT 
	rf.id,
	rf.remise,
	rf.idCategorieClient,
	tp.val AS idCategorieClientlib,
	rf.idProduit,
	ai.libelle,
	rf.cateGorieProduit,
	cti.val AS CATEGORIEPRODUITLIB,
	rf.idPoint,
	p.val AS idPointLib,
	rf.idRemise
FROM RemiseFille rf
LEFT JOIN typeclient tp ON tp.id = rf.idCategorieClient
LEFT JOIN as_ingredients ai ON ai.id = rf.idProduit
LEFT JOIN point p ON p.id = rf.idPoint
LEFT JOIN categorieingredient cti ON cti.id = rf.CATEGORIEPRODUIT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."REMISEFILLEMERE" ("ID", "REMISE", "IDCATEGORIECLIENT", "IDPRODUIT", "CATEGORIEPRODUIT", "IDPOINT", "IDREMISE", "NOM", "DATY", "DATEDEBUT", "DATEFIN", "ETAT") AS
select rf."ID",rf."REMISE",rf."IDCATEGORIECLIENT",rf."IDPRODUIT",rf."CATEGORIEPRODUIT",rf."IDPOINT",rf."IDREMISE",r.nom,r.daty,r.dateDebut,r.dateFin,r.etat from remiseFille rf left join remise r on r.id=rf.idremise;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."REMISEFILLEMERELIB" ("IDMERE", "IDFILLE", "DATY", "NOM", "DATEDEBUT", "DATEFIN", "ETAT", "REMISE", "IDCATEGORIECLIENT", "IDCATEGORIECLIENTLIB", "IDPRODUIT", "IDPRODUITLIB", "CATEGORIEPRODUIT", "CATEGORIEPRODUITLIB", "IDPOINT", "IDPOINTLIB") AS
SELECT 
r.id AS idmere,
rf.id AS idfille,
r.daty,
r.nom,
r.datedebut,
r.datefin,
r.etat,
rf.remise,
rf.idCategorieClient,
tp.val AS idCategorieClientLib,
rf.idProduit,
ai.libelle AS idProduitLib,
rf.cateGorieProduit,
cti.val AS cateGorieProduitLib,
rf.idPoint,
p.val AS idPointLib
FROM Remise r 
LEFT JOIN RemiseFille rf ON r.id = rf.idRemise
LEFT JOIN typeclient tp ON tp.id = rf.idCategorieClient
LEFT JOIN as_ingredients ai ON ai.id = rf.idProduit
LEFT JOIN point p ON p.id = rf.idPoint
LEFT JOIN categorieingredient cti ON cti.id = rf.CATEGORIEPRODUIT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."REMISEFILLEMEREVISE" ("ID", "REMISE", "IDCATEGORIECLIENT", "IDPRODUIT", "CATEGORIEPRODUIT", "IDPOINT", "IDREMISE", "NOM", "DATY", "DATEDEBUT", "DATEFIN", "ETAT") AS
select rf."ID",rf."REMISE",rf."IDCATEGORIECLIENT",rf."IDPRODUIT",rf."CATEGORIEPRODUIT",rf."IDPOINT",rf."IDREMISE",r.nom,r.daty,r.dateDebut,r.dateFin,r.etat from remiseFille rf left join remise r on r.id=rf.idremise where r.etat>=11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."REMISELIB" ("ID", "DATY", "NOM", "DATEDEBUT", "DATEFIN", "ETAT", "ETATLIB") AS
SELECT
	rem.ID , 
	rem.DATY , 
	rem.NOM, 
	rem.DATEDEBUT , 
	rem.DATEFIN , 
	rem.ETAT,
	CASE
		WHEN rem.ETAT = 1
            THEN 'CR&Eacute;&Eacute;E'
		WHEN rem.ETAT = 0
            THEN 'ANNUL&Eacute;E'
		WHEN rem.ETAT = 11
            THEN 'VIS&Eacute;E'
	END AS ETATLIB
FROM
	REMISE rem;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."REMISELIB_A" ("ID", "DATY", "NOM", "DATEDEBUT", "DATEFIN", "ETAT", "ETATLIB") AS
SELECT
	rem.ID , 
	rem.DATY , 
	rem.NOM, 
	rem.DATEDEBUT , 
	rem.DATEFIN , 
	rem.ETAT,
	CASE
		WHEN rem.ETAT = 1
            THEN 'CR&Eacute;&Eacute;E'
		WHEN rem.ETAT = 0
            THEN 'ANNUL&Eacute;E'
		WHEN rem.ETAT = 11
            THEN 'VIS&Eacute;E'
	END AS ETATLIB
FROM
	REMISE rem
	WHERE rem.ETAT = 0;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."REMISELIB_C" ("ID", "DATY", "NOM", "DATEDEBUT", "DATEFIN", "ETAT", "ETATLIB") AS
SELECT
	rem.ID , 
	rem.DATY , 
	rem.NOM, 
	rem.DATEDEBUT , 
	rem.DATEFIN , 
	rem.ETAT,
	CASE
		WHEN rem.ETAT = 1
            THEN 'CR&Eacute;&Eacute;E'
		WHEN rem.ETAT = 0
            THEN 'ANNUL&Eacute;E'
		WHEN rem.ETAT = 11
            THEN 'VIS&Eacute;E'
	END AS ETATLIB
FROM
	REMISE rem
	WHERE rem.ETAT = 1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."REMISELIB_V" ("ID", "DATY", "NOM", "DATEDEBUT", "DATEFIN", "ETAT", "ETATLIB") AS
SELECT
	rem.ID , 
	rem.DATY , 
	rem.NOM, 
	rem.DATEDEBUT , 
	rem.DATEFIN , 
	rem.ETAT,
	CASE
		WHEN rem.ETAT = 1
            THEN 'CR&Eacute;&Eacute;E'
		WHEN rem.ETAT = 0
            THEN 'ANNUL&Eacute;E'
		WHEN rem.ETAT = 11
            THEN 'VIS&Eacute;E'
	END AS ETATLIB
FROM
	REMISE rem
	WHERE rem.ETAT = 11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."REPARTIRIONPGGROUPEE" ("IDFACTUREFILLE", "MONTANT") AS
SELECT
    r.IDFACTUREFILLE ,
    NVL(SUM(r.montant), 0) AS montant
FROM REPARTIRIONPG r
GROUP BY r.IDFACTUREFILLE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."REPORTCAISSEAVECHEURE" ("ID", "IDCAISSE", "MONTANT", "MONTANTTHEORIQUE", "DATY", "ETAT", "REMARQUE", "HEURE") AS
select r.ID,
       IDCAISSE,
       MONTANT,
       MONTANTTHEORIQUE,
       TO_DATE(TO_CHAR(DATY, 'YYYY-MM-DD') || ' ' || NVL(HEURE, '00:00:00'), 'YYYY-MM-DD HH24:MI:SS') as DATY,
       ETAT,
       REMARQUE,
       HEURE
from REPORTCAISSE r;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."REPORTCAISSELIB" ("ID", "IDCAISSE", "IDCAISSELIB", "MONTANT", "MONTANTTHEORIQUE", "DATY", "ETAT", "HEURE", "ETATLIB") AS
SELECT
r.ID ,
r.IDCAISSE ,
c.VAL AS IDCAISSELIB,
CAST(r.MONTANT AS NUMBER(30,5)) AS MONTANT ,
CAST(r.MONTANTTHEORIQUE AS NUMBER(30,5)) AS MONTANTTHEORIQUE ,
r.DATY ,
r.ETAT ,r.heure,
CASE
	WHEN r.ETAT = 0
	THEN 'ANNULEE'
	WHEN r.ETAT = 1
	THEN 'CREE'
	WHEN r.ETAT = 11
	THEN 'VALIDEE'
END AS ETATLIB
FROM REPORTCAISSE r
LEFT JOIN CAISSE c ON c.ID  = r.IDCAISSE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."REPORTCAISSELIB_ANNULE" ("ID", "IDCAISSE", "IDCAISSELIB", "MONTANT", "MONTANTTHEORIQUE", "DATY", "ETAT", "ETATLIB") AS
SELECT
		ID,IDCAISSE,IDCAISSELIB,MONTANT,MONTANTTHEORIQUE,DATY,ETAT,ETATLIB
	FROM 
		reportcaisselib v 
	WHERE 
		v.etat = 0;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."REPORTCAISSELIB_CREE" ("ID", "IDCAISSE", "IDCAISSELIB", "MONTANT", "MONTANTTHEORIQUE", "DATY", "ETAT", "ETATLIB") AS
SELECT
		ID,IDCAISSE,IDCAISSELIB,MONTANT,MONTANTTHEORIQUE,DATY,ETAT,ETATLIB
	FROM 
		reportcaisselib v 
	WHERE 
		v.etat = 1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."REPORTCAISSELIB_VALIDER" ("ID", "IDCAISSE", "IDCAISSELIB", "MONTANT", "MONTANTTHEORIQUE", "DATY", "ETAT", "ETATLIB") AS
SELECT
		ID,IDCAISSE,IDCAISSELIB,MONTANT,MONTANTTHEORIQUE,DATY,ETAT,ETATLIB
	FROM 
		reportcaisselib v 
	WHERE 
		v.etat = 11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."REPORTCAISSE_DEVISE" ("ID", "IDCAISSE", "IDCAISSELIB", "MONTANT", "MONTANTTHEORIQUE", "DATY", "ETAT", "IDDEVISE", "ETATLIB") AS
SELECT
r.ID ,
r.IDCAISSE ,
c.VAL AS IDCAISSELIB,
r.MONTANT ,
r.MONTANTTHEORIQUE ,
r.DATY ,
r.ETAT ,
c.iddevise,
CASE
	WHEN r.ETAT = 0
	THEN 'ANNULEE'
	WHEN r.ETAT = 1
	THEN 'CREE'
	WHEN r.ETAT = 11
	THEN 'VALIDEE'
END AS ETATLIB
FROM REPORTCAISSE r
LEFT JOIN (select * from CAISSE where id not in ('CAIS001')) c ON c.ID  = r.IDCAISSE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."REPORTSOLDE" ("ID", "COMPTE", "LIBELLE_COMPTE", "DEBIT", "CREDIT", "DATY", "TYPECOMPTE", "MOIS", "ANNEE") AS
SELECT ce.id, cse.COMPTE, cc.libelle, cse.debit, cse.credit, ce.daty, cc.typecompte,
       EXTRACT(MONTH from ce.daty), EXTRACT(YEAR from ce.daty)
from
    compta_sous_ecriture cse, compta_ecriture ce, compta_compte cc, compta_journal jrn
where
    cse.idmere = ce.id and cc.COMPTE = cse.compte and ce.journal = 'COMP000015'
  and ce.etat = 11 and jrn.id = cse.journal
UNION
SELECT ce.id, cse.ANALYTIQUE, cc.libelle, cse.debit, cse.credit, ce.daty, cc.typecompte,
       EXTRACT(MONTH from ce.daty), EXTRACT(YEAR from ce.daty)
from
    compta_sous_ecriture cse, compta_ecriture ce, compta_compte cc, compta_journal jrn
where
    cse.idmere = ce.id and cc.COMPTE = cse.analytique and ce.journal = 'COMP000015'
  and ce.etat = 11 and jrn.id = cse.journal;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."REPORTSOLDE_ANALYTIQUE" ("COMPTE", "LIBELLE", "DEBIT", "CREDIT", "TYPECOMPTE", "DATY", "CHIFFRE3", "CHIFFRE2") AS
SELECT
    COMPTE,
    LIBELLE,
    CAST(DEBIT AS NUMBER(30,
                         2)),
    CAST(CREDIT AS NUMBER(30,
                          2)),
    TYPECOMPTE,
    daty,
    CHIFFRE3,
    CHIFFRE2
FROM
    (
        SELECT
            cse.ANALYTIQUE AS COMPTE,
            cc.libelle,
            sum(cse.debit) AS DEBIT,
            sum(cse.credit) AS CREDIT,
            cc.typecompte,
            cse.daty,
            substr(analytique, 1, 3)|| substr(analytique, 5, 1) AS chiffre3,
            substr(cse.ANALYTIQUE, 1, 2) AS chiffre2
        FROM
            compta_sous_ecriture cse,
            compta_compte cc,
            compta_journal jrn
        WHERE
            cc.COMPTE = cse.ANALYTIQUE
          AND cse.etat = 11
          AND cse.JOURNAL = jrn.id
        GROUP BY
            cse.ANALYTIQUE,
            cc.libelle,
            cc.typecompte,
            cse.daty

    );

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."REPORTSOLDE_AUX_V1" ("COMPTE", "LIBELLE", "DEBIT", "CREDIT", "TYPECOMPTE", "DATY", "CHIFFRE3", "CHIFFRE2") AS
SELECT
	COMPTE,
	LIBELLE,
	CAST(DEBIT AS NUMBER(30, 2)) AS debit,
	CAST(CREDIT AS NUMBER(30, 2)) AS credit,
	TYPECOMPTE,
	daty,
	CHIFFRE3,
	CHIFFRE2
FROM
	(
	SELECT
		t.COMPTEAUXILIAIRE AS COMPTE,
		t.NOM AS LIBELLE,
		SUM(cse.debit) AS debit,
		SUM(cse.credit) AS credit,
		cc.typecompte,
		cse.daty,
		CASE
			WHEN SUBSTR(t.COMPTEAUXILIAIRE, 1, 4) = '4007' THEN '407'
			ELSE SUBSTR(t.COMPTEAUXILIAIRE, 1, 2) || SUBSTR(t.COMPTEAUXILIAIRE, 5, 1)
		END AS CHIFFRE3,
		SUBSTR(t.COMPTEAUXILIAIRE, 1, 2) AS CHIFFRE2
	FROM
		compta_sous_ecriture cse
	JOIN compta_compte cc ON
		cc.COMPTE = cse.compte
	JOIN compta_journal jrn ON
		cse.JOURNAL = jrn.id
	JOIN TIERS t ON
		t.id = cse.COMPTE_AUX
	WHERE
		cse.etat = 11
	GROUP BY
		t.COMPTEAUXILIAIRE,
		t.NOM,
		cc.typecompte,
		cse.daty

    );

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."REPORTSOLDE_GENERAL" ("COMPTE", "LIBELLE_COMPTE", "DEBIT", "CREDIT", "TYPECOMPTE", "MOIS", "ANNEE", "CHIFFRE3", "CHIFFRE2") AS
SELECT
    COMPTE,
    LIBELLE,
    CAST(DEBIT AS NUMBER(30,
        2)),
    CAST(CREDIT AS NUMBER(30,
        2)),
    TYPECOMPTE,
    MOIS,
    ANNEE,
    CHIFFRE3,
    CHIFFRE2
FROM
    (
        SELECT
            cse.COMPTE,
            cc.libelle,
            sum(cse.debit) AS debit,
            sum(cse.credit) AS credit,
            cc.typecompte,
            EXTRACT(MONTH FROM cse.daty) AS mois,
            EXTRACT(YEAR FROM cse.daty) AS annee,
            CASE
                WHEN substr(cse.compte, 1, 4) = '4007' THEN '407'
                ELSE substr(cse.compte, 1, 2)|| substr(cse.compte, 5, 1)
                END AS CHIFFRE3,
            substr(cse.compte, 1, 2) AS CHIFFRE2
        FROM
            compta_sous_ecriture cse,
            compta_compte cc,
            compta_journal jrn
        WHERE
            cc.COMPTE = cse.compte
          AND cse.etat = 11
          AND cse.JOURNAL = jrn.id
        GROUP BY
            cse.COMPTE,
            cc.libelle,
            cc.typecompte,
            EXTRACT(MONTH FROM cse.daty),
            EXTRACT(YEAR FROM cse.daty)
    );

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."REPORTSOLDE_GENERAL_V1" ("COMPTE", "LIBELLE", "DEBIT", "CREDIT", "TYPECOMPTE", "DATY", "CHIFFRE3", "CHIFFRE2") AS
SELECT
	COMPTE,
	LIBELLE,
	CAST(DEBIT AS NUMBER(30, 2)) AS debit,
	CAST(CREDIT AS NUMBER(30, 2)) AS credit,
	TYPECOMPTE,
	daty,
	CHIFFRE3,
	CHIFFRE2
FROM
	(
	SELECT
		cse.COMPTE,
		cc.libelle,
		sum(cse.debit) AS debit,
		sum(cse.credit) AS credit,
		cc.typecompte,
		cse.daty,
		CASE
			WHEN substr(cse.compte, 1, 4) = '4007' THEN '407'
			ELSE substr(cse.compte, 1, 2) || substr(cse.compte, 5, 1)
		END AS CHIFFRE3,
		substr(cse.compte, 1, 2) AS CHIFFRE2
	FROM
		compta_sous_ecriture cse,
		compta_compte cc,
		compta_journal jrn
	WHERE
		cc.COMPTE = cse.compte
		AND cse.etat = 11
		AND cse.JOURNAL = jrn.id
	GROUP BY
		cse.COMPTE,
		cc.libelle,
		cc.typecompte,
		cse.daty

    );

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."REPORTSOLDE_JANVIER" ("COMPTE", "LIBELLE_COMPTE", "DEBIT", "CREDIT", "TYPECOMPTE", "MOIS", "ANNEE", "CHIFFRE3", "CHIFFRE2") AS
SELECT COMPTE,
       LIBELLE,
       CAST(sum(DEBIT) AS NUMBER(30, 2)),
       CAST(sum(CREDIT) AS NUMBER(30, 2)),
       TYPECOMPTE,
       MOIS,
       ANNEE,
       CHIFFRE3,
       CHIFFRE2
FROM (SELECT cse.COMPTE,
             cc.libelle,
             cse.debit,
             cse.credit,
             cc.typecompte,
             EXTRACT(MONTH from cse.daty)                                      AS MOIS,
             EXTRACT(YEAR from cse.daty)                                       AS ANNEE,
             CASE
                 WHEN TYPECOMPTE = 3 THEN SUBSTR(CSE.COMPTE, 1, 3) || SUBSTR(CSE.COMPTE, 5, 1)
                 WHEN TYPECOMPTE = 1 AND SUBSTR(CSE.COMPTE, 1, 4) = '4007' THEN '407'
                 ELSE SUBSTR(CSE.COMPTE, 1, 2) || SUBSTR(CSE.COMPTE, 5, 1) END as chiffre3,
             substr(cse.compte, 1, 2)                                          as chiffre2
      from compta_sous_ecriture cse,
           compta_compte cc,
           compta_journal jrn
      where cc.COMPTE = cse.compte
        and cse.journal = 'COMP000015'
        AND cse.etat = 11
        AND jrn.id = cse.journal
      UNION
      SELECT cse.ANALYTIQUE,
             cc.libelle,
             cse.debit                                                                 as debit,
             cse.credit                                                                as credit,
             cc.typecompte,
             EXTRACT(MONTH from cse.daty),
             EXTRACT(YEAR from cse.daty),
             CASE
                 WHEN TYPECOMPTE = 3 THEN SUBSTR(cse.ANALYTIQUE, 1, 3) || SUBSTR(cse.ANALYTIQUE, 5, 1)
                 ELSE SUBSTR(cse.ANALYTIQUE, 1, 2) || SUBSTR(cse.ANALYTIQUE, 5, 1) END as chiffre3,
             substr(cse.ANALYTIQUE, 1, 2)                                              as chiffre2
      from compta_sous_ecriture cse,
           compta_compte cc,
           compta_journal jrn
      where cc.COMPTE = cse.analytique
        and cse.journal = 'COMP000015'
        and cse.etat = 11
        and jrn.id = cse.journal)
group by COMPTE, LIBELLE, TYPECOMPTE, MOIS, ANNEE, CHIFFRE3, CHIFFRE2;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."REQUETE_A_ENVOYER_SERVEUR" ("ID", "ACTION", "TABLECONCERNE", "REQUETE", "DATY", "HEURE", "SERVEUR") AS
SELECT rae.ID, rae.ACTION, rae.TABLECONCERNE, rae.REQUETE, rae.DATY, rae.HEURE, rae.SERVEUR
FROM REQUETE_A_ENVOYER rae;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."REQUETE_EXECUTE_SERVEUR" ("ID", "ACTION", "TABLECONCERNE", "REQUETE", "DATY", "HEURE", "SERVEUR") AS
SELECT rae.ID, rae.ACTION, rae.TABLECONCERNE, rae.REQUETE, rae.DATY, rae.HEURE, re.SERVEUR
FROM REQUETE_A_ENVOYER rae
JOIN REQUETE_EXECUTE re on rae.ID = re.IDREQUETE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RESERVATIONDETAILSAVECMERE" ("ID", "IDPRODUIT", "QTE", "DATY", "IDCLIENT", "ETAT", "LIBELLECLIENT", "IDMERE", "LIBELLEPRODUIT") AS
select rd.id,ing.id as IDPRODUIT,rd.qte,rd.daty,r.IDCLIENT,r.ETAT as etat,c.nom||' '||c.TELEPHONE as libelleclient ,rd.IDMERE,ing.LIBELLE as libelleproduit from AS_INGREDIENTS ing
    left join reservationDetails rd on rd.idproduit=ing.ID
    left join reservation r on r.id=rd.IDMERE
left join CLIENT c on c.id=r.IDCLIENT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RESERVATIONDETAILSMAXDATE" ("ID", "IDMERE", "IDPRODUIT", "QTE", "DATY", "PU", "REMARQUE", "ETAT", "HEURE", "RN") AS
SELECT "ID","IDMERE","IDPRODUIT","QTE","DATY","PU","REMARQUE","ETAT","HEURE","RN"
FROM (
    SELECT r.*,
           ROW_NUMBER() OVER (PARTITION BY IDMERE ORDER BY daty DESC) AS rn
    FROM RESERVATIONDETAILS r
)
WHERE rn = 1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RESERVATIONDETAILS_LIB" ("ID", "IDMERE", "QTE", "DATY", "IDPRODUIT", "LIBELLEPRODUIT", "CATEGORIEPRODUIT", "PU", "MONTANT", "TVA", "MONTANTTVA", "MONTANTTTC", "CATEGORIEPRODUITLIB", "HEURE") AS
SELECT
r.ID,
r.IDMERE,
r.QTE,
r.DATY,
r.IDPRODUIT,
ai.LIBELLE AS libelleproduit,
ai.idCATEGORIEINGREDIENT AS categorieproduit,
r.PU,
r.QTE * r.PU AS  montant,
ai.tva as tva,
cast(r.qte*r.pu*(nvl(ai.tva,0)/100) as number(20,2)) as montantTva,
cast((r.QTE * r.PU)+(r.qte*r.pu*(nvl(ai.tva,0)/100)) as number(20,2)) as montantttc,
ai.CATEGORIEINGREDIENT AS categorieproduitlib,
r.heure AS heure
FROM RESERVATIONDETAILS r
LEFT JOIN AS_INGREDIENTS_LIB ai ON ai.id = r.IDPRODUIT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RESERVATIONDETAILS_LIBGROUPE" ("ID", "IDMERE", "QTE", "DATY", "IDPRODUIT", "LIBELLEPRODUIT", "CATEGORIEPRODUIT", "PU", "MONTANT", "TVA", "MONTANTTVA", "MONTANTTTC", "CATEGORIEPRODUITLIB", "HEURE") AS
SELECT
min(r.ID) as id,
r.IDMERE,
sum(r.QTE) as qte,
min(r.DATY) as daty,
r.IDPRODUIT,
r.libelleproduit AS libelleproduit,
r.categorieproduit AS categorieproduit,
avg(r.PU) as pu,
sum(r.QTE * r.PU) AS  montant,
avg(r.tva) as tva,
cast(sum(montantTva) as number(20,2)) as montantTva,
cast(sum(montantttc) as number(20,2)) as montantttc,
r.categorieproduitlib AS categorieproduitlib,
min(r.heure) AS heure
FROM RESERVATIONDETAILS_LIB r

group by r.idmere,r.idproduit,r.libelleproduit,r.categorieproduit,r.categorieproduitlib;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RESERVATIONDETSANSCI" ("ID", "IDMERE", "IDPRODUIT", "QTE", "DATY", "PU", "REMARQUE", "ETAT", "IDCLIENT") AS
SELECT
	rd."ID",
	rd."IDMERE",
	rd."IDPRODUIT",
	rd."QTE",
	rd."DATY",
	rd."PU",
	rd."REMARQUE",
	rd."ETAT",
	r."IDCLIENT"
FROM
	reservationDetails rd
	JOIN RESERVATION r
	ON rd.IDMERE = r.ID
WHERE
	rd.idmere NOT IN (
	SELECT
		c.reservation
	FROM
		checkin c
	WHERE
		c.etat >= 11
		AND c.IDPRODUIT = rd.idproduit);

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RESERVATIONMONTANT" ("IDMERE", "MONTANT", "MONTANTTVA", "MONTANTTTC") AS
SELECT 
r.IDMERE,
cast(sum(r.montant) as number(20,2)) AS montant,
cast(sum(r.MONTANTTVA)as number(20,2)) as MONTANTTVA,
cast(sum(r.MONTANTTTC) as number(20,2))as MONTANTTTC
FROM reservationdetails_lib r 
GROUP BY r.IDMERE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RESERVATIONSIMPLE" ("ID", "IDCLIENT", "DATY", "REMARQUE", "ETAT", "IDPRODUIT", "QTE") AS
select
    rs."ID",rs."IDCLIENT",rs."DATY",rs."REMARQUE",rs."ETAT",
    rsdt.IDPRODUIT,
    rsdt.QTE
from RESERVATION rs
join RESERVATIONDETAILS rsdt on rs.ID = rsdt.IDMERE
where 1> 2;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RESERVATION_LIB" ("ID", "IDCLIENT", "IDCLIENTLIB", "DATY", "REMARQUE", "ETAT", "ETATLIB", "MONTANT", "MONTANTTTC", "MONTANTTVA", "PAYE", "RESTEAPAYER") AS
SELECT 
r.id,
r.idClient,
c.NOM AS idclientlib,
r.daty,
r.remarque,
r.etat,
CASE 
	WHEN r.etat = 1 
	THEN 'CREE'
	WHEN r.etat = 0 
	THEN 'ANNULEE'
	WHEN r.etat = 11 
	THEN 'VISEE'
END AS etatlib,
rm.montant,
rm.MONTANTTTC,
rm.MONTANTTVA,
mvt.CREDIT as paye,
cast(rm.MONTANTTTC-mvt.CREDIT as number(20,2)) as resteAPayer
FROM RESERVATION r 
LEFT JOIN CLIENT c ON c.id = r.idClient 
LEFT JOIN reservationmontant rm ON rm.idmere = r.id
left join MOUVEMENTCAISSEGROUPERESA mvt on mvt.IDORIGINE=r.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RESERVATION_LIB_AVECMAXDATE" ("ID", "IDCLIENT", "IDCLIENTLIB", "DATY", "REMARQUE", "ETAT", "ETATLIB", "MONTANT", "MONTANTTTC", "MONTANTTVA", "PAYE", "RESTEAPAYER", "DATYFINPOTENTIEL") AS
select rl."ID",rl."IDCLIENT",rl."IDCLIENTLIB",rl."DATY",rl."REMARQUE",rl."ETAT",rl."ETATLIB",rl."MONTANT",rl."MONTANTTTC",rl."MONTANTTVA",rl."PAYE",rl."RESTEAPAYER", rdmd.DATY as DATYFINPOTENTIEL
from RESERVATION_LIB rl
         left join RESERVATIONDETAILSMAXDATE rdmd on rl.id = rdmd.IDMERE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RESRECLAMATIONLIB" ("ID", "IDRECLAMATION", "DATY", "IDTYPE", "ETAT", "ETATLIB", "IDTYPELIB", "QTE") AS
SELECT
    r.ID,
    r.IDRECLAMATION,
    r.daty,
    r.idType,
    r.etat,

    CASE r.etat
        WHEN 1  THEN 'Cree'
        WHEN 11 THEN 'Valide'
        WHEN 0 THEN 'Rejete'
        ELSE 'Autre'
        END AS etatLib,

    tr.VAL AS idTypeLib,
    r.qte
FROM resreclamation r
         LEFT JOIN TYPEresRECLAMATION tr
                   ON tr.ID = r.idType;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RESSOURCEPARFABCOMPLET_VISEE" ("ID", "IDFABRICATION", "IDPOSTEEFFECTIVE", "IDRESSOURCE", "MATRICULE", "IDOF", "ETAT", "TEMPORAIRE", "IDQUALIFICATIONEFFECTIVE", "IDCATEGORIE", "IDPOSTEDEFAUT", "IDQUALIFICATIONDEFAUT", "TAUXHORAIRE", "HS", "MN", "JF", "HD", "IF", "ETATLIB") AS
SELECT 
r."ID",r."IDFABRICATION",r."IDPOSTEEFFECTIVE",r."IDRESSOURCE",r."MATRICULE",r."IDOF",r."ETAT",r."TEMPORAIRE",r."IDQUALIFICATIONEFFECTIVE",r."IDCATEGORIE",r."IDPOSTEDEFAUT",r."IDQUALIFICATIONDEFAUT",r."TAUXHORAIRE",r."HS",r."MN",r."JF",r."HD",r."IF",r."ETATLIB"
FROM  ressourceParFabricationComplet r 
WHERE r.etat = 11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RESSOURCEPARFABRICATIONCOMPLET" ("ID", "DATY", "IDFABRICATION", "IDPOSTEDEFAUT", "IDRESSOURCE", "MATRICULE", "IDOF", "ETAT", "TEMPORAIRE", "IDQUALIFICATION", "IDCATEGORIE", "IDPOSTE", "IDPOSTELIB", "IDQUALIFICATIONEFFECTIVE", "TAUXHORAIRE", "HS", "MN", "JF", "HD", "IF", "ETATLIB", "IDRESSOURCELIB") AS
SELECT
    r.id,
    r.daty,
    r.idFabrication,
    r.idPoste AS idPosteDefaut,
    r.idRessource,
    p.matricule,
    f.IDOF,
    r.etat ,
    p.TEMPORAIRE,
    p.IDQUALIFICATION AS IdQualification,
    c.IDCATEGORIE,
    c.idPoste ,
    po.VAL AS idPostelib,
    p.IDQUALIFICATION AS IdQualificationEffective,
    CAST(c.montant/((40*52)/12) AS NUMBER(30,2) ) AS tauxhoraire,
    h.HS ,
    h.MN ,
    h.JF ,
    h.HD ,
    h.IF ,
    CASE
        WHEN r.etat = 0
            THEN 'ANNULEE'
        WHEN r.etat = 1
            THEN 'CREE'
        WHEN r.etat = 11
            THEN 'VISEE'
        END AS etatlib,
    p.MATRICULE AS idRessourcelib
FROM ressourceParFabrication r
         LEFT JOIN PAIE_INFO_PERSONNEL p ON p.id = r.idRessource
         LEFT JOIN CATEGORIE_QUALIFICATION c
                   ON c.IDQUALIFICATION = r.IDQUALIFICATION
                       AND c.IDCATEGORIE = p.IDCATEGORIE
                       AND (
                          (c.REMARQUE IS NULL)
                              OR (c.REMARQUE = r.IDRESSOURCE)
                          ) AND c.etat = 1
         LEFT JOIN FABRICATION f ON f.id = r.idFabrication
         LEFT JOIN heureSupFabrication h ON h.idRessParFab = r.id
         LEFT JOIN POSTE po ON po.id =  c.idPoste;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RESSOURCEPARFAB_CPL_RECTIF" ("ID", "DATY", "IDFABRICATION", "IDPOSTEDEFAUT", "IDRESSOURCE", "MATRICULE", "IDPOSTE", "IDPOSTELIB", "ETATLIB") AS
SELECT
	    r.id,
	    r.daty,
	    r.idFabrication,
	    r.idPoste AS idPosteDefaut,
	    r.idRessource,
	    p.MATRICULE,
	    r.IDPOSTE,
	    poste.val as idPosteLib,
	    CASE
	        WHEN r.etat = 0
	            THEN 'ANNULEE'
	        WHEN r.etat = 1
	            THEN 'CREEE'
	        WHEN r.etat = 11
	            THEN 'VISEE'
	        END AS etatlib
	FROM ressourceParFabrication r
	         LEFT JOIN PAIE_INFO_PERSONNEL p ON p.id = r.idRessource
	         LEFT JOIN POSTE poste ON poste.id = r.IDPOSTE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RESULTATFABRICATION" ("ID", "IDOFFILLE", "IDFABRICATION", "IDPRODUIT", "IDPRODUITLIB", "QTE", "IDINGREDIENTS", "QTEINGREDIENTS", "IDLIGNE", "DATY", "ENTREEDECHET") AS
SELECT
    OFF.IDMERE AS ID,
    OFF.ID AS IDOFFILLE,
    F.ID AS IDFABRICATION,
    OFF.IDINGREDIENTS AS IDPRODUIT,
    OFF.LIBELLE AS IDPRODUITLIB,
    OFF.QTE AS QTE,
    FF.IDINGREDIENTS,
    FF.QTE AS QTEINGREDIENTS,
    M.IDLIGNE,
    F.DATY,
    COALESCE((SELECT SUM(ENTREE)
              FROM MVTSTFILLEFABCATVISEGROUPE WHERE IDFAB = F.ID AND ENTREE > 0 and CATEGORIEINGREDIENT ='Dechets'
             ),0) AS ENTREEDECHET
FROM FABRICATIONFILLE FF
         LEFT JOIN FABRICATION F ON F.ID = FF.IDMERE
         LEFT JOIN OFFILLELIBSTOCK OFF ON OFF.ID = F.IDOFFILLE
         LEFT JOIN MACHINE M ON M.ID = FF.IDMACHINE
WHERE F.ETAT = 11 AND OFF.IDINGREDIENTS IS NOT NULL;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RESULTATMAINTENANCELIB" ("ID", "DATY", "IDORDRETRAVAUX", "IDPERSONNEL", "ETATMACHINE", "DESIGNATION", "PROCHAINEETAPE", "PROCHAINEDATY", "IDPERSONNELLIB", "ETATMACHINELIB") AS
SELECT
    rm."ID",rm."DATY",rm."IDORDRETRAVAUX",rm."IDPERSONNEL",rm."ETATMACHINE",rm."DESIGNATION",rm."PROCHAINEETAPE",rm."PROCHAINEDATY",
    u.nomuser AS idpersonnelLib,
    em.val AS etatmachineLib
FROM resultatmaintenance rm
         LEFT JOIN utilisateur u ON rm.idpersonnel = u.REFUSER
         LEFT JOIN etatmachine em ON rm.etatmachine = em.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RESULTATPREVEFFECTIFTOUS" ("DATY", "DEBIT", "CREDIT", "SEMAINE", "ANNEE", "MOIS") AS
SELECT 
t.daty,
nvl(r.debit,0) AS debit,
nvl(r.credit,0) AS credit,
(CAST (to_char( t.daty, 'IW') AS INTEGER)) AS semaine,
extract(YEAR FROM t.daty) AS annee,
EXTRACT (MONTH FROM t.daty) AS mois
FROM tousLesDate t 
left join resultatPrevisionnelEffectif r ON t.daty=r.daty;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RESULTATPREVGROUPMOIS" ("DATY", "DEBIT", "CREDIT", "annee", "mois") AS
SELECT min(r.daty) AS daty,sum(r.debit) AS debit,sum(r.CREDIT) AS credit,r."annee", r."mois" 
FROM RESULTATPREVISIONNELTOUS r GROUP BY r."annee", r."mois";

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RESULTATPREVGROUPSEMAINE" ("DATY", "DEBIT", "CREDIT", "semaine", "annee", "mois") AS
SELECT min(r.daty) AS daty,sum(r.debit) AS debit,sum(r.CREDIT) AS credit,r."semaine",r."annee", r."mois" 
FROM RESULTATPREVISIONNELTOUS r GROUP BY r."semaine",r."annee", r."mois";

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RESULTATPREVISIONNEL" ("DATY", "DEBIT", "CREDIT") AS
SELECT 
daty,
sum(debit) AS debit, 
sum(credit) AS credit 
FROM PREVISIONvalide p  group by daty;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RESULTATPREVISIONNELEFFECTIF" ("DATY", "DEBIT", "CREDIT") AS
SELECT daty,
sum(debit) AS debit, 
sum(credit) AS credit
FROM MOUVEMENTCAISSE_VISE  group by daty;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RESULTATPREVISIONNELMVT" ("DATY", "DEBIT", "CREDIT") AS
SELECT 
daty,
greatest(sum(debit-effectifdeb),0) AS debit, 
greatest(sum(credit-effectifCred),0) AS credit 
FROM PrevisionAvecMvtCaisse p  group by daty;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RESULTATPREVISIONNELTOUS" ("DATY", "DEBIT", "CREDIT", "SEMAINE", "ANNEE", "MOIS") AS
SELECT 
t.daty,
nvl(r.debit,0) AS debit,
nvl(r.credit,0) AS credit,
(CAST (to_char( t.daty, 'IW') AS INTEGER)) AS semaine,
extract(YEAR FROM t.daty) AS annee,
EXTRACT (MONTH FROM t.daty) AS mois
FROM tousLesDate t  left join resultatPrevisionnel r ON t.daty=r.daty;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RESULTATPREVISIONNELTOUSMVT" ("DATY", "DEBIT", "CREDIT", "SEMAINE", "ANNEE", "MOIS") AS
SELECT 
t.daty,
nvl(r.debit,0) AS debit,
nvl(r.credit,0) AS credit,
(CAST (to_char( t.daty, 'IW') AS INTEGER)) AS semaine,
extract(YEAR FROM t.daty) AS annee,
EXTRACT (MONTH FROM t.daty) AS mois
FROM tousLesDate t  left join resultatPrevisionnelMvt r ON t.daty=r.daty;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RESULTATRAPPROCHEMENT" ("ID", "IDSOUSECRITURE", "IDRELEVERDETAIL", "DEBIT", "CREDIT", "DATY", "DESIGNATIONSOUSECRITURE", "DESIGNATIONRELEVEDETAIL") AS
select
    '' as id,
    '' as idSousEcriture,
    '' as idReleverDetail,
    0 as debit,
    0 as credit,
    null as daty,
    '' as designationSousEcriture,
    '' as designationReleveDetail
from dual;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RETRAIT_FRAIS_MEDICAUX_ANALYSE" ("DIRECTION", "DIRECTIONLIB", "MOIS", "ANNEE", "DATEVAL", "DATEDESC", "DATELIB", "GAIN", "DEPENSE") AS
SELECT
    ld.id AS direction,
    ld.val AS directionlib,
    pe.mois,
    pe.annee,
    CASE
        WHEN pe.mois = 13 THEN TO_DATE('01-12-' || pe.annee, 'DD-MM-YYYY')
        ELSE TO_DATE('01-' || LPAD(pe.mois, 2, '0') || '-' || pe.annee, 'DD-MM-YYYY')
        END AS dateval,
    pe.annee || '-' || LPAD(pe.mois, 2, '0') AS datedesc,
    CASE
        WHEN pe.mois = 1 THEN 'Janvier'
        WHEN pe.mois = 2 THEN 'Fevrier'
        WHEN pe.mois = 3 THEN 'Mars'
        WHEN pe.mois = 4 THEN 'Avril'
        WHEN pe.mois = 5 THEN 'Mai'
        WHEN pe.mois = 6 THEN 'Juin'
        WHEN pe.mois = 7 THEN 'Juillet'
        WHEN pe.mois = 8 THEN 'Aout'
        WHEN pe.mois = 9 THEN 'Septembre'
        WHEN pe.mois = 10 THEN 'Octobre'
        WHEN pe.mois = 11 THEN 'Novembre'
        WHEN pe.mois = 12 THEN 'Decembre'
        WHEN pe.mois = 13 THEN '13 eme'
        ELSE NULL
        END || '-' || pe.annee AS datelib,
    SUM(pe.gain) AS gain,
    NVL(SUM(rf.montant), 0) AS depense
FROM paie_edition pe
         LEFT JOIN paie_info_personnel_libcomplet pf ON pf.id = pe.idpersonnel
         LEFT JOIN log_direction ld ON ld.id = pf.direction
         LEFT JOIN retrait_frais_medicaux rf
                   ON pe.mois = EXTRACT(MONTH FROM rf.daty)
                       AND pe.annee = EXTRACT(YEAR FROM rf.daty)
                       AND rf.etat >= 11
WHERE pe.idelementpaie NOT LIKE '%PR000FRM%'
GROUP BY
    pe.mois,
    pe.annee,
    ld.id,
    ld.val;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RETRAIT_FRAIS_MEDICAUX_LIB" ("ID", "DATY", "IDPERSONNEL", "DESCRIPTION", "MONTANT", "ETAT", "IDPERSONNELLIB", "ETATLIB", "MATRICULE") AS
SELECT rfm.id,
       rfm.daty,
       pipl.id AS idpersonnel,
       rfm.description,
       rfm.montant,
       rfm.etat,
       (pipl.nom || ' ') || pipl.prenom AS idpersonnellib,
       CASE
           WHEN rfm.etat = 1 THEN 'CREE(E)'
           WHEN rfm.etat = 10 THEN 'VALIDE(E)'
           WHEN rfm.etat >= 11 THEN 'VISE(E)'
           ELSE NULL
           END AS etatlib,
       pipl.matricule
FROM retrait_frais_medicaux rfm
         LEFT JOIN paie_info_personnel_libcomplet pipl ON rfm.idpersonnel = pipl.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RETRAIT_FRAIS_MEDICAUX_RESTE" ("ID", "DATY", "IDPERSONNEL", "DESCRIPTION", "MONTANT", "ETAT", "RESTE") AS
SELECT rfm.id,
       rfm.daty,
       rfm.idpersonnel,
       rfm.description,
       rfm.montant,
       rfm.etat,
       p.reste
FROM retrait_frais_medicaux rfm
         LEFT JOIN personne_gain_sortie_reste p ON rfm.idpersonnel = p.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RETRAIT_FRAIS_MEDIC_GRPPERS" ("MONTANT", "IDPERSONNEL") AS
SELECT sum(retrait_frais_medicaux.montant) AS montant,
       retrait_frais_medicaux.idpersonnel
FROM retrait_frais_medicaux
WHERE retrait_frais_medicaux.etat >= 9
GROUP BY retrait_frais_medicaux.idpersonnel;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RISTOURNEDETAILS_LIB" ("ID", "IDRISTOURNE", "IDPRODUIT", "TAUX1", "TAUX2", "IDORIGINE", "IDPRODUITLIB", "QTE", "PU") AS
SELECT
    r.Id,
    r.idristourne,
    r.idproduit,
    r.taux1,
    r.taux2,
    r.idorigine,
    nvl(ai.libellevente,ai.LIBELLE) AS idproduitlib,
    r.QTE,
    r.PU
FROM RISTOURNEDETAILS r
         LEFT JOIN AS_INGREDIENTS ai ON ai.id=r.idproduit;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RISTOURNELIB" ("ID", "DESIGNATION", "IDCLIENT", "DATY", "DATEDEBUTRISTOURNE", "DATEFINRISTOURNE", "IDORIGINE", "ETAT", "IDCLIENTLIB", "ETATLIB", "MOTSCLESSS") AS
SELECT SQ.ID,
       SQ.DESIGNATION,
       SQ.IDCLIENT,
       SQ.DATY,
       SQ.DATEDEBUTRISTOURNE,
       SQ.DATEFINRISTOURNE,
       SQ.IDORIGINE,
       SQ.ETAT,
       SQ.IDCLIENTLIB,
       SQ.ETATLIB,
       (
           id || ' | ' || designation || ' | ' || SQ.IDCLIENTLIB
           ) AS MOTSCLESSS
FROM (SELECT R.ID,
             R.DESIGNATION,
             R.IDCLIENT,
             R.DATY,
             R.DATEDEBUTRISTOURNE,
             R.DATEFINRISTOURNE,
             R.IDORIGINE,
             R.ETAT,
             C.NOM   AS IDCLIENTLIB,
             CASE
                 WHEN R.ETAT = 0
                     THEN 'ANNUL&Eacute;E'
                 WHEN R.ETAT = 1
                     THEN 'CR&Eacute;&Eacute;E'
                 WHEN R.ETAT = 11
                     THEN 'VIS&Eacute;E'
                 END AS ETATLIB
      FROM RISTOURNE R
               LEFT JOIN CLIENT C ON R.IDCLIENT = C.ID) SQ;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SALAIREBASEMOIS" ("IDPERSONNEL", "MOIS", "ANNEE", "SALAIREBASE") AS
SELECT IDPERSONNEL,mois,annee,round(sum(gain),0) AS salairebase FROM paie_edition WHERE IDELEMENTPAIE IN (
    SELECT id FROM PAIE_RUBRIQUE pr WHERE TYPERUBRIQUE='G' AND IMPOSABLE = 'I'
) GROUP BY IDPERSONNEL,mois,annee;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SALAIRECATEGORIE_ACTIF" ("ID", "IDCATEGORIE", "IDQUALIFICATION", "REMARQUE", "MONTANT", "DATE_DEBUT", "ETAT") AS
SELECT
    cq.id,
    cq.idcategorie,
    cq.idqualification,
    cq.remarque,
    cq.montant,
    cq.date_debut,
    cq.etat
FROM CATEGORIE_QUALIFICATION cq
WHERE cq.etat = 1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SANCTION_CPL" ("ID", "IDPERSONNE", "NOMPERSONNEL", "DATEDEBUT", "DATY", "DUREE", "NIVEAUSANCTION", "LIBELLEFAUTE", "SANCTION", "REGLEMENTLIB", "NUMEROREGLE", "ETAT", "MATRICULE") AS
SELECT
    s.id,
    s.IDPERSONNE,
    lpr.nom || ' ' || lpr.prenom AS nomPersonnel,
    s.datedebut,
    s.daty,
    s.duree,
    s.niveausanction,
    tf.val AS libelleFaute,
    ts.val AS sanction,
    ri.DESCRIPTIONREGLE AS reglementLib,
    ri.NUMEROREGLE AS numeroRegle,
    s.etat AS etat,
    lpr.MATRICULE
FROM SANCTION s
         LEFT JOIN LOG_PERSONNEL_V2 lpr ON s.idpersonne = lpr.id
         LEFT JOIN TYPEFAUTE tf ON s.TYPEFAUTE = tf.ID
         LEFT JOIN typesanction ts ON s.typesanction = ts.id
         LEFT JOIN REGLEMENTINTERIEUR ri ON s.IDREGLEENFREINTE = ri.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SECTIONLIB" ("ID", "IDSERVICE", "VAL", "DESCE", "IDSERVICELIB") AS
SELECT 
    s."ID",s."IDSERVICE",s."VAL",s."DESCE",
    sv.LIBELLE AS idServiceLib
FROM SECTION s
LEFT JOIN SERVICE sv 
    ON s.IDSERVICE = sv.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SECTION_LIB" ("ID", "IDSERVICE", "VAL", "DESCE", "LIBELLE", "COMPTE") AS
SELECT
    s."ID",s."IDSERVICE",s."VAL",s."DESCE",
    ser.LIBELLE AS libelle,
    ''  AS compte
FROM SECTION s
         LEFT JOIN departementDivers ser
                   ON s.IDSERVICE = ser.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SERVICEMAINTENANCE" ("ID", "VAL", "DESCE") AS
SELECT
    LOG_SERVICE.id,
    LOG_SERVICE.libelle AS val,
    LOG_SERVICE.libelle AS desce
FROM LOG_SERVICE
WHERE
    id LIKE 'SERVM%';

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SESSION_FORMATION_LIB" ("ID", "IDACTIONFORMATION", "IDACTIONFORMATIONLIB", "INTITULE", "REFERENCE", "DATEDEBUT", "DATEFIN", "NBHEUREPREVUE", "ETAT", "ETATLIB", "REMARQUE") AS
SELECT
    sf.ID,
    sf.IDACTIONFORMATION,
    af.REFERENCE || ' - ' || af.INTITULE AS IDACTIONFORMATIONLIB,
    af.INTITULE,
    af.REFERENCE,
    sf.DATEDEBUT,
    sf.DATEFIN,
    sf.NBHEUREPREVUE,
    sf.ETAT,
    CASE 
        WHEN sf.ETAT = 1 THEN 'Cree'
        WHEN sf.ETAT = 11 THEN 'Valide'
        WHEN sf.ETAT = 0 THEN 'Annule'
        ELSE 'Inconnu'
    END AS ETATLIB,
    sf.REMARQUE
FROM SESSION_FORMATION sf
LEFT JOIN ACTION_FORMATION af
    ON sf.IDACTIONFORMATION = af.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SITUATIONDEMANDE" ("ID", "IDPERSONNEL", "IDTYPEDEMANDE", "TITRE", "HORAIRENORMAL", "HEUREDEPART", "HEUREARRIVE", "IDTYPEABSENCE", "MOTIF", "NUMERO", "DESCE", "ETAT", "DATY", "DUREE", "DATEDEPART", "DATERETOUR", "OBSERVATION", "REMARQUE", "DATEHISTORIQUE", "HEUREHISTORIQUE", "VALETATHIERARCHIE", "RANG") AS
SELECT d.id,
       d.idpersonnel,
       d.idtypedemande,
       d.titre,
       d.horairenormal,
       d.heuredepart,
       d.heurearrive,
       d.idtypeabsence,
       d.motif,
       d.numero,
       d.desce,
       d.etat,
       d.daty,
       d.duree,
       d.datedepart,
       d.dateretour,
       d.observation,
       d.remarque,
       h.daty AS datehistorique,
       h.heure AS heurehistorique,
       e.valetathierarchie,
       e.rang
FROM demande d
         JOIN historiquedemandemax h ON h.iddemande = d.id
         JOIN etatdemande_etat e ON e.idtypedemande = d.idtypedemande AND d.etat = e.etatvisa OR d.etat = e.etatannule;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SITUATIONDEMANDE_SUIVANT" ("ID", "IDPERSONNEL", "IDTYPEDEMANDE", "TITRE", "HORAIRENORMAL", "HEUREDEPART", "HEUREARRIVE", "IDTYPEABSENCE", "MOTIF", "NUMERO", "DESCE", "ETAT", "DATY", "DUREE", "DATEDEPART", "DATERETOUR", "OBSERVATION", "REMARQUE", "DATEHISTORIQUE", "HEUREHISTORIQUE", "VALETATHIERARCHIE", "RANG", "RANGSUIVANT", "VALETATHIERARCHIESUIVANT", "IDETATHIERARCHIE") AS
SELECT s.id,
       s.idpersonnel,
       s.idtypedemande,
       s.titre,
       s.horairenormal,
       s.heuredepart,
       s.heurearrive,
       s.idtypeabsence,
       s.motif,
       s.numero,
       s.desce,
       s.etat,
       s.daty,
       s.duree,
       s.datedepart,
       s.dateretour,
       s.observation,
       s.remarque,
       s.datehistorique,
       s.heurehistorique,
       s.valetathierarchie,
       s.rang,
       e.rang AS rangsuivant,
       e.valetathierarchie AS valetathierarchiesuivant,
       e.idetathierarchie
FROM situationdemande s
         JOIN etatdemande_etat e ON e.idtypedemande = s.idtypedemande AND e.rang = (s.rang + 1);

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SITUATION_ARTICLE" ("ID", "PRODUIT", "IDBC", "QUANTITE", "PU", "MONTANT", "TVA", "UNITE", "REMISE", "DATY", "ETAT", "REMARQUE", "DESIGNATION", "MODEPAIEMENT", "FOURNISSEUR", "REFERENCE", "QTE_RESTE") AS
select bc."ID",bc."PRODUIT",bc."IDBC",bc."QUANTITE",bc."PU",bc."MONTANT",bc."TVA",bc."UNITE",bc."REMISE",bc."DATY",bc."ETAT",bc."REMARQUE",bc."DESIGNATION",bc."MODEPAIEMENT",bc."FOURNISSEUR",bc."REFERENCE",
       BC.QUANTITE - nvl(AB.qte_livre,0) AS QTE_reste
from AS_BONDECOMMANDE_MF bc
         left join AS_BONDELIVRAISON_LIVRE AB on AB.IDBC_FILLE = bc.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SITUATION_BUDGET_DEPENSES" ("ID", "COMPTE", "SERVICE", "MOIS", "ANNEE", "MOISLIB", "BUDGET", "MONTANTFACTURE", "PAIEMENT", "RESTEAPAYER", "ECARTFACTUREBUDGET", "ECARTBUDGETPAIEMENT", "MOTSCLESSS") AS
SELECT SQ.ID,SQ.COMPTE,SQ.SERVICE,SQ.MOIS,SQ.ANNEE,SQ.MOISLIB,SQ.BUDGET,SQ.MONTANTFACTURE,SQ.PAIEMENT,SQ.RESTEAPAYER,SQ.ECARTFACTUREBUDGET,SQ.ECARTBUDGETPAIEMENT,
	       (NVL(TO_CHAR(ID),'') || ' | ' || NVL(TO_CHAR(COMPTE),'') || ' | ' || NVL(TO_CHAR(SERVICE),'') || ' | ' || NVL(TO_CHAR(MOIS),'') || ' | ' || NVL(TO_CHAR(ANNEE),'') || ' | ' || NVL(TO_CHAR(MOISLIB),'') || ' | ' || NVL(TO_CHAR(BUDGET),'') || ' | ' || NVL(TO_CHAR(MONTANTFACTURE),'') || ' | ' || NVL(TO_CHAR(PAIEMENT),'') || ' | ' || NVL(TO_CHAR(RESTEAPAYER),'') || ' | ' || NVL(TO_CHAR(ECARTFACTUREBUDGET),'') || ' | ' || NVL(TO_CHAR(ECARTBUDGETPAIEMENT),'')) AS MOTSCLESSS
	FROM (
	         select
	             '-' as id,
	             bdsv.COMPTE,
	             IDSERVICELIB as service,
	             bdsv.mois,
	             bdsv.annee,
	             bdsv.moislib,
	             bdsv.depenses as budget,
	             ffc.montant as montantfacture,
	             ffc.montantpaye as paiement,
	             ffc.resteapayer,
	             bdsv.depenses - ffc.montant as ecartfacturebudget,
	             bdsv.depenses - ffc.montantpaye as ecartbudgetpaiement
	         from budget_depense_sum_view bdsv
	                  left join (
	             select
	                 SUBSTR(compteregr, 1, LENGTH(bdsv_inner.COMPTE)) as compteregr_groupe,
	                 mois,
	                 annee,
	                 SERVICE,
	                 sum(montantfille * TAUXDECHANGE)     as montant,
	                 sum(MontantFillePaye * TAUXDECHANGE) as montantpaye,
	                 sum(resteapayerfille * TAUXDECHANGE) as resteapayer
	             from facturefournisseurfille_paye ffp
	                      cross join (select distinct COMPTE from budget_depense_sum_view_budget) bdsv_inner
	             where SUBSTR(ffp.compteregr, 1, LENGTH(bdsv_inner.COMPTE)) = bdsv_inner.COMPTE
	             group by SUBSTR(compteregr, 1, LENGTH(bdsv_inner.COMPTE)), mois, annee, SERVICE
	         ) ffc
	                            on ffc.compteregr_groupe like bdsv.COMPTE||'%'
	                                and ffc.mois = bdsv.mois
	                                and ffc.annee = bdsv.annee
	                                and ffc.SERVICE = bdsv.SERVICE
	     ) SQ;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SITUATION_BUDGET_DEPENSES_VIDE" ("ID", "COMPTE", "SERVICE", "ANNEE", "MOISDEBUT", "MOISDEBUTLIB", "MOISFIN", "MOISFINLIB", "BUDGET", "MONTANTFACTURE", "PAIEMENT", "RESTEAPAYER", "ECARTFACTUREBUDGET", "ECARTBUDGETPAIEMENT") AS
select id, compte, service, annee, 6 as moisdebut,moisdebutlib, 8 as moisfin,moisfinlib, budget, montantfacture, paiement, resteapayer, ECARTFACTUREBUDGET, ECARTBUDGETPAIEMENT from
	    (select ID,
	            COMPTE,
	            SERVICE,
	            ANNEE,
	            sum(nvl(BUDGET, 0)) as budget,
	            sum(nvl(MONTANTFACTURE, 0)) as montantfacture,
	            sum(nvl(PAIEMENT, 0)) as paiement,
	            SUM(nvl(RESTEAPAYER, 0)) as resteapayer,
	            SUM(nvl(ECARTFACTUREBUDGET, 0)) as ECARTFACTUREBUDGET,
	            SUM(nvl(ECARTBUDGETPAIEMENT, 0)) as ECARTBUDGETPAIEMENT,
	            TO_CHAR(
	                    TO_DATE(TO_CHAR(6, 'FM00'), 'MM'),
	                    'FMMonth',
	                    'NLS_DATE_LANGUAGE=FRENCH'
	            ) AS moisdebutlib,
	            TO_CHAR(
	                    TO_DATE(TO_CHAR(8, 'FM00'), 'MM'),
	                    'FMMonth',
	                    'NLS_DATE_LANGUAGE=FRENCH'
	            ) AS moisfinlib
	     from situation_budget_depenses where mois between 6 and 8 group by ID, COMPTE, SERVICE, ANNEE);

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SITUATION_BUDGET_RECETTES" ("ID", "COMPTE", "SERVICE", "MOIS", "ANNEE", "MOISLIB", "BUDGET", "MONTANTFACTURE", "PAIEMENT", "RESTEAPAYER", "ECARTFACTUREBUDGET", "ECARTBUDGETPAIEMENT") AS
SELECT SQ.ID,
       SQ.COMPTE,
       SQ.SERVICE,
       SQ.MOIS,
       SQ.ANNEE,
       SQ.MOISLIB,
       SQ.BUDGET,
       SQ.MONTANTFACTURE,
       SQ.PAIEMENT,
       SQ.RESTEAPAYER,
       SQ.ECARTFACTUREBUDGET,
       SQ.ECARTBUDGETPAIEMENT
FROM (
  select
    '-' as id,
    bdsv.COMPTE,
    IDSERVICELIB as service,
    bdsv.mois,
    bdsv.annee,
    bdsv.moislib,
    bdsv.depenses as budget,
    ffc.montant as montantfacture,
    ffc.montantpaye as paiement,
    ffc.resteapayer,
    bdsv.depenses - ffc.montant as ecartfacturebudget,
    bdsv.depenses - ffc.montantpaye as ecartbudgetpaiement
from BUDGET_RECETTE_SUM_VIEW bdsv
    left join (
        select
            SUBSTR(ffp.compte, 1, LENGTH(bdsv_inner.COMPTE)) as compteregr_groupe,
            mois,
            annee,
            sum(montantfille * TAUXDECHANGE)     as montant,
            sum(MontantFillePaye * TAUXDECHANGE) as montantpaye,
            sum(resteapayerfille * TAUXDECHANGE) as resteapayer
        from VENTE_DETAILS_PAYE ffp
        cross join (select distinct COMPTE from BUDGET_RECETTE_SUM_VIEW) bdsv_inner
        where SUBSTR(ffp.compte, 1, LENGTH(bdsv_inner.COMPTE)) = bdsv_inner.COMPTE
        group by SUBSTR(ffp.compte, 1, LENGTH(bdsv_inner.COMPTE)), mois, annee
    ) ffc
    on ffc.compteregr_groupe like bdsv.COMPTE||'%'
        and ffc.mois = bdsv.mois
        and ffc.annee = bdsv.annee
) SQ;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SITUATION_BUDGET_RECETTES_VIDE" ("ID", "COMPTE", "SERVICE", "ANNEE", "MOISDEBUT", "MOISDEBUTLIB", "MOISFIN", "MOISFINLIB", "BUDGET", "MONTANTFACTURE", "PAIEMENT", "RESTEAPAYER", "ECARTFACTUREBUDGET", "ECARTBUDGETPAIEMENT") AS
SELECT SQ.ID,
       SQ.COMPTE,
       SQ.SERVICE,
       SQ.ANNEE,
       SQ.MOISDEBUT,
       SQ.MOISDEBUTLIB,
       SQ.MOISFIN,
       SQ.MOISFINLIB,
       SQ.BUDGET,
       SQ.MONTANTFACTURE,
       SQ.PAIEMENT,
       SQ.RESTEAPAYER,
       SQ.ECARTFACTUREBUDGET,
       SQ.ECARTBUDGETPAIEMENT
FROM (
select id, compte, service, annee, 6 as moisdebut,moisdebutlib, 8 as moisfin,moisfinlib, budget, montantfacture, paiement, resteapayer, ECARTFACTUREBUDGET, ECARTBUDGETPAIEMENT from
(select ID,
    COMPTE,
    SERVICE,
    ANNEE,
    sum(nvl(BUDGET, 0)) as budget,
    sum(nvl(MONTANTFACTURE, 0)) as montantfacture,
    sum(nvl(PAIEMENT, 0)) as paiement,
    SUM(nvl(RESTEAPAYER, 0)) as resteapayer,
    SUM(nvl(ECARTFACTUREBUDGET, 0)) as ECARTFACTUREBUDGET,
    SUM(nvl(ECARTBUDGETPAIEMENT, 0)) as ECARTBUDGETPAIEMENT,
    TO_CHAR(
        TO_DATE(TO_CHAR(6, 'FM00'), 'MM'),
        'FMMonth',
        'NLS_DATE_LANGUAGE=FRENCH'
    ) AS moisdebutlib,
    TO_CHAR(
        TO_DATE(TO_CHAR(8, 'FM00'), 'MM'),
        'FMMonth',
        'NLS_DATE_LANGUAGE=FRENCH'
    ) AS moisfinlib
    from SITUATION_BUDGET_RECETTES where mois between 6 and 8 group by ID, COMPTE, SERVICE, ANNEE)
) SQ;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SITUATION_SALAIRE_AUTRE" ("IDPERSONNEL", "IDEDITION", "MOIS", "ANNEE", "HEURESUPP30NI", "HEURESUPP30I", "HEURESUPP50NI", "HEURESUPP50I", "MAJNUIT", "MAJFERIE", "MAJWEEKEND", "ABBATEMENT") AS
SELECT
    idpersonnel,
    idedition,
    mois,
    annee,
    SUM(CASE WHEN IDELEMENTPAIE = 'PR0000130'  THEN gain ELSE 0 END) AS heuresupp30ni,
    SUM(CASE WHEN IDELEMENTPAIE = 'PR0000130I' THEN gain ELSE 0 END) AS heuresupp30i,
    SUM(CASE WHEN IDELEMENTPAIE = 'PR0000150'  THEN gain ELSE 0 END) AS heuresupp50ni,
    SUM(CASE WHEN IDELEMENTPAIE = 'PR0000150I'  THEN gain ELSE 0 END) AS heuresupp50i,
    SUM(CASE WHEN IDELEMENTPAIE = 'PR0000221' THEN gain ELSE 0 END) AS majnuit,
    SUM(CASE WHEN IDELEMENTPAIE = 'PR0000222'  THEN gain ELSE 0 END) AS majferie,
    SUM(CASE WHEN IDELEMENTPAIE = 'PR0000223'  THEN gain ELSE 0 END) AS majweekend,
    SUM(CASE WHEN IDELEMENTPAIE = 'PR000181'  THEN gain ELSE 0 END) AS abbatement
FROM PAIE_EDITION pe
GROUP BY
    idpersonnel,idedition,mois,annee;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SITUATION_SALAIRE_COMPLET" ("MATRICULE", "NOM", "ID", "MOIS", "ANNEE", "IDEDITION", "SALAIRE", "HS_M", "INDEM", "ANCIEN", "PRIME", "AUTRES", "TOTAL", "CNAPS", "OSTIE", "IRSA_E", "IRSA_S", "AV_SPE", "AUTRES2", "A_PAYER", "HEURESUPP30NI", "HEURESUPP30I", "HEURESUPP50NI", "HEURESUPP50I", "MAJNUIT", "MAJFERIE", "MAJWEEKEND", "ABBATEMENT", "MOISLIB") AS
SELECT se.MATRICULE,se.NOM,(se.ID||'//'||sa.idedition) AS id,se.MOIS,se.ANNEE,se.IDEDITION,se.SALAIRE,se.HS_M,se.INDEM,se.ANCIEN,se.PRIME,se.AUTRES,se.TOTAL,se.CNAPS,se.OSTIE,se.IRSA_E,se.IRSA_S,se.AV_SPE,se.AUTRES2,se.A_PAYER,sa.heuresupp30ni,heuresupp30i,heuresupp50ni,heuresupp50i,majnuit,majferie,majweekend,abbatement,
	       CASE se.MOIS
	           WHEN 1 THEN 'Janvier'
	           WHEN 2 THEN 'Fevrier'
	           WHEN 3 THEN 'Mars'
	           WHEN 4 THEN 'Avril'
	           WHEN 5 THEN 'Mai'
	           WHEN 6 THEN 'Juin'
	           WHEN 7 THEN 'Juillet'
	           WHEN 8 THEN 'Aout'
	           WHEN 9 THEN 'Septembre'
	           WHEN 10 THEN 'Octobre'
	           WHEN 11 THEN 'Novembre'
	           WHEN 12 THEN 'Decembre'
	           END AS MOISLIB
	FROM SITUATION_SALAIRE_EDITION se
	         LEFT JOIN SITUATION_SALAIRE_AUTRE sa
	                   ON se.idedition =sa.idedition
	                       AND se.id = sa.idpersonnel;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SITUATION_SALAIRE_EDITION" ("MATRICULE", "NOM", "ID", "MOIS", "ANNEE", "IDEDITION", "SALAIRE", "HS_M", "INDEM", "ANCIEN", "PRIME", "AUTRES", "TOTAL", "CNAPS", "OSTIE", "IRSA_E", "IRSA_S", "AV_SPE", "AUTRES2", "A_PAYER") AS
SELECT
    pinfo.matricule AS matricule,
    log.nom AS nom,
    v."ID",v."MOIS",v."ANNEE",v."IDEDITION",v."SALAIRE",v."HS_M",v."INDEM",v."ANCIEN",v."PRIME",v."AUTRES",v."TOTAL",v."CNAPS",v."OSTIE",v."IRSA_E",v."IRSA_S",v."AV_SPE",v."AUTRES2",v."A_PAYER"
FROM
    V_PAIE_RECAP v
        LEFT JOIN paie_info_personnel pinfo
                  ON v.id = pinfo.id
        LEFT JOIN log_personnel log
                  ON v.id = log.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SITUATION_SALAIRE_EDITION_DIST" ("ID", "IDEDITION", "NBENFANT", "MATRICULE", "NOM", "PRENOM", "PERSONNEL", "FONCTION", "IDFONCTION", "CLASSIFICATION", "IDCATEGORIE", "IDDIRECTION", "DIRECTION", "SECTION", "SECTION_NUMERO", "SECTION_LIBELLE", "SALAIRE", "SALAIREBRUTE", "HEUREMOIS", "HEUREPRESENCE", "TAUXHORAIRE", "SALAIREMOIS", "HEURESUP", "RAPPEL", "RETENUABSC", "PRIME", "CONGEPAYER", "PREAVIS", "NETPAYER", "NETPAYERARR", "INDAMDIVFIXE", "CNAPS", "OSTIE", "NETIMPOSABLE", "NETIMPOSABLEARR", "IRSA", "IRSANET", "ALLOCATION", "AVANCESALAIRE", "AVANCEEXCEP", "ANNEE", "MOIS") AS
SELECT DISTINCT
    lp.ID,
    pe.idedition AS idedition,
    pip.nbenfant,
    pip.MATRICULE,
    trim(TRAILING ' ' FROM lp.NOM) AS nom,
    trim(TRAILING ' ' FROM lp.PRENOM) AS prenom,
    trim(TRAILING ' ' FROM lp.NOM)
        || ' '
        || trim(TRAILING ' ' FROM lp.PRENOM) AS personnel,
    pf.desce AS fonction,
    pf.id AS idfonction,
    pc.VAL AS classification,
    pc.id AS idcategorie,
    ld.ID AS iddirection,
    ld.VAL AS direction,
    ls.ID AS SECTION,
    ls.CODE_SERVICE AS section_numero,
    ls.libelle AS section_libelle,
    nvl(SALAIREDEBASE.salairedebase, 0) AS salaire,
    nvl(totalgain.gain,0) as salairebrute,
    173.33 as heuremois,
    nvl(poi.HEURENORMAL, 0) AS heurepresence,
    nvl(pe.tauxhoraire, 0) AS tauxhoraire,
    nvl(salaire.gain, 0) AS salairemois,
    nvl(heuresup.gain, 0) AS heuresup,
    nvl(rappel.gain, 0) AS rappel,
    nvl(retenuabsc.retenue, 0) AS retenuabsc,
    nvl(prime.gain, 0) AS prime,
    nvl(congepayer.gain, 0) AS congepayer,
    nvl(preavis.gain, 0) AS preavis,
    nvl(netpayer.gain, 0) AS netpayer,
    nvl(netpayerarr.gain, 0) AS netpayerarr,
    nvl(indamdivfixe.gain, 0) AS indamdivfixe,
    nvl(cnaps.retenue, 0) AS cnaps,
    nvl(ostie.retenue, 0) AS ostie,
    nvl(netimposable.retenue, 0) AS netimposable,
    nvl(netimposablearr.retenue, 0) AS netimposablearr,
    nvl(irsa.retenue, 0) AS irsa,
    nvl(irsanet.retenue, 0) AS irsanet,
    nvl(allocation.gain,0) as allocation,
    nvl(avancesalaire.retenue, 0) AS avancesalaire,
    nvl(avanceexcep.retenue, 0) AS avanceexcep,
    pe.annee,
    pe.mois
FROM -- select * from
     paie_edition pe
         INNER JOIN log_personnel lp ON
         lp.id = pe.idpersonnel
         INNER JOIN paie_info_personnel pip ON
         pip.id = pe.idpersonnel
         INNER JOIN log_direction ld ON
         pe.DIRECTION = ld.ID
         INNER JOIN log_service ls ON
         pe.SERVICE = ls.ID
         INNER JOIN CATEGORIE_PAIE pc ON
         pe.IDCATEGORIE = pc.ID
         INNER JOIN paie_fonction pf ON
         pe.IDFONCTION = pf.ID
         INNER JOIN POINTAGE poi ON
         pe.IDPERSONNEL = poi.IDPERSONNEL
         LEFT JOIN (
         SELECT
             idpersonnel,
             sum(gain) AS gain,
             mois,
             annee
         FROM
             paie_edition pe
         WHERE
             regroupement = 1
         GROUP BY
             idpersonnel,
             mois,
             annee) salaire
                   ON
                       salaire.idpersonnel = lp.id
                           AND salaire.annee = pe.annee
                           AND salaire.mois = pe.mois
         LEFT JOIN (
         SELECT
             idpersonnel,
             max(SALAIREDEBASE) AS salairedebase,
             mois,
             annee
         FROM
             paie_edition pe
         WHERE
             regroupement = 18
         GROUP BY
             idpersonnel,
             mois,
             annee) salairedebase
                   ON
                       salairedebase.idpersonnel = lp.id
                           AND salairedebase.annee = pe.annee
                           AND salairedebase.mois = pe.mois
         LEFT JOIN (
         SELECT
             idpersonnel,
             sum(gain) AS gain,
             mois,
             annee
         FROM
             paie_edition pe
         WHERE
             regroupement = 2
         GROUP BY
             idpersonnel,
             mois,
             annee) heuresup
                   ON
                       heuresup.idpersonnel = lp.id
                           AND heuresup.annee = pe.annee
                           AND heuresup.mois = pe.mois
         LEFT JOIN (
         SELECT
             idpersonnel,
             sum(gain) AS gain,
             mois,
             annee
         FROM
             paie_edition pe
         WHERE
             regroupement = 3
         GROUP BY
             idpersonnel,
             mois,
             annee) rappel
                   ON
                       rappel.idpersonnel = lp.id
                           AND rappel.annee = pe.annee
                           AND rappel.mois = pe.mois
         LEFT JOIN (
         SELECT
             idpersonnel,
             sum(RETENUE) AS retenue,
             mois,
             annee
         FROM
             paie_edition pe
         WHERE
             regroupement = 4
         GROUP BY
             idpersonnel,
             mois,
             annee) retenuabsc
                   ON
                       retenuabsc.idpersonnel = lp.id
                           AND retenuabsc.annee = pe.annee
                           AND retenuabsc.mois = pe.mois
         LEFT JOIN (
         SELECT
             idpersonnel,
             sum(gain) AS gain,
             mois,
             annee
         FROM
             paie_edition pe
         WHERE
             regroupement = 5
         GROUP BY
             idpersonnel,
             mois,
             annee) prime
                   ON
                       prime.idpersonnel = lp.id
                           AND prime.annee = pe.annee
                           AND prime.mois = pe.mois
         LEFT JOIN (
         SELECT
             idpersonnel,
             sum(gain) AS gain,
             mois,
             annee
         FROM
             PAIE_EDITION_LIBCOMPLET pe
         WHERE
             CODERUBRIQUE IN ('403', '4030')
         GROUP BY
             idpersonnel,
             mois,
             annee) hs30
                   ON
                       hs30.idpersonnel = lp.id
                           AND hs30.annee = pe.annee
                           AND hs30.mois = pe.mois
         LEFT JOIN (
         SELECT
             idpersonnel,
             sum(gain) AS gain,
             mois,
             annee
         FROM
             PAIE_EDITION_LIBCOMPLET pe
         WHERE
             CODERUBRIQUE IN ('405', '4050')
         GROUP BY
             idpersonnel,
             mois,
             annee) hs50
                   ON
                       hs50.idpersonnel = lp.id
                           AND hs50.annee = pe.annee
                           AND hs50.mois = pe.mois
         LEFT JOIN (
         SELECT
             idpersonnel,
             sum(gain) AS gain,
             mois,
             annee
         FROM
             paie_edition pe
         WHERE
             regroupement = 6
         GROUP BY
             idpersonnel,
             mois,
             annee) congepayer
                   ON
                       congepayer.idpersonnel = lp.id
                           AND congepayer.annee = pe.annee
                           AND congepayer.mois = pe.mois
         LEFT JOIN (
         SELECT
             idpersonnel,
             sum(gain) AS gain,
             mois,
             annee
         FROM
             paie_edition pe
         WHERE
             regroupement = 7
         GROUP BY
             idpersonnel,
             mois,
             annee) preavis
                   ON
                       preavis.idpersonnel = lp.id
                           AND preavis.annee = pe.annee
                           AND preavis.mois = pe.mois
         LEFT JOIN (
         SELECT
             idpersonnel,
             sum(gain) AS gain,
             mois,
             annee
         FROM
             paie_edition pe
         WHERE
             regroupement = 8
         GROUP BY
             idpersonnel,
             mois,
             annee) indamdivfixe
                   ON
                       indamdivfixe.idpersonnel = lp.id
                           AND indamdivfixe.annee = pe.annee
                           AND indamdivfixe.mois = pe.mois
         LEFT JOIN (
         SELECT
             idpersonnel,
             sum(gain) AS gain,
             mois,
             annee
         FROM
             paie_edition pe
         WHERE
             regroupement = 9
         GROUP BY
             idpersonnel,
             mois,
             annee) totalgain
                   ON
                       totalgain.idpersonnel = lp.id
                           AND totalgain.annee = pe.annee
                           AND totalgain.mois = pe.mois
         LEFT JOIN (
         SELECT
             idpersonnel,
             sum(retenue) AS retenue,
             mois,
             annee
         FROM
             paie_edition pe
         WHERE
             regroupement = 10
         GROUP BY
             idpersonnel,
             mois,
             annee) cnaps
                   ON
                       cnaps.idpersonnel = lp.id
                           AND cnaps.annee = pe.annee
                           AND cnaps.mois = pe.mois
         LEFT JOIN (
         SELECT
             idpersonnel,
             sum(retenue) AS retenue,
             mois,
             annee
         FROM
             PAIE_EDITION_LIBCOMPLET pe
         WHERE
             CODERUBRIQUE IN ('700', '701')
         GROUP BY
             idpersonnel,
             mois,
             annee) cnaps_sans_complementaire
                   ON
                       cnaps_sans_complementaire.idpersonnel = lp.id
                           AND cnaps_sans_complementaire.annee = pe.annee
                           AND cnaps_sans_complementaire.mois = pe.mois
         LEFT JOIN (
         SELECT
             idpersonnel,
             sum(retenue) AS retenue,
             mois,
             annee
         FROM
             PAIE_EDITION_LIBCOMPLET pe
         WHERE
             CODERUBRIQUE IN ('705', '706')
         GROUP BY
             idpersonnel,
             mois,
             annee) cnaps_complementaire
                   ON
                       cnaps_complementaire.idpersonnel = lp.id
                           AND cnaps_complementaire.annee = pe.annee
                           AND cnaps_complementaire.mois = pe.mois
         LEFT JOIN (
         SELECT
             idpersonnel,
             sum(retenue) AS retenue,
             mois,
             annee
         FROM
             paie_edition pe
         WHERE
             regroupement = 11
         GROUP BY
             idpersonnel,
             mois,
             annee) ostie
                   ON
                       ostie.idpersonnel = lp.id
                           AND ostie.annee = pe.annee
                           AND ostie.mois = pe.mois
         LEFT JOIN (
         SELECT
             idpersonnel,
             sum(retenue) AS retenue,
             mois,
             annee
         FROM
             paie_edition pe
         WHERE
             regroupement = 12
         GROUP BY
             idpersonnel,
             mois,
             annee) netimposable
                   ON
                       netimposable.idpersonnel = lp.id
                           AND netimposable.annee = pe.annee
                           AND netimposable.mois = pe.mois
         LEFT JOIN (
         SELECT
             idpersonnel,
             sum(retenue) AS retenue,
             mois,
             annee
         FROM
             paie_edition pe
         WHERE
             regroupement = 13
         GROUP BY
             idpersonnel,
             mois,
             annee) netimposablearr
                   ON
                       netimposablearr.idpersonnel = lp.id
                           AND netimposablearr.annee = pe.annee
                           AND netimposablearr.mois = pe.mois
         LEFT JOIN (
         SELECT
             idpersonnel,
             sum(retenue) AS retenue,
             mois,
             annee
         FROM
             paie_edition pe
         WHERE
             regroupement = 14
         GROUP BY
             idpersonnel,
             mois,
             annee) irsa
                   ON
                       irsa.idpersonnel = lp.id
                           AND irsa.annee = pe.annee
                           AND irsa.mois = pe.mois
         LEFT JOIN (
         SELECT
             idpersonnel,
             sum(retenue) AS retenue,
             mois,
             annee
         FROM
             paie_edition pe
         WHERE
             regroupement = 15
         GROUP BY
             idpersonnel,
             mois,
             annee) irsanet
                   ON
                       irsanet.idpersonnel = lp.id
                           AND irsanet.annee = pe.annee
                           AND irsanet.mois = pe.mois
         LEFT JOIN (
         SELECT
             idpersonnel,
             sum(RETENUE) AS retenue,
             mois,
             annee
         FROM
             paie_edition pe
         WHERE
             regroupement = 16
         GROUP BY
             idpersonnel,
             mois,
             annee) avancesalaire
                   ON
                       avancesalaire.idpersonnel = lp.id
                           AND avancesalaire.annee = pe.annee
                           AND avancesalaire.mois = pe.mois
         LEFT JOIN (
         SELECT
             idpersonnel,
             sum(retenue) AS retenue,
             mois,
             annee
         FROM
             paie_edition pe
         WHERE
             regroupement = 17
         GROUP BY
             idpersonnel,
             mois,
             annee) avanceexcep
                   ON
                       avanceexcep.idpersonnel = lp.id
                           AND avanceexcep.annee = pe.annee
                           AND avanceexcep.mois = pe.mois
         LEFT JOIN (
         SELECT
             idpersonnel,
             sum(gain) AS gain,
             mois,
             annee
         FROM
             paie_edition pe
         WHERE
             regroupement = 18
         GROUP BY
             idpersonnel,
             mois,
             annee) netpayer
                   ON
                       netpayer.idpersonnel = lp.id
                           AND netpayer.annee = pe.annee
                           AND netpayer.mois = pe.mois
         LEFT JOIN (
         SELECT
             idpersonnel,
             sum(gain) AS gain,
             mois,
             annee
         FROM
             paie_edition pe
         WHERE
             regroupement = 19
         GROUP BY
             idpersonnel,
             mois,
             annee) netpayerarr
                   ON
                       netpayerarr.idpersonnel = lp.id
                           AND netpayerarr.annee = pe.annee
                           AND netpayerarr.mois = pe.mois
         LEFT JOIN (
         SELECT
             idpersonnel,
             sum(gain) AS gain,
             mois,
             annee
         FROM
             paie_edition pe
         WHERE
             regroupement = 20
         GROUP BY
             idpersonnel,
             mois,
             annee) allocation
                   ON
                       allocation.idpersonnel = lp.id
                           AND allocation.annee = pe.annee
                           AND allocation.mois = pe.mois
         LEFT JOIN (
         SELECT
             idpersonnel,
             sum(gain) AS gain,
             mois,
             annee
         FROM
             paie_edition pe
         WHERE
             regroupement = 100
         GROUP BY
             idpersonnel,
             mois,
             annee) net_a_payer
                   ON
                       net_a_payer.idpersonnel = lp.id
                           AND net_a_payer.annee = pe.annee
                           AND net_a_payer.mois = pe.mois
         LEFT JOIN (
         SELECT
             idpersonnel,
             sum(gain) AS gain,
             mois,
             annee
         FROM
             paie_edition pe
         WHERE
             (regroupement != 100
                 OR regroupement IS NULL)
         GROUP BY
             idpersonnel,
             mois,
             annee) salaire_brute
                   ON
                       salaire_brute.idpersonnel = lp.id
                           AND salaire_brute.annee = pe.annee
                           AND salaire_brute.mois = pe.mois
         LEFT JOIN (
         SELECT
             idpersonnel,
             sum(retenue) AS retenue,
             mois,
             annee
         FROM
             paie_edition pe
         GROUP BY
             idpersonnel,
             mois,
             annee) total_retenue
                   ON
                       total_retenue.idpersonnel = lp.id
                           AND total_retenue.annee = pe.annee
                           AND total_retenue.mois = pe.mois
         LEFT JOIN (
         SELECT
             idpersonnel,
             sum(gain) AS gain,
             mois,
             annee
         FROM
             paie_edition pe,
             paie_rubrique pr
         WHERE
             pr.id = pe.idelementpaie
           AND pr.imposable = 'I'
         GROUP BY
             idpersonnel,
             mois,
             annee) montant_brute_imposable
                   ON
                       montant_brute_imposable.idpersonnel = lp.id
                           AND montant_brute_imposable.annee = pe.annee
                           AND montant_brute_imposable.mois = pe.mois
         LEFT JOIN (
         SELECT
             idpersonnel,
             sum(gain) AS gain,
             mois,
             annee
         FROM
             PAIE_EDITION_LIBCOMPLET pe
         WHERE
             CODERUBRIQUE IN ('205')
         GROUP BY
             idpersonnel,
             mois,
             annee) indemnite_logement
                   ON
                       indemnite_logement.idpersonnel = lp.id
                           AND indemnite_logement.annee = pe.annee
                           AND indemnite_logement.mois = pe.mois
GROUP BY
    lp.ID,
    lpad(pe.MATRICULE, 5, '0'),
    pc.id,
    trim(TRAILING ' ' FROM lp.NOM),
    trim(TRAILING ' ' FROM lp.PRENOM),
    lp.NOM || ' ' || lp.PRENOM ,
    pf.DESCE,
    pf.id,
    pc.VAL ,
    ld.ID,
    ld.VAL,
    ls.ID,
    ls.CODE_SERVICE,
    ls.LIBELLE,
    pe.temporaire,
    nvl(SALAIREDEBASE.salairedebase, 0),
    nvl(heuresup.gain, 0),
    nvl(rappel.gain, 0),
    nvl(retenuabsc.retenue, 0),
    nvl(prime.gain, 0),
    nvl(net_a_payer.gain, 0),
    nvl(montant_brute_imposable.gain, 0),
    nvl(congepayer.gain, 0),
    nvl(preavis.gain, 0),
    nvl(hs30.gain, 0),
    nvl(hs50.gain, 0),
    nvl(indamdivfixe.gain, 0),
    nvl(totalgain.gain, 0),
    nvl(cnaps.retenue, 0),
    nvl(ostie.retenue, 0),
    nvl(salaire_brute.gain, 0),
    nvl(cnaps.retenue, 0),
    nvl(ostie.retenue, 0),
    nvl(irsa.retenue, 0),
    nvl(irsanet.retenue, 0),
    nvl(netimposable.retenue, 0),
    nvl(netimposablearr.retenue, 0),
    nvl(total_retenue.retenue, 0),
    nvl(avancesalaire.retenue, 0),
    nvl(avanceexcep.retenue, 0),
    nvl(cnaps_sans_complementaire.retenue, 0),
    nvl(cnaps_complementaire.retenue, 0),
    nvl(rappel.gain, 0),
    nvl(netpayer.gain, 0),
    nvl(netpayerarr.gain, 0),
    nvl(indemnite_logement.gain, 0),
    nvl(pe.tauxhoraire, 0),
    pip.MATRICULE,
    nvl(totalgain.gain,0),
    nvl(allocation.gain,0),
    173.33,
    nvl(poi.HEURENORMAL, 0),
    nvl(salaire.gain, 0),
    0,
    pip.nbenfant,
    pe.annee,
    pe.mois,
    pe.idedition;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SOCOBISMAINTENANCE0203" ("ID", "IDELEMENTINSPECTION", "IDMACHINE", "IDELEMENTINSPECTIONLIB", "IDMACHINELIB") AS
(
    SELECT
        eim.id,
        eim.idElementInspection as idElementInspection,
        eim.idMachine as idMachine,
        ei.val      AS idElementInspectionLib,
        m.libelle       AS idMachineLib
    FROM ElementInspectionMachine eim
             LEFT JOIN ElementInspection ei
                       ON eim.idElementInspection = ei.id
             LEFT JOIN AS_INGREDIENT_MAINTENANCE  m
                       ON eim.idMachine = m.id
);

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SOLDECONGEPRIS_PERS" ("ID", "PLUS", "CONGEPRIS", "NOMPERSONNEL", "MATRICULE", "IDDIRECTION") AS
SELECT
    lp.ID AS ID,
    CAST(sum(nvl(m.PLUS,0)) AS NUMBER(30, 2)) AS plus ,
    CAST(sum(nvl(m.MOINS ,0)) AS NUMBER(30, 2)) AS congepris ,
    lp.nom || ' ' || lp.prenom AS nomPersonnel,
    lp.matricule AS matricule,
    lp.iddirection AS idDirection
FROM MOUVEMENTABSENCE m
         LEFT JOIN LOG_PERSONNEL_V2 lp ON lp.ID = m.IDPERSONNEL
GROUP BY lp.NOM ,
         lp.PRENOM , lp.ID, lp.matricule, lp.IDDIRECTION;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SOLDECONGE_FIN_2023" ("IDPERSONNEL", "ID", "MATRICULE", "CONGE") AS
SELECT pip.id AS idpersonnel,
       cf.id,
       cf.matricule,
       cf.conge
FROM conge_fin_2023 cf
         LEFT JOIN paie_info_personnel pip ON pip.matricule = cf.matricule;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SOLDECONGE_PERS" ("PLUS", "MOINS", "SOLDE", "NOM", "PRENOM", "IDPERSONNEL") AS
SELECT
    CAST(sum(nvl(m.PLUS,0)) AS NUMBER(30, 2)) AS plus ,
    CAST(sum(nvl(m.MOINS ,0)) AS NUMBER(30, 2)) AS moins ,
    CAST(sum(nvl(m.PLUS,0)) - sum(nvl(m.MOINS ,0)) AS NUMBER(30, 2)) AS solde ,
    lp.NOM ,
    lp.PRENOM ,
    lp.ID AS IDPERSONNEL
FROM MOUVEMENTABSENCE m
         LEFT JOIN LOG_PERSONNEL lp ON lp.ID = m.IDPERSONNEL
where m.IDSOURCE='TYP000004'
GROUP BY lp.NOM ,
         lp.PRENOM , lp.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SOLDECONGE_PERS_CPL" ("DROIT", "CONGEPRIS", "SOLDE", "NOMPERSONNEL", "ID", "MATRICULE") AS
SELECT
    CAST(sum(nvl(m.PLUS,0)) AS NUMBER(30, 2)) AS droit ,
    CAST(sum(nvl(m.MOINS ,0)) AS NUMBER(30, 2)) AS congePris ,
    CAST(sum(nvl(m.PLUS,0)) - sum(nvl(m.MOINS ,0)) AS NUMBER(30, 2)) AS solde ,
    lp.NOM || ' ' || lp.PRENOM AS nomPersonnel,
    lp.ID ,
    pip.MATRICULE
FROM MOUVEMENTABSENCE m
         LEFT JOIN LOG_PERSONNEL lp ON lp.ID = m.IDPERSONNEL
         LEFT JOIN PAIE_INFO_PERSONNEL pip ON pip.id = lp.ID WHERE m.IDSOURCE ='TYP000004'
GROUP BY lp.NOM ,
         lp.PRENOM , lp.ID, pip.MATRICULE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SOLDEPERMISSION_PERS" ("IDPERSONNEL", "ANNEE", "PERMISSIONPRIS") AS
SELECT
    m.IDPERSONNEL ,
    m.ANNEE ,
    CAST(SUM(NVL(m.MOINS,0)) AS NUMBER(30, 2)) AS permissionPris
FROM
    MOUVEMENTABSENCE m
GROUP BY m.IDPERSONNEL , m.ANNEE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SOLDE_CONGE_PERS" ("ID", "CONGEDROIT", "CONGEPRIS", "CONGERESTE", "NOM", "PRENOM", "MATRICULE", "IDDEPARTEMENT", "IDDEPARTEMENTLIB") AS
SELECT
    pip.id,
    CAST(SUM(NVL(mvt.plus, 0)) AS NUMBER(30,2)) AS congedroit,
    CAST(SUM(NVL(mvt.moins, 0)) AS NUMBER(30,2)) AS congepris,
    CAST(
            SUM(NVL(mvt.plus, 0)) - SUM(NVL(mvt.moins, 0))
        AS NUMBER(30,2)
    ) AS congereste,
    log.NOM,
    log.PRENOM,
    pip.MATRICULE,
    pip.IDDEPARTEMENT,
    dep.VAL AS IDDEPARTEMENTLib
FROM PAIE_INFO_PERSONNEL pip
         LEFT JOIN MOUVEMENTABSENCE mvt
                   ON mvt.IDPERSONNEL = pip.id
                       AND mvt.IDTYPE = 'TYP000004'
         LEFT JOIN log_personnel_v log
                   ON log.id = pip.id
         LEFT JOIN DEPARTEMENT dep
                   ON dep.id = pip.IDDEPARTEMENT
GROUP BY
    pip.id,
    log.NOM,
    log.PRENOM,
    pip.MATRICULE,
    pip.IDDEPARTEMENT,
    dep.VAL;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SOLDE_FORMATION_SYNDICALE" ("ID", "ANNEE", "CONGEDROIT", "CONGEPRIS", "CONGERESTE", "NOM", "PRENOM", "MATRICULE", "IDDEPARTEMENT", "IDDEPARTEMENTLIB") AS
SELECT
    pip.id,
    NVL(mvt.ANNEE, EXTRACT(YEAR FROM SYSDATE)) AS annee,
    CAST(15 AS NUMBER(30,2)) AS congedroit,

    CAST(SUM(NVL(mvt.moins, 0)) AS NUMBER(30,2)) AS congepris,

    CAST(
            15 - SUM(NVL(mvt.moins, 0))
        AS NUMBER(30,2)
    ) AS congereste,

    log.NOM,
    log.PRENOM,
    pip.MATRICULE,
    pip.IDDEPARTEMENT,
    dep.VAL AS IDDEPARTEMENTLib

FROM PAIE_INFO_PERSONNEL pip

         LEFT JOIN MOUVEMENTABSENCE mvt
                   ON mvt.IDPERSONNEL = pip.id
                       AND mvt.IDTYPE = 'TYPCOL0005'

         LEFT JOIN log_personnel_v log
                   ON log.id = pip.id

         LEFT JOIN DEPARTEMENT dep
                   ON dep.id = pip.IDDEPARTEMENT

GROUP BY
    pip.id,
    mvt.ANNEE,
    log.NOM,
    log.PRENOM,
    pip.MATRICULE,
    pip.IDDEPARTEMENT,
    dep.VAL;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SORTIEENTREE" ("MVTSRC", "SORTIE") AS
SELECT 
m.mvtsrc,
sum(m.sortie) AS sortie
FROM MVTSTOCKFILLE m 
LEFT JOIN MVTSTOCK mp ON mp.id = m.IDMVTSTOCK
WHERE mp.etat = 11
GROUP BY m.mvtsrc;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SORTIEPRODUIT" ("IDPRODUIT", "QTESORTIE") AS
SELECT
idproduit,
CAST(sum(nvl(m.SORTIE,0)) AS NUMBER(15,2))  AS qteSortie
FROM MVTSTOCKFILLE m
LEFT JOIN MVTSTOCK mp ON mp.id = m.IDMVTSTOCK
WHERE mp.etat >= 11
GROUP BY idproduit;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SORTIEPRODUITPARORIGINE" ("IDPRODUIT", "IDOBJET", "QTESORTIE") AS
SELECT
idproduit,
idobjet,
CAST(sum(nvl(m.SORTIE,0)) AS NUMBER(15,2))  AS qteSortie
FROM MVTSTOCKFILLE m
LEFT JOIN MVTSTOCK mp ON mp.id = m.IDMVTSTOCK
WHERE mp.etat >= 11
GROUP BY idproduit, idobjet;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SORTIEPRODUITPARVENTE" ("IDPRODUIT", "IDOBJET", "QTESORTIE", "IDVENTE") AS
select spo."IDPRODUIT",spo."IDOBJET",spo."QTESORTIE", abc.IDVENTE from SORTIEPRODUITparorigine spo
    left join AS_BONDELIVRAISON_CLIENT abc on abc.id = spo.idobjet;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SORTIEPRODUITPARVENTEGRP" ("IDPRODUIT", "IDVENTE", "QTESORTIE") AS
select idproduit, IDVENTE, sum(qteSortie) as qteSortie from SORTIEPRODUITparvente
group by IDVENTE, idproduit;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SORTIESTOCKFILLE" ("IDPRODUIT", "IDVENTEDETAIL", "QTELIVREE") AS
SELECT 
m.IDPRODUIT ,
m.IDVENTEDETAIL ,
CAST(nvl(sum(m.SORTIE ),0)AS NUMBER(30,2)) AS  qtelivree
FROM MVTSTOCKFILLE m 
GROUP BY m.IDPRODUIT,m.IDVENTEDETAIL;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SOUSECRITURECOMPTEEXTRAIT" ("COMPTE", "COMPTE1", "COMPTE2", "COMPTE3", "COMPTE4", "DEBIT", "CREDIT", "ANNEE", "ETAT") AS
select
    compte,
    SUBSTR(COMPTE, 1, 1) as compte1,
    SUBSTR(COMPTE, 1, 2) as compte2,
    SUBSTR(COMPTE, 1, 3) as compte3,
    SUBSTR(COMPTE, 1, 4) as compte4,
    DEBIT,
    CREDIT,
    EXERCICE as annee,
    etat
from COMPTA_SOUS_ECRITURE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SOUSECRITUREGROUPCOMPTE" ("COMPTE", "DEBIT", "CREDIT", "EXERCICE", "ETAT") AS
select
    compte,
    sum(DEBIT) as DEBIT,
    sum(CREDIT) AS CREDIT,
    annee  as exercice,
    etat
from SousEcritureCompteExtrait group by compte, annee, etat;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SOUSECRITUREGROUPCOMPTE1" ("COMPTE1", "DEBIT", "CREDIT", "EXERCICE", "ETAT") AS
select
    compte1,
    sum(DEBIT) as DEBIT,
    sum(CREDIT) AS CREDIT,
    annee as exercice,
    etat
from SousEcritureCompteExtrait group by compte1, annee, etat;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SOUSECRITUREGROUPCOMPTE2" ("COMPTE2", "DEBIT", "CREDIT", "EXERCICE", "ETAT") AS
select
    compte2,
    sum(DEBIT) as DEBIT,
    sum(CREDIT) AS CREDIT,
    annee as exercice,
    etat
from SousEcritureCompteExtrait group by compte2, annee, etat;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SOUSECRITUREGROUPCOMPTE3" ("COMPTE3", "DEBIT", "CREDIT", "EXERCICE", "ETAT") AS
select
    compte3,
    sum(DEBIT) as DEBIT,
    sum(CREDIT) AS CREDIT,
    annee as exercice,
    etat
from SousEcritureCompteExtrait group by compte3, annee, etat;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SOUSECRITUREGROUPCOMPTE4" ("COMPTE4", "DEBIT", "CREDIT", "EXERCICE", "ETAT") AS
select
    compte4,
    sum(DEBIT) as DEBIT,
    sum(CREDIT) AS CREDIT,
    annee as exercice,
    etat
from SousEcritureCompteExtrait group by compte4, annee, etat;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SOUSECRITUREGROUPEBYUNIONVISE" ("COMPTE", "LIBELLE", "DEBIT", "CREDIT", "EXERCICE", "ETAT") AS
select t.compte,c.LIBELLE,t.DEBIT,t.CREDIT,t.exercice,t.etat from
    (
        select *
        from SousEcritureGroupCompte
        UNION
        select *
        from SousEcritureGroupCompte1
        UNION
        select *
        from SousEcritureGroupCompte2
        UNION
        select *
        from SousEcritureGroupCompte3
        UNION
        select *
        from SousEcritureGroupCompte4
    ) t join compta_compte c on c.COMPTE = t.compte order by compte desc;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SOUSECRITURENR" ("ID", "LIBELLEPIECE", "DEBIT", "CREDIT", "DATY", "IDCAISSE", "COMPTE") AS
SELECT
    cse.ID,
    cse.LIBELLEPIECE,
    cse.DEBIT,
    cse.CREDIT,
    cse.DATY,
    cai.ID as IDCAISSE,
    cse.COMPTE
FROM COMPTA_SOUS_ECRITURE cse
         LEFT JOIN COMPTA_ECRITURE ce ON ce.ID = cse.idmere
         LEFT join CAISSE cai on cai.COMPTE=cse.COMPTE
WHERE
    cse.ID NOT IN (
        SELECT rpf.idSousEcriture
        FROM RAPPROCHEMENTBC rpf join RAPPROCHEMENTBCMERE rp on rpf.idmere=rp.id
        WHERE rpf.idSousEcriture IS NOT NULL AND rp.ETAT>=11
    )
AND ce.JOURNAL in (select id from COMPTA_JOURNAL cj where cj.COMPTE like '512%') AND cse.COMPTE like '5%';

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SOUSECRITURENRMVT" ("ID", "LIBELLEPIECE", "DEBIT", "CREDIT", "DATY", "IDCAISSE", "COMPTE", "MOUVEMENT") AS
SELECT
    ID,
    LIBELLEPIECE,
    DEBIT,
    CREDIT,
    DATY,
    IDCAISSE,
    COMPTE,
    CASE
        WHEN DEBIT > 0 THEN 1
        WHEN CREDIT > 0 THEN 2
        ELSE 0
    END AS MOUVEMENT
FROM SOUSECRITURENR;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SOUSECRITURER" ("ID", "LIBELLEPIECE", "DEBIT", "CREDIT", "DATY", "IDCAISSE", "COMPTE") AS
SELECT
    cse.ID,
    cse.LIBELLEPIECE,
    cse.DEBIT,
    cse.CREDIT,
    cse.DATY,
    cai.ID as IDCAISSE,
    cse.COMPTE
FROM COMPTA_SOUS_ECRITURE cse
         LEFT JOIN COMPTA_ECRITURE ce ON ce.ID = cse.idmere
         LEFT join CAISSE cai on cai.COMPTE=cse.COMPTE
WHERE
    cse.ID IN (
        SELECT rpf.idSousEcriture
        FROM RAPPROCHEMENTBC rpf join RAPPROCHEMENTBCMERE rp on rpf.idmere=rp.id
        WHERE rpf.idSousEcriture IS NOT NULL AND rp.ETAT>=11
    )
  AND ce.JOURNAL = 'COMP000036' AND cse.COMPTE like '5%';

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SOUSECRITURERMVT" ("ID", "LIBELLEPIECE", "DEBIT", "CREDIT", "DATY", "IDCAISSE", "COMPTE", "MOUVEMENT") AS
SELECT
    ID,
    LIBELLEPIECE,
    DEBIT,
    CREDIT,
    DATY,
    IDCAISSE,
    COMPTE,
    CASE
        WHEN DEBIT > 0 THEN 1
        WHEN CREDIT > 0 THEN 2
        ELSE 0
        END AS MOUVEMENT
FROM SOUSECRITURER;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SOUS_FAMILLE_PRO_LIB" ("ID", "VAL", "DESCE", "IDFAMILLE", "IDFAMILLELIB") AS
(
       select
       sfp.ID,sfp.VAL,sfp.DESCE,sfp.IDFAMILLE,
       f.val as idfamillelib
       from
       sous_famille_pro sfp
       left join famille_professionnelle f on f.id=sfp.idfamille
);

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."STATFILLE" ("ID", "LIBELLE", "QTE", "MONTANT", "DATY", "IDCLIENT", "IDPROVINCE", "FAMILLE", "IDFAMILLE", "REMISE") AS
select IDPRODUIT as id, LIBELLE, sum(qte) as qte, sum(montant) as montant, DATY, IDCLIENT, IDPROVINCE, famille, IDFAMILLE, sum(remise) as remise from balance_client group by IDPRODUIT, LIBELLE, daty, IDCLIENT, IDPROVINCE, famille, IDFAMILLE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."STATMERE" ("ID", "FAMILLE", "QTE", "MONTANT", "DATY", "IDCLIENT", "IDPROVINCE") AS
select IDFAMILLE as id, famille, sum(qte) as qte, sum(montant) as montant, DATY, IDCLIENT, IDPROVINCE as idprovince  from balance_client group by IDFAMILLE, famille, daty, IDCLIENT,IDPROVINCE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."STAT_DEPENSE_CAT" ("DATY", "CATEGORIEINGREDIENT", "CATEGORIEINGREDIENTLIB", "MOISINT", "MOISSTRING", "ANNEE", "DEPENSE") AS
SELECT
	    ffc.daty,
	    ai.CATEGORIEINGREDIENT ,
	    cat.val AS CATEGORIEINGREDIENTLIB,
	    EXTRACT(MONTH FROM ffc.daty) as MOISINT,
	    TRIM(TO_CHAR(ffc.daty, 'Month', 'NLS_DATE_LANGUAGE=FRENCH')) AS MOISSTRING,
	    EXTRACT(YEAR FROM ffc.daty) as ANNEE,
	    CAST(sum(ffc.montant) / 1000000 AS NUMERIC(30,2)) AS depense
	FROM FACTUREFOURNISSEURFILLECPL  ffc
	         JOIN FACTUREFOURNISSEUR fc on fc.id = ffc.idfacturefournisseur and etat >= 11
	         JOIN AS_INGREDIENTS ai ON ffc.IDPRODUIT = ai.id
	         LEFT JOIN CATEGORIEINGREDIENT cat ON ai.CATEGORIEINGREDIENT  = cat.id
	GROUP BY
	    ai.CATEGORIEINGREDIENT,
	    ffc.daty,
	    cat.val
	ORDER BY ANNEE, MOISINT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."STAT_DEPENSE_MAT_PREM" ("ANNEE", "MOISINT", "MOIS", "ID", "DESIGNATION", "DEPENSE") AS
SELECT 
	EXTRACT (YEAR FROM f.DATY) AS annee,
	EXTRACT (MONTH FROM f.DATY) AS moisInt,
	TO_CHAR(f.DATY, 'Month', 'NLS_DATE_LANGUAGE=FRENCH') AS mois,
	ff.idproduit AS id,
	ai.LIBELLE AS designation,
	CAST(nvl(sum(ff.qte*ff.pu),0) AS NUMBER(30,5))  AS depense
FROM 
FACTUREFOURNISSEURFILLE ff
LEFT JOIN FACTUREFOURNISSEUR f 
ON f.ID = ff.IDFACTUREFOURNISSEUR 
LEFT JOIN AS_INGREDIENTS ai 
ON ai.ID = ff.idproduit
WHERE f.etat >=11
GROUP BY 
	ff.idproduit, 
	ai.LIBELLE,
	EXTRACT (YEAR FROM f.DATY),
	EXTRACT (MONTH FROM f.DATY),
	TO_CHAR(f.DATY, 'Month', 'NLS_DATE_LANGUAGE=FRENCH')
ORDER BY EXTRACT (MONTH FROM f.DATY) asc;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."STOCKDEPENSEOFFAB" ("IDOBJET", "IDPRODUIT", "ENTREE", "SORTIE", "PU", "MONTANENTREE", "MONTANTSORTIE", "IDMERE", "ID", "CATEGORIEINGREDIENT", "CATEGORIEINGREDIENTLIB") AS
select idmere as idobjet,sdf.IDPRODUIT,cast(sum(sdf.entree) as number(30,5)) as entree,cast(sum(sdf.sortie) as number(30,5)) as sortie, cast(avg(sdf.pu) as number(30,5)) as pu,
                                                                                                                                             sum(montantentree) as montanentree, sum(montantsortie) as montantsortie,idmere,'-' as id, sdf.categorieingredient, sdf.categorieingredientlib
                                                                                                                                             from STOCKETDEPENSEFAB sdf
                                                                                                                                             group by sdf.IDPRODUIT,idmere, sdf.categorieingredient, sdf.categorieingredientlib;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."STOCKDEPENSEOFFILLEFAB" ("IDOBJET", "IDPRODUIT", "ENTREE", "SORTIE", "PU", "MONTANENTREE", "MONTANTSORTIE", "IDMERE", "ID", "CATEGORIEINGREDIENT", "CATEGORIEINGREDIENTLIB") AS
select id as idobjet,sdf.IDPRODUIT,cast(sum(sdf.entree) as number(30,5)) as entree,cast(sum(sdf.sortie) as number(30,5)) as sortie, cast(avg(sdf.pu) as number(30,5)) as pu,
       sum(montantentree) as montanentree, sum(montantsortie) as montantsortie,idmere,'-' as id, sdf.categorieingredient, sdf.categorieingredientlib
from STOCKETDEPENSEFAB sdf
group by sdf.IDPRODUIT,id, sdf.categorieingredient, sdf.categorieingredientlib,idmere;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."STOCKETDEPENSEFAB" ("IDOBJET", "IDPRODUIT", "ENTREE", "SORTIE", "PU", "MONTANTENTREE", "MONTANTSORTIE", "IDMERE", "ID", "CATEGORIEINGREDIENT", "CATEGORIEINGREDIENTLIB") AS
select idobjet,IDPRODUIT,cast(entree as number(30,5)) as entree,cast(sortie as number(30,5)) as sortie,cast(pu as number(30,5)) as pu,
       cast(montantentree as number(30,5)) as montantentree,cast(montantsortie as number(30,5)) as montantsortie,IDMERE,id, CATEGORIEINGREDIENT,CATEGORIEINGREDIENTLIB
from STOCKETDEPENSEFABNC;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."STOCKETDEPENSEFABNC" ("IDOBJET", "IDPRODUIT", "ENTREE", "SORTIE", "PU", "MONTANTENTREE", "MONTANTSORTIE", "IDMERE", "ID", "CATEGORIEINGREDIENT", "CATEGORIEINGREDIENTLIB") AS
select mvt.IDOBJET, fille.IDPRODUIT,cast(sum(ENTREE) as number(15,2)) as entree, cast(sum(SORTIE) as number(15,2)) as sortie, cast(avg(fille.pu) as number(30,2)) as pu,
cast(nvl(avg(fille.pu)*sum(entree),0) as number(30,3)) as montantentree,cast(nvl(avg(fille.pu)*sum(sortie),0) as number(30,3)) as montantsortie,ofille.IDMERE,ofille.id, cat.id AS CATEGORIEINGREDIENT, cat.val AS CATEGORIEINGREDIENTLIB
from MVTSTOCKFILLE fille
left join MvtStockLib mvt on fille.IDMVTSTOCK=mvt.ID
left join FABRICATION fab on mvt.IDOBJET=fab.ID
left join OFFILLE ofille on fab.IDOFFILLE=ofille.ID
left join AS_INGREDIENTS ai on fille.IDPRODUIT=ai.id
LEFT JOIN CATEGORIEINGREDIENT cat ON cat.id = ai.CATEGORIEINGREDIENT 
where mvt.ETAT>=11  and ai.COMPOSE=0
group by fille.IDPRODUIT,mvt.IDOBJET,ofille.IDMERE,ofille.id,ai.COMPOSE, cat.id, cat.val
union all
select c.IDFABRICATION as idobjet,c.IDINGREDIENTS as IDPRODUIT,cast(0 as number(15,2)) as entree,cast(1 as number (15,2)) as sortie,cast(c.montant as number(30,2)) as pu,cast(0 as number(30,3)) as montantentree,cast(nvl(sum(c.montant),0) as number(30,3)) as montantsortie
,ofile.IDMERE,ofile.id, cat.id AS CATEGORIEINGREDIENT, cat.val AS CATEGORIEINGREDIENTLIB
from chargemontant c
left join fabrication fabb on c.IDFABRICATION=fabb.id
left join OFFILLE ofile on fabb.IDOFFILLE=ofile.ID
LEFT JOIN AS_INGREDIENTS ai ON c.IDINGREDIENTS = ai.id
LEFT JOIN CATEGORIEINGREDIENT cat ON cat.id = ai.CATEGORIEINGREDIENT 
where c.etat>=11 group by c.IDFABRICATION, c.IDINGREDIENTS,ofile.IDMERE,ofile.id, cat.id, cat.val,c.montant
UNION all
select 
    rsfab.IDFABRICATION as idobjet,
    'IG000364' as IDPRODUIT,
    cast(0 as number(15,2)) as entree,
    CAST(
        NVL(
            CASE 
                WHEN h.TEMPORAIRE = 0 THEN h.MN + h.JF + h.HD + h.IF + h.HEURENORMALE
                ELSE h.HS + h.MN + h.JF + h.HD + h.IF
            END,
        0) AS NUMBER(15,2)
    ) AS sortie,
    cast(rsfab.TAUXHORAIRE as number(30,2)) as pu,
    cast(0 as number(30,3)) as montantentree,
    cast(nvl(h.MONTANT, 0) as number(30,3)) as montantsortie,
    off.IDMERE,
    off.ID,
    'CATING000001' as CATEGORIEINGREDIENT,
    'Charge personnelle' as CATEGORIEINGREDIENTLIB
from HEURESUPFABRICATION h
left join RESSOURCEPARFABRICATIONCOMPLET rsfab ON rsfab.IDRESSOURCE = h.IDRESSPARFAB
left join FABRICATION f on rsfab.idfabrication = f.ID
left join OFFILLE off on f.IDOFFILLE = off.ID
where h.ETAT >= 11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."STOCKETDEPENSEFABTHE" ("IDOBJET", "IDPRODUIT", "DESIGNATION", "ENTREE", "SORTIE", "PU", "MONTANTENTREE", "MONTANTSORTIE", "IDMERE", "ID", "QTETH", "PUTH", "MONTTH", "CATEGORIEINGREDIENT") AS
SELECT
    sed.IDOBJET,
    sed.IDPRODUIT,
    ai.libelle AS designation,
    cast(sed.ENTREE as number(30,5)) as entree ,
    cast(sed.SORTIE as number(30,5)) as sortie,
    CAST(
            CASE
                WHEN nvl(sed."PU",0) = 0 THEN recFab.pu
                ELSE nvl(sed."PU",0)
                END
        as number(30,2)) AS PU,
    cast(sed.MONTANTENTREE as number(30,5)) as MONTANTENTREE,
    CAST(
            CASE
                WHEN nvl(sed."PU",0) = 0 THEN recFab.pu * sed.SORTIE
                ELSE nvl(sed."PU",0) * sed.SORTIE
                END
        as number(30,2)) as MONTANTSORTIE ,
    sed.IDMERE,
    sed.ID,
    CAST(nvl(recFab.QUANTITE, 0) AS NUMBER(30,
                                           10)) AS qteTh,
    CAST(nvl(recFab.QTEAV, sed.pu) AS NUMBER(30,
                                             5)) AS puth,
    CAST(nvl(recFab.QUANTITE, 0)* nvl(recFab.QTEAV, 0) AS NUMBER(30,
                                                                 5)) AS montTh,
    recFab.CATEGORIEINGREDIENT
FROM
    stockEtDepenseFab sed
        FULL OUTER JOIN as_recFabLibGroupe recFab
                        ON
                            sed.IDOBJET = recFab.IDPRODUITS
                                AND sed.IDPRODUIT = recFab.IDINGREDIENTS 
        LEFT JOIN as_ingredients ai ON ai.id = sed.idproduit;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."STOCKETDEPENSEFABTHECAT" ("IDOBJET", "IDPRODUIT", "ENTREE", "SORTIE", "PU", "MONTANTENTREE", "MONTANTSORTIE", "IDMERE", "ID", "QTETH", "PUTH", "MONTTH", "CATEGORIEINGREDIENT", "IDCATEGORIEINGREDIENT") AS
select std.IDOBJET,std.IDPRODUIT,std.ENTREE,std.SORTIE,std.PU,std.MONTANTENTREE,std.MONTANTSORTIE,std.IDMERE,std.ID,std.QTETH,std.PUTH,std.MONTTH,cat.VAL as CATEGORIEINGREDIENT, ing.CATEGORIEINGREDIENT IDCATEGORIEINGREDIENT from stockEtDepenseFabThe std
                                                                                                                                                                                                                                         left join AS_INGREDIENTS ing on std.IDPRODUIT=ing.id
                                                                                                                                                                                                                                         left join CATEGORIEINGREDIENT cat on ing.CATEGORIEINGREDIENT=cat.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."STOCKETDEPENSEOFFABTHE" ("IDOBJET", "IDPRODUIT", "DESIGNATION", "ENTREE", "SORTIE", "PU", "MONTANENTREE", "MONTANTSORTIE", "IDMERE", "ID", "QTETH", "PUTH", "MONTTH", "CATEGORIEINGREDIENT", "CATEGORIEINGREDIENTLIB") AS
select
    sed."IDOBJET",
    sed."IDPRODUIT",
    nvl(recFab.LIBINGREDIENTS,ai.LIBELLE) AS designation,
    CAST(sed."ENTREE" as number(30,5)) AS ENTREE ,
    CAST(sed."SORTIE" as number(30,5))  AS SORTIE ,
    CAST(
            CASE
                WHEN nvl(sed."PU",0) = 0 THEN recFab.pu
                ELSE nvl(sed."PU",0)
                END
        as number(30,2)) AS PU,
    CAST(sed."MONTANENTREE" as number(30,5)) AS MONTANENTREE ,
    CAST(
            CASE
                WHEN nvl(sed."PU",0) = 0 THEN recFab.pu * sed."SORTIE"
                ELSE nvl(sed."PU",0) * sed."SORTIE"
                END
        as number(30,2))  AS MONTANTSORTIE,
    sed."IDMERE",
    sed."ID",
    cast(nvl(recFab.QUANTITE,0) as number(30,10)) as qteTh,
    cast(nvl(recFab.QTEAV,sed.pu) as number(30,5)) as puth,
    cast(nvl(recFab.QUANTITE,0)*nvl(recFab.QTEAV,0) as number(30,5)) as montTh,
    sed.CATEGORIEINGREDIENT,
    sed.CATEGORIEINGREDIENTLIB
from stockDepenseOfFab sed full
                               outer join AS_RECFOFABLIBGROUPE recFab
                                          on sed.IDOBJET=recFab.IDPRODUITS and sed.IDPRODUIT=recFab.IDINGREDIENTS
                           LEFT JOIN AS_INGREDIENTS ai ON ai.ID = sed.IDOBJET OR ai.ID =  sed.IDPRODUIT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."STOCKETDEPENSEOFFABTHECAT" ("IDOBJET", "IDPRODUIT", "ENTREE", "SORTIE", "PU", "MONTANENTREE", "MONTANTSORTIE", "IDMERE", "ID", "QTETH", "PUTH", "MONTTH", "CATEGORIEINGREDIENT", "IDCATEGORIEINGREDIENT") AS
SELECT
    std."IDOBJET",
    std."IDPRODUIT",
    std."ENTREE",
    std."SORTIE",
    std."PU",
    std."MONTANENTREE",
    std."MONTANTSORTIE",
    std."IDMERE",
    std."ID",
    std."QTETH",
    std."PUTH",
    std."MONTTH",
    cat.VAL as CATEGORIEINGREDIENT,
    cat.ID AS idcategorieingredient
from stockEtDepenseOfFabThe std
         left join AS_INGREDIENTS ing on std.IDPRODUIT=ing.id
         left join CATEGORIEINGREDIENT cat on ing.CATEGORIEINGREDIENT=cat.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."STOCKETDEPENSEOFFILLEFABTHE" ("IDOBJET", "IDPRODUIT", "DESIGNATION", "ENTREE", "SORTIE", "PU", "MONTANENTREE", "MONTANTSORTIE", "IDMERE", "ID", "QTETH", "PUTH", "MONTTH", "CATEGORIEINGREDIENT", "CATEGORIEINGREDIENTLIB") AS
select
    sed."IDOBJET",
    sed."IDPRODUIT",
    nvl(recFab.LIBINGREDIENTS,ai.LIBELLE) AS designation,
    CAST(sed."ENTREE" as number(30,5)) AS ENTREE ,
    CAST(sed."SORTIE" as number(30,5))  AS SORTIE ,
    CAST(
            CASE
                WHEN nvl(sed."PU",0) = 0 THEN recFab.pu
                ELSE nvl(sed."PU",0)
                END
        as number(30,2)) AS PU,
    CAST(sed."MONTANENTREE" as number(30,2)) AS MONTANENTREE ,
    CAST(
            CASE
                WHEN nvl(sed."PU",0) = 0 THEN recFab.pu * sed."SORTIE"
                ELSE nvl(sed."PU",0) * sed."SORTIE"
                END
        as number(30,2))  AS MONTANTSORTIE,
    sed."IDMERE",
    sed."ID",
    cast(nvl(recFab.QUANTITE,0) as number(30,10)) as qteTh,
    cast(nvl(recFab.QTEAV,sed.pu) as number(30,2)) as puth,
    cast(nvl(recFab.QUANTITE,0)*nvl(recFab.QTEAV,0) as number(30,2)) as montTh,
    sed.CATEGORIEINGREDIENT,
    sed.CATEGORIEINGREDIENTLIB
from STOCKDEPENSEOFFILLEFAB sed full
                                    outer join AS_RECFOFABLIBGROUPE recFab
                                               on sed.IDMERE =recFab.IDPRODUITS and sed.IDPRODUIT=recFab.IDINGREDIENTS
                                LEFT JOIN AS_INGREDIENTS ai ON ai.ID = sed.IDOBJET OR ai.ID =  sed.IDPRODUIT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."STOCKETDEPENSEOFFILLETHECAT" ("IDOBJET", "IDPRODUIT", "ENTREE", "SORTIE", "PU", "MONTANENTREE", "MONTANTSORTIE", "IDMERE", "ID", "QTETH", "PUTH", "MONTTH", "CATEGORIEINGREDIENT", "IDCATEGORIEINGREDIENT") AS
SELECT
    std."IDOBJET",
    std."IDPRODUIT",
    std."ENTREE",
    std."SORTIE",
    std."PU",
    std."MONTANENTREE",
    std."MONTANTSORTIE",
    std."IDMERE",
    std."ID",
    std."QTETH",
    std."PUTH",
    std."MONTTH",
    cat.VAL as CATEGORIEINGREDIENT,
    cat.ID AS idcategorieingredient
from STOCKETDEPENSEOFFILLEFABTHE std
         left join AS_INGREDIENTS ing on std.IDPRODUIT=ing.id
         left join CATEGORIEINGREDIENT cat on ing.CATEGORIEINGREDIENT=cat.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."STOCKETDEPFABTHECATGROUPE" ("IDOBJET", "CATEGORIEINGREDIENT", "IDCATEGORIEINGREDIENT", "MONTANTSORTIE", "MONTTH", "ECART") AS
select st.IDOBJET ,st.CATEGORIEINGREDIENT,st.idcategorieingredient,cast(sum(montantsortie) as number(30,2)) as montantSortie,cast(sum(montth) as number(30,2)) as montth, cast(sum(montth)-sum(montantsortie) as number(30,2)) as ecart
  from stockEtDepenseFabTheCat st
  group by st.idobjet,st.CATEGORIEINGREDIENT,st.idcategorieingredient;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."STOCKETDEPOFFABTHECATGROUPE" ("IDMERE", "CATEGORIEINGREDIENT", "IDCATEGORIEINGREDIENT", "MONTANTSORTIE", "MONTTH", "ECART") AS
select
    st.idmere,
    st.CATEGORIEINGREDIENT,
    st.idcategorieingredient,
    cast(sum(montantsortie) as number(30,2)) as montantSortie,
    cast(sum(montth) as number(30,2)) as montth,
    cast(sum(montth)-sum(montantsortie) as number(30,2)) as ecart
from stockEtDepenseOfFabTheCat st
group by st.idmere,st.CATEGORIEINGREDIENT, st.idcategorieingredient;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."STOCKETDEPOFFILLETHECATGROUPE" ("IDMERE", "CATEGORIEINGREDIENT", "IDCATEGORIEINGREDIENT", "MONTANTSORTIE", "MONTTH", "ECART") AS
select
    st.IDOBJET AS idmere,
    st.CATEGORIEINGREDIENT,
    st.idcategorieingredient,
    cast(sum(montantsortie) as number(30,2)) as montantSortie,
    cast(sum(montth) as number(30,2)) as montth,
    cast(sum(montth)-sum(montantsortie) as number(30,2)) as ecart
from STOCKETDEPENSEOFFILLETHECAT st
group by st.IDOBJET ,st.CATEGORIEINGREDIENT, st.idcategorieingredient;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."STOCK_ENGAGE_FILLE_GP" ("IDPRODUIT", "SORTIE") AS
select IDPRODUIT, sum(SORTIE) as sortie
from STOCK_ENGAGE_FILLE
group by IDPRODUIT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."STOCK_ENGAGE_FILLE_GP_MAG" ("IDMAGASIN", "IDPRODUIT", "SORTIE") AS
select IDMAGASIN,IDPRODUIT, sum(SORTIE) as sortie
from STOCK_ENGAGE_FILLE stf join STOCK_ENGAGE st on st.id=stf.IDMVTSTOCK
group by IDPRODUIT,IDMAGASIN;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."ST_ARTICLELIB_PU" ("ID", "CODE", "DESIGNATION", "SEUIL", "UNITE", "PRESENTATION", "TYPE", "GROUPEE", "SOUSGROUPE", "CLASSEE", "CODEMNEMONIQUE", "PUGROS", "PUDONATION") AS
select ar.id,
       ar.code,
       ar.designation,
       ar.seuil,
       uni.val as unite,
       ar.presentation,
       ta.VAL        as type,
       ga.VAL        as groupee,
       sga.VAL       as sousgroupe,
       ar.classee,
       ar.codemnemonique,
       ar.PUGROS,
       ar.PUDONATION
from ST_ARTICLE ar
         left join ST_TYPE_ARTICLE ta on ta.id = ar.TYPE
         left join ST_GROUPE_ARTICLE ga on ga.id = ar.GROUPEE
         left join ST_SOUSGROUPE_ARTICLE sga on sga.id = ar.SOUSGROUPE
         left join st_unite uni on ar.UNITE = uni.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."ST_ARTICLE_EQUIVALENCE" ("ID", "CODE", "DESIGNATION", "SEUIL", "UNITE", "PRESENTATION", "TYPE", "GROUPEE", "SOUSGROUPE", "CLASSEE", "CODEMNEMONIQUE", "PUGROS", "PUDONATION", "UNITEEQUIVALENCE", "QTEEQUIVALENCE") AS
SELECT sa."ID",
       sa."CODE",
       sa."DESIGNATION",
       sa."SEUIL",
       sa."UNITE",
       sa."PRESENTATION",
       sa."TYPE",
       sa."GROUPEE",
       sa."SOUSGROUPE",
       sa."CLASSEE",
       sa."CODEMNEMONIQUE",
       sa."PUGROS",
       sa."PUDONATION",
       ''                         AS uniteEquivalence,
       CAST(0.0 AS NUMBER(38, 2)) as qteEquivalence
FROM ST_ARTICLE sa;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."ST_INGREDIENTSAUTO" ("ID", "LIBELLE", "SEUIL", "UNITE", "QUANTITEPARPACK", "PU", "ACTIF", "PHOTO", "CALORIE", "DURRE", "COMPOSE", "CATEGORIEINGREDIENT", "IDFOURNISSEUR", "DATY", "QTELIMITE", "PV", "LIBELLEVENTE", "SEUILMIN", "SEUILMAX", "PUACHATUSD", "PUACHATEURO", "PUACHATAUTREDEVISE", "PUVENTEUSD", "PUVENTEEURO", "PUVENTEAUTREDEVISE", "ISVENTE", "ISACHAT", "COMPTE_VENTE", "COMPTE_ACHAT", "COMPTE", "UNITELIB") AS
SELECT
    ai.ID,ai.LIBELLE,CAST(ai.SEUIL AS NUMBER(10,5)) AS SEUIL ,au.val AS UNITE,CAST(ai.QUANTITEPARPACK AS NUMBER(10,5)) AS QUANTITEPARPACK,CAST(ai.PU AS NUMBER(30,5)) AS PU,ai.ACTIF,ai.PHOTO,ai.CALORIE,ai.DURRE,ai.COMPOSE,ai.CATEGORIEINGREDIENT,ai.IDFOURNISSEUR,ai.DATY,CAST(ai.QTELIMITE AS NUMBER(30,5)) AS QTELIMITE,CAST(ai.PV AS NUMBER(30,5)) AS PV,ai.LIBELLEVENTE,CAST(COALESCE(ai.SEUILMIN,0) AS NUMBER(30,5)) AS SEUILMIN,CAST(COALESCE(ai.SEUILMAX,0) AS NUMBER(30,5)) AS SEUILMAX,CAST(COALESCE(ai.PUACHATUSD,0) AS NUMBER(30,5)) AS PUACHATUSD,CAST(COALESCE(ai.PUACHATEURO,0) AS NUMBER(30,5)) AS PUACHATEURO,CAST(COALESCE(ai.PUACHATAUTREDEVISE,0) AS NUMBER(30,5)) AS PUACHATAUTREDEVISE,CAST(COALESCE(ai.PUVENTEUSD,0) AS NUMBER(30,5)) AS PUVENTEUSD,CAST(COALESCE(ai.PUVENTEEURO,0) AS NUMBER(30,5)) AS PUVENTEEURO,CAST(COALESCE(ai.PUVENTEAUTREDEVISE,0) AS NUMBER(30,5)) AS PUVENTEAUTREDEVISE,ai.ISVENTE,ai.ISACHAT,ai.COMPTE_VENTE,ai.COMPTE_ACHAT,
    CASE
        WHEN ai.COMPTE_VENTE IS NOT NULL THEN ai.COMPTE_VENTE
        ELSE ai.COMPTE_ACHAT
    END AS compte,
    au.VAL AS UNITELIB
FROM AS_INGREDIENTS ai
LEFT JOIN AS_UNITE au  ON au.id = ai.UNITE 
 WHERE ai.actif = 1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."ST_INGREDIENTSAUTOACHAT_CPL" ("ID", "LIBELLE", "SEUIL", "UNITE", "QUANTITEPARPACK", "PU", "ACTIF", "PHOTO", "CALORIE", "DURRE", "COMPOSE", "CATEGORIEINGREDIENT", "IDFOURNISSEUR", "DATY", "QTELIMITE", "PV", "LIBELLEVENTE", "SEUILMIN", "SEUILMAX", "PUACHATUSD", "PUACHATEURO", "PUACHATAUTREDEVISE", "PUVENTEUSD", "PUVENTEEURO", "PUVENTEAUTREDEVISE", "ISVENTE", "ISACHAT", "COMPTE_VENTE", "COMPTE_ACHAT", "COMPTE", "TAUX") AS
select st."ID",st."LIBELLE",st."SEUIL",st."UNITE",st."QUANTITEPARPACK",st."PU",st."ACTIF",st."PHOTO",st."CALORIE",st."DURRE",st."COMPOSE",st."CATEGORIEINGREDIENT",st."IDFOURNISSEUR",st."DATY",st."QTELIMITE",st."PV",st."LIBELLEVENTE",st."SEUILMIN",st."SEUILMAX",st."PUACHATUSD",st."PUACHATEURO",st."PUACHATAUTREDEVISE",st."PUVENTEUSD",st."PUVENTEEURO",st."PUVENTEAUTREDEVISE",st."ISVENTE",st."ISACHAT",st."COMPTE_VENTE",st."COMPTE_ACHAT",st."COMPTE", 1 as taux from ST_INGREDIENTSAUTO st;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."ST_INGREDIENTSAUTOACHAT_EUR" ("ID", "LIBELLE", "SEUIL", "UNITE", "QUANTITEPARPACK", "PU", "ACTIF", "PHOTO", "CALORIE", "DURRE", "COMPOSE", "CATEGORIEINGREDIENT", "IDFOURNISSEUR", "DATY", "QTELIMITE", "PV", "LIBELLEVENTE", "SEUILMIN", "SEUILMAX", "PUACHATUSD", "PUACHATEURO", "PUACHATAUTREDEVISE", "PUVENTEUSD", "PUVENTEEURO", "PUVENTEAUTREDEVISE", "ISVENTE", "ISACHAT", "COMPTE_VENTE", "COMPTE_ACHAT", "TAUX", "IDDEVISE", "COMPTE") AS
SELECT ai.ID,
       ai.LIBELLE,
       ai.SEUIL,
       ai.UNITE,
       ai.QUANTITEPARPACK,
       ai.PU,
       ai.ACTIF,
       ai.PHOTO,
       ai.CALORIE,
       ai.DURRE,
       ai.COMPOSE,
       ai.CATEGORIEINGREDIENT,
       ai.IDFOURNISSEUR,
       ai.DATY,
       ai.QTELIMITE,
       ai.PV,
       ai.LIBELLEVENTE,
       ai.SEUILMIN,
       ai.SEUILMAX,
       ai.PUACHATUSD,
       ai.PUACHATEURO,
       ai.PUACHATAUTREDEVISE,
       ai.PUVENTEUSD,
       ai.PUVENTEEURO,
       ai.PUVENTEAUTREDEVISE,
       ai.ISVENTE,
       ai.ISACHAT,
       ai.COMPTE_VENTE,
       ai.COMPTE_ACHAT,
       ch.TAUX,
       'EUR'           as iddevise,
       ai.COMPTE_VENTE AS compte
FROM TAUXDECHANGE_MAXDATY ch,
     AS_INGREDIENTS ai
where ch.IDDEVISE = 'EUR';

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."ST_INGREDIENTSAUTOACHAT_USD" ("ID", "LIBELLE", "SEUIL", "UNITE", "QUANTITEPARPACK", "PU", "ACTIF", "PHOTO", "CALORIE", "DURRE", "COMPOSE", "CATEGORIEINGREDIENT", "IDFOURNISSEUR", "DATY", "QTELIMITE", "PV", "LIBELLEVENTE", "SEUILMIN", "SEUILMAX", "PUACHATUSD", "PUACHATEURO", "PUACHATAUTREDEVISE", "PUVENTEUSD", "PUVENTEEURO", "PUVENTEAUTREDEVISE", "ISVENTE", "ISACHAT", "COMPTE_VENTE", "COMPTE_ACHAT", "TAUX", "IDDEVISE", "COMPTE") AS
SELECT ai.ID,
       ai.LIBELLE,
       ai.SEUIL,
       ai.UNITE,
       ai.QUANTITEPARPACK,
       ai.PU,
       ai.ACTIF,
       ai.PHOTO,
       ai.CALORIE,
       ai.DURRE,
       ai.COMPOSE,
       ai.CATEGORIEINGREDIENT,
       ai.IDFOURNISSEUR,
       ai.DATY,
       ai.QTELIMITE,
       ai.PV,
       ai.LIBELLEVENTE,
       ai.SEUILMIN,
       ai.SEUILMAX,
       ai.PUACHATUSD,
       ai.PUACHATEURO,
       ai.PUACHATAUTREDEVISE,
       ai.PUVENTEUSD,
       ai.PUVENTEEURO,
       ai.PUVENTEAUTREDEVISE,
       ai.ISVENTE,
       ai.ISACHAT,
       ai.COMPTE_VENTE,
       ai.COMPTE_ACHAT,
       ch.TAUX,
       'USD'           as iddevise,
       ai.COMPTE_VENTE AS compte
FROM TAUXDECHANGE_MAXDATY ch,
     AS_INGREDIENTS ai
where ch.IDDEVISE = 'USD';

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."ST_INGREDIENTSAUTOCHAMBRE" ("ID", "LIBELLE", "SEUIL", "UNITE", "QUANTITEPARPACK", "PU", "ACTIF", "PHOTO", "CALORIE", "DURRE", "COMPOSE", "CATEGORIEINGREDIENT", "IDFOURNISSEUR", "DATY", "QTELIMITE", "PV", "LIBELLEVENTE", "SEUILMIN", "COMPTE") AS
SELECT ai."ID",ai."LIBELLE",ai."SEUIL",ai."UNITE",ai."QUANTITEPARPACK",ai."PU",ai."ACTIF",ai."PHOTO",ai."CALORIE",ai."DURRE",ai."COMPOSE",ai."CATEGORIEINGREDIENT",ai."IDFOURNISSEUR",ai."DATY",ai."QTELIMITE",ai."PV",ai."LIBELLEVENTE",ai."SEUILMIN", ai.COMPTE_VENTE AS compte
FROM AS_INGREDIENTS ai where ai.pv>0 and ai.CATEGORIEINGREDIENT = 'CAT001';

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."ST_INGREDIENTSAUTOSERVICE" ("ID", "LIBELLE", "SEUIL", "UNITE", "QUANTITEPARPACK", "PU", "ACTIF", "PHOTO", "CALORIE", "DURRE", "COMPOSE", "CATEGORIEINGREDIENT", "IDFOURNISSEUR", "DATY", "QTELIMITE", "PV", "LIBELLEVENTE", "SEUILMIN", "SEUILMAX", "PUACHATUSD", "PUACHATEURO", "PUACHATAUTREDEVISE", "PUVENTEUSD", "PUVENTEEURO", "PUVENTEAUTREDEVISE", "ISVENTE", "ISACHAT", "COMPTE_VENTE", "COMPTE_ACHAT", "COMPTE") AS
SELECT
    ai."ID",ai."LIBELLE",ai."SEUIL",ai."UNITE",ai."QUANTITEPARPACK",ai."PU",ai."ACTIF",ai."PHOTO",ai."CALORIE",ai."DURRE",ai."COMPOSE",ai."CATEGORIEINGREDIENT",ai."IDFOURNISSEUR",ai."DATY",ai."QTELIMITE",ai."PV",ai."LIBELLEVENTE",ai."SEUILMIN",ai."SEUILMAX",ai."PUACHATUSD",ai."PUACHATEURO",ai."PUACHATAUTREDEVISE",ai."PUVENTEUSD",ai."PUVENTEEURO",ai."PUVENTEAUTREDEVISE",ai."ISVENTE",ai."ISACHAT",ai."COMPTE_VENTE",ai."COMPTE_ACHAT",
    CASE
        WHEN ai.COMPTE_VENTE IS NOT NULL THEN ai.COMPTE_VENTE
        ELSE ai.COMPTE_ACHAT
    END AS compte
FROM AS_INGREDIENTS ai where ai.pv>0
and CATEGORIEINGREDIENT='CAT002';

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."ST_INGREDIENTSAUTOVENTE" ("ID", "LIBELLE", "SEUIL", "UNITE", "QUANTITEPARPACK", "PU", "ACTIF", "PHOTO", "CALORIE", "DURRE", "COMPOSE", "CATEGORIEINGREDIENT", "IDFOURNISSEUR", "DATY", "QTELIMITE", "PV", "LIBELLEVENTE", "SEUILMIN", "SEUILMAX", "PUACHATUSD", "PUACHATEURO", "PUACHATAUTREDEVISE", "PUVENTEUSD", "PUVENTEEURO", "PUVENTEAUTREDEVISE", "ISVENTE", "ISACHAT", "COMPTE_VENTE", "COMPTE_ACHAT", "TVA", "COMPTE") AS
SELECT
    ai."ID",ai."LIBELLE",ai."SEUIL",ai."UNITE",ai."QUANTITEPARPACK",ai."PU",ai."ACTIF",ai."PHOTO",ai."CALORIE",ai."DURRE",ai."COMPOSE",ai."CATEGORIEINGREDIENT",ai."IDFOURNISSEUR",ai."DATY",ai."QTELIMITE",ai."PV",ai."LIBELLEVENTE",ai."SEUILMIN",ai."SEUILMAX",ai."PUACHATUSD",ai."PUACHATEURO",ai."PUACHATAUTREDEVISE",ai."PUVENTEUSD",ai."PUVENTEEURO",ai."PUVENTEAUTREDEVISE",ai."ISVENTE",ai."ISACHAT",ai."COMPTE_VENTE",ai."COMPTE_ACHAT", ai.TVA,
 ai.COMPTE_VENTE AS compte
FROM AS_INGREDIENTS ai where ai.pv>0;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."ST_INGREDIENTSVENTEPOS" ("ID", "LIBELLE", "SEUIL", "UNITE", "QUANTITEPARPACK", "PU", "ACTIF", "PHOTO", "CALORIE", "DURRE", "COMPOSE", "CATEGORIEINGREDIENT", "IDFOURNISSEUR", "DATY", "QTELIMITE", "PV", "LIBELLEVENTE", "SEUILMIN", "SEUILMAX", "PUACHATUSD", "PUACHATEURO", "PUACHATAUTREDEVISE", "PUVENTEUSD", "PUVENTEEURO", "PUVENTEAUTREDEVISE", "ISVENTE", "ISACHAT", "COMPTE_VENTE", "COMPTE_ACHAT", "TVA", "TAUX", "COMPTE", "LIBELLECOMPOSANT", "COULEUR", "TAILLE", "CODEBARRE", "REFERENCE", "CODEGROS", "PVGROS", "UNITELIB", "DESIGNATION", "TYPESTOCK") AS
SELECT
    ai.ID,
    ai.LIBELLE as libelle,
    ai.SEUIL,
    ai.UNITE,
    ai.QUANTITEPARPACK,
    ai.PU,
    ai.ACTIF,
    ai.PHOTO,
    ai.CALORIE,
    ai.DURRE,
    ai.COMPOSE,
    ai.CATEGORIEINGREDIENT,
    ai.IDFOURNISSEUR,
    ai.DATY,
    ai.QTELIMITE,
    ai.PV,
    ai.LIBELLEVENTE,
    ai.SEUILMIN,
    ai.SEUILMAX,
    ai.PUACHATUSD,
    ai.PUACHATEURO,
    ai.PUACHATAUTREDEVISE,
    ai.PUVENTEUSD,
    ai.PUVENTEEURO,
    ai.PUVENTEAUTREDEVISE,
    ai.ISVENTE,
    ai.ISACHAT,
    ai.COMPTE_VENTE,
    ai.COMPTE_ACHAT,
    ai.TVA,
    1 AS taux,
    ai.COMPTE_VENTE AS compte,
    ai.LIBELLE || ' ' || ai.COULEUR || ' ' || ai.TAILLE AS libellecomposant,
    ai.COULEUR,
    ai.TAILLE,
    ai.codebarre,
    ai.REFERENCE,
    ai.codegros,
    ai.pvgros,
    u.VAL AS UNITELIB,
    CONCAT(concat(ai.libelle,' - '),u.val) AS designation,
    ai.TYPESTOCK
FROM
    AS_INGREDIENTS ai
        LEFT JOIN AS_RECETTE ar ON ar.IDPRODUITS = ai.ID
        LEFT JOIN AS_INGREDIENTS cps ON cps.ID  = ar.IDINGREDIENTS
        LEFT JOIN AS_UNITE u ON ai.unite=u.id
where AI.PV != 0 AND ai.ACTIF = 1
GROUP BY
    ai.ID,
    ai.LIBELLE,
    ai.SEUIL,
    ai.UNITE,
    ai.QUANTITEPARPACK,
    ai.PU,
    ai.ACTIF,
    ai.PHOTO,
    ai.CALORIE,
    ai.DURRE,
    ai.COMPOSE,
    ai.CATEGORIEINGREDIENT,
    ai.IDFOURNISSEUR,
    ai.DATY,
    ai.QTELIMITE,
    ai.PV,
    ai.LIBELLEVENTE,
    ai.SEUILMIN,
    ai.SEUILMAX,
    ai.PUACHATUSD,
    ai.PUACHATEURO,
    ai.PUACHATAUTREDEVISE,
    ai.PUVENTEUSD,
    ai.PUVENTEEURO,
    ai.PUVENTEAUTREDEVISE,
    ai.ISVENTE,
    ai.ISACHAT,
    ai.COMPTE_VENTE,
    ai.COMPTE_ACHAT,
    ai.TVA,
    ai.COULEUR,
    ai.TAILLE,
    ai.REFERENCE,
    ai.codebarre,
    u.val,
    ai.codegros,
    ai.pvgros,
    ai.TYPESTOCK;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."ST_INGREDIENTSVENTEPOS_REM" ("ID", "LIBELLE", "SEUIL", "UNITE", "QUANTITEPARPACK", "PU", "ACTIF", "PHOTO", "CALORIE", "DURRE", "COMPOSE", "CATEGORIEINGREDIENT", "IDFOURNISSEUR", "DATY", "QTELIMITE", "PV", "LIBELLEVENTE", "SEUILMIN", "SEUILMAX", "PUACHATUSD", "PUACHATEURO", "PUACHATAUTREDEVISE", "PUVENTEUSD", "PUVENTEEURO", "PUVENTEAUTREDEVISE", "ISVENTE", "ISACHAT", "COMPTE_VENTE", "COMPTE_ACHAT", "TVA", "TAUX", "COMPTE", "LIBELLECOMPOSANT", "COULEUR", "TAILLE", "CODEBARRE", "REFERENCE", "CODEGROS", "PVGROS", "UNITELIB", "DESIGNATION", "REMISE", "PVREMISE", "IDCATEGORIECLIENT", "IDPOINT", "IDREMISEFILLE", "IDREMISE", "REMISENOM", "DATYREMISE", "DATEDEBUTREMISE", "DATEFINREMISE", "TYPESTOCK") AS
SELECT
    ai.ID,
    ai.LIBELLE AS libelle,
    ai.SEUIL,
    ai.UNITE,
    ai.QUANTITEPARPACK,
    ai.PU,
    ai.ACTIF,
    ai.PHOTO,
    ai.CALORIE,
    ai.DURRE,
    ai.COMPOSE,
    ai.CATEGORIEINGREDIENT,
    ai.IDFOURNISSEUR,
    ai.DATY,
    ai.QTELIMITE,
    ai.PV,
    ai.LIBELLEVENTE,
    ai.SEUILMIN,
    ai.SEUILMAX,
    ai.PUACHATUSD,
    ai.PUACHATEURO,
    ai.PUACHATAUTREDEVISE,
    ai.PUVENTEUSD,
    ai.PUVENTEEURO,
    ai.PUVENTEAUTREDEVISE,
    ai.ISVENTE,
    ai.ISACHAT,
    ai.COMPTE_VENTE,
    ai.COMPTE_ACHAT,
    ai.TVA,
    1 AS taux,
    ai.COMPTE_VENTE AS compte,
    ai.LIBELLE || ' ' || ai.COULEUR || ' ' || ai.TAILLE AS libellecomposant,
    ai.COULEUR,
    ai.TAILLE,
    ai.codebarre,
    ai.REFERENCE,
    ai.codegros,
    ai.pvgros,
    u.VAL AS UNITELIB,
    CONCAT(CONCAT(ai.libelle, ' - '), u.val) AS designation,

    rfmv.remise,
    ai.PV - (ai.PV * NVL(rfmv.remise, 0) / 100) AS pvRemise,

    rfmv.IDCATEGORIECLIENT,
    rfmv.IDPOINT,
    rfmv.id AS idRemiseFille,
    rfmv.idRemise,
    rfmv.nom AS RemiseNom,
    rfmv.daty AS datyRemise,
    rfmv.DATEDEBUT AS datedebutRemise,
    rfmv.DATEFIN AS datefinRemise,
    ai.TYPESTOCK

FROM AS_INGREDIENTS ai

         LEFT JOIN AS_RECETTE ar
                   ON ar.IDPRODUITS = ai.ID

         LEFT JOIN AS_INGREDIENTS cps
                   ON cps.ID = ar.IDINGREDIENTS

         LEFT JOIN AS_UNITE u
                   ON ai.unite = u.id

         LEFT JOIN remiseFilleMereVise rfmv
                   ON (
                       rfmv.CATEGORIEPRODUIT = ai.CATEGORIEINGREDIENT
                           OR rfmv.idproduit = ai.id
                       )

WHERE ai.PV != 0
AND ai.ACTIF = 1
GROUP BY
    ai.ID,
    ai.LIBELLE,
    ai.SEUIL,
    ai.UNITE,
    ai.QUANTITEPARPACK,
    ai.PU,
    ai.ACTIF,
    ai.PHOTO,
    ai.CALORIE,
    ai.DURRE,
    ai.COMPOSE,
    ai.CATEGORIEINGREDIENT,
    ai.IDFOURNISSEUR,
    ai.DATY,
    ai.QTELIMITE,
    ai.PV,
    ai.LIBELLEVENTE,
    ai.SEUILMIN,
    ai.SEUILMAX,
    ai.PUACHATUSD,
    ai.PUACHATEURO,
    ai.PUACHATAUTREDEVISE,
    ai.PUVENTEUSD,
    ai.PUVENTEEURO,
    ai.PUVENTEAUTREDEVISE,
    ai.ISVENTE,
    ai.ISACHAT,
    ai.COMPTE_VENTE,
    ai.COMPTE_ACHAT,
    ai.TVA,
    ai.COULEUR,
    ai.TAILLE,
    ai.REFERENCE,
    ai.codebarre,
    u.VAL,
    ai.codegros,
    ai.pvgros,
    rfmv.remise,
    rfmv.IDCATEGORIECLIENT,
    rfmv.IDPOINT,
    rfmv.id,
    rfmv.idRemise,
    rfmv.nom,
    rfmv.daty,
    rfmv.DATEDEBUT,
    rfmv.DATEFIN,
    ai.TYPESTOCK;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SUIVICHAMBREFROIDEDETAIL_LIB" ("ID", "IDMERE", "IDRESPONSABLE", "HEURE", "TEMPERATURE", "HUMIDITE", "REMARQUE", "IDRESPONSABLELIB") AS
SELECT
	scfd.id,
	scfd.idmere,
	scfd.idresponsable,
	scfd.heure,
	scfd.temperature,
	scfd.humidite,
	scfd.remarque,
	lp.NOM || ' ' || lp.PRENOM AS idResponsableLib
FROM 
  suiviChambreFroideDetail scfd
LEFT JOIN LOG_PERSONNEL lp ON scfd.idresponsable = lp.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SUIVICHAMBREFROIDE_LIB" ("ID", "DATY", "IDSALLESTOCKAGEOEUF", "IDSALLESTOCKAGEOEUFLIB", "ETAT", "ETATLIB") AS
SELECT 
	sqf.id,
	sqf.daty,
	sqf.IDSALLESTOCKAGEOEUF,
	m.VAL AS idSalleStockageOeufLib,
	sqf.etat,
    CASE
        WHEN sqf.etat = 1 THEN 'CREE'
        WHEN sqf.etat = 0 THEN 'ANNULEE'
        WHEN sqf.etat = 11 THEN 'VISEE'
    END AS etatLib
FROM
	suiviChambreFroide sqf
LEFT JOIN MAGASIN2 m ON sqf.IDSALLESTOCKAGEOEUF = m.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SUIVIJOURNALIERDETAIL_LIB" ("ID", "IDMERE", "IDBATIMENT", "IDPARQUET", "AGEJOUR", "ENTREE", "TRI", "MORTALITE", "CULLS", "CONSIGNESURALIMENT", "EAU", "TEMPERATUREMIN", "TEMPERATUREMAX", "IDBATIMENTLIB", "IDPARQUETLIB") AS
SELECT d."ID",d."IDMERE",d."IDBATIMENT",d."IDPARQUET",d."AGEJOUR",d."ENTREE",d."TRI",d."MORTALITE",d."CULLS",d."CONSIGNESURALIMENT",d."EAU",d."TEMPERATUREMIN",d."TEMPERATUREMAX",
       b."NOMBATIMENT" AS "IDBATIMENTLIB",
       p."VAL" AS "IDPARQUETLIB"
FROM "SUIVIJOURNALIERDETAIL" d
LEFT JOIN "BATIMENT" b ON b."ID" = d."IDBATIMENT"
LEFT JOIN "PARQUET" p ON p."ID" = d."IDPARQUET";

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SUIVIJOURNALIER_LIB" ("ID", "DATY", "IDFERME", "IDLOT", "IDFERMELIB", "IDLOTLIB", "IDSOUCHELIB", "ETAT", "ETATLIB") AS
SELECT s.ID,s.DATY,s.IDFERME,s.IDLOT,
       m.VAL    AS IDFERMELIB,
       l.NOMLOT AS IDLOTLIB,
       so.val AS idsouchelib,
       s.ETAT AS ETAT,
       CASE s.ETAT
           WHEN 1  THEN 'CREE'
           WHEN 11 THEN 'VALIDE'
           WHEN 0  THEN 'ANULLE'
           END AS ETATLIB
FROM SUIVIJOURNALIER s
         LEFT JOIN MAGASIN2 m ON m.ID = s.IDFERME
         LEFT JOIN LOT l ON l.ID = s.IDLOT
         LEFT JOIN SOUCHE so ON so.id=l.idsouche;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SUIVI_PRESENCE_FILLE_LIB" ("ID", "IDSUIVIPRESENCEMERE", "IDPARTICIPATIONFORMATION", "IDPERSONNEL", "IDACTIONFORMATION", "DATESEANCE", "PRESENCE", "NBHEUREEFFECTUE", "PERSONNELLIB", "MATRICULE", "CATEGORIEEMPLOYE", "ACTIONFORMATIONLIB") AS
SELECT
    spf.ID,spf.IDSUIVIPRESENCEMERE,spf.IDPARTICIPATIONFORMATION,spf.IDPERSONNEL,spf.IDACTIONFORMATION,spf.DATESEANCE,spf.PRESENCE,spf.NBHEUREEFFECTUE,
    lp.nom || ' ' || lp.prenom AS personnelLib,
    pip.matricule,
    cp.val AS categorieEmploye,
    af.intitule AS actionFormationLib
FROM SUIVI_PRESENCE_FILLE spf
         LEFT JOIN LOG_PERSONNEL lp
                   ON lp.id = spf.idpersonnel
         LEFT JOIN PAIE_INFO_PERSONNEL pip
                   ON pip.id = spf.idpersonnel
         LEFT JOIN CATEGORIE_PAIE cp
                   ON pip.idcategorie_paie = cp.id
         LEFT JOIN ACTION_FORMATION af
                   ON af.id = spf.idactionformation;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SUIVI_PRESENCE_MERE_LIB" ("ID", "IDSESSIONFORMATION", "SESSIONFORMATIONLIB", "DATY", "ACTIONFORMATIONLIB") AS
SELECT
    spm.ID,spm.IDSESSIONFORMATION,
    sf.remarque AS sessionFormationLib,
    spm.DATY,
    af.intitule AS actionFormationLib
FROM SUIVI_PRESENCE_MERE spm
         LEFT JOIN SESSION_FORMATION sf
                   ON sf.id = spm.idsessionformation
         LEFT JOIN ACTION_FORMATION af
                   ON af.id = sf.idactionformation;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SUM_HS_DAY" ("JOUR", "AVG_HS_PER_DAY", "IDDEPARTEMENT", "DEPARTEMENTLIB") AS
SELECT
    dateFabrication AS jour,
    SUM(HS) AS avg_hs_per_day,
    IDDEPARTEMENT,
    departementLib
FROM HEURESUPFABRICATION_CPL
GROUP BY dateFabrication, IDDEPARTEMENT, departementLib
ORDER BY dateFabrication;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SUM_HS_MONTH" ("ANNEE", "MOIS", "AVG_HS_PER_MONTH", "IDDEPARTEMENT", "DEPARTEMENTLIB") AS
SELECT
    EXTRACT(YEAR FROM dateFabrication) AS annee,
    EXTRACT(MONTH FROM dateFabrication) AS mois,
    SUM(HS) AS avg_hs_per_month,
    IDDEPARTEMENT,
    departementLib
FROM HEURESUPFABRICATION_CPL
GROUP BY
    EXTRACT(YEAR FROM dateFabrication),
    EXTRACT(MONTH FROM dateFabrication),
    IDDEPARTEMENT,
    departementLib
ORDER BY annee, mois;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SUM_HS_MONTH_LIB" ("ANNEE", "MOIS", "MONTHLIB", "AVG_HS_PER_MONTH", "IDDEPARTEMENT", "DEPARTEMENTLIB") AS
SELECT
    EXTRACT(YEAR FROM dateFabrication) AS annee,
    EXTRACT(MONTH FROM dateFabrication) AS mois,
    TO_CHAR(dateFabrication, 'Month YYYY', 'NLS_DATE_LANGUAGE=FRENCH') AS monthLib,
    SUM(HS) AS avg_hs_per_month,
    IDDEPARTEMENT,
    departementLib
FROM HEURESUPFABRICATION_CPL
GROUP BY
    EXTRACT(YEAR FROM dateFabrication),
    EXTRACT(MONTH FROM dateFabrication),
    TO_CHAR(dateFabrication, 'Month YYYY', 'NLS_DATE_LANGUAGE=FRENCH'),
    IDDEPARTEMENT,
    departementLib
ORDER BY
    annee,
    mois;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SUM_HS_YEAR" ("ANNEE", "AVG_HS_PER_YEAR", "IDDEPARTEMENT", "DEPARTEMENTLIB") AS
SELECT
    EXTRACT(YEAR FROM dateFabrication) AS annee,
    SUM(HS) AS avg_hs_per_year,
    IDDEPARTEMENT,
    departementLib
FROM HEURESUPFABRICATION_CPL
GROUP BY EXTRACT(YEAR FROM dateFabrication),IDDEPARTEMENT,
         departementLib
ORDER BY annee;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TABLEAUBORDBC" ("PRODUIT", "MONTANT", "PU", "QUANTITE", "REMISE", "TVA", "UNITE", "QTEOF", "QTEOFRESTANTE", "QTEFAB", "QTEFABRESTANTE", "QTELIVRE", "QTENONLIVRE", "LIBELLEPRODUIT", "DATY") AS
SELECT
 	bcf.PRODUIT,
    CAST(avg(bcf.MONTANT) AS NUMBER(30,5))  as montant,
    CAST(avg(bcf.PU) AS NUMBER(30,5)) as pu,
    CAST(avg(bcf.QUANTITE) AS NUMBER(20,5)) as quantite,
    CAST(avg(bcf.REMISE) AS NUMBER(30,5)) as remise,
    CAST(avg(bcf.TVA) AS NUMBER(30,5)) as tva,
    ing.UNITE as unite,
    CAST(nvl(avg(o.QTE),0) AS NUMBER(20,5)) AS QTEOF,
    CAST(NVL(sum(bcf.QUANTITE) - nvl(avg(o.QTE),0), 0) AS NUMBER(20,5)) AS QTEOFRESTANTE,

    CAST(nvl(avg(f.QTE),0) AS NUMBER(20,5)) AS QTEFAB,
    CAST(NVL(sum(bcf.QUANTITE) - nvl(avg(f.QTE),0), 0) AS NUMBER(20,5)) AS QTEFABRESTANTE,

    CAST(AVG(NVL(abcf.QUANTITE, 0)) AS NUMBER(20,5)) AS QTELIVRE,
	CAST(NVL(avg(bcf.QUANTITE) - AVG(NVL(abcf.QUANTITE,0)), 0) AS NUMBER(20,5)) AS QTENONLIVRE,
	ing.LIBELLE as libelleProduit,
	bc.DATY 

FROM BONDECOMMANDE_CLIENT_FILLE bcf

LEFT JOIN BONDECOMMANDE_CLIENT bc ON bc.ID = bcf.IDBC 

LEFT JOIN OfGroupByIdbc o ON o.IDBCFILLE = bcf.ID


LEFT JOIN fabrGroupByIdbc f ON f.IDBCFILLE = bcf.ID

LEFT JOIN BLGroupByIdbc abcf ON abcf.IDBC_FILLE = bcf.ID

left join AS_INGREDIENTS ing on ing.id=bcf.PRODUIT

GROUP BY
    bcf.PRODUIT,
    ing.LIBELLE, ing.UNITE,bc.DATY;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TARIF_INGREDIENTS_LIB" ("ID", "IDTYPECLIENT", "IDINGREDIENT", "DATY", "PRIXUNITAIRE", "IDTYPECLIENTLIB", "IDINGREDIENTLIB", "UNITE", "UNITELIB", "MOTSCLESSS") AS
SELECT TI.ID,
       TI.IDTYPECLIENT,
       TI.IDINGREDIENT,
       TI.DATY,
       TI.PRIXUNITAIRE,
       T.VAL      AS IDTYPECLIENTLIB,
       AI.LIBELLE AS IDINGREDIENTLIB,
       TI.UNITE,
       U.VAL      AS UNITELIB,
       (
           TI.ID || ' | ' || T.VAL || ' | ' || AI.LIBELLE || ' | ' || U.VAL
           )      AS MOTSCLESSS
FROM TARIF_INGREDIENTS TI
         LEFT JOIN TYPECLIENT T
                   ON TI.IDTYPECLIENT = T.ID
         LEFT JOIN AS_INGREDIENTS AI
                   ON TI.IDINGREDIENT = AI.ID
         LEFT JOIN AS_UNITE U
                   ON U.ID = TI.UNITE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TARIF_INGREDIENTS_MAX" ("IDINGREDIENT", "UNITE", "IDTYPECLIENT", "PRIXUNITAIRE", "DATY", "IDMAGASIN") AS
WITH ranked_tarifs AS (
    SELECT
        IDINGREDIENT,
        UNITE,
        IDTYPECLIENT,
        CAST(PRIXUNITAIRE AS NUMBER(30,5)) AS PRIXUNITAIRE,
        DATY,
        IDMAGASIN,
        ROW_NUMBER() OVER (PARTITION BY IDINGREDIENT, UNITE, IDTYPECLIENT, IDMAGASIN ORDER BY DATY DESC) as rn
    FROM TARIF_INGREDIENTS
)
SELECT
    IDINGREDIENT,
    UNITE,
    IDTYPECLIENT,
    PRIXUNITAIRE,
    DATY,
    IDMAGASIN
FROM ranked_tarifs
WHERE rn = 1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TARIF_INGREDIENTS_MAX_DATE_MN" ("IDINGREDIENT", "UNITE", "IDTYPECLIENT", "DATY", "IDMAGASIN") AS
select IDINGREDIENT, UNITE, IDTYPECLIENT, max(DATY) as daty, IDMAGASIN
from (select * from TARIF_INGREDIENTS where idmagasin is null)
group by IDINGREDIENT, UNITE, IDTYPECLIENT, IDMAGASIN;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TARIF_INGREDIENTS_MAX_DATE_MNN" ("IDINGREDIENT", "UNITE", "IDTYPECLIENT", "DATY", "IDMAGASIN") AS
select IDINGREDIENT, UNITE, IDTYPECLIENT, max(DATY) as daty, IDMAGASIN
from (select * from TARIF_INGREDIENTS where idmagasin is not null)
group by IDINGREDIENT, UNITE, IDTYPECLIENT, IDMAGASIN;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TARIF_INGREDIENTS_MAX_LIB" ("IDTYPECLIENT", "IDINGREDIENT", "DATY", "PRIXUNITAIRE", "IDTYPECLIENTLIB", "IDINGREDIENTLIB", "UNITE", "UNITELIB") AS
SELECT
    ti."IDTYPECLIENT",ti."IDINGREDIENT",ti."DATY",ti."PRIXUNITAIRE" ,
    t.VAL AS idtypeclientlib,
    ai.LIBELLE AS idingredientlib,
    ti.UNITE,
    u.VAL as unitelib
FROM TARIF_INGREDIENTS_MAX ti
         LEFT JOIN TYPECLIENT t
                   ON ti.IDTYPECLIENT = t.ID
         LEFT JOIN AS_INGREDIENTS ai
                   ON ti.IDINGREDIENT = ai.ID
         left join AS_UNITE u on u.id=ti.UNITE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TARIF_INGREDIENTS_MAX_MN" ("IDINGREDIENT", "UNITE", "IDTYPECLIENT", "DATY", "IDMAGASIN", "PRIXUNITAIRE") AS
select timd."IDINGREDIENT",timd."UNITE",timd."IDTYPECLIENT",timd."DATY",timd."IDMAGASIN", ti.PRIXUNITAIRE
from TARIF_INGREDIENTS_MAX_date_mn timd
         left join (select * from TARIF_INGREDIENTS where idmagasin is null) ti
              on ti.DATY = timd.daty and timd.IDINGREDIENT = ti.IDINGREDIENT and timd.UNITE = ti.UNITE and timd.IDTYPECLIENT = ti.IDTYPECLIENT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TARIF_INGREDIENTS_MAX_MNN" ("IDINGREDIENT", "UNITE", "IDTYPECLIENT", "DATY", "IDMAGASIN", "PRIXUNITAIRE") AS
select timd."IDINGREDIENT",timd."UNITE",timd."IDTYPECLIENT",timd."DATY",timd."IDMAGASIN", ti.PRIXUNITAIRE
from TARIF_INGREDIENTS_MAX_date_mnn timd
         left join (select * from TARIF_INGREDIENTS where idmagasin is not null) ti
              on ti.DATY = timd.daty and timd.IDINGREDIENT = ti.IDINGREDIENT and timd.UNITE = ti.UNITE and ti.idmagasin = timd.idmagasin and timd.IDTYPECLIENT = ti.IDTYPECLIENT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TAUXABSENTEISME" ("HEURETHEORIQUE", "HEUREABSENCE", "MOIS", "ANNEE", "TAUXABSENCE", "MOISLIB", "IDDIRECTION") AS
SELECT
    CAST(nb.NBPERSONNELVALIDE * 173.33 AS NUMBER(30, 2)) AS heuretheorique,
    CAST(NVL(SUM(p.ABSENCE), 0) AS NUMBER(30, 2)) AS heureabsence,
    p.mois,
    p.ANNEE,
    CAST(
            ROUND(
                    (NVL(SUM(p.ABSENCE), 0) / (nb.NBPERSONNELVALIDE * 173.33)) * 100,
                    2
            ) AS NUMBER(30, 2)
    ) AS tauxAbsence,
    TO_CHAR(
            TO_DATE(TO_CHAR(p.mois, 'FM00'), 'MM'),
            'FMMonth',
            'NLS_DATE_LANGUAGE=FRENCH'
    ) AS moisLib,
    p.DIRECTION AS iddirection
FROM
    POINTAGE p,
    NB_PERS_VALIDE nb
GROUP BY
    nb.NBPERSONNELVALIDE, p.mois, p.ANNEE, p.DIRECTION;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TAUXDECHANGE_MAXDATY" ("IDDEVISE", "TAUX") AS
SELECT 
  tc.IDDEVISE,
  tc.TAUX
FROM
(SELECT
IDDEVISE,
max(DATY) AS  DATY
FROM TAUXDECHANGE
GROUP BY
IDDEVISE) t1 
JOIN 
TAUXDECHANGE tc 
ON t1.idDevise = tc.IDDEVISE AND t1.daty = tc.daty;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TAUXDISPONIBILITEMACHINE" ("IDMACHINE", "NOMMACHINE", "IDLIGNE", "IDLIGNELIB", "TAUXDISPONIBILITE") AS
SELECT
    m.IDMACHINE ,
    m.NOMMACHINE ,
    l.ID AS idLigne,
    l.VAL AS idLigneLib,
    CASE
        WHEN m2.ECARTJOURS != 0 AND m.MOYENNEDUREE !=0 THEN (m2.ECARTJOURS * 24)/((m2.ECARTJOURS * 24)/m.MOYENNEDUREE)
		ELSE 0
END AS TauxDisponibilite
FROM MOYENNETRAVAUXMACHINE m
LEFT JOIN MOYENNEPANNESTRAVAUX m2
ON m.IDMACHINE = m2.IDMACHINE
LEFT JOIN AS_INGREDIENT_MAINTENANCE aim
ON m.IDMACHINE = aim.ID
LEFT JOIN LIGNE l
ON aim.IDLIGNE = l.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TEMPSMOYENPANNES" ("IDMACHINE", "NOMMACHINE", "IDTRAVAUX", "DATY", "ECART_JOURS") AS
WITH ECARTS AS (
        SELECT
            CASE
                WHEN ai.id IS NULL THEN aim.id
                ELSE ai.id
            END AS idMachine,
            CASE
                WHEN ai.libelle IS NULL THEN aim.descriptionObjet
                ELSE ai.libelle
            END AS nomMachine,
            t.ID AS IDTRAVAUX,
            t.DATY,
            NVL(
                t.DATY - LAG(t.DATY) OVER (PARTITION BY o.IDINGREDIENTS ORDER BY t.DATY),
                0
            ) AS ECART_JOURS
        FROM TRAVAUX t
        LEFT JOIN ORDRETRAVAUXFILLE o
            ON t.IDOFFILLE = o.ID
        LEFT JOIN as_ingredients ai
            ON o.IDINGREDIENTS = ai.id
        LEFT JOIN AS_INGREDIENT_MAINTENANCE aim
            ON o.IDINGREDIENTS = aim.id
    )
SELECT "IDMACHINE","NOMMACHINE","IDTRAVAUX","DATY","ECART_JOURS"
FROM ECARTS;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TEMPSOUVERTURELIB" ("ID", "IDMACHINE", "TEMPS", "CAPACITE", "IDUNITE", "IDMACHINELIB", "IDUNITELIB", "MOTSCLESSS") AS
SELECT
    t.ID,t.IDMACHINE,t.TEMPS,t.CAPACITE,t.IDUNITE,
    aim.LIBELLE AS idmachinelib,
    au.VAL as idunitelib,
    
    t.ID || t.IDMACHINE || t.TEMPS || t.CAPACITE || t.IDUNITE || 
    aim.LIBELLE || au.VAL  AS motsClesss
FROM tempsouverture t
         LEFT JOIN as_ingredient_maintenance aim
                   ON aim.id = t.idmachine
         LEFT JOIN AS_UNITE au
                   ON au.id = t.IDUNITE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TEST_SITUATION_SALAIRE_EDITION" ("ID", "IDEDITION", "NBENFANT", "MATRICULE", "NOM", "PRENOM", "PERSONNEL", "FONCTION", "IDFONCTION", "CLASSIFICATION", "IDCATEGORIE", "IDDIRECTION", "DIRECTION", "SECTION", "SECTION_NUMERO", "SECTION_LIBELLE", "SALAIRE", "SALAIREBRUTE", "HEUREMOIS", "HEUREPRESENCE", "TAUXHORAIRE", "SALAIREMOIS", "HEURESUP", "RAPPEL", "RETENUABSC", "PRIME", "CONGEPAYER", "PREAVIS", "NETPAYER", "NETPAYERARR", "INDAMDIVFIXE", "CNAPS", "OSTIE", "NETIMPOSABLE", "NETIMPOSABLEARR", "IRSA", "IRSANET", "ALLOCATION", "AVANCESALAIRE", "AVANCEEXCEP", "ANNEE", "MOIS") AS
SELECT
    lp.ID,
    pe.idedition AS idedition,
    pip.nbenfant,
    pip.MATRICULE,
    trim(TRAILING ' ' FROM lp.NOM) AS nom,
    trim(TRAILING ' ' FROM lp.PRENOM) AS prenom,
    trim(TRAILING ' ' FROM lp.NOM)
        || ' '
        || trim(TRAILING ' ' FROM lp.PRENOM) AS personnel,
    pf.desce AS fonction,
    pf.id AS idfonction,
    pc.VAL AS classification,
    pc.id AS idcategorie,
    ld.ID AS iddirection,
    ld.VAL AS direction,
    ls.ID AS SECTION,
    ls.CODE_SERVICE AS section_numero,
    ls.libelle AS section_libelle,
    nvl(SALAIREDEBASE.salairedebase, 0) AS salaire,
    nvl(totalgain.gain,0) as salairebrute,
    173.33 as heuremois,
    nvl(poi.HEURENORMAL, 0) AS heurepresence,
    nvl(pe.tauxhoraire, 0) AS tauxhoraire,
    nvl(salaire.gain, 0) AS salairemois,
    nvl(heuresup.gain, 0) AS heuresup,
    nvl(rappel.gain, 0) AS rappel,
    nvl(retenuabsc.retenue, 0) AS retenuabsc,
    nvl(prime.gain, 0) AS prime,
    nvl(congepayer.gain, 0) AS congepayer,
    nvl(preavis.gain, 0) AS preavis,
    nvl(netpayer.gain, 0) AS netpayer,
    nvl(netpayerarr.gain, 0) AS netpayerarr,
    nvl(indamdivfixe.gain, 0) AS indamdivfixe,
    nvl(cnaps.retenue, 0) AS cnaps,
    nvl(ostie.retenue, 0) AS ostie,
    nvl(netimposable.retenue, 0) AS netimposable,
    nvl(netimposablearr.retenue, 0) AS netimposablearr,
    nvl(irsa.retenue, 0) AS irsa,
    nvl(irsanet.retenue, 0) AS irsanet,
    nvl(allocation.gain,0) as allocation,
    nvl(avancesalaire.retenue, 0) AS avancesalaire,
    nvl(avanceexcep.retenue, 0) AS avanceexcep,
    pe.annee,
    pe.mois
FROM -- select * from
    paie_edition pe
    INNER JOIN log_personnel lp ON
    lp.id = pe.idpersonnel
    INNER JOIN paie_info_personnel pip ON
    pip.id = pe.idpersonnel
    INNER JOIN log_direction ld ON
    pe.DIRECTION = ld.ID
    INNER JOIN log_service ls ON
    pe.SERVICE = ls.ID
    INNER JOIN CATEGORIE_PAIE pc ON
    pe.IDCATEGORIE = pc.ID
    INNER JOIN paie_fonction pf ON
    pe.IDFONCTION = pf.ID
    INNER JOIN POINTAGE poi ON
    pe.IDPERSONNEL = poi.IDPERSONNEL
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(gain) AS gain,
    mois,
    annee
    FROM
    paie_edition pe
    WHERE
    regroupement = 1
    GROUP BY
    idpersonnel,
    mois,
    annee) salaire
    ON
    salaire.idpersonnel = lp.id
    AND salaire.annee = pe.annee
    AND salaire.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    max(SALAIREDEBASE) AS salairedebase,
    mois,
    annee
    FROM
    paie_edition pe
    WHERE
    regroupement = 18
    GROUP BY
    idpersonnel,
    mois,
    annee) salairedebase
    ON
    salairedebase.idpersonnel = lp.id
    AND salairedebase.annee = pe.annee
    AND salairedebase.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(gain) AS gain,
    mois,
    annee
    FROM
    paie_edition pe
    WHERE
    regroupement = 2
    GROUP BY
    idpersonnel,
    mois,
    annee) heuresup
    ON
    heuresup.idpersonnel = lp.id
    AND heuresup.annee = pe.annee
    AND heuresup.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(gain) AS gain,
    mois,
    annee
    FROM
    paie_edition pe
    WHERE
    regroupement = 3
    GROUP BY
    idpersonnel,
    mois,
    annee) rappel
    ON
    rappel.idpersonnel = lp.id
    AND rappel.annee = pe.annee
    AND rappel.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(RETENUE) AS retenue,
    mois,
    annee
    FROM
    paie_edition pe
    WHERE
    regroupement = 4
    GROUP BY
    idpersonnel,
    mois,
    annee) retenuabsc
    ON
    retenuabsc.idpersonnel = lp.id
    AND retenuabsc.annee = pe.annee
    AND retenuabsc.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(gain) AS gain,
    mois,
    annee
    FROM
    paie_edition pe
    WHERE
    regroupement = 5
    GROUP BY
    idpersonnel,
    mois,
    annee) prime
    ON
    prime.idpersonnel = lp.id
    AND prime.annee = pe.annee
    AND prime.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(gain) AS gain,
    mois,
    annee
    FROM
    PAIE_EDITION_LIBCOMPLET pe
    WHERE
    CODERUBRIQUE IN ('403', '4030')
    GROUP BY
    idpersonnel,
    mois,
    annee) hs30
    ON
    hs30.idpersonnel = lp.id
    AND hs30.annee = pe.annee
    AND hs30.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(gain) AS gain,
    mois,
    annee
    FROM
    PAIE_EDITION_LIBCOMPLET pe
    WHERE
    CODERUBRIQUE IN ('405', '4050')
    GROUP BY
    idpersonnel,
    mois,
    annee) hs50
    ON
    hs50.idpersonnel = lp.id
    AND hs50.annee = pe.annee
    AND hs50.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(gain) AS gain,
    mois,
    annee
    FROM
    paie_edition pe
    WHERE
    regroupement = 6
    GROUP BY
    idpersonnel,
    mois,
    annee) congepayer
    ON
    congepayer.idpersonnel = lp.id
    AND congepayer.annee = pe.annee
    AND congepayer.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(gain) AS gain,
    mois,
    annee
    FROM
    paie_edition pe
    WHERE
    regroupement = 7
    GROUP BY
    idpersonnel,
    mois,
    annee) preavis
    ON
    preavis.idpersonnel = lp.id
    AND preavis.annee = pe.annee
    AND preavis.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(gain) AS gain,
    mois,
    annee
    FROM
    paie_edition pe
    WHERE
    regroupement = 8
    GROUP BY
    idpersonnel,
    mois,
    annee) indamdivfixe
    ON
    indamdivfixe.idpersonnel = lp.id
    AND indamdivfixe.annee = pe.annee
    AND indamdivfixe.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(gain) AS gain,
    mois,
    annee
    FROM
    paie_edition pe
    WHERE
    regroupement = 9
    GROUP BY
    idpersonnel,
    mois,
    annee) totalgain
    ON
    totalgain.idpersonnel = lp.id
    AND totalgain.annee = pe.annee
    AND totalgain.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(retenue) AS retenue,
    mois,
    annee
    FROM
    paie_edition pe
    WHERE
    regroupement = 10
    GROUP BY
    idpersonnel,
    mois,
    annee) cnaps
    ON
    cnaps.idpersonnel = lp.id
    AND cnaps.annee = pe.annee
    AND cnaps.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(retenue) AS retenue,
    mois,
    annee
    FROM
    PAIE_EDITION_LIBCOMPLET pe
    WHERE
    CODERUBRIQUE IN ('700', '701')
    GROUP BY
    idpersonnel,
    mois,
    annee) cnaps_sans_complementaire
    ON
    cnaps_sans_complementaire.idpersonnel = lp.id
    AND cnaps_sans_complementaire.annee = pe.annee
    AND cnaps_sans_complementaire.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(retenue) AS retenue,
    mois,
    annee
    FROM
    PAIE_EDITION_LIBCOMPLET pe
    WHERE
    CODERUBRIQUE IN ('705', '706')
    GROUP BY
    idpersonnel,
    mois,
    annee) cnaps_complementaire
    ON
    cnaps_complementaire.idpersonnel = lp.id
    AND cnaps_complementaire.annee = pe.annee
    AND cnaps_complementaire.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(retenue) AS retenue,
    mois,
    annee
    FROM
    paie_edition pe
    WHERE
    regroupement = 11
    GROUP BY
    idpersonnel,
    mois,
    annee) ostie
    ON
    ostie.idpersonnel = lp.id
    AND ostie.annee = pe.annee
    AND ostie.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(retenue) AS retenue,
    mois,
    annee
    FROM
    paie_edition pe
    WHERE
    regroupement = 12
    GROUP BY
    idpersonnel,
    mois,
    annee) netimposable
    ON
    netimposable.idpersonnel = lp.id
    AND netimposable.annee = pe.annee
    AND netimposable.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(retenue) AS retenue,
    mois,
    annee
    FROM
    paie_edition pe
    WHERE
    regroupement = 13
    GROUP BY
    idpersonnel,
    mois,
    annee) netimposablearr
    ON
    netimposablearr.idpersonnel = lp.id
    AND netimposablearr.annee = pe.annee
    AND netimposablearr.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(retenue) AS retenue,
    mois,
    annee
    FROM
    paie_edition pe
    WHERE
    regroupement = 14
    GROUP BY
    idpersonnel,
    mois,
    annee) irsa
    ON
    irsa.idpersonnel = lp.id
    AND irsa.annee = pe.annee
    AND irsa.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(retenue) AS retenue,
    mois,
    annee
    FROM
    paie_edition pe
    WHERE
    regroupement = 15
    GROUP BY
    idpersonnel,
    mois,
    annee) irsanet
    ON
    irsanet.idpersonnel = lp.id
    AND irsanet.annee = pe.annee
    AND irsanet.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(RETENUE) AS retenue,
    mois,
    annee
    FROM
    paie_edition pe
    WHERE
    regroupement = 16
    GROUP BY
    idpersonnel,
    mois,
    annee) avancesalaire
    ON
    avancesalaire.idpersonnel = lp.id
    AND avancesalaire.annee = pe.annee
    AND avancesalaire.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(retenue) AS retenue,
    mois,
    annee
    FROM
    paie_edition pe
    WHERE
    regroupement = 17
    GROUP BY
    idpersonnel,
    mois,
    annee) avanceexcep
    ON
    avanceexcep.idpersonnel = lp.id
    AND avanceexcep.annee = pe.annee
    AND avanceexcep.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(gain) AS gain,
    mois,
    annee
    FROM
    paie_edition pe
    WHERE
    regroupement = 18
    GROUP BY
    idpersonnel,
    mois,
    annee) netpayer
    ON
    netpayer.idpersonnel = lp.id
    AND netpayer.annee = pe.annee
    AND netpayer.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(gain) AS gain,
    mois,
    annee
    FROM
    paie_edition pe
    WHERE
    regroupement = 19
    GROUP BY
    idpersonnel,
    mois,
    annee) netpayerarr
    ON
    netpayerarr.idpersonnel = lp.id
    AND netpayerarr.annee = pe.annee
    AND netpayerarr.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(gain) AS gain,
    mois,
    annee
    FROM
    paie_edition pe
    WHERE
    regroupement = 20
    GROUP BY
    idpersonnel,
    mois,
    annee) allocation
    ON
    allocation.idpersonnel = lp.id
    AND allocation.annee = pe.annee
    AND allocation.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(gain) AS gain,
    mois,
    annee
    FROM
    paie_edition pe
    WHERE
    regroupement = 100
    GROUP BY
    idpersonnel,
    mois,
    annee) net_a_payer
    ON
    net_a_payer.idpersonnel = lp.id
    AND net_a_payer.annee = pe.annee
    AND net_a_payer.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(gain) AS gain,
    mois,
    annee
    FROM
    paie_edition pe
    WHERE
    (regroupement != 100
    OR regroupement IS NULL)
    GROUP BY
    idpersonnel,
    mois,
    annee) salaire_brute
    ON
    salaire_brute.idpersonnel = lp.id
    AND salaire_brute.annee = pe.annee
    AND salaire_brute.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(retenue) AS retenue,
    mois,
    annee
    FROM
    paie_edition pe
    GROUP BY
    idpersonnel,
    mois,
    annee) total_retenue
    ON
    total_retenue.idpersonnel = lp.id
    AND total_retenue.annee = pe.annee
    AND total_retenue.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(gain) AS gain,
    mois,
    annee
    FROM
    paie_edition pe,
    paie_rubrique pr
    WHERE
    pr.id = pe.idelementpaie
    AND pr.imposable = 'I'
    GROUP BY
    idpersonnel,
    mois,
    annee) montant_brute_imposable
    ON
    montant_brute_imposable.idpersonnel = lp.id
    AND montant_brute_imposable.annee = pe.annee
    AND montant_brute_imposable.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(gain) AS gain,
    mois,
    annee
    FROM
    PAIE_EDITION_LIBCOMPLET pe
    WHERE
    CODERUBRIQUE IN ('205')
    GROUP BY
    idpersonnel,
    mois,
    annee) indemnite_logement
    ON
    indemnite_logement.idpersonnel = lp.id
    AND indemnite_logement.annee = pe.annee
    AND indemnite_logement.mois = pe.mois
GROUP BY
    lp.ID,
    lpad(pe.MATRICULE, 5, '0'),
    pc.id,
    trim(TRAILING ' ' FROM lp.NOM),
    trim(TRAILING ' ' FROM lp.PRENOM),
    lp.NOM || ' ' || lp.PRENOM ,
    pf.DESCE,
    pf.id,
    pc.VAL ,
    ld.ID,
    ld.VAL,
    ls.ID,
    ls.CODE_SERVICE,
    ls.LIBELLE,
    pe.temporaire,
    nvl(SALAIREDEBASE.salairedebase, 0),
    nvl(heuresup.gain, 0),
    nvl(rappel.gain, 0),
    nvl(retenuabsc.retenue, 0),
    nvl(prime.gain, 0),
    nvl(net_a_payer.gain, 0),
    nvl(montant_brute_imposable.gain, 0),
    nvl(congepayer.gain, 0),
    nvl(preavis.gain, 0),
    nvl(hs30.gain, 0),
    nvl(hs50.gain, 0),
    nvl(indamdivfixe.gain, 0),
    nvl(totalgain.gain, 0),
    nvl(cnaps.retenue, 0),
    nvl(ostie.retenue, 0),
    nvl(salaire_brute.gain, 0),
    nvl(cnaps.retenue, 0),
    nvl(ostie.retenue, 0),
    nvl(irsa.retenue, 0),
    nvl(irsanet.retenue, 0),
    nvl(netimposable.retenue, 0),
    nvl(netimposablearr.retenue, 0),
    nvl(total_retenue.retenue, 0),
    nvl(avancesalaire.retenue, 0),
    nvl(avanceexcep.retenue, 0),
    nvl(cnaps_sans_complementaire.retenue, 0),
    nvl(cnaps_complementaire.retenue, 0),
    nvl(rappel.gain, 0),
    nvl(netpayer.gain, 0),
    nvl(netpayerarr.gain, 0),
    nvl(indemnite_logement.gain, 0),
    nvl(pe.tauxhoraire, 0),
    pip.MATRICULE,
    nvl(totalgain.gain,0),
    nvl(allocation.gain,0),
    173.33,
    nvl(poi.HEURENORMAL, 0),
    nvl(salaire.gain, 0),
    0,
    pip.nbenfant,
    pe.annee,
    pe.mois,
    pe.idedition;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TIERS" ("ID", "NOM", "COMPTE", "COMPTEAUXILIAIRE") AS
select ID, NOM, COMPTE, compteauxiliaire from FOURNISSEUR
UNION ALL
select ID, NOM, COMPTE, compteauxiliaire from CLIENT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TIERSENSEMBLE" ("ID", "NOM", "NIF", "STAT", "ADRESSE", "CONTACT", "CODEPOSTAL", "COMPTE", "IDTYPEFOURNISSEUR", "COMPTEAUXILIAIRE", "ESTACTIF", "ECHEANCE", "DEVISE", "MAIL", "BANQUE") AS
select f.ID,
       NOM,
       NIF,
       STAT,
       ADRESSE,
       CONTACT,
       CODEPOSTAL,
       COMPTE,
       IDTYPEFOURNISSEUR,
       COMPTEAUXILIAIRE,
       ESTACTIF,
       ECHEANCE,
       DEVISE,
       MAIL,
       BANQUE
from FOURNISSEUR f
union all
select c.ID,
       c.NOM,
       c.NIF,
       c.STAT,
       c.ADRESSE,
       c.mail as contact,
       '' as codepostal,
       c.COMPTE,
       c.IDTYPECLIENT as idTypefournisseur,
       c.COMPTEAUXILIAIRE,
       c.ESTACTIF,
       ECHEANCE,
       'AR' as devise,
       c.MAIL,
       '' as banque
from CLIENT c;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TOUSLESDATE" ("DATY") AS
SELECT
    (TO_DATE('01/01/2000', 'DD/MM/YYYY') + level - 1) AS daty
FROM dual
CONNECT BY level <= 1 + (ADD_MONTHS(TRUNC(SYSDATE), 120) - TO_DATE('01/01/2000', 'DD/MM/YYYY'));

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TRAITEETATVERSEMENT" ("IDTRAITE", "ETATVERSEMENT") AS
select IDTRAITE, cast(-2 as number) as etatversement
from MVTINTRACAISSE
where IDTRAITE is not null
  and ETATVERSEMENT = -2
group by IDTRAITE
UNION ALL
select idtraite, cast(11 as number) as etatversement
from MVTINTRACAISSE
where idtraite is not null
  and ETATVERSEMENT = 11
  and IDTRAITE not in
      (select IDTRAITE from MVTINTRACAISSE where IDTRAITE is not null and ETATVERSEMENT = -2 group by IDTRAITE)
group by idtraite;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TRAITELIB_GRP" ("IDTRAITE", "CODE") AS
SELECT  IDTRAITE,LISTAGG(CODE , ';') WITHIN GROUP (ORDER BY CODE) AS CODE FROM TRAITE_FCLIB tf
GROUP BY IDTRAITE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TRAITEMENT_PAIE_LIB" ("IDPERSONNEL", "NOMPERSONNEL", "MATRICULE", "NETAPAYER", "IDEDITION", "MODEPAIEMENT", "NUMEROCOMPTE") AS
SELECT
    ec.id AS idpersonnel ,
    ec.nom || ' ' || ec.PRENOM AS nomPersonnel,
    ec.MATRICULE ,
    pe.GAIN AS netapayer,
    pe.IDEDITION ,
    ec.MODE_PAIEMENT AS modepaiement,
    ec.BANQUE_NUMERO_COMPTE AS numeroCompte
FROM PAIE_EDITION pe
         LEFT JOIN EMPLOYE_COMPLET ec ON ec.id = pe.IDPERSONNEL
WHERE pe.IDELEMENTPAIE ='PR000210A' AND pe.etat >= 11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TRAITEMTTFC" ("ID", "MONTANTENLEVETRAITE") AS
SELECT
    t.ID,
    cast(nvl(sum(f.montant),0) as number(30,2)) AS montantenlevetraite
FROM traite t
         LEFT JOIN LIAISONPAIEMENT f ON t.ID = f.ID2
GROUP BY t.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TRAITEMTTRESTE" ("ID", "DATY", "TIERS", "BANQUE", "DATEECHEANCE", "ETAT", "MONTANT", "ESCOMPTE", "TOTAL", "REFERENCE", "MONTANTRESTE", "CDCLT", "IDBANQUE", "IDTYPEPIECE", "TYPEPIECE", "ETATVERSEMENT", "ETATVERSEMENTLIB") AS
SELECT t.ID,
       t.DATY,
       t.TIERS,
       t.BANQUE,
       t.DATEECHEANCE,
       t.ETAT,
       CAST(nvl(t.MONTANT,0) AS NUMBER(30, 2))                          AS montant,
       t.ESCOMPTE,
       CAST(nvl(t.TOTAL,0) AS NUMBER(30, 2))                            AS total,
       t.REFERENCE,
       CAST((nvl(t.total,0) - nvl(tf.montantenlevetraite, 0)) AS NUMBER(30, 2)) AS montantreste,
       t.cdclt,
       t.idbanque,
       t.idtypepiece,
       t.typepiece,
       nvl(te.etatversement, 1)                                  as etatversement,
       case
           when te.etatversement = -2 then 'Encaissee'
           when te.etatversement = 11 then 'Versee'
           else
               'Non Versee' end                                  as etatversementlib
FROM TRAITE_LIBMTT t
         LEFT JOIN traitemttfc tf ON tf.id = t.id
         LEFT JOIN traiteetatversement te on te.IDTRAITE = t.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TRAITEMTTRESTE_NONVERSEE" ("ID", "DATY", "TIERS", "BANQUE", "DATEECHEANCE", "ETAT", "MONTANT", "ESCOMPTE", "TOTAL", "REFERENCE", "MONTANTRESTE", "CDCLT", "IDBANQUE") AS
SELECT ID,DATY,TIERS,BANQUE,DATEECHEANCE,ETAT,MONTANT,ESCOMPTE,TOTAL,REFERENCE,MONTANTRESTE,CDCLT,IDBANQUE FROM (
	SELECT t.ID,t.DATY,t.TIERS,t.BANQUE,t.DATEECHEANCE,t.ETAT,t.MONTANT,t.ESCOMPTE,t.TOTAL,t.REFERENCE,
 (t.total-tf. montantenlevetraite) AS montantreste, t.cdclt, t.idbanque
 FROM TRAITE_LIBMTT t 
 LEFT JOIN traitemttfc tf ON tf.id=t.id
) tmttrst WHERE id NOT IN (SELECT idtraite FROM MVTINTRACAISSE m WHERE m.idtraite IS NOT NULL AND m.ETATVERSEMENT = 11);

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TRAITE_FC" ("ID", "IDTRAITE", "IDFC", "MONTANTFACTURE", "MONTANTJC", "MONTANT", "DATY", "ETAT", "CODE", "TIERS", "BANQUE", "FACTURECLIENTLIB", "TIERSLIB", "ETATLIB") AS
select
    fc.ID,tl.id AS IDTRAITE,fc.id AS IDFC, FC.MONTANTTTC as MONTANTFACTURE, j.CREDIT as MONTANTJC, pf.MONTANT,fc.DATY,fc.ETAT,'' as CODE,
    tl.tiers,
    tl.banque,
    fc.designation as factureclientlib,
    fc.IDCLIENTLIB as TIERSLIB,
    CASE
        WHEN j.etat = 1
            THEN 'Cree'
        WHEN j.ETAT >= 11
            THEN 'visee'
        WHEN j.ETAT =0
            THEN 'Annulee'
        END AS etatlib
from LIAISONPAIEMENT pf
         LEFT JOIN MOUVEMENTCAISSE j ON j.ID  = pf.id2
         JOIN traite tl on tl.id = j.idtraite
         left join VENTE_CPL fc on pf.id1  = fc.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TRAITE_FCLIB" ("IDTRAITE", "IDFACT", "CODE") AS
SELECT t.IDTRAITE ,t.idFc AS idfact,t.code FROM TRAITE_FC t;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TRAITE_FCSUM" ("ID", "FACTURECLIENTLIB", "TIERSLIB", "DATY", "MONTANTFACTURE", "ETATLIB", "IDTRAITE", "MONTANTTRAITE") AS
SELECT
    t.id,
    t.factureclientlib,
    t.tierslib,
    t.daty,
    cast(t.montantfacture as number(30,2)),
    t.etatLib,
    t.idTraite,
    cast(m.montanttraite as number(30,2))
FROM TRAITE_FC t
         LEFT JOIN montant_traite_fc m ON m.id=t.id AND m.idtraite=t.IDTRAITE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TRAITE_JC" ("ID", "IDTRAITE", "MONTANT", "DATY", "ETAT", "IDJC", "DATESAISIE", "DATEEFFET", "FOLIO", "CAISSE", "NUMPIECE", "LIBELLE", "DEBIT", "CREDIT", "REMARQUE", "ETATJC", "TIERS", "IDTYPECHEQUE", "DESIGNATION", "IDORDRE", "IDDEVISE", "IDMODE", "NUMCHEQUE", "TYPEMVT", "IDPLACEMENT", "IDBANQUE", "IDPLACEMENTVRAI", "ETATVERSEMENT", "ETATLIB", "ETATVERSEMENTLIB", "VALCAISSE") AS
select
    jc.id,fc.ID AS idtraite,fc.MONTANT,fc.DATY,fc.ETAT,jc.id AS IDJC,
    jc.daty as datesaisie,
    jc.daty as DATEEFFET,
    '' as FOLIO,
    jc.IDCAISSE as caisse,
    '' as NUMPIECE,
    jc.DESIGNATION as libelle ,
    jc.DEBIT,
    jc.CREDIT,
    jc.DESIGNATION as REMARQUE,
    jc.ETAT AS etatjc,
    jc.IDTIERS as TIERS,
    '' as IDTYPECHEQUE,
    jc.DESIGNATION,
    '' as IDORDRE,
    jc.IDDEVISE,
    '' as IDMODE,
    '' as NUMCHEQUE,
    '' as TYPEMVT,
    '' as IDPLACEMENT,
    fc.BANQUE as IDBANQUE,
    '' as IDPLACEMENTVRAI,
    jc.ETATVERSEMENT,
    case
        when jc.etat = 1 then 'CREEE'
        when jc.etat >= 11 then 'VISEE'
        else '' end                           as etatlib,
    case
        when jc.etatversement = -2 then 'Encaissee'
        when jc.etatversement = 11 then 'Versee'
        else '' end                           as etatversementlib,
    c.VAL AS valcaisse
from MOUVEMENTCAISSE jc
         join traite fc on fc.id = jc.IDTRAITE
          LEFT JOIN caisse c ON c.id = jc.IDCAISSE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TRAITE_LIB" ("ID", "DATY", "TIERS", "BANQUE", "DATEECHEANCE", "ETAT", "MONTANT", "REFERENCE", "CDCLT", "IDBANQUE", "IDTYPEPIECE", "TYPEPIECE") AS
select
    tr.id,
    tr.daty,
    ti.nom as tiers,
    ba.val as banque,
    tr.dateEcheance,
    tr.etat,
    tr.montant,
    tr.REFERENCE,
    '' as CDCLT,
    ba.ID AS idbanque,
    IDTYPEPIECE ,
    tp.val AS typepiece
from traite tr
         left join client ti on tr.tiers = ti.id
         left join banque ba on tr.banque = ba.id
         LEFT JOIN type_piece tp ON tp.id=tr.IDTYPEPIECE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TRAITE_LIBC" ("ID", "DATY", "TIERS", "BANQUE", "DATEECHEANCE", "ETAT", "MONTANT", "ETATVERSEMENT", "ETATVERSEMENTLIB", "MONTANTRESTE", "REFERENCE") AS
SELECT ID,DATY,TIERS,BANQUE,DATEECHEANCE,ETAT,MONTANT, etatversement, etatversementlib,MONTANTRESTE,reference  from TRAITEMTTRESTE where etat = 1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TRAITE_LIBENC" ("ID", "DATY", "TIERS", "BANQUE", "DATEECHEANCE", "ETAT", "MONTANT", "ETATVERSEMENT", "ETATVERSEMENTLIB", "MONTANTRESTE", "REFERENCE") AS
select ID,DATY,TIERS,BANQUE,DATEECHEANCE,ETAT,MONTANT, etatversement, etatversementlib,MONTANTRESTE, reference from TRAITEMTTRESTE where etatversement = -2;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TRAITE_LIBESC" ("ID", "DATY", "TIERS", "BANQUE", "DATEECHEANCE", "ETAT", "MONTANT", "ETATVERSEMENT", "ETATVERSEMENTLIB", "MONTANTRESTE", "REFERENCE") AS
select ID,DATY,TIERS,BANQUE,DATEECHEANCE,ETAT,MONTANT, etatversement, etatversementlib,MONTANTRESTE,reference from TRAITEMTTRESTE where id in (select idtraite from escompte where etat = 11);

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TRAITE_LIBMTT" ("ID", "DATY", "TIERS", "BANQUE", "DATEECHEANCE", "ETAT", "MONTANT", "ESCOMPTE", "TOTAL", "REFERENCE", "CDCLT", "IDBANQUE", "IDTYPEPIECE", "TYPEPIECE") AS
select t.ID,t.DATY,t.TIERS,t.BANQUE,t.DATEECHEANCE,t.ETAT,t.MONTANT,
       sum(nvl(e.FRAIS,0)) AS escompte,
       montant - sum(nvl(e.FRAIS, 0)) AS total, t.reference,
       t.CDCLT,
       t.idbanque,
       t.idtypepiece,
       t.typepiece
from traite_lib t
         LEFT JOIN ESCOMPTE_LIBV e ON e.IDTRAITE = t.id
GROUP BY t.id, t.DATY ,t.TIERS ,t.BANQUE ,t.DATEECHEANCE ,t.ETAT ,t.MONTANT,t.REFERENCE, t.CDCLT, t.idbanque,t.idtypepiece,
         t.typepiece;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TRAITE_LIBNONENC" ("ID", "DATY", "TIERS", "BANQUE", "DATEECHEANCE", "ETAT", "MONTANT", "ETATVERSEMENT", "ETATVERSEMENTLIB", "MONTANTRESTE", "REFERENCE") AS
select ID,DATY,TIERS,BANQUE,DATEECHEANCE,ETAT,MONTANT, etatversement, etatversementlib,MONTANTRESTE,reference from TRAITEMTTRESTE where etatversement= 11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TRAITE_LIBV" ("ID", "DATY", "TIERS", "BANQUE", "DATEECHEANCE", "ETAT", "MONTANT", "ETATVERSEMENT", "ETATVERSEMENTLIB", "MONTANTRESTE", "REFERENCE") AS
select ID,DATY,TIERS,BANQUE,DATEECHEANCE,ETAT,MONTANT, etatversement, etatversementlib,MONTANTRESTE,reference from TRAITEMTTRESTE where etat = 11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TRAITE_LIBVER" ("ID", "DATY", "TIERS", "BANQUE", "DATEECHEANCE", "ETAT", "MONTANT", "ETATVERSEMENT", "ETATVERSEMENTLIB", "MONTANTRESTE", "REFERENCE") AS
select ID,DATY,TIERS,BANQUE,DATEECHEANCE,ETAT,MONTANT, etatversement, etatversementlib,MONTANTRESTE,reference from TRAITEMTTRESTE where etatversement= 11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TRANSFERTPOULETDETAIL_LIB" ("ID", "IDMERE", "IDSEXE", "IDFERMEDEPART", "IDBATIMENTDEPART", "IDPARQUETDEPART", "QTE", "IDFERMEARRIVE", "IDBATIMENTARRIVE", "IDPARQUETARRIVE", "IDCONTROLEUR", "IDCHAUFFEUR", "IDVEHICULE", "IDSEXELIB", "IDFERMEDEPARTLIB", "IDBATIMENTDEPARTLIB", "IDPARQUETDEPARTLIB", "IDFERMEARRIVELIB", "IDBATIMENTARRIVELIB", "IDPARQUETARRIVELIB", "IDCONTROLEURLIB", "IDCHAUFFEURLIB", "IDVEHICULELIB") AS
SELECT
    td."ID",td."IDMERE",td."IDSEXE",td."IDFERMEDEPART",td."IDBATIMENTDEPART",td."IDPARQUETDEPART",td."QTE",td."IDFERMEARRIVE",td."IDBATIMENTARRIVE",td."IDPARQUETARRIVE",td."IDCONTROLEUR",td."IDCHAUFFEUR",td."IDVEHICULE",
    s.val                              AS idSexeLib,
    mFermeDep.val                      AS idFermeDepartLib,
    bDep.nomBatiment                   AS idBatimentDepartLib,
    pDep.val                           AS idParquetDepartLib,
    mFermeArr.val                      AS idFermeArriveLib,
    bArr.nomBatiment                   AS idBatimentArriveLib,
    pArr.val                           AS idParquetArriveLib,
    (ctrl.nom || ' ' || ctrl.prenom)   AS idControleurLib,
    (chauf.nom || ' ' || chauf.prenom) AS idChauffeurLib,
    v.val                              AS idVehiculeLib
FROM transfertPouletDetail td
     LEFT JOIN sexe s              ON td.idSexe = s.id
     LEFT JOIN magasin2 mFermeDep  ON td.idFermeDepart = mFermeDep.id
     LEFT JOIN batiment bDep       ON td.idBatimentDepart = bDep.id
     LEFT JOIN parquet pDep        ON td.idParquetDepart = pDep.id
     LEFT JOIN magasin2 mFermeArr  ON td.idFermeArrive = mFermeArr.id
     LEFT JOIN batiment bArr       ON td.idBatimentArrive = bArr.id
     LEFT JOIN parquet pArr        ON td.idParquetArrive = pArr.id
     LEFT JOIN log_personnel ctrl  ON td.idControleur = ctrl.id
     LEFT JOIN log_personnel chauf ON td.idChauffeur = chauf.id
     LEFT JOIN vehicule v          ON td.idVehicule = v.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TRANSFERTPOULET_LIB" ("ID", "DATY", "IDLOT", "REMARQUE", "IDLOTLIB", "IDSOUCHELIB", "ETAT", "ETATLIB") AS
SELECT
    t."ID",t."DATY",t."IDLOT",t."REMARQUE",
    l.nomLot AS idLotLib,
    so.val AS idsouchelib,
    t.ETAT AS ETAT,
    CASE t.ETAT
        WHEN 1  THEN 'CREE'
        WHEN 11 THEN 'VALIDE'
        WHEN 0  THEN 'ANULLE'
        END AS ETATLIB
FROM transfertPoulet t
         LEFT JOIN lot l ON t.idLot = l.id
         LEFT JOIN SOUCHE so ON so.id=l.idsouche;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TRANSFERTSTOCKCPL" ("ID", "DESIGNATION", "IDMAGASINDEPART", "IDMAGASINDEPARTLIB", "IDMAGASINARRIVE", "IDMAGASINARRIVELIB", "DATY", "ETAT", "IDOF", "ETATLIB", "MONTANTQUANTITE") AS
SELECT
    t.ID ,
    t.DESIGNATION ,
    t.IDMAGASINDEPART ,
    m.VAL AS IDMAGASINDEPARTLIB,
    t.IDMAGASINARRIVE ,
    m2.VAL AS IDMAGASINARRIVELIB,
    t.DATY ,
    t.ETAT ,
    t.idof,
    CASE
        WHEN t.ETAT = 0
            THEN 'ANNUL&Eacute;'
        WHEN t.ETAT = 1
            THEN 'CR&Eacute;&Eacute;'
        WHEN t.ETAT = 11
            THEN 'VIS&Eacute;'
        END AS ETATLIB,
    CAST(tgm.montantQuantite AS NUMBER(30,2)) AS montantQuantite
FROM TRANSFERTSTOCK t
         LEFT JOIN MAGASINPOINT m ON m.ID = t.IDMAGASINDEPART
         LEFT JOIN MAGASINPOINT m2 ON m2.ID = t.IDMAGASINARRIVE
         LEFT JOIN TRANSTOCKDETAILSGROUPEMERE tgm ON tgm.IDTRANSFERTSTOCK = t.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TRANSFERTSTOCKCPL_ANNULEE" ("ID", "DESIGNATION", "IDMAGASINDEPART", "IDMAGASINDEPARTLIB", "IDMAGASINARRIVE", "IDMAGASINARRIVELIB", "DATY", "ETAT", "IDOF", "ETATLIB", "MONTANTQUANTITE") AS
(
	SELECT
		t.ID,t.DESIGNATION,t.IDMAGASINDEPART,t.IDMAGASINDEPARTLIB,t.IDMAGASINARRIVE,t.IDMAGASINARRIVELIB,t.DATY,t.ETAT,t.IDOF,t.ETATLIB,t.montantQuantite
	FROM
	TransfertStockCpl t
	WHERE t.etat=0
);

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TRANSFERTSTOCKCPL_CREE" ("ID", "DESIGNATION", "IDMAGASINDEPART", "IDMAGASINDEPARTLIB", "IDMAGASINARRIVE", "IDMAGASINARRIVELIB", "DATY", "ETAT", "IDOF", "ETATLIB", "MONTANTQUANTITE") AS
(
	SELECT
		t.ID,t.DESIGNATION,t.IDMAGASINDEPART,t.IDMAGASINDEPARTLIB,t.IDMAGASINARRIVE,t.IDMAGASINARRIVELIB,t.DATY,t.ETAT,t.IDOF,t.ETATLIB,t.montantQuantite
	FROM
	TransfertStockCpl t
	WHERE t.etat=1
);

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TRANSFERTSTOCKCPL_VISEE" ("ID", "DESIGNATION", "IDMAGASINDEPART", "IDMAGASINDEPARTLIB", "IDMAGASINARRIVE", "IDMAGASINARRIVELIB", "DATY", "ETAT", "IDOF", "ETATLIB", "MONTANTQUANTITE") AS
(
	SELECT
		t.ID,t.DESIGNATION,t.IDMAGASINDEPART,t.IDMAGASINDEPARTLIB,t.IDMAGASINARRIVE,t.IDMAGASINARRIVELIB,t.DATY,t.ETAT,t.IDOF,t.ETATLIB,montantQuantite
	FROM
	TransfertStockCpl t
	WHERE t.etat=11
);

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TRANSFERTSTOCKDETAILSCPL" ("ID", "IDTRANSFERTSTOCK", "IDTRANSFERTSTOCKLIB", "IDPRODUIT", "IDPRODUITLIB", "QUANTITE", "PU", "IDSOURCE", "UNITE") AS
SELECT
    t.ID ,
    t.IDTRANSFERTSTOCK ,
    t2.DESIGNATION AS IDTRANSFERTSTOCKLIB,
    t.IDPRODUIT ,
    p.libelle AS IDPRODUITLIB,
    CAST(t.QUANTITE AS NUMBER(30,5)) AS QUANTITE,
    CAST(t.PU AS NUMBER(30, 5)) AS PU,
    t.idsource,
    u.VAL as UNITE
FROM TRANSFERTSTOCKDETAILS t
         LEFT JOIN TRANSFERTSTOCK t2 ON t2.ID = t.IDTRANSFERTSTOCK
         LEFT JOIN AS_INGREDIENTS  p ON p.ID = t.IDPRODUIT
         left join AS_UNITE u on u.ID = p.UNITE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TRANSTOCKDETAILSGROUPEMERE" ("IDTRANSFERTSTOCK", "MONTANTQUANTITE") AS
select f.IDTRANSFERTSTOCK,cast(sum(nvl(f.pu*f.QUANTITE,0)) as number(30,2)) as montantQuantite
from TRANSFERTSTOCKDETAILS f group by f.IDTRANSFERTSTOCK;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TRAVAUXCPL" ("ID", "LANCEPAR", "CIBLE", "REMARQUE", "LIBELLE", "BESOIN", "DATY", "IDOFFILLE", "IDOF", "LANCEPARLIB", "CIBLELIB", "ETAT", "ETATLIB", "FABRICATIONPREC", "FABRICATIONSUIV", "IDINGREDIENTMAINTENANCE", "INGREDIENTMAINTENANCELIB") AS
SELECT
    f.ID,f.LANCEPAR,f.CIBLE,f.REMARQUE,f.LIBELLE,f.BESOIN,f.DATY,f.idOffille,nvl(f.idof, off.idmere) AS idof,
    p.val AS lanceparLib,
    p2.val AS cibleLib,
    f.etat AS etat,
    CASE
        WHEN f.ETAT=1
            THEN 'CR&Eacute;E'
        WHEN f.ETAT=11
            THEN 'VALID&Eacute;E'
        WHEN f.ETAT=0
            THEN 'ANNUL&Eacute;E'
        WHEN f.ETAT=21
            THEN 'ENTAM&Eacute;E'
        WHEN f.ETAT=31
            THEN 'BLOQU&Eacute;E'
        WHEN f.ETAT=41
            THEN 'TERMIN&Eacute;E'
        END AS ETATLIB,
    f.FABRICATIONPREC,
    f.FABRICATIONSUIV,
    off.idIngredients AS idIngredientMaintenance,
    off.remarque AS ingredientMaintenanceLib
FROM TRAVAUX f
         LEFT JOIN ENTITE p ON p.id = f.lancepar
         LEFT JOIN MAGASIN p2 ON p2.id = f.cible
         LEFT JOIN ORDRETRAVAUXFILLE off ON f.idoffille = off.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TRAVAUXCPLANNULE" ("ID", "LANCEPAR", "CIBLE", "REMARQUE", "LIBELLE", "BESOIN", "DATY", "IDOFFILLE", "IDOF", "LANCEPARLIB", "CIBLELIB", "ETAT", "ETATLIB", "FABRICATIONPREC", "FABRICATIONSUIV") AS
SELECT
    ID,LANCEPAR,CIBLE,REMARQUE,LIBELLE,BESOIN,DATY,IDOFFILLE,IDOF,LANCEPARLIB,CIBLELIB,ETAT,ETATLIB,FABRICATIONPREC,FABRICATIONSUIV
FROM TRAVAUXCPL f
WHERE etat = 0;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TRAVAUXCPLBLOQUEE" ("ID", "LANCEPAR", "CIBLE", "REMARQUE", "LIBELLE", "BESOIN", "DATY", "IDOFFILLE", "IDOF", "LANCEPARLIB", "CIBLELIB", "ETAT", "ETATLIB", "FABRICATIONPREC", "FABRICATIONSUIV") AS
SELECT
    ID,LANCEPAR,CIBLE,REMARQUE,LIBELLE,BESOIN,DATY,IDOFFILLE,IDOF,LANCEPARLIB,CIBLELIB,ETAT,ETATLIB,FABRICATIONPREC,FABRICATIONSUIV
FROM TRAVAUXCPL f
WHERE etat = 31;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TRAVAUXCPLCREE" ("ID", "LANCEPAR", "CIBLE", "REMARQUE", "LIBELLE", "BESOIN", "DATY", "IDOFFILLE", "IDOF", "LANCEPARLIB", "CIBLELIB", "ETAT", "ETATLIB", "FABRICATIONPREC", "FABRICATIONSUIV") AS
SELECT
    ID,LANCEPAR,CIBLE,REMARQUE,LIBELLE,BESOIN,DATY,IDOFFILLE,IDOF,LANCEPARLIB,CIBLELIB,ETAT,ETATLIB,FABRICATIONPREC,FABRICATIONSUIV
FROM TRAVAUXCPL f
WHERE etat = 1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TRAVAUXCPLENTAMEE" ("ID", "LANCEPAR", "CIBLE", "REMARQUE", "LIBELLE", "BESOIN", "DATY", "IDOFFILLE", "IDOF", "LANCEPARLIB", "CIBLELIB", "ETAT", "ETATLIB", "FABRICATIONPREC", "FABRICATIONSUIV") AS
SELECT
    ID,LANCEPAR,CIBLE,REMARQUE,LIBELLE,BESOIN,DATY,IDOFFILLE,IDOF,LANCEPARLIB,CIBLELIB,ETAT,ETATLIB,FABRICATIONPREC,FABRICATIONSUIV
FROM TRAVAUXCPL f
WHERE etat = 21;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TRAVAUXCPLTERMINEE" ("ID", "LANCEPAR", "CIBLE", "REMARQUE", "LIBELLE", "BESOIN", "DATY", "IDOFFILLE", "IDOF", "LANCEPARLIB", "CIBLELIB", "ETAT", "ETATLIB", "FABRICATIONPREC", "FABRICATIONSUIV") AS
SELECT
    ID,LANCEPAR,CIBLE,REMARQUE,LIBELLE,BESOIN,DATY,IDOFFILLE,IDOF,LANCEPARLIB,CIBLELIB,ETAT,ETATLIB,FABRICATIONPREC,FABRICATIONSUIV
FROM TRAVAUXCPL f
WHERE etat = 41;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TRAVAUXCPLVISEE" ("ID", "LANCEPAR", "CIBLE", "REMARQUE", "LIBELLE", "BESOIN", "DATY", "IDOFFILLE", "IDOF", "LANCEPARLIB", "CIBLELIB", "ETAT", "ETATLIB", "FABRICATIONPREC", "FABRICATIONSUIV") AS
SELECT
    ID,LANCEPAR,CIBLE,REMARQUE,LIBELLE,BESOIN,DATY,IDOFFILLE,IDOF,LANCEPARLIB,CIBLELIB,ETAT,ETATLIB,FABRICATIONPREC,FABRICATIONSUIV
FROM TRAVAUXCPL f
WHERE etat = 11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TRAVAUXFILLECPL" ("ID", "IDINGREDIENTS", "LIBELLE", "REMARQUE", "IDMERE", "DATYBESOIN", "QTE", "IDUNITE", "PU", "IDINGREDIENTSLIB", "OPERATEUR", "IDUNITELIB", "IDBCFILLE", "IDMACHINE", "IDMACHINELIB", "OPERATEURLIB") AS
SELECT
    f.ID,
    f.IDINGREDIENTS,
    f.LIBELLE,
    f.REMARQUE,
    f.IDMERE,
    f.DATYBESOIN,
    f.QTE,
    f.IDUNITE,
    f.PU,
    ai.LIBELLE AS idingredientsLib,
    p.NOM || ' - ' || p.TELEPHONE AS operateur,
    au.val AS IDUNITELIB,
    f.IDBCFILLE ,
    f.IDMACHINE,
    m.val AS IDMACHINELIB,
    p2.NOM AS OPERATEURLiB
FROM
    TRAVAUXFILLE f
        LEFT JOIN AS_INGREDIENT_MAINTENANCE ai ON
        ai.id = f.IDINGREDIENTS
        LEFT JOIN PERSONNEL p ON
        p.ID = f.OPERATEUR
        LEFT JOIN AS_UNITE au ON
        au.id = f.IDUNITE
        LEFT JOIN MACHINE m ON
        m.ID = f.IDMACHINE
        LEFT JOIN PERSONNEL p2 ON
        p2.id = f.OPERATEUR;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TRAVAUXMEREFILLE" ("IDINGREDIENTS", "IDINGREDIENTSLIB", "QTE", "IDUNITE", "IDOFFILLE", "IDOF", "LIBELLE", "DATY", "IDBCFILLE") AS
SELECT
    ff.IDINGREDIENTS,
    ff.IDINGREDIENTSLIB ,
    sum(ff.QTE) qte,
    ff.IDUNITE ,
    f.idOffille,
    f.IDOF,
    f.LIBELLE,
    f.DATY,
    ff.IDBCFILLE
FROM
    TRAVAUXFILLECPL ff
        JOIN TRAVAUX f ON
        f.id = ff.IDMERE
WHERE
    f.etat = 11
GROUP BY
    ff.IDINGREDIENTS,
    ff.IDINGREDIENTSLIB ,
    ff.IDUNITE ,
    f.idOffille,
    f.LIBELLE,
    f.DATY,
    ff.IDBCFILLE,
    f.IDOF;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TRAVAUX_RECAP" ("ID", "MONTANTCHARGEEXTERNE", "MONTANTPIECE", "MONTANTMAINDOEUVRE", "MONTANTTOTAL") AS
WITH fac_agg AS (
  SELECT idtravaux,
         SUM(NVL(montantttc, 0)) AS montantChargeExterne
  FROM FACTUREFOURNISSEURCPL_TRAVAUX
  GROUP BY idtravaux
),
mvt_agg AS (
  SELECT idobjet,
         SUM(NVL(montantsortie, 0)) AS montantPiece
  FROM MVTSTOCKLIB
  GROUP BY idobjet
),
pm_agg AS (
  SELECT idtravaux,
         SUM(NVL(montantreel, 0)) AS montantMainDoeuvre
  FROM RAPPROCHEMENTTRAVAUX
  GROUP BY idtravaux
)
SELECT t.id,
       NVL(fac_agg.montantChargeExterne, 0) AS montantChargeExterne,
       NVL(mvt_agg.montantPiece, 0)         AS montantPiece,
       NVL(pm_agg.montantMainDoeuvre, 0)    AS montantMainDoeuvre,
       NVL(fac_agg.montantChargeExterne, 0)
           + NVL(mvt_agg.montantPiece, 0)
           + NVL(pm_agg.montantMainDoeuvre, 0)    AS montantTotal
FROM TRAVAUX t
         LEFT JOIN fac_agg ON fac_agg.idtravaux = t.id
         LEFT JOIN mvt_agg ON mvt_agg.idobjet   = t.id
         LEFT JOIN pm_agg  ON pm_agg.idtravaux  = t.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TRIAGEBATIMENTPARQUET_LIB" ("ID", "DATY", "IDLOT", "DISPOMALE", "DISPOFEMELLE", "IDLOTLIB", "IDSOUCHELIB", "ETAT", "ETATLIB", "ECARTFEMELLE", "ECARTMALE") AS
SELECT t.ID, t.DATY, t.IDLOT, t.DISPOMALE, t.DISPOFEMELLE,
       l.NOMLOT AS IDLOTLIB,
       s.val AS idsouchelib,
       t.etat AS etat,
       CASE
           WHEN t.ETAT = 1  THEN 'CR&Eacute;&Eacute;'
           WHEN t.ETAT = 11 THEN 'VALID&Eacute;'
           END AS ETATLIB,
       NVL(t.DISPOFEMELLE - (SELECT SUM(d.QTE)
            FROM TRIAGEBATIMENTPARQUETDETAIL d
            WHERE d.IDMERE = t.ID
              AND d.IDQUALITE = 'QP000001'
              AND d.IDSEXE = '0'), 0) AS ecartFemelle,
       NVL(t.DISPOMALE - (SELECT SUM(d.QTE)
            FROM TRIAGEBATIMENTPARQUETDETAIL d
            WHERE d.IDMERE = t.ID
              AND d.IDQUALITE = 'QP000001'
              AND d.IDSEXE = '1'), 0) AS ecartMale
FROM TRIAGEBATIMENTPARQUET t
         LEFT JOIN LOT l ON l.ID = t.IDLOT
         LEFT JOIN SOUCHE s ON s.id = l.idsouche;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TRIAGEBATPARQUETDETAIL_LIB" ("ID", "IDMERE", "IDBATIMENT", "IDPARQUET", "IDSEXE", "IDQUALITE", "QTE", "IDBATIMENTLIB", "IDPARQUETLIB", "IDSEXELIB", "IDQUALITELIB", "IDLOT") AS
SELECT d."ID",d."IDMERE",d."IDBATIMENT",d."IDPARQUET",d."IDSEXE",d."IDQUALITE",d."QTE",
       b."NOMBATIMENT"  AS "IDBATIMENTLIB",
       p."VAL"  AS "IDPARQUETLIB",
       sx."VAL" AS "IDSEXELIB",
       q."VAL"  AS "IDQUALITELIB",
    	t.idlot AS idlot
FROM "TRIAGEBATIMENTPARQUETDETAIL" d
         LEFT JOIN "BATIMENT" b ON b."ID" = d."IDBATIMENT"
         LEFT JOIN "PARQUET" p ON p."ID" = d."IDPARQUET"
         LEFT JOIN "SEXE" sx ON sx."ID" = d."IDSEXE"
         LEFT JOIN "QUALITEPOUSSIN" q ON q."ID" = d."IDQUALITE"
		LEFT JOIN TRIAGEBATIMENTPARQUET t ON t.id=d.idmere;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TRIAGEOEUFDETAIL_LIB" ("ID", "IDMERE", "IDTYPECOLLECTE", "IDQUALITETRIAGEOEUF", "QTE", "IDDESTINATION", "IDTYPECOLLECTELIB", "IDQUALITETRIAGEOEUFLIB", "IDDESTINATIONLIB") AS
SELECT d."ID",
       d."IDMERE",
       d."IDTYPECOLLECTE",
       d."IDQUALITETRIAGEOEUF",
       d."QTE",
       d."IDDESTINATION",
       tc."VAL" AS "IDTYPECOLLECTELIB",
       qt."VAL" AS "IDQUALITETRIAGEOEUFLIB",
       m."VAL"  AS "IDDESTINATIONLIB"
FROM "TRIAGEOEUFDETAIL" d
         LEFT JOIN "TYPECOLLECTE" tc ON tc."ID" = d."IDTYPECOLLECTE"
         LEFT JOIN "QUALITETRIAGEOEUF" qt ON qt."ID" = d."IDQUALITETRIAGEOEUF"
         LEFT JOIN "MAGASIN2" m ON m."ID" = d."IDDESTINATION";

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TRIAGEOEUF_LIB" ("ID", "DATY", "HEUREDEPART", "IDOPERATEUR", "IDNUMEROCOLLECTE", "IDBATIMENT", "IDPARQUET", "OEUFTOTAL", "POIDSMOYENOEUFS", "IDOPERATEURLIB", "IDNUMEROCOLLECTELIB", "IDBATIMENTLIB", "IDPARQUETLIB", "ETAT", "ETATLIB", "ECART") AS
SELECT
    t.ID,
    t.DATY,
    t.HEUREDEPART,
    t.IDOPERATEUR,
    t.IDNUMEROCOLLECTE,
    t.IDBATIMENT,
    t.IDPARQUET,
    t.OEUFTOTAL,
    t.POIDSMOYENOEUFS,
 
    lp.NOM || ' ' || lp.PRENOM AS IDOPERATEURLIB,
 
    nc.VAL AS IDNUMEROCOLLECTELIB,
 
    b.NOMBATIMENT AS IDBATIMENTLIB,
 
    p.VAL AS IDPARQUETLIB,
 
    t.ETAT,
 
    CASE
        WHEN t.ETAT = 1 THEN 'CREE'
        WHEN t.ETAT = 0 THEN 'ANNULEE'
        WHEN t.ETAT = 11 THEN 'VISEE'
    END AS ETATLIB,
    t.OEUFTOTAL - COALESCE(td.QTE_TOTAL, 0) AS ECART

FROM TRIAGEOEUF t
 
LEFT JOIN LOG_PERSONNEL lp
    ON lp.ID = t.IDOPERATEUR
 
LEFT JOIN NUMEROCOLLECTE nc
    ON nc.ID = t.IDNUMEROCOLLECTE
 
LEFT JOIN BATIMENT b
    ON b.ID = t.IDBATIMENT
 
LEFT JOIN PARQUET p
    ON p.ID = t.IDPARQUET

LEFT JOIN V_TRIAGEOEUFDETAIL_AGG td ON td.IDMERE = t.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TRIAGEQUALITEPOUSSINDETAIL_LIB" ("ID", "IDMERE", "IDBATIMENT", "IDPARQUET", "IDQUALITE", "QTE", "IDBATIMENTLIB", "IDPARQUETLIB", "IDQUALITELIB") AS
SELECT 
	tqpd.id,
	tqpd.idmere,
	tqpd.idbatiment,
	tqpd.idparquet,
	tqpd.idqualite,
	tqpd.qte,
	b.NOMBATIMENT AS idBatimentLib,
	p.VAL AS idParquetLib,
	q.VAL AS idQualiteLib
FROM 
	triageQualitePoussinDetail tqpd
LEFT JOIN BATIMENT b ON tqpd.idbatiment = b.ID
LEFT JOIN PARQUET p ON tqpd.idparquet = p.ID
LEFT JOIN QUALITEPOUSSIN q ON tqpd.idqualite = q.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TRIAGEQUALITEPOUSSIN_LIB" ("ID", "IDLOT", "DATY", "QTEPOUSSINACONTROLER", "IDECLOSOIR", "IDINCUBATEUR", "IDLOTLIB", "IDECLOSOIRLIB", "IDINCUBATEURLIB", "ETAT", "ETATLIB") AS
SELECT
	tqp.id,
	tqp.idlot,
	tqp.daty,
	tqp.QTEPOUSSINACONTROLER,
	tqp.IDECLOSOIR,
	tqp.IDINCUBATEUR,
    l.nomlot AS idLotLib,
    e.VAL AS idEclosoirLib,
    i.VAL AS idIncubateurLib,
    tqp.etat,
    CASE
        WHEN tqp.etat = 1 THEN 'CREE'
        WHEN tqp.etat = 0 THEN 'ANNULEE'
        WHEN tqp.etat = 11 THEN 'VISEE'
    END AS etatLib
FROM
	triageQualitePoussin tqp
LEFT JOIN lot l ON tqp.IDLOT = l.id
LEFT JOIN ECLOSOIR e ON tqp.IDECLOSOIR = e.id
LEFT JOIN INCUBATEUR i ON tqp.IDINCUBATEUR = i.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TYPEABSENCE_CPL" ("ID", "VAL", "DESCE", "NBJOUR", "FREQUENCE", "ETAT", "FREQUENCELIB", "ETATLIB") AS
SELECT
    typ."ID",typ."VAL",typ."DESCE",typ."NBJOUR",typ."FREQUENCE",typ."ETAT",
    fc.val AS frequencelib,
    CASE
        WHEN typ.etat=1 THEN 'CR&Eacute;&Eacute;'
        WHEN typ.etat=11 THEN 'VALID&Eacute;'
        END AS etatlib
FROM type_absence typ
         LEFT JOIN frequence_conge fc ON fc.id=typ.frequence;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TYPEMAGASIN_SANSRESERVOIR" ("ID", "VAL", "DESCE") AS
SELECT 
t."ID",t."VAL",t."DESCE"
FROM TYPEMAGASIN t  
WHERE t.ID  != 'TYPMG000001';

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TYPEMAINTENANCETRAVAUX" ("ID", "VAL", "DESCE") AS
(
    SELECT
        t.id,
        dc.IDTYPEMAINTENANCE AS val,
        dc.IDTYPEMAINTENANCELIB AS desce
    FROM
    TRAVAUX t
    LEFT JOIN DEMANDETRAVAUX_CPL dc ON dc.IDOTFILLE =t.IDOFFILLE
);

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TYPE_PRODUIT_ACTIF" ("ID", "VAL", "DESCE", "IDLIGNE", "ACTIF") AS
select "ID","VAL","DESCE","IDLIGNE","ACTIF" from TYPE_PRODUIT where ACTIF=1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TYPE_PRODUIT_LIB" ("ID", "VAL", "DESCE", "IDCATEGORIE", "IDCATEGORIELIB") AS
SELECT tp.ID,
       tp.VAL,
       tp.DESCE,
       '' as IDCATEGORIE,
       '' as IDCATEGORIELIB
FROM TYPE_PRODUIT tp;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."UNITES_TRAIT" ("ID", "VAL", "DESCE") AS
select ''  as id,
       '-' as val,
       '-' as desce
from DUAL
union
select su."ID", su."VAL", su."DESCE"
from ST_UNITE su;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."UPDATEVENTE" ("ID", "DESIGNATION", "IDMAGASIN", "DATY", "REMARQUE", "ETAT", "IDORIGINE", "IDCLIENT", "IDCLIENTLIB", "IDDEVISE", "IDRESERVATION", "DATYPREVU", "ECHEANCEFACTURE", "ESTPREVU") AS
SELECT
	v.ID,
	v.DESIGNATION,
	v.IDMAGASIN,
	v.DATY,
	v.REMARQUE,
	v.ETAT,
	v.IDORIGINE,
	v.IDCLIENT,
	c.NOM AS idClientLib,
	v2.IDDEVISE,
	v.IDRESERVATION,
	v.DATYPREVU ,
	v.ECHEANCEFACTURE,
	v.ESTPREVU
FROM VENTE v
JOIN CLIENT c ON c.ID = v.IDCLIENT
JOIN VENTEMONTANT v2 ON v2.ID = v.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."UPDATEVENTEDETAILS" ("ID", "IDVENTE", "IDPRODUIT", "IDPRODUITLIB", "IDORIGINE", "QTE", "PU", "REMISE", "TVA", "PUACHAT", "PUVENTE", "IDDEVISE", "TAUXDECHANGE", "DESIGNATION", "COMPTE", "IDPREVISION") AS
SELECT
	vd.ID,
	vd.IDVENTE,
	vd.IDPRODUIT,
	p.LIBELLE AS idProduitLib,
	vd.IDORIGINE,
	vd.QTE,
	vd.PU,
	vd.REMISE,
	vd.TVA,
	vd.PUACHAT,
	vd.PUVENTE,
	vd.IDDEVISE,
	vd.TAUXDECHANGE,
	vd.DESIGNATION,
	vd.COMPTE,
	vd.idprevision
FROM
	VENTE_DETAILS vd
LEFT JOIN AS_INGREDIENTS p ON
	p.ID = vd.IDPRODUIT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."UTILISATEURCPL" ("REFUSER", "IDROLE", "ADRUSER", "NOMUSER", "LOGINUSER", "PWDUSER", "TELUSER", "DIRECTIONLIB", "IDPERSONNEL", "NOMPERSONNEL") AS
SELECT
    u.REFUSER,
    u.IDROLE,
    u.ADRUSER,
    u.NOMUSER,
    u.LOGINUSER,
    u.PWDUSER,
    u.TELUSER,
    dir.DESCDIR AS directionLib,
    log.id AS idPersonnel,
    log.nom || ' ' || log.prenom AS nomPersonnel
FROM UTILISATEUR u
         LEFT JOIN direction dir ON dir.iddir = u.ADRUSER
         JOIN LOG_PERSONNEL log ON log.refuser = u.REFUSER;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."UTILISATEURROLE" ("REFUSER", "LOGINUSER", "PWDUSER", "NOMUSER", "ADRUSER", "TELUSER", "IDROLE", "ID", "RANG") AS
select u.refuser,u.LOGINUSER,u.PWDUSER,u.NOMUSER,d.ID as adruser,u.TELUSER,u.IDROLE,
       s.ID, r.rang
from utilisateur u, log_direction d, roles r, log_service s, log_personnel p, annulationutilisateur a
where u.TELUSER = p.ID
  and p.DIRECTION = d.id
  and p.SERVICE = s.id
  and u.IDROLE = r.IDROLE and
    u.refuser = a.REFUSER(+) and a.REFUSER is null;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."UTILISATEURVALIDE" ("REFUSER", "LOGINUSER", "PWDUSER", "NOMUSER", "ADRUSER", "TELUSER", "IDROLE", "RANG") AS
SELECT u.REFUSER, u.LOGINUSER, u.PWDUSER, u.NOMUSER, u.ADRUSER, u.TELUSER,
       u.IDROLE,r.RANG
FROM utilisateur u ,ROLES r , annulationutilisateur a
WHERE u.IDROLE = r.IDROLE and
    u.refuser = a.REFUSER(+) and a.REFUSER is null;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."UTILISATEURVUE" ("REFUSER", "LOGINUSER", "PWDUSER", "NOMUSER", "ADRUSER", "TELUSER", "IDROLE", "RANG") AS
SELECT
    u.refuser,
    u.LOGINUSER,
    u.PWDUSER,
    u.NOMUSER,
    d.LIBELLEDIR AS adruser,
    u.TELUSER,
    u.IDROLE,
    r.RANG
FROM utilisateur u
         JOIN direction d ON u.ADRUSER = d.IDDIR
         LEFT JOIN roles r ON r.IDROLE = u.IDROLE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."UTILISATEURVUEFICHE_ID" ("REFUSER", "LOGINUSER", "PWDUSER", "NOMUSER", "ADRUSER", "TELUSER", "IDROLE") AS
SELECT u.refuser AS refuser,
       u.loginuser,
       u.pwduser,
       u.nomuser,
       d.DESCDIR AS adruser,
       u.teluser,
       u.idrole
FROM utilisateur u,
     direction d
WHERE u.adruser = d.IDDIR;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."UTILISATEUR_ACTIONROLE" ("ID", "LOGINUSER", "PWDUSER", "NOMUSER", "ADRUSER", "TELUSER", "IDROLE", "RANG") AS
SELECT
    u.refuser AS id,
    u.LOGINUSER,
    u.PWDUSER,
    u.NOMUSER,
    d.LIBELLEDIR AS adruser,
    u.TELUSER,
    u.IDROLE,
    r.RANG
FROM utilisateur u
         JOIN direction d ON u.ADRUSER = d.IDDIR
         LEFT JOIN roles r ON r.IDROLE = u.IDROLE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V1_OSTIE_AFFICHE_T1" ("NUMERO", "MATRICULE", "NOM", "PRENOMS", "SEXE", "DATE_NAISSANCE", "DATEEMBAUCHE", "DATE_DEPART", "FONCTION", "CNAPS", "CIN", "MOIS1", "MOIS2", "MOIS3", "SALAIRES_NON_PLAFONNES", "SALAIRES_PLAFONNES", "EMPLOYEUR", "TRAVAILLEUR", "TOTAL", "ANNEE", "DIRECTION") AS
SELECT
    rownum as numero,
    lpad(pip.matricule,5,'0') as matricule,
    Upper(trim(trailing ' ' from lp.NOM)) as nom,
    Upper(trim(trailing ' ' from lp.prenom)) as prenoms,
    sexe.val as sexe,
    lp.date_naissance,
    pip.dateembauche,
    case
        when extract(year from pip.date_depart)=nvl(s3.annee,nvl(s2.annee,nvl(s1.annee,0)))
            and (
                 extract(month from pip.date_depart) = 1
                     or
                 extract(month from pip.date_depart) = 2
                     or
                 extract(month from pip.date_depart) = 3
                 ) then pip.date_depart
        else
            null
        end as date_depart,
    upper(paf.desce) as fonction,
    upper(pip.NUMERO_CNAPS) as cnaps,
    lp.numero_cin as cin,
    nvl(s1.salairebase,0) as mois1,
    nvl(s2.salairebase,0) as mois2,
    nvl(s3.salairebase,0) as mois3,
    (nvl(s1.salairebase, 0)+nvl(s2.salairebase, 0)+nvl(s3.salairebase, 0)) as salaires_non_plafonnes,
    (
        case
            when nvl(s1.salairebase,0) >= (select cast(valmin as number) as maximum from configuration where id = 'CONF000140')
                then (select cast(valmin as number) as maximum from configuration where id = 'CONF000140')
            else
                nvl(s1.salairebase,0)
            end
        )+
    (
        case
            when nvl(s2.salairebase,0) >= (select cast(valmin as number) as maximum from configuration where id = 'CONF000140')
                then (select cast(valmin as number) as maximum from configuration where id = 'CONF000140')
            else
                nvl(s2.salairebase,0)
            end
        )+
    (
        case
            when nvl(s3.salairebase,0) >= (select cast(valmin as number) as maximum from configuration where id = 'CONF000140')
                then (select cast(valmin as number) as maximum from configuration where id = 'CONF000140')
            else
                nvl(s3.salairebase,0)
            end
        ) as salaires_plafonnes,
    nvl(ostie.retenue,0)*5 as employeur,
    nvl(ostie.retenue,0) as travailleur,
    (nvl(ostie.retenue,0)*5)+nvl(ostie.retenue,0) as total,
    ostie.annee,
    ostie.direction
FROM log_personnel lp
         JOIN paie_info_personnel pip ON pip.id=lp.id
         JOIN log_direction ld ON ld.id=lp.direction
         JOIN paie_fonction paf ON paf.id = pip.idfonction
         JOIN sexe ON sexe.id = lp.sexe
         LEFT JOIN
     (SELECT sum(round(retenue,0)) as retenue,idpersonnel,annee,direction FROM paie_edition WHERE
         (mois = 1 or mois=2 or mois =3) AND etat=11 AND IDELEMENTPAIE ='PRU000I710'
      group by idpersonnel,annee,direction) ostie
     ON ostie.idpersonnel = lp.id
         LEFT JOIN
     (select * from salairebasemois where mois = 1) s1
     ON lp.id = s1.idpersonnel and ostie.annee= s1.annee
         LEFT JOIN
     (select * from salairebasemois where mois = 2) s2
     ON lp.id = s2.idpersonnel and ostie.annee = s2.annee
         LEFT JOIN
     (select * from salairebasemois where mois = 3) s3
     ON lp.id = s3.idpersonnel and ostie.annee=s3.annee
WHERE nvl(ostie.retenue,0)!=0
ORDER BY annee,pip.matricule;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V1_OSTIE_AFFICHE_T2" ("NUMERO", "MATRICULE", "NOM", "PRENOMS", "SEXE", "DATE_NAISSANCE", "DATEEMBAUCHE", "DATE_DEPART", "FONCTION", "CNAPS", "CIN", "MOIS1", "MOIS2", "MOIS3", "SALAIRES_NON_PLAFONNES", "SALAIRES_PLAFONNES", "EMPLOYEUR", "TRAVAILLEUR", "TOTAL", "ANNEE", "DIRECTION") AS
SELECT
    rownum as numero,
    lpad(pip.matricule,5,'0') as matricule,
    Upper(trim(trailing ' ' from lp.NOM)) as nom,
    Upper(trim(trailing ' ' from lp.prenom)) as prenoms,
    sexe.val as sexe,
    lp.date_naissance,
    pip.dateembauche,
    case
        when extract(year from pip.date_depart)=nvl(s3.annee,nvl(s2.annee,nvl(s1.annee,0)))
            and (
                 extract(month from pip.date_depart) = 4
                     or
                 extract(month from pip.date_depart) = 5
                     or
                 extract(month from pip.date_depart) = 6
                 ) then pip.date_depart
        else
            null
        end as date_depart,
    upper(paf.desce) as fonction,
    upper(pip.NUMERO_CNAPS) as cnaps,
    lp.numero_cin as cin,
    nvl(s1.salairebase,0) as mois1,
    nvl(s2.salairebase,0) as mois2,
    nvl(s3.salairebase,0) as mois3,
    (nvl(s1.salairebase, 0)+nvl(s2.salairebase, 0)+nvl(s3.salairebase, 0)) as salaires_non_plafonnes,
    (
        case
            when nvl(s1.salairebase,0) >= (select cast(valmin as number) as maximum from configuration where id = 'CONF000140')
                then (select cast(valmin as number) as maximum from configuration where id = 'CONF000140')
            else
                nvl(s1.salairebase,0)
            end
        )+
    (
        case
            when nvl(s2.salairebase,0) >= (select cast(valmin as number) as maximum from configuration where id = 'CONF000140')
                then (select cast(valmin as number) as maximum from configuration where id = 'CONF000140')
            else
                nvl(s2.salairebase,0)
            end
        )+
    (
        case
            when nvl(s3.salairebase,0) >= (select cast(valmin as number) as maximum from configuration where id = 'CONF000140')
                then (select cast(valmin as number) as maximum from configuration where id = 'CONF000140')
            else
                nvl(s3.salairebase,0)
            end
        ) as salaires_plafonnes,
    nvl(ostie.retenue,0)*5 as employeur,
    nvl(ostie.retenue,0) as travailleur,
    (nvl(ostie.retenue,0)*5)+nvl(ostie.retenue,0) as total,
    ostie.annee,
    ostie.direction
FROM log_personnel lp
         JOIN paie_info_personnel pip ON pip.id=lp.id
         JOIN log_direction ld ON ld.id=lp.direction
         JOIN paie_fonction paf ON paf.id = pip.idfonction
         JOIN sexe ON sexe.id = lp.sexe
         LEFT JOIN
     (SELECT sum(round(retenue,0)) as retenue,idpersonnel,annee,direction FROM paie_edition WHERE
         (mois = 4 or mois=5 or mois =6) AND etat=11 AND IDELEMENTPAIE ='PRU000I710'
      group by idpersonnel,annee,direction) ostie
     ON ostie.idpersonnel = lp.id
         LEFT JOIN
     (select * from salairebasemois where mois = 4) s1
     ON lp.id = s1.idpersonnel and ostie.annee= s1.annee
         LEFT JOIN
     (select * from salairebasemois where mois = 5) s2
     ON lp.id = s2.idpersonnel and ostie.annee = s2.annee
         LEFT JOIN
     (select * from salairebasemois where mois = 6) s3
     ON lp.id = s3.idpersonnel and ostie.annee=s3.annee
WHERE nvl(ostie.retenue,0)!=0
ORDER BY annee,pip.matricule;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V1_OSTIE_AFFICHE_T3" ("NUMERO", "MATRICULE", "NOM", "PRENOMS", "SEXE", "DATE_NAISSANCE", "DATEEMBAUCHE", "DATE_DEPART", "FONCTION", "CNAPS", "CIN", "MOIS1", "MOIS2", "MOIS3", "SALAIRES_NON_PLAFONNES", "SALAIRES_PLAFONNES", "EMPLOYEUR", "TRAVAILLEUR", "TOTAL", "ANNEE", "DIRECTION") AS
SELECT
    rownum as numero,
    lpad(pip.matricule,5,'0') as matricule,
    Upper(trim(trailing ' ' from lp.NOM)) as nom,
    Upper(trim(trailing ' ' from lp.prenom)) as prenoms,
    sexe.val as sexe,
    lp.date_naissance,
    pip.dateembauche,
    case
        when extract(year from pip.date_depart)=nvl(s3.annee,nvl(s2.annee,nvl(s1.annee,0)))
            and (
                 extract(month from pip.date_depart) = 7
                     or
                 extract(month from pip.date_depart) = 8
                     or
                 extract(month from pip.date_depart) = 9
                 ) then pip.date_depart
        else
