CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VENTE_CPL_AVEC_MONTANT_USD" ("ID", "DESIGNATION", "IDMAGASIN", "DATY", "REMARQUE", "ETAT", "IDORIGINE", "IDCLIENT", "IDCLIENTLIB", "IDMAGASINLIB", "MONTANTTC", "MONTANTTTC", "MONTANTPAYE", "ENCAISSEMENTCHANGE", "MONTANTRESTE", "IDDEVISE", "IDRESERVATION") AS
SELECT
v.ID,v.DESIGNATION,v.IDMAGASIN,v.DATY,v.REMARQUE,v.ETAT,v.IDORIGINE,v.IDCLIENT,
