CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VENTE_CPL_BC_VISEE" ("ID", "DESIGNATION", "IDMAGASIN", "IDMAGASINLIB", "DATY", "REMARQUE", "ETAT", "ETATLIB", "MONTANTTOTAL", "IDDEVISE", "IDCLIENT", "CLIENTLIB", "MONTANTTVA", "MONTANTTTC", "MONTANTTTCAR", "MONTANTPAYE", "MONTANTRESTE", "AVOIR", "TAUXDECHANGE", "MONTANTREVIENT", "MARGEBRUTE", "IDRESERVATION", "IDORIGINE", "MONTANTAVOIR") AS
SELECT v.ID,
       v.DESIGNATION,
       v.IDMAGASIN,
       m.VAL AS IDMAGASINLIB,
       v.DATY,
       v.REMARQUE,
       v.ETAT,
       CASE
           WHEN v.ETAT = 1 THEN 'CREE'
           WHEN v.ETAT = 11 THEN 'VISEE'
           WHEN v.ETAT = 0 THEN 'ANNULEE'
           END
             AS ETATLIB,
       v2.MONTANTTOTAL,
       v2.IDDEVISE,
       v.IDCLIENT,
       c.NOM AS CLIENTLIB,
       cast(V2.MONTANTTVA as number(30,2)) as MONTANTTVA,
       cast(V2.MONTANTTTC as number(30,2)) as montantttc,
       cast(V2.MONTANTTTCAR as number(30,2)) as MONTANTTTCAR,
       cast(nvl(mv.MONTANT,0)-nvl(ACG.MONTANTPAYEar, 0) AS NUMBER(30,2)) AS montantpaye,
       cast(V2.MONTANTTTC-nvl(mv.MONTANT,0)-nvl(ACG.MONTANTTTCAR, 0)+nvl(acg.MONTANTPAYEAR,0) AS NUMBER(30,2)) AS montantreste,
       nvl(ACG.MONTANTTTCAR, 0)  as avoir,
       v2.tauxDeChange AS tauxDeChange,v2.MONTANTREVIENT,cast((V2.MONTANTTTCAR-v2.MONTANTREVIENT) as number(20,2))  as margeBrute,
       v.IDRESERVATION,
       v.idorigine as IDORIGINE,
       cast(nvl(ACG.MONTANTTTCAR, 0)  as NUMBER(30,2)) as montantAvoir
FROM VENTE v
         LEFT JOIN CLIENT c ON c.ID = v.IDCLIENT
         LEFT JOIN MAGASIN m ON m.ID = v.IDMAGASIN
         JOIN VENTEMONTANTLEGER v2 ON v2.ID = v.ID
         LEFT JOIN LIAISONPAIEMENTTOTAL mv ON v.id=mv.ID2
         LEFT JOIN AVOIRFCMONTANT ACG on ACG.IDVENTE = v.ID
         --left join AS_BONDELIVRAISON_CLIENT asbl on asbl.ID = v.IDORIGINE
where v.ETAT = 11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VENTE_CPL_CL" ("ID", "DESIGNATION", "IDMAGASIN", "IDMAGASINLIB", "DATY", "REMARQUE", "ETAT", "ETATLIB", "MONTANTTOTAL", "IDDEVISE", "IDCLIENT", "IDCLIENTLIB", "MONTANTTVA", "MONTANTTTC", "MONTANTTTCAR", "MONTANTPAYE", "MONTANTRESTE", "AVOIR", "TAUXDECHANGE", "MONTANTREVIENT", "MARGEBRUTE", "IDRESERVATION", "DATYPREVU", "REFERENCEFACTURE", "MONTANTREMISE", "MONTANT", "MOIS", "ANNEE", "POIDS", "COLIS", "MODEPAIEMENT", "MODEPAIEMENTLIB", "FRAISLIVRAISON", "MODELIVRAISON", "MODELIVRAISONLIB", "RESTE", "IDPROVINCE", "PROVINCELIB", "IDORIGINE", "FRAIS", "REFERENCEFACT", "NUMEROFACTURE", "LIEULIVRAISON", "DATELIVRAISON", "UPDATED_AT", "ESTPREVULIB", "IDECRITURE", "DATEDELIVRAISON", "ADRESSE") AS
SELECT v.ID,
       v.DESIGNATION,
       v.IDMAGASIN,
       m.VAL                                                                                         AS IDMAGASINLIB,
       v.DATY,
       v.REMARQUE,
       v.ETAT,
       CASE
           WHEN v.ETAT = 1 THEN 'CR&Eacute;&Eacute;E'
           WHEN v.ETAT = 11 THEN 'VIS&Eacute;E'
           WHEN v.ETAT = 0 THEN 'ANNUL&Eacute;E'
           END
                                                                                                     AS ETATLIB,
       cast(v2.MONTANTTOTAL as number(30, 5)) AS MONTANTTOTAL,
       v2.IDDEVISE,
       v.IDCLIENT,
       c.NOM                                                                                         AS IDCLIENTLIB,
       cast(V2.MONTANTTVA as number(30, 5))                                                          as MONTANTTVA,
       cast(V2.MONTANTTTC as number(30, 5))                                                          as montantttc,
       cast(V2.MONTANTTTCAR as number(30, 5))                                                        as MONTANTTTCAR,
       cast(nvl(mv.montant, 0) AS number(30, 5))                                                     AS montantpaye,
       cast(nvl(V2.MONTANTTTC, 0) - nvl(mv.montant, 0) - nvl(ACG.imputeefactar, 0) AS number(30, 5)) AS montantreste,
       cast(nvl(ACG.MONTANTTTC_avr, 0) as number(30, 5))                                             as avoir,
       cast(v2.tauxDeChange as number(10, 2))                                                                        AS tauxDeChange,
       cast(v2.MONTANTREVIENT as number(20, 5)) AS MONTANTREVIENT  ,
       cast((V2.MONTANTTTCAR - v2.MONTANTREVIENT) as number(20, 5))                                  as margeBrute,
       v.IDRESERVATION,
       case when v.DATYPREVU is null then v.daty else V.DATYPREVU end                                as datyprevu,
       rf.REFERENCE                                                                                  as referencefacture,
       cast(v2.MONTANTREMISE as number(30, 5)) AS MONTANTREMISE,
       cast(nvl(v2.MONTANTTOTAL, 0) + nvl(v2.MONTANTREMISE, 0) as number(30, 5))                                             as montant,
       extract(month from v.DATY)                                                                    as mois,
       extract(year from v.DATY)                                                                     as annee,
       CAST(vp.poids as number(30, 5))                                                               as poids,
       CAST(vp.colis as number(30, 5))                                                               as colis,
       v.modepaiement,
       mp.VAL                                                                                        as modepaiementlib,
       nvl(v.fraislivraison, 0) * nvl(vp.poids, 0)                                                   as fraislivraison,
       v.modelivraison,
       CASE
           WHEN v.modelivraison = 1 THEN '<span style=color: green;>LIVRAISON</span>'
           WHEN v.modelivraison = 2 THEN '<span style=color: green;>RECUPERATION</span>'
           END                                                                                       AS modelivraisonlib,
       cast(vr.reste  as number(30, 5)) AS reste,
       pv.id                                                                                         as idprovince,
       pv.val                                                                                        as provincelib,
       --bl.id                                                                                         as idbl,
       v.IDORIGINE,
       CAST(COALESCE(v.FRAISLIVRAISON,0) AS  number(30, 5))                                                                             as frais,
       v.REFERENCEFACT,
       v.NUMEROFACTURE,
       v.LIEULIVRAISON,
       v.DATELIVRAISON,
       v.UPDATED_AT,
       case
           when v.ESTPREVU = 0 then 'Non'
           ELSE 'Oui'
           END estprevulib,
       ce.id AS idecriture,
       nvl(blc.daty,v.DATELIVRAISON) AS datedelivraison,
       c.ADRESSE
FROM VENTE v
         LEFT JOIN CLIENT c ON c.ID = v.IDCLIENT
         left join PROVINCE pv on pv.id = c.IDPROVINCE
         LEFT JOIN MAGASINPOINT m ON m.ID = v.IDMAGASIN
         JOIN VENTEMONTANT v2 ON v2.ID = v.ID
         LEFT JOIN LIAISONPAIEMENTTOTAL mv ON v.id = mv.id2
         LEFT JOIN AVOIRFCLIB_CPL_GRP ACG on ACG.IDVENTE = v.ID
         LEFT JOIN REFERENCEFACTURE rf ON rf.idfacture = v.Id
         left join vente_poids vp on vp.idvente = v.id
         left join MODEPAIEMENT mp on mp.id = v.modepaiement
         left join vente_reste vr on vr.idvente = v.id
         LEFT JOIN AS_BONDELIVRAISON_CLIENT blc ON blc.IDVENTE = v.id
         LEFT JOIN compta_ecriture ce ON ce.idobjet=v.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VENTE_CPL_EUR" ("ID", "DESIGNATION", "IDMAGASIN", "IDMAGASINLIB", "DATY", "REMARQUE", "ETAT", "ETATLIB", "MONTANTTOTAL", "IDDEVISE", "IDCLIENT", "IDCLIENTLIB", "MONTANTTVA", "MONTANTTTC", "MONTANTTTCAR", "MONTANTPAYE", "MONTANTRESTE") AS
SELECT "ID","DESIGNATION","IDMAGASIN","IDMAGASINLIB","DATY","REMARQUE","ETAT","ETATLIB","MONTANTTOTAL","IDDEVISE","IDCLIENT","IDCLIENTLIB","MONTANTTVA","MONTANTTTC","MONTANTTTCAR","MONTANTPAYE","MONTANTRESTE" FROM VENTE_CPL WHERE iddevise='EUR';

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VENTE_CPL_LIVREE" ("ID", "DESIGNATION", "IDMAGASIN", "IDMAGASINLIB", "DATY", "REMARQUE", "ETAT", "ETATLIB", "MONTANTTOTAL") AS
select "ID","DESIGNATION","IDMAGASIN","IDMAGASINLIB","DATY","REMARQUE","ETAT","ETATLIB","MONTANTTOTAL"
from VENTE_CPL v
where v.ETAT = 11
   or v.ETAT = 13;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VENTE_CPL_MGA" ("ID", "DESIGNATION", "IDMAGASIN", "IDMAGASINLIB", "DATY", "REMARQUE", "ETAT", "ETATLIB", "MONTANTTOTAL", "IDDEVISE", "IDCLIENT", "IDCLIENTLIB", "MONTANTTVA", "MONTANTTTC", "MONTANTTTCAR", "MONTANTPAYE", "MONTANTRESTE") AS
SELECT "ID","DESIGNATION","IDMAGASIN","IDMAGASINLIB","DATY","REMARQUE","ETAT","ETATLIB","MONTANTTOTAL","IDDEVISE","IDCLIENT","IDCLIENTLIB","MONTANTTVA","MONTANTTTC","MONTANTTTCAR","MONTANTPAYE","MONTANTRESTE" FROM VENTE_CPL WHERE iddevise='AR';

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VENTE_CPL_PAYEE" ("ID", "DESIGNATION", "IDMAGASIN", "IDMAGASINLIB", "DATY", "REMARQUE", "ETAT", "ETATLIB", "MONTANTTOTAL") AS
select "ID","DESIGNATION","IDMAGASIN","IDMAGASINLIB","DATY","REMARQUE","ETAT","ETATLIB","MONTANTTOTAL"
from VENTE_CPL v
where  v.ETAT = 11 OR v.ETAT = 12;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VENTE_CPL_SANSAVOIR" ("ID", "DESIGNATION", "IDMAGASIN", "IDMAGASINLIB", "DATY", "REMARQUE", "ETAT", "ETATLIB", "MONTANTTOTAL", "IDDEVISE", "IDCLIENT", "IDCLIENTLIB", "MONTANTTVA", "MONTANTTTC", "MONTANTTTCAR", "MONTANTPAYE", "MONTANTRESTE", "TAUXDECHANGE", "MONTANTREVIENT", "MARGEBRUTE", "IDRESERVATION", "DATYPREVU", "REFERENCEFACTURE", "MONTANTREMISE", "MONTANT", "MOIS", "ANNEE", "POIDS", "MODEPAIEMENT", "MODEPAIEMENTLIB", "FRAISLIVRAISON", "MODELIVRAISON", "MODELIVRAISONLIB", "RESTE", "IDPROVINCE", "PROVINCELIB", "NUMFACT") AS
SELECT v.ID,
       v.DESIGNATION,
       v.IDMAGASIN,
       m.VAL                                                        AS IDMAGASINLIB,
       v.DATY,
       v.REMARQUE,
       v.ETAT,
       CASE
           WHEN v.ETAT = 1 THEN 'CREE'
           WHEN v.ETAT = 11 THEN 'VISE'
           WHEN v.ETAT = 0 THEN 'ANNULE'
           END
                                                                    AS ETATLIB,
       v2.MONTANTTOTAL,
       v2.IDDEVISE,
       v.IDCLIENT,
       c.NOM                                                        AS IDCLIENTLIB,
       cast(V2.MONTANTTVA as number(30, 2))                         as MONTANTTVA,
       cast(V2.MONTANTTTC as number(30, 2))                         as montantttc,
       cast(V2.MONTANTTTCAR as number(30, 2))                       as MONTANTTTCAR,
       cast(nvl(mv.montant, 0) AS NUMBER(30, 2))                    AS montantpaye,
       cast(V2.MONTANTTTC - nvl(mv.montant, 0) AS NUMBER(30, 2))    AS montantreste,
       v2.tauxDeChange                                              AS tauxDeChange,
       v2.MONTANTREVIENT,
       cast((V2.MONTANTTTCAR - v2.MONTANTREVIENT) as number(20, 2)) as margeBrute,
       v.IDRESERVATION,
       case when v.DATYPREVU is null then daty else V.DATYPREVU end as datyprevu,
       rf.REFERENCE                                                 as referencefacture,
       v2.MONTANTREMISE,
       nvl(v2.MONTANTTOTAL, 0) + nvl(v2.MONTANTREMISE, 0)           as montant,
       extract(month from DATY)                                     as mois,
       extract(year from DATY)                                      as annee,
       vp.poids,
       v.modepaiement,
       mp.VAL                                                       as modepaiementlib,
       nvl(v.fraislivraison, 0) * nvl(vp.poids, 0)                  as fraislivraison,
       v.modelivraison,
       CASE
           WHEN v.modelivraison = 1 THEN '<span style=color: green;>LIVRAISON</span>'
           WHEN v.modelivraison = 2 THEN '<span style=color: green;>RECUPERATION</span>'
           END                                                      AS modelivraisonlib,
       vr.reste,
       pv.id                                                        as idprovince,
       pv.val                                                       as provincelib,
       v.NUMEROFACTURE as numfact
FROM VENTE v
         LEFT JOIN CLIENT c ON c.ID = v.IDCLIENT
         left join PROVINCE pv on pv.id = c.IDPROVINCE
         LEFT JOIN MAGASINPOINT m ON m.ID = v.IDMAGASIN
         JOIN VENTEMONTANT v2 ON v2.ID = v.ID
         LEFT JOIN LIAISONPAIEMENTTOTAL mv ON v.id = mv.id2
         LEFT JOIN REFERENCEFACTURE rf ON rf.idfacture = v.Id
         left join vente_poids vp on vp.idvente = v.id
         left join MODEPAIEMENT mp on mp.id = v.modepaiement
         left join vente_reste vr on vr.idvente = v.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VENTE_CPL_USD" ("ID", "DESIGNATION", "IDMAGASIN", "IDMAGASINLIB", "DATY", "REMARQUE", "ETAT", "ETATLIB", "MONTANTTOTAL", "IDDEVISE", "IDCLIENT", "IDCLIENTLIB", "MONTANTTVA", "MONTANTTTC", "MONTANTTTCAR", "MONTANTPAYE", "MONTANTRESTE") AS
SELECT "ID","DESIGNATION","IDMAGASIN","IDMAGASINLIB","DATY","REMARQUE","ETAT","ETATLIB","MONTANTTOTAL","IDDEVISE","IDCLIENT","IDCLIENTLIB","MONTANTTVA","MONTANTTTC","MONTANTTTCAR","MONTANTPAYE","MONTANTRESTE" FROM VENTE_CPL WHERE iddevise='USD';

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VENTE_CPL_VISEE" ("ID", "DESIGNATION", "IDMAGASIN", "IDMAGASINLIB", "DATY", "REMARQUE", "ETAT", "ETATLIB", "MONTANTTOTAL", "IDDEVISE", "IDCLIENT", "CLIENTLIB", "MONTANTTVA", "MONTANTTTC", "MONTANTTTCAR", "MONTANTPAYE", "MONTANTRESTE", "AVOIR", "TAUXDECHANGE", "MONTANTREVIENT", "MARGEBRUTE", "IDRESERVATION", "IDORIGINE", "IDBL") AS
SELECT v.ID,
       v.DESIGNATION,
       v.IDMAGASIN,
       m.VAL AS IDMAGASINLIB,
       v.DATY,
       v.REMARQUE,
       v.ETAT,
       CASE
           WHEN v.ETAT = 1 THEN 'CREE'
           WHEN v.ETAT = 11 THEN 'VISEE'
           WHEN v.ETAT = 0 THEN 'ANNULEE'
           END
             AS ETATLIB,
       v2.MONTANTTOTAL,
       v2.IDDEVISE,
       v.IDCLIENT,
       c.NOM AS CLIENTLIB,
       cast(V2.MONTANTTVA as number(30,2)) as MONTANTTVA,
       cast(V2.MONTANTTTC as number(30,2)) as montantttc,
       cast(V2.MONTANTTTCAR as number(30,2)) as MONTANTTTCAR,
       cast(nvl(mv.credit,0)-nvl(ACG.MONTANTPAYE, 0) AS NUMBER(30,2)) AS montantpaye,
       cast(V2.MONTANTTTC-nvl(mv.credit,0)-nvl(ACG.resteapayer_avr, 0) AS NUMBER(30,2)) AS montantreste,
       nvl(ACG.MONTANTTTC_avr, 0)  as avoir,
       v2.tauxDeChange AS tauxDeChange,v2.MONTANTREVIENT,cast((V2.MONTANTTTCAR-v2.MONTANTREVIENT) as number(20,2))  as margeBrute,
       v.IDRESERVATION,
       v.IDORIGINE,
       bl.id as idbl
FROM VENTE v
         LEFT JOIN CLIENT c ON c.ID = v.IDCLIENT
         LEFT JOIN MAGASIN m ON m.ID = v.IDMAGASIN
         JOIN VENTEMONTANT v2 ON v2.ID = v.ID
         LEFT JOIN mouvementcaisseGroupeFacture mv ON v.id=mv.IDORIGINE
         LEFT JOIN AVOIRFCLIB_CPL_GRP ACG on ACG.IDVENTE = v.ID
         left join AS_BONDELIVRAISON_CLIENT bl on bl.IDVENTE = v.id
where v.ETAT = 11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VENTE_DETAILS_ANALYSE" ("IDVENTELIB", "IDCLIENTLIB", "CATEGORIEPRODUITLIB", "DATY", "DATYPREVU") AS
SELECT
v.DESIGNATION AS  idventelib,
c.NOM  AS idclientlib,
ct.VAL AS categorieproduitlib,
v.DATY,
v.DATYPREVU
FROM VENTE_DETAILS_POIDS vdp
LEFT JOIN VENTE v ON v.id = vdp.IDVENTE
LEFT JOIN CLIENT c ON c.id = v.IDCLIENT
LEFT JOIN AS_INGREDIENTS ai ON ai.ID = vdp.IDPRODUIT
LEFT JOIN CATEGORIEINGREDIENT ct ON ct.ID = ai.CATEGORIEINGREDIENT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VENTE_DETAILS_BC" ("IDPRODUIT", "PU", "QTE", "PUACHAT", "TVA") AS
SELECT 
	bcf.PRODUIT AS idproduit,
	bcf.PU AS PU,
	bcf.QUANTITE AS QTE,
	p.PUACHAT AS PUACHAT,
	bcf.TVA AS tva
FROM 
BONDECOMMANDE_CLIENT_FILLE bcf JOIN 
PRODUIT p ON p.ID =bcf.PRODUIT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VENTE_DETAILS_CPL" ("ID", "IDVENTE", "IDVENTELIB", "IDPRODUIT", "IDPRODUITLIB", "IDORIGINE", "QTE", "PU", "MONTANTREMISE", "MONTANT", "IDDEVISE", "TAUXDECHANGE", "TVA", "IDCLIENT", "IDCLIENTLIB", "DESIGNATION", "PUREVIENT", "MONTANTREVIENT") AS
SELECT vd.ID,
          vd.IDVENTE,
          v.DESIGNATION AS IDVENTELIB,
          vd.IDPRODUIT,
          p.LIBELLE AS IDPRODUITLIB,
          v.IDORIGINE,
          vd.QTE,
          VD.pu
             AS PU,
         	CAST((nvl(vd.remise/100,0))*(vd.QTE * vd.PU) AS NUMBER(30,2)) AS montantRemise,
            CAST((1-nvl(vd.remise/100,0))*(vd.QTE * vd.PU) AS NUMBER(30,2)) AS montant,
          vd.iddevise AS iddevise,
          vd.tauxDeChange AS tauxDeChange,
          vd.tva AS tva,
          v.idclient,
          v.idclientlib,
          vd.designation,
          vd.PUREVIENT,
          cast(vd.QTE*vd.PUREVIENT as NUMBER(20,2)) as montantRevient
     FROM VENTE_DETAILS vd
          LEFT JOIN VENTE_LIB v ON v.ID = vd.IDVENTE
          LEFT JOIN AS_INGREDIENTS p ON p.ID = vd.IDPRODUIT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VENTE_DETAILS_CPL_2" ("ID", "IDVENTE", "IDVENTELIB", "IDPRODUIT", "IDPRODUITLIB", "IDORIGINE", "QTE", "PU", "PUTOTAL", "PUTOTALACHAT", "PUREVIENT", "IDCATEGORIE", "IDCATEGORIELIB", "DATY", "IDMAGASIN", "IDMAGASINLIB", "IDPOINT", "IDPOINTLIB", "IDDEVISE", "IDDEVISELIB", "IDRESERVATION", "IDBCFILLE", "TYPEPRODUIT", "TYPEPRODUITLIB", "IDPROVINCE", "IDPROVINCELIB", "MOTSCLESSS") AS
SELECT SQ.ID,
       SQ.IDVENTE,
       SQ.IDVENTELIB,
       SQ.IDPRODUIT,
       SQ.IDPRODUITLIB,
       SQ.IDORIGINE,
       SQ.QTE,
       SQ.PU,
       SQ.PUTOTAL,
       SQ.PUTOTALACHAT,
       SQ.PUREVIENT,
       SQ.IDCATEGORIE,
       SQ.IDCATEGORIELIB,
       SQ.DATY,
       SQ.IDMAGASIN,
       SQ.IDMAGASINLIB,
       SQ.IDPOINT,
       SQ.IDPOINTLIB,
       SQ.IDDEVISE,
       SQ.IDDEVISELIB,
       SQ.IDRESERVATION,
       SQ.IDBCFILLE,
       SQ.TYPEPRODUIT,
       SQ.TYPEPRODUITLIB,
       SQ.IDPROVINCE,
       SQ.IDPROVINCELIB,
       (NVL(TO_CHAR(SQ.ID), '') || ' | ' ||
        NVL(TO_CHAR(SQ.IDVENTE), '') || ' | ' ||
        NVL(TO_CHAR(SQ.IDVENTELIB), '') || ' | ' ||
        NVL(TO_CHAR(SQ.IDPRODUIT), '') || ' | ' ||
        NVL(TO_CHAR(SQ.IDPRODUITLIB), '') || ' | ' ||
        NVL(TO_CHAR(SQ.IDORIGINE), '') || ' | ' ||
        NVL(TO_CHAR(SQ.QTE), '') || ' | ' ||
        NVL(TO_CHAR(SQ.PU), '') || ' | ' ||
        NVL(TO_CHAR(SQ.PUTOTAL), '') || ' | ' ||
        NVL(TO_CHAR(SQ.PUTOTALACHAT), '') || ' | ' ||
        NVL(TO_CHAR(SQ.PUREVIENT), '') || ' | ' ||
        NVL(TO_CHAR(SQ.IDCATEGORIE), '') || ' | ' ||
        NVL(TO_CHAR(SQ.IDCATEGORIELIB), '') || ' | ' ||
        NVL(TO_CHAR(SQ.DATY, 'YYYY-MM-DD HH24:MI:SS'), '') || ' | ' ||
        NVL(TO_CHAR(SQ.IDMAGASIN), '') || ' | ' ||
        NVL(TO_CHAR(SQ.IDMAGASINLIB), '') || ' | ' ||
        NVL(TO_CHAR(SQ.IDPOINT), '') || ' | ' ||
        NVL(TO_CHAR(SQ.IDPOINTLIB), '') || ' | ' ||
        NVL(TO_CHAR(SQ.IDDEVISE), '') || ' | ' ||
        NVL(TO_CHAR(SQ.IDDEVISELIB), '') || ' | ' ||
        NVL(TO_CHAR(SQ.IDRESERVATION), '') || ' | ' ||
        NVL(TO_CHAR(SQ.IDBCFILLE), '') || ' | ' ||
        NVL(TO_CHAR(SQ.TYPEPRODUIT), '') || ' | ' ||
        NVL(TO_CHAR(SQ.TYPEPRODUITLIB), '') || ' | ' ||
        NVL(TO_CHAR(SQ.IDPROVINCE), '') || ' | ' ||
        NVL(TO_CHAR(SQ.IDPROVINCELIB), '')) AS MOTSCLESSS
FROM (
         SELECT vd.ID,
                vd.IDVENTE,
                v.DESIGNATION                                                      AS IDVENTELIB,
                vd.IDPRODUIT,
                p.LIBELLEVENTE                                                     AS IDPRODUITLIB,
                vd.IDORIGINE,
                vd.QTE,
                NVL(vd.PU, 0)                                                      AS PU,
                -- Formule de PUTOTAL aligne?e sur le MONTANTTTC de la vue de?taille?e
                CAST(
                    -- Partie HT avec de?duction des frais
                        ((NVL(vd.PU, 0) * (1 - NVL(vd.REMISE, 0) / 100)) * vd.QTE
                            - NVL(v.FRAISLIVRAISON, 0) * NVL(p.CALORIE, 0) * NVL(vd.QTE, 0))
                            +
                            -- Partie TVA applique?e sur cette me?me base HT modifie?e
                        (((NVL(vd.PU, 0) * (1 - NVL(vd.REMISE, 0) / 100)) * vd.QTE
                            - NVL(v.FRAISLIVRAISON, 0) * NVL(p.CALORIE, 0) * NVL(vd.QTE, 0)) * NVL(vd.TVA, 0) / 100)
                    AS NUMBER(30,2)
                )                                                                  AS PUTOTAL,
                CAST(NVL(vd.PUACHAT * vd.QTE, 0) AS NUMBER(30, 2))                  AS PUTOTALACHAT,
                CAST(NVL(vd.PU * vd.QTE, 0) - NVL(vd.PUACHAT * vd.QTE, 0) AS NUMBER(30, 2)) AS PUREVIENT,
                cat.ID                                                             AS IDCATEGORIE,
                cat.VAL                                                            AS IDCATEGORIELIB,
                v.DATY                                                             AS DATY,
                m.ID                                                               AS IDMAGASIN,
                m.VAL                                                              AS IDMAGASINLIB,
                p1.ID                                                              AS IDPOINT,
                p1.VAL                                                             AS IDPOINTLIB,
                vd.IDDEVISE,
                vd.IDDEVISE                                                        AS IDDEVISELIB,
                v.IDRESERVATION,
                vd.IDBCFILLE,
                p.TYPEPRODUIT,
                tp.VAL                                                             AS TYPEPRODUITLIB,
                cli.IDPROVINCE,
                pro.VAL                                                            AS IDPROVINCELIB
         FROM VENTE_DETAILS vd
                  LEFT JOIN VENTE v ON v.ID = vd.IDVENTE
                  LEFT JOIN MAGASIN2 m ON m.ID = v.IDMAGASIN
                  LEFT JOIN AS_INGREDIENTS p ON p.ID = vd.IDPRODUIT
                  LEFT JOIN POINT p1 ON p1.ID = m.IDPOINT
                  LEFT JOIN CATEGORIEINGREDIENT cat ON p.CATEGORIEINGREDIENT = cat.ID
                  LEFT JOIN TYPE_PRODUIT tp ON tp.ID = p.TYPEPRODUIT
                  LEFT JOIN CLIENT cli ON cli.ID = v.IDCLIENT
                  LEFT JOIN PROVINCE pro ON pro.ID = cli.IDPROVINCE
     ) SQ;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VENTE_DETAILS_CPL_2_VISEE" ("ID", "IDVENTE", "IDVENTELIB", "IDPRODUIT", "IDPRODUITLIB", "IDORIGINE", "QTE", "PU", "PUTOTAL", "PUTOTALACHAT", "PUREVIENT", "IDCATEGORIE", "IDCATEGORIELIB", "DATY", "IDMAGASIN", "IDMAGASINLIB", "IDPOINT", "IDPOINTLIB", "IDDEVISE", "IDDEVISELIB", "IDRESERVATION", "IDBCFILLE", "SUM_QTE", "MONTANTTOTAL", "MONTANT_TOTAL", "IDCLIENT", "TOTAL_ACHAT", "TYPEPRODUIT", "TYPEPRODUITLIB", "IDPROVINCE", "IDPROVINCELIB") AS
SELECT VD.ID,
       VD.IDVENTE,
       VD.IDVENTELIB,
       VD.IDPRODUIT,
       VD.IDPRODUITLIB,
       VD.IDORIGINE,
       VD.QTE,
       VD.PU,
       VD.PUTOTAL,
       VD.PUTOTALACHAT,
       VD.PUREVIENT,
       VD.IDCATEGORIE,
       VD.IDCATEGORIELIB,
       VD.DATY,
       VD.IDMAGASIN,
       VD.IDMAGASINLIB,
       VD.IDPOINT,
       VD.IDPOINTLIB,
       VD.IDDEVISE,
       VD.IDDEVISELIB,
       VD.IDRESERVATION,
       VD.IDBCFILLE,
       SUM(VD.QTE) OVER ()                            AS SUM_QTE,
       SUM(VD.PUTOTAL) OVER ()                        AS MONTANTTOTAL,
       SUM(VD.PUTOTAL) OVER ()                        AS MONTANT_TOTAL,
       V.IDCLIENT,
       SUM(VD.PUTOTAL) OVER (PARTITION BY V.IDCLIENT) AS TOTAL_ACHAT,
       VD.TYPEPRODUIT,
       VD.TYPEPRODUITLIB,
       VD.IDPROVINCE,
       VD.IDPROVINCELIB
FROM VENTE_DETAILS_CPL_2 VD
         LEFT JOIN VENTE V ON V.ID = VD.IDVENTE
WHERE V.ETAT >= 11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VENTE_DETAILS_LIB" ("ID", "IDVENTE", "IDVENTELIB", "IDPRODUIT", "IDPRODUITLIB", "IDORIGINE", "QTE", "PU", "PUTOTAL", "PUACHAT", "IDRESERVATION") AS
SELECT vd.ID,
       vd.IDVENTE,
       v.DESIGNATION    AS IDVENTELIB,
       vd.IDPRODUIT,
       p.LIBELLE            AS IDPRODUITLIB,
       vd.IDORIGINE,
       vd.QTE,
       vd.PU,
       cast((vd.QTE * vd.PU) as NUMBER(30,2)) AS puTotal,
       vd.PuAchat AS PUACHAT,
       v.IDRESERVATION
FROM VENTE_DETAILS vd
         LEFT JOIN VENTE v ON v.ID = vd.IDVENTE
         LEFT JOIN AS_INGREDIENTS p ON p.ID = vd.IDPRODUIT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VENTE_DETAILS_PAYE" ("ID", "IDVENTE", "IDPRODUIT", "IDORIGINE", "QTE", "PU", "REMISE", "TVA", "PUACHAT", "PUVENTE", "IDDEVISE", "TAUXDECHANGE", "DESIGNATION", "COMPTE", "PUREVIENT", "IDBCFILLE", "UNITE", "POIDS", "RISTOURNE", "IDPREVISION", "MOIS", "ANNEE", "POURCENTAGEPAYE", "MONTANTFILLEPAYE", "RESTEAPAYERFILLE", "MONTANTFILLEPAYEAR", "MONTANTFILLE") AS
SELECT
    VD.ID,
    VD.IDVENTE,
    VD.IDPRODUIT,
    VD.IDORIGINE,
    VD.QTE,
    VD.PU,
    VD.REMISE,
    VD.TVA,
    VD.PUACHAT,
    VD.PUVENTE,
    VD.IDDEVISE,
    VD.TAUXDECHANGE,
    VD.DESIGNATION,
    VD.COMPTE,
    VD.PUREVIENT,
    VD.IDBCFILLE,
    VD.UNITE,
    VD.POIDS,
    VD.RISTOURNE,
    VD.IDPREVISION,
    V.MOIS,
    V.ANNEE,
    V.MONTANTPAYE * 100 / NULLIF(V.MONTANTTTC,0) AS  pourcentagepaye,
    (V.MONTANTPAYE / NULLIF(V.MONTANTTTC, 0)) * (VD.QTE * VD.PU) AS MontantFillePaye,
    (VD.QTE * VD.PU) - ((V.MONTANTPAYE / NULLIF(V.MONTANTTTC, 0)) * (VD.QTE * VD.PU))   AS resteapayerfille,
    ((V.MONTANTPAYE / NULLIF(V.MONTANTTTC, 0)) * (VD.QTE * VD.PU)) * VD.TAUXDECHANGE AS MontantFillePayeAr,
    (VD.QTE * VD.PU) AS montantfille
FROM VENTE_DETAILS VD
    LEFT JOIN VENTE_CPL V ON V.ID = VD.IDVENTE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VENTE_DETAILS_POIDS" ("ID", "IDVENTE", "IDPRODUIT", "IDORIGINE", "QTE", "PU", "REMISE", "TVA", "PUACHAT", "PUVENTE", "IDDEVISE", "TAUXDECHANGE", "DESIGNATION", "COMPTE", "PUREVIENT", "IDBCFILLE", "UNITE", "UNITELIB", "PUNET", "MONTANTHT", "MONTANTTTC", "MONTANTTVA", "MONTANTREMISE", "MONTANT", "POIDS", "RESTE", "FRAIS", "IDPRODUITLIB", "DATY", "DATYPREVU", "IDDEVISELIB", "IDCATEGORIELIB", "CATEGORIEPRODUITLIB", "PUTOTAL", "IDCLIENTLIB", "RISTOURNE", "IDPREVISION", "IDRESERVATION", "FRAISLIVRAISON", "CALORIE") AS
SELECT v.ID,
       v.IDVENTE,
       v.IDPRODUIT,
       v.IDORIGINE,
       CAST(v.QTE AS NUMBER(38, 2)) AS QTE,
       v.PU,
       v.REMISE,
       v.TVA,
       v.PUACHAT,
       v.PUVENTE,
       v.IDDEVISE,
       v.TAUXDECHANGE,
       v.DESIGNATION,
       v.COMPTE,
       v.PUREVIENT,
       v.IDBCFILLE,
       v.UNITE,
       v.UNITELIB,
       v.PUNET,
       v.MONTANTHT,
       cast(v.MONTANTTTC as number(30,2)) as MONTANTTTC,
       cast(v.MONTANTTVA as number(30,2)) as montanttva,
       v.MONTANTREMISE,
       v.MONTANT,
       v.poids,
       vc.RESTE                     AS RESTE,
       v.frais                      AS FRAIS,
       v.IDPRODUITLIB,
       v.DATY,
       v.DATYPREVU                  AS DATYPREVU,
       v.IDDEVISE                   AS IDDEVISELIB,
       v.IDCATEGORIELIB,
       v.CATEGORIEPRODUITLIB,
       montantttc                   AS PUTOTAL,
       v.idclientlib,
       v.RISTOURNE                  AS RISTOURNE,
       v.idprevision,
       v.IDRESERVATION,
       v.fraislivraison,
       v.calorie
FROM VENTE_DETAILS_VIDE v
--         LEFT JOIN EQUIVALENCE e
--                   ON e.IDPRODUIT = v.IDPRODUIT
--                       AND e.IDUNITE = v.UNITE
         LEFT JOIN VENTE_DETAILS_RESTE vc
                   ON vc.ID = v.ID
--         LEFT JOIN Vente ve
--                   ON ve.ID = v.IDVENTE
--         LEFT JOIN VENTE_DETAILS vdc
--                   ON vdc.ID = ve.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VENTE_DETAILS_POIDS_ING" ("ID", "IDVENTE", "IDPRODUIT", "IDORIGINE", "QTE", "PU", "REMISE", "TVA", "PUACHAT", "PUVENTE", "IDDEVISE", "TAUXDECHANGE", "DESIGNATION", "COMPTE", "PUREVIENT", "IDBCFILLE", "UNITE", "UNITELIB", "PUNET", "MONTANTHT", "MONTANTTTC", "MONTANTTVA", "MONTANTREMISE", "MONTANT", "POIDS", "RESTE", "FRAIS", "IDPRODUITLIB", "DATY", "DATYPREVU", "IDDEVISELIB", "IDCATEGORIELIB", "CATEGORIEPRODUITLIB", "PUTOTAL", "IDCLIENTLIB", "RISTOURNE", "IDPREVISION", "IDRESERVATION", "FRAISLIVRAISON", "CALORIE", "PUINGREDIENT", "CONTENUE", "UNITE2", "MONTANTREMISER", "IDREMISE", "REMISEARBIOCHEM", "RISTOURNEARBIOCHEM") AS
SELECT
    p.ID,
    p.IDVENTE,
    p.IDPRODUIT,
    p.IDORIGINE,
    CAST(p.QTE AS NUMBER(38, 2))                                              AS QTE,
    p.PU,
    p.REMISE,
    p.TVA,
    p.PUACHAT,
    p.PUVENTE,
    p.IDDEVISE,
    p.TAUXDECHANGE,
    p.DESIGNATION,
    p.COMPTE,
    p.PUREVIENT,
    p.IDBCFILLE,
    p.UNITE,
    u.VAL                                                                     AS UNITELIB,

    CAST(p.pu - (p.pu * p.remise / 100) + (p.pu * p.tva / 100)
        AS NUMBER(30, 5))                                                    AS PUNET,

    -- MONTANTHT : deduction remise % + remise Arbiochem (montant fixe par qte)
    CAST(((p.pu - (p.pu * p.remise / 100)) * p.qte
        - NVL(v.fraislivraison, 0) * NVL(ing.CALORIE, 0) * NVL(p.QTE, 0)
        - (nvl(p.remiseArbiochem, 0) * p.qte))
        AS NUMBER(30, 5))                                                    AS MONTANTHT,

    -- MONTANTTTC : base (avec remise Arbiochem) + TVA calculee sur cette meme base
    CAST(
            ((p.pu - (p.pu * p.remise / 100)) * p.qte
                - NVL(v.fraislivraison, 0) * NVL(ing.CALORIE, 0) * NVL(p.QTE, 0)
                - (nvl(p.remiseArbiochem, 0) * p.qte))
                + ((((p.pu * p.qte) - (p.pu * p.remise / 100) * p.qte)
                - NVL(v.fraislivraison, 0) * NVL(ing.CALORIE, 0) * NVL(p.QTE, 0)
                - (nvl(p.remiseArbiochem, 0) * p.qte)) * p.tva / 100)
        AS NUMBER(30, 2)
    )                                                                         AS MONTANTTTC,

    -- MONTANTTVA : calculee sur la base HT deja reduite de la remise Arbiochem
    CAST(
            ((((p.pu * p.qte) - (p.pu * p.remise / 100) * p.qte)
                - NVL(v.fraislivraison, 0) * NVL(ing.CALORIE, 0) * NVL(p.QTE, 0)
                - (nvl(p.remiseArbiochem, 0) * p.qte)) * p.tva / 100)
        AS NUMBER(30, 2)
    )                                                                         AS MONTANTTVA,

    -- MONTANTREMISE : remise % + remise Arbiochem (montant total de la remise)
    CAST(((p.pu * p.remise / 100) * p.qte) + (nvl(p.remiseArbiochem, 0) * p.qte)
        AS NUMBER(30, 5))                                                    AS MONTANTREMISE,

    CAST(p.pu * p.qte AS NUMBER(30, 5))                                       AS MONTANT,

    CAST(NVL(ing.CALORIE, 0) * NVL(p.QTE, 0) AS NUMBER(30, 5))                AS POIDS,
    (NVL(p.QTE, 0) - NVL(bl.QUANTITE, 0)) - NVL(avcf.qte, 0)                  AS RESTE,

    CAST(NVL(v.fraislivraison, 0) * NVL(ing.CALORIE, 0) * NVL(p.QTE, 0)
        AS NUMBER(30, 5))                                                    AS FRAIS,

    nvl(ing.LIBELLEVENTE,ing.libelle)                                                          AS IDPRODUITLIB,
    v.DATY,
    v.DATYPREVU                                                               AS DATYPREVU,
    p.IDDEVISE                                                                AS IDDEVISELIB,
    c.VAL                                                                     AS IDCATEGORIELIB,
    c.VAL                                                                     AS CATEGORIEPRODUITLIB,

    -- PUTOTAL : meme formule que MONTANTTTC (avec remise Arbiochem)
    CAST(
            ((p.pu - (p.pu * p.remise / 100)) * p.qte
                - NVL(v.fraislivraison, 0) * NVL(ing.CALORIE, 0) * NVL(p.QTE, 0)
                - (nvl(p.remiseArbiochem, 0) * p.qte))
                + ((((p.pu * p.qte) - (p.pu * p.remise / 100) * p.qte)
                - NVL(v.fraislivraison, 0) * NVL(ing.CALORIE, 0) * NVL(p.QTE, 0)
                - (nvl(p.remiseArbiochem, 0) * p.qte)) * p.tva / 100)
        AS NUMBER(30, 2)
    )                                                                         AS PUTOTAL,

    cl.nom                                                                    AS IDCLIENTLIB,
    p.ristourne                                                               AS RISTOURNE,
    p.idprevision,
    v.IDRESERVATION,
    NVL(v.fraislivraison, 0)                                                  AS FRAISLIVRAISON,
    ing.calorie,
    CAST(p.pu / NVL(eq.QUANTITE, 1) AS NUMBER(30, 2))                        AS PUINGREDIENT,
    NVL(eq.QUANTITE, 1)                                                       AS CONTENUE,
    ing.unite2,

    -- MONTANTREMISER : montant net apres remise % + remise Arbiochem
    (p.pu * p.qte) - ((p.pu * p.remise / 100) * p.qte) - (nvl(p.remiseArbiochem, 0) * p.qte) AS MONTANTREMISER,

    p.IDREMISE,
    nvl(p.remiseArbiochem, 0)                                                 AS REMISEARBIOCHEM,
    nvl(p.ristourneArbiochem, 0)                                              AS RISTOURNEARBIOCHEM
FROM VENTE_DETAILS p
         LEFT JOIN VENTE v
                   ON v.id = p.IDVENTE
         LEFT JOIN AS_UNITE u
                   ON u.id = p.unite
         LEFT JOIN AS_INGREDIENTS ing
                   ON ing.ID = p.IDPRODUIT
         LEFT JOIN CLIENT cl
                   ON v.IDCLIENT = cl.ID
         LEFT JOIN CATEGORIEINGREDIENT c
                   ON ing.CATEGORIEINGREDIENT = c.ID
         LEFT JOIN EQUIVALENCEVENTE eq
                   ON eq.IDPRODUIT1 = p.IDPRODUIT
         LEFT JOIN BL_CLIENT_FILLE_grp_vente bl
                   ON bl.idventedetail = p.ID
         LEFT JOIN avoirfcfille_grp_viseee avcf
                   ON avcf.idventedetails = p.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VENTE_DETAILS_QTE_GRP" ("IDBCFILLE", "QTE") AS
SELECT idbcfille AS idbcfille,sum(qte) AS qte FROM VENTE_DETAILS_CPL_2_VISEE vd GROUP BY idbcfille;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VENTE_DETAILS_RESTE" ("ID", "IDPRODUIT", "IDUNITE", "UNITELIB", "QTE", "RESTE", "IDVENTE", "IDBCFILLE") AS
SELECT
    vd.id AS id,
    vd.idProduit,
    vd.UNITE as idunite,
    u.VAL AS unitelib,
    vd.qte AS QTE,
    nvl(vd.QTE,0) - nvl(bl.QUANTITE,0) - nvl(acf.QUANTITE,0) AS reste,
    vd.IDVENTE AS IDVENTE,
    vd.IDBCFILLE
FROM
    VENTE_DETAILS vd
        LEFT JOIN BL_CLIENT_FILLE_grp_vente bl ON vd.ID = bl.idventedetail
--         left join BL_CLIENT_FILLE_grp_bc bl2 ON vd.IDBCFILLE = bl2.idbc_fille
        left join AS_BL_CLIENT_FILLE_vise acf on vd.IDORIGINE = acf.ID
        LEFT JOIN AS_INGREDIENTS p ON p.id = vd.IDPRODUIT
        LEFT JOIN AS_UNITE u ON u.id = vd.unite
WHERE p.actif = 1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VENTE_DETAILS_SAISIE" ("ID", "IDVENTE", "IDPRODUIT", "DESIGNATION", "IDORIGINE", "QTE", "PU", "REMISE", "TVA", "PUACHAT", "PUVENTE", "IDDEVISE", "TAUXDECHANGE", "COMPTE", "IDBCFILLE") AS
SELECT
         id,
         IDVENTE ,
         IDPRODUIT ,
         DESIGNATION ,
         IDORIGINE ,
         qte,
         pu,
         REMISE ,
         TVA ,
         PUACHAT ,
         PUVENTE ,
         IDDEVISE ,
         TAUXDECHANGE ,
         compte,
         vd.idbcfille
         FROM VENTE_DETAILS vd;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VENTE_DETAILS_SAISIE_DIRECTE" ("ID", "IDVENTE", "IDPRODUIT", "DESIGNATION", "IDORIGINE", "QTE", "PU", "REMISE", "REMISEMONTANT", "TVA", "PUACHAT", "PUVENTE", "IDDEVISE", "TAUXDECHANGE", "COMPTE", "PHOTO", "REFERENCE", "MONTANT", "UNITE", "RISTOURNE") AS
SELECT id,
       IDVENTE,
       IDPRODUIT,
       DESIGNATION,
       IDORIGINE,
       qte,
       pu,
       REMISE,
       nvl(remiseMontant, 0) AS remiseMontant,
       TVA,
       PUACHAT,
       PUVENTE,
       IDDEVISE,
       TAUXDECHANGE,
       compte,
       PHOTO,
       reference,
       montant,
       unite,
       RISTOURNE
FROM VENTE_DETAILS vd;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VENTE_DETAILS_TICKET" ("ID", "IDVENTE", "IDVENTELIB", "IDPRODUIT", "IDPRODUITLIB", "IDORIGINE", "QTE", "PU", "MONTANTREMISE", "MONTANT", "IDDEVISE", "TAUXDECHANGE", "TVA", "IDCLIENT", "IDCLIENTLIB", "DESIGNATION", "PUREVIENT", "MONTANTREVIENT", "UNITE", "IDUNITELIB") AS
SELECT vd.ID,
       vd.IDVENTE,
       v.DESIGNATION AS IDVENTELIB,
       vd.IDPRODUIT,
       p.LIBELLE AS IDPRODUITLIB,
       v.IDORIGINE,
       vd.QTE,
       VD.pu
                     AS PU,
       CAST((nvl(vd.remise/100,0))*(vd.QTE * vd.PU) AS NUMBER(30,2)) AS montantRemise,
       CAST((1-nvl(vd.remise/100,0))*(vd.QTE * vd.PU) AS NUMBER(30,2)) AS montant,
       vd.iddevise AS iddevise,
       vd.tauxDeChange AS tauxDeChange,
       vd.tva AS tva,
       v.idclient,
       v.idclientlib,
       vd.designation,
       vd.PUREVIENT,
       cast(vd.QTE*vd.PUREVIENT as NUMBER(20,2)) as montantRevient,
       p.UNITE,
       unit.val as idUniteLib
FROM VENTE_DETAILS vd
         LEFT JOIN VENTE_LIB v ON v.ID = vd.IDVENTE
         LEFT JOIN AS_INGREDIENTS p ON p.ID = vd.IDPRODUIT
         LEFT JOIN UNITE unit ON unit.id = p.UNITE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VENTE_DETAILS_VIDE" ("ID", "IDVENTE", "IDPRODUIT", "IDORIGINE", "QTE", "PU", "REMISE", "TVA", "PUACHAT", "PUVENTE", "IDDEVISE", "TAUXDECHANGE", "DESIGNATION", "COMPTE", "PUREVIENT", "IDBCFILLE", "UNITE", "UNITELIB", "PUNET", "FRAIS", "MONTANTHT", "MONTANTTTC", "MONTANTTVA", "MONTANTREMISE", "MONTANT", "RISTOURNE", "IDCLIENTLIB", "DATY", "DATYPREVU", "IDPRODUITLIB", "IDCATEGORIELIB", "CATEGORIEPRODUITLIB", "POIDS", "IDPREVISION", "CALORIE", "IDRESERVATION", "FRAISLIVRAISON", "RISTOURNEARBIOCHEM", "REMISEARBIOCHEM") AS
select p.ID,
       p.IDVENTE,
       p.IDPRODUIT,
       p.IDORIGINE,
       p.QTE,
       p.PU,
       p.REMISE,
       p.TVA,
       p.PUACHAT,
       p.PUVENTE,
       p.IDDEVISE,
       p.TAUXDECHANGE,
       p.DESIGNATION,
       p.COMPTE,
       p.PUREVIENT,
       p.IDBCFILLE,
       p.UNITE,
       u.VAL                                                                                                   as unitelib,
       cast(p.pu - (p.pu * p.remise / 100) + ((p.pu * p.tva / 100)) as number(30, 5))                                                   as punet,
       cast(nvl(v.fraislivraison, 0) * NVL(ing.CALORIE, 0) * NVL(p.QTE, 0) as number(30, 5))                                          as frais,
       cast(((p.pu - (p.pu * p.remise / 100)) * p.qte - nvl(v.fraislivraison, 0) * NVL(ing.CALORIE, 0) *
                                                        NVL(p.QTE, 0)) as number(30, 5))                                                  as montantht,
       cast(((p.pu - (p.pu * p.remise / 100)) * p.qte - nvl(v.fraislivraison, 0) * NVL(ing.CALORIE, 0) * NVL(p.QTE, 0)) +
            ((((p.pu * qte) - (p.pu * p.remise / 100) * p.qte) -
              nvl(v.fraislivraison, 0) * NVL(ing.CALORIE, 0) * NVL(p.QTE, 0)) * p.tva /
             100) as number(30, 5))                                                                                                   as montantttc,
       cast(((((p.pu * qte) - (p.pu * p.remise / 100) * p.qte) - nvl(v.fraislivraison, 0) * NVL(ing.CALORIE, 0) *
                                                                 NVL(p.QTE, 0)) * p.tva / 100) as number(30, 5))                                            as montanttva,
       cast((p.pu * p.remise / 100) * qte as number(30, 5))                                                                             as montantremise,
       cast((p.pu) * p.qte as number(30, 5))                                                                                            as montant,
       p.ristourne,
       cl.nom                                                                                                  as idclientlib,
       v.DATY,
       v.DATYPREVU,
       ing.LIBELLEVENTE                                                                                             AS IDPRODUITLIB,
       c.VAL                                                                                                   AS IDCATEGORIELIB,
       c.VAL                                                                                                   AS CATEGORIEPRODUITLIB,
       cast(NVL(ing.CALORIE, 0) * NVL(p.QTE, 0) as number(30, 5))                                                                     as poids,
       p.idprevision,
       ing.calorie,
       v.IDRESERVATION,
       nvl(v.fraislivraison, 0) AS fraislivraison,
       p.ristourneArbiochem,
       p.remiseArbiochem
from VENTE_DETAILS p
         left join AS_UNITE u on u.id = p.unite
         left join vente v on v.id = p.IDVENTE
         LEFT JOIN AS_INGREDIENTS ing
                   ON ing.ID = p.IDPRODUIT
         LEFT JOIN CLIENT cl
                   ON v.IDCLIENT = cl.ID
         LEFT JOIN CATEGORIEINGREDIENT c
                   ON ing.CATEGORIEINGREDIENT = c.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VENTE_DETAILS_VIDEAUTOCOMPLETE" ("ID", "IDVENTE", "IDPRODUIT", "IDORIGINE", "QTE", "PU", "REMISE", "TVA", "PUACHAT", "PUVENTE", "IDDEVISE", "TAUXDECHANGE", "DESIGNATION", "COMPTE", "PUREVIENT", "IDBCFILLE", "UNITE", "UNITELIB", "PUNET", "FRAIS", "MONTANTHT", "MONTANTTTC", "MONTANTTVA", "MONTANTREMISE", "MONTANT", "RISTOURNE", "IDCLIENTLIB", "DATY", "DATYPREVU", "IDPRODUITLIB", "IDCATEGORIELIB", "CATEGORIEPRODUITLIB", "POIDS", "IDPREVISION", "CALORIE", "IDRESERVATION", "FRAISLIVRAISON", "RISTOURNEARBIOCHEM", "REMISEARBIOCHEM") AS
SELECT
    v.ID,
    v.IDVENTE,
    CASE
        WHEN v.IDPRODUIT IS NULL
            THEN v.IDPRODUIT
        ELSE v.IDPRODUIT||'---'||a.LIBELLE
        END AS IDPRODUIT,
    v.IDORIGINE,
    v.QTE,
    v.PU,
    v.REMISE,
    v.TVA,
    v.PUACHAT,
    v.PUVENTE,
    v.IDDEVISE,
    v.TAUXDECHANGE,
    v.DESIGNATION,
    v.COMPTE,
    v.PUREVIENT,
    v.IDBCFILLE,
    v.UNITE,
    v.UNITELIB,
    v.PUNET,
    v.FRAIS,
    v.MONTANTHT,
    v.MONTANTTTC,
    v.MONTANTTVA,
    v.MONTANTREMISE,
    v.MONTANT,
    v.RISTOURNE,
    v.IDCLIENTLIB,
    v.DATY,
    v.DATYPREVU,
    v.IDPRODUITLIB,
    v.IDCATEGORIELIB,
    v.CATEGORIEPRODUITLIB,
    v.POIDS,
    CASE
        WHEN v.IDPREVISION IS NULL
            THEN v.IDPREVISION
        ELSE v.IDPREVISION||'---'||p.DESIGNATION
        END AS IDPREVISION ,
    v.CALORIE,
    v.IDRESERVATION,
    v.FRAISLIVRAISON,
    v.ristourneArbiochem,
    v.remiseArbiochem
FROM VENTE_DETAILS_VIDE v
         LEFT  JOIN AS_INGREDIENTS a ON a.id = v.IDPRODUIT
         LEFT JOIN PREVISION p ON p.ID = v.IDPREVISION;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VENTE_DIRECTE_CPL_PDF" ("ID", "DESIGNATION", "IDMAGASIN", "IDMAGASINLIB", "DATY", "DATYPREVU", "REMARQUE", "ETAT", "ADECLARER", "ETATLIB", "MONTANTTOTAL", "IDDEVISE", "IDCLIENT", "IDCLIENTLIB", "MONTANTTVA", "MONTANTTTC", "MONTANTTTCAR", "MONTANTPAYE", "MONTANTRESTE", "AVOIR", "TAUXDECHANGE", "MONTANTREVIENT", "MARGEBRUTE", "IDRESERVATION", "AVECCOMMISSION", "IDMODEPAIEMENT", "REFERENCEFACTURE", "IDMODEPAIEMENTLIB", "MONTANTDONNE", "MONTANTRETOURNER", "HEURESAISIE", "IDECHEANCEPAIEMENT", "ECHEANCEPAIEMENTLIB", "IDORIGINE", "DATYHEURE") AS
SELECT "ID","DESIGNATION","IDMAGASIN","IDMAGASINLIB","DATY","DATYPREVU","REMARQUE","ETAT","ADECLARER","ETATLIB","MONTANTTOTAL","IDDEVISE","IDCLIENT","IDCLIENTLIB","MONTANTTVA","MONTANTTTC","MONTANTTTCAR","MONTANTPAYE","MONTANTRESTE","AVOIR","TAUXDECHANGE","MONTANTREVIENT","MARGEBRUTE","IDRESERVATION","AVECCOMMISSION","IDMODEPAIEMENT","REFERENCEFACTURE","IDMODEPAIEMENTLIB","MONTANTDONNE","MONTANTRETOURNER","HEURESAISIE","IDECHEANCEPAIEMENT","ECHEANCEPAIEMENTLIB","IDORIGINE","DATYHEURE"
FROM (
         SELECT v.ID,
                v.DESIGNATION,
                v.IDMAGASIN,
                m.VAL AS IDMAGASINLIB,
                v.DATY,
                v.DATYPREVU,
                v.REMARQUE,
                v.ETAT,
                ADECLARER,
                CASE
                    WHEN v.ETAT = 1  THEN 'CR&Eacute;&Eacute;E'
                    WHEN v.ETAT = 11 THEN 'VIS&Eacute;E'
                    WHEN v.ETAT = 0  THEN 'ANNUL&Eacute;E'
                    END AS ETATLIB,
                v2.MONTANTTOTAL,
                v2.IDDEVISE,
                v.IDCLIENT,
                c.NOM AS IDCLIENTLIB,
                cast(V2.MONTANTTVA as number(30,2)) as MONTANTTVA,
                cast(V2.MONTANTTTC as number(30,2)) as montantttc,
                cast(V2.MONTANTTTCAR as number(30,2)) as MONTANTTTCAR,
                cast(nvl(mv.credit,0)-nvl(ACG.MONTANTPAYE, 0) AS NUMBER(30,2)) AS montantpaye,
                cast(V2.MONTANTTTC-nvl(mv.credit,0)-nvl(ACG.resteapayer_avr, 0) AS NUMBER(30,2)) AS montantreste,
                nvl(ACG.MONTANTTTC_avr, 0) as avoir,
                v2.tauxDeChange AS tauxDeChange,
                v2.MONTANTREVIENT,
                cast((V2.MONTANTTTCAR-v2.MONTANTREVIENT) as number(20,2)) as margeBrute,
                v.IDRESERVATION,
                CASE
                    WHEN cm.id IS NOT NULL THEN 'Oui'
                    ELSE                        'Non'
                    END AS avecCommission,
                v.idmodepaiement,
                rf.REFERENCE as referencefacture,
                mp.val AS idmodepaiementlib,
                CASE
                    WHEN v.MONTANTDONNE IS NULL OR v.MONTANTDONNE = 0
                        THEN cast(nvl(mv.credit,0)-nvl(ACG.MONTANTPAYE, 0) AS NUMBER(30,2))
                    ELSE cast(v.MONTANTDONNE AS NUMBER(30,2))
                    END AS MONTANTDONNE,
                nvl(mv.MONTANTRETOURNER, 0) as montantretourner,
                v.heureSaisie,
                V.IDECHEANCEPAIEMENT,
                EP.DESCE AS echeancePaiementLib,
                v.IDORIGINE,
                TO_DATE(v.daty || ' ' || v.heureSaisie, 'DD/MM/YYYY HH24:MI:SS') AS DATYHEURE
         FROM VENTE v
                  LEFT JOIN CLIENT c ON c.ID = v.IDCLIENT
                  LEFT JOIN MAGASIN m ON m.ID = v.IDMAGASIN
                  JOIN VENTEMONTANT v2 ON v2.ID = v.ID
                  LEFT JOIN MVTCAISSEGROUPEFACTURE_PDF mv ON v.id in mv.IDORIGINE
                  LEFT JOIN AVOIRFCLIB_CPL_GRP ACG on ACG.IDVENTE = v.ID
             LEFT JOIN COMMISSION cm ON cm.IDFACTURE = v.id
             LEFT JOIN MODEPAIEMENT mp ON mp.id = v.idmodepaiement
             LEFT JOIN REFERENCEFACTURE rf ON rf.idfacture=v.Id
             LEFT JOIN ECHEANCEPAIEMENT EP on EP.ID = V.IDECHEANCEPAIEMENT
     )
ORDER BY DATYHEURE DESC NULLS LAST;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VENTE_EDITEES" ("ID", "DATY", "IDRISTOURNE") AS
SELECT v.id,
       v.daty,
       r.idristourne
FROM VENTE_CPL v
JOIN (
    SELECT id as idristourne,
           REGEXP_SUBSTR(idorigine, '[^,]+', 1, LEVEL) AS idvente_explose
    FROM ristourne
    CONNECT BY REGEXP_SUBSTR(idorigine, '[^,]+', 1, LEVEL) IS NOT NULL
           AND PRIOR id = id
           AND PRIOR SYS_GUID() IS NOT NULL
) r
ON v.id = r.idvente_explose;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VENTE_ENCAISSE" ("IDVENTE", "IDRESERVATION", "MONTANTPAYE") AS
SELECT
v.id AS IDVENTE,
v.IDRESERVATION,
sum( nvl(ed.MONTANT,0) ) AS montantpaye
FROM ENCAISSEMENT_DETAILS ed
LEFT JOIN ENCAISSEMENT e ON e.id = ed.IDENCAISSEMENT
LEFT JOIN VENTE v ON v.id = e.IDORIGINE
GROUP BY v.id ,v.IDRESERVATION;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VENTE_GRP_CREE" ("IDVENTE", "COMPTE", "MONTANTHT", "MONTANTTVA", "MONTANTTTC", "ETAT") AS
select "IDVENTE","COMPTE","MONTANTHT","MONTANTTVA","MONTANTTTC","ETAT"
from VENTE_GRP_TOUS
where etat = 1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VENTE_GRP_CREER" ("IDVENTE", "COMPTE", "MONTANTHT", "MONTANTTVA", "MONTANTTTC", "ETAT") AS
select "IDVENTE","COMPTE","MONTANTHT","MONTANTTVA","MONTANTTTC","ETAT"
from VENTE_GRP_TOUS
where etat = 1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VENTE_GRP_SANSDEVISE" ("IDVENTE", "QTETOTAL", "MONTANTTC", "IDDEVISE") AS
SELECT 
vd.IDVENTE,
sum(nvl(vd.qte,0) ) AS qtetotal,
sum(nvl(vd.qte*pu,0) ) AS montanttc,
max(iddevise) AS iddevise
FROM VENTE_DETAILS vd 
GROUP BY vd.IDVENTE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VENTE_GRP_TOUS" ("IDVENTE", "COMPTE", "MONTANTHT", "MONTANTTVA", "MONTANTTTC", "MONTANTHTAR", "MONTANTTVAAR", "MONTANTTTCAR", "ETAT", "TAUXDECHANGE") AS
select IDVENTE,
       compte,
       cast(sum(montantHT) as NUMBER(30, 2)) as montantHT,
       cast(sum(montantTVA) as NUMBER(30, 2)) as montantTVA,
       cast(sum(montantTTC) as NUMBER(30, 2)) as montantTTC,
       cast(sum(montantHTAr) as NUMBER(30, 2)) as montantHTAr,
       cast(sum(montantTVAAr) as NUMBER(30, 2)) as montantTVAAr,
       cast(sum(montantTTCAr) as NUMBER(30, 2)) as montantTTCAr,
       ETAT,
       max(TAUXDECHANGE) AS TAUXDECHANGE
from VENTEDETCALC
group by IDVENTE, compte, etat;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VENTE_GRP_VISER" ("IDVENTE", "COMPTE", "MONTANTHT", "MONTANTTVA", "MONTANTTTC", "ETAT", "TAUXDECHANGE") AS
select IDVENTE,COMPTE,MONTANTHT,MONTANTTVA,MONTANTTTC,ETAT,TAUXDECHANGE
from VENTE_GRP_TOUS
where etat >=11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VENTE_LIB" ("IDORIGINE", "ID", "DESIGNATION", "IDMAGASIN", "IDMAGASINLIB", "DATY", "REMARQUE", "ETAT", "ETATLIB", "IDCLIENT", "IDCLIENTLIB") AS
SELECT
  v.IDORIGINE ,
v.ID ,
v.DESIGNATION ,
v.IDMAGASIN ,
m.VAL AS IDMAGASINLIB,
v.DATY ,
v.REMARQUE ,
v.ETAT ,
CASE
	WHEN v.ETAT = 1
	THEN 'CREE'
	WHEN v.ETAT = 11
	THEN 'VALIDEE'
	WHEN v.ETAT = 0
	THEN 'ANNULEE'
END AS ETATLIB,
v.IDCLIENT ,
c.NOM AS IDCLIENTLIB
FROM VENTE v
LEFT JOIN MAGASIN m ON m.ID = v.IDMAGASIN
LEFT JOIN CLIENT c ON c.ID = v.IDCLIENT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VENTE_LIB_ANNULEE" ("ID", "DESIGNATION", "IDMAGASIN", "IDMAGASINLIB", "DATY", "REMARQUE", "ETAT", "ETATLIB", "IDCLIENT", "IDCLIENTLIB", "IDRESERVATION") AS
SELECT
vl."ID",vl."DESIGNATION",vl."IDMAGASIN",vl."IDMAGASINLIB",vl."DATY",vl."REMARQUE",vl."ETAT",vl."ETATLIB",vl."IDCLIENT",vl."IDCLIENTLIB",vl."IDRESERVATION"
FROM VENTE_LIB vl
WHERE vl.ETAT = 0;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VENTE_LIB_BC" ("ID", "DESIGNATION", "IDORIGINE", "IDMAGASIN", "IDMAGASINLIB", "DATY", "REMARQUE", "ETAT", "ETATLIB", "MONTANTTOTAL", "IDDEVISE", "IDCLIENT", "IDCLIENTLIB", "MONTANTTVA", "MONTANTTTC", "MONTANTTTCAR", "MONTANTPAYE", "MONTANTRESTE", "AVOIR", "TAUXDECHANGE", "MONTANTREVIENT", "MARGEBRUTE", "IDRESERVATION") AS
SELECT v.ID,
          v.DESIGNATION,
          v.IDORIGINE,
          v.IDMAGASIN,
          m.VAL AS IDMAGASINLIB,
          v.DATY,
          v.REMARQUE,
          v.ETAT,
          CASE
             WHEN v.ETAT = 1 THEN 'CREE'
             WHEN v.ETAT = 11 THEN 'VISEE'
             WHEN v.ETAT = 0 THEN 'ANNULEE'
          END
             AS ETATLIB,
          v2.MONTANTTOTAL,
          v2.IDDEVISE,
          v.IDCLIENT,
          c.NOM AS IDCLIENTLIB,
          cast(V2.MONTANTTVA as number(30,2)) as MONTANTTVA,
          cast(V2.MONTANTTTC as number(30,2)) as montantttc,
          cast(V2.MONTANTTTCAR as number(30,2)) as MONTANTTTCAR,
          cast(nvl(mv.credit,0)-nvl(ACG.MONTANTPAYE, 0) AS NUMBER(30,2)) AS montantpaye,
          cast(V2.MONTANTTTC-nvl(mv.credit,0)-nvl(ACG.resteapayer_avr, 0) AS NUMBER(30,2)) AS montantreste,
          nvl(ACG.MONTANTTTC_avr, 0)  as avoir,
          v2.tauxDeChange AS tauxDeChange,v2.MONTANTREVIENT,cast((V2.MONTANTTTCAR-v2.MONTANTREVIENT) as number(20,2))  as margeBrute,
          v.IDRESERVATION
     FROM VENTE v
          LEFT JOIN CLIENT c ON c.ID = v.IDCLIENT
          LEFT JOIN MAGASIN m ON m.ID = v.IDMAGASIN
          JOIN VENTEMONTANT v2 ON v2.ID = v.ID
          LEFT JOIN mouvementcaisseGroupeFacture mv ON v.id=mv.IDORIGINE
		  LEFT JOIN AVOIRFCLIB_CPL_GRP ACG on ACG.IDVENTE = v.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VENTE_LIB_CREE" ("ID", "DESIGNATION", "IDMAGASIN", "IDMAGASINLIB", "DATY", "REMARQUE", "ETAT", "ETATLIB", "IDCLIENT", "IDCLIENTLIB", "IDRESERVATION") AS
SELECT
vl."ID",vl."DESIGNATION",vl."IDMAGASIN",vl."IDMAGASINLIB",vl."DATY",vl."REMARQUE",vl."ETAT",vl."ETATLIB",vl."IDCLIENT",vl."IDCLIENTLIB",vl."IDRESERVATION"
FROM VENTE_LIB vl
WHERE vl.ETAT = 1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VENTE_LIB_VISEE" ("ID", "DESIGNATION", "IDMAGASIN", "IDMAGASINLIB", "DATY", "REMARQUE", "ETAT", "ETATLIB", "IDCLIENT", "IDCLIENTLIB", "IDRESERVATION") AS
SELECT
vl."ID",vl."DESIGNATION",vl."IDMAGASIN",vl."IDMAGASINLIB",vl."DATY",vl."REMARQUE",vl."ETAT",vl."ETATLIB",vl."IDCLIENT",vl."IDCLIENTLIB",vl."IDRESERVATION"
FROM VENTE_LIB vl
WHERE vl.ETAT = 11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VENTE_MERE_MONTANT" ("ID", "DESIGNATION", "IDMAGASIN", "DATY", "REMARQUE", "ETAT", "IDORIGINE", "IDCLIENT", "MONTANTHT", "MONTANTTVA", "MONTANTTTC", "TAUXDECHANGE", "CLIENTLIB", "COMPTE", "IDRESERVATION") AS
select v.ID,v.DESIGNATION,v.IDMAGASIN,v.DATY,v.REMARQUE,v.ETAT,v.IDORIGINE,v.IDCLIENT,
       vt.MONTANTHT,
       vt.MONTANTTVA,
       vt.MONTANTTTC,
       vt.TAUXDECHANGE,
        CL.NOM AS CLIENTLIB,
       CL.COMPTE,
       v.IDRESERVATION
from VENTE v
left join VENTE_GRP_TOUS vt on vt.IDVENTE = v.id
left join CLIENT CL on CL.ID = v.IDCLIENT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VENTE_MF" ("ID", "IDVENTE", "IDPRODUIT", "IDORIGINE", "QTE", "PU", "REMISE", "TVA", "PUACHAT", "PUVENTE", "DESIGNATION", "IDMAGASIN", "DATY", "REMARQUE", "ETAT", "IDCLIENT", "COMPTE", "MONTANTHT", "MONTANTTVA", "MONTANTTTC", "TAUXDECHANGE", "IDRESERVATION") AS
select vd.ID,vd.IDVENTE,vd.IDPRODUIT,vd.IDORIGINE,vd.QTE,vd.PU,vd.REMISE,vd.TVA,vd.PUACHAT,vd.PUVENTE,
       v.DESIGNATION,
       v.IDMAGASIN,
       v.DATY,
       v.REMARQUE,
       v.ETAT,
       v.IDCLIENT,
       vd.compte,
       cast((PU * qte* (1-(nvl(vd.REMISE,0)/100))) as NUMBER(30, 2)) as montantHT,
       cast((PU * qte* (1-(nvl(vd.REMISE,0)/100)) *(tva/100)) as NUMBER(30, 2)) as montantTVA,
       cast(PU * qte* (1-(nvl(vd.REMISE,0)/100)) + (PU * qte* (1-(nvl(vd.REMISE,0)/100)) * (tva/100))  as NUMBER(30, 2)) as montantTTC,
       vd.TAUXDECHANGE AS tauxdechange,
       v.IDRESERVATION
from VENTE_DETAILS vd
         left outer join VENTE V on V.ID = vd.IDVENTE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VENTE_ORIGINE" ("IDORIGINE", "NOMBRE") AS
select IDORIGINE,count(*) as nombre from VENTE where ETAT>=11 group by IDORIGINE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VENTE_POIDS" ("IDVENTE", "POIDS", "COLIS") AS
select IDVENTE,sum(poids) as poids, sum(QTE) as colis from VENTE_DETAILS_POIDS group by IDVENTE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VENTE_PRELEVEMENT" ("ID", "IDPRELEVEMENTANTERIEUR", "COMPTEUR", "DATY", "HEURE", "IDPOMPISTE", "IDPOMPE", "ETAT", "MONTANTTOTALVENTE", "IDENCAISSEMENT", "MONTANTTOTALENCAISSEMENT") AS
SELECT
	p.ID ,
	p.IDPRELEVEMENTANTERIEUR ,
	p.COMPTEUR ,
	p.DATY ,
	p.HEURE ,
	p.IDPOMPISTE ,
	p.IDPOMPE ,
	p.ETAT ,
	nvl(vdc.montantTotalVente,0) AS montantTotalVente,
	pe.IDENCAISSEMENT ,
	nvl(m.montantTotalEncaissement,0) AS montantTotalEncaissement
FROM
	PRELEVEMENT p
LEFT JOIN PRELEVEMENT_ENCAISSE pe ON
	pe.IDPRELEVEMENT = p.ID
LEFT JOIN VENTEPRELEVEMENT vdc ON
	vdc.IDORIGINE = pe.IDPRELEVEMENT
LEFT JOIN MONTANTENCAISSEMENT m ON m.IDENCAISSEMENT = pe.IDENCAISSEMENT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VENTE_RECAP_JOUR" ("DATY", "MONTANTTTC", "MONTANTPAYE", "MONTANTRESTE", "NOMBRE", "MONTANTRESTEACEJOUR") AS
WITH BORNES AS (
    SELECT
        DATE '2026-06-01' AS DATE_MIN,
        TRUNC(SYSDATE) AS DATE_MAX
    FROM DUAL
),
CALENDRIER AS (
    SELECT
        DATE_MIN + LEVEL - 1 AS DATY
    FROM BORNES
    CONNECT BY LEVEL <= DATE_MAX - DATE_MIN + 1
),
VENTE_JOUR AS (
    SELECT
        TRUNC(DATY) AS DATY,
        SUM(NVL(MONTANTTTC, 0)) AS MONTANTTTC,
        SUM(NVL(MONTANTPAYE, 0)) AS MONTANTPAYE,
        SUM(NVL(MONTANTRESTE, 0)) AS MONTANTRESTE,
        COUNT(*) AS NOMBRE
    FROM VENTE_CPL
    WHERE ETAT = 11
      AND DATY >= DATE '2026-06-01'
    GROUP BY TRUNC(DATY)
)
SELECT
    c.DATY,

    CAST(NVL(v.MONTANTTTC, 0) AS NUMBER(30,5)) AS MONTANTTTC,
    CAST(NVL(v.MONTANTPAYE, 0) AS NUMBER(30,5)) AS MONTANTPAYE,
    CAST(NVL(v.MONTANTRESTE, 0) AS NUMBER(30,5)) AS MONTANTRESTE,
    CAST(NVL(v.NOMBRE, 0) AS NUMBER(10,0)) AS NOMBRE,

    CAST(
        SUM(NVL(v.MONTANTRESTE, 0))
        OVER (
            ORDER BY c.DATY
            ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
        )
        AS NUMBER(30,5)
    ) AS MONTANTRESTEACEJOUR

FROM CALENDRIER c
LEFT JOIN VENTE_JOUR v
    ON c.DATY = v.DATY;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VENTE_RESTE" ("IDVENTE", "RESTE") AS
select IDVENTE, sum(reste) reste
from VENTE_DETAILS_RESTE
group by IDVENTE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VENTE_SANS_RISTOURNE" ("ID", "DESIGNATION", "IDMAGASIN", "IDMAGASINLIB", "DATY", "REMARQUE", "ETAT", "ETATLIB", "MONTANTTOTAL", "IDDEVISE", "IDCLIENT", "IDCLIENTLIB", "MONTANTTVA", "MONTANTTTC", "MONTANTTTCAR", "MONTANTPAYE", "MONTANTRESTE", "AVOIR", "TAUXDECHANGE", "MONTANTREVIENT", "MARGEBRUTE", "IDRESERVATION", "DATYPREVU", "MOIS", "ANNEE") AS
SELECT v.ID,
       v.DESIGNATION,
       v.IDMAGASIN,
       v.IDMAGASINLIB,
       v.DATY,
       v.REMARQUE,
       v.ETAT,
       v.ETATLIB,
       v.MONTANTTOTAL,
       v.IDDEVISE,
       v.IDCLIENT,
       v.IDCLIENTLIB,
       v.MONTANTTVA,
       v.MONTANTTTC,
       v.MONTANTTTCAR,
       v.MONTANTPAYE,
       v.MONTANTRESTE,
       v.AVOIR,
       v.TAUXDECHANGE,
       v.MONTANTREVIENT,
       v.MARGEBRUTE,
       v.IDRESERVATION,
       v.DATYPREVU,
       v.mois,
       v.annee
FROM VENTE_CPL v
WHERE v.ETAT >= 11
  AND NOT EXISTS (
        SELECT 1
        FROM VENTE_EDITEES e
        WHERE e.id = v.id
  );

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VENTE_VALIDEE" ("ID", "IDVENTE", "IDPRODUIT", "IDORIGINE", "QTE", "PU", "IDRESERVATION") AS
SELECT
vd.ID,vd.IDVENTE,vd.IDPRODUIT,vd.IDORIGINE,vd.QTE,vd.PU,v.IDRESERVATION
FROM VENTE_DETAILS vd
LEFT JOIN VENTE v ON v.ID = vd.IDVENTE AND v.ETAT > 1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VERSEMENTCHEQUEDETAILSCPL" ("ID", "IDVERSEMENTCHEQUE", "IDVERSEMENTCHEQUELIB", "IDCHEQUE", "IDCHEQUELIB", "REMARQUE", "IDCAISSECHEQUE", "MONTANT", "DATY", "IDCAISSEVERSEMENT") AS
SELECT 
v.ID ,
v.IDVERSEMENTCHEQUE ,
v2.DESIGNATION AS IDVERSEMENTCHEQUELIB,
v.IDCHEQUE ,
c.REFERENCE AS IDCHEQUELIB,
v.REMARQUE ,
c.IDCAISSE AS idcaissecheque ,
c.MONTANT ,
v2.DATY ,
v2.IDCAISSE AS idcaisseversement
FROM VERSEMENTCHEQUEDETAILS v 
LEFT JOIN VERSEMENTCHEQUE v2 ON v2.ID = v.IDVERSEMENTCHEQUE 
LEFT JOIN CHEQUE c ON c.ID = v.IDCHEQUE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VESTOCKPRODFINI_CAT_PCENTAGE" ("ID", "IDTYPEPRODUITLIB", "QUANTITE", "POURCENTAGE", "DATY", "MONTANTRESTE") AS
SELECT
    TYPEPRODUIT        AS id,
    typeproduitlib AS idTypeProduitLib ,
    CAST(SUM(quantite) AS NUMBER(30,2))  AS quantite,
    CAST(
            SUM(quantite) * 100.0
                / SUM(SUM(quantite)) OVER ()
        AS NUMBER(10,2))                     AS pourcentage,
    CURRENT_DATE AS DATY,
    CAST(SUM(montantReste) AS NUMBER(30,2))  AS montantReste
FROM V_ETATSTOCK_PROD_FINI2 where TYPEPRODUIT is not null
GROUP BY TYPEPRODUIT, typeproduitlib;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VIEW_VIDE_SOMME" ("ID", "IDDEPARTEMENT", "IDTYPESOMME") AS
SELECT
    CAST(NULL AS VARCHAR2(50)) AS id,
    CAST(NULL AS VARCHAR2(50)) AS idDepartement,
    CAST(NULL AS VARCHAR2(50)) AS idTypeSomme
FROM dual
WHERE 1 = 0;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VIREMENTINTRACAISSECPL" ("ID", "DESIGNATION", "IDCAISSEDEPART", "IDCAISSEDEPARTLIB", "IDCAISSEARRIVE", "IDCAISSEARRIVELIB", "MONTANT", "DATY", "ETAT", "ETATLIB") AS
SELECT
	    v.ID ,
	    v.DESIGNATION ,
	    v.IDCAISSEDEPART ,
	    c.VAL AS IDCAISSEDEPARTLIB ,
	    v.IDCAISSEARRIVE ,
	    c2.VAL AS IDCAISSEARRIVELIB,
	    CAST(v.MONTANT AS NUMBER(30,5)) AS MONTANT   ,
	    v.DATY ,
	    v.ETAT ,
	    CASE
	        WHEN v.ETAT = 0
	            THEN 'ANNUL&Eacute;'
	        WHEN v.ETAT = 1
	            THEN 'CR&Eacute;&Eacute;'
	        WHEN v.ETAT = 11
	            THEN  'VIS&Eacute;'
	        END AS ETATLIB
	FROM VIREMENTINTRACAISSE v
	         LEFT JOIN CAISSE c ON c.ID = v.IDCAISSEDEPART
	         LEFT JOIN CAISSE c2 ON c2.ID  = v.IDCAISSEARRIVE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VIREMENTINTRACAISSECPL_ANNULE" ("ID", "DESIGNATION", "IDCAISSEDEPART", "IDCAISSEDEPARTLIB", "IDCAISSEARRIVE", "IDCAISSEARRIVELIB", "MONTANT", "DATY", "ETAT", "ETATLIB") AS
SELECT
		ID,DESIGNATION,IDCAISSEDEPART,IDCAISSEDEPARTLIB,IDCAISSEARRIVE,IDCAISSEARRIVELIB,MONTANT,DATY,ETAT,ETATLIB
	FROM 
		VIREMENTINTRACAISSECPL v 
	WHERE 
		v.etat = 0;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VIREMENTINTRACAISSECPL_CREE" ("ID", "DESIGNATION", "IDCAISSEDEPART", "IDCAISSEDEPARTLIB", "IDCAISSEARRIVE", "IDCAISSEARRIVELIB", "MONTANT", "DATY", "ETAT", "ETATLIB") AS
SELECT
		ID,DESIGNATION,IDCAISSEDEPART,IDCAISSEDEPARTLIB,IDCAISSEARRIVE,IDCAISSEARRIVELIB,MONTANT,DATY,ETAT,ETATLIB
	FROM 
		VIREMENTINTRACAISSECPL v 
	WHERE 
		v.etat = 1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VIREMENTINTRACAISSECPL_VALIDER" ("ID", "DESIGNATION", "IDCAISSEDEPART", "IDCAISSEDEPARTLIB", "IDCAISSEARRIVE", "IDCAISSEARRIVELIB", "MONTANT", "DATY", "ETAT", "ETATLIB") AS
SELECT
		ID,DESIGNATION,IDCAISSEDEPART,IDCAISSEDEPARTLIB,IDCAISSEARRIVE,IDCAISSEARRIVELIB,MONTANT,DATY,ETAT,ETATLIB
	FROM 
		VIREMENTINTRACAISSECPL v 
	WHERE 
		v.etat = 11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VUE_CARTONFILLE_IDMERE" ("IDBCFILLE", "ID_CARTON_MERE") AS
SELECT
  cf.IDBCFILLE,
  MIN(cf.IDMERE) AS ID_CARTON_MERE
FROM CARTONFILLE cf
JOIN CARTON c ON c.ID = cf.IDMERE AND c.ETAT >= 11
GROUP BY cf.IDBCFILLE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VUE_CARTONFILLE_SUM" ("IDBCFILLE", "QUANTITE_CARTONFILLE") AS
SELECT
  cf.IDBCFILLE,
  SUM(cf.QUANTITE) AS QUANTITE_CARTONFILLE
FROM CARTONFILLE cf
JOIN CARTON c ON c.ID = cf.IDMERE AND c.ETAT >= 11
GROUP BY cf.IDBCFILLE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VUE_CNAPS" ("IDPERSONNEL", "MOIS", "ANNEE", "RETENUE") AS
SELECT pe.idpersonnel,
       pe.mois,
       pe.annee,
       pe.retenue
FROM paie_edition pe
WHERE pe.idelementpaie = 'PR000101';

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VUE_CONTRAT_LIB" ("ID", "MATRICULE", "NOM", "PRENOM", "SEXE", "DATEEMBAUCHE", "PERIODE", "DATE_FIN_CONTRAT", "ETAT", "TYPE_CONTRAT") AS
SELECT
    lpf.idpersonnel AS id,
    lpf.matricule,
    lpf.nom,
    lpf.prenom,
    lpf.sexe,
    pip.dateembauche,
    pip.indesirable AS periode,
    CASE
        WHEN pip.indesirable > 0 THEN pip.dateembauche + INTERVAL '1' MONTH * pip.indesirable
        ELSE NULL
        END AS date_fin_contrat,
    lpf.etat,
    tc.val AS type_contrat
FROM
    log_personnel_fin lpf
        JOIN paie_info_personnel pip ON pip.id = lpf.idpersonnel
        JOIN type_contrat tc ON tc.id = pip.typecontrat;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VUE_ID_MATRICULE" ("ID", "PRENOM", "NOM", "MATRICULE", "DIRECTION", "IDDIRECTION", "ETAT") AS
SELECT lp.id,
       lp.prenom,
       lp.nom,
       pip.matricule,
       ld.VAL AS direction,
       ld.ID AS iddirection,
       pip.ETAT
FROM paie_info_personnel pip
         JOIN log_personnel lp ON pip.id = lp.id
         LEFT JOIN LOG_DIRECTION ld ON ld.ID = lp.direction;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VUE_SUIVI_CARTON" ("ID", "IDBC_MERE", "PRODUITLIB", "QUANTITEBCF", "QUANTITECARTONFILLE", "RESTECARTONFILLE") AS
SELECT 
    bcf.ID AS id,
    bcf.IDBC AS idbc_mere,
    ai.LIBELLE AS produitlib,
    NVL(bcf.QUANTITE, 0) AS quantitebcf,
    NVL(SUM(cf.QUANTITE), 0) AS quantitecartonfille,
    NVL(bcf.QUANTITE, 0) - NVL(SUM(cf.QUANTITE), 0) AS restecartonfille
FROM BONDECOMMANDE_CLIENT_FILLE bcf
LEFT JOIN CARTONFILLE cf ON cf.IDBCFILLE = bcf.ID
LEFT JOIN CARTON c ON c.ID = cf.IDMERE AND c.ETAT > 11
LEFT JOIN AS_INGREDIENTS ai ON ai.ID = bcf.PRODUIT
GROUP BY 
    bcf.ID,
    bcf.IDBC,
    ai.LIBELLE,
    bcf.QUANTITE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VUE_SUIVI_CARTON_LIVRAISON" ("ID", "IDBC_MERE", "IDCARTONMERE", "PRODUIT", "PRODUITLIB", "UNITE", "QUANTITEBCF", "QUANTITECARTONFILLE", "RESTECARTONFILLE") AS
SELECT 
    bcf.ID AS id,
    bcf.IDBC AS idbc_mere,
    vci.ID_CARTON_MERE AS idCartonMere,
    ai.ID AS produit,
    ai.LIBELLE AS produitlib,
    ai.UNITE AS unite,
    NVL(bcf.QUANTITE, 0) AS quantitebcf,
    NVL(vc.QUANTITE_CARTONFILLE, 0) AS quantitecartonfille,
    NVL(bcf.QUANTITE, 0) - NVL(vc.QUANTITE_CARTONFILLE, 0) AS restecartonfille
FROM BONDECOMMANDE_CLIENT_FILLE bcf
LEFT JOIN AS_INGREDIENTS ai ON ai.ID = bcf.PRODUIT
LEFT JOIN VUE_CARTONFILLE_SUM vc ON vc.IDBCFILLE = bcf.ID
LEFT JOIN VUE_CARTONFILLE_IDMERE vci ON vci.IDBCFILLE = bcf.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VW_HS_CUMUL_WEEK" ("IDPERSONNEL", "SEMAINE", "TOTAL_HS") AS
SELECT
    pip.id as IDPERSONNEL,
    TO_CHAR(f.DATY, 'IYYY-IW') AS SEMAINE,
    NVL(SUM(hp.HS), 0) AS TOTAL_HS
FROM HEURESUPFABRICATION hp
         LEFT JOIN FABRICATION f ON f.ID = hp.IDFABRICATION
         LEFT JOIN RESSOURCEPARFABRICATION ress ON ress.id = hp.IDRESSPARFAB
         LEFT JOIN PAIE_INFO_PERSONNEL pip ON pip.id = ress.IDRESSOURCE

GROUP BY
    pip.id,
    TO_CHAR(f.DATY, 'IYYY-IW');

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VW_MOUVEMENTCAISSE_TOTAL_DEBIT" ("IDBC", "TOTAL_DEBIT") AS
SELECT
    idbc,
    SUM(debit) AS total_debit
FROM mouvementcaisse
GROUP BY idbc;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_ACCIDENT_LIB" ("ID", "DATY", "DATE_DECLARATION", "ID_PERSONNEL", "ID_LIEU", "ID_TYPE_ACCIDENT", "ID_GRAVITE", "ID_MACHINE", "CAUSE", "HEUREACCIDENT", "HORAIREDEBUT", "HORAIREFIN", "ACTIVITE", "LESIONS", "CENTRESOIN", "DETAILSTEMOIN1", "DETAILSTEMOIN2", "ETAT", "ID_MACHINE_LIB", "ID_LIEU_LIB", "ID_TYPE_ACCIDENT_LIB", "ID_GRAVITE_LIB", "ID_PERSONNEL_LIB", "MATRICULE", "ETAT_LIB") AS
SELECT acc."ID",acc."DATY",acc."DATE_DECLARATION",acc."ID_PERSONNEL",acc."ID_LIEU",acc."ID_TYPE_ACCIDENT",acc."ID_GRAVITE",acc."ID_MACHINE",acc."CAUSE",acc."HEUREACCIDENT",acc."HORAIREDEBUT",acc."HORAIREFIN",acc."ACTIVITE",acc."LESIONS",acc."CENTRESOIN",acc."DETAILSTEMOIN1",acc."DETAILSTEMOIN2",acc."ETAT",
       m.VAL AS id_machine_lib,
       lat.val AS id_lieu_lib,
       ta.VAL AS id_type_accident_lib,
       ga.val AS id_gravite_lib,
       lp.NOM || ' ' || lp.prenom AS id_personnel_lib,
       pip.MATRICULE AS matricule,
       CASE
           WHEN acc.etat = 1 THEN 'Cree'
           WHEN acc.etat = 11 THEN 'Declare'
           ELSE 'inconnu'
       END AS etat_lib
FROM Accident acc
         LEFT JOIN MACHINE m ON m.ID = acc.Id_machine
         LEFT JOIN lieu_accident_travail lat ON lat.ID = acc.id_lieu
         LEFT JOIN type_accident ta ON ta.id = acc.id_type_accident
         LEFT JOIN gravite_accident ga ON ga.id = acc.id_gravite
         LEFT JOIN LOG_PERSONNEL lp ON lp.ID = acc.ID_PERSONNEL
         LEFT JOIN PAIE_INFO_PERSONNEL pip ON pip.id = acc.ID_PERSONNEL;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_ACCIDENT_PDF" ("ID", "DATY", "DATE_DECLARATION", "ID_PERSONNEL", "ID_LIEU", "ID_TYPE_ACCIDENT", "ID_GRAVITE", "ID_MACHINE", "CAUSE", "ETAT", "ID_MACHINE_LIB", "ID_LIEU_LIB", "ID_TYPE_ACCIDENT_LIB", "ID_GRAVITE_LIB", "ID_PERSONNEL_LIB", "MATRICULE", "ETAT_LIB", "DETAILSTEMOIN1", "DETAILSTEMOIN2", "HEUREACCIDENT", "HORAIREDEBUT", "HORAIREFIN", "ACTIVITE", "LESIONS", "CENTRESOIN", "NUMERO_CIN", "DATE_NAISSANCE", "FONCTION", "ADRESSE", "DATEEMBAUCHE", "NUMERO_CNAPS") AS
SELECT acc."ID",acc."DATY",acc."DATE_DECLARATION",acc."ID_PERSONNEL",acc."ID_LIEU",acc."ID_TYPE_ACCIDENT",acc."ID_GRAVITE",acc."ID_MACHINE",acc."CAUSE",acc."ETAT",
       m.VAL AS id_machine_lib,
       lat.val AS id_lieu_lib,
       ta.VAL AS id_type_accident_lib,
       ga.val AS id_gravite_lib,
       lp.NOM || ' ' || lp.prenom AS id_personnel_lib,
       pip.MATRICULE AS matricule,
       CASE
           WHEN acc.etat = 1 THEN 'Cree'
           WHEN acc.etat = 11 THEN 'Declare'
           ELSE 'inconnu'
           END AS etat_lib,
       acc.DETAILSTEMOIN1,
       acc.DETAILSTEMOIN2,
       acc.HEUREACCIDENT,
       acc.HORAIREDEBUT,
       acc.HORAIREFIN,
       acc.ACTIVITE,
       acc.LESIONS,
       acc.CENTRESOIN,
       lp.NUMERO_CIN,
       lp.DATE_NAISSANCE,
       pf.val as fonction,
       lp.ADRESSE,
       pip.DATEEMBAUCHE,
       pip.NUMERO_CNAPS
FROM Accident acc
         LEFT JOIN MACHINE m ON m.ID = acc.Id_machine
         LEFT JOIN lieu_accident_travail lat ON lat.ID = acc.id_lieu
         LEFT JOIN type_accident ta ON ta.id = acc.id_type_accident
         LEFT JOIN gravite_accident ga ON ga.id = acc.id_gravite
         LEFT JOIN LOG_PERSONNEL lp ON lp.ID = acc.ID_PERSONNEL
         LEFT JOIN PAIE_INFO_PERSONNEL pip ON pip.id = acc.ID_PERSONNEL
         LEFT JOIN PAIE_FONCTION pf ON pf.id = pip.IDFONCTION;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_ARRETTRAVAIL_LIB" ("ID", "DATY", "DATE_FIN_ARRET", "DATE_DEBUT_ARRET", "ID_ACCIDENT", "NOMBRE_JOUR", "NOMPERSONNEL", "MATRICULE", "DATEACCIDENT", "ID_PERSONNEL") AS
SELECT
    at.id,
    at.DATY,
    at.DATE_FIN_ARRET,
    at.DATE_DEBUT_ARRET,
    at.ID_ACCIDENT,
    at.NOMBRE_JOUR,
    acc.id_personnel_lib as nomPersonnel,
    acc.MATRICULE,
    acc.DATY as dateAccident,
    acc.ID_PERSONNEL
FROM ARRET_TRAVAIL at
        left join V_ACCIDENT_LIB acc ON acc.id = at.ID_ACCIDENT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_BALANCE_DETAILS" ("ANNEE", "MOIS", "COMPTE", "LIBELLECOMPTE", "DEBIT", "CREDIT", "COMPTE3", "COMPTE2", "CUMULDEBIT", "CUMULCREDIT") AS
WITH mois_annees AS (
    SELECT
        ADD_MONTHS(TRUNC(SYSDATE, 'MM'), LEVEL - 25) AS mois
    FROM DUAL
        CONNECT BY LEVEL <= 49
        ),
        base_comptes_periode AS (
        SELECT
        CAST(c.compte AS VARCHAR2(100)) AS compte,
        c.libelle AS libelleCompte,
        m.mois,
        EXTRACT(YEAR FROM m.mois) AS annee,
        EXTRACT(MONTH FROM m.mois) AS mois_num
        FROM
        compta_compte c
        CROSS JOIN mois_annees m
        ),
        ecritures_mensuelles AS (
    -- Excludes journal = 'COMP000015'
        SELECT
        CAST(cse.compte AS VARCHAR2(100)) AS compte,
        TRUNC(cse.daty, 'MM') AS mois,
        SUM(cse.debit) AS soldeDebit,
        SUM(cse.credit) AS soldeCredit
        FROM
        compta_sous_ecriture cse
        JOIN compta_ecriture ce ON ce.id = cse.idmere
        WHERE
        cse.daty IS NOT NULL
        AND cse.etat >= 11
        AND cse.journal != 'COMP000015'
        GROUP BY
        cse.compte, TRUNC(cse.daty, 'MM')
        ),
        ecritures_mensuelles_cumuls AS (
    -- Includes all journals, including 'COMP000015'
        SELECT
        CAST(cse.compte AS VARCHAR2(100)) AS compte,
        TRUNC(cse.daty, 'MM') AS mois,
        SUM(cse.debit) AS cumulDebit,
        SUM(cse.credit) AS cumulCredit
        FROM
        compta_sous_ecriture cse
        JOIN compta_ecriture ce ON ce.id = cse.idmere
        WHERE
        cse.daty IS NOT NULL
        AND cse.etat >= 11
        GROUP BY
        cse.compte, TRUNC(cse.daty, 'MM')
        ),
        fusion_comptes_mois AS (
        SELECT
        b.annee,
        b.mois_num AS mois,
        b.compte,
        b.libelleCompte,
        b.mois AS date_mois,
        NVL(em.soldeDebit, 0) AS soldeDebit,
        NVL(em.soldeCredit, 0) AS soldeCredit,
        NVL(ec.cumulDebit, 0) AS cumulDebit,
        NVL(ec.cumulCredit, 0) AS cumulCredit
        FROM
        base_comptes_periode b
        LEFT JOIN ecritures_mensuelles em ON b.compte = em.compte AND b.mois = em.mois
        LEFT JOIN ecritures_mensuelles_cumuls ec ON b.compte = ec.compte AND b.mois = ec.mois
        )
SELECT
    annee,
    mois,
    compte,
    libelleCompte,
    ROUND(soldeDebit, 2) AS debit,
    ROUND(soldeCredit, 2) AS credit,
    TO_NUMBER(SUBSTR(compte, 1, 3)) AS compte3,
    TO_NUMBER(SUBSTR(compte, 1, 2)) AS compte2,
    ROUND(
            SUM(cumulDebit) OVER (
            PARTITION BY compte ORDER BY date_mois
            ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
        ), 2
    ) AS cumulDebit,
    ROUND(
            SUM(cumulCredit) OVER (
            PARTITION BY compte ORDER BY date_mois
            ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
        ), 2
    ) AS cumulCredit
FROM
    fusion_comptes_mois
ORDER BY
    compte, annee, mois;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_BALANCE_DETAILS_ANALYTIQUE" ("ANNEE", "MOIS", "COMPTE", "LIBELLECOMPTE", "DEBIT", "CREDIT", "COMPTE3", "COMPTE2", "CUMULDEBIT", "CUMULCREDIT") AS
WITH mois_annees AS (
    SELECT
        ADD_MONTHS(TRUNC(SYSDATE, 'MM'), LEVEL - 25) AS mois
    FROM DUAL
        CONNECT BY LEVEL <= 49
        ),
        base_comptes_periode AS (
        SELECT
        CAST(c.compte AS VARCHAR2(100)) AS compte,
        c.libelle AS libelleCompte,
        m.mois,
        EXTRACT(YEAR FROM m.mois) AS annee,
        EXTRACT(MONTH FROM m.mois) AS mois_num
        FROM
        compta_compte c
        CROSS JOIN mois_annees m
        WHERE
        c.typecompte = '3'
        ),
        ecritures_mensuelles AS (
    -- For monthly values: EXCLUDE journal = 'COMP000015'
        SELECT
        CAST(cse.compte AS VARCHAR2(100)) AS compte,
        TRUNC(cse.daty, 'MM') AS mois,
        SUM(cse.debit) AS soldeDebit,
        SUM(cse.credit) AS soldeCredit
        FROM
        compta_sous_ecriture cse
        JOIN compta_ecriture ce ON ce.id = cse.idmere
        WHERE
        cse.daty IS NOT NULL
        AND cse.etat >= 11
        AND ce.journal != 'COMP000015'
        GROUP BY
        cse.compte, TRUNC(cse.daty, 'MM')
        ),
        ecritures_mensuelles_cumuls AS (
    -- For cumulative values: INCLUDE everything
        SELECT
        CAST(cse.compte AS VARCHAR2(100)) AS compte,
        TRUNC(cse.daty, 'MM') AS mois,
        SUM(cse.debit) AS cumulDebit,
        SUM(cse.credit) AS cumulCredit
        FROM
        compta_sous_ecriture cse
        JOIN compta_ecriture ce ON ce.id = cse.idmere
        WHERE
        cse.daty IS NOT NULL
        AND cse.etat >= 11
        GROUP BY
        cse.compte, TRUNC(cse.daty, 'MM')
        ),
        fusion_comptes_mois AS (
        SELECT
        b.annee,
        b.mois_num AS mois,
        b.compte,
        b.libelleCompte,
        b.mois AS date_mois,
        NVL(em.soldeDebit, 0) AS soldeDebit,
        NVL(em.soldeCredit, 0) AS soldeCredit,
        NVL(ec.cumulDebit, 0) AS cumulDebit,
        NVL(ec.cumulCredit, 0) AS cumulCredit
        FROM
        base_comptes_periode b
        LEFT JOIN ecritures_mensuelles em ON b.compte = em.compte AND b.mois = em.mois
        LEFT JOIN ecritures_mensuelles_cumuls ec ON b.compte = ec.compte AND b.mois = ec.mois
        )
SELECT
    annee,
    mois,
    compte,
    libelleCompte,
    ROUND(soldeDebit, 2) AS debit,
    ROUND(soldeCredit, 2) AS credit,
    TO_NUMBER(SUBSTR(compte, 1, 3)) AS compte3,
    TO_NUMBER(SUBSTR(compte, 1, 2)) AS compte2,
    ROUND(
            SUM(cumulDebit) OVER (
            PARTITION BY compte ORDER BY date_mois
            ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
        ), 2
    ) AS cumulDebit,
    ROUND(
            SUM(cumulCredit) OVER (
            PARTITION BY compte ORDER BY date_mois
            ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
        ), 2
    ) AS cumulCredit
FROM
    fusion_comptes_mois
ORDER BY
    compte, annee, mois;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_BALANCE_DETAILS_AUX" ("ANNEE", "MOIS", "COMPTE", "LIBELLECOMPTE", "DEBIT", "CREDIT", "COMPTE3", "COMPTE2", "CUMULDEBIT", "CUMULCREDIT") AS
WITH mois_annees AS (
    SELECT
        ADD_MONTHS(TRUNC(SYSDATE, 'MM'), LEVEL - 25) AS mois
    FROM DUAL
        CONNECT BY LEVEL <= 49
        ),
        base_comptes_periode AS (
        SELECT
        CAST(c.compte AS VARCHAR2(100)) AS compte,
        c.libelle AS libelleCompte,
        m.mois,
        EXTRACT(YEAR FROM m.mois) AS annee,
        EXTRACT(MONTH FROM m.mois) AS mois_num
        FROM
        compte_aux c
        CROSS JOIN mois_annees m
        ),
        ecritures_mensuelles AS (
    -- Excludes journal = 'COMP000015'
        SELECT
        CAST(cse.COMPTE_AUX AS VARCHAR2(100)) AS compte,
        TRUNC(cse.daty, 'MM') AS mois,
        SUM(cse.debit) AS soldeDebit,
        SUM(cse.credit) AS soldeCredit
        FROM
        compta_sous_ecriture cse
        JOIN compta_ecriture ce ON ce.id = cse.idmere
        WHERE
        cse.daty IS NOT NULL
        AND cse.etat >= 11
        AND cse.journal != 'COMP000015'
        GROUP BY
        cse.COMPTE_AUX, TRUNC(cse.daty, 'MM')
        ),
        ecritures_mensuelles_cumuls AS (
    -- Includes all journals, including 'COMP000015'
        SELECT
        CAST(cse.COMPTE_AUX AS VARCHAR2(100)) AS compte,
        TRUNC(cse.daty, 'MM') AS mois,
        SUM(cse.debit) AS cumulDebit,
        SUM(cse.credit) AS cumulCredit
        FROM
        compta_sous_ecriture cse
        JOIN compta_ecriture ce ON ce.id = cse.idmere
        WHERE
        cse.daty IS NOT NULL
        AND cse.etat >= 11
        GROUP BY
        cse.COMPTE_AUX, TRUNC(cse.daty, 'MM')
        ),
        fusion_comptes_mois AS (
        SELECT
        b.annee,
        b.mois_num AS mois,
        b.compte,
        b.libelleCompte,
        b.mois AS date_mois,
        NVL(em.soldeDebit, 0) AS soldeDebit,
        NVL(em.soldeCredit, 0) AS soldeCredit,
        NVL(ec.cumulDebit, 0) AS cumulDebit,
        NVL(ec.cumulCredit, 0) AS cumulCredit
        FROM
        base_comptes_periode b
        LEFT JOIN ecritures_mensuelles em ON b.compte = em.compte AND b.mois = em.mois
        LEFT JOIN ecritures_mensuelles_cumuls ec ON b.compte = ec.compte AND b.mois = ec.mois
        )
SELECT
    annee,
    mois,
    compte,
    libelleCompte,
    ROUND(soldeDebit, 2) AS debit,
    ROUND(soldeCredit, 2) AS credit,
    TO_NUMBER(SUBSTR(compte, 1, 3)) AS compte3,
    TO_NUMBER(SUBSTR(compte, 1, 2)) AS compte2,
    ROUND(
            SUM(cumulDebit) OVER (
            PARTITION BY compte ORDER BY date_mois
            ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
        ), 2
    ) AS cumulDebit,
    ROUND(
            SUM(cumulCredit) OVER (
            PARTITION BY compte ORDER BY date_mois
            ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
        ), 2
    ) AS cumulCredit
FROM
    fusion_comptes_mois
ORDER BY
    compte, annee, mois;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_BILAN_SECTION_COMPTE_COMPLET" ("ID", "IDBILANSECTION", "EXERCICE", "COMPTE", "DEBIT", "CREDIT") AS
SELECT 
bsc.ID ,
bsc.IDBILANSECTION ,
ce.ID AS exercice ,
bsc.COMPTE ,
sum(nvl(cse.DEBIT,0)) AS debit,
sum(nvl(cse.CREDIT,0)) AS credit
FROM BILAN_SECTION_COMPTE bsc
JOIN COMPTA_EXERCICE ce ON 1=1
JOIN BILANSECTION b ON b.ID = bsc.IDBILANSECTION 
LEFT JOIN COMPTA_SOUS_ECRITURE cse ON cse.COMPTE = bsc.COMPTE AND EXTRACT(YEAR FROM cse.daty) = ce.id 
GROUP BY bsc.ID,bsc.IDBILANSECTION,ce.ID,bsc.COMPTE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_CATEGORIEINGREDIENT" ("ID", "VAL", "DESCE") AS
select c.id, val, desce from CATEGORIEINGREDIENT c where ACTIF > 0;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_CLASSEETFICHE" ("ID", "CLASSE", "FICHE", "LIBELLE") AS
select
    id, classe, fiche,
    nvl(libelle, REGEXP_SUBSTR(classe, '[^\.]+', 1, REGEXP_COUNT(classe, '\.') + 1)) as libelle
from CLASSEETFICHE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_COMPTA_COMPTE" ("ID", "COMPTEINT", "COMPTE", "LIBELLE", "TYPECOMPTE", "CLASSY", "ANALYTIQUE_OBLI", "IDJOURNAL", "CODEIMPOT") AS
SELECT
    id,
    TO_NUMBER(REGEXP_SUBSTR(TRIM(compte), '^[0-9]+')) AS compteInt,
    compte,
    libelle,
    typecompte,
    classy,
    analytique_obli,
    idjournal,
    codeimpot
FROM compta_compte
WHERE REGEXP_LIKE(TRIM(compte), '^[0-9]+');

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_COMPTA_ETAT_BALANCE" ("EXERCICE", "TYPECOMPTE", "MOISDEBUT", "MOISFIN", "DEBUTCOMPTE", "FINCOMPTE", "ETAT") AS
select
    CAST(0 AS int) as exercice,
    CAST(' ' AS varchar(1)) as typeCompte,
    CAST(0 AS int) as moisDebut,
    CAST(0 AS int) as moisFin,
    CAST(' ' AS varchar(1)) as debutCompte,
    CAST(' ' AS varchar(1)) as finCompte,
    CAST(0 AS int) as etat
from dual;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_CV_SCORE_GLOBAL" ("IDCV", "IDFICHEPOSTE", "NBCOMPETENCES", "NBCOMPETENCESVALIDES", "NBCOMPETENCESNONVALIDES", "SCORE") AS
SELECT
    v.IDCV                                          AS idCv,
    v.IDFICHEPOSTE                                  AS idFichePoste,
    COUNT(*)                                        AS nbCompetences,
    SUM(v.ESTVALIDE)                                AS nbCompetencesValides,
    COUNT(*) - SUM(v.ESTVALIDE)                     AS nbCompetencesNonValides,
    ROUND((SUM(v.ESTVALIDE) / COUNT(*)) * 100, 2)   AS score
FROM V_MATCHING_CV_FP v
GROUP BY
    v.IDCV,
    v.IDFICHEPOSTE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_DETAILSBONCAISSECLIENTRESTE" ("ID", "IDCLIENTLIB", "IDCAISSE", "IDCAISSELIB", "IDPOINT", "IDPOINTLIB", "DEBIT", "CREDIT", "RESTE") AS
SELECT
	d.IDCLIENT as ID,
	d.IDCLIENTLIB,
	d.IDCAISSE,
	d.IDCAISSELIB,
	d.IDPOINT,
	d.IDPOINTLIB,
	sum(d.DEBIT) as DEBIT,
	sum(d.CREDIT) as CREDIT,
	sum(d.CREDIT)-sum(d.DEBIT) AS reste
FROM
	DetailsBonCaisseCpl d
GROUP by
	d.IDCAISSE,
	d.IDCAISSELIB,
	d.IDPOINT,
	d.IDPOINTLIB,
	d.IDCLIENT,
	d.IDCLIENTLIB;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_DUREE_AGREGEE_TRAVAUX" ("REFOBJET", "DUREE_REELLE_TOTAL_HEURES", "ECART_ENREGISTRE") AS
SELECT
    REFOBJET,
    SUM(DUREE_HEURES_DECIMALE) AS DUREE_REELLE_TOTAL_HEURES,
    MAX(ECART) AS ECART_ENREGISTRE
FROM V_DUREE_REELLE_TRAVAUX
GROUP BY REFOBJET;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_DUREE_REELLE_TRAVAUX" ("REFOBJET", "OBJET", "ACTION", "DATEHISTORIQUE", "HEURE", "DUREE_HEURES_DECIMALE", "ECART") AS
SELECT
    p.REFOBJET,
    p.OBJET,
    p.ACTION,
    p.DATEHISTORIQUE,
    p.HEURE,
    CASE
        WHEN p.HEURE IS NOT NULL THEN
            TO_NUMBER(SUBSTR(p.HEURE, 1, INSTR(p.HEURE, ':') - 1)) +
            (TO_NUMBER(SUBSTR(p.HEURE, INSTR(p.HEURE, ':') + 1)) / 60)
        ELSE NULL
        END AS DUREE_HEURES_DECIMALE,
    p.ECART
FROM PROCESS p
WHERE p.REFOBJET IS NOT NULL;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_DUREE_TRAVAUX_MACHINE" ("IDINGREDIENTS", "DESCRIPTIONOBJET", "DATY", "ID_TRAVAUX", "DUREE_ESTIMATIVE_HEURES", "DUREE_REELLE_HEURES", "ECART_HEURES", "ECART_POURCENTAGE", "ECART_ENREGISTRE") AS
SELECT
    CASE
        WHEN aim.id IS NULL THEN ai.id
        ELSE aim.id
        END AS idIngredients,
    CASE
        WHEN aim.libelle IS NULL THEN ai.descriptionObjet
        ELSE aim.libelle
        END AS DESCRIPTIONOBJET,
    t.DATY,
    t.ID AS ID_TRAVAUX,
    NVL(t.DUREEESTIMATIF, 0) AS DUREE_ESTIMATIVE_HEURES,
    COALESCE(vd.DUREE_REELLE_TOTAL_HEURES, 0) AS DUREE_REELLE_HEURES,
    COALESCE(vd.DUREE_REELLE_TOTAL_HEURES, 0) - COALESCE (t.DUREEESTIMATIF, 0) AS ECART_HEURES,
    CASE
        WHEN t.DUREEESTIMATIF > 0 THEN
            ROUND(((COALESCE(vd.DUREE_REELLE_TOTAL_HEURES, 0) - t.DUREEESTIMATIF) / t.DUREEESTIMATIF) * 100, 2)
        ELSE NULL
        END AS ECART_POURCENTAGE,
    vd.ECART_ENREGISTRE
FROM ORDRETRAVAUXFILLE o
         LEFT JOIN AS_INGREDIENTS aim
                   ON o.IDINGREDIENTS = aim.ID
         LEFT JOIN as_ingredient_maintenance ai
                   ON o.IDINGREDIENTS = ai.ID
         JOIN TRAVAUX t
              ON o.id = t.IDOFFILLE
         LEFT JOIN V_DUREE_AGREGEE_TRAVAUX vd
                   ON vd.REFOBJET = t.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_ETATCAISSE" ("IDCAISSE", "IDCAISSELIB", "CREDIT", "DEBIT", "RESTE", "TAUX", "RESTEAR", "DATY", "ID", "DATEDERNIERREPORT", "MONTANTDERNIERREPORT", "IDPOINT", "IDPOINTLIB", "IDTYPECAISSE", "IDTYPECAISSELIB", "MOTSCLESSS") AS
WITH MAX_INVENTAIRE AS (
    -- Etape 1 : On extrait la date maximale valide et la quantite par COUPLE produit/magasin
    SELECT REP.IDCAISSE,
           MAX(REP.DATY)                                             AS MAX_DATY,
           MAX(REP.MONTANT) KEEP (DENSE_RANK LAST ORDER BY REP.DATY) AS MONTANT_MAX_DATY
    FROM REPORTCAISSEAVECHEURE REP
    WHERE REP.ETAT >= 11 --and rep.DATY<=TO_DATE('27/07/2026','DD-MM-YYYY')
    GROUP BY REP.IDCAISSE),
     TAUXCHANGEMAX
         AS (SELECT MAX(TAU.TAUX) KEEP (DENSE_RANK LAST ORDER BY TAU.DATY) AS TAUX,
                    TAU.IDDEVISE                                           AS TAUXIDDEVISE,
                    MAX(TAU.DATY)                                          AS TAUXDATY
             FROM TAUXDECHANGE TAU
             GROUP BY IDDEVISE),
     SOMME_PRECALC AS (SELECT C.ID                              AS IDCAISSE,
                              C.VAL                             AS IDCAISSELIB,
                              NVL(SUM(CASE
                                          WHEN MFF.DATY > NVL(INV.MAX_DATY, DATE '2025-01-01') THEN MFF.CREDIT
                                          ELSE 0 END), 0)       AS CREDIT,

                              NVL(SUM(CASE
                                          WHEN MFF.DATY > NVL(INV.MAX_DATY, DATE '2025-01-01') THEN MFF.DEBIT
                                          ELSE 0 END), 0)       AS DEBIT,
                              MAX(INV.MAX_DATY)                 AS DATEDERNIERREPORT,
                              NVL(MAX(INV.MONTANT_MAX_DATY), 0) AS MONTANTDERNIERREPORT,
                              C.IDPOINT,
                              P.VAL                             AS IDPOINTLIB,
                              C.IDTYPECAISSE,
                              TYP.VAL                           AS IDTYPECAISSELIB,
                              C.IDDEVISE,
                              MAX(TAU.TAUX)                     AS TAUX
                       FROM CAISSE C
                                LEFT JOIN MOUVEMENTCAISSEAVECHEURE MFF
                                          ON MFF.IDCAISSE = C.ID AND MFF.ETAT >= 11 AND MFF.IDREPORT IS NOT NULL-- and mff.DATY<=TO_DATE('27/07/2026','DD-MM-YYYY')
                                JOIN MAX_INVENTAIRE INV ON INV.IDCAISSE = C.ID
                                LEFT JOIN TAUXCHANGEMAX TAU ON TAU.TAUXIDDEVISE = C.IDDEVISE
                                LEFT JOIN POINT P ON P.ID = C.IDPOINT
                                LEFT JOIN TYPECAISSE TYP ON TYP.ID = C.IDTYPECAISSE
                       GROUP BY C.ID, C.IDPOINT, P.VAL, C.IDTYPECAISSE, TYP.VAL, C.VAL, C.IDDEVISE)
-- Selection finale
SELECT IDCAISSE,
       IDCAISSELIB || ' (' || NVL(IDDEVISE, 'AR') || ')'                             AS IDCAISSELIB,
       CAST(CREDIT AS NUMBER(30, 2))                                                 AS CREDIT,
       CAST(DEBIT AS NUMBER(30, 2))                                                  AS DEBIT,
       CAST(MONTANTDERNIERREPORT + CREDIT - DEBIT AS NUMBER(30, 2))                  AS RESTE,
       CAST(NVL(TAUX, 1) AS NUMBER(30, 2))                                           AS TAUX,
       CAST((MONTANTDERNIERREPORT + CREDIT - DEBIT) * NVL(TAUX, 1) AS NUMBER(30, 2)) AS RESTEAR,
       DATE '2025-01-01'                                                             AS DATY,
       IDCAISSE                                                                      AS ID,
       DATEDERNIERREPORT,
       CAST(MONTANTDERNIERREPORT AS NUMBER(30, 2))                                   AS MONTANTDERNIERREPORT,
       IDPOINT,
       IDPOINTLIB,
       IDTYPECAISSE,
       IDTYPECAISSELIB,
       (IDCAISSELIB || ' | ' || IDPOINTLIB || ' | ' || IDTYPECAISSELIB || ' | ' || DATEDERNIERREPORT) AS MOTSCLESSS
FROM SOMME_PRECALC;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_ETATCAISSE_CLOTURE" ("ID", "IDCAISSE", "IDCAISSELIB", "IDTYPECAISSE", "IDTYPECAISSELIB", "IDPOINT", "IDPOINTLIB", "DATEDERNIERREPORT", "MONTANTDERNIERREPORT", "DEBIT", "CREDIT", "RESTE", "DEVISE") AS
SELECT
    r.ID,
    r.IDCAISSE,
    c.val AS idcaisseLib,
    c.idtypecaisse,
    tc.desce AS idtypecaisselib,
    c.idpoint,
    p.desce AS idpointlib,
    r.DATY AS dateDernierReport,
    CAST(NVL(((r.MONTANT + NVL(mvtAv.CREDIT - mvtAv.DEBIT, 0)) * taux.taux), 0) AS NUMBER(30,2)) AS montantDernierReport,
    CAST(NVL(mvt.debit, 0) AS NUMBER(30,2)) AS debit,
    CAST(NVL(mvt.credit, 0) AS NUMBER(30,2)) AS credit,
    CAST((NVL(mvt.credit, 0) - NVL(mvt.debit, 0)) AS NUMBER(30,2)) AS reste,
    'AR' AS devise
FROM REPORTCAISSE_deVISE r,
     (
         SELECT  r.IDCAISSE,
                 MAX(r.DATY) AS maxDateReport
         FROM REPORTCAISSE_deVISE r
         WHERE r.ETAT = 11
           AND r.DATY <= TRUNC(SYSDATE)
         GROUP BY r.IDCAISSE
     ) rm,
     (
         SELECT  m.IDCAISSE,
                 SUM(NVL((m.DEBIT * t.taux),0)) AS DEBIT,
                 SUM(NVL((m.CREDIT * t.taux),0)) AS CREDIT
         FROM MOUVEMENTCAISSE_VISE m,
              (
                  SELECT  r.IDCAISSE,
                          MAX(r.DATY) AS maxDateReport
                  FROM REPORTCAISSE r
                  WHERE r.ETAT = 11
                    AND r.DATY <= TRUNC(SYSDATE)
                  GROUP BY r.IDCAISSE
              ) rm,
              (
                  SELECT ta.*
                  FROM TAUXDECHANGE ta,
                       (
                           SELECT MAX(daty) AS daty, iddevise
                           FROM TAUXDECHANGE t
                           WHERE daty <= TRUNC(SYSDATE)
                           GROUP BY iddevise
                       ) tmax
                  WHERE ta.daty = tmax.daty
                    AND ta.iddevise = tmax.iddevise
              ) t
         WHERE m.IDDEVISE = t.iddevise(+)
           AND m.IDCAISSE = rm.idcaisse(+)
           AND m.DATY >= TRUNC(SYSDATE)
           AND m.DATY <= TRUNC(SYSDATE)
         GROUP BY m.IDCAISSE
     ) mvt,
     (
         SELECT  m.IDCAISSE,
                 SUM(NVL((m.DEBIT * t.taux),0)) AS DEBIT,
                 SUM(NVL((m.CREDIT * t.taux),0)) AS CREDIT
         FROM MOUVEMENTCAISSE_VISE m,
              (
                  SELECT  r.IDCAISSE,
                          MAX(r.DATY) AS maxDateReport
                  FROM REPORTCAISSE r
                  WHERE r.ETAT = 11
                    AND r.DATY <= TRUNC(SYSDATE)
                  GROUP BY r.IDCAISSE
              ) rm,
              (
                  SELECT ta.*
                  FROM TAUXDECHANGE ta,
                       (
                           SELECT MAX(daty) AS daty, iddevise
                           FROM TAUXDECHANGE t
                           WHERE daty <=TRUNC(SYSDATE)
                           GROUP BY iddevise
                       ) tmax
                  WHERE ta.daty = tmax.daty
                    AND ta.iddevise = tmax.iddevise
              ) t
         WHERE m.IDDEVISE = t.iddevise(+)
           AND m.IDCAISSE = rm.idcaisse(+)
           AND m.DATY >= maxDateReport
           AND m.DATY < TRUNC(SYSDATE)
         GROUP BY m.IDCAISSE
     ) mvtAv,
     (
         SELECT ta.*
         FROM TAUXDECHANGE ta,
              (
                  SELECT MAX(daty) AS daty, iddevise
                  FROM TAUXDECHANGE t
                  WHERE daty <= TRUNC(SYSDATE)
                  GROUP BY iddevise
              ) tmax
         WHERE ta.daty = tmax.daty
           AND ta.iddevise = tmax.iddevise
     ) taux,
     CAISSE c,
     TYPECAISSE tc,
     POINT p
WHERE r.DATY = rm.maxDateReport
  AND r.IDDEVISE = taux.iddevise(+)
  AND r.ETAT = 11
  AND r.IDCAISSE = rm.IDCAISSE
  AND r.IDCAISSE = c.ID(+)
  AND r.IDCAISSE = mvt.idcaisse(+)
  AND r.IDCAISSE = mvtAv.idcaisse(+)
  AND c.IDTYPECAISSE = tc.ID(+)
  AND c.IDPOINT = p.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_ETATCAISSE_DEVISE_AR" ("IDCAISSE", "IDCAISSELIB", "CREDIT", "DEBIT", "RESTE", "TAUX", "RESTEAR", "DATY", "ID", "DATEDERNIERREPORT", "MONTANTDERNIERREPORT", "IDPOINT", "IDPOINTLIB", "IDTYPECAISSE", "IDTYPECAISSELIB") AS
select "IDCAISSE","IDCAISSELIB","CREDIT","DEBIT","RESTE","TAUX","RESTEAR","DATY","ID","DATEDERNIERREPORT","MONTANTDERNIERREPORT","IDPOINT","IDPOINTLIB","IDTYPECAISSE","IDTYPECAISSELIB" from v_Etatcaisse;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_ETATSTOCK" ("ID", "IDPRODUITLIB", "IDTYPEPRODUIT", "IDTYPEPRODUITLIB", "IDMAGASIN", "IDMAGASINLIB", "DATEDERNIERINVENTAIRE", "QUANTITE", "ENTREE", "SORTIE", "RESTE", "IDUNITE", "IDUNITELIB", "PUVENTE", "IDPOINT", "IDTYPEMAGASIN", "SEUILMIN", "SEUILMAX") AS
SELECT inv.IDPRODUIT AS                                               ID,
       p.desce       AS                                               idproduitLib,
       p.IDTYPEPRODUIT,
       tp.desce      AS                                               idtypeproduitlib,
       inv.idmagasin,
       mag.desce     AS                                               idmagasinlib,
       inv.DATY                                                       dateDernierinventaire,
       CAST(NVL(inv.QUANTITE, 0)  AS NUMBER(30, 2))                                          QUANTITE,
       NVL(mvt.ENTREE, 0)                                             ENTREE,
       NVL(mvt.SORTIE, 0)                                             SORTIE,
       NVL(mvt.ENTREE, 0) + NVL(inv.QUANTITE, 0) - NVL(mvt.SORTIE, 0) reste,
       p.IDUNITE,
       u.desce       AS                                               idunitelib,
       CAST(NVL(p.PUVENTE, 0) AS NUMBER(30, 2))                       PUVENTE,
       mag.IDPOINT,
       mag.IDTYPEMAGASIN,
       p.seuilmin,
       p.seuilmax
FROM INVENTAIRE_FILLE_CPL inv,
     (
         SELECT inv.IDPRODUIT,
                inv.IDMAGASIN,
                MAX(inv.DATY) maxDateInventaire
         FROM INVENTAIRE_FILLE_CPL inv
         WHERE inv.ETAT = 11
           AND inv.DATY <= SYSDATE --- dateMin
         GROUP BY inv.IDPRODUIT, inv.IDMAGASIN
     ) invm,
     (
         SELECT m.IDPRODUIT,
                dinv.IDMAGASIN,
                SUM(nvl(m.ENTREE, 0)) ENTREE,
                SUM(nvl(m.SORTIE, 0)) SORTIE
         FROM MVTSTOCKFILLELIB_VISE m,
              (
                  SELECT inv.IDPRODUIT,
                         inv.IDMAGASIN,
                         MAX(inv.DATY) maxDateInventaire
                  FROM INVENTAIRE_FILLE_CPL inv
                  WHERE inv.ETAT = 11
                    AND inv.DATY <= SYSDATE --- dateMin
                  GROUP BY inv.IDPRODUIT, inv.IDMAGASIN
              ) dinv
         WHERE m.IDPRODUIT = dinv.IDPRODUIT(+)
           AND m.IDMAGASIN = dinv.IDMAGASIN(+)
           AND m.DATY > dinv.maxDateInventaire
           AND m.DATY <= SYSDATE -- dateMax
         GROUP BY m.IDPRODUIT, dinv.IDMAGASIN
     ) mvt,
     produit p,
     type_produit tp,
     magasin mag,
     unite u
WHERE inv.DATY = invm.maxDateInventaire
  AND inv.IDMAGASIN = invm.IDMAGASIN
  AND inv.IDPRODUIT = invm.IDPRODUIT
  AND inv.IDPRODUIT = mvt.IDPRODUIT(+)
  AND inv.IDMAGASIN = mvt.IDMAGASIN(+)
  AND inv.IDPRODUIT = p.ID(+)
  AND p.IDTYPEPRODUIT = tp.ID
  AND inv.idmagasin = mag.ID
  AND p.IDUNITE = u.ID(+)
  AND ( mvt.SORTIE > 0 OR mvt.ENTREE > 0 )
  AND inv.ETAT >= 11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_ETATSTOCK_ENTREE" ("ID", "IDPRODUIT", "IDPRODUITLIB", "CATEGORIEINGREDIENT", "IDTYPEPRODUITLIB", "IDMAGASIN", "IDMAGASINLIB", "QUANTITE", "ENTREE", "SORTIE", "RESTE", "UNITE", "IDUNITELIB", "PU", "DATY", "IDFOURNISSEUR", "IDFOURNISSEURLIB", "DATEACHAT", "PUVENTE", "IDPOINT", "IDTYPEMAGASIN", "SEUILMIN", "SEUILMAX", "MONTANTENTREE", "MONTANTSORTIE", "MONTANTRESTE", "MOTSCLESSS") AS
SELECT SQ.ID,SQ.IDPRODUIT,SQ.IDPRODUITLIB,SQ.CATEGORIEINGREDIENT,SQ.IDTYPEPRODUITLIB,SQ.IDMAGASIN,SQ.IDMAGASINLIB,CAST(COALESCE(SQ.QUANTITE,0) AS NUMBER(30,5)) AS quantite,cast(COALESCE(SQ.ENTREE,0) as number(30,5)) as entree,cast(COALESCE(SQ.SORTIE,0) as number(30,5)) as sortie,CAST(COALESCE(SQ.RESTE,0) AS NUMBER(30,5)) AS reste,SQ.UNITE,SQ.IDUNITELIB,SQ.PU,SQ.DATY,SQ.IDFOURNISSEUR,SQ.IDFOURNISSEURLIB,SQ.DATEACHAT,CAST(COALESCE(SQ.PUVENTE,0) AS NUMBER(30,5)) AS PUVENTE,SQ.IDPOINT,SQ.IDTYPEMAGASIN,CAST(COALESCE(SQ.SEUILMIN,0) AS NUMBER(30,5)) AS SEUILMIN,CAST(COALESCE(SQ.SEUILMAX,0) AS NUMBER(30,5)) AS SEUILMAX ,CAST(COALESCE(SQ.MONTANTENTREE,0) AS NUMBER(30,5)) AS MONTANTENTREE,CAST(COALESCE(SQ.MONTANTSORTIE,0) AS NUMBER(30,5)) AS MONTANTSORTIE ,CAST(COALESCE(SQ.MONTANTRESTE,0) AS NUMBER(30,5)) AS MONTANTRESTE,
       (NVL(TO_CHAR(ID),'') || ' | ' || NVL(TO_CHAR(IDPRODUIT),'') || ' | ' || NVL(TO_CHAR(IDPRODUITLIB),'') || ' | ' || NVL(TO_CHAR(CATEGORIEINGREDIENT),'') || ' | ' || NVL(TO_CHAR(IDTYPEPRODUITLIB),'') || ' | ' || NVL(TO_CHAR(IDMAGASIN),'') || ' | ' || NVL(TO_CHAR(IDMAGASINLIB),'') || ' | ' || NVL(TO_CHAR(QUANTITE),'') || ' | ' || NVL(TO_CHAR(ENTREE),'') || ' | ' || NVL(TO_CHAR(SORTIE),'') || ' | ' || NVL(TO_CHAR(RESTE),'') || ' | ' || NVL(TO_CHAR(UNITE),'') || ' | ' || NVL(TO_CHAR(IDUNITELIB),'') || ' | ' || NVL(TO_CHAR(PU),'') || ' | ' || NVL(TO_CHAR(DATY,'YYYY-MM-DD HH24:MI:SS'),'') || ' | ' || NVL(TO_CHAR(IDFOURNISSEUR),'') || ' | ' || NVL(TO_CHAR(IDFOURNISSEURLIB),'') || ' | ' || NVL(TO_CHAR(DATEACHAT,'YYYY-MM-DD HH24:MI:SS'),'') || ' | ' || NVL(TO_CHAR(PUVENTE),'') || ' | ' || NVL(TO_CHAR(IDPOINT),'') || ' | ' || NVL(TO_CHAR(IDTYPEMAGASIN),'') || ' | ' || NVL(TO_CHAR(SEUILMIN),'') || ' | ' || NVL(TO_CHAR(SEUILMAX),'') || ' | ' || NVL(TO_CHAR(MONTANTENTREE),'') || ' | ' || NVL(TO_CHAR(MONTANTSORTIE),'') || ' | ' || NVL(TO_CHAR(MONTANTRESTE),'')) AS MOTSCLESSS
FROM (
         SELECT DISTINCT
             ve.id,
             ai.id AS idproduit,
             ai.libelle AS idproduitlib,
             ai.categorieingredient,
             c.val AS idtypeproduitlib,
             ve.idmagasin,
             m.val AS idmagasinlib,
             CAST(ve.quantite AS NUMBER(30,5)) AS quantite,
             CAST(ve.entree AS NUMBER(30,5)) AS entree,
             CAST(ve.sortie AS NUMBER(30,5)) AS sortie,
             CAST(ve.reste AS NUMBER(30,5)) AS reste,
             ai.unite,
             u.val AS idunitelib,
             ve.pu,
             ve.daty,
             ve.idfournisseur,
             f.NOM AS idfournisseurlib,
             ve.dateAchat,
             CAST(NVL(ai.PV, 0) AS NUMBER(30, 5)) AS PUVENTE,
             m.IDPOINT,
             m.IDTYPEMAGASIN,
             ai.SEUILMIN,
             ai.SEUILMAX,
             MONTANTENTREE,
             MONTANTSORTIE,
             MONTANTRESTE
         FROM (
                  SELECT
                      x.*,
                      COALESCE(b.idfournisseur, invf.idfournisseur, bb.IDFOURNISSEUR,trs.idfournisseur) AS idfournisseur,
                      f.DATY as dateAchat

                  FROM (
                           SELECT
                               ID,
                               IDMVTSTOCK,
                               IDPRODUIT,
                               ENTREE,
                               SORTIE,
                               IDVENTEDETAIL,
                               IDTRANSFERTDETAIL,
                               PU,
                               MVTSRC,
                               DATY,
                               RESTE,
                               QUANTITE,
                               IDMAGASIN,
                               IDINVENTAIREFILLE,
                               MONTANTENTREE,
                               MONTANTSORTIE,
                               MONTANTRESTE
                           FROM (
                                    SELECT
                                        mf.ID,
                                        mf.IDMVTSTOCK,
                                        mf.IDPRODUIT,
                                        nvl(mf.ENTREE,0)+nvl(s.ENTREE,0) as entree,
                                        s.SORTIE,
                                        mf.IDVENTEDETAIL,
                                        mf.IDTRANSFERTDETAIL,
                                        mf.PU,
                                        mf.MVTSRC,
                                        ms.DATY,
                                        NVL(mf.ENTREE, 0) - NVL(s.SORTIE, 0)  + NVL(s.ENTREE, 0) AS RESTE,
                                        NVL(mf.ENTREE, 0) - NVL(s.SORTIE, 0) +  NVL(s.ENTREE, 0) AS QUANTITE,
                                        ms.IDMAGASIN,
                                        mf.idinventairefille,
                                        cast((mf.PU*mf.ENTREE) as number(30,5)) AS MONTANTENTREE,
                                        cast((mf.PU*s.SORTIE) as number(30,5)) AS MONTANTSORTIE,
                                        CAST(NVL(mf.ENTREE, 0) - NVL(s.SORTIE, 0)  + NVL(s.ENTREE, 0) AS NUMBER(30,5)) * mf.PU AS MONTANTRESTE

                                    FROM MVTSTOCKFILLE mf
                                             LEFT JOIN MVTSTOCK ms ON ms.id = mf.IDMVTSTOCK
                                             LEFT JOIN (
                                        SELECT mf2.MVTSRC, SUM(mf2.SORTIE) AS SORTIE,SUM(mf2.ENTREE) AS ENTREE
                                        FROM MVTSTOCKFILLE mf2
                                                 LEFT JOIN MVTSTOCK ms2 ON ms2.id = mf2.IDMVTSTOCK
                                        WHERE ms2.ETAT >= 11
                                          AND mf2.MVTSRC IS NOT NULL
                                        GROUP BY mf2.MVTSRC
                                    ) s ON s.MVTSRC = mf.id
                                    WHERE mf.ENTREE > 0 and (mf.MVTSRC is null or mf.MVTSRC=mf.id)
                                      AND (ms.IDCATEGORIESTOCK IS NULL
                                        OR ms.IDCATEGORIESTOCK <> 'CTGST000003')
                                      AND ms.ETAT >= 11
                                )
                       ) x
                           LEFT JOIN MVTSTOCK ms  ON ms.id = x.IDMVTSTOCK
                           LEFT JOIN AS_BONDELIVRAISON b ON b.ID = ms.IDOBJET
                           LEFT JOIN AS_BONDELIVRAISON bb ON b.ID = ms.IDTRANSFERT
                           LEFT JOIN FACTUREFOURNISSEUR f on f.id=b.IDFACTUREFOURNISSEUR
                           LEFT JOIN INVENTAIREFILLE invf ON invf.id = x.IDINVENTAIREFILLE
                           LEFT JOIN TRANSFERTSTOCKDETAILS trs ON trs.id = x.IDTRANSFERTDETAIL
                  WHERE b.IDFOURNISSEUR IS NOT NULL OR invf.IDFOURNISSEUR IS NOT NULL or bb.IDFOURNISSEUR IS NOT NULL OR trs.idfournisseur is not null

              ) ve

                  LEFT JOIN AS_INGREDIENTS ai ON ai.id = ve.IDPRODUIT
                  LEFT JOIN CATEGORIEINGREDIENT c ON ai.CATEGORIEINGREDIENT = c.id
                  LEFT JOIN MAGASINPOINT m ON ve.IDMAGASIN = m.id
                  LEFT JOIN AS_UNITE u ON ai.UNITE = u.id

                  LEFT JOIN FOURNISSEUR f ON f.ID = ve.idfournisseur

         WHERE ve.PU > 0 AND CAST(ve.reste AS NUMBER(30,5)) != 0
     ) SQ;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_ETATSTOCK_ENTREE_DMDACHAT" ("ID", "IDPRODUIT", "IDPRODUITLIB", "CATEGORIEINGREDIENT", "IDTYPEPRODUITLIB", "IDMAGASIN", "IDMAGASINLIB", "QUANTITE", "ENTREE", "SORTIE", "RESTE", "UNITE", "IDUNITELIB", "PU", "DATY") AS
SELECT
    ai.id AS ID,
    ai.id AS IDPRODUIT,
    ai.LIBELLE AS IDPRODUITLIB,
    ai.CATEGORIEINGREDIENT,
    c.VAL AS IDTYPEPRODUITLIB,
    ve.IDMAGASIN,
    ai.IDMAGASINLIB,
    CAST(SUM(nvl(ve.QUANTITE, 0)) AS NUMBER(30,5)) AS QUANTITE,
    CAST(SUM(nvl(ve.ENTREE, 0))AS NUMBER(30,5)) AS ENTREE,
    CAST(SUM(nvl(ve.SORTIE, 0))AS NUMBER(30,5)) AS SORTIE,
    CAST(SUM(nvl(ve.RESTE, 0))AS NUMBER(30,5)) AS RESTE,
    ai.UNITE,
    u.VAL AS IDUNITELIB,
    CAST(MIN(nvl(ve.PU, 0))AS NUMBER(30,5)) AS PU,  -- On prend le PU minimal si plusieurs
    MIN(ve.DATY) AS DATY  -- Date representative
FROM
    as_ingredientxmagasin2 ai
    left join MVTSTOCKENTREEAVECRESTE ve on ai.id = ve.IDPRODUIT
    LEFT JOIN CATEGORIEINGREDIENT c ON ai.CATEGORIEINGREDIENT = c.id
    LEFT JOIN UNITE u ON ai.UNITE = u.id
--WHERE ve.RESTE > 0 AND ve.PU > 0
GROUP BY
    ai.id,
    ai.LIBELLE,
    ai.CATEGORIEINGREDIENT,
    c.VAL,
    ve.IDMAGASIN,
    ai.UNITE,
    u.VAL, ai.IDMAGASINLIB;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_ETATSTOCK_ENTREE_STANDARD" ("ID", "DATY", "INVQUANTITE", "ENTREE", "SORTIE", "RESTE", "QUANTITE", "MONTANTRESTE", "IDPRODUITLIB", "CATEGORIEINGREDIENT", "UNITE", "TYPESTOCK", "IDUNITELIB", "IDTYPEPRODUITLIB", "PU", "IDFOURNISSEUR", "IDFOURNISSEURLIB", "IDPRODUIT", "IDMAGASIN", "IDMAGASINLIB", "INVDATY") AS
WITH max_inventaire AS (
    -- ?    tape 1 : On extrait la date maximale valide par produit une fois pour toutes
    SELECT
        invff.MVTSRC,
        MAX(imeref.DATY) AS max_daty
    FROM INVENTAIREFILLE invff
             LEFT JOIN inventaireDateHeure imeref ON imeref.ID = invff.IDINVENTAIRE
    WHERE imeref.ETAT >= 11
    GROUP BY invff.MVTSRC
),
     inv_final_precalc AS (
         -- ?   tape 2 : On r??cup??re les quantit??s associ??es ?  cette date maximale
         SELECT
             invfff.MVTSRC,
             invfff.QUANTITE,
             imm.DATY AS invdaty
         FROM INVENTAIREFILLE invfff
                  LEFT JOIN inventaireDateHeure imm ON imm.ID = invfff.IDINVENTAIRE
                  INNER JOIN max_inventaire mi ON mi.MVTSRC = invfff.MVTSRC AND imm.DATY = mi.max_daty
         WHERE imm.ETAT >= 11
     ),
     somme_precalc AS (
         -- ?   tape 3 : Calcul des sommes globales (sorties/entr??es) sans sous-requ??te corr??l??e cass??e
         SELECT
             mff.MVTSRC,
             NVL(SUM(mff.ENTREE), 0) AS entree,
             NVL(SUM(mff.SORTIE), 0) AS sortie
         FROM MVTSTOCKFILLE mff
                  LEFT JOIN mvtStockDateHeure meref ON meref.ID = mff.IDMVTSTOCK
                  LEFT JOIN inv_final_precalc inv ON inv.MVTSRC = mff.MVTSRC
         WHERE meref.DATY > nvl(inv.invdaty,to_date('01/01/2025','DD-MM-YYYY')) and meref.ETAT>=11
           AND meref.IDTYPEMVSTOCK != 'TPMVST000023'
         GROUP BY mff.MVTSRC
     ),
     main_data AS (
         -- ?   tape 4 : Requ??te principale avec application exacte des r??gles de calcul d'origine
         SELECT
             mf.ID,
             mere.DATY,
             CAST(NVL(invfinal.QUANTITE, 0) AS NUMBER(30,3)) AS invquantite,

             CASE WHEN mere.DATY > NVL(invfinal.invdaty, TO_DATE('01/01/2025','DD-MM-YYYY'))
                      THEN CAST(NVL(mf.ENTREE, 0) AS NUMBER(30,3))
                  ELSE 0
                 END AS ENTREE,

             CAST(NVL(somme.SORTIE, 0) AS NUMBER(30,3)) AS sortie,

             CASE WHEN mere.DATY <= NVL(invfinal.invdaty, TO_DATE('01/01/2025','DD-MM-YYYY'))
                      THEN CAST((NVL(invfinal.QUANTITE, 0) - NVL(somme.SORTIE, 0)) AS NUMBER(30,3))
                  ELSE CAST((NVL(invfinal.QUANTITE, 0) + mf.ENTREE - NVL(somme.SORTIE, 0)) AS NUMBER(30,3))
                 END AS reste,

             ai.LIBELLE AS idproduitlib,
             ai.CATEGORIEINGREDIENT,
             ai.UNITE,
             ai.TYPESTOCK,
             u.VAL AS idunitelib,
             c.VAL AS idtypeproduitlib,
             mf.PU,
             b.IDFOURNISSEUR,
             b.IDFOURNISSEURLIB,
             mf.IDPRODUIT,
             mere.IDMAGASIN,
             m.VAL AS idmagasinlib,
             invfinal.invdaty AS invdaty
         FROM MVTSTOCKFILLE mf
                  LEFT JOIN mvtStockDateHeure mere ON mere.id = mf.IDMVTSTOCK
                  LEFT JOIN somme_precalc somme ON somme.MVTSRC = mf.id
                  LEFT JOIN inv_final_precalc invfinal ON invfinal.MVTSRC = mf.ID
                  LEFT JOIN AS_INGREDIENTS ai ON ai.id = mf.IDPRODUIT
                  LEFT JOIN CATEGORIEINGREDIENT c ON ai.CATEGORIEINGREDIENT = c.id
                  LEFT JOIN MAGASINPOINT m ON mere.IDMAGASIN = m.id
                  LEFT JOIN AS_UNITE u ON ai.UNITE = u.id
                  LEFT JOIN AS_BONDELIVRAISON_LIB b ON b.ID = mere.IDOBJET
         WHERE mf.ENTREE > 0
            AND mere.IDTYPEMVSTOCK != 'TPMVST000023'
            AND mere.ETAT >= 11
            AND ai.TYPESTOCK != 'CUMP'
     )
SELECT
    ID, DATY, CAST(invquantite AS NUMBER(30,3)) AS invquantite, CAST(entree AS NUMBER(30,3)) AS entree, CAST(sortie AS NUMBER(30,3)) AS sortie, CAST(reste AS NUMBER(30,3)) AS reste,
    CAST(reste AS NUMBER(30,3)) AS quantite,
    CAST(reste * PU AS NUMBER(30,2)) AS montantreste,
    idproduitlib, CATEGORIEINGREDIENT, UNITE, TYPESTOCK, idunitelib, idtypeproduitlib,
    PU, IDFOURNISSEUR, IDFOURNISSEURLIB, IDPRODUIT, IDMAGASIN, idmagasinlib, invdaty
FROM main_data
WHERE reste != 0;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_ETATSTOCK_ING" ("ID", "DATY", "INVQUANTITE", "ENTREE", "SORTIE", "RESTE", "QUANTITE", "MONTANTRESTE", "IDPRODUITLIB", "CATEGORIEINGREDIENT", "UNITE", "TYPESTOCK", "IDUNITELIB", "IDTYPEPRODUITLIB", "PU", "IDFOURNISSEUR", "IDFOURNISSEURLIB", "IDPRODUIT", "IDMAGASIN", "IDMAGASINLIB", "INVDATY") AS
SELECT
    '' as id,
    '' as DATY,
    cast(sum(invquantite) as number(30,3)) as invquantite,
    cast(sum(entree) as number(30,3)) as entree,
    cast(sum(sortie) as number(30,3)) as sortie,
    cast(sum(reste) as number(30,3)) as reste,
    cast(sum(quantite) as number(30,3)) as quantite,
    cast(sum(reste)* avg(pu) as number(30,2)) as montantReste,
    idproduitlib,
    CATEGORIEINGREDIENT,
    UNITE,
    TYPESTOCK,
    idunitelib,
    idtypeproduitlib,
    avg(PU) AS PU,
    '' as IDFOURNISSEUR,
    '' as IDFOURNISSEURLIB,
    IDPRODUIT,
    IDMAGASIN,
    idmagasinlib,
    min(invdaty) as invdaty
FROM (
    SELECT * FROM V_ETATSTOCK_ENTREE_STANDARD
    union all select * from (
    WITH max_inventaire AS (
        SELECT
            invff.IDPRODUIT,imeref.IDMAGASIN,
            MAX(imeref.DATY) AS max_daty
            ,MAX(invff.QUANTITE) KEEP (DENSE_RANK LAST ORDER BY imeref.DATY) AS qte_max_daty,
            MAX(invff.pu) KEEP (DENSE_RANK LAST ORDER BY imeref.DATY) AS pu_max_daty
        FROM INVENTAIREFILLE invff
        LEFT JOIN inventaireDateHeure imeref ON imeref.ID = invff.IDINVENTAIRE
        WHERE imeref.ETAT >= 11 and invff.MVTSRC is null
        GROUP BY invff.IDPRODUIT, imeref.IDMAGASIN
    ),
         somme_precalc AS (
             -- Etape 3 : Calcul des sommes globales agregees par COUPLE produit/magasin
             SELECT
                 mff.idproduit as idproduit,
                 meref.idmagasin as idmagasin,
                 NVL(SUM(CASE WHEN meref.DATY >NVL(inv.max_daty, TO_DATE('01/01/2025','DD-MM-YYYY')) THEN mff.ENTREE ELSE 0 END), 0) AS entree,

                 NVL(SUM(CASE WHEN meref.DATY > NVL(inv.max_daty, TO_DATE('01/01/2025','DD-MM-YYYY')) THEN mff.SORTIE ELSE 0 END), 0) AS sortie,
                 ai.LIBELLE AS idproduitlib,
            ai.CATEGORIEINGREDIENT as CATEGORIEINGREDIENT,
            ai.UNITE as unite,
            ai.TYPESTOCK as typestock,
            u.VAL AS idunitelib,
            c.VAL AS idtypeproduitlib,
                 avg(mff.PU) as pu,
                 null as IDFOURNISSEUR,
                 null as IDFOURNISSEURLIB,
                 m.VAL AS idmagasinlib,
                 max(inv.max_daty) AS invdaty,
                 nvl(max(inv.qte_max_daty),0)as invquantite,
                 NVL(SUM(CASE WHEN meref.DATY >NVL(inv.max_daty, TO_DATE('01/01/2025','DD-MM-YYYY')) THEN mff.ENTREE*mff.pu ELSE 0 END), 0) AS montantEntree,
                 NVL(SUM(CASE WHEN meref.DATY > NVL(inv.max_daty, TO_DATE('01/01/2025','DD-MM-YYYY')) THEN mff.SORTIE*mff.pu ELSE 0 END), 0) AS montantSortie,
                 nvl(avg(inv.pu_max_daty*inv.qte_max_daty),0) as montantInv, nvl(max(ai.SEUIL),0) as seuil,nvl(max(ai.SEUILMAX),nvl(max(ai.SEUILMIN),0)+1000) as seuilmax,nvl(max(ai.SEUILMIN),0) as seuilMin
             FROM MVTSTOCKFILLE mff
                      LEFT JOIN mvtStockDateHeure meref ON meref.ID = mff.IDMVTSTOCK
        LEFT JOIN max_inventaire inv ON inv.idproduit = mff.idproduit AND inv.idmagasin = meref.idmagasin
        LEFT JOIN AS_INGREDIENTS ai ON ai.id = mff.IDPRODUIT
        LEFT JOIN CATEGORIEINGREDIENT c ON ai.CATEGORIEINGREDIENT = c.id
        LEFT JOIN MAGASINPOINT m ON meref.IDMAGASIN = m.id
        LEFT JOIN AS_UNITE u ON ai.UNITE = u.id
        WHERE --meref.DATY > NVL(inv.max_daty, TO_DATE('01/01/2025','DD-MM-YYYY')) and
          meref.ETAT >= 11
          AND meref.IDTYPEMVSTOCK != 'TPMVST000023' and mff.MVTSRC is null
          and not exists(select 1 from V_ETATSTOCK_ENTREE_STANDARD  ve where ve.id = mff.id)
        GROUP BY mff.idproduit, meref.idmagasin,ai.LIBELLE,ai.CATEGORIEINGREDIENT,ai.UNITE,ai.TYPESTOCK,u.VAL,c.VAL,m.VAL
         )
    SELECT
        null as ID, null as DATY,  cast(invquantite as number(30,3)) as invquantite,cast(entree as number(30,3)) as entree, cast(sortie as number(30,3)) as sortie,CAST((invquantite)+(ENTREE)-(sortie) AS NUMBER(30,3)) as reste,
        CAST(invquantite+ENTREE-sortie AS NUMBER(30,3)) AS quantite,
        CAST((montantInv+montantEntree-montantSortie)AS NUMBER(30,2))AS montantreste,
        idproduitlib, CATEGORIEINGREDIENT, UNITE, TYPESTOCK, idunitelib, idtypeproduitlib,
        cast((montantInv+montantEntree-montantSortie)/(invquantite+ENTREE-sortie)  as number(30,2)) as pu,
        IDFOURNISSEUR, IDFOURNISSEURLIB, IDPRODUIT, IDMAGASIN, idmagasinlib,invdaty
    FROM somme_precalc
    WHERE (invquantite+ENTREE-sortie) != 0)
) GROUP BY
idproduitlib, CATEGORIEINGREDIENT, UNITE, TYPESTOCK,
idunitelib, idtypeproduitlib, IDPRODUIT,
IDMAGASIN, idmagasinlib;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_ETATSTOCK_INGINFSEUIL" ("ID", "DATY", "INVQUANTITE", "ENTREE", "SORTIE", "RESTE", "QUANTITE", "MONTANTRESTE", "PU", "IDPRODUITLIB", "CATEGORIEINGREDIENT", "UNITE", "TYPESTOCK", "IDUNITELIB", "IDTYPEPRODUITLIB", "IDFOURNISSEUR", "IDFOURNISSEURLIB", "IDPRODUIT", "IDMAGASIN", "IDMAGASINLIB", "INVDATY", "SEUIL", "SEUILMIN", "SEUILMAX", "QTEDEMANDE") AS
select eta."ID",eta."DATY",eta."INVQUANTITE",eta."ENTREE",eta."SORTIE",eta."RESTE",eta."QUANTITE",eta."MONTANTRESTE",eta."PU",eta."IDPRODUITLIB",eta."CATEGORIEINGREDIENT",eta."UNITE",eta."TYPESTOCK",eta."IDUNITELIB",eta."IDTYPEPRODUITLIB",eta."IDFOURNISSEUR",eta."IDFOURNISSEURLIB",eta."IDPRODUIT",eta."IDMAGASIN",eta."IDMAGASINLIB",eta."INVDATY",eta."SEUIL",eta."SEUILMIN",eta."SEUILMAX", cast(seuilMax-reste as number(30,2)) as qteDemande from V_ETATSTOCK_ING_TOUS eta where reste<seuilMin and seuilMin>0;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_ETATSTOCK_ING_ALL" ("ID", "IDPRODUITLIB", "CATEGORIEINGREDIENT", "IDTYPEPRODUITLIB", "IDMAGASIN", "IDMAGASINLIB", "DATEDERNIERMOUVEMENT", "QUANTITE", "ENTREE", "SORTIE", "RESTE", "UNITE", "IDUNITELIB", "PUVENTE", "IDPOINT", "IDTYPEMAGASIN", "SEUILMIN", "SEUILMAX", "MONTANTENTREE", "MONTANTSORTIE", "PU", "MONTANTRESTE") AS
SELECT
 p.ID AS ID,
 p.LIBELLE AS idproduitLib,
 p.CATEGORIEINGREDIENT,
 tp.DESCE AS idtypeproduitlib,
 ms.IDMAGASIN,
 mag.VAL AS idmagasinlib,
 TO_DATE('01-01-2001', 'DD-MM-YYYY') AS dateDernierMouvement,
 ms.quantite AS QUANTITE,
 CAST(NVL( ms.entree, 0) AS NUMBER(30, 2))  AS ENTREE,
 CAST(NVL( ms.sortie, 0) AS NUMBER(30, 2))  AS SORTIE,
 CAST(NVL( ms.quantite, 0) AS NUMBER(30, 2))  AS reste,
 p.UNITE,
 u.DESCE AS idunitelib,
 CAST(NVL(p.PV, 0) AS NUMBER(30, 2)) AS PUVENTE,
 mag.IDPOINT,
 mag.IDTYPEMAGASIN,
 p.SEUILMIN,
 p.SEUILMAX,
 ms.montantEntree,
 ms.montantSortie,
 p.pu,
 ms.montant as montantReste
FROM AS_INGREDIENTS p
LEFT JOIN MONTANT_STOCK ms ON ms.IDPRODUIT = p.ID
LEFT JOIN CATEGORIEINGREDIENT tp ON p.CATEGORIEINGREDIENT = tp.ID
LEFT JOIN MAGASINPOINT mag ON ms.IDMAGASIN = mag.ID
LEFT JOIN AS_UNITE u ON p.UNITE = u.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_ETATSTOCK_ING_ENG" ("ID", "DATY", "INVQUANTITE", "ENTREE", "SORTIE", "RESTE", "QUANTITE", "MONTANTRESTE", "IDPRODUITLIB", "CATEGORIEINGREDIENT", "UNITE", "TYPESTOCK", "IDUNITELIB", "IDTYPEPRODUITLIB", "PU", "IDFOURNISSEUR", "IDFOURNISSEURLIB", "IDPRODUIT", "IDMAGASIN", "IDMAGASINLIB", "INVDATY") AS
SELECT
    '' as id,
    '' as DATY,
    cast(sum(invquantite) as number(30,3)) as invquantite,
    cast(sum(entree) as number(30,3)) as entree,
    cast(sum(sortie) as number(30,3)) as sortie,
    cast(sum(reste) as number(30,3)) as reste,
    cast(sum(quantite) as number(30,3)) as quantite,
    cast(sum(reste)* avg(pu) as number(30,2)) as montantReste,
    idproduitlib,
    CATEGORIEINGREDIENT,
    UNITE,
    TYPESTOCK,
    idunitelib,
    idtypeproduitlib,
    avg(PU) AS PU,
    '' as IDFOURNISSEUR,
    '' as IDFOURNISSEURLIB,
    IDPRODUIT,
    IDMAGASIN,
    idmagasinlib,
    min(invdaty) as invdaty
FROM (
    SELECT * FROM V_ETATSTOCK_ING
    UNION ALL
    SELECT
        TO_CHAR(mf.ID)                    AS id,
        TO_CHAR(mere.DATY, 'DD/MM/YYYY')  AS DATY,
        0 AS invquantite,
        mf.entree,
        mf.sortie AS sortie,
        mf.entree - mf.SORTIE AS reste,
        mf.entree - mf.SORTIE AS quantite,
        (mf.entree - mf.SORTIE) * mf.pu AS montantReste,
        ai.LIBELLE AS idproduitlib,
        ai.CATEGORIEINGREDIENT AS CATEGORIEINGREDIENT,
        ai.UNITE,
        ai.TYPESTOCK,
        u.val AS idunitelib,
        c.val AS idtypeproduitlib,
        mf.pu AS PU,
        '' AS IDFOURNISSEUR,
        '' AS IDFOURNISSEURLIB,
        mf.IDPRODUIT,
        mere.IDMAGASIN,
        m.val AS idmagasinlib,
        NULL AS invdaty
    FROM stock_engage_FILLE mf
        LEFT JOIN stock_engage mere ON mere.id = mf.IDMVTSTOCK
        LEFT JOIN AS_INGREDIENTS ai ON ai.id = mf.IDPRODUIT
        LEFT JOIN CATEGORIEINGREDIENT c ON ai.CATEGORIEINGREDIENT = c.id
        LEFT JOIN MAGASINPOINT m ON mere.IDMAGASIN = m.id
        LEFT JOIN AS_UNITE u ON ai.UNITE = u.id
) GROUP BY
    idproduitlib, CATEGORIEINGREDIENT, UNITE, TYPESTOCK,
    idunitelib, idtypeproduitlib, IDPRODUIT,
    IDMAGASIN, idmagasinlib;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_ETATSTOCK_ING_ENG_PDF" ("ID", "IDPRODUITLIB", "RESTE", "SORTIE", "ENTREE", "IDTYPEPRODUITLIB", "PU", "MONTANTRESTE") AS
select
    v.id,
    v.idProduitLib,
    v.reste,
    NVL(s.SORTIE, 0) as SORTIE,
    v.RESTE - NVL(s.SORTIE, 0) as entree,
    v.IDTYPEPRODUITLIB,
    v.pu,
    v.montantreste
from V_ETATSTOCK_ING_GP_PDF v
         left join STOCK_ENGAGE_FILLE_GP s
                   on v.id = s.IDPRODUIT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_ETATSTOCK_ING_ENG_SOMME" ("ID", "IDPRODUITLIB", "CATEGORIEINGREDIENT", "IDTYPEPRODUITLIB", "IDMAGASIN", "IDMAGASINLIB", "QUANTITE", "ENTREE", "SORTIE", "RESTE", "UNITE", "IDUNITELIB", "IDPOINT", "IDTYPEMAGASIN", "SEUILMIN", "SEUILMAX", "PU", "LIBELLEVENTE") AS
SELECT
    p.ID,
    p.LIBELLE AS idproduitLib,
    p.CATEGORIEINGREDIENT,
    tp.DESCE AS idtypeproduitlib,
    ms.IDMAGASIN,
    mag.VAL AS idmagasinlib,
    sum(CAST(ms.quantite AS NUMBER(30,5) )) AS QUANTITE,
    sum(CAST(NVL( ms.entree, 0) AS NUMBER(30, 5)))  AS ENTREE,
    sum(CAST(NVL( ms.sortie, 0) AS NUMBER(30, 5)) ) AS SORTIE,
    sum(CAST(NVL( ms.quantite, 0) AS NUMBER(30, 5)))  AS reste,
    p.UNITE,
    u.DESCE AS idunitelib,
    mag.IDPOINT,
    mag.IDTYPEMAGASIN,
    p.SEUILMIN,
    p.SEUILMAX,
    CAST(p.pu AS NUMBER(30,5)) AS pu,
    p.LIBELLEVENTE
FROM AS_INGREDIENTS p
         LEFT JOIN MONTANT_STOCK_eng ms ON ms.IDPRODUIT = p.ID
         LEFT JOIN CATEGORIEINGREDIENT tp ON p.CATEGORIEINGREDIENT = tp.ID
         LEFT JOIN MAGASINPOINT mag ON ms.IDMAGASIN = mag.ID
         LEFT JOIN AS_UNITE u ON p.UNITE = u.ID
WHERE NVL(ms.ENTREE, 0) > 0 OR NVL(ms.SORTIE, 0) > 0
group by p.ID, p.LIBELLE, p.CATEGORIEINGREDIENT, tp.DESCE, ms.IDMAGASIN, mag.VAL, p.UNITE, u.DESCE, mag.IDPOINT, mag.IDTYPEMAGASIN, p.SEUILMIN, p.SEUILMAX, p.pu, p.LIBELLEVENTE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_ETATSTOCK_ING_GP" ("ID", "IDPRODUITLIB", "RESTE") AS
select id,idProduitLib,sum(reste) as reste
from V_ETATSTOCK_ING where CATEGORIEINGREDIENT = 'CAT008'
group by idProduitLib, id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_ETATSTOCK_ING_GP_PDF" ("ID", "IDPRODUITLIB", "RESTE", "IDTYPEPRODUITLIB", "PU", "MONTANTRESTE") AS
select ving.id,ving.idProduitLib,sum(ving.reste) as reste,tp.val as IDTYPEPRODUITLIB ,sum(ving.pu),sum(ving.montantreste)
from V_ETATSTOCK_ING ving
LEFT JOIN as_ingredients aig ON aig.id=ving.id
LEFT JOIN type_produit tp ON aig.typeproduit=tp.id
where ving.CATEGORIEINGREDIENT = 'CAT008'
group by ving.idProduitLib, ving.id,tp.val;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_ETATSTOCK_ING_MAGASIN" ("ID", "IDPRODUITLIB", "CATEGORIEINGREDIENT", "IDTYPEPRODUITLIB", "IDMAGASIN", "IDMAGASINLIB", "DATEDERNIERMOUVEMENT", "QUANTITE", "ENTREE", "SORTIE", "RESTE", "UNITE", "IDUNITELIB", "PUVENTE", "IDPOINT", "IDTYPEMAGASIN", "SEUILMIN", "SEUILMAX", "IDPOINTLIB") AS
SELECT
    aim.ID AS ID,
    p.LIBELLE AS idproduitLib,
    p.CATEGORIEINGREDIENT,
    tp.DESCE AS idtypeproduitlib,
    aim.IDMAGASIN,
    mag.DESCE AS idmagasinlib,
    NVL(MAX(m.DATY),TO_DATE('01-01-2001', 'DD-MM-YYYY')) AS dateDernierMouvement,
    CAST(SUM(NVL(f.ENTREE, 0)) - SUM(NVL(f.SORTIE, 0)) AS NUMBER(30,2)) AS QUANTITE,
    CAST(SUM(NVL(f.ENTREE, 0)) AS NUMBER(30,2)) AS ENTREE,
    CAST(SUM(NVL(f.SORTIE, 0)) AS NUMBER(30,2)) AS SORTIE,
    CAST(SUM(NVL(f.ENTREE, 0)) - SUM(NVL(f.SORTIE, 0)) AS NUMBER(30,2)) AS reste,
    p.UNITE,
    u.DESCE AS idunitelib,
    CAST(NVL(p.PV, 0) AS NUMBER(30, 2)) AS PUVENTE,
    mag.IDPOINT,
    mag.IDTYPEMAGASIN,
    p.SEUILMIN,
    p.SEUILMAX,
    pt.VAL AS idPointLib
FROM AS_INGREDIENTS_MAGASIN aim
LEFT JOIN AS_INGREDIENTS p ON aim.ID = p.ID
LEFT JOIN CATEGORIEINGREDIENT tp ON p.CATEGORIEINGREDIENT = tp.ID
LEFT JOIN MAGASINPOINT mag ON aim.IDMAGASIN = mag.ID
LEFT JOIN AS_UNITE u ON p.UNITE = u.ID
LEFT JOIN MVTSTOCK m ON m.IDMAGASIN = aim.IDMAGASIN AND m.ETAT = 11
LEFT JOIN MVTSTOCKFILLE f ON f.IDMVTSTOCK = m.ID AND f.IDPRODUIT = aim.ID
LEFT JOIN POINT pt ON pt.ID = mag.IDPOINT
GROUP BY
    aim.ID,
    p.LIBELLE,
    p.CATEGORIEINGREDIENT,
    tp.DESCE,
    aim.IDMAGASIN,
    mag.DESCE,
    p.UNITE,
    u.DESCE,
    p.PV,
    mag.IDPOINT,
    mag.IDTYPEMAGASIN,
    p.SEUILMIN,
    p.SEUILMAX,
	pt.VAL;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_ETATSTOCK_ING_POINT" ("ID", "IDPRODUITLIB", "CATEGORIEINGREDIENT", "IDTYPEPRODUITLIB", "DATEDERNIERMOUVEMENT", "QUANTITE", "ENTREE", "SORTIE", "RESTE", "UNITE", "IDUNITELIB", "PUVENTE", "IDPOINT", "SEUILMIN", "SEUILMAX", "IDPOINTLIB") AS
SELECT
    aim.ID AS ID,
    p.LIBELLE AS idproduitLib,
    p.CATEGORIEINGREDIENT,
    tp.DESCE AS idtypeproduitlib,
    NVL(MAX(m.DATY),TO_DATE('01-01-2001', 'DD-MM-YYYY')) AS dateDernierMouvement,
    CAST(SUM(NVL(f.ENTREE, 0)) - SUM(NVL(f.SORTIE, 0)) AS NUMBER(30,2)) AS QUANTITE,
    CAST(SUM(NVL(f.ENTREE, 0)) AS NUMBER(30,2)) AS ENTREE,
    CAST(SUM(NVL(f.SORTIE, 0)) AS NUMBER(30,2)) AS SORTIE,
    CAST(SUM(NVL(f.ENTREE, 0)) - SUM(NVL(f.SORTIE, 0)) AS NUMBER(30,2)) AS reste,
    p.UNITE,
    u.DESCE AS idunitelib,
    CAST(NVL(p.PV, 0) AS NUMBER(30, 2)) AS PUVENTE,
    mag.IDPOINT,
    p.SEUILMIN,
    p.SEUILMAX,
    pt.VAL AS idPointLib
FROM AS_INGREDIENTS_MAGASIN aim
LEFT JOIN AS_INGREDIENTS p ON aim.ID = p.ID
LEFT JOIN CATEGORIEINGREDIENT tp ON p.CATEGORIEINGREDIENT = tp.ID
LEFT JOIN MAGASINPOINT mag ON aim.IDMAGASIN = mag.ID
LEFT JOIN AS_UNITE u ON p.UNITE = u.ID
LEFT JOIN MVTSTOCK m ON m.IDMAGASIN = aim.IDMAGASIN AND m.ETAT = 11
LEFT JOIN MVTSTOCKFILLE f ON f.IDMVTSTOCK = m.ID AND f.IDPRODUIT = aim.ID
LEFT JOIN POINT pt ON pt.ID = mag.IDPOINT
GROUP BY
    aim.ID,
    p.LIBELLE,
    p.CATEGORIEINGREDIENT,
    tp.DESCE,
    p.UNITE,
    u.DESCE,
    p.PV,
    mag.IDPOINT,
    p.SEUILMIN,
    p.SEUILMAX,
  	pt.VAL;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_ETATSTOCK_ING_TOUS" ("ID", "DATY", "INVQUANTITE", "ENTREE", "SORTIE", "RESTE", "QUANTITE", "MONTANTRESTE", "PU", "IDPRODUITLIB", "CATEGORIEINGREDIENT", "UNITE", "TYPESTOCK", "IDUNITELIB", "IDTYPEPRODUITLIB", "IDFOURNISSEUR", "IDFOURNISSEURLIB", "IDPRODUIT", "IDMAGASIN", "IDMAGASINLIB", "INVDATY", "SEUIL", "SEUILMIN", "SEUILMAX") AS
WITH max_inventaire AS (
    -- Etape 1 : On extrait la date maximale valide et la quantite par COUPLE produit/magasin
    SELECT
        invff.idproduit,
        imeref.idmagasin,
        MAX(imeref.DATY) AS max_daty,
        MAX(invff.QUANTITE) KEEP (DENSE_RANK LAST ORDER BY imeref.DATY) AS qte_max_daty,
        MAX(invff.pu) KEEP (DENSE_RANK LAST ORDER BY imeref.DATY) AS pu_max_daty
    FROM INVENTAIREFILLE invff
    LEFT JOIN inventaireDateHeure imeref ON imeref.ID = invff.IDINVENTAIRE
    WHERE imeref.ETAT >= 11
    GROUP BY invff.idproduit, imeref.idmagasin
),
somme_precalc AS (
    -- Etape 3 : Calcul des sommes globales agregees par COUPLE produit/magasin
    SELECT
        mff.idproduit as idproduit,
        meref.idmagasin as idmagasin,
        NVL(SUM(CASE WHEN meref.DATY >NVL(inv.max_daty, TO_DATE('01/01/2025','DD-MM-YYYY')) THEN mff.ENTREE ELSE 0 END), 0) AS entree,

        NVL(SUM(CASE WHEN meref.DATY > NVL(inv.max_daty, TO_DATE('01/01/2025','DD-MM-YYYY')) THEN mff.SORTIE ELSE 0 END), 0) AS sortie,
        ai.LIBELLE AS idproduitlib,
        ai.CATEGORIEINGREDIENT as CATEGORIEINGREDIENT,
        ai.UNITE as unite,
        ai.TYPESTOCK as typestock,
        u.VAL AS idunitelib,
        c.VAL AS idtypeproduitlib,
        avg(mff.PU) as pu,
        null as IDFOURNISSEUR,
        null as IDFOURNISSEURLIB,
        m.VAL AS idmagasinlib,
        max(inv.max_daty) AS invdaty,
        nvl(max(inv.qte_max_daty),0)as invquantite,
        NVL(SUM(CASE WHEN meref.DATY >NVL(inv.max_daty, TO_DATE('01/01/2025','DD-MM-YYYY')) THEN mff.ENTREE*mff.pu ELSE 0 END), 0) AS montantEntree,
        NVL(SUM(CASE WHEN meref.DATY > NVL(inv.max_daty, TO_DATE('01/01/2025','DD-MM-YYYY')) THEN mff.SORTIE*mff.pu ELSE 0 END), 0) AS montantSortie,
        nvl(avg(inv.pu_max_daty*inv.qte_max_daty),0) as montantInv, nvl(max(ai.SEUIL),0) as seuil,nvl(max(ai.SEUILMAX),nvl(max(ai.SEUILMIN),0)+1000) as seuilmax,nvl(max(ai.SEUILMIN),0) as seuilMin
    FROM MVTSTOCKFILLE mff
    LEFT JOIN mvtStockDateHeure meref ON meref.ID = mff.IDMVTSTOCK
    LEFT JOIN max_inventaire inv ON inv.idproduit = mff.idproduit AND inv.idmagasin = meref.idmagasin
    LEFT JOIN AS_INGREDIENTS ai ON ai.id = mff.IDPRODUIT
    LEFT JOIN CATEGORIEINGREDIENT c ON ai.CATEGORIEINGREDIENT = c.id
    LEFT JOIN MAGASINPOINT m ON meref.IDMAGASIN = m.id
    LEFT JOIN AS_UNITE u ON ai.UNITE = u.id
    WHERE --meref.DATY > NVL(inv.max_daty, TO_DATE('01/01/2025','DD-MM-YYYY')) and
      meref.ETAT >= 11
      AND meref.IDTYPEMVSTOCK != 'TPMVST000023'
    GROUP BY mff.idproduit, meref.idmagasin,ai.LIBELLE,ai.CATEGORIEINGREDIENT,ai.UNITE,ai.TYPESTOCK,u.VAL,c.VAL,m.VAL
)
-- Selection finale
SELECT
    null as ID, null as DATY,  cast(invquantite as number(30,2)) as invquantite,cast(entree as number(30,2)) as entree, cast(sortie as number(30,2)) as sortie,CAST((invquantite)+(ENTREE)-(sortie) AS NUMBER(30,2)) as reste,
    CAST(invquantite+ENTREE-sortie AS NUMBER(30,2)) AS quantite,
    CAST((montantInv+montantEntree-montantSortie)AS NUMBER(30,2))AS montantreste,
    cast((montantInv+montantEntree-montantSortie)/(invquantite+ENTREE-sortie)  as number(30,2)) as pu,
    idproduitlib, CATEGORIEINGREDIENT, UNITE, TYPESTOCK, idunitelib, idtypeproduitlib,
     IDFOURNISSEUR, IDFOURNISSEURLIB, IDPRODUIT, IDMAGASIN, idmagasinlib,invdaty,cast(seuil as number(30,2))as seuil,cast(seuilMin as number(30,2))as seuilMin,cast(seuilMax as number(30,2))as seuilMax
FROM somme_precalc;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_ETATSTOCK_ING_VENTE" ("ID", "IDPRODUITLIB", "IDMAGASIN", "IDMAGASINLIB", "PHYSIQUE", "ENGAGE", "AFACTURER", "MONTANTENTREE", "MONTANTSORTIE", "MONTANTRESTE", "UNITE", "IDUNITELIB", "PU", "MOTSCLESSS") AS
SELECT AI.ID                                                                               AS ID,
       nvl(AI.LIBELLEVENTE,ai.libelle)                                                                     AS IDPRODUITLIB,
       M.ID                                                                                AS IDMAGASIN,
       M.VAL                                                                               AS IDMAGASINLIB,
       CAST(VE.RESTE AS NUMBER(30, 2))                                                     AS PHYSIQUE,
       NVL(CAST(STE.SORTIE AS NUMBER(30, 2)), 0)                                           AS ENGAGE,
       NVL(CAST(VE.RESTE AS NUMBER(30, 2)) - NVL(CAST(STE.SORTIE AS NUMBER(30, 2)), 0), 0) AS AFACTURER,
       CAST(NVL(VE.ENTREE * VE.PU, 0) AS NUMBER(30, 2))                                    AS MONTANTENTREE,
       CAST(NVL(VE.SORTIE * VE.PU, 0) AS NUMBER(30, 2))                                    AS MONTANTSORTIE,
       CAST(NVL((VE.ENTREE * VE.PU) - (VE.SORTIE * VE.PU), 0) AS NUMBER(30, 2))            AS MONTANTRESTE,
       AI.UNITE,
       U.VAL                                                                               AS IDUNITELIB,
       CASE
           WHEN VE.RESTE != 0
               THEN CAST(NVL(((VE.ENTREE * VE.PU) - (VE.SORTIE * VE.PU)) / NVL(VE.RESTE, 1), 0) AS NUMBER(30, 2))
           ELSE CAST(AI.PU AS NUMBER(30, 2))
           END                                                                             AS PU,
       (
           AI.ID || ' | ' || AI.LIBELLEVENTE || ' | ' || M.VAL
           )                                                                               AS MOTSCLESSS
FROM (SELECT MF.IDPRODUIT,
             SUM(MF.ENTREE)                  AS ENTREE,
             SUM(MF.SORTIE)                  AS SORTIE,
             ''                              AS IDVENTEDETAIL,
             ''                              AS IDTRANSFERTDETAIL,
             AVG(MF.PU)                      AS PU,
             ''                              AS MVTSRC,
             ''                              AS DATY,
             SUM(MF.ENTREE) - SUM(MF.SORTIE) AS RESTE,
             0                               AS QUANTITE,
             MS.IDMAGASIN                    AS IDMAGASIN
      FROM MVTSTOCKFILLE MF
               LEFT JOIN MVTSTOCK MS ON MS.ID = MF.IDMVTSTOCK
      WHERE MS.ETAT >= 11
      GROUP BY MF.IDPRODUIT, MS.IDMAGASIN) VE
         LEFT JOIN AS_INGREDIENTS AI ON AI.ID = VE.IDPRODUIT
         LEFT JOIN CATEGORIEINGREDIENT C ON AI.CATEGORIEINGREDIENT = C.ID
         JOIN MAGASINPOINT M ON VE.IDMAGASIN = M.ID
         LEFT JOIN AS_UNITE U ON AI.UNITE = U.ID
         LEFT JOIN STOCK_ENGAGE_FILLE_GP_MAG STE
                   ON STE.IDPRODUIT = VE.IDPRODUIT
                       AND STE.IDMAGASIN = VE.IDMAGASIN
where ai.ISVENTE = 1 and ai.ACTIF = 1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_ETATSTOCK_PROD_FINI" ("ID", "IDPRODUITLIB", "CATEGORIEINGREDIENT", "IDTYPEPRODUITLIB", "IDMAGASIN", "IDMAGASINLIB", "DATEDERNIERMOUVEMENT", "QUANTITE", "ENTREE", "SORTIE", "RESTE", "UNITE", "IDUNITELIB", "PUVENTE", "IDPOINT", "IDTYPEMAGASIN", "SEUILMIN", "SEUILMAX", "MONTANTENTREE", "MONTANTSORTIE", "PU", "MONTANTRESTE") AS
SELECT
 p.ID AS ID,
 p.LIBELLE AS idproduitLib,
 p.CATEGORIEINGREDIENT,
 tp.DESCE AS idtypeproduitlib,
 ms.IDMAGASIN,
 mag.VAL AS idmagasinlib,
 TO_DATE('01-01-2001', 'DD-MM-YYYY') AS dateDernierMouvement,
 CAST(ms.quantite AS NUMBER(30,5) ) AS QUANTITE,
 CAST(NVL( ms.entree, 0) AS NUMBER(30,5))  AS ENTREE,
 CAST(NVL( ms.sortie, 0) AS NUMBER(30,5))  AS SORTIE,
 CAST(NVL( ms.quantite, 0) AS NUMBER(30,5))  AS reste,
 p.UNITE,
 u.DESCE AS idunitelib,
 CAST(NVL(p.PV, 0) AS NUMBER(30,5)) AS PUVENTE,
 mag.IDPOINT,
 mag.IDTYPEMAGASIN,
 CAST(COALESCE(p.SEUILMIN,0) AS NUMBER(30,5)) AS SEUILMIN,
 CAST(COALESCE(p.SEUILMAX,0) AS NUMBER(30,5)) AS SEUILMAX,
 CAST(ms.montantEntree AS NUMBER(30,5)) AS montantEntree,
 CAST(ms.montantSortie AS NUMBER(30,5)) AS montantSortie,
 CAST(p.pu AS NUMBER(30,5)) AS pu,
 CAST(ms.montant AS NUMBER(30,5)) as montantReste
FROM AS_INGREDIENTS p
LEFT JOIN MONTANT_STOCK ms ON ms.IDPRODUIT = p.ID
LEFT JOIN CATEGORIEINGREDIENT tp ON p.CATEGORIEINGREDIENT = tp.ID
LEFT JOIN MAGASINPOINT mag ON ms.IDMAGASIN = mag.ID
LEFT JOIN AS_UNITE u ON p.UNITE = u.ID
WHERE NVL(ms.ENTREE, 0)>0 or NVL(ms.SORTIE, 0)>0
AND p.CATEGORIEINGREDIENT = 'CAT008';

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_ETATSTOCK_PROD_FINI2" ("ID", "IDPRODUITLIB", "CATEGORIEINGREDIENT", "IDTYPEPRODUITLIB", "IDMAGASIN", "IDMAGASINLIB", "DATEDERNIERMOUVEMENT", "QUANTITE", "ENTREE", "SORTIE", "RESTE", "UNITE", "IDUNITELIB", "PUVENTE", "IDPOINT", "IDTYPEMAGASIN", "SEUILMIN", "SEUILMAX", "MONTANTENTREE", "MONTANTSORTIE", "PU", "MONTANTRESTE", "TYPEPRODUIT", "TYPEPRODUITLIB", "DATY") AS
SELECT
    p.ID AS ID,
    p.LIBELLE AS idproduitLib,
    p.CATEGORIEINGREDIENT,
    tp.DESCE AS idtypeproduitlib,
    ms.IDMAGASIN,
    mag.VAL AS idmagasinlib,
    TO_DATE('01-01-2001', 'DD-MM-YYYY') AS dateDernierMouvement,
    CAST(ms.quantite AS NUMBER(30,2) ) AS QUANTITE,
    CAST(NVL( ms.entree, 0) AS NUMBER(30, 2))  AS ENTREE,
    CAST(NVL( ms.sortie, 0) AS NUMBER(30, 2))  AS SORTIE,
    CAST(NVL( ms.quantite, 0) AS NUMBER(30, 2))  AS reste,
    p.UNITE,
    u.DESCE AS idunitelib,
    CAST(NVL(p.PV, 0) AS NUMBER(30, 2)) AS PUVENTE,
    mag.IDPOINT,
    mag.IDTYPEMAGASIN,
    p.SEUILMIN,
    p.SEUILMAX,
    CAST(ms.montantEntree AS NUMBER(30,2)) AS montantEntree,
    CAST(ms.montantSortie AS NUMBER(30,2)) AS montantSortie,
    CAST(p.pu AS NUMBER(30,2)) AS pu,
    CAST(ms.montant AS NUMBER(30,2)) as montantReste,
    p.TYPEPRODUIT,
    tpp.val as typeproduitlib,
    CURRENT_DATE AS DATY
FROM AS_INGREDIENTS p
         LEFT JOIN MONTANT_STOCK ms ON ms.IDPRODUIT = p.ID
         LEFT JOIN CATEGORIEINGREDIENT tp ON p.CATEGORIEINGREDIENT = tp.ID
         LEFT JOIN MAGASINPOINT mag ON ms.IDMAGASIN = mag.ID
         LEFT JOIN AS_UNITE u ON p.UNITE = u.ID
         LEFT JOIN TYPE_PRODUIT tpp ON tpp.id = p.TYPEPRODUIT
WHERE (NVL(ms.ENTREE, 0) > 0 OR NVL(ms.SORTIE, 0) > 0) -- Parentheses ajoutees pour la logique
  AND p.CATEGORIEINGREDIENT = 'CAT008'
  AND p.actif = 1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_ETATSTOCK_PU" ("ID", "RESTE", "IDMAGASIN", "PU", "IDMAGASINLIB", "MVTSRC") AS
SELECT
    idproduit AS id,
    SUM(QUANTITE) AS RESTE,
    IDMAGASIN,
    PU,
    IDMAGASINLIB,
    max(id) AS mvtsrc
FROM
    V_ETATSTOCK_ENTREE vee
GROUP BY
    IDPRODUIT,
    pu,
    IDMAGASIN ,
    IDMAGASINLIB;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_FORMATEUR_FF" ("ID", "LIBELLE", "NIF", "STAT", "ADRESSE", "CONTACT", "CODEPOSTAL", "COMPTE", "IDTYPEFOURNISSEUR", "COMPTEAUXILIAIRE", "ESTACTIF") AS
SELECT "ID",
       "NOM" AS LIBELLE,
       "NIF",
       "STAT",
       "ADRESSE",
       "CONTACT",
       "CODEPOSTAL",
       "COMPTE",
       "IDTYPEFOURNISSEUR",
       "COMPTEAUXILIAIRE",
       "ESTACTIF"
FROM FOURNISSEUR
WHERE IDTYPEFOURNISSEUR = 'TYP000004';

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_FORMATION_BILAN_PAR_STATUT" ("ANNEE", "NBREALISE", "NBNONREALISEE") AS
SELECT
    pf.ANNEE,

    SUM(CASE WHEN afl.ESTREALISEELIB = 'OUI' THEN 1 ELSE 0 END) AS nbRealise,

    SUM(CASE WHEN afl.ESTREALISEELIB = 'NON' THEN 1 ELSE 0 END) AS nbNonRealisee

FROM ACTION_FORMATION_LIB afl

         LEFT JOIN PLAN_FORMATION_ANNUEL pf
                   ON afl.IDPLANFORMATION = pf.ID

GROUP BY pf.ANNEE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_FORMATION_BILAN_PAR_TYPE" ("ANNEE", "NBINTERNE", "NBEXTERNE") AS
SELECT
    pf.ANNEE,

    SUM(CASE WHEN af.TYPEPRESTATAIRE = '1' THEN 1 ELSE 0 END) AS nbInterne,

    SUM(CASE WHEN af.TYPEPRESTATAIRE = '0' THEN 1 ELSE 0 END) AS nbExterne

FROM ACTION_FORMATION af

         LEFT JOIN PLAN_FORMATION_ANNUEL pf
                   ON af.IDPLANFORMATION = pf.ID

GROUP BY pf.ANNEE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_FORMATION_CROISE_TYPE_STATUT" ("ANNEE", "NBREALISEINTERNE", "NBREALISEEXTERNE") AS
SELECT
    pf.ANNEE,

    SUM(CASE
            WHEN af.ESTREALISEE = 1
                AND af.TYPEPRESTATAIRE = '1'
                THEN 1 ELSE 0
        END) AS nbRealiseInterne,

    SUM(CASE
            WHEN af.ESTREALISEE = 1
                AND af.TYPEPRESTATAIRE = '0'
                THEN 1 ELSE 0
        END) AS nbRealiseExterne

FROM ACTION_FORMATION af

         LEFT JOIN PLAN_FORMATION_ANNUEL pf
                   ON af.IDPLANFORMATION = pf.ID

GROUP BY pf.ANNEE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_FOURNISSEUR_LIB" ("ID", "NOM", "NIF", "STAT", "ADRESSE", "CONTACT", "CODEPOSTAL", "COMPTE", "IDTYPEFOURNISSEUR", "COMPTEAUXILIAIRE", "ESTACTIF", "ECHEANCE", "DEVISE", "MAIL", "BANQUE", "IDTYPEFOURNISSEURLIB") AS
SELECT
    f.ID,
    f.NOM,
    f.NIF,
    f.STAT,
    f.ADRESSE,
    f.CONTACT,
    f.CODEPOSTAL,
    f.COMPTE,
    f.IDTYPEFOURNISSEUR,
    f.COMPTEAUXILIAIRE,
    f.ESTACTIF,
    f.ECHEANCE,
    f.DEVISE,
    f.MAIL,
    f.BANQUE,
    tf.VAL AS IDTYPEFOURNISSEURLIB
FROM FOURNISSEUR f
         LEFT JOIN TYPEFOURNISSEUR tf ON f.IDTYPEFOURNISSEUR = tf.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_HIERARCHIE_PROFESSIONNELLE" ("IDFAMILLEPRO", "FAMILLEPRO", "SOUSFAMILLE", "CODEROME", "METIER", "EMPLOIE", "FONCTION") AS
SELECT 
    fp.ID AS idFamillePro,
    fp.VAL AS FamillePro,
    sfp.VAL AS SousFamille,
    cr.CODE AS CodeRome,
    m.VAL AS Metier,
    e.VAL AS Emploie,
    pf.VAL AS Fonction
FROM FAMILLE_PROFESSIONNELLE fp
LEFT JOIN SOUS_FAMILLE_PRO sfp
    ON sfp.IDFAMILLE = fp.ID
LEFT JOIN CODE_ROME cr
    ON cr.IDSOUSFAMILLE = sfp.ID
LEFT JOIN METIER m
    ON m.IDCODEROME = cr.ID
LEFT JOIN EMPLOI e
    ON e.IDMETIER = m.ID
LEFT JOIN PAIE_FONCTION pf
    ON pf.IDEMPLOIE = e.ID;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_HISTOINSERT" ("IDHISTORIQUE", "DATEHISTORIQUE", "HEURE", "OBJET", "ACTION", "IDUTILISATEUR", "REFOBJET", "REMARQUE", "FICHE") AS
select
    hi."IDHISTORIQUE",hi."DATEHISTORIQUE",hi."HEURE",hi."OBJET",hi."ACTION",hi."IDUTILISATEUR",hi."REFOBJET",hi."REMARQUE"|| ' ' ||hi.REFOBJET||' '||hi.datehistorique as remarque,
    cf.FICHE
from HISTOINSERT hi
         left join V_CLASSEETFICHE cf on cf.CLASSE = hi.OBJET;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_HS_FABRICATION_DETAIL" ("IDFABRICATION", "IDPERSONNE", "DATY", "ANNEE", "MOIS", "HS_TOTAL", "HS30", "HS50") AS
SELECT
    hp.IDFABRICATION,
    hp.idPersonne,
    f.daty,
    p.annee,
    p.mois,
    SUM(hp.HS) AS hs_total,
    LEAST(SUM(hp.HS), 8) AS hs30,
    GREATEST(SUM(hp.HS) - 8, 0) AS hs50
FROM HEURESUPFABRICATION_CPL hp
         LEFT JOIN FABRICATION f ON f.id = hp.IDFABRICATION
         LEFT JOIN PERIODEPAIE p ON f.daty BETWEEN p.datedebut AND p.datefin
GROUP BY hp.IDFABRICATION, hp.idPersonne, f.daty, p.annee, p.mois;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_INVENTAIREFILLECAT" ("ID", "IDINVENTAIRE", "IDPRODUIT", "IDPRODUITLIB", "EXPLICATION", "QUANTITETHEORIQUE", "QUANTITE", "LIBELLEEXTACTE", "PU", "ECART", "DATEINV", "MONTANTTHEORIQUE", "MONTANTREELLE", "ECARTMONTANT", "CATEGORIEINGREDIENT", "MVTSRC", "CATEGORIEINGREDIENTLIB") AS
SELECT v."ID",v."IDINVENTAIRE",v."IDPRODUIT",v."IDPRODUITLIB",v."EXPLICATION",v."QUANTITETHEORIQUE",v."QUANTITE",v."LIBELLEEXTACTE",v."PU",v."ECART",v."DATEINV",v."MONTANTTHEORIQUE",v."MONTANTREELLE",v."ECARTMONTANT",v."CATEGORIEINGREDIENT",v."MVTSRC",
	c.val AS categorieingredientlib
	FROM V_INVENTAIREFILLECPL v
	LEFT JOIN CATEGORIEINGREDIENT c ON c.id=v.categorieingredient;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_INVENTAIREFILLECPL" ("ID", "IDINVENTAIRE", "IDPRODUIT", "IDPRODUITLIB", "EXPLICATION", "QUANTITETHEORIQUE", "QUANTITE", "LIBELLEEXTACTE", "PU", "ECART", "DATEINV", "MONTANTTHEORIQUE", "MONTANTREELLE", "ECARTMONTANT", "CATEGORIEINGREDIENT", "MVTSRC", "UNITELIB", "IDMAGASIN", "IDMAGASINLIB") AS
SELECT
    i.ID AS ID,
    i.IDINVENTAIRE AS IDINVENTAIRE,
    i.IDPRODUIT AS IDPRODUIT,
    p.LIBELLE AS IDPRODUITLIB,
    i.EXPLICATION AS EXPLICATION,

    CAST(
            NVL(i.QUANTITETHEORIQUE, 0)
        AS NUMBER(30, 6)
    ) AS QUANTITETHEORIQUE,

    CAST(
            NVL(i.QUANTITE, 0)
        AS NUMBER(30, 6)
    ) AS QUANTITE,

    p.LIBELLEEXTACTE AS LIBELLEEXTACTE,

    CAST(
            NVL(i.PU, 0)
        AS NUMBER(30, 6)
    ) AS PU,

    CAST(
            NVL(i.QUANTITE, 0)
                - NVL(i.QUANTITETHEORIQUE, 0)
        AS NUMBER(30, 6)
    ) AS ECART,

    iv.DATY AS DATEINV,

    CAST(
            NVL(i.PU, 0)
                * NVL(i.QUANTITETHEORIQUE, 0)
        AS NUMBER(30, 6)
    ) AS MONTANTTHEORIQUE,

    CAST(
            NVL(i.PU, 0)
                * NVL(i.QUANTITE, 0)
        AS NUMBER(30, 6)
    ) AS MONTANTREELLE,

    CAST(
            (
                NVL(i.PU, 0)
                    * NVL(i.QUANTITE, 0)
                )
                -
            (
                NVL(i.PU, 0)
                    * NVL(i.QUANTITETHEORIQUE, 0)
                )
        AS NUMBER(30, 6)
    ) AS ECARTMONTANT,

    p.CATEGORIEINGREDIENT AS CATEGORIEINGREDIENT,
    i.MVTSRC,
    au.val as uniteLib,
    iv.idMagasin,
    m.val as idMagasinLib
FROM INVENTAIREFILLE i

         LEFT JOIN INVENTAIRE iv
                   ON iv.ID = i.IDINVENTAIRE

         LEFT JOIN AS_INGREDIENTS p
                   ON p.ID = i.IDPRODUIT
         LEFT JOIN AS_UNITE AU on p.UNITE = au.id
         LEFT JOIN MAGASINPOINT m ON m.ID = iv.IDMAGASIN
WHERE iv.ETAT >= 11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_JOURS_2016_NOW" ("DATY", "JOUR", "SEMAINEMOIS", "MOIS", "ANNEE", "NUMEROJOURSEMAINE", "JOURLIB") AS
SELECT
    d AS DATY,
    EXTRACT(DAY FROM d) AS JOUR,
    CEIL((TO_CHAR(d, 'DD') + TO_CHAR(TRUNC(d, 'MM'), 'D') - 1) / 7) as semainemois,
    EXTRACT(MONTH FROM d) AS MOIS,
    EXTRACT(YEAR FROM d) AS ANNEE,
    TO_CHAR(d, 'D') as numerojoursemaine,
    TO_CHAR(d, 'Day', 'NLS_DATE_LANGUAGE=FRENCH') AS JOURLIB
FROM (
         SELECT TO_DATE('2025-05-01', 'YYYY-MM-DD') + LEVEL - 1 AS d
         FROM dual
             CONNECT BY LEVEL <= LAST_DAY(SYSDATE) - TO_DATE('2025-05-01', 'YYYY-MM-DD') + 1
     );

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_LIAISONPAIEMENT_FACTUREFOURN" ("ID", "ID1", "ID2", "MONTANT", "ETAT", "IDFACTUREFOURNISSEUR", "DESIGNATION", "DATY") AS
select li."ID",li."ID1",li."ID2",li."MONTANT",li."ETAT",ve.id as idfacturefournisseur, ve.DESIGNATION,ve.daty from LIAISONPAIEMENT li left join FACTUREFOURNISSEUR ve on ve.id=li.ID2;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_LIAISONPAIEMENT_VENTE" ("ID", "ID1", "ID2", "MONTANT", "ETAT", "IDVENTE", "DESIGNATION", "DATY") AS
select li."ID",li."ID1",li."ID2",li."MONTANT",li."ETAT",ve.id as idVente, ve.DESIGNATION,ve.daty
from LIAISONPAIEMENT li left join (select id,DESIGNATION,daty from vente union all select id,designation,daty from FACTUREFOURNISSEUR) ve on ve.id=li.ID2;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_MATCHING_CV_FP" ("IDCV", "IDFICHEPOSTE", "IDFICHEPOSTECOMPETENCE", "IDTYPECOMPETENCE", "TYPECOMPETENCELIB", "COMPETENCE", "NIVEAUREQUIS", "NIVEAUCANDIDAT", "ECART", "ESTVALIDE", "RESULTAT") AS
SELECT
    cv.ID AS idCv,
    cv.IDFICHEPOSTE AS idFichePoste,
    fpc.ID AS idFichePosteCompetence,
    fpc.IDTYPECOMPETENCESFP AS idTypeCompetence,
    typ.VAL AS typeCompetenceLib,
    fpc.DESCRIPTION AS competence,
    fpc.NIVEAU AS niveauRequis,
    cvc.NIVEAU AS niveauCandidat,
    (cvc.NIVEAU - fpc.NIVEAU) AS ecart,
    CASE
        WHEN cvc.NIVEAU IS NULL THEN 0
        WHEN cvc.NIVEAU >= fpc.NIVEAU THEN 1
        ELSE 0
        END AS estValide,
    CASE
        WHEN cvc.NIVEAU IS NULL THEN 'NON RENSEIGNE'
        WHEN cvc.NIVEAU >= fpc.NIVEAU THEN 'OK'
        ELSE 'INSUFFISANT'
        END AS resultat
FROM CV cv
         JOIN FICHE_POSTE_COMPETENCES fpc ON fpc.IDFICHEPOSTE = cv.IDFICHEPOSTE
         LEFT JOIN TYPE_COMPETENCES_FP typ ON typ.ID = fpc.IDTYPECOMPETENCESFP
         LEFT JOIN CV_COMPETENCE cvc ON cvc.IDCV = cv.ID
    AND cvc.IDTYPECOMPETENCESFP = fpc.IDTYPECOMPETENCESFP;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_MODULE_PRESTATAIRE_LIB" ("ID", "IDFORMATEUR", "MODULE", "IDFORMATEURLIB") AS
SELECT
    mp.ID,mp.IDFORMATEUR,mp.MODULE,
    f.LIBELLE AS idFormateurLib
FROM
    MODULE_PRESTATAIRE mp
        LEFT JOIN
    FORMATEUR f ON f.ID = mp.IDFORMATEUR;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_MOIS_ANNEE_DISTINCTS" ("MOIS", "ANNEE", "MOISLIB") AS
SELECT
    EXTRACT(MONTH FROM dt) AS MOIS,
    EXTRACT(YEAR FROM dt) AS ANNEE,
    TRIM(TO_CHAR(dt, 'Month', 'NLS_DATE_LANGUAGE=FRENCH')) AS moislib
FROM (
         SELECT ADD_MONTHS(DATE '2025-05-01', LEVEL - 1) AS dt
         FROM dual
             CONNECT BY ADD_MONTHS(DATE '2025-05-01', LEVEL - 1) <= TRUNC(SYSDATE, 'MM')
     )
ORDER BY ANNEE, MOIS;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_MOYENNE_SALAIRE_PARFONCTION" ("ID", "FONCTIONLIB", "ANNEE", "MOIS", "MOYENNE_SALAIRE_BASE") AS
SELECT
    pip.idfonction as id,
    pf.desce as fonctionlib,
    pem.annee,
    pem.mois,
    ROUND(AVG(pe.GAIN), 2) AS moyenne_salaire_base
FROM PAIE_EDITION pe
         LEFT JOIN PAIE_EDITIONMOISANNEE pem ON pem.ID = pe.IDEDITION
         LEFT JOIN PAIE_INFO_PERSONNEL pip ON pip.ID = pe.IDPERSONNEL
         left join PAIE_FONCTION pf ON pf.id = pip.IDFONCTION
WHERE pe.IDELEMENTPAIE = 'PR000041'
GROUP BY pip.idfonction, pf.desce, pem.annee, pem.mois;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_MOYENNE_SALAIRE_PAR_FONCTION" ("IDFONCTION", "FONCTION_LIBELLE", "MOYENNE_SALAIRE") AS
SELECT
    sb.idfonction,
    pf.desce AS fonction_libelle,
    AVG(sb.montant) AS moyenne_salaire
FROM PAIE_INFO_PERSONNEL_SB sb
         LEFT JOIN PAIE_FONCTION pf ON pf.id = sb.idfonction
GROUP BY sb.idfonction, pf.desce;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_MVTSTOCKFILLEOFF" ("IDPRODUIT", "IDOFFILLE", "LIBELLEEXACTE", "ENTREE", "SORTIE", "PU", "MONTANT") AS
SELECT
	mvt.IDPRODUIT,
	fof.IDOFFILLE,
	mvt.LIBELLEEXACTE,
	CAST(sum(mvt.ENTREE ) AS NUMBER(20, 2)) AS ENTREE,
	CAST(sum(mvt.SORTIE ) AS NUMBER(20, 2)) AS SORTIE,
	ROUND(sum(mvt.PU), 2) AS PU,
	ROUND(SUM(MONTANT), 2) AS MONTANT
FROM
	MVTSTOCKFILLELIB mvt
JOIN FABRICATION_OF fof ON
	mvt.IDOBJET = fof.IDMERE
WHERE
	mvt.ETAT >= 11
GROUP BY
	mvt.IDPRODUIT,
	fof.IDOFFILLE,
	mvt.LIBELLEEXACTE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_MVTSTOCKFILLERENDEMENT" ("IDPRODUIT", "IDOFFILLE", "LIBELLEEXACTE", "ENTREE", "PU", "MONTANT") AS
SELECT
	mvt.IDPRODUIT,
	fof.IDOFFILLE,
	mvt.LIBELLEEXACTE,
	CAST(sum(mvt.ENTREE) AS NUMBER(20, 2)) AS ENTREE,
	ROUND(sum(mvt.PU), 2) AS PU,
	ROUND(SUM(MONTANT), 2) AS MONTANT
FROM
	MVTSTOCKFILLELIB mvt
JOIN FABRICATION_OF fof ON
	mvt.IDOBJET = fof.IDMERE
WHERE
	mvt.ENTREE > 0 and
	mvt.ETAT >= 11
GROUP BY
	mvt.IDPRODUIT,
	fof.IDOFFILLE,
	mvt.LIBELLEEXACTE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_NEXT_FACTURE_FOURNISSEUR" ("PREFIXE", "DATE_FACTURE", "NEXTNUM") AS
SELECT
    typeachat || '-' || SUBSTR(IDFOURNISSEURLIB, 1, 1) AS prefixe,
    daty AS date_facture,
    LPAD(COUNT(*) + 1, 2, '0') AS nextnum
FROM facturefournisseurcpl
WHERE etat>=11
GROUP BY
    typeachat || '-' || SUBSTR(IDFOURNISSEURLIB, 1, 1),
    daty;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_NUMEROAVOIR_EN_COURS" ("ANNEE_EN_COURS", "DERNIER_NUM", "PROCHAIN_NUM", "PROCHAIN_NUM_FORMAT") AS
SELECT
    EXTRACT(YEAR FROM SYSDATE) AS ANNEE_EN_COURS,
    NVL(MAX(TO_NUMBER(SUBSTR(numavoir, 1, INSTR(numavoir, '/') - 1))), 0) AS DERNIER_NUM,
    NVL(MAX(TO_NUMBER(SUBSTR(numavoir, 1, INSTR(numavoir, '/') - 1))), 0) + 1 AS PROCHAIN_NUM,
    LPAD(NVL(MAX(TO_NUMBER(SUBSTR(numavoir, 1, INSTR(numavoir, '/') - 1))), 0) + 1, 4, '0')
        || '/' || TO_CHAR(EXTRACT(YEAR FROM SYSDATE)) AS PROCHAIN_NUM_FORMAT
FROM AVOIRFC
WHERE SUBSTR(numavoir, INSTR(numavoir, '/') + 1) = TO_CHAR(EXTRACT(YEAR FROM SYSDATE));

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_NUMEROBC_EN_COURS" ("ANNEE_EN_COURS", "DERNIER_NUM", "PROCHAIN_NUM", "PROCHAIN_NUM_FORMAT") AS
SELECT
    EXTRACT(YEAR FROM SYSDATE) AS ANNEE_EN_COURS,
    NVL(MAX(TO_NUMBER(SUBSTR(NUMEROBC, 1, INSTR(NUMEROBC, '/') - 1))), 0) AS DERNIER_NUM,
    NVL(MAX(TO_NUMBER(SUBSTR(NUMEROBC, 1, INSTR(NUMEROBC, '/') - 1))), 0) + 1 AS PROCHAIN_NUM,
    LPAD(NVL(MAX(TO_NUMBER(SUBSTR(NUMEROBC, 1, INSTR(NUMEROBC, '/') - 1))), 0) + 1, 4, '0')
        || '/' || TO_CHAR(EXTRACT(YEAR FROM SYSDATE)) AS PROCHAIN_NUM_FORMAT
FROM BONDECOMMANDE_CLIENT
WHERE SUBSTR(NUMEROBC, INSTR(NUMEROBC, '/') + 1) = TO_CHAR(EXTRACT(YEAR FROM SYSDATE));

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_NUMEROFACTURE_EN_COURS" ("ANNEE_EN_COURS", "DERNIER_NUM", "PROCHAIN_NUM", "PROCHAIN_NUM_FORMAT") AS
SELECT
    EXTRACT(YEAR FROM SYSDATE) AS ANNEE_EN_COURS,
    NVL(MAX(TO_NUMBER(SUBSTR(NUMEROFACTURE, 1, INSTR(NUMEROFACTURE, '/') - 1))), 0) AS DERNIER_NUM,
    NVL(MAX(TO_NUMBER(SUBSTR(NUMEROFACTURE, 1, INSTR(NUMEROFACTURE, '/') - 1))), 0) + 1 AS PROCHAIN_NUM,
    LPAD(NVL(MAX(TO_NUMBER(SUBSTR(NUMEROFACTURE, 1, INSTR(NUMEROFACTURE, '/') - 1))), 0) + 1, 4, '0')
    || '/' || TO_CHAR(EXTRACT(YEAR FROM SYSDATE)) AS PROCHAIN_NUM_FORMAT
FROM VENTE
WHERE SUBSTR(NUMEROFACTURE, INSTR(NUMEROFACTURE, '/') + 1) = TO_CHAR(EXTRACT(YEAR FROM SYSDATE));

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_NUMEROPROFORMA_EN_COURS" ("ANNEE_EN_COURS", "DERNIER_NUM", "PROCHAIN_NUM", "PROCHAIN_NUM_FORMAT") AS
SELECT
    EXTRACT(YEAR FROM SYSDATE) AS ANNEE_EN_COURS,
    NVL(MAX(TO_NUMBER(SUBSTR(NUMEROPROFORMA, 1, INSTR(NUMEROPROFORMA, '/') - 1))), 0) AS DERNIER_NUM,
    NVL(MAX(TO_NUMBER(SUBSTR(NUMEROPROFORMA, 1, INSTR(NUMEROPROFORMA, '/') - 1))), 0) + 1 AS PROCHAIN_NUM,
    LPAD(NVL(MAX(TO_NUMBER(SUBSTR(NUMEROPROFORMA, 1, INSTR(NUMEROPROFORMA, '/') - 1))), 0) + 1, 4, '0')
        || '/' || TO_CHAR(EXTRACT(YEAR FROM SYSDATE)) AS PROCHAIN_NUM_FORMAT
FROM PROFORMA
WHERE SUBSTR(NUMEROPROFORMA, INSTR(NUMEROPROFORMA, '/') + 1) = TO_CHAR(EXTRACT(YEAR FROM SYSDATE));

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_PAIE_RECAP" ("ID", "MOIS", "ANNEE", "IDEDITION", "SALAIRE", "HS_M", "INDEM", "ANCIEN", "PRIME", "AUTRES", "TOTAL", "CNAPS", "OSTIE", "IRSA_E", "IRSA_S", "AV_SPE", "AUTRES2", "A_PAYER") AS
SELECT
    p.idpersonnel AS id,
    p.mois,
    p.annee,
    p.idedition,
    SUM(NVL(CASE WHEN p.regroupement = 1  THEN p.gain END, 0)) AS SALAIRE,
    SUM(NVL(CASE WHEN p.regroupement = 2  THEN p.gain END, 0)) AS HS_M,
    SUM(NVL(CASE WHEN p.regroupement = 3  THEN p.gain END, 0)) AS INDEM,
    SUM(NVL(CASE WHEN p.regroupement = 4  THEN p.gain END, 0)) AS ANCIEN,
    SUM(NVL(CASE WHEN p.regroupement = 5  THEN p.gain END, 0)) AS PRIME,
    SUM(NVL(CASE WHEN p.regroupement = 6  THEN p.gain END, 0)) AS AUTRES,
    SUM(NVL(CASE WHEN p.regroupement = 7  THEN p.gain END, 0)) AS TOTAL,
    SUM(NVL(CASE WHEN p.regroupement = 8  THEN p.retenue END, 0)) AS CNAPS,
    SUM(NVL(CASE WHEN p.regroupement = 9  THEN p.retenue END, 0)) AS OSTIE,
    SUM(NVL(CASE WHEN p.regroupement = 10 THEN p.retenue END, 0)) AS IRSA_E,
    SUM(NVL(CASE WHEN p.regroupement = 11 THEN p.retenue END, 0)) AS IRSA_S,
    SUM(NVL(CASE WHEN p.regroupement = 12 THEN p.retenue END, 0)) AS AV_SPE,
    SUM(NVL(CASE WHEN p.regroupement = 13 THEN p.retenue END, 0)) AS AUTRES2,
    SUM(NVL(CASE WHEN p.regroupement = 14 THEN p.gain END, 0)) AS A_PAYER
FROM
    PAIE_EDITION p
        LEFT JOIN log_personnel l ON l.id = p.idpersonnel
GROUP BY
    p.idedition,p.idpersonnel, p.mois, p.annee;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_POINTAGE_TOTAL_HEURE_SUP" ("IDPERSONNEL", "MOIS", "ANNEE", "TOTAL_HEURE_SUP") AS
SELECT
    IDPERSONNEL,
    MOIS,
    ANNEE,
    (HEURESUPNORMAL + HEURESUPNUIT + HEURESUPFERIE + HEURESUPWEEKEND) AS TOTAL_HEURE_SUP
FROM
    POINTAGE
WHERE
    ETAT = 11
ORDER BY
    IDPERSONNEL, ANNEE, MOIS;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_PROGRAMME_INTEGRATION_LIB" ("ID", "IDPERSONNEL", "DATY", "REMARQUE", "IDPERSONNELLIB", "MATRICULE", "IDFONCTION", "IDFONCTIONLIB", "IDSERVICE", "IDSERVICELIB") AS
SELECT
    p.ID,p.IDPERSONNEL,p.DATY,p.REMARQUE,
    lp.nom || ' ' || lp.prenom AS idPersonnelLib,
    paie.matricule,
    paie.idfonction,
    f.val AS idFonctionLib,
    lp.service AS idService,
    s.libelle AS idServiceLib
FROM Programme_integration p
         JOIN LOG_PERSONNEL lp ON p.idPersonnel = lp.id
         JOIN PAIE_INFO_PERSONNEL paie ON lp.id = paie.id
         LEFT JOIN PAIE_FONCTION f ON paie.idfonction = f.id
         LEFT JOIN LOG_SERVICE s ON lp.service = s.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_PROG_INTEGRATION_DETAIL_LIB" ("ID", "IDPROGRAMEDETAIL", "JOURDELASEMAINE", "HEURE", "DUREE", "ACTIONTHEME", "CONTENUE", "IDINTERVENANT", "IDINTERVENANTLIB", "IDINTERVENANTFONCTION", "IDINTERVENANTFONCTIONLIB", "IDINTERVENANTSERVICE", "IDINTERVENANTSERVICELIB", "DUREE_EFFECTIVE") AS
SELECT
    pd.ID,
    pd.IDPROGRAMEDETAIL,

    CASE
        WHEN pd.JOURDELASEMAINE = 1 THEN 'Lundi'
        WHEN pd.JOURDELASEMAINE = 2 THEN 'Mardi'
        WHEN pd.JOURDELASEMAINE = 3 THEN 'Mercredi'
        WHEN pd.JOURDELASEMAINE = 4 THEN 'Jeudi'
        WHEN pd.JOURDELASEMAINE = 5 THEN 'Vendredi'
        WHEN pd.JOURDELASEMAINE = 6 THEN 'Samedi'
        WHEN pd.JOURDELASEMAINE = 7 THEN 'Dimanche'
        ELSE 'Inconnu'
        END AS JOURDELASEMAINE,

    pd.HEURE,
    pd.DUREE,
    pd.ACTIONTHEME,
    pd.CONTENUE,
    pd.IDINTERVENANT,

    lp.nom || ' ' || lp.prenom AS idIntervenantLib,

    paie.idfonction AS idIntervenantFonction,
    f.val AS idIntervenantFonctionLib,

    lp.service AS idIntervenantService,
    s.libelle AS idIntervenantServiceLib,

    (pd.Duree * 2) AS Duree_Effective

FROM Programme_integration_detail pd
         LEFT JOIN LOG_PERSONNEL lp
                   ON pd.idIntervenant = lp.id
         LEFT JOIN PAIE_INFO_PERSONNEL paie
                   ON lp.id = paie.id
         LEFT JOIN PAIE_FONCTION f
                   ON paie.idfonction = f.id
         LEFT JOIN LOG_SERVICE s
                   ON lp.service = s.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_QTE_DISPO_LOT_SEXE_QUALITE" ("ID", "IDSEXE", "IDQUALITE", "QTE") AS
SELECT
    m.IDLOT                     AS id,
    d.IDSEXE                    AS idsexe,
    d.IDQUALITE                 AS idqualite,
    SUM(d.QTE)                  AS qte
FROM TRIAGEBATIMENTPARQUETDETAIL d
JOIN TRIAGEBATIMENTPARQUET m
    ON d.IDMERE = m.ID
GROUP BY
    m.IDLOT,
    d.IDSEXE,
    d.IDQUALITE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_RAPPROCHEMENT_OF" ("IDOBJET", "SORTIE", "PU", "MONTANTSORTIE", "QTETH", "PUTH", "MONTTH", "ECARTQTE", "ECARTMONTANT", "ECARTPU") AS
SELECT
    IDOBJET,
    CAST(SUM(SORTIE) AS NUMBER(30,5)) AS sortie,
    CAST(SUM(PU) AS NUMBER(30,2)) AS pu,
    CAST(SUM(MONTANTSORTIE) AS NUMBER(30,5)) AS montantsortie,
    CAST(SUM(QTETH) AS NUMBER(30,5)) AS qteth,
    CAST(SUM(PUTH) AS NUMBER(30,2)) AS puth,
    CAST(SUM(MONTTH) AS NUMBER(30,2)) AS montth,
    CAST(SUM(SORTIE - QTETH) AS NUMBER(30,5)) AS ecartqte,
    CAST(SUM(MONTANTSORTIE - MONTTH) AS NUMBER(30,2)) AS ecartmontant,
    CAST(SUM(PU - PUTH) AS NUMBER(30,2)) AS ecartpu
FROM
    STOCKETDEPENSEOFFABTHE
GROUP BY
    IDOBJET;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_RAPPROCHEMENT_OF_IA" ("IDOBJET", "SORTIE", "PU", "MONTANTSORTIE", "QTETH", "PUTH", "MONTTH", "ECARTQTE", "ECARTMONTANT", "ECARTPU", "IDPRODUIT", "MOTSCLESSS") AS
SELECT SQ."IDOBJET",SQ."SORTIE",SQ."PU",SQ."MONTANTSORTIE",SQ."QTETH",SQ."PUTH",SQ."MONTTH",SQ."ECARTQTE",SQ."ECARTMONTANT",SQ."ECARTPU",SQ.IDPRODUIT,
       (NVL(TO_CHAR(IDOBJET),'') || ' | ' || NVL(TO_CHAR(SORTIE),'') || ' | ' || NVL(TO_CHAR(PU),'') || ' | ' || NVL(TO_CHAR(MONTANTSORTIE),'') || ' | ' || NVL(TO_CHAR(QTETH),'') || ' | ' || NVL(TO_CHAR(PUTH),'') || ' | ' || NVL(TO_CHAR(MONTTH),'') || ' | ' || NVL(TO_CHAR(ECARTQTE),'') || ' | ' || NVL(TO_CHAR(ECARTMONTANT),'') || ' | ' || NVL(TO_CHAR(ECARTPU),'')) AS MOTSCLESSS
FROM (
         SELECT
             IDOBJET,
             IDPRODUIT,
             CAST(SUM(SORTIE) AS NUMBER(30,5)) AS sortie,
             CAST(SUM(PU) AS NUMBER(30,2)) AS pu,
             CAST(SUM(MONTANTSORTIE) AS NUMBER(30,5)) AS montantsortie,
             CAST(SUM(QTETH) AS NUMBER(30,5)) AS qteth,
             CAST(SUM(PUTH) AS NUMBER(30,2)) AS puth,
             CAST(SUM(MONTTH) AS NUMBER(30,2)) AS montth,
             CAST(SUM(SORTIE - QTETH) AS NUMBER(30,5)) AS ecartqte,
             CAST(SUM(MONTANTSORTIE - MONTTH) AS NUMBER(30,2)) AS ecartmontant,
             CAST(SUM(PU - PUTH) AS NUMBER(30,2)) AS ecartpu
         FROM
             STOCKETDEPENSEOFFABTHE
         GROUP BY
             IDOBJET,
             IDPRODUIT
     ) SQ;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_RAPPROCHEMENT_POURCENTAGE" ("ID", "VAL", "DESCE", "MONTANT", "POURCENTAGE", "DATY") AS
SELECT
    ID,
    VAL,
    DESCE,
    CAST(MONTANT AS NUMBER(15,2)) AS montant,
    CAST(
            CASE
                WHEN MONTANT > 0 THEN
                    MONTANT * 100.0 /
                    SUM(
                            CASE
                                WHEN MONTANT > 0 THEN MONTANT
                                ELSE 0
                                END
                    ) OVER ()
                ELSE 0
                END
        AS NUMBER(10,2)) AS pourcentage,
    CURRENT_DATE AS DATY
FROM RAPPROCHEMENTGLOBALE_PIE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_RECAP_GLOBAL_FORMATION" ("ANNEE", "REF_FORMATION", "TYPE_FORMATION", "TYPE_FORMATIONLIB", "CATEGORIE", "CATEGORIELIB", "INTITULE", "SEMESTRE", "SEMESTRELIB", "INTERNE_EXTERNE", "FORMATEUR", "FORMATEURLIB", "TYPE_COUT_ID", "TYPE_COUT_LIB", "MONTANT_COUT", "NOMBRE_SESSION", "NB_PARTICIPANT_OUVRIERS", "NB_PARTICIPANT_CADRES", "NB_PARTICIPANT_TOTAL", "DUREE_PAR_STAGIAIRE", "DUREE_TOTALE_HEURE") AS
SELECT
    pfa.ANNEE,

    af.REFERENCE AS REF_FORMATION,

    af.IDTYPEFORMATION AS TYPE_FORMATION,
    tf.VAL AS TYPE_FORMATIONLIB,

    af.IDCATEGORIEFORMATION AS CATEGORIE,
    cf.VAL AS CATEGORIELIB,

    af.INTITULE,

    af.IDSEMESTRE AS SEMESTRE,
    s.VAL AS SEMESTRELIB,

    cASE af.TYPEPRESTATAIRE
        WHEN '0' THEN 'INTERNE'
        WHEN '1' THEN 'EXTERNE'
        ELSE 'AUTRE'
    END AS INTERNE_EXTERNE,

    af.FORMATEUR,
    f.LIBELLE AS FORMATEURLIB,

    tcf.ID AS TYPE_COUT_ID,
    tcf.VAL AS TYPE_COUT_LIB,

    NVL(cout.MONTANT,0) AS MONTANT_COUT,

    NVL(sess.NB_SESSION,0) AS NOMBRE_SESSION,

    NVL(af.NBOUVRIERSPREVUE,0) AS NB_PARTICIPANT_OUVRIERS,
    NVL(af.NBCADREPREVUE,0) AS NB_PARTICIPANT_CADRES,

    NVL(af.NBOUVRIERSPREVUE,0) + NVL(af.NBCADREPREVUE,0) AS NB_PARTICIPANT_TOTAL,

    NVL(af.DUREESTAGIAIREHEURE,0) AS DUREE_PAR_STAGIAIRE,

    NVL(af.DUREESTAGIAIREHEURE,0) *
    (NVL(af.NBOUVRIERSPREVUE,0) + NVL(af.NBCADREPREVUE,0))
        AS DUREE_TOTALE_HEURE

FROM PLAN_FORMATION_ANNUEL pfa

         JOIN ACTION_FORMATION af
              ON af.IDPLANFORMATION = pfa.ID

-- ? jointures libelles
         LEFT JOIN TYPE_FORMATION tf
                   ON tf.ID = af.IDTYPEFORMATION

         LEFT JOIN CATEGORIE_FORMATION cf
                   ON cf.ID = af.IDCATEGORIEFORMATION

         LEFT JOIN SEMESTRE s
                   ON s.ID = af.IDSEMESTRE

         LEFT JOIN FORMATEUR f
                   ON f.ID = af.FORMATEUR

-- ? sessions agregees
         LEFT JOIN (
    SELECT
        IDACTIONFORMATION,
        COUNT(*) AS NB_SESSION
    FROM SESSION_FORMATION
    GROUP BY IDACTIONFORMATION
) sess
                   ON sess.IDACTIONFORMATION = af.ID

-- ? couts agreges
         LEFT JOIN (
    SELECT
        afd.IDACTIONFORMATION,
        afd.IDTYPECOUT,
        SUM(afd.COUT) AS MONTANT
    FROM ACTION_FORMATION_DETAIL afd
    GROUP BY afd.IDACTIONFORMATION, afd.IDTYPECOUT
) cout
                   ON cout.IDACTIONFORMATION = af.ID

         LEFT JOIN TYPE_COUT_FORMATION tcf
                   ON tcf.ID = cout.IDTYPECOUT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_STATISTIQUE_CA" ("ANNEE", "DATY", "CA_DU_JOUR", "MEILLEUR_CA_SEMAINE", "MEILLEUR_CA_MOIS", "CA_ANNEE", "CA_JANVIER", "CA_FEVRIER", "CA_MARS", "CA_AVRIL", "CA_MAI", "CA_JUIN", "CA_JUILLET", "CA_AOUT", "CA_SEPTEMBRE", "CA_OCTOBRE", "CA_NOVEMBRE", "CA_DECEMBRE") AS
WITH CA_PAR_VENTE AS (
    SELECT
        v.ID AS IDVENTE,
        TRUNC(v.DATY) AS DATY,


        SUM(
                NVL(vd.QTE, 0) * NVL(vd.PU, 0)
        ) - NVL(v.FRAISLIVRAISON, 0) AS CA_VENTE

    FROM VENTE v

             JOIN VENTE_DETAILS vd
                  ON vd.IDVENTE = v.ID

    WHERE v.DATY IS NOT NULL
      AND v.ETAT >= 11

    GROUP BY
        v.ID,
        TRUNC(v.DATY),
        v.FRAISLIVRAISON
),

     CA_PAR_JOUR AS (
         SELECT
             DATY,
             SUM(CA_VENTE) AS CA
         FROM CA_PAR_VENTE
         GROUP BY DATY
     )

SELECT
    EXTRACT(YEAR FROM SYSDATE) AS ANNEE,
    TRUNC(SYSDATE) AS DATY,

    /* CA du jour */
    NVL(
            MAX(
                    CASE
                        WHEN DATY = TRUNC(SYSDATE)
                            THEN CA
                        END
            ),
            0
    ) AS CA_DU_JOUR,

    /* Meilleur CA journalier de la semaine */
    NVL(
            MAX(
                    CASE
                        WHEN DATY >= TRUNC(SYSDATE, 'IW')
                            AND DATY < TRUNC(SYSDATE, 'IW') + 7
                            THEN CA
                        END
            ),
            0
    ) AS MEILLEUR_CA_SEMAINE,

    /* Meilleur CA journalier du mois */
    NVL(
            MAX(
                    CASE
                        WHEN DATY >= TRUNC(SYSDATE, 'MM')
                            AND DATY < ADD_MONTHS(TRUNC(SYSDATE, 'MM'), 1)
                            THEN CA
                        END
            ),
            0
    ) AS MEILLEUR_CA_MOIS,

    /* CA total de l'annee */
    NVL(
            SUM(
                    CASE
                        WHEN DATY >= TRUNC(SYSDATE, 'YYYY')
                            AND DATY < ADD_MONTHS(TRUNC(SYSDATE, 'YYYY'), 12)
                            THEN CA
                        ELSE 0
                        END
            ),
            0
    ) AS CA_ANNEE,

    /* CA par mois de l'annee courante */
    NVL(SUM(
                CASE
                    WHEN DATY >= TRUNC(SYSDATE, 'YYYY')
                        AND DATY < ADD_MONTHS(TRUNC(SYSDATE, 'YYYY'), 1)
                        THEN CA ELSE 0
                    END
        ), 0) AS CA_JANVIER,

    NVL(SUM(
                CASE
                    WHEN DATY >= ADD_MONTHS(TRUNC(SYSDATE, 'YYYY'), 1)
                        AND DATY < ADD_MONTHS(TRUNC(SYSDATE, 'YYYY'), 2)
                        THEN CA ELSE 0
                    END
        ), 0) AS CA_FEVRIER,

    NVL(SUM(
                CASE
                    WHEN DATY >= ADD_MONTHS(TRUNC(SYSDATE, 'YYYY'), 2)
                        AND DATY < ADD_MONTHS(TRUNC(SYSDATE, 'YYYY'), 3)
                        THEN CA ELSE 0
                    END
        ), 0) AS CA_MARS,

    NVL(SUM(
                CASE
                    WHEN DATY >= ADD_MONTHS(TRUNC(SYSDATE, 'YYYY'), 3)
                        AND DATY < ADD_MONTHS(TRUNC(SYSDATE, 'YYYY'), 4)
                        THEN CA ELSE 0
                    END
        ), 0) AS CA_AVRIL,

    NVL(SUM(
                CASE
                    WHEN DATY >= ADD_MONTHS(TRUNC(SYSDATE, 'YYYY'), 4)
                        AND DATY < ADD_MONTHS(TRUNC(SYSDATE, 'YYYY'), 5)
                        THEN CA ELSE 0
                    END
        ), 0) AS CA_MAI,

    NVL(SUM(
                CASE
                    WHEN DATY >= ADD_MONTHS(TRUNC(SYSDATE, 'YYYY'), 5)
                        AND DATY < ADD_MONTHS(TRUNC(SYSDATE, 'YYYY'), 6)
                        THEN CA ELSE 0
                    END
        ), 0) AS CA_JUIN,

    NVL(SUM(
                CASE
                    WHEN DATY >= ADD_MONTHS(TRUNC(SYSDATE, 'YYYY'), 6)
                        AND DATY < ADD_MONTHS(TRUNC(SYSDATE, 'YYYY'), 7)
                        THEN CA ELSE 0
                    END
        ), 0) AS CA_JUILLET,

    NVL(SUM(
                CASE
                    WHEN DATY >= ADD_MONTHS(TRUNC(SYSDATE, 'YYYY'), 7)
                        AND DATY < ADD_MONTHS(TRUNC(SYSDATE, 'YYYY'), 8)
                        THEN CA ELSE 0
                    END
        ), 0) AS CA_AOUT,

    NVL(SUM(
                CASE
                    WHEN DATY >= ADD_MONTHS(TRUNC(SYSDATE, 'YYYY'), 8)
                        AND DATY < ADD_MONTHS(TRUNC(SYSDATE, 'YYYY'), 9)
                        THEN CA ELSE 0
                    END
        ), 0) AS CA_SEPTEMBRE,

    NVL(SUM(
                CASE
                    WHEN DATY >= ADD_MONTHS(TRUNC(SYSDATE, 'YYYY'), 9)
                        AND DATY < ADD_MONTHS(TRUNC(SYSDATE, 'YYYY'), 10)
                        THEN CA ELSE 0
                    END
        ), 0) AS CA_OCTOBRE,

    NVL(SUM(
                CASE
                    WHEN DATY >= ADD_MONTHS(TRUNC(SYSDATE, 'YYYY'), 10)
                        AND DATY < ADD_MONTHS(TRUNC(SYSDATE, 'YYYY'), 11)
                        THEN CA ELSE 0
                    END
        ), 0) AS CA_NOVEMBRE,

    NVL(SUM(
                CASE
                    WHEN DATY >= ADD_MONTHS(TRUNC(SYSDATE, 'YYYY'), 11)
                        AND DATY < ADD_MONTHS(TRUNC(SYSDATE, 'YYYY'), 12)
                        THEN CA ELSE 0
                    END
        ), 0) AS CA_DECEMBRE

FROM CA_PAR_JOUR;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_TRIAGEOEUFDETAIL_AGG" ("IDMERE", "QTE_TOTAL") AS
SELECT
    IDMERE,
    SUM(NVL(QTE, 0)) AS QTE_TOTAL
FROM TRIAGEOEUFDETAIL
GROUP BY IDMERE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_TYPE_PRODUIT" ("ID", "VAL", "DESCE") AS
select tp.id , tp.val , tp.desce from TYPE_PRODUIT tp where ACTIF > 0;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_UTILISATEURLIB" ("REFUSER", "LOGINUSER", "PWDUSER", "NOMUSER", "ADRUSER", "TELUSER", "IDROLE", "DESCROLE", "IDPERSONNEL") AS
select u."REFUSER",u."LOGINUSER",u."PWDUSER",u."NOMUSER",u."ADRUSER",u."TELUSER",u."IDROLE",r.DESCROLE,up.idpersonnel from UTILISATEUR u
                                                                                                                               left join ROLES r on r.IDROLE=u.IDROLE
                                                                                                                               LEFT JOIN utilisateur_personnel up ON up.idutilisateur=u.refuser;
